    private void InitializeDocumentTabs()
    {
        _documentTabs.ItemsSource = _documentTabItems;
        _mainDocumentTab = CreateDocumentTab(isMain: true, EditorEntityKind.Units, isModified: false, entityName: null);
        _openDocumentTabs.Add(_mainDocumentTab);
        _documentTabItems.Add(_mainDocumentTab.TabItem);
        _activeDocumentTab = _mainDocumentTab;
        _documentTabs.SelectedItem = _mainDocumentTab.TabItem;
        RefreshDocumentTabHeaders();
    }

    private EditorDocumentTabState CreateDocumentTab(
        bool isMain,
        EditorEntityKind entityKind,
        bool isModified,
        string? entityName)
    {
        var title = new TextBlock
        {
            VerticalAlignment = VerticalAlignment.Center,
            TextTrimming = TextTrimming.CharacterEllipsis,
            FontSize = 13,
            MaxWidth = 170
        };
        var header = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 5,
            VerticalAlignment = VerticalAlignment.Center
        };
        header.Children.Add(title);

        var item = new TabStripItem { Classes = { "documentTab" }, Content = header };
        var state = new EditorDocumentTabState
        {
            IsMain = isMain,
            EntityKind = entityKind,
            IsModified = isModified,
            EntityName = entityName,
            TabItem = item,
            TitleText = title
        };

        if (!isMain)
        {
            var closeButton = new Button
            {
                Content = "×",
                Padding = new Thickness(4, 0),
                MinWidth = 20,
                MinHeight = 20,
                Background = Brushes.Transparent
            };
            ToolTip.SetTip(closeButton, "Close tab");
            closeButton.Click += async (_, eventArgs) =>
            {
                eventArgs.Handled = true;
                await CloseDocumentTabAsync(state);
            };
            header.Children.Add(closeButton);
        }

        return state;
    }

    private void RefreshDocumentTabHeaders()
    {
        foreach (var tab in _openDocumentTabs)
        {
            var kind = tab.EntityKind == EditorEntityKind.Units ? "Unit" : "Tech";
            var source = tab.IsModified ? "Custom" : "Original";
            var target = string.IsNullOrWhiteSpace(tab.EntityName)
                ? tab.IsMain ? "Main" : kind
                : $"{kind}: {tab.EntityName} ({source})";
            var isDirty = IsDocumentTabDirty(tab);
            tab.TitleText.Text = isDirty ? target + " *" : target;
            var tooltip = string.IsNullOrWhiteSpace(tab.EntityName)
                ? "Main editor tab"
                : target + (tab.IsMain ? "\nMain editor tab" : "");
            if (isDirty)
                tooltip += "\nPending save — close this tab to cancel its changes.";
            ToolTip.SetTip(tab.TabItem, tooltip);
        }
    }

    private bool IsDocumentTabDirty(EditorDocumentTabState tab)
    {
        if (!tab.IsModified || string.IsNullOrWhiteSpace(tab.EntityName))
            return false;

        return tab.EntityKind == EditorEntityKind.Units
            ? _dirtyUnitNames.Contains(tab.EntityName)
            : _technologyView?.IsTechnologyDirty(tab.EntityName) == true;
    }

    private static HashSet<string> CollectUnitOwnedStringIds(string unitName, XElement? unit)
    {
        var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var tag in StringBackedFieldTags)
        {
            var existingId = unit == null ? null : ProtoXmlHandler.GetSimpleField(unit, tag);
            if (!string.IsNullOrWhiteSpace(existingId))
                ids.Add(existingId);
            ids.Add(BuildStringIdForUnit(unitName, GetStringSuffixForField(tag)));
        }
        return ids;
    }

    private void DiscardUnitDocumentChanges(EditorDocumentTabState tab)
    {
        if (_modXmlRoot == null || string.IsNullOrWhiteSpace(tab.EntityName))
            return;

        var currentName = tab.EntityName;
        var savedElement = tab.SavedElement == null ? null : new XElement(tab.SavedElement);
        var savedName = savedElement?.Attribute("name")?.Value?.Trim();
        if (string.IsNullOrWhiteSpace(savedName))
            savedName = currentName;

        var currentElement = ProtoXmlHandler.GetUnitElement(_modXmlRoot, currentName);
        var affectedStringIds = CollectUnitOwnedStringIds(currentName, currentElement);
        affectedStringIds.UnionWith(CollectUnitOwnedStringIds(savedName, savedElement));

        if (currentElement != null)
        {
            if (savedElement != null)
                currentElement.ReplaceWith(savedElement);
            else
                currentElement.Remove();
        }
        else if (savedElement != null)
        {
            _modXmlRoot.Add(savedElement);
        }

        _dirtyUnitNames.Remove(currentName);
        _dirtyUnitNames.Remove(savedName);
        _unitAbilityDrafts.Remove(currentName);
        _unitAbilityDrafts.Remove(savedName);
        _duplicatedUnitRechargeFallbacks.Remove(currentName);
        _duplicatedUnitRechargeFallbacks.Remove(savedName);

        foreach (var rename in _pendingUnitRenames.Where(entry =>
                     entry.Key.Equals(savedName, StringComparison.OrdinalIgnoreCase) ||
                     entry.Value.Equals(currentName, StringComparison.OrdinalIgnoreCase)).ToList())
        {
            _pendingUnitRenames.Remove(rename.Key);
        }

        foreach (var id in affectedStringIds)
        {
            if (IsUnitStringIdOwnedByAnotherDirtyDocument(id, currentName, savedName))
                continue;
            _pendingUnitStringUpdates.Remove(id);
            _pendingUnitStringRemovals.Remove(id);
            _pendingUnitRenameRemovedStringIds.Remove(id);
        }

        _isDirty = _dirtyUnitNames.Count > 0;
        InvalidateSuggestionCaches();
    }

    private bool IsUnitStringIdOwnedByAnotherDirtyDocument(
        string stringId,
        string discardedName,
        string restoredName)
    {
        if (_modXmlRoot == null)
            return false;

        foreach (var dirtyName in _dirtyUnitNames)
        {
            if (dirtyName.Equals(discardedName, StringComparison.OrdinalIgnoreCase) ||
                dirtyName.Equals(restoredName, StringComparison.OrdinalIgnoreCase))
                continue;

            var unit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, dirtyName);
            if (CollectUnitOwnedStringIds(dirtyName, unit).Contains(stringId))
                return true;
        }

        return false;
    }

    private void SetMainDocumentTarget(EditorEntityKind entityKind, bool isModified, string? entityName)
    {
        if (_mainDocumentTab == null)
            return;

        _mainDocumentTab.EntityKind = entityKind;
        _mainDocumentTab.IsModified = isModified;
        _mainDocumentTab.EntityName = entityName;
        _mainDocumentTab.SavedElement = !isModified || string.IsNullOrWhiteSpace(entityName)
            ? null
            : entityKind == EditorEntityKind.Units
                ? LoadSavedUnitElement(entityName)
                : _technologyView?.LoadSavedTechnologyElement(entityName);
        SelectDocumentTabWithoutActivation(_mainDocumentTab);
        _activeDocumentTab = _mainDocumentTab;
        if (string.IsNullOrWhiteSpace(entityName))
            ShowEmptyDocumentState(entityKind);
        else
            _emptyDocumentOverlay.IsVisible = false;
        RefreshDocumentTabHeaders();
    }

    private void ShowEmptyDocumentState(EditorEntityKind entityKind)
    {
        _emptyDocumentMessage.Text = entityKind == EditorEntityKind.Technologies
            ? "Click on a technology to start"
            : "Click on a unit to start";
        _emptyDocumentOverlay.IsVisible = true;

        _suppressUnitListSelectionChange = true;
        try
        {
            _unitList.SelectedItem = null;
        }
        finally
        {
            _suppressUnitListSelectionChange = false;
        }

        if (entityKind == EditorEntityKind.Technologies)
        {
            _technologyView?.SelectTechnology(null);
        }
        else
        {
            _currentUnitName = null;
            ClearEditorPanels();
            _xmlPreviewText.Text = "";
        }
    }

    private void HideEmptyDocumentPlaceholder()
    {
        _emptyDocumentOverlay.IsVisible = false;
    }

    private void RenameOpenDocumentTabs(EditorEntityKind entityKind, string oldName, string newName)
    {
        foreach (var tab in _openDocumentTabs.Where(tab =>
                     tab.EntityKind == entityKind &&
                     tab.IsModified &&
                     string.Equals(tab.EntityName, oldName, StringComparison.OrdinalIgnoreCase)))
        {
            tab.EntityName = newName;
        }
        RefreshDocumentTabHeaders();
    }

    private void RemoveDeletedDocumentTabs(EditorEntityKind entityKind, string entityName)
    {
        foreach (var tab in _openDocumentTabs.Where(tab =>
                     !tab.IsMain &&
                     tab.EntityKind == entityKind &&
                     string.Equals(tab.EntityName, entityName, StringComparison.OrdinalIgnoreCase)).ToList())
        {
            _openDocumentTabs.Remove(tab);
            _documentTabItems.Remove(tab.TabItem);
        }

        if (_mainDocumentTab?.EntityKind == entityKind &&
            string.Equals(_mainDocumentTab.EntityName, entityName, StringComparison.OrdinalIgnoreCase))
        {
            _mainDocumentTab.EntityName = null;
        }
        _activeDocumentTab = _mainDocumentTab;
        if (_mainDocumentTab != null)
            SelectDocumentTabWithoutActivation(_mainDocumentTab);
        RefreshDocumentTabHeaders();
    }

    private void SelectDocumentTabWithoutActivation(EditorDocumentTabState tab)
    {
        _suppressDocumentTabSelection = true;
        try
        {
            _documentTabs.SelectedItem = tab.TabItem;
        }
        finally
        {
            _suppressDocumentTabSelection = false;
        }
    }

    private EditorDocumentTabState? FindPinnedDocumentTab(
        EditorEntityKind entityKind,
        bool isModified,
        string entityName)
        => _openDocumentTabs.FirstOrDefault(tab =>
            !tab.IsMain &&
            tab.EntityKind == entityKind &&
            tab.IsModified == isModified &&
            string.Equals(tab.EntityName, entityName, StringComparison.OrdinalIgnoreCase));

    private XElement? LoadSavedUnitElement(string unitName)
    {
        if (string.IsNullOrWhiteSpace(_modFilePath) || !File.Exists(_modFilePath))
            return null;

        var savedName = _pendingUnitRenames.FirstOrDefault(entry =>
            entry.Value.Equals(unitName, StringComparison.OrdinalIgnoreCase)).Key;
        if (string.IsNullOrWhiteSpace(savedName))
            savedName = unitName;

        try
        {
            var (_, root) = ProtoXmlHandler.ParseProtoXml(_modFilePath);
            var unit = ProtoXmlHandler.GetUnitElement(root, savedName);
            return unit == null ? null : new XElement(unit);
        }
        catch
        {
            return null;
        }
    }

    private async Task OpenPinnedDocumentTabAsync(string entityName)
    {
        var isModified = _unitTabs.SelectedIndex == 1;
        var existing = FindPinnedDocumentTab(_activeEntityKind, isModified, entityName);
        if (existing != null)
        {
            _documentTabs.SelectedItem = existing.TabItem;
            return;
        }

        var tab = CreateDocumentTab(false, _activeEntityKind, isModified, entityName);
        if (isModified)
        {
            tab.SavedElement = _activeEntityKind == EditorEntityKind.Units
                ? LoadSavedUnitElement(entityName)
                : _technologyView?.LoadSavedTechnologyElement(entityName);
        }

        if (_mainDocumentTab?.EntityKind == _activeEntityKind &&
            _mainDocumentTab.IsModified == isModified &&
            string.Equals(_mainDocumentTab.EntityName, entityName, StringComparison.OrdinalIgnoreCase))
        {
            _mainDocumentTab.EntityName = null;
        }
        _openDocumentTabs.Add(tab);
        _documentTabItems.Add(tab.TabItem);
        RefreshDocumentTabHeaders();
        _documentTabs.SelectedItem = tab.TabItem;
        await Task.CompletedTask;
    }

    private async Task CloseDocumentTabAsync(EditorDocumentTabState tab)
    {
        if (tab.IsMain)
            return;

        if (ReferenceEquals(_activeDocumentTab, tab) &&
            tab.EntityKind == EditorEntityKind.Technologies &&
            _technologyView != null &&
            !await _technologyView.CommitCurrentTechnologyAsync())
            return;

        if (IsDocumentTabDirty(tab))
        {
            var prompt = new Prompt(
                PromptType.Confirm,
                "Unsaved tab",
                $"'{tab.EntityName}' has unsaved changes. Discard those changes and close this tab?",
                confirmButtonText: "Discard & close");
            await prompt.ShowDialog(this);
            if (!prompt.Confirmed)
                return;

            if (tab.EntityKind == EditorEntityKind.Units)
                DiscardUnitDocumentChanges(tab);
            else if (_technologyView != null && !string.IsNullOrWhiteSpace(tab.EntityName))
                _technologyView.DiscardTechnologyChanges(tab.EntityName, tab.SavedElement);
        }

        var wasActive = ReferenceEquals(_activeDocumentTab, tab);
        _openDocumentTabs.Remove(tab);
        _documentTabItems.Remove(tab.TabItem);
        if (wasActive && _mainDocumentTab != null)
        {
            _documentTabs.SelectedItem = _mainDocumentTab.TabItem;
        }
        RefreshDocumentTabHeaders();
    }

    private async void DocumentTabs_SelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (_documentTabs is null || _suppressDocumentTabSelection)
            return;
        if (_documentTabActivationInProgress)
        {
            if (_activeDocumentTab != null)
                SelectDocumentTabWithoutActivation(_activeDocumentTab);
            return;
        }
        if (_documentTabs.SelectedItem is not TabStripItem selectedItem)
            return;

        var target = _openDocumentTabs.FirstOrDefault(tab => ReferenceEquals(tab.TabItem, selectedItem));
        if (target == null || ReferenceEquals(target, _activeDocumentTab))
            return;

        await ActivateDocumentTabAsync(target);
    }

    private async Task ActivateDocumentTabAsync(EditorDocumentTabState target)
    {
        if (_documentTabActivationInProgress)
            return;

        var previous = _activeDocumentTab;
        _documentTabActivationInProgress = true;
        var tabsWereEnabled = _documentTabs.IsEnabled;
        var saveWasEnabled = _saveButton.IsEnabled;
        _documentTabs.IsEnabled = false;
        _saveButton.IsEnabled = false;
        try
        {
            if (_activeEntityKind == EditorEntityKind.Units && !await CaptureCurrentUnitDraftAsync())
            {
                if (previous != null)
                    SelectDocumentTabWithoutActivation(previous);
                return;
            }
            if (_activeEntityKind == EditorEntityKind.Technologies &&
                _technologyView != null &&
                !await _technologyView.CommitCurrentTechnologyAsync())
            {
                if (previous != null)
                    SelectDocumentTabWithoutActivation(previous);
                return;
            }

            _activeDocumentTab = target;
            if (string.IsNullOrWhiteSpace(target.EntityName))
            {
                ApplyEntityKindUi(target.EntityKind);
                RefreshUnitList();
                ShowEmptyDocumentState(target.EntityKind);
                return;
            }

            _emptyDocumentOverlay.IsVisible = false;
            ApplyEntityKindUi(target.EntityKind);
            _unitTabs.SelectedIndex = target.IsModified ? 1 : 0;
            if (target.EntityKind == EditorEntityKind.Technologies)
                _technologyView?.SetModifiedMode(target.IsModified);
            RefreshUnitList();

            _suppressUnitListSelectionChange = true;
            try
            {
                _unitList.SelectedItem = _filteredUnitNames.FirstOrDefault(item =>
                    string.Equals(item.UnitName, target.EntityName, StringComparison.OrdinalIgnoreCase));
            }
            finally
            {
                _suppressUnitListSelectionChange = false;
            }

            if (target.EntityKind == EditorEntityKind.Technologies)
                _technologyView?.SelectTechnology(target.EntityName);
            else
                BuildEditorPanel(target.EntityName);
        }
        catch (Exception ex)
        {
            if (previous != null)
                SelectDocumentTabWithoutActivation(previous);
            await new Prompt(
                PromptType.Error,
                "Unable to switch tab",
                $"The document could not be activated:\n{ex.Message}").ShowDialog(this);
        }
        finally
        {
            _documentTabActivationInProgress = false;
            _documentTabs.IsEnabled = tabsWereEnabled;
            _saveButton.IsEnabled = saveWasEnabled;
            RefreshDocumentTabHeaders();
        }
    }

    private void RefreshUnitList()
    {
        // TabStrip raises its initial SelectionChanged while InitializeComponent
        // is still assigning named controls. The shared browser is not ready yet.
        if (_unitTabs is null)
            return;

        var names = new List<string>();
        int selectedIndex = _unitTabs.SelectedIndex;

        if (_activeEntityKind == EditorEntityKind.Technologies)
        {
            if (_technologyView == null)
                return;

            names.AddRange(_technologyView.GetTechnologyNames(modified: selectedIndex == 1));
        }
        else if (_barData == null)
        {
            return;
        }
        else if (selectedIndex == 1) // Modified units
        {
            if (_modXmlRoot != null)
            {
                names.AddRange(ProtoXmlHandler.GetUnitNames(_modXmlRoot));
            }
        }
        else // Original
        {
            names.AddRange(_barData.UnitNames);
            if (_modXmlRoot != null)
            {
                var modNames = new HashSet<string>(ProtoXmlHandler.GetUnitNames(_modXmlRoot), StringComparer.OrdinalIgnoreCase);
                names.RemoveAll(n => modNames.Contains(n));
            }
        }

        _allCurrentNames = names.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
        FilterUnitList();
        RestoreEntityBrowserSelection();
    }

    private void FilterUnitList()
    {
        var query = _searchBox.Text?.Trim().ToLower();
        _filteredUnitNames.Clear();

        var names = string.IsNullOrEmpty(query)
            ? _allCurrentNames
            : _allCurrentNames.Where(name => GetDisplayedUnitName(name).Contains(query, StringComparison.OrdinalIgnoreCase)).ToList();

        _filteredUnitNames.AddItems(names.Select(name => new UnitListItem(name, GetDisplayedUnitName(name))));
    }

    private void RestoreEntityBrowserSelection()
    {
        var selectedName = _activeEntityKind == EditorEntityKind.Technologies
            ? _technologyView?.CurrentTechnologyName
            : _currentUnitName;
        if (string.IsNullOrWhiteSpace(selectedName))
            return;

        _suppressUnitListSelectionChange = true;
        try
        {
            _unitList.SelectedItem = _filteredUnitNames.FirstOrDefault(item =>
                string.Equals(item.UnitName, selectedName, StringComparison.OrdinalIgnoreCase));
        }
        finally
        {
            _suppressUnitListSelectionChange = false;
        }
    }

    private string GetDisplayedUnitName(string unitName)
    {
        if (_unitTabs.SelectedIndex == 1 &&
            string.Equals(unitName, _currentUnitName, StringComparison.OrdinalIgnoreCase) &&
            _fieldControls.TryGetValue(ProtoUnitNameFieldKey, out var control) &&
            control is TextBox nameBox &&
            !string.IsNullOrWhiteSpace(nameBox.Text))
        {
            return nameBox.Text.Trim();
        }

        return unitName;
    }

    private void SearchBox_TextChanged(object? sender, TextChangedEventArgs e)
    {
        FilterUnitList();
        RestoreEntityBrowserSelection();
    }

    private async void UnitsEntity_Click(object? sender, RoutedEventArgs e)
    {
        await ShowEntityKindAsync(EditorEntityKind.Units);
    }

    private async void TechsEntity_Click(object? sender, RoutedEventArgs e)
    {
        await ShowEntityKindAsync(EditorEntityKind.Technologies);
    }

    private async Task ShowEntityKindAsync(EditorEntityKind entityKind)
    {
        if (_activeEntityKind == entityKind)
            return;

        if (!await ConfirmMainDocumentReplacementAsync(
                entityKind,
                _unitTabs.SelectedIndex == 1,
                incomingName: null))
            return;

        if (_activeEntityKind == EditorEntityKind.Units && !await CaptureCurrentUnitDraftAsync())
            return;
        if (_activeEntityKind == EditorEntityKind.Technologies &&
            _technologyView != null &&
            !await _technologyView.CommitCurrentTechnologyAsync())
            return;

        ApplyEntityKindUi(entityKind);
        var showTechnologies = entityKind == EditorEntityKind.Technologies;
        SetMainDocumentTarget(entityKind, _unitTabs.SelectedIndex == 1, entityName: null);
        RefreshUnitList();

        if (!showTechnologies)
            _unitList.Focus();
    }

    private void ApplyEntityKindUi(EditorEntityKind entityKind)
    {
        _activeEntityKind = entityKind;
        var showTechnologies = entityKind == EditorEntityKind.Technologies;
        if (showTechnologies)
        {
            EnsureTechnologyView();
            _technologyView!.SetModifiedMode(_unitTabs.SelectedIndex == 1);
        }

        _technologyHost.IsVisible = showTechnologies;
        _entityListHeading.Text = showTechnologies ? "Technologies" : "Units";
        _unitsEntityButton.Classes.Set("active", !showTechnologies);
        _techsEntityButton.Classes.Set("active", showTechnologies);
        _entityDeleteButton.IsEnabled = _unitTabs.SelectedIndex == 1;
    }

    private void ResetEntityBrowserToUnits()
    {
        _activeEntityKind = EditorEntityKind.Units;
        _technologyHost.IsVisible = false;
        _technologyHost.Content = null;
        _technologyView = null;
        _entityListHeading.Text = "Units";
        _unitsEntityButton.Classes.Set("active", true);
        _techsEntityButton.Classes.Set("active", false);
        _entityDeleteButton.IsEnabled = false;
        ResetDocumentTabs();
    }

    private void ResetDocumentTabs()
    {
        if (_mainDocumentTab == null)
            return;

        foreach (var tab in _openDocumentTabs.Where(tab => !tab.IsMain).ToList())
        {
            _openDocumentTabs.Remove(tab);
            _documentTabItems.Remove(tab.TabItem);
        }
        _mainDocumentTab.EntityKind = EditorEntityKind.Units;
        _mainDocumentTab.IsModified = false;
        _mainDocumentTab.EntityName = null;
        _activeDocumentTab = _mainDocumentTab;
        SelectDocumentTabWithoutActivation(_mainDocumentTab);
        RefreshDocumentTabHeaders();
    }

    private void RefreshSavedDocumentSnapshots(EditorEntityKind entityKind)
    {
        foreach (var tab in _openDocumentTabs.Where(tab =>
                     tab.IsModified && tab.EntityKind == entityKind &&
                     !string.IsNullOrWhiteSpace(tab.EntityName)))
        {
            tab.SavedElement = entityKind == EditorEntityKind.Units
                ? LoadSavedUnitElement(tab.EntityName!)
                : _technologyView?.LoadSavedTechnologyElement(tab.EntityName!);
        }
    }

    private void EnsureTechnologyView()
    {
        if (_technologyView != null)
            return;

        LoadCurrentModAssetCatalogs();
        _technologyView = new TechnologyEditorView(
            GetBaseTechtreeDocumentsFromLoadedBar(),
            ResolveBaseGameplayDirectory(),
            GetCurrentModGameplayFilePath("techtree_mods.xml"),
            ResolveDisplayStringAsync,
            SaveTechnologyStringValuesAsync,
            _baseGameIconPaths.Concat(_customIconPaths),
            GetTechnologyPrerequisiteUnitNames(),
            GetTechnologyProtoUnitNames(),
            SupportedCultureLabels,
            GetTechnologyPrerequisiteMajorGodNames(),
            GetTechnologyTechTypeNames(),
            GetTechnologyProtoActionNames(),
            GetAvailableCommandNames(),
            _iconPreviewService);
        _technologyView.BrowserStateChanged += TechnologyView_BrowserStateChanged;
        _technologyView.DirtyStateChanged += TechnologyView_DirtyStateChanged;
        _technologyHost.Content = _technologyView;
    }

    private void TechnologyView_BrowserStateChanged(object? sender, EventArgs e)
    {
        if (_activeEntityKind != EditorEntityKind.Technologies || _technologyView == null)
            return;

        _unitTabs.SelectedIndex = _technologyView.IsModifiedMode ? 1 : 0;
        if (_activeDocumentTab?.EntityKind == EditorEntityKind.Technologies &&
            !string.IsNullOrWhiteSpace(_technologyView.CurrentTechnologyName))
        {
            var previousName = _activeDocumentTab.EntityName;
            var currentName = _technologyView.CurrentTechnologyName!;
            var changedDocument = !string.IsNullOrWhiteSpace(previousName) &&
                                  !string.Equals(previousName, currentName, StringComparison.OrdinalIgnoreCase);
            var wasRenamed = changedDocument &&
                             _technologyView.IsModifiedMode &&
                             !_technologyView.GetTechnologyNames(modified: true)
                                 .Contains(previousName!, StringComparer.OrdinalIgnoreCase);
            if (wasRenamed)
            {
                RenameOpenDocumentTabs(
                    EditorEntityKind.Technologies,
                    previousName!,
                    currentName);
            }
            else if (changedDocument && _activeDocumentTab.IsMain == false)
            {
                // Add/Copy selects the newly created technology. That is navigation,
                // not a rename of the pinned source document.
                SetMainDocumentTarget(
                    EditorEntityKind.Technologies,
                    _technologyView.IsModifiedMode,
                    currentName);
            }
            _activeDocumentTab.IsModified = _technologyView.IsModifiedMode;
            _activeDocumentTab.EntityName = currentName;
        }
        RefreshUnitList();
        RefreshDocumentTabHeaders();
    }

    private void TechnologyView_DirtyStateChanged(object? sender, EventArgs e)
        => RefreshDocumentTabHeaders();

    private async void EntityAdd_Click(object? sender, RoutedEventArgs e)
    {
        if (_activeEntityKind == EditorEntityKind.Units)
        {
            await AddUnitAsync(duplicateSelected: false);
            return;
        }

        if (_technologyView == null)
            return;
        await _technologyView.AddTechnologyAsync();
        _unitTabs.SelectedIndex = _technologyView.IsModifiedMode ? 1 : 0;
        RefreshUnitList();
    }

    private async void EntityDelete_Click(object? sender, RoutedEventArgs e)
    {
        if (_activeEntityKind == EditorEntityKind.Units)
        {
            await DeleteSelectedUnitAsync();
            return;
        }

        await DeleteSelectedTechnologyAsync();
    }

    private async Task DeleteSelectedTechnologyAsync()
    {
        if (_technologyView == null || _unitTabs.SelectedIndex != 1)
            return;
        var deletedTechnologyName = (_unitList.SelectedItem as UnitListItem)?.UnitName;
        await _technologyView.DeleteTechnologyAsync();
        if (!string.IsNullOrWhiteSpace(deletedTechnologyName) &&
            !_technologyView.GetTechnologyNames(modified: true).Contains(deletedTechnologyName, StringComparer.OrdinalIgnoreCase))
        {
            RemoveDeletedDocumentTabs(EditorEntityKind.Technologies, deletedTechnologyName);
        }
        RefreshUnitList();
    }

    private async void UnitList_PointerPressed(object? sender, PointerPressedEventArgs e)
    {
        if (!e.GetCurrentPoint(_unitList).Properties.IsLeftButtonPressed ||
            e.Source is not Visual sourceVisual)
            return;

        var container = sourceVisual.FindAncestorOfType<ListBoxItem>(includeSelf: true);
        var item = container?.Content as UnitListItem ?? container?.DataContext as UnitListItem;
        if (item?.UnitName is not { } entityName)
            return;

        // Selection is owned here so the first-click load and the second-click
        // promotion to a pinned tab are serialized deterministically.
        e.Handled = true;
        var entityKind = _activeEntityKind;
        var isModified = _unitTabs.SelectedIndex == 1;
        var elapsed = e.Timestamp >= _lastEntityPointerPressTimestamp
            ? e.Timestamp - _lastEntityPointerPressTimestamp
            : ulong.MaxValue;
        var isSecondClick =
            elapsed <= EntitySecondClickWindowMilliseconds &&
            _lastEntityPointerPressKind == entityKind &&
            _lastEntityPointerPressIsModified == isModified &&
            string.Equals(_lastEntityPointerPressName, entityName, StringComparison.OrdinalIgnoreCase);

        if (isSecondClick)
        {
            _lastEntityPointerPressName = null;
            _lastEntityPointerPressTimestamp = 0;
            await _unitSelectionChangeTask;
            await OpenPinnedDocumentTabAsync(entityName);
            return;
        }

        _lastEntityPointerPressName = entityName;
        _lastEntityPointerPressKind = entityKind;
        _lastEntityPointerPressIsModified = isModified;
        _lastEntityPointerPressTimestamp = e.Timestamp;

        // Highlight and start resolving Main immediately. If a second click was
        // already generated while a heavy Unit build blocked the UI thread, its
        // raw timestamp still falls inside the window and it will promote this
        // document after this selection task completes.
        _suppressUnitListSelectionChange = true;
        try
        {
            _unitList.SelectedItem = item;
        }
        finally
        {
            _suppressUnitListSelectionChange = false;
        }

        await RunUnitListSelectionChangeAsync();
    }

    private UnitListItem? GetContextEntityItem(ContextRequestedEventArgs e)
    {
        Visual? source = e.Source as Visual;
        if (e.TryGetPosition(_unitList, out var position))
            source = _unitList.InputHitTest(position) as Visual ?? source;

        var container = source?.FindAncestorOfType<ListBoxItem>(includeSelf: true);
        return container?.Content as UnitListItem
               ?? container?.DataContext as UnitListItem
               ?? _unitList.SelectedItem as UnitListItem;
    }

    private async Task<bool> ActivateContextEntityAsync(
        EditorEntityKind entityKind,
        bool isModified,
        string entityName)
    {
        if (_activeEntityKind != entityKind || (_unitTabs.SelectedIndex == 1) != isModified)
            return false;

        var item = _filteredUnitNames.FirstOrDefault(candidate =>
            string.Equals(candidate.UnitName, entityName, StringComparison.OrdinalIgnoreCase));
        if (item == null)
            return false;

        _suppressUnitListSelectionChange = true;
        try
        {
            _unitList.SelectedItem = item;
        }
        finally
        {
            _suppressUnitListSelectionChange = false;
        }

        var pinned = FindPinnedDocumentTab(entityKind, isModified, entityName);
        if (pinned != null && !ReferenceEquals(pinned, _activeDocumentTab))
        {
            SelectDocumentTabWithoutActivation(pinned);
            await ActivateDocumentTabAsync(pinned);
        }
        else if (pinned == null)
        {
            await RunUnitListSelectionChangeAsync();
        }

        return _activeDocumentTab?.EntityKind == entityKind &&
               _activeDocumentTab.IsModified == isModified &&
               string.Equals(_activeDocumentTab.EntityName, entityName, StringComparison.OrdinalIgnoreCase);
    }

    private void UnitList_ContextRequested(object? sender, ContextRequestedEventArgs e)
    {
        if (GetContextEntityItem(e) is not { UnitName: { } entityName })
            return;

        var entityKind = _activeEntityKind;
        var isModified = _unitTabs.SelectedIndex == 1;

        var menu = new ContextMenu();
        var openItem = new MenuItem { Header = "Open in new tab" };
        openItem.Click += async (_, _) => await OpenPinnedDocumentTabAsync(entityName);
        menu.Items.Add(openItem);

        var copyItem = new MenuItem { Header = "Copy" };
        copyItem.Click += async (_, _) =>
        {
            if (!await ActivateContextEntityAsync(entityKind, isModified, entityName))
                return;

            if (entityKind == EditorEntityKind.Units)
                await AddUnitAsync(duplicateSelected: true);
            else if (_technologyView != null)
                await _technologyView.AddTechnologyAsync(duplicateSelected: true);
        };
        menu.Items.Add(copyItem);

        var deleteItem = new MenuItem
        {
            Header = "Delete",
            Foreground = Brushes.OrangeRed,
            IsEnabled = isModified
        };
        deleteItem.Click += async (_, _) =>
        {
            if (!await ActivateContextEntityAsync(entityKind, isModified, entityName))
                return;

            if (entityKind == EditorEntityKind.Units)
            {
                await DeleteSelectedUnitAsync();
            }
            else
            {
                await DeleteSelectedTechnologyAsync();
            }
        };
        menu.Items.Add(deleteItem);

        menu.Open(_unitList);
        e.Handled = true;
    }

    private async void UnitTab_SelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (_unitTabs is null)
            return;

        if (_entitySourceChangeInProgress)
        {
            if (_activeDocumentTab != null)
                _unitTabs.SelectedIndex = _activeDocumentTab.IsModified ? 1 : 0;
            return;
        }

        var selectedModified = _unitTabs.SelectedIndex == 1;
        if (_documentTabActivationInProgress)
        {
            ApplyEntitySourceUi(selectedModified);
            return;
        }

        var tabsWereEnabled = _unitTabs.IsEnabled;
        _entitySourceChangeInProgress = true;
        _unitTabs.IsEnabled = false;
        try
        {
            if (_activeDocumentTab != null && _activeDocumentTab.IsModified != selectedModified)
            {
                var previousTab = _activeDocumentTab;
                if (!await ConfirmMainDocumentReplacementAsync(
                        _activeEntityKind,
                        selectedModified,
                        incomingName: null))
                {
                    _unitTabs.SelectedIndex = previousTab.IsModified ? 1 : 0;
                    return;
                }

                var canLeave = _activeEntityKind == EditorEntityKind.Units
                    ? await CaptureCurrentUnitDraftAsync()
                    : _technologyView == null || await _technologyView.CommitCurrentTechnologyAsync();
                if (!canLeave)
                {
                    _unitTabs.SelectedIndex = previousTab.IsModified ? 1 : 0;
                    return;
                }

                SetMainDocumentTarget(_activeEntityKind, selectedModified, entityName: null);
                ShowEmptyDocumentState(_activeEntityKind);
            }

            ApplyEntitySourceUi(selectedModified);
        }
        catch (Exception ex)
        {
            if (_activeDocumentTab != null)
                _unitTabs.SelectedIndex = _activeDocumentTab.IsModified ? 1 : 0;
            await new Prompt(
                PromptType.Error,
                "Unable to switch source",
                $"The entity source could not be changed:\n{ex.Message}").ShowDialog(this);
        }
        finally
        {
            _unitTabs.IsEnabled = tabsWereEnabled;
            _entitySourceChangeInProgress = false;
        }
    }

    private void ApplyEntitySourceUi(bool selectedModified)
    {
        if (_activeEntityKind == EditorEntityKind.Technologies)
            _technologyView?.SetModifiedMode(selectedModified);
        if (_entityDeleteButton != null)
            _entityDeleteButton.IsEnabled = selectedModified;
        RefreshUnitList();
    }

    private async void UnitList_SelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (_suppressUnitListSelectionChange || _unitSelectionChangeInProgress)
            return;

        await RunUnitListSelectionChangeAsync();
    }

    private async Task RunUnitListSelectionChangeAsync()
    {
        if (_unitSelectionChangeInProgress)
            return;

        var selectionTask = HandleUnitListSelectionChangedAsync();
        _unitSelectionChangeTask = selectionTask;
        try
        {
            await selectionTask;
        }
        finally
        {
            if (ReferenceEquals(_unitSelectionChangeTask, selectionTask))
                _unitSelectionChangeTask = Task.CompletedTask;
        }
    }

    private async Task HandleUnitListSelectionChangedAsync()
    {
        if (_unitList.SelectedItem is UnitListItem { UnitName: { } selectedName })
        {
            if (!await ConfirmMainDocumentReplacementAsync(
                    _activeEntityKind,
                    _unitTabs.SelectedIndex == 1,
                    selectedName))
            {
                RestoreEntityBrowserSelection();
                return;
            }

            var pinned = FindPinnedDocumentTab(_activeEntityKind, _unitTabs.SelectedIndex == 1, selectedName);
            if (pinned != null)
            {
                if (!ReferenceEquals(pinned, _activeDocumentTab))
                    _documentTabs.SelectedItem = pinned.TabItem;
                return;
            }

            if (_activeEntityKind == EditorEntityKind.Technologies)
            {
                if (_technologyView != null && !await _technologyView.CommitCurrentTechnologyAsync())
                {
                    RestoreEntityBrowserSelection();
                    return;
                }
                SetMainDocumentTarget(EditorEntityKind.Technologies, _unitTabs.SelectedIndex == 1, selectedName);
                _technologyView?.SelectTechnology(selectedName);
                return;
            }

            if (selectedName.Equals(_currentUnitName, StringComparison.OrdinalIgnoreCase))
            {
                SetMainDocumentTarget(EditorEntityKind.Units, _unitTabs.SelectedIndex == 1, selectedName);
                return;
            }

            var previousName = _currentUnitName;
            _unitSelectionChangeInProgress = true;
            if (!await CaptureCurrentUnitDraftAsync())
            {
                _suppressUnitListSelectionChange = true;
                try
                {
                    _unitList.SelectedItem = _filteredUnitNames.FirstOrDefault(item =>
                        string.Equals(item.UnitName, previousName, StringComparison.OrdinalIgnoreCase));
                }
                finally
                {
                    _suppressUnitListSelectionChange = false;
                    _unitSelectionChangeInProgress = false;
                }
                return;
            }

            try
            {
                SetMainDocumentTarget(EditorEntityKind.Units, _unitTabs.SelectedIndex == 1, selectedName);
                // Keep the existing item container and scroll offset stable. The
                // browser is refreshed by add/delete/rename/filter operations;
                // selecting an unchanged name does not require rebuilding it.
                BuildEditorPanel(selectedName);
            }
            finally
            {
                _unitSelectionChangeInProgress = false;
            }
        }
    }

    private async Task<bool> ConfirmMainDocumentReplacementAsync(
        EditorEntityKind incomingKind,
        bool incomingModified,
        string? incomingName)
    {
        var main = _activeDocumentTab;
        if (main?.IsMain != true || string.IsNullOrWhiteSpace(main.EntityName))
            return true;
        if (main.EntityKind == incomingKind &&
            main.IsModified == incomingModified &&
            !string.IsNullOrWhiteSpace(incomingName) &&
            string.Equals(main.EntityName, incomingName, StringComparison.OrdinalIgnoreCase))
            return true;

        var captured = main.EntityKind == EditorEntityKind.Units
            ? await CaptureCurrentUnitDraftAsync()
            : _technologyView == null || await _technologyView.CommitCurrentTechnologyAsync();
        if (!captured)
            return false;
        if (!IsDocumentTabDirty(main))
            return true;

        var destination = string.IsNullOrWhiteSpace(incomingName)
            ? incomingKind == EditorEntityKind.Units ? "the Units browser" : "the Technologies browser"
            : $"'{incomingName}'";
        var prompt = new Prompt(
            PromptType.Confirm,
            "Unsaved main document",
            $"'{main.EntityName}' has unsaved changes. Discard those changes and open {destination}?",
            confirmButtonText: "Discard changes");
        await prompt.ShowDialog(this);
        if (!prompt.Confirmed)
            return false;

        if (main.EntityKind == EditorEntityKind.Units)
        {
            DiscardUnitDocumentChanges(main);
            _currentUnitName = null;
            ClearEditorPanels();
        }
        else if (_technologyView != null)
        {
            _technologyView.DiscardTechnologyChanges(main.EntityName, main.SavedElement);
        }

        RefreshDocumentTabHeaders();
        return true;
    }

    private async void UnitNameBox_TextChanged(object? sender, TextChangedEventArgs e)
    {
        if (_isPopulating || _suppressUnitNameChange)
            return;

        if (InternalNamePolicy.IsValidOrUnchangedLegacy(_unitNameBox.Text, _currentUnitName))
            ClearStatsValidationError(_unitNameBox);

        // Keep the modified-unit list and its search results in sync with the
        // pending name, while retaining the original key until Save applies it.
        FilterUnitList();
        var proceed = await CheckStartLocalMod();
        if (proceed)
            MarkDirty();
    }

    private void InitializePageSearch()
    {
        AddHandler(InputElement.KeyDownEvent, OnWindowKeyDown, RoutingStrategies.Tunnel);

        _pageSearchBox.TextChanged += (_, _) => RefreshPageSearchMatches(scrollToCurrentMatch: true);
        _pageSearchBox.KeyDown += PageSearchBox_KeyDown;

        _pageSearchMatchCaseToggle.IsCheckedChanged += OnPageSearchOptionChanged;
        _pageSearchWholeWordToggle.IsCheckedChanged += OnPageSearchOptionChanged;
        _pageSearchRegexToggle.IsCheckedChanged += OnPageSearchOptionChanged;

        _pageSearchPreviousButton.Click += (_, _) => MoveToPreviousPageSearchMatch();
        _pageSearchNextButton.Click += (_, _) => MoveToNextPageSearchMatch();
        _pageSearchCloseButton.Click += (_, _) => ClosePageSearch();

        UpdatePageSearchUiState(hasMatches: false, hasQuery: false, hasValidPattern: true);
        RebuildSectionJumpFlyout();
    }

    private void InitializeXmlPreview()
    {
        XmlSyntaxEditorService.Configure(_xmlPreviewText);
        _xmlPreviewRefreshTimer.Tick += (_, _) =>
        {
            _xmlPreviewRefreshTimer.Stop();
            UpdateXmlPreview();
        };
    }

    private void XmlPreviewToggle_Click(object? sender, RoutedEventArgs e)
    {
        _isXmlPreviewCollapsed = !_isXmlPreviewCollapsed;

        _xmlPreviewContent.IsVisible = !_isXmlPreviewCollapsed;
        _previewSplitter.IsVisible = !_isXmlPreviewCollapsed;
        _mainContentGrid.ColumnDefinitions[3].Width = new GridLength(_isXmlPreviewCollapsed ? 0 : 5);
        _mainContentGrid.ColumnDefinitions[4].Width = new GridLength(
            _isXmlPreviewCollapsed ? CollapsedXmlPreviewWidth : _expandedXmlPreviewWidth.Value,
            _isXmlPreviewCollapsed ? GridUnitType.Pixel : _expandedXmlPreviewWidth.GridUnitType);

        _xmlPreviewToggleButton.Content = _isXmlPreviewCollapsed ? "\u25C0" : "\u25B6";
        ToolTip.SetTip(
            _xmlPreviewToggleButton,
            _isXmlPreviewCollapsed ? "Restore XML Preview" : "Collapse XML Preview");
    }

    private void InitializeEditorTabs()
    {
        _editorTabSettleTimer.Tick += (_, _) =>
        {
            _editorTabSettleTimer.Stop();
            _suppressEditorChangeTracking = false;
        };
        _editorTabsInitialized = true;
    }

    private void EditorTab_SelectionChanged(object? sender, SelectionChangedEventArgs e)
    {
        if (!_editorTabsInitialized || _isPopulating)
            return;

        // A tab's controls can raise delayed initialization events the first
        // time Avalonia realizes it. They are not user edits and must not cause
        // the raw XML preview to be projected/reformatted.
        _suppressEditorChangeTracking = true;
        _editorTabSettleTimer.Stop();
        _editorTabSettleTimer.Start();
    }

    private void ScheduleXmlPreviewRefresh()
    {
        if (_isPopulating || _isXmlPreviewDirty)
            return;

        _xmlPreviewRefreshTimer.Stop();
        _xmlPreviewRefreshTimer.Start();
    }

    private void UpdateXmlPreview(bool force = false)
    {
        if (_isAbilityDefinitionEditorMode)
        {
            try
            {
                if (!_loadingAbilityEditor)
                    _captureAbilityEditorCurrent?.Invoke();
                var draft = _abilityDrafts.GetValueOrDefault(_currentAbilityEditorName);
                var preview = draft == null ? null : BuildAbilityPowerElement(draft);
                _xmlPreviewText.IsEnabled = preview != null;
                XmlSyntaxEditorService.SetReadOnly(_xmlPreviewText, isReadOnly: true);
                _xmlPreviewText.Focusable = true;
                _xmlPreviewText.IsTabStop = false;
                _xmlPreviewText.Opacity = 1;
                _xmlPreviewText.Background = Brush.Parse("#090C0B");
                _xmlPreviewText.Foreground = Brush.Parse("#E8DECC");
                _applyXmlPreviewButton.IsVisible = false;
                SetXmlPreviewText(preview == null ? "" : FormatXmlForPreview(preview));
            }
            catch { }
            return;
        }

        if (_protoActionHostAdapter.Context.UsesStandaloneDocumentLifecycle)
        {
            try
            {
                var previewDocument = BuildTacticsActionEditorDocument(validateSerializedActions: false);
                var previewRoot = previewDocument.Root;
                _xmlPreviewText.IsEnabled = previewRoot != null;
                XmlSyntaxEditorService.SetReadOnly(_xmlPreviewText, isReadOnly: true);
                _xmlPreviewText.Focusable = true;
                _xmlPreviewText.IsTabStop = false;
                _xmlPreviewText.Opacity = 1;
                _xmlPreviewText.Background = Brush.Parse("#090C0B");
                _xmlPreviewText.Foreground = Brush.Parse("#E8DECC");
                _applyXmlPreviewButton.IsVisible = false;
                SetXmlPreviewText(previewRoot == null ? "" : FormatXmlForPreview(previewRoot));
            }
            catch
            {
                // Keep the last valid preview while the user is in the middle of
                // entering an incomplete action value.
            }
            return;
        }

        var modUnit = _modXmlRoot != null && !string.IsNullOrWhiteSpace(_currentUnitName)
            ? ProtoXmlHandler.GetUnitElement(_modXmlRoot, _currentUnitName)
            : null;
        var sourceUnit = modUnit ?? (!string.IsNullOrWhiteSpace(_currentUnitName) && _barXmlRoot != null
            ? ProtoXmlHandler.GetUnitElement(_barXmlRoot, _currentUnitName)
            : null);
        var canEditRawXml = modUnit != null && !_isReadOnly;
        // Base-game XML remains read-only, but stays enabled so it can be focused
        // and scrolled like any other text viewer.
        _xmlPreviewText.IsEnabled = sourceUnit != null;
        XmlSyntaxEditorService.SetReadOnly(_xmlPreviewText, isReadOnly: !canEditRawXml);
        _xmlPreviewText.Focusable = sourceUnit != null;
        _xmlPreviewText.IsTabStop = canEditRawXml;
        _xmlPreviewText.Opacity = sourceUnit != null ? 1 : 0.55;
        _xmlPreviewText.Background = Brush.Parse(canEditRawXml ? "#090C0B" : "#090C0B");
        _xmlPreviewText.Foreground = Brush.Parse(sourceUnit != null ? "#E8DECC" : "#8a8a8a");
        _applyXmlPreviewButton.IsVisible = canEditRawXml;

        if (!force && canEditRawXml && _isXmlPreviewDirty)
            return;

        if (sourceUnit == null)
        {
            SetXmlPreviewText("");
            return;
        }

        var previewUnit = new XElement(sourceUnit);
        if (!_showStoredRawXml && !_isReadOnly && _modXmlRoot != null)
            ApplyCurrentEdits(previewUnit);

        RefreshTacticsOnlyActionTabMarkers(previewUnit);
        SetXmlPreviewText(FormatXmlForPreview(previewUnit));
    }

    private bool IsTacticsBackedProtoAction(ProtoAction action)
    {
        var actionName = action.Name?.Trim() ?? "";
        if (string.IsNullOrWhiteSpace(actionName) || !string.IsNullOrWhiteSpace(action.Type))
            return false;

        return _currentUnitTacticsActionTypeMap.TryGetValue(actionName, out var tacticsType) &&
               !string.IsNullOrWhiteSpace(tacticsType);
    }

    private static Control CreateProtoActionSelectorContent(ProtoActionWidgetState state, string actionName)
    {
        actionName = string.IsNullOrWhiteSpace(actionName) ? "Unnamed action" : actionName.Trim();

        if (!state.IsCurrentTacticsAction)
            return new TextBlock { Text = actionName, VerticalAlignment = VerticalAlignment.Center };

        var row = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 6,
            VerticalAlignment = VerticalAlignment.Center
        };
        row.Children.Add(new TextBlock { Text = actionName, VerticalAlignment = VerticalAlignment.Center });

        var source = state.HasTacticsOnlyOverrides
            ? ProtoActionValueSource.ProtoOverride
            : ProtoActionValueSource.TacticsInherited;
        var dot = CreateProtoActionSourceMarker(source);
        if (dot != null)
        {
            dot.Margin = new Thickness(0);
            dot.VerticalAlignment = VerticalAlignment.Center;
            dot.HorizontalAlignment = HorizontalAlignment.Center;
            ToolTip.SetTip(dot, state.HasTacticsOnlyOverrides
                ? "This tactics action has protoaction overrides"
                : "Action inherited from tactics");
            row.Children.Add(dot);
        }

        return row;
    }

    private void RefreshTacticsOnlyActionTabMarkers(XElement previewUnit)
    {
        foreach (var state in _protoActionWidgets)
        {
            var actionName = state.NameAcb.Text?.Trim() ?? "";
            state.IsCurrentTacticsAction = TryGetCurrentUnitTacticsAction(actionName, out var tacticsAction);

            var previewAction = state.IsCurrentTacticsAction
                ? ProtoXmlHandler.GetProtoActions(previewUnit)
                    .FirstOrDefault(action => string.Equals(
                        action.Name?.Trim() ?? "",
                        actionName,
                        StringComparison.OrdinalIgnoreCase))
                : null;
            var hasOverride = previewAction != null &&
                              tacticsAction != null &&
                              HasActualTacticsOverride(previewAction, tacticsAction);

            state.HasTacticsOnlyOverrides = hasOverride;
            if (state.ActionSelectorButton != null)
                state.ActionSelectorButton.Content = CreateProtoActionSelectorContent(state, actionName);
        }
    }

    private static bool HasSerializableProtoActionOverride(ProtoAction action)
    {
        // Name and type identify the tactics action; neither is an editable override.
        // Ignore them even if a source/parser path leaves them in AdditionalElements.
        var hasAdditionalOverride = action.AdditionalElements.Any(element =>
            !element.Name.LocalName.Equals("name", StringComparison.OrdinalIgnoreCase) &&
            !element.Name.LocalName.Equals("type", StringComparison.OrdinalIgnoreCase));

        return !string.IsNullOrWhiteSpace(action.Rof) ||
               !string.IsNullOrWhiteSpace(action.MaxRange) ||
               action.Damages.Count > 0 ||
               action.DamageBonuses.Count > 0 ||
               hasAdditionalOverride;
    }

    internal static bool HasActualTacticsOverride(ProtoAction protoAction, ProtoAction tacticsAction)
    {
        if (!string.IsNullOrWhiteSpace(protoAction.Rof) &&
            !string.IsNullOrWhiteSpace(tacticsAction.Rof) &&
            !ProtoActionSourceValuesEqual(protoAction.Rof, tacticsAction.Rof))
        {
            return true;
        }

        if (!string.IsNullOrWhiteSpace(protoAction.MaxRange) &&
            !string.IsNullOrWhiteSpace(tacticsAction.MaxRange) &&
            !ProtoActionSourceValuesEqual(protoAction.MaxRange, tacticsAction.MaxRange))
        {
            return true;
        }

        foreach (var protoDamage in protoAction.Damages)
        {
            if (tacticsAction.Damages.Any(entry =>
                    entry.DamageType.Equals(protoDamage.DamageType, StringComparison.OrdinalIgnoreCase) &&
                    !ProtoActionSourceValuesEqual(protoDamage.Amount, entry.Amount)))
                return true;
        }

        foreach (var protoBonus in protoAction.DamageBonuses)
        {
            if (tacticsAction.DamageBonuses.Any(entry =>
                    entry.UnitType.Equals(protoBonus.UnitType, StringComparison.OrdinalIgnoreCase) &&
                    !ProtoActionSourceValuesEqual(protoBonus.Multiplier, entry.Multiplier)))
                return true;
        }

        var protoAdditional = protoAction.AdditionalElements
            .Where(IsProtoActionOverridePayloadElement)
            .ToList();
        var tacticsAdditional = tacticsAction.AdditionalElements
            .Where(IsProtoActionOverridePayloadElement)
            .ToList();
        foreach (var protoElement in protoAdditional)
        {
            var sameTagInherited = tacticsAdditional
                .Where(element => element.Name.LocalName.Equals(
                    protoElement.Name.LocalName,
                    StringComparison.OrdinalIgnoreCase))
                .ToList();
            if (sameTagInherited.Count == 0)
                continue; // A ProtoUnit-only tag is an addition, not an override.

            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(protoElement.Name.LocalName);
            var keyAttributes = GetProtoActionOverrideKeyAttributes(protoElement, definition);
            if (keyAttributes.Count > 0)
            {
                var inheritedMatch = sameTagInherited.FirstOrDefault(element =>
                    ProtoActionAttributesMatch(protoElement, element, keyAttributes));
                if (inheritedMatch != null &&
                    !ProtoActionOverrideElementsEqual(protoElement, inheritedMatch))
                    return true;

                continue; // A new key is another addition.
            }

            if (definition.EditorKind == ProtoActionFieldEditorKind.StructuredList && definition.IsRepeatable)
            {
                // Unkeyed repeated values are additive. An exact duplicate is redundant,
                // while a different value is a new collection entry rather than an override.
                continue;
            }

            if (!sameTagInherited.Any(element => ProtoActionOverrideElementsEqual(protoElement, element)))
                return true;
        }

        return false;
    }

    private static bool IsProtoActionOverridePayloadElement(XElement element)
        => !element.Name.LocalName.Equals("name", StringComparison.OrdinalIgnoreCase) &&
           !element.Name.LocalName.Equals("type", StringComparison.OrdinalIgnoreCase);

    private static bool ProtoActionOverrideElementsEqual(XElement left, XElement right)
    {
        if (!left.Name.LocalName.Equals(right.Name.LocalName, StringComparison.OrdinalIgnoreCase))
            return false;

        var leftAttributes = left.Attributes()
            .ToDictionary(attribute => attribute.Name.LocalName, attribute => attribute.Value?.Trim() ?? "", StringComparer.OrdinalIgnoreCase);
        var rightAttributes = right.Attributes()
            .ToDictionary(attribute => attribute.Name.LocalName, attribute => attribute.Value?.Trim() ?? "", StringComparer.OrdinalIgnoreCase);
        if (leftAttributes.Count != rightAttributes.Count)
            return false;

        foreach (var attribute in leftAttributes)
        {
            if (!rightAttributes.TryGetValue(attribute.Key, out var rightValue) ||
                !ProtoActionSourceValuesEqual(attribute.Value, rightValue))
            {
                return false;
            }
        }

        var leftChildren = left.Elements().ToList();
        var rightChildren = right.Elements().ToList();
        if (leftChildren.Count != rightChildren.Count)
            return false;

        if (leftChildren.Count == 0)
            return ProtoActionSourceValuesEqual(left.Value, right.Value);

        for (int i = 0; i < leftChildren.Count; i++)
        {
            if (!ProtoActionOverrideElementsEqual(leftChildren[i], rightChildren[i]))
                return false;
        }

        return true;
    }

    private static string FormatXmlForPreview(XElement unit)
    {
        // BAR XML and local XML can carry different insignificant whitespace.
        // Reparse the compact form for a consistent, readable preview layout.
        return XElement.Parse(unit.ToString(SaveOptions.DisableFormatting)).ToString();
    }

    private void SetXmlPreviewText(string text)
    {
        _lastRenderedXmlPreview = text;
        _isUpdatingXmlPreviewText = true;
        _xmlPreviewText.Text = text;
        _isUpdatingXmlPreviewText = false;
        _isXmlPreviewDirty = false;
    }

    private void XmlPreviewText_TextChanged(object? sender, EventArgs e)
    {
        // Avalonia can dispatch a programmatic Text assignment after the setter
        // returns. Compare against the rendered value as well as the guard so a
        // normal preview refresh is never mistaken for un-applied raw input.
        if (!_isUpdatingXmlPreviewText &&
            !_xmlPreviewText.IsReadOnly &&
            !string.Equals(_xmlPreviewText.Text, _lastRenderedXmlPreview, StringComparison.Ordinal))
            _isXmlPreviewDirty = true;
    }

    private async void ApplyXmlPreview_Click(object? sender, RoutedEventArgs e)
    {
        if (_isReadOnly || _modXmlRoot == null || string.IsNullOrWhiteSpace(_currentUnitName))
            return;

        XElement parsedUnit;
        try
        {
            parsedUnit = XElement.Parse(_xmlPreviewText.Text ?? "", LoadOptions.PreserveWhitespace);
        }
        catch (Exception ex)
        {
            await new Prompt(PromptType.Error, "Invalid XML", $"The XML could not be applied:\n{ex.Message}").ShowDialog(this);
            return;
        }

        if (!parsedUnit.Name.LocalName.Equals("unit", StringComparison.OrdinalIgnoreCase))
        {
            await new Prompt(PromptType.Error, "Invalid Unit XML", "Raw XML must have a <unit> root element so it can be saved in proto_mods.xml.").ShowDialog(this);
            return;
        }

        var newUnitName = parsedUnit.Attribute("name")?.Value?.Trim();
        if (string.IsNullOrWhiteSpace(newUnitName))
        {
            await new Prompt(PromptType.Error, "Invalid Unit XML", "The <unit> element must have a name attribute.").ShowDialog(this);
            return;
        }

        var oldUnitName = _currentUnitName;
        if (!InternalNamePolicy.IsValidOrUnchangedLegacy(newUnitName, oldUnitName))
        {
            await new Prompt(PromptType.Error, "Invalid Unit name",
                "New or renamed ProtoUnit names can contain only letters, digits, '_' and '-'.").ShowDialog(this);
            return;
        }
        if (!newUnitName.Equals(oldUnitName, StringComparison.OrdinalIgnoreCase) && UnitNameExistsAnywhere(newUnitName))
        {
            await new Prompt(PromptType.Error, "Duplicate Unit", $"Unit '{newUnitName}' already exists in the base game or this mod.").ShowDialog(this);
            return;
        }

        var currentUnit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, oldUnitName);
        if (currentUnit == null)
        {
            await new Prompt(PromptType.Error, "Missing Unit", $"Could not find mod unit '{oldUnitName}'.").ShowDialog(this);
            return;
        }

        currentUnit.ReplaceWith(parsedUnit);
        TrackPendingUnitRename(oldUnitName, newUnitName);
        _currentUnitName = newUnitName;
        RenameOpenDocumentTabs(EditorEntityKind.Units, oldUnitName, newUnitName);
        _isXmlPreviewDirty = false;
        MarkDirty();
        InvalidateSuggestionCaches();
        RefreshUnitList();
        _unitList.SelectedItem = _filteredUnitNames.FirstOrDefault(item =>
            string.Equals(item.UnitName, newUnitName, StringComparison.OrdinalIgnoreCase));
        BuildEditorPanel(newUnitName, resetScroll: false);
        _statusMessage.Text = "Raw XML applied.";
    }

    private void OnWindowKeyDown(object? sender, KeyEventArgs e)
    {
        if (e.Key == Key.S && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            if (_protoActionHostAdapter.Context.UsesStandaloneDocumentLifecycle)
                _ = SaveTacticsActionEditorAsync();
            else if (_isAbilityDefinitionEditorMode)
                _ = SaveAbilityDefinitionEditorAsync();
            else
                Save_Click(this, e);
            e.Handled = true;
            return;
        }

        if (e.Key == Key.F && e.KeyModifiers.HasFlag(KeyModifiers.Control))
        {
            if (!string.IsNullOrWhiteSpace(_currentUnitName))
            {
                OpenPageSearch();
                e.Handled = true;
            }
            return;
        }

        if (!_pageSearchPanel.IsVisible)
            return;

        if (e.Key == Key.Escape)
        {
            ClosePageSearch();
            e.Handled = true;
            return;
        }

        if (e.Key == Key.F3)
        {
            if (e.KeyModifiers.HasFlag(KeyModifiers.Shift))
                MoveToPreviousPageSearchMatch();
            else
                MoveToNextPageSearchMatch();

            e.Handled = true;
        }
    }

    private void PageSearchBox_KeyDown(object? sender, KeyEventArgs e)
    {
        if (e.Key == Key.Enter)
        {
            if (e.KeyModifiers.HasFlag(KeyModifiers.Shift))
                MoveToPreviousPageSearchMatch();
            else
                MoveToNextPageSearchMatch();

            e.Handled = true;
            return;
        }

        if (e.Key == Key.Escape)
        {
            ClosePageSearch();
            e.Handled = true;
        }
    }

    private void OnPageSearchOptionChanged(object? sender, RoutedEventArgs e)
    {
        RefreshPageSearchMatches(scrollToCurrentMatch: true);
    }

    private void AddSectionHeader(string title)
    {
        var lbl = new TextBlock
        {
            Text = $"\u2500\u2500\u2500\u2500 {title} \u2500\u2500\u2500\u2500",
            Classes = { "SectionHeader" },
            FontWeight = FontWeight.Bold,
            FontSize = 14,
            Foreground = Brush.Parse("#C59A52"),
            Margin = new Thickness(0, 15, 0, 5)
        };
        _activeEditorPanel?.Children.Add(lbl);
        _sectionJumpTargets.Add(new SectionJumpTarget
        {
            Title = title,
            Header = lbl,
            TabIndex = _activeEditorTabIndex
        });
    }

    private void RebuildSectionJumpFlyout()
    {
        _sectionsFlyoutPanel.Children.Clear();

        foreach (var target in _sectionJumpTargets)
        {
            var button = new Button
            {
                Content = target.Title,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                HorizontalContentAlignment = HorizontalAlignment.Left,
                Padding = new Thickness(10, 6),
                MinWidth = 180
            };

            button.Click += (_, _) =>
            {
                _sectionsButton.Flyout?.Hide();
                _editorTabs.SelectedIndex = target.TabIndex;
                Dispatcher.UIThread.Post(() => ScrollEditorControlToTop(target.Header, target.TabIndex), DispatcherPriority.Loaded);
            };

            _sectionsFlyoutPanel.Children.Add(button);
        }

        var hasSections = _protoActionHostAdapter.Context.ShowsProtoUnitChrome && !_isAbilityDefinitionEditorMode && _sectionJumpTargets.Count > 0;
        _sectionsButton.IsVisible = hasSections;
        _sectionsButton.IsEnabled = hasSections;
    }

    private void ScrollEditorControlToTop(Control target, int? tabIndex = null, double topPadding = 8)
    {
        var resolvedTabIndex = tabIndex ??
            (target.TranslatePoint(new Point(0, 0), _actionsEditorPanel) != null ? 1 :
             target.TranslatePoint(new Point(0, 0), _commandsEditorPanel) != null ? 2 :
             target.TranslatePoint(new Point(0, 0), _abilitiesEditorPanel) != null ? 3 :
             target.TranslatePoint(new Point(0, 0), _trainResearchEditorPanel) != null ? 4 : 0);
        _editorTabs.SelectedIndex = resolvedTabIndex;
        var targetPanel = resolvedTabIndex switch
        {
            1 => (Panel)_actionsEditorPanel,
            2 => _commandsEditorPanel,
            3 => _abilitiesEditorPanel,
            4 => _trainResearchEditorPanel,
            _ => _statsEditorPanel
        };
        var targetScroll = resolvedTabIndex switch
        {
            1 => _actionsEditorScroll,
            2 => _commandsEditorScroll,
            3 => _abilitiesEditorScroll,
            4 => _trainResearchEditorScroll,
            _ => _editorScroll
        };
        var targetOrigin = target.TranslatePoint(new Point(0, 0), targetPanel);
        if (targetOrigin == null)
        {
            target.BringIntoView();
            return;
        }

        var desiredOffsetY = Math.Max(0, targetOrigin.Value.Y - topPadding);
        var maxOffsetY = Math.Max(0, targetScroll.Extent.Height - targetScroll.Viewport.Height);
        var clampedOffsetY = Math.Min(desiredOffsetY, maxOffsetY);

        targetScroll.Offset = new Vector(targetScroll.Offset.X, clampedOffsetY);
    }

    private void OpenPageSearch()
    {
        _pageSearchPanel.IsVisible = true;
        RefreshPageSearchMatches(scrollToCurrentMatch: !string.IsNullOrWhiteSpace(_pageSearchBox.Text));
        Dispatcher.UIThread.Post(() =>
        {
            _pageSearchBox.Focus();
            _pageSearchBox.SelectAll();
        }, DispatcherPriority.Input);
    }

    private void ClosePageSearch()
    {
        ClearPageSearchHighlights();
        _pageSearchPanel.IsVisible = false;
        (_editorTabs.SelectedIndex switch
        {
            1 => _actionsEditorScroll,
            2 => _commandsEditorScroll,
            3 => _abilitiesEditorScroll,
            4 => _trainResearchEditorScroll,
            _ => _editorScroll
        }).Focus();
    }

    private void RebuildPageSearchTargets()
    {
        _pageSearchTargets.Clear();

        foreach (var target in EnumeratePageSearchTargets(_statsEditorPanel))
        {
            _pageSearchTargets.Add(target);
        }
        foreach (var target in EnumeratePageSearchTargets(_actionsEditorPanel))
        {
            _pageSearchTargets.Add(target);
        }
        foreach (var target in EnumeratePageSearchTargets(_commandsEditorPanel))
        {
            _pageSearchTargets.Add(target);
        }
        foreach (var target in EnumeratePageSearchTargets(_trainResearchEditorPanel))
        {
            _pageSearchTargets.Add(target);
        }

        RefreshPageSearchMatches(scrollToCurrentMatch: _pageSearchPanel.IsVisible && !string.IsNullOrWhiteSpace(_pageSearchBox.Text));
    }

    private IEnumerable<PageSearchTarget> EnumeratePageSearchTargets(ILogical root)
    {
        foreach (var child in root.LogicalChildren)
        {
            if (child is TextBlock textBlock)
            {
                var text = NormalizePageSearchTargetText(textBlock.Text);
                if (!string.IsNullOrWhiteSpace(text) && ShouldIncludePageSearchTextBlock(textBlock, text))
                {
                    yield return new PageSearchTarget
                    {
                        Control = textBlock,
                        Text = text
                    };
                }
            }
            else if (child is CheckBox checkBox && checkBox.Content is string checkBoxText)
            {
                var text = NormalizePageSearchTargetText(checkBoxText);
                if (!string.IsNullOrWhiteSpace(text))
                {
                    yield return new PageSearchTarget
                    {
                        Control = checkBox,
                        Text = text
                    };
                }
            }

            if (child is ILogical logicalChild)
            {
                foreach (var nestedTarget in EnumeratePageSearchTargets(logicalChild))
                {
                    yield return nestedTarget;
                }
            }
        }
    }

    private bool ShouldIncludePageSearchTextBlock(TextBlock textBlock, string text)
    {
        if (text.StartsWith("Editing:", StringComparison.OrdinalIgnoreCase))
            return false;

        for (StyledElement? current = textBlock; current != null; current = current.Parent as StyledElement)
        {
            if (current is Button ||
                current is ToggleButton ||
                current is TabStripItem ||
                current is ListBoxItem)
            {
                return false;
            }
        }

        return true;
    }

    private static bool IsPageSearchTargetVisible(Control control)
    {
        for (StyledElement? current = control; current != null; current = current.Parent as StyledElement)
        {
            if (current is Visual visual && !visual.IsVisible)
                return false;
        }

        return true;
    }

    private static string NormalizePageSearchTargetText(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return string.Empty;

        var normalized = text.Replace('\u2500', ' ').Trim();
        return Regex.Replace(normalized, "\\s+", " ");
    }

    private void RefreshPageSearchMatches(bool scrollToCurrentMatch)
    {
        ClearPageSearchHighlights();
        _pageSearchMatches.Clear();
        _currentPageSearchMatchIndex = -1;

        var query = _pageSearchBox.Text?.Trim() ?? string.Empty;
        if (string.IsNullOrWhiteSpace(query))
        {
            UpdatePageSearchUiState(hasMatches: false, hasQuery: false, hasValidPattern: true);
            return;
        }

        if (!TryCreatePageSearchRegex(query, out var regex))
        {
            UpdatePageSearchUiState(hasMatches: false, hasQuery: true, hasValidPattern: false);
            return;
        }

        foreach (var target in _pageSearchTargets)
        {
            if (IsPageSearchTargetVisible(target.Control) && regex.IsMatch(target.Text))
            {
                _pageSearchMatches.Add(target);
            }
        }

        if (_pageSearchMatches.Count == 0)
        {
            UpdatePageSearchUiState(hasMatches: false, hasQuery: true, hasValidPattern: true);
            return;
        }

        _currentPageSearchMatchIndex = 0;
        UpdatePageSearchUiState(hasMatches: true, hasQuery: true, hasValidPattern: true);
        ApplyCurrentPageSearchMatch(scrollToCurrentMatch);
    }

    private bool TryCreatePageSearchRegex(string query, out Regex regex)
    {
        try
        {
            var pattern = _pageSearchRegexToggle.IsChecked == true
                ? query
                : Regex.Escape(query);

            if (_pageSearchWholeWordToggle.IsChecked == true)
            {
                pattern = $"\\b{pattern}\\b";
            }

            var options = RegexOptions.CultureInvariant;
            if (_pageSearchMatchCaseToggle.IsChecked != true)
            {
                options |= RegexOptions.IgnoreCase;
            }

            regex = new Regex(pattern, options);
            return true;
        }
        catch (ArgumentException)
        {
            regex = null!;
            return false;
        }
    }

    private void MoveToNextPageSearchMatch()
    {
        if (_pageSearchMatches.Count == 0)
            return;

        _currentPageSearchMatchIndex = (_currentPageSearchMatchIndex + 1) % _pageSearchMatches.Count;
        ApplyCurrentPageSearchMatch(scrollToCurrentMatch: true);
    }

    private void MoveToPreviousPageSearchMatch()
    {
        if (_pageSearchMatches.Count == 0)
            return;

        _currentPageSearchMatchIndex = (_currentPageSearchMatchIndex - 1 + _pageSearchMatches.Count) % _pageSearchMatches.Count;
        ApplyCurrentPageSearchMatch(scrollToCurrentMatch: true);
    }

    private void ApplyCurrentPageSearchMatch(bool scrollToCurrentMatch)
    {
        if (_currentPageSearchMatchIndex < 0 || _currentPageSearchMatchIndex >= _pageSearchMatches.Count)
            return;

        ClearPageSearchHighlights();

        var target = _pageSearchMatches[_currentPageSearchMatchIndex].Control;
        if (target is TextBlock textBlock)
        {
            textBlock.Classes.Add("PageSearchQueryMatch");
            _pageSearchHighlightedBlocks.Add(textBlock);
        }

        UpdatePageSearchMatchCountText();

        if (scrollToCurrentMatch)
        {
            Dispatcher.UIThread.Post(() => target.BringIntoView(), DispatcherPriority.Loaded);
        }
    }

    private void ClearPageSearchHighlights()
    {
        foreach (var textBlock in _pageSearchHighlightedBlocks)
        {
            textBlock.Classes.Remove("PageSearchQueryMatch");
        }

        _pageSearchHighlightedBlocks.Clear();
    }

    private void UpdatePageSearchMatchCountText()
    {
        if (string.IsNullOrWhiteSpace(_pageSearchBox.Text))
        {
            _pageSearchMatchCountText.Text = string.Empty;
            return;
        }

        if (_currentPageSearchMatchIndex >= 0 && _pageSearchMatches.Count > 0)
        {
            _pageSearchMatchCountText.Text = $"{_currentPageSearchMatchIndex + 1} of {_pageSearchMatches.Count}";
            return;
        }

        _pageSearchMatchCountText.Text = _pageSearchMatches.Count == 0 ? "0 of 0" : $"0 of {_pageSearchMatches.Count}";
    }

    private void UpdatePageSearchUiState(bool hasMatches, bool hasQuery, bool hasValidPattern)
    {
        var borderBrush = hasMatches || !hasQuery
            ? "#4C4031"
            : "#7A1F1C";

        _pageSearchPanel.BorderBrush = Brush.Parse(borderBrush);
        _pageSearchPreviousButton.IsEnabled = hasMatches;
        _pageSearchNextButton.IsEnabled = hasMatches;
        _pageSearchMatchCountText.Foreground = Brush.Parse(hasValidPattern ? "#E8DECC" : "#ff7a7a");

        if (!hasQuery)
        {
            _pageSearchMatchCountText.Text = string.Empty;
        }
        else if (!hasValidPattern)
        {
            _pageSearchMatchCountText.Text = "Invalid pattern";
        }
        else
        {
            UpdatePageSearchMatchCountText();
        }
    }

