    private static void ApplyProtoActionFieldWidth(Control editor, string tag)
    {
        const double animationFieldWidth = 200;
        var isCompactBoneField = tag.Equals("modelattachmentbone", StringComparison.OrdinalIgnoreCase) ||
                                 tag.Equals("targetattachmentbone", StringComparison.OrdinalIgnoreCase) ||
                                 tag.Equals("infectionattachmentbone", StringComparison.OrdinalIgnoreCase);
        var fieldWidth = CompactProtoActionAnimationFieldTags.Contains(tag) ||
                         tag.Equals("modelattachment", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("infectionattachment", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("targetattachment", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("impacteffect", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("launchpoint", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("castpower", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("conversionprotoid", StringComparison.OrdinalIgnoreCase)
            ? animationFieldWidth
            : isCompactBoneField
                ? 100
                : (double?)null;
        if (fieldWidth == null)
            return;

        switch (editor)
        {
            case TextBox textBox:
                textBox.Width = fieldWidth.Value;
                textBox.MinWidth = fieldWidth.Value;
                textBox.MaxWidth = fieldWidth.Value;
                break;
            case AutoCompleteBox autoCompleteBox:
                autoCompleteBox.Width = fieldWidth.Value;
                autoCompleteBox.MinWidth = fieldWidth.Value;
                autoCompleteBox.MaxWidth = fieldWidth.Value;
                if (isCompactBoneField)
                    KeepAutoCompleteTextStartVisible(autoCompleteBox);
                break;
            case AssetPathEditor assetPathEditor:
                assetPathEditor.Width = fieldWidth.Value;
                assetPathEditor.MinWidth = fieldWidth.Value;
                assetPathEditor.MaxWidth = fieldWidth.Value;
                assetPathEditor.Editor.Width = fieldWidth.Value;
                assetPathEditor.Editor.MinWidth = fieldWidth.Value;
                assetPathEditor.Editor.MaxWidth = fieldWidth.Value;
                break;
        }
    }

    private static bool IsKnownProtoActionFlagTag(string tag)
        => !string.IsNullOrWhiteSpace(tag) &&
           ProtoActionMetadataCatalog.GetKnownFlagTags().Contains(tag.Trim(), StringComparer.OrdinalIgnoreCase);

    private static readonly IReadOnlyDictionary<string, string> InvertedDefaultProtoActionFlags =
        new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["workonfrozenunits"] = "donotworkonfrozenunits",
            ["workonabductedunits"] = "donotworkonabductedunits",
            ["workonstonedamageunits"] = "donotworkonstonedamageunits",
            ["workonchaosunits"] = "donotworkonchaosunits",
            ["healnonidle"] = "donothealnonidle",
        };

    private static bool IsInvertedDefaultProtoActionFlag(string tag)
        => InvertedDefaultProtoActionFlags.ContainsKey(tag);

    private static string GetInvertedDefaultProtoActionFlagTag(string tag)
        => InvertedDefaultProtoActionFlags.TryGetValue(tag, out var inverseTag) ? inverseTag : tag;

    private static string GetProtoActionFlagDisplayLabel(string tag)
    {
        var normalized = tag?.Trim() ?? "";
        var originalTag = InvertedDefaultProtoActionFlags
            .FirstOrDefault(pair => pair.Value.Equals(normalized, StringComparison.OrdinalIgnoreCase))
            .Key;
        if (string.IsNullOrWhiteSpace(originalTag))
            return ProtoActionMetadataCatalog.GetKnownFlagLabel(normalized);

        return originalTag.ToLowerInvariant() switch
        {
            "workonfrozenunits" => "DoNotWorkOnFrozenUnits",
            "workonabductedunits" => "DoNotWorkOnAbductedUnits",
            "workonstonedamageunits" => "DoNotWorkOnStoneDamageUnits",
            "workonchaosunits" => "DoNotWorkOnChaosUnits",
            "healnonidle" => "DoNotHealNonIdle",
            _ => ProtoActionMetadataCatalog.GetKnownFlagLabel(normalized)
        };
    }

