            {
                return;
            }

            if (seen.Add(normalized))
                tags.Add(normalized);
        }

        foreach (var tag in GetRecommendedProtoActionFieldTags(actionType))
            AddTag(tag);

        foreach (var extra in action.AdditionalElements)
        {
            if (!extra.HasElements ||
                extra.Name.LocalName.Equals("donotautogatherunlessgatheringtypes", StringComparison.OrdinalIgnoreCase) ||
                extra.Name.LocalName.Equals("scalebycontainedunittype", StringComparison.OrdinalIgnoreCase))
                AddTag(extra.Name.LocalName);
        }

        return tags;
    }

    private List<string> GetVisibleProtoActionStructuredFieldTags(ProtoActionWidgetState state, ProtoAction action, string actionType)
    {
        var tags = new List<string>(GetVisibleProtoActionStructuredFieldTags(action, actionType));

        foreach (var tag in state.ForcedVisibleFieldTags)
        {
            if (string.IsNullOrWhiteSpace(tag))
                continue;

            var normalized = tag.Trim();
              if (HardcodedProtoActionFieldTags.Contains(normalized) ||
                 IsManagedBolsterStructuredFieldTag(actionType, normalized) ||
                 IsManagedAutoBoostStructuredFieldTag(actionType, normalized) ||
                 IsManagedAutoRangedModifyStructuredFieldTag(actionType, normalized) ||
                 IsManagedDrainResurrectionStructuredFieldTag(actionType, normalized) ||
                 IsManagedHealStructuredFieldTag(actionType, normalized) ||
                 IsManagedConditionalTransformStructuredFieldTag(actionType, normalized) ||
                 IsManagedDelayedTransformStructuredFieldTag(actionType, normalized) ||
                 IsManagedMaintainStructuredFieldTag(actionType, normalized) ||
                 IsManagedAutoGatherStructuredFieldTag(actionType, normalized) ||
                 IsManagedConvertStructuredFieldTag(actionType, normalized) ||
                 IsManagedSpawnStructuredFieldTag(actionType, normalized) ||
                 IsManagedTradeStructuredFieldTag(actionType, normalized) ||
                 IsManagedAreaRestrictStructuredFieldTag(actionType, normalized) ||
                 IsManagedLureStructuredFieldTag(actionType, normalized) ||
                 IsManagedDevoteMinorStructuredFieldTag(actionType, normalized) ||
                 IsManagedDistanceModifyStructuredFieldTag(actionType, normalized) ||
                 IsManagedChargedFieldTag(actionType, normalized) ||
                 !ProtoActionMetadataCatalog.SupportsAutoRender(normalized))
            {
                continue;
            }

            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(normalized);
            if (definition.EditorKind != ProtoActionFieldEditorKind.StructuredList ||
                !definition.IsRepeatable)
            {
                continue;
            }

            if (!tags.Contains(normalized, StringComparer.OrdinalIgnoreCase))
                tags.Add(normalized);
        }

        return tags;
    }

    private List<string> GetSuggestedProtoActionStructuredFieldTags(string actionType)
    {
        var tags = new List<string>();
        foreach (var tag in GetRecommendedProtoActionFieldTags(actionType))
        {
            var normalized = tag?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(normalized) || HardcodedProtoActionFieldTags.Contains(normalized))
                continue;
            if (IsManagedBolsterStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedAutoBoostStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedDrainResurrectionStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedHealStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedConditionalTransformStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedDelayedTransformStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedMaintainStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedAutoGatherStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedConvertStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedSpawnStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedTradeStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedAreaRestrictStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedLureStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedDevoteMinorStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedDistanceModifyStructuredFieldTag(actionType, normalized))
                continue;
            if (IsManagedChargedFieldTag(actionType, normalized))
                continue;

            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(normalized);
            if (!ProtoActionMetadataCatalog.SupportsAutoRender(normalized) ||
                definition.EditorKind != ProtoActionFieldEditorKind.StructuredList ||
                !definition.IsRepeatable)
            {
                continue;
            }

            if (!tags.Contains(normalized, StringComparer.OrdinalIgnoreCase))
                tags.Add(normalized);
        }

        return tags;
    }

    private string ReadProtoActionFieldControlValue(Control control, ProtoActionFieldDefinition definition)
    {
        return definition.EditorKind switch
        {
            ProtoActionFieldEditorKind.Toggle when control is CheckBox checkBox => checkBox.IsChecked == true ? "1" : "",
            _ when control is AssetPathEditor pathEditor => pathEditor.FullValue,
            _ when control is ComboBox comboBox => comboBox.SelectedItem as string ?? "",
            _ when control is AutoCompleteBox autoCompleteBox => autoCompleteBox.Text?.Trim() ?? "",
            _ when control is TextBox textBox => textBox.Text?.Trim() ?? "",
            _ => "",
        };
    }

    private static string ReadTextLikeControlValue(Control control)
        => control switch
        {
            AssetPathEditor pathEditor => pathEditor.FullValue,
            ComboBox comboBox => comboBox.SelectedItem as string ?? "",
            AutoCompleteBox autoCompleteBox => autoCompleteBox.Text?.Trim() ?? "",
            TextBox textBox => textBox.Text?.Trim() ?? "",
            _ => "",
        };

    private async Task HandleAssetPathChangedAsync(string _)
    {
        if (_isPopulating)
            return;

        var proceed = await CheckStartLocalMod();
        if (proceed)
            MarkDirty();
    }

    private AssetPathEditor CreateAssetPathEditor(string tag, string initialValue, IEnumerable<string> suggestions)
    {
        if (tag.Equals("icon", StringComparison.OrdinalIgnoreCase))
            initialValue = NormalizeIconCatalogValue(initialValue, _baseGameIconPaths);
        var editor = new AssetPathEditor();
        editor.IsEnabled = !_isReadOnly;
        editor.Opacity = _isReadOnly ? 0.55 : 1.0;
        editor.CompactPresenter.Background = Brush.Parse(_isReadOnly ? "#202220" : "#0E1110");
        editor.Configure(initialValue, suggestions, HandleAssetPathChangedAsync);
        editor.Margin = new Thickness(0, 4, 0, 4);
        return editor;
    }

    private (AssetPathEditor Attachment, AutoCompleteBox Bone) CreateProtoActionModelAttachmentEditors(
        string attachmentValue,
        string boneValue)
    {
        var attachment = CreateAssetPathEditor(
            "modelattachment",
            attachmentValue,
            GetProtoActionValueSuggestions("modelattachment") ?? []);
        ApplyProtoActionFieldWidth(attachment, "modelattachment");

        var bone = new AutoCompleteBox
        {
            Text = boneValue,
            FilterMode = AutoCompleteFilterMode.Contains,
            ItemsSource = GetAvailableProtoActionModelAttachmentBones(),
            IsEnabled = !_isReadOnly,
            Width = 100
        };
        EditorTextFieldStyle.ConfigureSelector(bone);
        bone.Width = 100;
        EnableDropdownAutoComplete(bone);
        bone.TextChanged += async (_, _) =>
        {
            if (!_isPopulating && await CheckStartLocalMod())
                MarkDirty();
        };

        return (attachment, bone);
    }

    internal static string NormalizeIconCatalogValue(string value, IEnumerable<string> catalogPaths)
    {
        var normalized = value?.Trim().Replace('/', '\\') ?? "";
        if (!normalized.EndsWith(".dds", StringComparison.OrdinalIgnoreCase))
            return normalized;
        var pngPath = normalized[..^".dds".Length] + ".png";
        return catalogPaths.Any(path => path.Replace('/', '\\').Equals(pngPath, StringComparison.OrdinalIgnoreCase))
            ? pngPath
            : normalized;
    }

    private static StackPanel CreateLabeledFieldGroup(
        string label,
        Control editor,
        Thickness? margin = null)
    {
        editor.VerticalAlignment = VerticalAlignment.Center;

        var group = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 6,
            Margin = margin ?? new Thickness(0, 0, 12, 6),
            VerticalAlignment = VerticalAlignment.Center
        };
        group.Children.Add(new TextBlock
        {
            Text = label,
            VerticalAlignment = VerticalAlignment.Center
        });
        group.Children.Add(editor);
        return group;
    }

    private IEnumerable<string> GetAssetPathSuggestions(string tag, IEnumerable<string>? additionalValues = null)
    {
        var staticValues = ProtoConstants.FieldSuggestions.TryGetValue(tag, out var suggestions)
            ? suggestions
            : [];
        var barValues = _barXmlRoot?.Descendants(tag).Select(element => element.Value) ?? Enumerable.Empty<string>();
        var modValues = _modXmlRoot?.Descendants(tag).Select(element => element.Value) ?? Enumerable.Empty<string>();
        IEnumerable<string> catalogValues = tag.ToLowerInvariant() switch
        {
            "icon" => _baseGameIconPaths.Concat(_customIconPaths),
            "animfile" => _baseGameAnimFiles.Concat(_customAnimFiles).Select(entry => entry.Path),
            "soundsetfile" => _baseGameSoundSets.Concat(_customSoundSets).Select(entry => entry.Path),
            _ => []
        };
        return staticValues.Concat(catalogValues).Concat(barValues).Concat(modValues).Concat(additionalValues ?? []);
    }

    private static string ReadControlValue(Control control) => control switch
    {
        AssetPathEditor pathEditor => pathEditor.FullValue,
        AutoCompleteBox acb => acb.Text?.Trim() ?? "",
        TextBox tb => tb.Text?.Trim() ?? "",
        ComboBox cb => cb.SelectedItem?.ToString()?.Trim() ?? "",
        _ => ""
    };

    private static void AttachProtoActionDecimalBehavior(TextBox textBox, Func<bool>? allowNegative = null)
    {
        EditorNumericFieldStyle.ConfigureNumericTextBox(textBox);
        textBox.TextChanged += (s, e) =>
        {
            var text = textBox.Text ?? "";
            if (!string.IsNullOrWhiteSpace(text) &&
                (!double.TryParse(text, out _) || text.Count(ch => ch == '.') > 1))
            {
                var canBeNegative = allowNegative?.Invoke() == true;
                var filtered = new string(text.Where(ch => char.IsDigit(ch) || ch == '.' || (canBeNegative && ch == '-')).ToArray());
                if (filtered.Count(ch => ch == '-') > 1 || (filtered.Contains('-') && !filtered.StartsWith('-')))
                    filtered = (filtered.StartsWith('-') ? "-" : "") + filtered.Replace("-", "", StringComparison.Ordinal);
                var dotIndex = filtered.IndexOf('.');
                if (dotIndex >= 0)
                    filtered = filtered[..(dotIndex + 1)] + filtered[(dotIndex + 1)..].Replace(".", "", StringComparison.Ordinal);
                if (!string.Equals(textBox.Text, filtered, StringComparison.Ordinal))
                    textBox.Text = filtered;
            }
        };
    }

    private static void AttachProtoActionProbabilityBehavior(TextBox textBox, double maximum = 100d)
    {
        AttachProtoActionDecimalBehavior(textBox);
        textBox.LostFocus += (s, e) =>
        {
            var text = textBox.Text?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(text))
                return;

            textBox.Text = NormalizeProtoActionProbabilityText(text, maximum);
        };
    }

    internal static string NormalizeProtoActionProbabilityText(string text, double maximum = 100d)
    {
        if (!double.TryParse(text.Trim(), NumberStyles.Float, CultureInfo.InvariantCulture, out var value))
            return text;
        return Math.Clamp(value, 0d, maximum).ToString("0.####", CultureInfo.InvariantCulture);
    }

