    private static bool SupportsOptionalModelAttachmentActionType(string actionType)
        => !string.IsNullOrWhiteSpace(actionType) &&
           OptionalModelAttachmentActionTypes.Contains(actionType.Trim());

    private static bool SupportsOptionalAbductDamageAreaActionType(string actionType)
        => actionType.Equals("Abduct", StringComparison.OrdinalIgnoreCase) ||
           IsBuckAttackActionType(actionType) ||
           IsAttackActionType(actionType) ||
           IsChainAttackActionType(actionType) ||
           IsAoeAttackActionType(actionType) ||
           IsLinearAreaAttackActionType(actionType) ||
           IsLureActionType(actionType) ||
           IsRampageActionType(actionType);

    private static bool ShouldShowOptionalModelAttachmentFields(
        ProtoActionWidgetState state,
        string actionType,
        ProtoAction effectiveAction,
        IReadOnlyDictionary<string, string>? currentSimpleValues = null)
    {
        if (!SupportsOptionalModelAttachmentActionType(actionType))
            return false;

        if (state.CustomValues.GetValueOrDefault(OptionalModelAttachmentHiddenStateKey, "0") == "1")
            return false;

        var editorProfile = ProtoActionMetadataCatalog.GetEditorProfile(actionType);
        var showByDefault = editorProfile.DefaultVisibleTags.Any(tag =>
            OptionalModelAttachmentTags.Contains(tag, StringComparer.OrdinalIgnoreCase));

        return showByDefault || OptionalModelAttachmentTags.Any(tag =>
            state.ForcedVisibleFieldTags.Contains(tag) ||
            (currentSimpleValues != null &&
             currentSimpleValues.TryGetValue(tag, out var currentValue) &&
             !string.IsNullOrWhiteSpace(currentValue)) ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
    }

    private static bool ShouldShowOptionalAbductDamageAreaFields(
        ProtoActionWidgetState state,
        string actionType,
        ProtoAction effectiveAction,
        IReadOnlyDictionary<string, string>? currentSimpleValues = null)
    {
        if (!SupportsOptionalAbductDamageAreaActionType(actionType))
            return false;

        return OptionalAbductDamageAreaTags.Any(tag =>
            state.ForcedVisibleFieldTags.Contains(tag) ||
            (currentSimpleValues != null &&
             currentSimpleValues.TryGetValue(tag, out var currentValue) &&
             !string.IsNullOrWhiteSpace(currentValue)) ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
    }

    private static string GetProtoActionDefaultSimpleValue(string tag, string currentValue)
    {
        if (!string.IsNullOrWhiteSpace(currentValue))
            return currentValue;

        if (tag.Equals("devotiontime", StringComparison.OrdinalIgnoreCase))
            return "0";

        if (tag.Equals("devotioncombatxpreward", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("devotionfavorreward", StringComparison.OrdinalIgnoreCase))
        {
            return "0";
        }

        return currentValue;
    }

    private static List<string> GetDefaultVisibleProtoActionStructuredAttributeNames(string actionType, string tag)
    {
        if (tag.Equals("rate", StringComparison.OrdinalIgnoreCase) &&
            (actionType.Equals("DropOff", StringComparison.OrdinalIgnoreCase) ||
             actionType.Equals("SmartDropsite", StringComparison.OrdinalIgnoreCase)))
        {
            return [];
        }

        var defaults = new List<string>();
        if (tag.Equals("trailprotounit", StringComparison.OrdinalIgnoreCase))
        {
            defaults.Add("frequency");
            return defaults;
        }

        if (tag.Equals("rate", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("typedminrange", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("minrate", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("damage", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("damagebonus", StringComparison.OrdinalIgnoreCase))
        {
            defaults.Add("type");
        }

        return defaults;
    }

    private static readonly HashSet<string> ProtoActionTypesShowingOnHitEffectByDefault = new(StringComparer.OrdinalIgnoreCase)
    {
        "Attack",
        "Hunting",
        "AutoBoost",
        "ChainAttack",
        "AoEAttack",
        "AssistAttack",
        "LinearAreaAttack",
        "AreaRestrict",
        "Lure",
        "JumpAttack",
        "BuckAttack",
        "Maul",
        "TeleportAttack",
        "Gore",
        "Throw",
        "DrainResurrection",
    };

    private static bool ShouldShowProtoActionOnHitEffectByDefault(string actionType)
        => ProtoActionTypesShowingOnHitEffectByDefault.Contains(actionType);

    private static bool IsDeferredComplexProtoActionAttributeAvailableFromPicker(string actionType, string tag)
    {
        if (!tag.Equals("onhiteffect", StringComparison.OrdinalIgnoreCase))
            return false;

        return !ShouldShowProtoActionOnHitEffectByDefault(actionType);
    }

    private List<(string Tag, string Label)> GetAvailableProtoActionAttributePickerOptions(ProtoActionWidgetState state)
    {
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var usedTags = new HashSet<string>(state.ForcedVisibleFieldTags, StringComparer.OrdinalIgnoreCase);
        foreach (var tag in state.AdditionalFieldControls.Keys)
            usedTags.Add(tag);
        foreach (var tag in state.StructuredFieldRows.Keys)
            usedTags.Add(tag);
        foreach (var tag in state.EmpowerTargetStates.Keys)
            usedTags.Add(tag);
        foreach (var tag in GetVisibleProtoActionSimpleFieldTags(state, effectiveAction, actionType))
            usedTags.Add(tag);
        foreach (var tag in GetVisibleProtoActionStructuredFieldTags(state, effectiveAction, actionType))
            usedTags.Add(tag);
        var showsCoreRof = ShouldShowProtoActionHardcodedField(state, effectiveAction, actionType, "rof");
        var showsCoreMaxRange = ShouldShowProtoActionHardcodedField(state, effectiveAction, actionType, "maxrange");
        if (IsAttackActionType(actionType))
        {
            showsCoreRof = state.SelectedFlagTags.Contains("handlogic") || state.SelectedFlagTags.Contains("rangedlogic");
            showsCoreMaxRange = showsCoreRof;
        }
        if (state.CustomValues.GetValueOrDefault("additional.rof") != "1" && showsCoreRof)
            usedTags.Add("rof");
        if (state.CustomValues.GetValueOrDefault("additional.maxrange") != "1" && showsCoreMaxRange)
        {
            usedTags.Add("maxrange");
        }

        var options = ProtoActionMetadataCatalog.GetKnownFieldDefinitions()
            .Where(x => !ProtoActionAttributePickerExcludedTags.Contains(x.Tag))
            .Where(x => ProtoActionMetadataCatalog.SupportsAutoRender(x.Tag))
            .Where(x => x.EditorKind != ProtoActionFieldEditorKind.Toggle)
              .Where(x => !IsKnownProtoActionFlagTag(x.Tag))
              .Where(x => !IsManagedModelAttachmentFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedAbductDamageAreaFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedAbductFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedStackControlFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedBolsterStructuredFieldTag(actionType, x.Tag))
              .Where(x => !IsActionCardManagedOptionalFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedChargedFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedSelfModifyFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedReleaseSkyLanternFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedIdleStatBonusFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedDistanceModifyFieldTag(actionType, x.Tag))
              .Where(x => !IsManagedCoreMinRangeFieldTag(actionType, x.Tag))
              .Where(x => !x.Tag.Equals("modifyunittype", StringComparison.OrdinalIgnoreCase))
              .Where(x => !usedTags.Contains(x.Tag))
            .OrderBy(x => x.Label, StringComparer.OrdinalIgnoreCase)
            .Select(x => (x.Tag, x.Label))
            .ToList();

        var hasOnHitEffect = GetProtoActionOnHitEffectElements(effectiveAction).Count > 0 || state.OnHitEffectRows.Count > 0;
        if (!hasOnHitEffect &&
            !usedTags.Contains("onhiteffect") &&
            IsDeferredComplexProtoActionAttributeAvailableFromPicker(actionType, "onhiteffect"))
        {
            options.Add(("onhiteffect", ProtoActionMetadataCatalog.GetFieldDefinition("onhiteffect").Label));
        }

        var existingComplexTags = effectiveAction.AdditionalElements
            .Select(element => element.Name.LocalName)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        foreach (var complexTag in EmpowerSectionTags.Concat(["stackcontrol"]))
        {
            var isNativeActionField = complexTag.Equals("stackcontrol", StringComparison.OrdinalIgnoreCase)
                ? IsStackControlActionType(actionType)
                : IsEmpowerActionType(actionType);
            if (!isNativeActionField &&
                !usedTags.Contains(complexTag) &&
                !existingComplexTags.Contains(complexTag))
            {
                options.Add((complexTag, ProtoActionMetadataCatalog.GetFieldDefinition(complexTag).Label));
            }
        }

        var currentModifyType = state.AdditionalFieldControls.TryGetValue("modifytype", out var modifyTypeControl)
            ? ProtoConstants.GetModifyTypeValue(ReadTextLikeControlValue(modifyTypeControl))
            : ProtoConstants.GetModifyTypeValue(ProtoXmlHandler.GetProtoActionSimpleFieldValue(state.Model, "modifytype"));
        if (IsAutoRangedModifyActionType(actionType) &&
            currentModifyType.Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase) &&
            !usedTags.Contains("empowerdata"))
        {
            options.Add(("empowerdata", "Empower Data"));
        }

        return options.OrderBy(x => x.Label, StringComparer.OrdinalIgnoreCase).ToList();
    }

    private bool ShouldShowProtoActionHardcodedField(ProtoActionWidgetState state, ProtoAction action, string actionType, string tag)
    {
        if (state.ForcedVisibleFieldTags.Contains(tag))
            return true;

        var editorProfile = ProtoActionMetadataCatalog.GetEditorProfile(actionType);
        if (!editorProfile.HiddenByDefaultTags.Contains(tag))
            return true;

        return tag.ToLowerInvariant() switch
        {
            "rof" => !string.IsNullOrWhiteSpace(action.Rof),
            "maxrange" => !string.IsNullOrWhiteSpace(action.MaxRange),
            "damage" => action.Damages.Count > 0,
            "damagebonus" => action.DamageBonuses.Count > 0,
            _ => true,
        };
    }

    private static bool IsUserAddedProtoActionField(ProtoActionWidgetState state, string tag)
        => state.ForcedVisibleFieldTags.Contains(tag);

    private static bool CanRemoveProtoActionAdditionalField(string actionType, string tag)
        => !IsVisibleProtoActionFlagFieldTag(actionType, tag) &&
           !(IsMaulActionType(actionType) &&
             (tag.Equals("anim", StringComparison.OrdinalIgnoreCase) ||
              tag.Equals("impacteffect", StringComparison.OrdinalIgnoreCase))) &&
           !((IsJumpAttackActionType(actionType) || IsGoreActionType(actionType)) &&
             tag.Equals("anim", StringComparison.OrdinalIgnoreCase)) &&
           !(actionType.Equals("SwitchTactic", StringComparison.OrdinalIgnoreCase) &&
             tag.Equals("anim", StringComparison.OrdinalIgnoreCase)) &&
           !(tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
             (IsBuckAttackActionType(actionType) ||
              IsAutoBoostActionType(actionType) ||
              IsThrowActionType(actionType) ||
              IsSpawnAssistActionType(actionType) ||
              actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
              actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase) ||
              actionType.Equals("BurstHeal", StringComparison.OrdinalIgnoreCase))) &&
           !(IsDevoteMajorActionType(actionType) && tag.Equals("devotiontime", StringComparison.OrdinalIgnoreCase)) &&
           !(IsRampageActionType(actionType) &&
             (tag.Equals("autocastdistance", StringComparison.OrdinalIgnoreCase) ||
              tag.Equals("modifyduration", StringComparison.OrdinalIgnoreCase)));

    private static string GetProtoActionFieldLabel(string actionType, string tag, string defaultLabel)
        => (actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
            actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase)) &&
           tag.Equals("anim", StringComparison.OrdinalIgnoreCase)
                ? "Default animation"
            : IsAssistAttackActionType(actionType) && tag.Equals("modifymultiplier", StringComparison.OrdinalIgnoreCase)
                ? "Lifesteal"
                : IsAssistAttackActionType(actionType) && tag.Equals("modifytargetlimit", StringComparison.OrdinalIgnoreCase)
                    ? "Max Targets"
                    : IsSpawnAssistActionType(actionType) && tag.Equals("projectile", StringComparison.OrdinalIgnoreCase)
                        ? "Spawned Assist Unit"
            : IsRampageActionType(actionType) && tag.Equals("modifyduration", StringComparison.OrdinalIgnoreCase)
                ? "Duration (ms)"
            : IsReleaseSkyLanternActionType(actionType) && tag.Equals("timer", StringComparison.OrdinalIgnoreCase)
                ? "Timer (s)"
                : defaultLabel;

    private static string GetProtoActionStructuredFieldLabel(string actionType, string tag, string defaultLabel)
        => tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase)
            ? "Animations by Type"
            : tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase)
                ? "Max Range by Type"
                : defaultLabel;

    private void RenderProtoActionVisibility(ProtoActionWidgetState state)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");

        RenderAutoBoostModeControls(state, effectiveAction, actionType);
        RenderJumpAttackOptions(state, actionType);
        RenderBuckAttackOptions(state, effectiveAction, actionType);

        var showRof = state.CustomValues.GetValueOrDefault("additional.rof") != "1" &&
                      ShouldShowProtoActionHardcodedField(state, effectiveAction, actionType, "rof");
        var showMaxRange = !state.IsLinkedMaulAreaAction &&
                           state.CustomValues.GetValueOrDefault("additional.maxrange") != "1" &&
                           ShouldShowProtoActionHardcodedField(state, effectiveAction, actionType, "maxrange");
        if (IsAttackActionType(actionType))
        {
            var usesCombatRanges = state.SelectedFlagTags.Contains("handlogic") || state.SelectedFlagTags.Contains("rangedlogic");
            showRof = usesCombatRanges && state.CustomValues.GetValueOrDefault("additional.rof") != "1";
            showMaxRange = usesCombatRanges && state.CustomValues.GetValueOrDefault("additional.maxrange") != "1";
        }
        state.CoreFieldsGrid.IsVisible = showRof || showMaxRange ||
                                         ShouldShowCoreMinRange(state, effectiveAction, actionType);
        state.RofLabel.IsVisible = showRof;
        state.RofTb.IsVisible = showRof;
        state.MaxRangeLabel.IsVisible = showMaxRange;
        state.MaxRangeTb.IsVisible = showMaxRange;

        var showCoreMinRange = ShouldShowCoreMinRange(state, effectiveAction, actionType);
        if (showMaxRange && !showRof && !showCoreMinRange)
        {
            state.CoreFieldsGrid.ColumnDefinitions = new ColumnDefinitions("Auto, 80, Auto");
            Grid.SetColumn(state.MaxRangeLabel, 0);
            Grid.SetColumn(state.MaxRangeTb, 1);
        }
        state.MaxRangeLabel.Margin = new Thickness(
            showMaxRange && !showRof && !showCoreMinRange ? 0 : 18,
            0,
            10,
            0);
        EnsureJumpAttackCoreLayout(state, effectiveAction, actionType);

        foreach (var existingLinearShockwave in state.CoreFieldsGrid.Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "buckattack.linearshockwave", StringComparison.Ordinal))
                     .ToList())
        {
            state.CoreFieldsGrid.Children.Remove(existingLinearShockwave);
        }
        if (IsBuckAttackActionType(actionType) && showMaxRange)
        {
            var maxRangeColumn = Grid.GetColumn(state.MaxRangeTb);
            if (maxRangeColumn >= 0 && maxRangeColumn < state.CoreFieldsGrid.ColumnDefinitions.Count)
                state.CoreFieldsGrid.ColumnDefinitions[maxRangeColumn].Width = new GridLength(90);
            var linearShockwaveCheckBox = new CheckBox
            {
                Tag = "buckattack.linearshockwave",
                Content = "Linear Shockwave",
                IsChecked = state.SelectedFlagTags.Contains("linearshockwave"),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0)
            };
            linearShockwaveCheckBox.IsCheckedChanged += async (_, _) =>
            {
                if (_isPopulating || !await CheckStartLocalMod())
                    return;
                if (linearShockwaveCheckBox.IsChecked == true)
                    state.SelectedFlagTags.Add("linearshockwave");
                else
                    state.SelectedFlagTags.Remove("linearshockwave");
                RenderProtoActionFlags(state);
                MarkDirty();
            };
            state.CustomFlagControls["linearshockwave"] = linearShockwaveCheckBox;
            RegisterProtoActionFlagSourceControl(state, linearShockwaveCheckBox, "linearshockwave");
            var linearShockwaveSpacerColumn = Grid.GetColumn(state.MaxRangeTb) + 1;
            while (state.CoreFieldsGrid.ColumnDefinitions.Count <= linearShockwaveSpacerColumn)
                state.CoreFieldsGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
            state.CoreFieldsGrid.ColumnDefinitions[linearShockwaveSpacerColumn].Width = new GridLength(8);
            var linearShockwaveColumn = linearShockwaveSpacerColumn + 1;
            while (state.CoreFieldsGrid.ColumnDefinitions.Count <= linearShockwaveColumn)
                state.CoreFieldsGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
            Grid.SetColumn(linearShockwaveCheckBox, linearShockwaveColumn);
            state.CoreFieldsGrid.Children.Add(linearShockwaveCheckBox);
        }

        foreach (var existingKillOnInvalidLand in state.CoreFieldsGrid.Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "throw.killoninvalidland", StringComparison.Ordinal))
                     .ToList())
        {
            state.CoreFieldsGrid.Children.Remove(existingKillOnInvalidLand);
        }
        if (IsThrowActionType(actionType) && showMaxRange)
        {
            var killOnInvalidLandCheckBox = new CheckBox
            {
                Tag = "throw.killoninvalidland",
                Content = "Kill On Invalid Land",
                IsChecked = state.SelectedFlagTags.Contains("killoninvalidland"),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0)
            };
            killOnInvalidLandCheckBox.IsCheckedChanged += async (_, _) =>
            {
                if (_isPopulating || !await CheckStartLocalMod())
                    return;
                if (killOnInvalidLandCheckBox.IsChecked == true)
                    state.SelectedFlagTags.Add("killoninvalidland");
                else
                    state.SelectedFlagTags.Remove("killoninvalidland");
                RenderProtoActionFlags(state);
                MarkDirty();
            };
            state.CustomFlagControls["killoninvalidland"] = killOnInvalidLandCheckBox;
            RegisterProtoActionFlagSourceControl(state, killOnInvalidLandCheckBox, "killoninvalidland");
            var killOnInvalidLandSpacerColumn = Grid.GetColumn(state.MaxRangeTb) + 1;
            while (state.CoreFieldsGrid.ColumnDefinitions.Count <= killOnInvalidLandSpacerColumn)
                state.CoreFieldsGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
            state.CoreFieldsGrid.ColumnDefinitions[killOnInvalidLandSpacerColumn].Width = new GridLength(8);
            var killOnInvalidLandColumn = killOnInvalidLandSpacerColumn + 1;
            while (state.CoreFieldsGrid.ColumnDefinitions.Count <= killOnInvalidLandColumn)
                state.CoreFieldsGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
            Grid.SetColumn(killOnInvalidLandCheckBox, killOnInvalidLandColumn);
            state.CoreFieldsGrid.Children.Add(killOnInvalidLandCheckBox);
        }

        // AreaMutate shares the AutoRanged targeting editor, but Keep Alive belongs with its range.
        foreach (var existingKeepAlive in state.CoreFieldsGrid.Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "areamutate.keepalive", StringComparison.Ordinal))
                     .ToList())
        {
            state.CoreFieldsGrid.Children.Remove(existingKeepAlive);
        }
        if (IsAreaMutateActionType(actionType))
        {
            var maxRangeOnly = showMaxRange && !showRof && !showCoreMinRange;
            state.CoreFieldsGrid.ColumnDefinitions = maxRangeOnly
                ? new ColumnDefinitions("Auto, 80, Auto")
                : new ColumnDefinitions("Auto, 80, Auto, 80, Auto");
            Grid.SetColumn(state.MaxRangeLabel, maxRangeOnly ? 0 : 2);
            Grid.SetColumn(state.MaxRangeTb, maxRangeOnly ? 1 : 3);
            var keepAliveCheckBox = new CheckBox
            {
                Tag = "areamutate.keepalive",
                Content = "Keep Alive",
                IsChecked = state.SelectedFlagTags.Contains("keepalive"),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(18, 0, 0, 0)
            };
            keepAliveCheckBox.IsCheckedChanged += async (_, _) =>
            {
                if (_isPopulating || !await CheckStartLocalMod()) return;
                if (keepAliveCheckBox.IsChecked == true) state.SelectedFlagTags.Add("keepalive");
                else state.SelectedFlagTags.Remove("keepalive");
                RenderProtoActionFlags(state);
                MarkDirty();
            };
            state.CustomFlagControls["keepalive"] = keepAliveCheckBox;
            RegisterProtoActionFlagSourceControl(state, keepAliveCheckBox, "keepalive");
            Grid.SetColumn(keepAliveCheckBox, maxRangeOnly ? 2 : 4);
            state.CoreFieldsGrid.Children.Add(keepAliveCheckBox);
        }

        foreach (var existingSingleUse in state.CoreFieldsGrid.Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "attaching.singleuse", StringComparison.Ordinal))
                     .ToList())
        {
            state.CoreFieldsGrid.Children.Remove(existingSingleUse);
        }
        if (IsAttachingActionType(actionType) && showMaxRange)
        {
            var singleUseCheckBox = new CheckBox
            {
                Tag = "attaching.singleuse",
                Content = "Single Use",
                IsChecked = state.SelectedFlagTags.Contains("singleuse"),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(12, 0, 0, 0)
            };
            singleUseCheckBox.IsCheckedChanged += async (_, _) =>
            {
                if (_isPopulating || !await CheckStartLocalMod()) return;
                if (singleUseCheckBox.IsChecked == true) state.SelectedFlagTags.Add("singleuse");
                else state.SelectedFlagTags.Remove("singleuse");
                RenderProtoActionFlags(state);
                MarkDirty();
            };
            state.CustomFlagControls["singleuse"] = singleUseCheckBox;
            RegisterProtoActionFlagSourceControl(state, singleUseCheckBox, "singleuse");
            var singleUseColumn = Grid.GetColumn(state.MaxRangeTb) + 1;
            while (state.CoreFieldsGrid.ColumnDefinitions.Count <= singleUseColumn)
                state.CoreFieldsGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
            Grid.SetColumn(singleUseCheckBox, singleUseColumn);
            state.CoreFieldsGrid.Children.Add(singleUseCheckBox);
        }

        var selfOnlyAutoBoost = IsAutoBoostActionType(actionType) &&
                                IsAutoBoostSelfEnabled(state, effectiveAction) &&
                                !IsAutoBoostAreaEnabled(state, effectiveAction);
        var conditionalShieldDamageEnabled = !IsConditionalShieldActionType(actionType) ||
                                             IsConditionalShieldDamageEnabled(state, effectiveAction);
        var showDamageSection = !selfOnlyAutoBoost &&
                                (IsConditionalShieldActionType(actionType) || conditionalShieldDamageEnabled) &&
                                (IsConditionalShieldActionType(actionType) ||
                                 ShouldShowProtoActionHardcodedField(state, effectiveAction, actionType, "damage"));
        state.DamageSectionContainer.IsVisible = showDamageSection;
        if (IsConditionalShieldActionType(actionType))
        {
            // Damage flags are required for both shield modes, but damage entries only apply in Damage mode.
            if (state.DamageSectionContainer.Children.Count > 0)
                state.DamageSectionContainer.Children[0].IsVisible =
                    conditionalShieldDamageEnabled && state.DamageRows.Count > 0;
            if (state.DamageSectionContainer.Children.Count > 1)
                state.DamageSectionContainer.Children[1].IsVisible = conditionalShieldDamageEnabled;
        }
        state.BonusSectionContainer.IsVisible = !selfOnlyAutoBoost && conditionalShieldDamageEnabled &&
                                                (IsRampageActionType(actionType) ||
                                                 IsAutoBoostActionType(actionType) ||
                                                 ShouldShowProtoActionHardcodedField(state, effectiveAction, actionType, "damagebonus"));
    }

    private static bool IsConditionalShieldDamageEnabled(ProtoActionWidgetState state, ProtoAction effectiveAction)
        => state.CustomValues.TryGetValue("conditionalshield.damage", out var value)
            ? value == "1"
            : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "damageflags")
                  .Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                  .Contains("Enemy", StringComparer.OrdinalIgnoreCase);

    private bool IsAutoBoostSelfEnabled(ProtoActionWidgetState state, ProtoAction effectiveAction)
    {
        if (state.CustomValues.TryGetValue(AutoBoostSelfEnabledStateKey, out var configuredValue))
            return configuredValue.Equals("1", StringComparison.OrdinalIgnoreCase);

        var effects = state.OnHitEffectRows.Count > 0
            ? state.OnHitEffectRows.Select(x => x.TypeCb.Text?.Trim() ?? "")
            : GetProtoActionOnHitEffectElements(effectiveAction).Select(x => (string?)x.Attribute("type") ?? "");
        return effects.Any(x => x.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) ||
                                x.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase));
    }

    private bool IsAutoBoostAreaEnabled(ProtoActionWidgetState state, ProtoAction effectiveAction)
    {
        if (state.CustomValues.TryGetValue(AutoBoostAreaEnabledStateKey, out var configuredValue))
            return configuredValue.Equals("1", StringComparison.OrdinalIgnoreCase);

        var effects = state.OnHitEffectRows.Count > 0
            ? state.OnHitEffectRows.Select(x => x.TypeCb.Text?.Trim() ?? "")
            : GetProtoActionOnHitEffectElements(effectiveAction).Select(x => (string?)x.Attribute("type") ?? "");
        return effects.Any(x => x.Equals("Boost", StringComparison.OrdinalIgnoreCase)) ||
               state.IsNewCustomAction;
    }

    private void RenderAutoBoostModeControls(ProtoActionWidgetState state, ProtoAction effectiveAction, string actionType)
    {
        state.AutoBoostModeContainer.Children.Clear();
        state.AutoBoostModeContainer.IsVisible = IsAutoBoostActionType(actionType);
        if (!state.AutoBoostModeContainer.IsVisible)
            return;

        var selfEnabled = IsAutoBoostSelfEnabled(state, effectiveAction) &&
                          !IsAutoBoostAreaEnabled(state, effectiveAction);
        var areaEnabled = !selfEnabled;
        state.CustomValues[AutoBoostSelfEnabledStateKey] = selfEnabled ? "1" : "0";
        state.CustomValues[AutoBoostAreaEnabledStateKey] = areaEnabled ? "1" : "0";

        var modeRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 14,
            Margin = new Thickness(0, 0, 0, 2)
        };
        modeRow.Children.Add(new TextBlock
        {
            Text = "Boost Mode:",
            VerticalAlignment = VerticalAlignment.Center
        });

        var modeOptions = new[] { "Self", "Area" };
        var selectedMode = selfEnabled ? "Self" : "Area";
        var modeCombo = new ComboBox
        {
            ItemsSource = modeOptions,
            SelectedItem = selectedMode,
            Width = 120,
            IsEnabled = !_isReadOnly,
            VerticalAlignment = VerticalAlignment.Center
        };
        modeCombo.SelectionChanged += async (_, _) =>
        {
            if (_isPopulating)
                return;
            if (!await CheckStartLocalMod())
                return;

            var mode = modeCombo.SelectedItem as string ?? "Area";
            state.CustomValues[AutoBoostSelfEnabledStateKey] = mode == "Self" ? "1" : "0";
            state.CustomValues[AutoBoostAreaEnabledStateKey] = mode == "Area" ? "1" : "0";
            state.CustomValues[AutoBoostResetOnHitEffectStateKey] = mode == "Self" ? "SelfModify" : "Boost";
            MarkDirty();
            RefreshProtoActionMetadataPanels(state);
        };
        modeRow.Children.Add(modeCombo);
        state.AutoBoostModeContainer.Children.Add(modeRow);
    }

    private void RenderJumpAttackOptions(ProtoActionWidgetState state, string actionType)
    {
        state.JumpAttackOptionsContainer.Children.Clear();
        state.JumpAttackOptionsContainer.IsVisible = IsJumpAttackActionType(actionType);
        if (!state.JumpAttackOptionsContainer.IsVisible)
            return;

        var optionsRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 16,
            Margin = new Thickness(0, 0, 0, 2)
        };

        CheckBox CreateFlagCheckBox(string label, string flagTag)
        {
            var checkBox = new CheckBox
            {
                Content = label,
                IsChecked = state.SelectedFlagTags.Contains(flagTag),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center
            };
            checkBox.IsCheckedChanged += async (_, _) =>
            {
                if (_isPopulating)
                    return;

                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                if (checkBox.IsChecked == true)
                    state.SelectedFlagTags.Add(flagTag);
                else
                    state.SelectedFlagTags.Remove(flagTag);

                RenderProtoActionFlags(state);
                MarkDirty();
            };
            return checkBox;
        }

        optionsRow.Children.Add(CreateFlagCheckBox("Only If Path Clear", "onlyattackifpathclear"));
        optionsRow.Children.Add(CreateFlagCheckBox("Ambush Only", "ambushonly"));
        state.JumpAttackOptionsContainer.Children.Add(optionsRow);
    }

    private void EnsureJumpAttackCoreLayout(ProtoActionWidgetState state, ProtoAction effectiveAction, string actionType)
    {
        var isWaterTornado = actionType.Equals("WaterTornado", StringComparison.OrdinalIgnoreCase);
        var usesAttackLikeRangeLayout = IsAttackActionType(actionType) || IsChainAttackActionType(actionType) || IsAoeAttackActionType(actionType) || IsLinearAreaAttackActionType(actionType) || IsAbductActionType(actionType) || IsTeleportAttackActionType(actionType) || isWaterTornado;
        foreach (var existingAttackMinRangeButton in state.CoreFieldsGrid.Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "attack.minrange.button", StringComparison.Ordinal) ||
                                       string.Equals(control.Tag as string, "attack.minrange.remove", StringComparison.Ordinal))
                     .ToList())
        {
            state.CoreFieldsGrid.Children.Remove(existingAttackMinRangeButton);
        }
        if (!ShouldShowCoreMinRange(state, effectiveAction, actionType))
        {
            if (state.JumpAttackMinRangeTb != null || usesAttackLikeRangeLayout)
            {
                if (state.JumpAttackMinRangeTb != null)
                    state.JumpAttackMinRangeTb.IsVisible = false;
                if (state.JumpAttackMinRangeLabel != null)
                    state.JumpAttackMinRangeLabel.IsVisible = false;
                var showRof = state.RofLabel.IsVisible;
                state.CoreFieldsGrid.ColumnDefinitions = isWaterTornado
                    ? new ColumnDefinitions("Auto, Auto, 80")
                    : showRof
                    ? usesAttackLikeRangeLayout
                        ? new ColumnDefinitions("Auto, 80, Auto, Auto, 80")
                        : new ColumnDefinitions("Auto, 80, Auto, 80")
                    : usesAttackLikeRangeLayout
                        ? new ColumnDefinitions("Auto, 80, Auto")
                        : new ColumnDefinitions("Auto, 80");
                Grid.SetColumn(state.MaxRangeLabel, isWaterTornado ? 1 : showRof ? (usesAttackLikeRangeLayout ? 3 : 2) : 0);
                Grid.SetColumn(state.MaxRangeTb, isWaterTornado ? 2 : showRof ? (usesAttackLikeRangeLayout ? 4 : 3) : 1);
                var supportsAttackCombatRanges = !IsAttackActionType(actionType) ||
                                                 state.SelectedFlagTags.Contains("handlogic") ||
                                                 state.SelectedFlagTags.Contains("rangedlogic");
                if (usesAttackLikeRangeLayout && supportsAttackCombatRanges && !_isReadOnly)
                {
                    var addMinRangeButton = new Button
                    {
                        Tag = "attack.minrange.button",
                        Content = "Min Range",
                        Classes = { "add-component" },
                        Margin = isWaterTornado ? new Thickness(0, 0, 8, 0) : new Thickness(12, 0, 0, 0)
                    };
                    addMinRangeButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Add("minrange");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    Grid.SetColumn(addMinRangeButton, isWaterTornado ? 0 : 2);
                    state.CoreFieldsGrid.Children.Add(addMinRangeButton);
                }
            }
            return;
        }

        state.CoreFieldsGrid.ColumnDefinitions = isWaterTornado
            ? new ColumnDefinitions("Auto, 90, 42, Auto, 80")
            : usesAttackLikeRangeLayout
            ? new ColumnDefinitions("Auto, 80, Auto, 90, 42, Auto, 80")
            : new ColumnDefinitions("Auto, 80, Auto, 80, Auto, 80");
        Grid.SetColumn(state.MaxRangeLabel, isWaterTornado ? 3 : usesAttackLikeRangeLayout ? 5 : 4);
        Grid.SetColumn(state.MaxRangeTb, isWaterTornado ? 4 : usesAttackLikeRangeLayout ? 6 : 5);

        void AddAttackMinRangeRemoveButton()
        {
            if (!usesAttackLikeRangeLayout || _isReadOnly)
                return;

            var removeButton = new Button
            {
                Tag = "attack.minrange.remove",
                Classes = { "remove-button" },
                Margin = new Thickness(5, 0, 0, 0) };
            removeButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;
                state.ForcedVisibleFieldTags.Remove("minrange");
                state.JumpAttackMinRangeTb?.Clear();
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "minrange", "");
                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            Grid.SetColumn(removeButton, isWaterTornado ? 2 : 4);
            state.CoreFieldsGrid.Children.Add(removeButton);
        }
        if (state.JumpAttackMinRangeTb != null)
        {
                state.JumpAttackMinRangeTb.IsVisible = true;
                state.JumpAttackMinRangeTb.Width = 90;
                state.JumpAttackMinRangeTb.Margin = new Thickness(0, 0, 8, 0);
            if (state.JumpAttackMinRangeLabel != null)
                state.JumpAttackMinRangeLabel.IsVisible = true;
            AddAttackMinRangeRemoveButton();
            return;
        }

        var minRangeLabel = new TextBlock
        {
            Text = "Min Range:",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(18, 0, 10, 0)
        };
        Grid.SetColumn(minRangeLabel, isWaterTornado ? 0 : 2);
        state.CoreFieldsGrid.Children.Add(minRangeLabel);

        var initialMinRange = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "minrange");
        var minRangeTb = new TextBox
        {
            Text = string.IsNullOrWhiteSpace(initialMinRange) && state.IsNewCustomAction ? "0" : initialMinRange,
            IsEnabled = !_isReadOnly,
            Width = 90,
            Margin = new Thickness(0, 0, 8, 0)
        };
        AttachProtoActionDecimalBehavior(minRangeTb);
        minRangeTb.TextChanged += async (_, _) =>
        {
            if (_isPopulating)
                return;

            var proceed = await CheckStartLocalMod();
            if (proceed)
                MarkDirty();
        };
        Grid.SetColumn(minRangeTb, isWaterTornado ? 1 : 3);
        state.CoreFieldsGrid.Children.Add(minRangeTb);
        state.JumpAttackMinRangeLabel = minRangeLabel;
        state.JumpAttackMinRangeTb = minRangeTb;
        AddAttackMinRangeRemoveButton();
    }

    private void RenderBuckAttackOptions(ProtoActionWidgetState state, ProtoAction effectiveAction, string actionType)
    {
        state.BuckAttackOptionsContainer.Children.Clear();
        state.BuckAttackOptionsContainer.IsVisible =
            IsBuckAttackActionType(actionType) ||
            actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
            actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase) ||
            actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase);
        if (!state.BuckAttackOptionsContainer.IsVisible)
            return;

        var rawWorkOnFrozenUnits = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "workonfrozenunits");
        if (!state.CustomValues.ContainsKey(BuckAttackWorkOnFrozenUnitsStateKey))
        {
            state.CustomValues[BuckAttackWorkOnFrozenUnitsStateKey] =
                IsProtoActionFlagEnabledValue(rawWorkOnFrozenUnits) ? "1" : "0";
            state.CustomValues[BuckAttackWorkOnFrozenUnitsExplicitStateKey] =
                state.IsNewCustomAction || !string.IsNullOrWhiteSpace(rawWorkOnFrozenUnits) ? "1" : "0";
        }

        var optionsRow = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 16,
            Margin = new Thickness(0, 0, 0, 2)
        };

        if (optionsRow.Children.Count > 0)
            state.BuckAttackOptionsContainer.Children.Add(optionsRow);
    }

    private void ConfigureStrictSuggestionAutoComplete(AutoCompleteBox autoCompleteBox, IEnumerable<string> suggestions, string initialValue)
    {
        var renderState = _activeProtoActionRenderState;
        var renderRevision = renderState?.RenderRevision ?? 0;
        EditorAutoCompleteService.ConfigureStrict(
            autoCompleteBox,
            suggestions,
            initialValue,
            () => _isPopulating ||
                  (renderState != null &&
                   (renderState.IsRefreshingMetadataPanels || renderState.RenderRevision != renderRevision)),
            preserveUnknownInitialValue: true);
    }

    private void CaptureProtoActionDraftFromControls(
        ProtoActionWidgetState state,
        string selectedType,
        bool preserveMissingDynamicCollections,
        bool consumePendingChargedElements)
    {
        var simpleValues = state.AdditionalFieldControls.ToDictionary(
            pair => pair.Key,
            pair => ReadProtoActionFieldControlValue(
                pair.Value,
                ProtoActionMetadataCatalog.GetFieldDefinition(pair.Key)),
            StringComparer.OrdinalIgnoreCase);
        var structuredValues = state.StructuredFieldRows.Keys.ToDictionary(
            tag => tag,
            tag => CollectProtoActionStructuredFieldEntries(state, tag),
            StringComparer.OrdinalIgnoreCase);
        var damages = state.DamageRows
            .Select(row => (
                DamageType: (row.TypeCb.SelectedItem as string ?? row.TypeCb.Text ?? "").Trim(),
                Amount: row.ValTb.Text?.Trim() ?? "0"))
            .Where(entry => !string.IsNullOrWhiteSpace(entry.DamageType))
            .ToList();
        var damageBonuses = state.BonusRows
            .Select(row => (
                UnitType: row.TypeAcb.Text?.Trim() ?? "",
                Multiplier: row.ValTb.Text?.Trim() ?? "0"))
            .Where(entry => !string.IsNullOrWhiteSpace(entry.UnitType))
            .ToList();
        Dictionary<string, XElement?>? empowerSections = null;
        if (state.EmpowerTargetStates.Count > 0 || !preserveMissingDynamicCollections)
        {
            empowerSections = state.EmpowerTargetStates.Keys.ToDictionary(
                sectionTag => sectionTag,
                sectionTag => BuildEmpowerSectionElement(state, sectionTag),
                StringComparer.OrdinalIgnoreCase);
        }
        var onHitEffects = state.OnHitEffectRows.Count > 0 || !preserveMissingDynamicCollections
            ? CollectProtoActionOnHitEffectEntries(state)
                .Select(entry => new ProtoActionDraft.ElementSnapshot(entry.Element, entry.IsSupported))
                .ToList()
            : null;
        List<XElement>? fullChargedElements = state.FullChargedRows.Count > 0 || !preserveMissingDynamicCollections
            ? BuildFullChargedElements(state, includeEmptyRows: true)
            : null;
        var chargedElements = state.ChargedRows.Count > 0 || !preserveMissingDynamicCollections
            ? BuildChargedElements(state, includeEmptyRows: true)
            : null;

        if (consumePendingChargedElements && state.PendingFullChargedElements.Count > 0)
        {
            fullChargedElements ??= [];
            fullChargedElements.AddRange(state.PendingFullChargedElements.Select(element => new XElement(element)));
            state.PendingFullChargedElements.Clear();
        }

        state.Draft.Replace(
            state.RenderRevision,
            state.NameAcb.Text,
            selectedType,
            GetAttackMode(state),
            state.RofTb.Text,
            state.JumpAttackMinRangeTb?.Text,
            state.MaxRangeTb.Text,
            damages,
            damageBonuses,
            simpleValues,
            structuredValues,
            state.SelectedFlagTags,
            state.ForcedVisibleFieldTags,
            state.CustomValues,
            empowerSections,
            onHitEffects,
            fullChargedElements,
            chargedElements);
    }

    private void RefreshProtoActionMetadataPanels(ProtoActionWidgetState state)
    {
        if (state.IsRefreshingMetadataPanels)
            return;

        state.IsRefreshingMetadataPanels = true;
        state.RenderRevision++;
        var previousRenderState = _activeProtoActionRenderState;
        var wasPopulating = _isPopulating;
        _activeProtoActionRenderState = state;
        _isPopulating = true;
        try
        {
        var selectedType = GetExactProtoActionTypeMatch(state.TypeAcb.Text);
        var hasSelectedType = !string.IsNullOrWhiteSpace(selectedType);
        state.BodyContainer.IsVisible = hasSelectedType;
        state.ActiveLabel.IsVisible = hasSelectedType;
        state.ActiveCheckBox.IsVisible = hasSelectedType;
        EnsureProtoActionDefaultFlags(state, selectedType ?? "");
        if (!hasSelectedType)
            return;

        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", selectedType!);
        ReorderProtoActionSectionContainers(state, actionType);
        CaptureProtoActionDraftFromControls(
            state,
            selectedType!,
            preserveMissingDynamicCollections: true,
            consumePendingChargedElements: true);
        var currentSimpleValues = state.Draft.CopySimpleValues();
        var currentStructuredValues = state.Draft.CopyStructuredValues();
        var currentSelectedFlagTags = state.Draft.CopySelectedFlagTags();
        var currentForcedVisibleFieldTags = state.Draft.CopyForcedVisibleFieldTags();
        var currentCustomValues = state.Draft.CopyCustomValues();
        var currentEmpowerSections = state.Draft.CopyEmpowerSections();
        state.SelectedFlagTags.Clear();
        state.SelectedFlagTags.UnionWith(currentSelectedFlagTags);
        state.ForcedVisibleFieldTags.Clear();
        state.ForcedVisibleFieldTags.UnionWith(currentForcedVisibleFieldTags);
        state.CustomValues.Clear();
        foreach (var pair in currentCustomValues)
            state.CustomValues[pair.Key] = pair.Value;
        var currentOnHitEffectEntries = state.Draft.CopyOnHitEffects()?
            .Select(snapshot => new ProtoActionOnHitEffectEntry
            {
                Element = snapshot.Element,
                IsSupported = snapshot.IsSupported
            })
            .ToList();
        var currentFullChargedElements = state.Draft.CopyFullChargedElements();
        var currentChargedElements = state.Draft.CopyChargedElements();
        RenderProtoActionVisibility(state);
        RenderProtoActionAdditionalFields(state, currentSimpleValues, currentStructuredValues);
        RenderProtoActionDamageExtras(state, currentSimpleValues);
        RenderProtoActionStackControlFields(state, currentSimpleValues);
        RenderProtoActionEmpowerSections(state, currentEmpowerSections);
        RenderProtoActionChargedFields(
            state,
            currentChargedElements ?? (IsBolsterActionType(actionType) ? currentFullChargedElements : null));
        RenderProtoActionFullChargedFields(
            state,
            currentFullChargedElements ?? (!IsBolsterActionType(actionType) ? currentChargedElements : null));
        RenderProtoActionStructuredFields(state, currentStructuredValues);
        ArrangePostRateAnimationLayout(state, actionType);
        ArrangeAutoBoostPostRateLayout(state, actionType);
        ArrangeLureLayout(state, actionType);
        ArrangeBuckAttackAndBuildLayout(state, actionType);
        ArrangeTrailingImpactEffectLayout(state, actionType);
        ArrangeRampageLayout(state, actionType);
        RenderAbductPostCoreFields(state, currentSimpleValues, actionType);
        RenderAbductPostRateAnimationFields(state, currentSimpleValues, actionType);
        RenderTeleportAttackPostRateFields(state, currentSimpleValues, actionType);
        IReadOnlyList<string>? newOnHitEffectTypes = null;
        string? defaultOnHitEffectType = null;
        if (IsAutoBoostActionType(actionType))
        {
            var selfBoostEnabled = IsAutoBoostSelfEnabled(state, CreateEffectiveProtoActionSnapshot(state));
            var areaBoostEnabled = IsAutoBoostAreaEnabled(state, CreateEffectiveProtoActionSnapshot(state));
            if (areaBoostEnabled)
            {
                defaultOnHitEffectType = "Boost";
            }
            else if (selfBoostEnabled)
            {
                newOnHitEffectTypes = ["SelfModify", "SelfStealth"];
                defaultOnHitEffectType = "SelfModify";
            }
        }
        RenderProtoActionOnHitEffects(state, currentOnHitEffectEntries, newOnHitEffectTypes, defaultOnHitEffectType);
        var hasOnHitEffects = (currentOnHitEffectEntries?.Count ?? 0) > 0 ||
                              state.OnHitEffectRows.Count > 0 ||
                              GetProtoActionOnHitEffectElements(CreateEffectiveProtoActionSnapshot(state)).Count > 0;
        state.OnHitEffectsContainer.IsVisible = ShouldShowProtoActionOnHitEffectByDefault(actionType) ||
                                                state.ForcedVisibleFieldTags.Contains("onhiteffect") ||
                                                hasOnHitEffects;
        RenderProtoActionFlags(state);
        RenderProtoActionOptionalFields(state, currentSimpleValues, currentStructuredValues);
        MoveLikeBonusAttachmentRowsBelowRate(state, actionType);
        MoveBurstHealAttachmentBelowAnimation(state, actionType);
        MoveConvertAnimationBeforeAttachment(state, actionType);
        ArrangeDevoteMajorLayout(state, actionType);
        ArrangeDevoteMinorLayout(state, actionType);
        ArrangeEatLayout(state, actionType);
        ArrangeDistanceModifyStructuredLayout(state, actionType);
        ArrangeDrainResurrectionStructuredLayout(state, actionType);
        ArrangeEmpowerLayout(state, actionType);
        RefreshProtoActionSourceMarkers(state);
        }
        finally
        {
            _isPopulating = wasPopulating;
            _activeProtoActionRenderState = previousRenderState;
            state.IsRefreshingMetadataPanels = false;
        }
    }

    private static void ArrangePostRateAnimationLayout(ProtoActionWidgetState state, string actionType)
    {
        if (IsMaulActionType(actionType))
        {
            var row = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };

            foreach (var tag in new[] { "anim", "impacteffect" })
            {
                if (!state.AdditionalFieldControls.TryGetValue(tag, out var editor) || editor.Parent is not Grid fieldRow)
                    continue;
                if (!state.AdditionalFieldsContainer.Children.Remove(fieldRow))
                    continue;

                fieldRow.ColumnDefinitions = new ColumnDefinitions("Auto, Auto");
                fieldRow.HorizontalAlignment = HorizontalAlignment.Left;
                fieldRow.Margin = new Thickness(row.Children.Count == 0 ? 0 : 14, 0, 0, 0);
                editor.Width = 200;
                editor.MaxWidth = 200;
                row.Children.Add(fieldRow);
            }

            if (row.Children.Count > 0)
                state.StructuredFieldsContainer.Children.Add(row);
            return;
        }

        if (IsThrowActionType(actionType) || IsJumpAttackActionType(actionType) || IsGoreActionType(actionType))
        {
            var visualRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };

            foreach (var tag in new[] { "anim", "impacteffect" })
            {
                if (!state.AdditionalFieldControls.TryGetValue(tag, out var editor) || editor.Parent is not Grid fieldRow)
                    continue;
                if (!state.AdditionalFieldsContainer.Children.Remove(fieldRow))
                    continue;

                fieldRow.ColumnDefinitions = fieldRow.ColumnDefinitions.Count >= 3
                    ? new ColumnDefinitions("Auto, 200, Auto")
                    : new ColumnDefinitions("Auto, 200");
                fieldRow.HorizontalAlignment = HorizontalAlignment.Left;
                fieldRow.Margin = new Thickness(visualRow.Children.Count == 0 ? 0 : 14, 0, 0, 0);
                editor.Width = 200;
                editor.MinWidth = 200;
                editor.MaxWidth = 200;
                visualRow.Children.Add(fieldRow);
            }

            if (visualRow.Children.Count > 0)
                state.StructuredFieldsContainer.Children.Add(visualRow);
            return;
        }

        if (!IsAutoBoostActionType(actionType) &&
            !IsSpawnAssistActionType(actionType))
            return;

        if (!state.AdditionalFieldControls.TryGetValue("anim", out var animationEditor) || animationEditor.Parent is not Control animationRow)
            return;

        if (!state.AdditionalFieldsContainer.Children.Remove(animationRow))
            return;

        if (IsAutoBoostActionType(actionType) && animationRow is Grid compactAnimationRow)
        {
            compactAnimationRow.ColumnDefinitions = new ColumnDefinitions("Auto, 200");
            compactAnimationRow.HorizontalAlignment = HorizontalAlignment.Left;
            animationEditor.Width = 200;
            animationEditor.MinWidth = 200;
            animationEditor.MaxWidth = 200;
        }

        state.StructuredFieldsContainer.Children.Add(animationRow);
    }

    private static void ArrangeAutoBoostPostRateLayout(ProtoActionWidgetState state, string actionType)
    {
        if (!IsAutoBoostActionType(actionType))
            return;

        static bool ContainsLabel(Control control, string label)
        {
            if (control is TextBlock textBlock &&
                string.Equals(textBlock.Text, label, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            return control is Panel panel && panel.Children.Any(child => ContainsLabel(child, label));
        }

        var attachmentControl = state.AdditionalFieldsContainer.Children
            .FirstOrDefault(control =>
                control is Button button &&
                string.Equals(button.Content as string, "Add Model Attachment", StringComparison.OrdinalIgnoreCase) ||
                ContainsLabel(control, "Model Attachment:"));

        var visualOptionsRow = new WrapPanel
        {
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 2, 0, 2),
            HorizontalAlignment = HorizontalAlignment.Left
        };
        if (attachmentControl != null && state.AdditionalFieldsContainer.Children.Remove(attachmentControl))
        {
            attachmentControl.Margin = new Thickness(0, 0, 0, 0);
            visualOptionsRow.Children.Add(attachmentControl);
        }

        if (state.AutoBoostModifyProtoControl != null &&
            state.AdditionalFieldsContainer.Children.Remove(state.AutoBoostModifyProtoControl))
        {
            state.AutoBoostModifyProtoControl.Margin = new Thickness(
                visualOptionsRow.Children.Count > 0 ? 8 : 0,
                0,
                0,
                0);
            visualOptionsRow.Children.Add(state.AutoBoostModifyProtoControl);
        }

        if (visualOptionsRow.Children.Count > 0)
            state.StructuredFieldsContainer.Children.Add(visualOptionsRow);
    }

    private static void ArrangeLureLayout(ProtoActionWidgetState state, string actionType)
    {
        if (!IsLureActionType(actionType))
            return;

        var rateSection = state.AdditionalFieldsContainer.Children
            .FirstOrDefault(control => string.Equals(control.Tag as string, "lure.rate", StringComparison.Ordinal));
        if (rateSection != null && state.AdditionalFieldsContainer.Children.Remove(rateSection))
            state.StructuredFieldsContainer.Children.Add(rateSection);

        var animationRow = state.AdditionalFieldsContainer.Children
            .FirstOrDefault(control => string.Equals(control.Tag as string, "lure.animations", StringComparison.Ordinal));
        if (animationRow is Grid animationGrid)
        {
            animationGrid.ColumnDefinitions = new ColumnDefinitions("Auto, 200, Auto, 200, Auto, 200");
            animationGrid.HorizontalAlignment = HorizontalAlignment.Left;
            foreach (var editor in animationGrid.Children.Where(control => Grid.GetColumn(control) is 1 or 3 or 5))
            {
                editor.Width = 200;
                editor.MaxWidth = 200;
            }
        }
        if (animationRow != null && state.AdditionalFieldsContainer.Children.Remove(animationRow))
            state.StructuredFieldsContainer.Children.Add(animationRow);
    }

    private static void ArrangeTrailingImpactEffectLayout(ProtoActionWidgetState state, string actionType)
    {
        if (!IsReflectAttackActionType(actionType) &&
            !actionType.Equals("Hunting", StringComparison.OrdinalIgnoreCase))
            return;

        if (!state.AdditionalFieldControls.TryGetValue("impacteffect", out var impactEditor) ||
            impactEditor.Parent is not Grid impactRow ||
            !state.AdditionalFieldsContainer.Children.Remove(impactRow))
        {
            return;
        }

        impactRow.ColumnDefinitions = impactRow.ColumnDefinitions.Count >= 3
            ? new ColumnDefinitions("Auto, 200, Auto")
            : new ColumnDefinitions("Auto, 200");
        impactRow.HorizontalAlignment = HorizontalAlignment.Left;
        impactEditor.Width = 200;
        impactEditor.MinWidth = 200;
        impactEditor.MaxWidth = 200;
        state.StructuredFieldsContainer.Children.Add(impactRow);
    }

    private static void MoveLikeBonusAttachmentRowsBelowRate(ProtoActionWidgetState state, string actionType)
    {
        if (!IsLikeBonusActionType(actionType) && !IsConditionalShieldActionType(actionType))
            return;

        foreach (var source in new[] { state.AdditionalFieldsContainer, state.OptionalFieldsContainer })
        {
            static bool HasAttachmentLabel(Control control)
            {
                if (control is not Panel panel)
                    return false;

                return panel.Children.OfType<TextBlock>().Any(text => text.Text is "Model Attachment:" or "Target Attachment:") ||
                       panel.Children.OfType<Control>().Any(HasAttachmentLabel);
            }

            var attachmentRows = source.Children
                .OfType<Control>()
                .Where(HasAttachmentLabel)
                .ToList();

            foreach (var row in attachmentRows)
            {
                source.Children.Remove(row);
                state.StructuredFieldsContainer.Children.Add(row);
            }
        }

        var attachmentButtons = state.AdditionalFieldsContainer.Children
            .OfType<Button>()
            .Where(button => button.Content is string content &&
                             (content.Equals("Add Model Attachment", StringComparison.OrdinalIgnoreCase) ||
                              content.Equals("Add Target Attachment", StringComparison.OrdinalIgnoreCase)))
            .ToList();

        if (IsLikeBonusActionType(actionType) && attachmentButtons.Count == 2)
        {
            var sharedAttachmentButtons = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };
            foreach (var button in attachmentButtons)
            {
                state.AdditionalFieldsContainer.Children.Remove(button);
                button.Margin = new Thickness(sharedAttachmentButtons.Children.Count == 0 ? 0 : 8, 0, 0, 0);
                sharedAttachmentButtons.Children.Add(button);
            }
            state.StructuredFieldsContainer.Children.Add(sharedAttachmentButtons);
        }
        else
        {
            foreach (var button in attachmentButtons)
            {
                state.AdditionalFieldsContainer.Children.Remove(button);
                state.StructuredFieldsContainer.Children.Add(button);
            }
        }

        var sharedButtonsRow = state.AdditionalFieldsContainer.Children
            .OfType<WrapPanel>()
            .FirstOrDefault(panel => string.Equals(panel.Tag as string, "conditionalshield.attachment-buttons", StringComparison.Ordinal));
        if (sharedButtonsRow != null)
        {
            state.AdditionalFieldsContainer.Children.Remove(sharedButtonsRow);
            state.StructuredFieldsContainer.Children.Add(sharedButtonsRow);
        }
    }

