    private void RenderModifyGatherRateSection(
        ProtoActionWidgetState state,
        ProtoAction effectiveAction,
        string actionType)
    {
        // A metadata refresh can be triggered by an unrelated optional field. Prefer
        // the live rows so that opening Resource Sub Type never restores stale model data.
        var rateEntries = state.StructuredFieldRows.TryGetValue("rate", out var liveRateRows) && liveRateRows.Count > 0
            ? CollectProtoActionStructuredFieldEntries(state, "rate")
            : GetProtoActionStructuredFieldEntriesForEditor(effectiveAction, actionType, "rate");
        state.StructuredFieldRows["rate"] = [];
        var rateSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
        rateSection.Children.Add(new TextBlock { Text = "Rate", FontWeight = FontWeight.Bold });
        var ratesContainer = new WrapPanel { Orientation = Orientation.Horizontal };
        rateSection.Children.Add(ratesContainer);
        var refreshingChoices = false;
        Button? addRateButton = null;

        void RefreshResourceChoices()
        {
            if (refreshingChoices)
                return;

            refreshingChoices = true;
            try
            {
                foreach (var row in state.StructuredFieldRows["rate"])
                {
                    if (!row.AttributeEditors.TryGetValue("type", out var control) || control is not ComboBox combo)
                        continue;

                    var current = combo.SelectedItem?.ToString() ?? "";
                    var usedElsewhere = state.StructuredFieldRows["rate"]
                        .Where(other => !ReferenceEquals(other, row))
                        .Select(other => other.AttributeEditors.TryGetValue("type", out var otherControl) && otherControl is ComboBox otherCombo
                            ? otherCombo.SelectedItem?.ToString() ?? ""
                            : "")
                        .Where(value => !string.IsNullOrWhiteSpace(value))
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);
                    var choices = ProtoConstants.KnownResourceTypes
                        .Where(resource => resource.Equals(current, StringComparison.OrdinalIgnoreCase) || !usedElsewhere.Contains(resource))
                        .ToList();
                    combo.ItemsSource = choices;
                    combo.SelectedItem = choices.FirstOrDefault(resource => resource.Equals(current, StringComparison.OrdinalIgnoreCase));
                }

                if (addRateButton != null)
                {
                    var usedResources = state.StructuredFieldRows["rate"]
                        .Select(row => row.AttributeEditors.TryGetValue("type", out var control) && control is ComboBox combo
                            ? combo.SelectedItem?.ToString() ?? ""
                            : "")
                        .Where(value => !string.IsNullOrWhiteSpace(value))
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);
                    addRateButton.IsVisible = ProtoConstants.KnownResourceTypes.Any(resource => !usedResources.Contains(resource));
                }
            }
            finally
            {
                refreshingChoices = false;
            }
        }

        void AddRateRow(ProtoActionStructuredFieldEntry? initialEntry = null)
        {
            var initialType = initialEntry?.Attributes.TryGetValue("type", out var typeValue) == true ? typeValue : "";
            var isInheritedRateType = IsInheritedStructuredProtoActionEntry(
                state,
                "rate",
                "type",
                initialType);
            var typeCombo = new ComboBox
            {
                Width = 110,
                ItemsSource = ProtoConstants.KnownResourceTypes,
                SelectedItem = ProtoConstants.KnownResourceTypes.FirstOrDefault(resource =>
                    resource.Equals(initialType, StringComparison.OrdinalIgnoreCase)),
                IsEnabled = !_isReadOnly && !isInheritedRateType
            };
            typeCombo.SelectionChanged += async (_, _) =>
            {
                RefreshResourceChoices();
                if (!_isPopulating && await CheckStartLocalMod())
                    MarkDirty();
            };

            var valueTb = new TextBox
            {
                Text = initialEntry?.Value ?? "1.0",
                Width = 80,
                IsEnabled = !_isReadOnly
            };
            AttachProtoActionDecimalBehavior(valueTb);
            valueTb.TextChanged += async (_, _) =>
            {
                if (!_isPopulating && await CheckStartLocalMod())
                    MarkDirty();
            };

            var rowPanel = new RateEditor(
                typeCombo,
                valueTb,
                "Resource:",
                showRemoveButton: !_isReadOnly);

            var rowState = new ProtoActionStructuredFieldRowState
            {
                Tag = "rate",
                RowPanel = rowPanel,
                ValueTb = valueTb
            };
            rowState.AttributeEditors["type"] = typeCombo;
            state.StructuredFieldRows["rate"].Add(rowState);

            if (rowPanel.RemoveButton != null)
            {
                rowPanel.RemoveButton.Click += async (_, _) =>
                {
                    var selectedResource = typeCombo.SelectedItem?.ToString()?.Trim() ?? "";
                    if (await BlockInheritedStructuredProtoActionEntryRemovalAsync(
                            state,
                            "rate",
                            "type",
                            selectedResource,
                            "Rate type"))
                    {
                        return;
                    }

                    if (!await CheckStartLocalMod())
                        return;

                    ratesContainer.Children.Remove(rowPanel);
                    state.StructuredFieldRows["rate"].Remove(rowState);
                    RefreshResourceChoices();
                    MarkDirty();
                };
            }

            if (addRateButton != null)
                ratesContainer.Children.Remove(addRateButton);
            ratesContainer.Children.Add(rowPanel);
            if (addRateButton != null)
                ratesContainer.Children.Add(addRateButton);
            RefreshResourceChoices();
        }

        if (rateEntries.Count == 0 && !_isReadOnly)
            AddRateRow();
        else
            foreach (var entry in rateEntries)
                AddRateRow(entry);

        if (!_isReadOnly)
        {
            addRateButton = new Button
            {
                Content = "Add Rate",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left,
                VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(0, 0, 0, 4)
            };
            addRateButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;

                AddRateRow();
                MarkDirty();
            };
            ratesContainer.Children.Add(addRateButton);
            RefreshResourceChoices();
        }

        state.AdditionalFieldsContainer.Children.Add(rateSection);
    }

    private void RenderProtoActionAdditionalFields(
        ProtoActionWidgetState state,
        Dictionary<string, string> currentValues,
        Dictionary<string, List<ProtoActionStructuredFieldEntry>> currentStructuredValues)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        List<ProtoActionStructuredFieldEntry> GetCurrentStructuredEntries(string tag)
            => currentStructuredValues.TryGetValue(tag, out var editedEntries)
                ? editedEntries
                : GetProtoActionStructuredFieldEntriesForEditor(effectiveAction, actionType, tag);
        var isRampage = IsRampageActionType(actionType);
        var showOptionalModelAttachmentFields = ShouldShowOptionalModelAttachmentFields(state, actionType, effectiveAction, currentValues);
        var hasDamageAreaData = OptionalAbductDamageAreaTags.Any(tag =>
            state.ForcedVisibleFieldTags.Contains(tag) ||
            (currentValues.TryGetValue(tag, out var currentValue) && !string.IsNullOrWhiteSpace(currentValue)) ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
        var fieldTags = GetVisibleProtoActionSimpleFieldTags(state, effectiveAction, actionType)
            .Where(tag => !state.IsLinkedMaulAreaAction ||
                          (!tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
                           !tag.Equals("impacteffect", StringComparison.OrdinalIgnoreCase)))
            .Where(tag => state.IsNewCustomAction ||
                          !(IsGoreActionType(actionType) || IsThrowActionType(actionType)) ||
                          (!(tag.Equals("anim", StringComparison.OrdinalIgnoreCase) ||
                             tag.Equals("maxsizeclass", StringComparison.OrdinalIgnoreCase)) ||
                           !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag))))
            .Where(tag => !IsManagedAbductFieldTag(actionType, tag))
            .Where(tag => !(showOptionalModelAttachmentFields &&
                            OptionalModelAttachmentTags.Contains(tag, StringComparer.OrdinalIgnoreCase)))
            .Where(tag => !(hasDamageAreaData &&
                            OptionalAbductDamageAreaTags.Contains(tag, StringComparer.OrdinalIgnoreCase)))
            // Damage area and flags are rendered by the compact, action-aware damage-extra panel.
            .Where(tag => !OptionalAbductDamageAreaTags.Contains(tag, StringComparer.OrdinalIgnoreCase) ||
                          hasDamageAreaData)
            .Where(tag => !(isRampage &&
                            tag.Equals("projectile", StringComparison.OrdinalIgnoreCase) &&
                            state.CustomValues.GetValueOrDefault("rampage.projectile.hidden") == "1"))
            .ToList();
        var suggestedFieldTags = GetSuggestedProtoActionSimpleFieldTags(actionType);
        if (IsBuckAttackActionType(actionType))
        {
            foreach (var optionalTag in new[] { "maxsizeclass", "stunduration" })
            {
                if (fieldTags.Contains(optionalTag, StringComparer.OrdinalIgnoreCase) &&
                    !suggestedFieldTags.Contains(optionalTag, StringComparer.OrdinalIgnoreCase))
                {
                    suggestedFieldTags.Add(optionalTag);
                }
            }
        }
        if (isRampage)
        {
            foreach (var optionalTag in new[] { "maxsizeclass", "projectile" })
            {
                if (fieldTags.Contains(optionalTag, StringComparer.OrdinalIgnoreCase) &&
                    !suggestedFieldTags.Contains(optionalTag, StringComparer.OrdinalIgnoreCase))
                {
                    suggestedFieldTags.Add(optionalTag);
                }
            }
        }
        if (showOptionalModelAttachmentFields)
        {
            foreach (var tag in OptionalModelAttachmentTags)
            {
                if (!suggestedFieldTags.Contains(tag, StringComparer.OrdinalIgnoreCase))
                    suggestedFieldTags.Add(tag);
            }
        }
        var primaryFieldTags = fieldTags
            .Where(x => suggestedFieldTags.Contains(x, StringComparer.OrdinalIgnoreCase))
            .Where(x => !x.Equals("maxrange", StringComparison.OrdinalIgnoreCase) ||
                        state.CustomValues.GetValueOrDefault("additional.maxrange") != "1")
            .ToList();

        state.AdditionalFieldsContainer.Children.Clear();
        state.AdditionalFieldControls.Clear();
        state.LinearAreaAttackOptionsContainer.Children.Clear();
        state.LinearAreaAttackOptionsContainer.IsVisible = IsLinearAreaAttackActionType(actionType);
        state.AutoBoostModifyProtoControl = null;

        var hasManagedCustomLayout =
            actionType.Equals("ResourceDecay", StringComparison.OrdinalIgnoreCase) ||
            actionType.Equals("Bolster", StringComparison.OrdinalIgnoreCase) ||
            IsDevoteMinorActionType(actionType) ||
            IsSelfModifyActionType(actionType) ||
            IsLikeBonusActionType(actionType) ||
            IsReleaseSkyLanternActionType(actionType) ||
            IsHealActionType(actionType) ||
            IsConditionalShieldActionType(actionType) ||
            IsAutoRangedModifyActionType(actionType) ||
            IsAreaMutateActionType(actionType) ||
            IsAutoRangedAttachActionType(actionType) ||
            IsConditionalTransformActionType(actionType) ||
            IsDelayedTransformActionType(actionType) ||
            IsMaintainActionType(actionType) ||
            IsAutoGatherActionType(actionType) ||
            actionType.Equals("ModifyGather", StringComparison.OrdinalIgnoreCase) ||
            IsConvertActionType(actionType) ||
            IsSpawnActionType(actionType) ||
            IsTradeActionType(actionType) ||
            IsStealthActionType(actionType) ||
            IsAreaRestrictActionType(actionType) ||
            IsLureActionType(actionType) ||
            IsGatherActionType(actionType) ||
            IsIdleStatBonusActionType(actionType) ||
            IsDrainResurrectionActionType(actionType) ||
            IsDistanceModifyActionType(actionType) ||
            IsChainAttackActionType(actionType) ||
            IsAoeAttackActionType(actionType) ||
            IsLinearAreaAttackActionType(actionType) ||
            IsAbductActionType(actionType);

        if (primaryFieldTags.Count == 0 && _isReadOnly && !hasManagedCustomLayout && !IsAssistAttackActionType(actionType) && !IsAttackActionType(actionType))
            return;

        void RenderFieldRow(string tag)
        {
            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
            var fieldLabel = GetProtoActionFieldLabel(actionType, tag, definition.Label);
            var rawValue = currentValues.TryGetValue(tag, out var editedValue)
                ? editedValue
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
            var value = GetProtoActionDefaultSimpleValue(tag, rawValue);
            if (IsJumpAttackActionType(actionType) &&
                tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(value) &&
                state.IsNewCustomAction)
            {
                value = "Jump";
            }
            if (IsBuckAttackActionType(actionType) &&
                tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(value) &&
                state.IsNewCustomAction)
            {
                value = "Gore";
            }
            if (IsMaulActionType(actionType) &&
                !state.IsLinkedMaulAreaAction &&
                tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(value) &&
                state.IsNewCustomAction)
            {
                value = "Maul";
            }
            if (IsGoreActionType(actionType) &&
                tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(value) &&
                state.IsNewCustomAction)
            {
                value = "Gore";
            }
            if (IsThrowActionType(actionType) &&
                tag.Equals("anim", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(value) &&
                state.IsNewCustomAction)
            {
                value = "Pickup";
            }
            if (IsBuckAttackActionType(actionType) &&
                tag.Equals("stunduration", StringComparison.OrdinalIgnoreCase) &&
                string.IsNullOrWhiteSpace(value) &&
                state.IsNewCustomAction)
            {
                value = "0";
            }

            var rowGrid = new Grid
            {
                ColumnDefinitions = (actionType.Equals("BurstHeal", StringComparison.OrdinalIgnoreCase) ||
                                     actionType.Equals("SwitchTactic", StringComparison.OrdinalIgnoreCase) ||
                                     IsSpawnAssistActionType(actionType)) &&
                                    tag.Equals("anim", StringComparison.OrdinalIgnoreCase)
                    ? new ColumnDefinitions("Auto, 200")
                    : !_isReadOnly && CanRemoveProtoActionAdditionalField(actionType, tag)
                        ? new ColumnDefinitions("180, *, 32")
                        : new ColumnDefinitions("180, *"),
                Margin = new Thickness(0, 2, 0, 2),
                HorizontalAlignment = (actionType.Equals("SwitchTactic", StringComparison.OrdinalIgnoreCase) ||
                                      IsSpawnAssistActionType(actionType)) &&
                                      tag.Equals("anim", StringComparison.OrdinalIgnoreCase)
                    ? HorizontalAlignment.Left
                    : HorizontalAlignment.Stretch
            };

            rowGrid.Children.Add(new TextBlock
            {
                Text = fieldLabel + ":",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 4, 10, 4)
            });

            Control editor = definition.EditorKind switch
            {
                ProtoActionFieldEditorKind.Toggle => new CheckBox
                {
                    IsChecked = !string.IsNullOrWhiteSpace(value) && !value.Equals("0", StringComparison.OrdinalIgnoreCase),
                    IsEnabled = !_isReadOnly,
                    VerticalAlignment = VerticalAlignment.Center
                },
                _ => GetProtoActionValueSuggestions(tag) is List<string> suggestions
                    ? new AutoCompleteBox
                    {
                        Text = value,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = suggestions,
                        IsEnabled = !_isReadOnly
                    }
                    : new TextBox
                    {
                        Text = value,
                        IsEnabled = !_isReadOnly
                    }
            };

            if (editor is TextBox editorTextBox && definition.EditorKind == ProtoActionFieldEditorKind.Number)
                AttachProtoActionNumberBehavior(editorTextBox, tag);
            else if (AssetPathFieldTags.Contains(tag) && editor is TextBox assetTextBox)
            {
                EditorTextFieldStyle.ConfigureTextBox(assetTextBox);
            }
            else if (editor is TextBox textBox)
                EditorTextFieldStyle.ConfigureTextBox(textBox);
            if (editor is AutoCompleteBox editorAcb)
            {
                if (AssetPathFieldTags.Contains(tag))
                    EditorTextFieldStyle.ConfigureSelector(editorAcb);
                else
                    EditorTextFieldStyle.ConfigureSelector(editorAcb);
                ConfigureProtoActionValueAutoComplete(editorAcb, tag, value);
            }

            if (AssetPathFieldTags.Contains(tag))
                editor = CreateAssetPathEditor(tag, value, GetProtoActionValueSuggestions(tag) ?? []);
            ApplyProtoActionFieldWidth(editor, tag);

            if (!AssetPathFieldTags.Contains(tag) && editor is TextBox additionalTb)
            {
                additionalTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            MarkDirty();
                        }
                    }
                };
            }
            else if (!AssetPathFieldTags.Contains(tag) && editor is AutoCompleteBox additionalAcb)
            {
                additionalAcb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            MarkDirty();
                        }
                    }
                };
            }
            else if (editor is CheckBox additionalCb)
            {
                additionalCb.IsCheckedChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            if (IsKnownProtoActionFlagTag(tag))
                            {
                                if (additionalCb.IsChecked == true)
                                    state.SelectedFlagTags.Add(tag);
                                else
                                    state.SelectedFlagTags.Remove(tag);
                                RenderProtoActionFlags(state);
                            }
                            MarkDirty();
                        }
                    }
                };
            }

            Grid.SetColumn(editor, 1);
            rowGrid.Children.Add(editor);
            state.AdditionalFieldControls[tag] = editor;

            if (!_isReadOnly && CanRemoveProtoActionAdditionalField(actionType, tag))
            {
                var removeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(8, 0, 0, 0),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        if (tag.Equals("displaynameid", StringComparison.OrdinalIgnoreCase))
                        {
                            var stringId = state.CustomValues.GetValueOrDefault("displaynameid.stringid") ?? "";
                            if (stringId.StartsWith("STR_ACTION_", StringComparison.OrdinalIgnoreCase))
                                _pendingUnitStringRemovals.Add(stringId);
                        }
                        state.ForcedVisibleFieldTags.Remove(tag);
                        if (isRampage && tag.Equals("projectile", StringComparison.OrdinalIgnoreCase))
                            state.CustomValues["rampage.projectile.hidden"] = "1";
                        state.AdditionalFieldControls.Remove(tag);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    }
                };
                Grid.SetColumn(removeButton, 2);
                rowGrid.Children.Add(removeButton);
            }

            state.AdditionalFieldsContainer.Children.Add(rowGrid);
        }

        void RenderWaterTornadoSpreadRow()
        {
            var row = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };

            void AddSpreadField(string tag, string label, bool addLeadingGap)
            {
                var rawValue = currentValues.TryGetValue(tag, out var editedValue)
                    ? editedValue
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                var editor = new TextBox
                {
                    Text = rawValue,
                    Width = 90,
                    IsEnabled = !_isReadOnly
                };
                AttachProtoActionDecimalBehavior(editor);
                editor.TextChanged += async (_, _) =>
                {
                    if (!_isPopulating && await CheckStartLocalMod())
                        MarkDirty();
                };
                row.Children.Add(new TextBlock
                {
                    Text = label + ":",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(addLeadingGap ? 16 : 0, 4, 8, 4)
                });
                row.Children.Add(editor);
                state.AdditionalFieldControls[tag] = editor;
            }

            AddSpreadField("maxspread", "Max Spread", false);
            AddSpreadField("spreadfactor", "Spread Factor", true);
            state.AdditionalFieldsContainer.Children.Add(row);
        }

        void RenderRampageTimingRow()
        {
            primaryFieldTags.RemoveAll(tag => tag.Equals("autocastdistance", StringComparison.OrdinalIgnoreCase) ||
                                              tag.Equals("modifyduration", StringComparison.OrdinalIgnoreCase));

            Control CreateTimingEditor(string tag)
            {
                var rawValue = currentValues.TryGetValue(tag, out var editedValue)
                    ? editedValue
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                var editor = new TextBox { Text = GetProtoActionDefaultSimpleValue(tag, rawValue), IsEnabled = !_isReadOnly, Width = 120 };
                AttachProtoActionDecimalBehavior(editor);
                editor.TextChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;
                    if (await CheckStartLocalMod())
                        MarkDirty();
                };
                ApplyProtoActionFieldWidth(editor, tag);
                state.AdditionalFieldControls[tag] = editor;
                return editor;
            }

            var timingRow = new WrapPanel
            {
                Tag = "rampage.timing",
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };
            timingRow.Children.Add(new TextBlock { Text = "Auto Cast Distance:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
            timingRow.Children.Add(CreateTimingEditor("autocastdistance"));
            timingRow.Children.Add(new TextBlock { Text = "Duration (ms):", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(18, 4, 8, 4) });
            timingRow.Children.Add(CreateTimingEditor("modifyduration"));
            state.AdditionalFieldsContainer.Children.Add(timingRow);
        }

        if (IsTeleportAttackActionType(actionType))
        {
            primaryFieldTags.RemoveAll(tag => tag.Equals("anim", StringComparison.OrdinalIgnoreCase) ||
                                              tag.Equals("reloadanim", StringComparison.OrdinalIgnoreCase) ||
                                              tag.Equals("impacteffect", StringComparison.OrdinalIgnoreCase));
        }
        else if (IsAttackActionType(actionType))
        {
            primaryFieldTags.RemoveAll(tag => tag.Equals("anim", StringComparison.OrdinalIgnoreCase) ||
                                              tag.Equals("impacteffect", StringComparison.OrdinalIgnoreCase));
        }

        void RenderThrowAdditionalInfo()
        {
            var values = ThrowAdditionalInfoTags.ToDictionary(
                tag => tag,
                tag => currentValues.TryGetValue(tag, out var currentValue)
                    ? currentValue
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag),
                StringComparer.OrdinalIgnoreCase);
            var shouldShow = ThrowAdditionalInfoTags.Any(tag =>
                state.ForcedVisibleFieldTags.Contains(tag) || !string.IsNullOrWhiteSpace(values[tag]));
            var maxSizeClass = currentValues.TryGetValue("maxsizeclass", out var currentMaxSizeClass)
                ? currentMaxSizeClass
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "maxsizeclass");
            var shouldShowMaxSizeClass = state.ForcedVisibleFieldTags.Contains("maxsizeclass") ||
                                         !string.IsNullOrWhiteSpace(maxSizeClass);
            var addButtonsRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };

            if (!shouldShow && !_isReadOnly)
            {
                var addButton = new Button
                {
                    Content = "Additional Throw Information",
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left,
                    Margin = new Thickness(0, 0, 8, 0)
                };
                addButton.Click += async (_, _) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;
                    foreach (var tag in ThrowAdditionalInfoTags)
                        state.ForcedVisibleFieldTags.Add(tag);
                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                };
                addButtonsRow.Children.Add(addButton);
            }

            if (!shouldShowMaxSizeClass && !_isReadOnly)
            {
                var addMaxSizeClassButton = new Button
                {
                    Content = "Max Size Class",
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                addMaxSizeClassButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    state.ForcedVisibleFieldTags.Add("maxsizeclass");
                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                };
                addButtonsRow.Children.Add(addMaxSizeClassButton);
            }

            if (addButtonsRow.Children.Count > 0)
                state.AdditionalFieldsContainer.Children.Add(addButtonsRow);

            if (shouldShow)
            {
                var row = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 90, Auto, 90, Auto, 90, Auto, 90, Auto"),
                    Margin = new Thickness(0, 2, 0, 2)
                };
                var labels = new[]
                {
                    ("throwdistancemin", "Distance Min"),
                    ("throwdistancemax", "Max"),
                    ("throwmaxheight", "Height Max"),
                    ("throwvelocity", "Velocity"),
                };
                for (var index = 0; index < labels.Length; index++)
                {
                    var (tag, label) = labels[index];
                    var labelControl = new TextBlock
                    {
                        Text = label + ":",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(index == 0 ? 0 : 10, 0, 6, 0)
                    };
                    Grid.SetColumn(labelControl, index * 2);
                    row.Children.Add(labelControl);
                    var editor = new TextBox { Text = values[tag], IsEnabled = !_isReadOnly };
                    AttachProtoActionDecimalBehavior(editor);
                    editor.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };
                    Grid.SetColumn(editor, index * 2 + 1);
                    row.Children.Add(editor);
                    state.AdditionalFieldControls[tag] = editor;
                }
                if (!_isReadOnly)
                {
                    var removeButton = new Button { Classes = { "remove-button" } };
                    removeButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;
                        foreach (var tag in ThrowAdditionalInfoTags)
                        {
                            state.ForcedVisibleFieldTags.Remove(tag);
                            state.AdditionalFieldControls.Remove(tag);
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                        }
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    Grid.SetColumn(removeButton, 8);
                    row.Children.Add(removeButton);
                }
                state.AdditionalFieldsContainer.Children.Add(row);
            }

            if (shouldShowMaxSizeClass)
            {
                var maxSizeClassRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 90, Auto"),
                    HorizontalAlignment = HorizontalAlignment.Left,
                    Margin = new Thickness(0, 2, 0, 2)
                };
                maxSizeClassRow.Children.Add(new TextBlock
                {
                    Text = "Max Size Class:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                var maxSizeClassEditor = new TextBox
                {
                    Text = maxSizeClass,
                    Width = 90,
                    IsEnabled = !_isReadOnly
                };
                AttachProtoActionIntegerBehavior(maxSizeClassEditor);
                maxSizeClassEditor.TextChanged += async (_, _) =>
                {
                    if (!_isPopulating && await CheckStartLocalMod())
                        MarkDirty();
                };
                Grid.SetColumn(maxSizeClassEditor, 1);
                maxSizeClassRow.Children.Add(maxSizeClassEditor);
                state.AdditionalFieldControls["maxsizeclass"] = maxSizeClassEditor;
                if (!_isReadOnly)
                {
                    var removeButton = new Button
                    {
                        Classes = { "remove-button" },
                        Margin = new Thickness(2, 0, 0, 0)
                    };
                    removeButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;
                        state.ForcedVisibleFieldTags.Remove("maxsizeclass");
                        state.AdditionalFieldControls.Remove("maxsizeclass");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "maxsizeclass", "");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    Grid.SetColumn(removeButton, 2);
                    maxSizeClassRow.Children.Add(removeButton);
                }
                state.AdditionalFieldsContainer.Children.Add(maxSizeClassRow);
            }
        }

        if (IsGoreActionType(actionType) || IsThrowActionType(actionType))
            RenderThrowAdditionalInfo();

        if (isRampage)
            RenderRampageTimingRow();

        var coreParent = state.CoreFieldsGrid.Parent as Panel;
        foreach (var existingAssistNote in (coreParent ?? state.Container).Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "assistattack.note", StringComparison.Ordinal))
                     .ToList())
        {
            (coreParent ?? state.Container).Children.Remove(existingAssistNote);
        }
        foreach (var existingAssistOptions in (coreParent ?? state.Container).Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "assistattack.options", StringComparison.Ordinal))
                     .ToList())
        {
            (coreParent ?? state.Container).Children.Remove(existingAssistOptions);
        }
        if (IsAssistAttackActionType(actionType))
        {
            var note = new TextBlock
            {
                Tag = "assistattack.note",
                Text = "Work only when defined as spawned assist unit of a SpawnAssistUnit action",
                FontStyle = FontStyle.Italic,
                Opacity = 0.78,
                Margin = new Thickness(0, 0, 0, 4)
            };
            var noteParent = coreParent ?? state.Container;
            var coreIndex = noteParent.Children.IndexOf(state.CoreFieldsGrid);
            noteParent.Children.Insert(Math.Max(0, coreIndex), note);

            foreach (var existingOption in state.CoreFieldsGrid.Children
                         .OfType<Control>()
                         .Where(control => (control.Tag as string)?.StartsWith("assistattack.option.", StringComparison.Ordinal) == true)
                         .ToList())
            {
                state.CoreFieldsGrid.Children.Remove(existingOption);
            }

            // Keep the shared range row untouched: when ROF and Min Range are absent,
            // its generic layout places Max Range in the first available position.
            // Assist-specific values belong together on the following row.
            var optionsRow = new WrapPanel
            {
                Tag = "assistattack.options",
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 4)
            };
            void AddAssistOption(string tag, string label)
            {
                var rawValue = currentValues.TryGetValue(tag, out var editedValue)
                    ? editedValue
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                var visible = state.ForcedVisibleFieldTags.Contains(tag) || !string.IsNullOrWhiteSpace(rawValue);
                if (!visible)
                {
                    var addButton = new Button
                    {
                        Tag = "assistattack.option." + tag,
                        Content = label,
                        Classes = { "add-component" },
                        Margin = new Thickness(optionsRow.Children.Count == 0 ? 0 : 8, 0, 0, 0)
                    };
                    addButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Add(tag);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    optionsRow.Children.Add(addButton);
                    return;
                }

                var fieldGroup = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 0,
                    Margin = new Thickness(optionsRow.Children.Count == 0 ? 0 : 8, 0, 0, 0)
                };
                var labelControl = new TextBlock
                {
                    Tag = "assistattack.option." + tag,
                    Text = label + ":",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 0, 8, 0)
                };
                fieldGroup.Children.Add(labelControl);
                var editor = new TextBox { Tag = "assistattack.option." + tag, Text = rawValue, IsEnabled = !_isReadOnly, Width = 90 };
                AttachProtoActionDecimalBehavior(editor);
                editor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                state.AdditionalFieldControls[tag] = editor;
                fieldGroup.Children.Add(editor);
                if (!_isReadOnly)
                {
                    var removeButton = new Button { Tag = "assistattack.option." + tag, Classes = { "remove-button" }, Margin = new Thickness(2, 0, 0, 0) };
                    removeButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Remove(tag);
                        editor.Text = "";
                        state.AdditionalFieldControls.Remove(tag);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    fieldGroup.Children.Add(removeButton);
                }
                optionsRow.Children.Add(fieldGroup);
            }
            AddAssistOption("modifytargetlimit", "Max Targets");
            AddAssistOption("modifymultiplier", "Lifesteal");
            noteParent.Children.Insert(Math.Min(noteParent.Children.Count, coreIndex + 2), optionsRow);
        }
        else if (IsSpawnAssistActionType(actionType))
        {
            primaryFieldTags.RemoveAll(tag => tag.Equals("projectile", StringComparison.OrdinalIgnoreCase));
            var projectileRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 0, 0, 6) };
            projectileRow.Children.Add(new TextBlock { Text = "Spawned Assist Unit:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
            var projectileValue = currentValues.TryGetValue("projectile", out var editedProjectile)
                ? editedProjectile
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "projectile");
            var projectileEditor = new AutoCompleteBox
            {
                Text = projectileValue,
                FilterMode = AutoCompleteFilterMode.Contains,
                IsEnabled = !_isReadOnly,
                Width = 200
            };
            ConfigureStrictSuggestionAutoComplete(projectileEditor, GetAvailableTrainUnitNames(), projectileValue);
            projectileEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
            state.AdditionalFieldControls["projectile"] = projectileEditor;
            projectileRow.Children.Add(projectileEditor);
            projectileRow.Children.Add(new TextBlock
            {
                Text = "Requires the spawned assist unit to have an AssistAttack",
                FontStyle = FontStyle.Italic,
                Opacity = 0.78,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(14, 4, 0, 4)
            });
            state.AdditionalFieldsContainer.Children.Add(projectileRow);
        }

        foreach (var existingAttackMode in (coreParent ?? state.Container).Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "attack.mode", StringComparison.Ordinal))
                     .ToList())
        {
            (coreParent ?? state.Container).Children.Remove(existingAttackMode);
        }
        if (IsAttackActionType(actionType))
        {
            var attackModes = new[] { "Hand Attack", "Ranged Attack", "Self-Destruct Attack", "Birth Attack" };
            var savedMode = GetAttackMode(state);
            if (!string.IsNullOrWhiteSpace(savedMode))
                state.CustomValues["attack.mode"] = savedMode;
            var availableAttackModes = attackModes
                .Where(mode =>
                    !mode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) &&
                    !mode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase) ||
                    mode.Equals(savedMode, StringComparison.OrdinalIgnoreCase) ||
                    !IsAttackModeClaimedByAnother(state, mode))
                .ToList();

            var modeRow = new WrapPanel
            {
                Tag = "attack.mode",
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 0, 0, 4)
            };
            modeRow.Children.Add(new TextBlock { Text = "Attack Mode:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
            var modeCombo = new ComboBox
            {
                ItemsSource = availableAttackModes,
                SelectedItem = availableAttackModes.Contains(savedMode, StringComparer.OrdinalIgnoreCase) ? savedMode : null,
                IsEnabled = !_isReadOnly,
                Width = 190
            };
            RegisterProtoActionFlagSourceControl(state, modeCombo, "handlogic", "rangedlogic");
            modeCombo.SelectionChanged += async (_, _) =>
            {
                if (_isPopulating || !await CheckStartLocalMod() || modeCombo.SelectedItem is not string selectedMode)
                    return;

                var previousMode = GetAttackMode(state);
                if ((selectedMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) ||
                     selectedMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase)) &&
                    IsAttackModeClaimedByAnother(state, selectedMode))
                {
                    modeCombo.SelectedItem = previousMode;
                    return;
                }

                var wasRangedAttack = previousMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase);
                var usesCombatMode = selectedMode.Equals("Hand Attack", StringComparison.OrdinalIgnoreCase) ||
                                     selectedMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase);
                var isRangedAttack = selectedMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase);

                void ClearAttackFields(IEnumerable<string> tags)
                {
                    foreach (var tag in tags)
                    {
                        state.ForcedVisibleFieldTags.Remove(tag);
                        state.AdditionalFieldControls.Remove(tag);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                    }
                }

                if (wasRangedAttack && !isRangedAttack)
                {
                    ClearAttackFields(["projectile", "numberprojectiles", "displayednumberprojectiles", "launchpoint", "accuracy", "trackrating", "maxspread", "spreadfactor", "numberbounces", "projectilechainbouncerange", "projectilechainbouncereduction"]);
                    state.Model.SourceElement?.SetAttributeValue("launchpoint", null);
                    GetProtoActionAdditionalElement(state.Model, "projectile")?.SetAttributeValue("launchpoint", null);
                    foreach (var flag in new[] { "volleymode", "instantballistics", "perfectaccuracy", "homingballistics", "passthrough", "passthroughbuildings", "projectilechainbounce" })
                        state.SelectedFlagTags.Remove(flag);
                }

                if (!usesCombatMode)
                {
                    ClearAttackFields(["anim", "minrange"]);
                    state.JumpAttackMinRangeTb?.Clear();
                    state.RofTb.Clear();
                    state.MaxRangeTb.Clear();
                    state.SelectedFlagTags.Remove("defaultattack");
                }

                if (selectedMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase))
                    ClearAttackFields(["castpower", "castpowertargettype"]);

                var usesDefaultDamageArea = selectedMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) ||
                                          selectedMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase);
                var previouslyUsedDefaultDamageArea = previousMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) ||
                                                    previousMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase);
                if (usesDefaultDamageArea && !previouslyUsedDefaultDamageArea)
                {
                    state.ForcedVisibleFieldTags.Add("damagearea");
                    state.ForcedVisibleFieldTags.Add("damageflags");
                    state.ForcedVisibleFieldTags.Add("areasortmode");
                    InitializeDamageAreaDefaults(state, requireAreaSortMode: true);
                }
                if (!usesDefaultDamageArea && previouslyUsedDefaultDamageArea)
                {
                    ClearAttackFields(["areasortmode"]);
                }

                state.CustomValues["attack.mode"] = selectedMode;
                if (previousMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) &&
                    !selectedMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase))
                    SetCurrentUnitActionReference("selfdestructprotoaction", "");
                if (previousMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase) &&
                    !selectedMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase))
                    SetCurrentUnitActionReference("birthprotoaction", "");
                if (selectedMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase))
                    SetCurrentUnitActionReference("selfdestructprotoaction", state.NameAcb.Text?.Trim() ?? "");
                if (selectedMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase))
                    SetCurrentUnitActionReference("birthprotoaction", state.NameAcb.Text?.Trim() ?? "");
                RefreshExclusiveAttackActionReferences();
                RefreshAllProtoActionNameValidation();
                state.SelectedFlagTags.Remove("handlogic");
                state.SelectedFlagTags.Remove("rangedlogic");
                if (selectedMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) ||
                    selectedMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase))
                {
                    state.SelectedFlagTags.Remove("defaultattack");
                }
                if (selectedMode.Equals("Hand Attack", StringComparison.OrdinalIgnoreCase))
                    state.SelectedFlagTags.Add("handlogic");
                else if (selectedMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase))
                    state.SelectedFlagTags.Add("rangedlogic");
                RenderProtoActionFlags(state);
                RefreshProtoActionMetadataPanels(state);
                foreach (var otherState in _protoActionWidgets.Where(other => !ReferenceEquals(other, state)))
                {
                    var otherType = ResolveProtoActionType(otherState.NameAcb.Text?.Trim() ?? "", otherState.TypeAcb.Text?.Trim() ?? "");
                    if (IsAttackActionType(otherType))
                        RefreshProtoActionMetadataPanels(otherState);
                }
                MarkDirty();
            };
            modeRow.Children.Add(modeCombo);
            var usesCombatMode = savedMode.Equals("Hand Attack", StringComparison.OrdinalIgnoreCase) ||
                                 savedMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase);
            if (usesCombatMode)
            {
                var defaultAttackCheckBox = new CheckBox
                {
                    Content = "Default Attack",
                    IsChecked = state.SelectedFlagTags.Contains("defaultattack"),
                    IsEnabled = !_isReadOnly,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(18, 4, 0, 4)
                };
                state.CustomFlagControls["defaultattack"] = defaultAttackCheckBox;
                RegisterProtoActionFlagSourceControl(state, defaultAttackCheckBox, "defaultattack");
                defaultAttackCheckBox.IsCheckedChanged += async (_, _) =>
                {
                    if (_isPopulating || !await CheckStartLocalMod())
                        return;

                    if (defaultAttackCheckBox.IsChecked == true)
                        state.SelectedFlagTags.Add("defaultattack");
                    else
                        state.SelectedFlagTags.Remove("defaultattack");
                    RenderProtoActionFlags(state);
                    MarkDirty();
                };
                modeRow.Children.Add(defaultAttackCheckBox);
            }
            var modeParent = coreParent ?? state.Container;
            var coreIndex = modeParent.Children.IndexOf(state.CoreFieldsGrid);
            modeParent.Children.Insert(Math.Max(0, coreIndex), modeRow);

            if (savedMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase))
            {
                string GetAttackFieldValue(string tag)
                {
                    if (currentValues.TryGetValue(tag, out var editedValue) &&
                        !string.IsNullOrWhiteSpace(editedValue))
                        return editedValue;

                    if (tag.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
                    {
                        var protoValue = GetExplicitProtoActionLaunchPointValue(state.Model);
                        if (!string.IsNullOrWhiteSpace(protoValue))
                            return protoValue;

                        return GetProtoActionLaunchPointValue(effectiveAction);
                    }

                    var value = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                    return value;
                }

                async Task RemoveAttackRangedFieldAsync(string tag)
                {
                    if (!await CheckStartLocalMod())
                        return;

                    state.ForcedVisibleFieldTags.Remove(tag);
                    state.AdditionalFieldControls.Remove(tag);
                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                    if (tag.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
                    {
                        state.Model.SourceElement?.SetAttributeValue("launchpoint", null);
                        GetProtoActionAdditionalElement(state.Model, "projectile")?.SetAttributeValue("launchpoint", null);
                    }
                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                }

                Control CreateRangedAttackField(string tag, string value)
                {
                    var editor = new TextBox
                    {
                        Text = value,
                        IsEnabled = !_isReadOnly,
                        Width = 90,
                        Height = 32,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    if (ProtoActionMetadataCatalog.GetFieldDefinition(tag).EditorKind == ProtoActionFieldEditorKind.Number)
                        AttachProtoActionDecimalBehavior(editor);
                    else
                        EditorTextFieldStyle.ConfigureTextBox(editor);
                    ApplyProtoActionFieldWidth(editor, tag);
                    editor.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating && await CheckStartLocalMod())
                            MarkDirty();
                    };
                    state.AdditionalFieldControls[tag] = editor;
                    return editor;
                }

                bool IsRangedPropertyVisible(string tag)
                    => state.ForcedVisibleFieldTags.Contains(tag) || !string.IsNullOrWhiteSpace(GetAttackFieldValue(tag));

                void AddRangedProperty(Panel row, string tag, string label, bool renderButtons)
                {
                    var value = GetAttackFieldValue(tag);
                    var visible = IsRangedPropertyVisible(tag);
                    if (visible && renderButtons)
                        return;
                    if (!visible)
                    {
                        if (renderButtons && !_isReadOnly)
                        {
                            var addButton = new Button
                            {
                                Content = label,
                                Classes = { "add-component" },
                                Margin = new Thickness(10, 0, 0, 0)
                            };
                            addButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;
                                state.ForcedVisibleFieldTags.Add(tag);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            row.Children.Add(addButton);
                        }
                        return;
                    }

                    row.Children.Add(new TextBlock
                    {
                        Text = label + ":",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(12, 4, 8, 4)
                    });
                    row.Children.Add(CreateRangedAttackField(tag, value));
                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(5, 0, 0, 0) };
                        removeButton.Click += async (_, _) => await RemoveAttackRangedFieldAsync(tag);
                        row.Children.Add(removeButton);
                    }
                }

                var projectileRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2)
                };
                projectileRow.Children.Add(new TextBlock
                {
                    Text = "Projectile:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                var projectileValue = GetAttackFieldValue("projectile");
                var projectileEditor = new AutoCompleteBox
                {
                    Text = projectileValue,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly,
                    Width = 200
                };
                ConfigureStrictSuggestionAutoComplete(projectileEditor, GetAvailableTrainUnitNames(), projectileValue);
                projectileEditor.TextChanged += async (_, _) =>
                {
                    if (!_isPopulating && await CheckStartLocalMod())
                        MarkDirty();
                };
                state.AdditionalFieldControls["projectile"] = projectileEditor;
                projectileRow.Children.Add(projectileEditor);
                AddRangedProperty(projectileRow, "numberprojectiles", "Number Projectiles", renderButtons: false);
                var hasNumberProjectiles = IsRangedPropertyVisible("numberprojectiles");
                var hasDisplayedNumberProjectiles = IsRangedPropertyVisible("displayednumberprojectiles");
                if (hasNumberProjectiles || hasDisplayedNumberProjectiles)
                    AddRangedProperty(projectileRow, "displayednumberprojectiles", "Displayed Number", renderButtons: false);
                AddRangedProperty(projectileRow, "launchpoint", "Launch Point", renderButtons: false);
                if (hasNumberProjectiles)
                {
                    var volleyModeCheckBox = new CheckBox
                    {
                        Content = "Volley Mode",
                        IsChecked = state.SelectedFlagTags.Contains("volleymode"),
                        IsEnabled = !_isReadOnly,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(12, 4, 0, 4)
                    };
                    state.CustomFlagControls["volleymode"] = volleyModeCheckBox;
                    RegisterProtoActionFlagSourceControl(state, volleyModeCheckBox, "volleymode");
                    volleyModeCheckBox.IsCheckedChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod())
                            return;

                        if (volleyModeCheckBox.IsChecked == true)
                            state.SelectedFlagTags.Add("volleymode");
                        else
                            state.SelectedFlagTags.Remove("volleymode");
                        RenderProtoActionFlags(state);
                        MarkDirty();
                    };
                    projectileRow.Children.Add(volleyModeCheckBox);
                }
                if (hasNumberProjectiles)
                    AddRangedProperty(projectileRow, "displayednumberprojectiles", "Displayed Number", renderButtons: true);
                AddRangedProperty(projectileRow, "numberprojectiles", "Number Projectiles", renderButtons: true);
                AddRangedProperty(projectileRow, "launchpoint", "Launch Point", renderButtons: true);

                var bounceTags = new[] { "numberbounces", "projectilechainbouncerange", "projectilechainbouncereduction" };
                var hasBounce = state.SelectedFlagTags.Contains("projectilechainbounce") ||
                                bounceTags.Any(IsRangedPropertyVisible);
                if (!hasBounce && !_isReadOnly)
                {
                    var addBounceButton = new Button
                    {
                        Content = "Bounce",
                        Classes = { "add-component" },
                        Margin = new Thickness(10, 0, 0, 0)
                    };
                    addBounceButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.SelectedFlagTags.Add("projectilechainbounce");
                        RenderProtoActionFlags(state);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    projectileRow.Children.Add(addBounceButton);
                }
                state.AdditionalFieldsContainer.Children.Add(projectileRow);

                var spreadRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2)
                };
                foreach (var (tag, label) in new[] { ("accuracy", "Accuracy"), ("trackrating", "Track Rating"), ("maxspread", "Max Spread"), ("spreadfactor", "Spread Factor") })
                    AddRangedProperty(spreadRow, tag, label, renderButtons: false);
                foreach (var (tag, label) in new[] { ("accuracy", "Accuracy"), ("trackrating", "Track Rating"), ("maxspread", "Max Spread"), ("spreadfactor", "Spread Factor") })
                    AddRangedProperty(spreadRow, tag, label, renderButtons: true);
                state.AdditionalFieldsContainer.Children.Add(spreadRow);

                if (hasBounce)
                {
                    var bounceRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2)
                    };
                    bounceRow.Children.Add(new TextBlock
                    {
                        Text = "Bounce:",
                        FontWeight = FontWeight.SemiBold,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 10, 4)
                    });
                    foreach (var (tag, label) in new[]
                    {
                        ("numberbounces", "Number"),
                        ("projectilechainbouncerange", "Range"),
                        ("projectilechainbouncereduction", "Damage Reduction")
                    })
                    {
                        var value = GetAttackFieldValue(tag);
                        if (tag.Equals("projectilechainbouncereduction", StringComparison.OrdinalIgnoreCase) &&
                            string.IsNullOrWhiteSpace(value))
                        {
                            value = "0";
                        }

                        bounceRow.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(10, 4, 8, 4)
                        });
                        bounceRow.Children.Add(CreateRangedAttackField(tag, value));
                    }

                    if (!_isReadOnly)
                    {
                        var removeBounceButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(8, 0, 0, 0)
                        };
                        removeBounceButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.SelectedFlagTags.Remove("projectilechainbounce");
                            foreach (var tag in bounceTags)
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            }
                            RenderProtoActionFlags(state);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        bounceRow.Children.Add(removeBounceButton);
                    }

                    var spreadRowIndex = state.AdditionalFieldsContainer.Children.IndexOf(spreadRow);
                    state.AdditionalFieldsContainer.Children.Insert(Math.Max(0, spreadRowIndex), bounceRow);
                }

                var ballisticFlagOptions = new (string Tag, string Label)[]
                {
                    ("instantballistics", "Instant Ballistics"),
                    ("perfectaccuracy", "Perfect Accuracy"),
                    ("homingballistics", "Homing Ballistics"),
                    ("passthrough", "Pass Through"),
                    ("passthroughbuildings", "Pass Through Buildings")
                };
                var ballisticFlagsRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2)
                };
                ballisticFlagsRow.Children.Add(new TextBlock
                {
                    Text = "Ranged Flags:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                if (!_isReadOnly)
                {
                    var ballisticFlagPicker = new ComboBox
                    {
                        ItemsSource = ballisticFlagOptions
                            .Where(option => !state.SelectedFlagTags.Contains(option.Tag))
                            .Select(option => option.Label)
                            .ToList(),
                        Width = 190
                    };
                    ballisticFlagPicker.SelectionChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod() || ballisticFlagPicker.SelectedItem is not string selectedLabel)
                            return;

                        var selectedFlag = ballisticFlagOptions
                            .FirstOrDefault(option => option.Label.Equals(selectedLabel, StringComparison.OrdinalIgnoreCase)).Tag;
                        if (string.IsNullOrWhiteSpace(selectedFlag))
                            return;

                        state.SelectedFlagTags.Add(selectedFlag);
                        RenderProtoActionFlags(state);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    ballisticFlagsRow.Children.Add(ballisticFlagPicker);
                }
                foreach (var (flagTag, label) in ballisticFlagOptions.Where(option => state.SelectedFlagTags.Contains(option.Tag)))
                {
                    var tacticsFlagValue = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsFlagAction)
                        ? GetProtoActionSimpleSourceValue(tacticsFlagAction, flagTag)
                        : "";
                    var protoFlagValue = GetProtoActionSimpleSourceValue(state.Model, flagTag);
                    var flagSource = GetProtoActionValueSource("1", protoFlagValue, tacticsFlagValue);
                    var flagChip = CreateChip(label, async () =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.SelectedFlagTags.Remove(flagTag);
                        RenderProtoActionFlags(state);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    }, flagSource, tacticsFlagValue);
                    ballisticFlagsRow.Children.Add(flagChip);
                }
                state.AdditionalFieldsContainer.Children.Add(ballisticFlagsRow);
            }

            var attackAnimationValue = currentValues.TryGetValue("anim", out var editedAnimation)
                ? editedAnimation
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "anim");
            var attackImpactValue = currentValues.TryGetValue("impacteffect", out var editedImpact) &&
                                    !string.IsNullOrWhiteSpace(editedImpact)
                ? editedImpact
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "impacteffect");
            if (usesCombatMode || !_isReadOnly || !string.IsNullOrWhiteSpace(attackImpactValue))
            {
                state.AdditionalFieldsContainer.Children.Add(CreateCombatVisualFieldsRow(
                    state,
                    attackAnimationValue,
                    attackImpactValue,
                    showAnimation: usesCombatMode,
                    showImpact: !_isReadOnly || !string.IsNullOrWhiteSpace(attackImpactValue)));
            }

            var hasThrowOnHitEffect = state.OnHitEffectRows.Count > 0
                ? state.OnHitEffectRows.Any(row => string.Equals(row.TypeCb.Text?.Trim(), "Throw", StringComparison.OrdinalIgnoreCase))
                : GetProtoActionOnHitEffectElements(effectiveAction)
                    .Any(effect => string.Equals((string?)effect.Attribute("type"), "Throw", StringComparison.OrdinalIgnoreCase));
            if (hasThrowOnHitEffect)
            {
                var throwTags = new[] { "throwdistancemax", "throwdistancemin", "throwmaxheight", "throwvelocity", "maxsizeclass" };
                var hasThrowConfiguration = state.SelectedFlagTags.Contains("throw") ||
                                            throwTags.Any(tag =>
                                                currentValues.TryGetValue(tag, out var currentValue)
                                                    ? !string.IsNullOrWhiteSpace(currentValue)
                                                    : !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
                if (!hasThrowConfiguration && !_isReadOnly)
                {
                    var addThrowButton = new Button
                    {
                        Content = "Throw",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 4, 0, 2)
                    };
                    addThrowButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.SelectedFlagTags.Add("throw");
                        RenderProtoActionFlags(state);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    state.AdditionalFieldsContainer.Children.Add(addThrowButton);
                }
                else if (hasThrowConfiguration)
                {
                    var throwRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 4, 0, 2)
                    };
                    throwRow.Children.Add(new TextBlock
                    {
                        Text = "Throw:",
                        FontWeight = FontWeight.SemiBold,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 10, 4)
                    });

                    foreach (var (tag, label) in new[]
                    {
                        ("throwdistancemin", "Distance Min"),
                        ("throwdistancemax", "Distance Max"),
                        ("throwmaxheight", "Max Height"),
                        ("throwvelocity", "Velocity"),
                        ("maxsizeclass", "Max Size Class")
                    })
                    {
                        var value = currentValues.TryGetValue(tag, out var currentValue)
                            ? currentValue
                            : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                        var editor = new TextBox
                        {
                            Text = value,
                            IsEnabled = !_isReadOnly,
                            Width = 82,
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        AttachProtoActionDecimalBehavior(editor);
                        editor.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        throwRow.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(10, 4, 7, 4)
                        });
                        throwRow.Children.Add(editor);
                        state.AdditionalFieldControls[tag] = editor;
                    }

                    if (!_isReadOnly)
                    {
                        var removeThrowButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(8, 0, 0, 0)
                        };
                        removeThrowButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.SelectedFlagTags.Remove("throw");
                            foreach (var tag in throwTags)
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            }
                            RenderProtoActionFlags(state);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        throwRow.Children.Add(removeThrowButton);
                    }
                    state.AdditionalFieldsContainer.Children.Add(throwRow);
                }
            }

            if (!GetAttackMode(state).Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase))
            {
                var isBirthAttack = GetAttackMode(state).Equals("Birth Attack", StringComparison.OrdinalIgnoreCase);
                var castPowerTags = isBirthAttack
                    ? new[] { "castpower" }
                    : new[] { "castpower", "castpowertargettype" };
                var hasCastPower = castPowerTags.Any(tag =>
                    state.ForcedVisibleFieldTags.Contains(tag) ||
                    (currentValues.TryGetValue(tag, out var currentValue)
                        ? !string.IsNullOrWhiteSpace(currentValue)
                        : !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag))));
                if (!hasCastPower && !_isReadOnly)
                {
                    var addCastPowerButton = new Button
                    {
                        Content = "Cast Power",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 4, 0, 2)
                    };
                    addCastPowerButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        foreach (var tag in castPowerTags)
                            state.ForcedVisibleFieldTags.Add(tag);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    state.AdditionalFieldsContainer.Children.Add(addCastPowerButton);
                }
                else if (hasCastPower)
                {
                    var castPowerRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 4, 0, 2)
                    };
                    castPowerRow.Children.Add(new TextBlock
                    {
                        Text = "Cast Power:",
                        FontWeight = FontWeight.SemiBold,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 10, 4)
                    });
                    var castPowerEditor = new TextBox
                    {
                        Text = currentValues.TryGetValue("castpower", out var currentCastPower)
                            ? currentCastPower
                            : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "castpower"),
                        IsEnabled = !_isReadOnly,
                        Width = 200,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    EditorTextFieldStyle.ConfigureTextBox(castPowerEditor);
                    ApplyProtoActionFieldWidth(castPowerEditor, "castpower");
                    castPowerEditor.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating && await CheckStartLocalMod())
                            MarkDirty();
                    };
                    state.AdditionalFieldControls["castpower"] = castPowerEditor;
                    castPowerRow.Children.Add(castPowerEditor);

                    if (!isBirthAttack)
                    {
                        castPowerRow.Children.Add(new TextBlock
                        {
                            Text = "Target Type:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(14, 4, 8, 4)
                        });
                        var castPowerTargetSuggestions = GetKnownUnitTypeNames()
                            .Concat(GetAvailableTrainUnitNames())
                            .Where(value => !string.IsNullOrWhiteSpace(value))
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                            .ToList();
                        var castPowerTargetValue = currentValues.TryGetValue("castpowertargettype", out var currentCastPowerTarget)
                            ? currentCastPowerTarget
                            : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "castpowertargettype");
                        if (string.IsNullOrWhiteSpace(castPowerTargetValue))
                            castPowerTargetValue = "Unit";
                        var castPowerTargetEditor = new AutoCompleteBox
                        {
                            Text = castPowerTargetValue,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            IsEnabled = !_isReadOnly,
                            Width = 200
                        };
                        ConfigureStrictSuggestionAutoComplete(castPowerTargetEditor, castPowerTargetSuggestions, castPowerTargetEditor.Text ?? "");
                        ApplyProtoActionFieldWidth(castPowerTargetEditor, "castpower");
                        castPowerTargetEditor.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        state.AdditionalFieldControls["castpowertargettype"] = castPowerTargetEditor;
                        castPowerRow.Children.Add(castPowerTargetEditor);
                    }

                    if (!_isReadOnly)
                    {
                        var removeCastPowerButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(8, 0, 0, 0)
                        };
                        removeCastPowerButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            foreach (var tag in castPowerTags)
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            }
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        castPowerRow.Children.Add(removeCastPowerButton);
                    }
                    state.AdditionalFieldsContainer.Children.Add(castPowerRow);
                }
            }
        }

        var isWaterTornadoLayout = actionType.Equals("WaterTornado", StringComparison.OrdinalIgnoreCase);
        if (isWaterTornadoLayout)
            primaryFieldTags.RemoveAll(tag => tag.Equals("maxspread", StringComparison.OrdinalIgnoreCase) ||
                                              tag.Equals("spreadfactor", StringComparison.OrdinalIgnoreCase));

        if (!IsAutoRangedModifyActionType(actionType) && !IsAreaMutateActionType(actionType) && !IsAutoRangedAttachActionType(actionType))
        {
            foreach (var tag in primaryFieldTags)
                RenderFieldRow(tag);
        }

        if (isWaterTornadoLayout)
            RenderWaterTornadoSpreadRow();

        if (isRampage && !fieldTags.Contains("maxsizeclass", StringComparer.OrdinalIgnoreCase) && !_isReadOnly)
        {
            var addMaxSizeClassButton = new Button
            {
                Content = "Max Size Class",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left
            };
            addMaxSizeClassButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;

                state.ForcedVisibleFieldTags.Add("maxsizeclass");
                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            state.AdditionalFieldsContainer.Children.Add(addMaxSizeClassButton);
        }

        if (isRampage && !fieldTags.Contains("projectile", StringComparer.OrdinalIgnoreCase) && !_isReadOnly)
        {
            var addProjectileButton = new Button
            {
                Content = "Projectile",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left
            };
            addProjectileButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;

                state.CustomValues.Remove("rampage.projectile.hidden");
                state.ForcedVisibleFieldTags.Add("projectile");
                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            state.AdditionalFieldsContainer.Children.Add(addProjectileButton);
        }

        if (IsJumpAttackActionType(actionType))
        {
            var hasThrowEffect = state.OnHitEffectRows.Count > 0
                ? state.OnHitEffectRows.Any(x => string.Equals(x.TypeCb.Text?.Trim(), "Throw", StringComparison.OrdinalIgnoreCase))
                : GetProtoActionOnHitEffectElements(effectiveAction)
                    .Any(x => string.Equals((string?)x.Attribute("type"), "Throw", StringComparison.OrdinalIgnoreCase));
            if (hasThrowEffect)
                RenderFieldRow("maxsizeclass");
        }

        if (hasManagedCustomLayout)
        {
            state.AdditionalFieldsContainer.Children.Clear();
            state.AdditionalFieldControls.Clear();

            static double GetCompactReadOnlyEditorWidth(string value)
            {
                var length = value?.Trim().Length ?? 0;
                if (length <= 0)
                    return 80;

                return Math.Clamp(24 + (length * 8), 80, 420);
            }

            Control CreateSimpleEditor(string tag)
            {
                var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
                var rawValue = currentValues.TryGetValue(tag, out var editedValue)
                    ? editedValue
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                var value = GetProtoActionDefaultSimpleValue(tag, rawValue);

                Control editor = definition.EditorKind switch
                {
                    ProtoActionFieldEditorKind.Toggle => new CheckBox
                    {
                        IsChecked = !string.IsNullOrWhiteSpace(value) && !value.Equals("0", StringComparison.OrdinalIgnoreCase),
                        IsEnabled = !_isReadOnly,
                        VerticalAlignment = VerticalAlignment.Center
                    },
                    _ => GetProtoActionValueSuggestions(tag) is List<string> suggestions
                        ? new AutoCompleteBox
                        {
                            Text = value,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            ItemsSource = suggestions,
                            IsEnabled = !_isReadOnly
                        }
                        : new TextBox
                        {
                            Text = value,
                            IsEnabled = !_isReadOnly
                        }
                };

                if (editor is TextBox editorTextBox && definition.EditorKind == ProtoActionFieldEditorKind.Number)
                    AttachProtoActionNumberBehavior(editorTextBox, tag);
                else if (AssetPathFieldTags.Contains(tag) && editor is TextBox assetTextBox)
                {
                    EditorTextFieldStyle.ConfigureTextBox(assetTextBox);
                }
                else if (editor is TextBox textBox)
                    EditorTextFieldStyle.ConfigureTextBox(textBox);
                if (editor is AutoCompleteBox editorAcb)
                {
                    if (AssetPathFieldTags.Contains(tag))
                        EditorTextFieldStyle.ConfigureSelector(editorAcb);
                    else
                        EditorTextFieldStyle.ConfigureSelector(editorAcb);
                    ConfigureProtoActionValueAutoComplete(editorAcb, tag, value);
                }

                if (AssetPathFieldTags.Contains(tag))
                    editor = CreateAssetPathEditor(tag, value, GetProtoActionValueSuggestions(tag) ?? []);
                ApplyProtoActionFieldWidth(editor, tag);

                if (_isReadOnly && IsDevoteMinorActionType(actionType))
                {
                    var width = GetCompactReadOnlyEditorWidth(value);
                    switch (editor)
                    {
                        case TextBox compactTb:
                            compactTb.Width = width;
                            compactTb.HorizontalAlignment = HorizontalAlignment.Left;
                            break;
                        case AutoCompleteBox compactAcb:
                            compactAcb.Width = width;
                            compactAcb.HorizontalAlignment = HorizontalAlignment.Left;
                            break;
                    }
                }

                if (!AssetPathFieldTags.Contains(tag) && editor is TextBox tb)
                {
                    tb.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        }
                    };
                }
                else if (!AssetPathFieldTags.Contains(tag) && editor is AutoCompleteBox acb)
                {
                    acb.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        }
                    };
                }
                else if (editor is CheckBox cb)
                {
                    cb.IsCheckedChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                if (IsKnownProtoActionFlagTag(tag))
                                {
                                    if (cb.IsChecked == true)
                                        state.SelectedFlagTags.Add(tag);
                                    else
                                        state.SelectedFlagTags.Remove(tag);
                                    RenderProtoActionFlags(state);
                                }
                                MarkDirty();
                            }
                        }
                    };
                }

                state.AdditionalFieldControls[tag] = editor;
                return editor;
            }

            WrapPanel CreateCompactRow(params (string Tag, string Label)[] fields)
            {
                var row = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Stretch
                };
                foreach (var field in fields)
                {
                    var editor = CreateSimpleEditor(field.Tag);
                    row.Children.Add(CreateLabeledFieldGroup(field.Label + ":", editor));
                }
                return row;
            }

            if (IsLinearAreaAttackActionType(actionType))
            {
                string GetLinearAreaAttackValue(string tag)
                    => currentValues.TryGetValue(tag, out var editedValue)
                        ? editedValue
                        : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);

                bool IsLinearAreaAttackOptionalVisible(string tag)
                    => state.ForcedVisibleFieldTags.Contains(tag) || !string.IsNullOrWhiteSpace(GetLinearAreaAttackValue(tag));

                var speedValue = GetLinearAreaAttackValue("modifyamount");
                if (!_isReadOnly || !string.IsNullOrWhiteSpace(speedValue))
                {
                    var speedRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2)
                    };
                    speedRow.Children.Add(CreateLabeledFieldGroup("Speed:", CreateSimpleEditor("modifyamount")));

                    var rollingSmashVisible = state.SelectedFlagTags.Contains("rollingsmash") ||
                                             IsLinearAreaAttackOptionalVisible("rollingdamagefactor");
                    if (!rollingSmashVisible)
                    {
                        if (!_isReadOnly)
                        {
                            var addRollingSmashButton = new Button
                            {
                                Content = "Rolling Smash",
                                Classes = { "add-component" },
                                Margin = new Thickness(12, 0, 0, 0)
                            };
                            addRollingSmashButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;

                                state.SelectedFlagTags.Add("rollingsmash");
                                state.ForcedVisibleFieldTags.Add("rollingdamagefactor");
                                RenderProtoActionFlags(state);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            speedRow.Children.Add(addRollingSmashButton);
                        }
                    }
                    else
                    {
                        speedRow.Children.Add(CreateLabeledFieldGroup("Rolling Damage Factor:", CreateSimpleEditor("rollingdamagefactor")));
                        if (!_isReadOnly)
                        {
                            var removeRollingSmashButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(6, 0, 0, 0)
                            };
                            removeRollingSmashButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;

                                state.SelectedFlagTags.Remove("rollingsmash");
                                state.ForcedVisibleFieldTags.Remove("rollingdamagefactor");
                                state.AdditionalFieldControls.Remove("rollingdamagefactor");
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "rollingdamagefactor", "");
                                RenderProtoActionFlags(state);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            speedRow.Children.Add(removeRollingSmashButton);
                        }
                    }
                    state.LinearAreaAttackOptionsContainer.Children.Add(speedRow);
                }

                var visualRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2)
                };
                foreach (var (tag, label) in new[]
                {
                    ("anim", "Animation"),
                    ("walkanim", "Movement Anim")
                })
                {
                    if (!_isReadOnly || !string.IsNullOrWhiteSpace(GetLinearAreaAttackValue(tag)))
                        visualRow.Children.Add(CreateLabeledFieldGroup(label + ":", CreateSimpleEditor(tag)));
                }

                if (IsLinearAreaAttackOptionalVisible("idleanim"))
                {
                    visualRow.Children.Add(CreateLabeledFieldGroup("Idle Anim:", CreateSimpleEditor("idleanim")));
                    if (!_isReadOnly)
                    {
                        var removeIdleAnimationButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0)
                        };
                        removeIdleAnimationButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.ForcedVisibleFieldTags.Remove("idleanim");
                            state.AdditionalFieldControls.Remove("idleanim");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "idleanim", "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        visualRow.Children.Add(removeIdleAnimationButton);
                    }
                }
                else if (!_isReadOnly)
                {
                    var addIdleAnimationButton = new Button
                    {
                        Content = "Idle Anim",
                        Classes = { "add-component" },
                        Margin = new Thickness(12, 0, 0, 0)
                    };
                    addIdleAnimationButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.ForcedVisibleFieldTags.Add("idleanim");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    visualRow.Children.Add(addIdleAnimationButton);
                }
                if (!_isReadOnly || !string.IsNullOrWhiteSpace(GetLinearAreaAttackValue("impacteffect")))
                {
                    var impactEffectGroup = CreateLabeledFieldGroup("Impact Effect:", CreateSimpleEditor("impacteffect"));
                    impactEffectGroup.Margin = new Thickness(16, 0, 0, 0);
                    visualRow.Children.Add(impactEffectGroup);
                }
                if (visualRow.Children.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(visualRow);

                var hasThrowOnHitEffect = state.OnHitEffectRows.Count > 0
                    ? state.OnHitEffectRows.Any(row => string.Equals(row.TypeCb.Text?.Trim(), "Throw", StringComparison.OrdinalIgnoreCase))
                    : GetProtoActionOnHitEffectElements(effectiveAction)
                        .Any(effect => string.Equals((string?)effect.Attribute("type"), "Throw", StringComparison.OrdinalIgnoreCase));
                if (hasThrowOnHitEffect)
                {
                    var throwTags = new[] { "throwdistancemax", "throwdistancemin", "throwmaxheight", "throwvelocity", "maxsizeclass" };
                    var hasThrowConfiguration = state.SelectedFlagTags.Contains("throw") || throwTags.Any(IsLinearAreaAttackOptionalVisible);
                    if (!hasThrowConfiguration && !_isReadOnly)
                    {
                        var addThrowButton = new Button
                        {
                            Content = "Throw",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 4, 0, 2)
                        };
                        addThrowButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.SelectedFlagTags.Add("throw");
                            RenderProtoActionFlags(state);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        state.AdditionalFieldsContainer.Children.Add(addThrowButton);
                    }
                    else if (hasThrowConfiguration)
                    {
                        var throwRow = new WrapPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Margin = new Thickness(0, 4, 0, 2)
                        };
                        throwRow.Children.Add(new TextBlock
                        {
                            Text = "Throw:",
                            FontWeight = FontWeight.SemiBold,
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 10, 4)
                        });
                        foreach (var (tag, label) in new[]
                        {
                            ("throwdistancemin", "Min Distance"),
                            ("throwdistancemax", "Max Distance"),
                            ("throwmaxheight", "Max Height"),
                            ("throwvelocity", "Velocity"),
                            ("maxsizeclass", "Max Size")
                        })
                        {
                            throwRow.Children.Add(CreateLabeledFieldGroup(label + ":", CreateSimpleEditor(tag)));
                        }
                        if (!_isReadOnly)
                        {
                            var removeThrowButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(6, 0, 0, 0)
                            };
                            removeThrowButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;

                                ClearProtoActionThrowConfiguration(state);
                                RenderProtoActionFlags(state);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            throwRow.Children.Add(removeThrowButton);
                        }
                        state.AdditionalFieldsContainer.Children.Add(throwRow);
                    }
                }
            }
            else if (IsChainAttackActionType(actionType) || IsAoeAttackActionType(actionType))
            {
                string GetChainAttackValue(string tag)
                    => currentValues.TryGetValue(tag, out var editedValue)
                        ? editedValue
                        : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);

                Control CreateChainAttackEditor(string tag, string value, double width = 100)
                {
                    Control editor;
                    if (tag.Equals("projectile", StringComparison.OrdinalIgnoreCase))
                    {
                        var projectileEditor = new AutoCompleteBox
                        {
                            Text = value,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            IsEnabled = !_isReadOnly,
                            Width = 200
                        };
                        ConfigureStrictSuggestionAutoComplete(projectileEditor, GetAvailableTrainUnitNames(), value);
                        editor = projectileEditor;
                    }
                    else if (tag.Equals("anim", StringComparison.OrdinalIgnoreCase) ||
                             tag.Equals("impacteffect", StringComparison.OrdinalIgnoreCase))
                    {
                        IEnumerable<string> suggestions = tag.Equals("anim", StringComparison.OrdinalIgnoreCase)
                            ? GetAvailableProtoActionAnimationNames()
                            : KnownImpactEffects;
                        var selector = new AutoCompleteBox
                        {
                            Text = value,
                            ItemsSource = suggestions,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            IsEnabled = !_isReadOnly,
                            Width = 200
                        };
                        EditorTextFieldStyle.ConfigureSelector(selector);
                        EnableDropdownAutoComplete(selector);
                        editor = selector;
                    }
                    else
                    {
                        var textBox = new TextBox
                        {
                            Text = value,
                            IsEnabled = !_isReadOnly,
                            Width = width
                        };
                        AttachProtoActionDecimalBehavior(textBox);
                        editor = textBox;
                    }

                    if (editor is TextBox textBoxEditor)
                    {
                        textBoxEditor.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                    }
                    else if (editor is AutoCompleteBox autoCompleteEditor)
                    {
                        autoCompleteEditor.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                    }

                    state.AdditionalFieldControls[tag] = editor;
                    return editor;
                }

                bool IsChainAttackOptionalVisible(string tag)
                    => state.ForcedVisibleFieldTags.Contains(tag) || !string.IsNullOrWhiteSpace(GetChainAttackValue(tag));

                void AddChainAttackOptional(Panel row, string tag, string label, bool renderButtons, double width = 100)
                {
                    var value = GetChainAttackValue(tag);
                    var visible = IsChainAttackOptionalVisible(tag);
                    if (visible && renderButtons)
                        return;
                    if (!visible)
                    {
                        if (renderButtons && !_isReadOnly)
                        {
                            var addButton = new Button
                            {
                                Content = label,
                                Classes = { "add-component" },
                                Margin = new Thickness(10, 0, 0, 0)
                            };
                            addButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;
                                state.ForcedVisibleFieldTags.Add(tag);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            row.Children.Add(addButton);
                        }
                        return;
                    }

                    row.Children.Add(new TextBlock
                    {
                        Text = label + ":",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(12, 4, 8, 4)
                    });
                    row.Children.Add(CreateChainAttackEditor(tag, value, width));
                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(6, 0, 0, 0)
                        };
                        removeButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            state.ForcedVisibleFieldTags.Remove(tag);
                            state.AdditionalFieldControls.Remove(tag);
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        row.Children.Add(removeButton);
                    }
                }

                if (IsChainAttackActionType(actionType))
                {
                    var projectileRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2)
                    };
                    projectileRow.Children.Add(CreateLabeledFieldGroup("Projectile:", CreateChainAttackEditor("projectile", GetChainAttackValue("projectile"))));
                    foreach (var (tag, label) in new[] { ("displayednumberprojectiles", "Displayed Number"), ("numberbounces", "Number Bounces") })
                        AddChainAttackOptional(projectileRow, tag, label, renderButtons: false);
                    foreach (var (tag, label) in new[] { ("displayednumberprojectiles", "Displayed Number"), ("numberbounces", "Number Bounces") })
                        AddChainAttackOptional(projectileRow, tag, label, renderButtons: true);
                    state.AdditionalFieldsContainer.Children.Add(projectileRow);

                    var targetingRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2)
                    };
                    foreach (var (tag, label) in new[] { ("accuracy", "Accuracy"), ("trackrating", "Track Rating") })
                        AddChainAttackOptional(targetingRow, tag, label, renderButtons: false);
                    foreach (var (tag, label) in new[] { ("accuracy", "Accuracy"), ("trackrating", "Track Rating") })
                        AddChainAttackOptional(targetingRow, tag, label, renderButtons: true);
                    if (targetingRow.Children.Count > 0)
                        state.AdditionalFieldsContainer.Children.Add(targetingRow);
                }

                var animationValue = GetChainAttackValue("anim");
                var impactValue = GetChainAttackValue("impacteffect");
                if (!_isReadOnly || !string.IsNullOrWhiteSpace(animationValue) || !string.IsNullOrWhiteSpace(impactValue))
                {
                    state.AdditionalFieldsContainer.Children.Add(CreateCombatVisualFieldsRow(
                        state,
                        animationValue,
                        impactValue,
                        showAnimation: !_isReadOnly || !string.IsNullOrWhiteSpace(animationValue),
                        showImpact: !_isReadOnly || !string.IsNullOrWhiteSpace(impactValue)));
                }
            }
            else if (IsDevoteMinorActionType(actionType))
            {
                state.CoreFieldsGrid.IsVisible = false;
                state.MaxRangeLabel.IsVisible = false;
                state.MaxRangeTb.IsVisible = false;
                var isOriginalReadOnlyAction = _isReadOnly;

                bool HasDevoteMinorSimpleValue(string tag)
                    => !string.IsNullOrWhiteSpace(
                        currentValues.TryGetValue(tag, out var currentValue)
                            ? currentValue
                            : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag));

                bool HasDevoteMinorRateValue()
                    => GetCurrentStructuredEntries("rate").Count > 0;

                string InferDevoteMinorSubtype()
                {
                    if (state.CustomValues.TryGetValue(DevoteMinorSubtypeStateKey, out var selectedSubtype) &&
                        DevoteMinorSubtypeOptions.Contains(selectedSubtype, StringComparer.OrdinalIgnoreCase))
                    {
                        return selectedSubtype;
                    }

                    var hasPrayData =
                        state.SelectedFlagTags.Contains("devotionneversacrifice") ||
                        !string.IsNullOrWhiteSpace(currentValues.TryGetValue("devotionfavortrickle", out var favorTrickleValue) ? favorTrickleValue : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "devotionfavortrickle")) ||
                        !string.IsNullOrWhiteSpace(currentValues.TryGetValue("devotionhealthdraineachsecond", out var healthDrainValue) ? healthDrainValue : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "devotionhealthdraineachsecond")) ||
                        !string.IsNullOrWhiteSpace(currentValues.TryGetValue("devotionhealthdrainlimit", out var healthDrainLimitValue) ? healthDrainLimitValue : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "devotionhealthdrainlimit")) ||
                        !string.IsNullOrWhiteSpace(currentValues.TryGetValue("devotionscaleatminimumhealth", out var scaleValue) ? scaleValue : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "devotionscaleatminimumhealth"));

                    return hasPrayData ? DevoteMinorPraySubtype : DevoteMinorSacrificeSubtype;
                }

                void ClearDevoteMinorSubtypeValues(IEnumerable<string> simpleTags, bool clearRate)
                {
                    foreach (var tag in simpleTags)
                    {
                        state.ForcedVisibleFieldTags.Remove(tag);
                        state.AdditionalFieldControls.Remove(tag);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                    }

                    if (clearRate)
                    {
                        state.StructuredFieldRows.Remove("rate");
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "rate", []);
                    }
                }

                var currentSubtype = InferDevoteMinorSubtype();
                state.CustomValues[DevoteMinorSubtypeStateKey] = currentSubtype;
                if (!isOriginalReadOnlyAction)
                {
                    var subtypeRow = new Grid
                    {
                        ColumnDefinitions = new ColumnDefinitions("Auto, 220"),
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    subtypeRow.Children.Add(new TextBlock
                    {
                        Text = "Type:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 8, 4)
                    });
                    var subtypeCombo = new ComboBox
                    {
                        ItemsSource = DevoteMinorSubtypeOptions,
                        SelectedItem = currentSubtype,
                        IsEnabled = !_isReadOnly,
                        Width = 220
                    };
                    RegisterProtoActionFlagSourceControl(state, subtypeCombo, "devotionneversacrifice");
                    subtypeCombo.SelectionChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        var selectedSubtype = subtypeCombo.SelectedItem as string ?? DevoteMinorSacrificeSubtype;
                        state.CustomValues[DevoteMinorSubtypeStateKey] = selectedSubtype;

                        if (selectedSubtype.Equals(DevoteMinorPraySubtype, StringComparison.OrdinalIgnoreCase))
                        {
                            ClearDevoteMinorSubtypeValues(DevoteMinorSacrificeExclusiveSimpleTags, clearRate: true);
                            state.SelectedFlagTags.Add("devotionneversacrifice");
                        }
                        else
                        {
                            ClearDevoteMinorSubtypeValues(DevoteMinorPrayExclusiveSimpleTags, clearRate: false);
                            state.SelectedFlagTags.Remove("devotionneversacrifice");
                        }

                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    };
                    Grid.SetColumn(subtypeCombo, 1);
                    subtypeRow.Children.Add(subtypeCombo);
                    state.AdditionalFieldsContainer.Children.Add(subtypeRow);
                }

                var animEditor = CreateSimpleEditor("anim");
                var maxRangeMirror = new TextBox
                {
                    Text = GetProtoActionDefaultSimpleValue(
                        "maxrange",
                        currentValues.TryGetValue("maxrange", out var currentMaxRange)
                            ? currentMaxRange
                            : state.MaxRangeTb.Text ?? ""),
                    IsEnabled = !_isReadOnly,
                    Width = _isReadOnly
                        ? GetCompactReadOnlyEditorWidth(currentValues.TryGetValue("maxrange", out var maxRangeValue) ? maxRangeValue : state.MaxRangeTb.Text ?? "")
                        : 120,
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                AttachProtoActionDecimalBehavior(maxRangeMirror);
                state.MirroredSimpleSourceControls[maxRangeMirror] = "maxrange";
                maxRangeMirror.TextChanged += async (_, _) =>
                {
                    state.MaxRangeTb.Text = maxRangeMirror.Text;
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                var topRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 120"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                topRow.Children.Add(new TextBlock
                {
                    Text = "Max Range:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                Grid.SetColumn(maxRangeMirror, 1);
                topRow.Children.Add(maxRangeMirror);
                state.AdditionalFieldsContainer.Children.Add(topRow);

                var renderSacrificeFields = !isOriginalReadOnlyAction
                    ? currentSubtype.Equals(DevoteMinorSacrificeSubtype, StringComparison.OrdinalIgnoreCase)
                    : HasDevoteMinorRateValue() ||
                      DevoteMinorSacrificeExclusiveSimpleTags.Any(HasDevoteMinorSimpleValue);
                var renderPrayFields = !isOriginalReadOnlyAction
                    ? currentSubtype.Equals(DevoteMinorPraySubtype, StringComparison.OrdinalIgnoreCase)
                    : state.SelectedFlagTags.Contains("devotionneversacrifice") ||
                      DevoteMinorPrayExclusiveSimpleTags.Any(HasDevoteMinorSimpleValue);

                if (renderSacrificeFields)
                {
                    var devotionRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    if (!isOriginalReadOnlyAction || HasDevoteMinorSimpleValue("devotiontime"))
                        devotionRow.Children.Add(CreateLabeledFieldGroup("Devotion Time:", CreateSimpleEditor("devotiontime")));

                    void AddDevotionReward(string tag, string label)
                    {
                        var visible = state.ForcedVisibleFieldTags.Contains(tag) || HasDevoteMinorSimpleValue(tag);
                        if (visible)
                        {
                            var editor = CreateSimpleEditor(tag);
                            devotionRow.Children.Add(CreateLabeledFieldGroup(label + ":", editor));
                            if (!_isReadOnly)
                            {
                                var remove = new Button
                                {
                                    Classes = { "remove-button" },
                                    Margin = new Thickness(2, 0, 8, 6),
                                    VerticalAlignment = VerticalAlignment.Center
                                };
                                remove.Click += async (_, _) =>
                                {
                                    if (!await CheckStartLocalMod()) return;
                                    state.ForcedVisibleFieldTags.Remove(tag);
                                    state.AdditionalFieldControls.Remove(tag);
                                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                    RefreshProtoActionMetadataPanels(state);
                                    MarkDirty();
                                };
                                devotionRow.Children.Add(remove);
                            }
                        }
                        else if (!_isReadOnly)
                        {
                            var add = new Button
                            {
                                Content = label,
                                Classes = { "add-component" },
                                Margin = new Thickness(0, 0, 8, 6)
                            };
                            add.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod()) return;
                                state.ForcedVisibleFieldTags.Add(tag);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            devotionRow.Children.Add(add);
                        }
                    }

                    AddDevotionReward("devotioncombatxpreward", "Combat XP Reward");
                    AddDevotionReward("devotionfavorreward", "Favor Reward");
                    if (devotionRow.Children.Count > 0)
                        state.AdditionalFieldsContainer.Children.Add(devotionRow);

                    var rateEntries = GetCurrentStructuredEntries("rate");
                    if (rateEntries.Count > 0 || !isOriginalReadOnlyAction)
                    {
                        state.StructuredFieldRows["rate"] = [];
                        var currentRateEntry = rateEntries.FirstOrDefault() ?? new ProtoActionStructuredFieldEntry();
                        var selectedRateType = currentRateEntry.Attributes.TryGetValue("type", out var currentRateType) && !string.IsNullOrWhiteSpace(currentRateType)
                            ? ProtoConstants.KnownResourceTypes.FirstOrDefault(resource => resource.Equals(currentRateType, StringComparison.OrdinalIgnoreCase)) ?? "Favor"
                            : "Favor";
                        var rateTypeAcb = new ComboBox
                        {
                            SelectedItem = selectedRateType,
                            Width = 140,
                            ItemsSource = ProtoConstants.KnownResourceTypes,
                            IsEnabled = !_isReadOnly
                        };
                        rateTypeAcb.SelectionChanged += async (_, _) =>
                        {
                            if (_isPopulating)
                                return;

                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        };
                        var rateValueTb = new TextBox
                        {
                            Text = !string.IsNullOrWhiteSpace(currentRateEntry.Value) ? currentRateEntry.Value : "1",
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        };
                        AttachProtoActionDecimalBehavior(rateValueTb);
                        rateValueTb.TextChanged += async (_, _) =>
                        {
                            if (_isPopulating)
                                return;

                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        };
                        var rateRowState = new ProtoActionStructuredFieldRowState
                        {
                            Tag = "rate",
                            RowPanel = new StackPanel(),
                            ValueTb = rateValueTb
                        };
                        rateRowState.AttributeEditors["type"] = rateTypeAcb;
                        state.StructuredFieldRows["rate"].Add(rateRowState);

                        var rateRow = new Grid
                        {
                            ColumnDefinitions = new ColumnDefinitions("Auto, Auto"),
                            Margin = new Thickness(0, 2, 0, 2),
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        rateRow.Children.Add(new TextBlock
                        {
                            Text = "Rate:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 10, 4)
                        });
                        var ratePanel = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 6
                        };
                        ratePanel.Children.Add(new TextBlock { Text = "Type:", VerticalAlignment = VerticalAlignment.Center });
                        ratePanel.Children.Add(rateTypeAcb);
                        ratePanel.Children.Add(rateValueTb);
                        Grid.SetColumn(ratePanel, 1);
                        rateRow.Children.Add(ratePanel);
                        state.AdditionalFieldsContainer.Children.Add(rateRow);
                    }

                    var showScalingReduction = state.ForcedVisibleFieldTags.Contains("reductionstart") ||
                                               state.ForcedVisibleFieldTags.Contains("reductionend") ||
                                               state.ForcedVisibleFieldTags.Contains("minscale") ||
                                               HasDevoteMinorSimpleValue("reductionstart") ||
                                               HasDevoteMinorSimpleValue("reductionend") ||
                                               HasDevoteMinorSimpleValue("minscale");

                    var visualRow = new WrapPanel
                    {
                        Tag = "devoteminor.animation",
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    animEditor.Width = 200;
                    visualRow.Children.Add(CreateLabeledFieldGroup("Animation:", animEditor));
                    state.AdditionalFieldsContainer.Children.Add(visualRow);

                    bool showSoundsetEnter = state.ForcedVisibleFieldTags.Contains("soundsetenter") ||
                                             !string.IsNullOrWhiteSpace(currentValues.TryGetValue("soundsetenter", out var currentSoundsetEnter) ? currentSoundsetEnter : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "soundsetenter"));
                    bool showDevotionPower = state.ForcedVisibleFieldTags.Contains("devotionpower") ||
                                             !string.IsNullOrWhiteSpace(currentValues.TryGetValue("devotionpower", out var currentDevotionPower) ? currentDevotionPower : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "devotionpower"));

                    async Task RemoveDevoteMinorOptionalFieldAsync(string tag)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        state.ForcedVisibleFieldTags.Remove(tag);
                        state.AdditionalFieldControls.Remove(tag);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    }

                    var optionalFieldRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2)
                    };

                    void AddDevoteMinorTextOption(string tag, string label, bool visible)
                    {
                        if (visible)
                        {
                            var editor = CreateSimpleEditor(tag);
                            editor.Width = 200;
                            optionalFieldRow.Children.Add(CreateLabeledFieldGroup(label + ":", editor));
                            if (!_isReadOnly)
                            {
                                var remove = new Button
                                {
                                    Classes = { "remove-button" },
                                    Margin = new Thickness(2, 0, 8, 6),
                                    VerticalAlignment = VerticalAlignment.Center
                                };
                                remove.Click += async (_, _) => await RemoveDevoteMinorOptionalFieldAsync(tag);
                                optionalFieldRow.Children.Add(remove);
                            }
                            return;
                        }

                        if (_isReadOnly)
                            return;

                        var add = new Button
                        {
                            Content = label,
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 6)
                        };
                        add.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            state.ForcedVisibleFieldTags.Add(tag);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        optionalFieldRow.Children.Add(add);
                    }

                    if (!showScalingReduction && !_isReadOnly)
                    {
                        var addScalingReduction = new Button
                        {
                            Content = "Scaling Reduction",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 6)
                        };
                        addScalingReduction.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            foreach (var tag in new[] { "reductionstart", "reductionend", "minscale" })
                                state.ForcedVisibleFieldTags.Add(tag);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        optionalFieldRow.Children.Add(addScalingReduction);
                    }

                    AddDevoteMinorTextOption("devotionpower", "Devotion Power", showDevotionPower);
                    AddDevoteMinorTextOption("soundsetenter", "Soundset Enter", showSoundsetEnter);

                    if (optionalFieldRow.Children.Count > 0)
                        state.AdditionalFieldsContainer.Children.Add(optionalFieldRow);

                    if (showScalingReduction)
                    {
                        var scalingRow = new WrapPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Margin = new Thickness(0, 2, 0, 2),
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        scalingRow.Children.Add(CreateLabeledFieldGroup("Reduction Start:", CreateSimpleEditor("reductionstart")));
                        scalingRow.Children.Add(CreateLabeledFieldGroup("Reduction End:", CreateSimpleEditor("reductionend")));
                        scalingRow.Children.Add(CreateLabeledFieldGroup("Min Scale:", CreateSimpleEditor("minscale")));
                        if (!_isReadOnly)
                        {
                            var removeScaling = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(2, 0, 0, 6),
                                VerticalAlignment = VerticalAlignment.Center
                            };
                            removeScaling.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod()) return;
                                foreach (var tag in new[] { "reductionstart", "reductionend", "minscale" })
                                {
                                    state.ForcedVisibleFieldTags.Remove(tag);
                                    state.AdditionalFieldControls.Remove(tag);
                                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                }
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            scalingRow.Children.Add(removeScaling);
                        }
                        state.AdditionalFieldsContainer.Children.Add(scalingRow);
                    }
                }
                if (renderPrayFields)
                {
                    var prayVisualRow = new WrapPanel
                    {
                        Tag = "devoteminor.animation",
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    animEditor.Width = 200;
                    prayVisualRow.Children.Add(CreateLabeledFieldGroup("Animation:", animEditor));
                    state.AdditionalFieldsContainer.Children.Add(prayVisualRow);

                    var prayDevotionRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    if (!isOriginalReadOnlyAction || HasDevoteMinorSimpleValue("devotionfavortrickle"))
                        prayDevotionRow.Children.Add(CreateLabeledFieldGroup("Devotion Favor Trickle:", CreateSimpleEditor("devotionfavortrickle")));

                    void AddPrayOptional(string tag, string label)
                    {
                        var visible = state.ForcedVisibleFieldTags.Contains(tag) || HasDevoteMinorSimpleValue(tag);
                        if (visible)
                        {
                            prayDevotionRow.Children.Add(CreateLabeledFieldGroup(label + ":", CreateSimpleEditor(tag)));
                            if (!_isReadOnly)
                            {
                                var remove = new Button
                                {
                                    Classes = { "remove-button" },
                                    Margin = new Thickness(2, 0, 8, 6),
                                    VerticalAlignment = VerticalAlignment.Center
                                };
                                remove.Click += async (_, _) =>
                                {
                                    if (!await CheckStartLocalMod()) return;
                                    state.ForcedVisibleFieldTags.Remove(tag);
                                    state.AdditionalFieldControls.Remove(tag);
                                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                    RefreshProtoActionMetadataPanels(state);
                                    MarkDirty();
                                };
                                prayDevotionRow.Children.Add(remove);
                            }
                        }
                        else if (!_isReadOnly)
                        {
                            var add = new Button
                            {
                                Content = label,
                                Classes = { "add-component" },
                                Margin = new Thickness(0, 0, 8, 6)
                            };
                            add.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod()) return;
                                state.ForcedVisibleFieldTags.Add(tag);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            prayDevotionRow.Children.Add(add);
                        }
                    }

                    AddPrayOptional("devotionhealthdraineachsecond", "HP Drained (s)");
                    AddPrayOptional("devotionhealthdrainlimit", "HP Cap");
                    AddPrayOptional("devotionscaleatminimumhealth", "Scale at Min Health");
                    if (prayDevotionRow.Children.Count > 0)
                        state.AdditionalFieldsContainer.Children.Add(prayDevotionRow);
                }
            }
            else if (actionType.Equals("ResourceDecay", StringComparison.OrdinalIgnoreCase))
            {
                state.AdditionalFieldsContainer.Children.Add(CreateCompactRow(
                    ("decayrate", "Decay Rate"),
                    ("minresource", "Min Resource"),
                    ("scaleincrement", "Scale Increment")));
                state.AdditionalFieldsContainer.Children.Add(CreateCompactRow(
                    ("reductionstart", "Reduction Start"),
                    ("reductionend", "Reduction End"),
                    ("minscale", "Min Scale")));
            }
            else if (IsLikeBonusActionType(actionType))
            {
                var inverseAura = state.CustomValues.GetValueOrDefault("likebonus.inverseaura") == "1" ||
                                  state.SelectedFlagTags.Contains("targetenemy") ||
                                  state.SelectedFlagTags.Contains("includenature") ||
                                  state.SelectedFlagTags.Contains("includeally") ||
                                  state.SelectedFlagTags.Contains("modifyratebytype");
                var includeNature = state.SelectedFlagTags.Contains("includenature");
                var savedModifyAmount = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifyamount");
                var savedModifyMultiplier = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifymultiplier");
                var savedModifyType = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifytype");
                var mode = state.CustomValues.GetValueOrDefault("likebonus.mode") ??
                    (state.SelectedFlagTags.Contains("modifyratebytype") ? "Rate By Type"
                    : !string.IsNullOrWhiteSpace(savedModifyAmount) ? "Amount"
                    : !string.IsNullOrWhiteSpace(savedModifyMultiplier) ? "Multiplier"
                    : ProtoConstants.GetModifyTypeValueMode(savedModifyType) == ProtoConstants.ModifyTypeValueMode.Multiplier
                        ? "Multiplier"
                        : "Amount");
                if (inverseAura)
                    mode = "Rate By Type";

                var optionsRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 14, Margin = new Thickness(0, 2, 0, 2) };
                foreach (var previousOptionsRow in state.CoreFieldsGrid.Children
                             .OfType<Control>()
                             .Where(control => string.Equals(control.Tag as string, "likebonus.options", StringComparison.Ordinal))
                             .ToList())
                {
                    state.CoreFieldsGrid.Children.Remove(previousOptionsRow);
                }
                var inverseAuraCheckBox = new CheckBox { Content = "Inverse Aura", IsChecked = inverseAura, IsEnabled = !_isReadOnly };
                var exclusiveCheckBox = new CheckBox { Content = "Exclusive", IsChecked = state.SelectedFlagTags.Contains("exclusive"), IsEnabled = !_isReadOnly };
                optionsRow.Children.Add(inverseAuraCheckBox);
                optionsRow.Children.Add(exclusiveCheckBox);
                optionsRow.Tag = "likebonus.options";
                optionsRow.Margin = new Thickness(28, 2, 0, 2);
                state.CoreFieldsGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
                Grid.SetColumn(optionsRow, state.CoreFieldsGrid.ColumnDefinitions.Count - 1);
                state.CoreFieldsGrid.Children.Add(optionsRow);

                var targetSelfCheckBox = new CheckBox { Content = "Self", IsChecked = inverseAura && !state.SelectedFlagTags.Contains("targetenemy"), IsEnabled = !_isReadOnly };
                var targetEnemyCheckBox = new CheckBox { Content = "Enemy", IsChecked = state.SelectedFlagTags.Contains("targetenemy"), IsEnabled = !_isReadOnly };
                var includeNatureCheckBox = new CheckBox { Content = "Include Nature", IsChecked = includeNature, IsEnabled = !_isReadOnly };
                var includeAlliesCheckBox = new CheckBox { Content = "Include Allies", IsChecked = state.SelectedFlagTags.Contains("includeally"), IsEnabled = !_isReadOnly };
                state.CustomFlagControls["exclusive"] = exclusiveCheckBox;
                RegisterProtoActionFlagSourceControl(state, exclusiveCheckBox, "exclusive");
                state.CustomFlagControls["targetenemy"] = targetEnemyCheckBox;
                RegisterProtoActionFlagSourceControl(state, targetEnemyCheckBox, "targetenemy");
                state.CustomFlagControls["includenature"] = includeNatureCheckBox;
                RegisterProtoActionFlagSourceControl(state, includeNatureCheckBox, "includenature");
                state.CustomFlagControls["includeally"] = includeAlliesCheckBox;
                RegisterProtoActionFlagSourceControl(state, includeAlliesCheckBox, "includeally");
                RegisterProtoActionFlagSourceControl(state, targetSelfCheckBox, "targetenemy");
                var targetRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 14, Margin = new Thickness(18, 0, 0, 2), IsVisible = inverseAura };
                targetRow.Children.Add(new TextBlock { Text = "Targets:", VerticalAlignment = VerticalAlignment.Center });
                targetRow.Children.Add(targetSelfCheckBox);
                targetRow.Children.Add(targetEnemyCheckBox);
                targetRow.Children.Add(includeNatureCheckBox);
                targetRow.Children.Add(includeAlliesCheckBox);
                state.AdditionalFieldsContainer.Children.Add(targetRow);

                async Task UpdateLikeBonusFlagsAsync()
                {
                    if (_isPopulating || !await CheckStartLocalMod())
                        return;

                    if (inverseAuraCheckBox.IsChecked != true)
                    {
                        state.CustomValues.Remove("likebonus.inverseaura");
                        state.CustomValues.Remove("likebonus.mode");
                        state.SelectedFlagTags.Remove("targetenemy");
                        state.SelectedFlagTags.Remove("includenature");
                        state.SelectedFlagTags.Remove("includeally");
                        state.SelectedFlagTags.Remove("modifyratebytype");
                        state.ForcedVisibleFieldTags.Remove("rate");
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "rate", []);
                    }
                    else
                    {
                        state.CustomValues["likebonus.inverseaura"] = "1";
                        state.AdditionalFieldControls.Remove("modifyamount");
                        state.AdditionalFieldControls.Remove("modifymultiplier");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifyamount", "");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifymultiplier", "");
                        if (targetEnemyCheckBox.IsChecked == true)
                            state.SelectedFlagTags.Add("targetenemy");
                        else
                            state.SelectedFlagTags.Remove("targetenemy");
                    }
                    if (includeNatureCheckBox.IsChecked == true && inverseAuraCheckBox.IsChecked == true)
                        state.SelectedFlagTags.Add("includenature");
                    else
                        state.SelectedFlagTags.Remove("includenature");
                    if (includeAlliesCheckBox.IsChecked == true && inverseAuraCheckBox.IsChecked == true)
                        state.SelectedFlagTags.Add("includeally");
                    else
                        state.SelectedFlagTags.Remove("includeally");
                    if (exclusiveCheckBox.IsChecked == true)
                        state.SelectedFlagTags.Add("exclusive");
                    else
                        state.SelectedFlagTags.Remove("exclusive");

                    RenderProtoActionFlags(state);
                    MarkDirty();
                    RefreshProtoActionMetadataPanels(state);
                }
                inverseAuraCheckBox.IsCheckedChanged += async (_, _) => await UpdateLikeBonusFlagsAsync();
                targetSelfCheckBox.IsCheckedChanged += async (_, _) =>
                {
                    if (targetSelfCheckBox.IsChecked == true && targetEnemyCheckBox.IsChecked == true)
                        targetEnemyCheckBox.IsChecked = false;
                    await UpdateLikeBonusFlagsAsync();
                };
                targetEnemyCheckBox.IsCheckedChanged += async (_, _) =>
                {
                    if (targetEnemyCheckBox.IsChecked == true && targetSelfCheckBox.IsChecked == true)
                        targetSelfCheckBox.IsChecked = false;
                    await UpdateLikeBonusFlagsAsync();
                };
                includeNatureCheckBox.IsCheckedChanged += async (_, _) => await UpdateLikeBonusFlagsAsync();
                includeAlliesCheckBox.IsCheckedChanged += async (_, _) => await UpdateLikeBonusFlagsAsync();
                exclusiveCheckBox.IsCheckedChanged += async (_, _) => await UpdateLikeBonusFlagsAsync();

                var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
                    .Select(ProtoConstants.GetModifyTypeDisplayName)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                string GetValue(string tag) => currentValues.TryGetValue(tag, out var value) ? value : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                var modifyRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                var modifyTypeAcb = new AutoCompleteBox { Text = ProtoConstants.GetModifyTypeDisplayName(ProtoConstants.GetModifyTypeValue(GetValue("modifytype"))), Width = 210, FilterMode = AutoCompleteFilterMode.Contains, IsEnabled = !_isReadOnly };
                ConfigureStrictSuggestionAutoComplete(modifyTypeAcb, modifyTypeSuggestions, modifyTypeAcb.Text ?? "");
                modifyRow.Children.Add(CreateLabeledFieldGroup("Modify:", modifyTypeAcb));
                var damageTypeCombo = new ComboBox { Width = 100, IsEnabled = !_isReadOnly };
                var damageTypeGroup = CreateLabeledFieldGroup("Damage Type:", damageTypeCombo);
                modifyRow.Children.Add(damageTypeGroup);
                var damageTargetSuggestions = GetKnownUnitTypeNames()
                    .Concat(GetAvailableTrainUnitNames())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var damageTargetTypeAcb = new AutoCompleteBox
                {
                    Text = GetValue("modifydamagetargettype"),
                    Width = 180,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly
                };
                ConfigureStrictSuggestionAutoComplete(damageTargetTypeAcb, damageTargetSuggestions, damageTargetTypeAcb.Text ?? "");
                var damageTargetTypeGroup = CreateLabeledFieldGroup("Target:", damageTargetTypeAcb);
                modifyRow.Children.Add(damageTargetTypeGroup);
                void RefreshConditionalModifyFields()
                {
                    var modifyType = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                    var showDamageType = modifyType is "ArmorSpecific" or "DamageSpecific";
                    var showDamageTargetType = modifyType.Equals("DamageByTargetType", StringComparison.OrdinalIgnoreCase);
                    damageTypeGroup.IsVisible = showDamageType;
                    damageTargetTypeGroup.IsVisible = showDamageTargetType;
                    RefreshProtoActionDamageTypeCombo(damageTypeCombo, modifyType, GetValue("modifydamagetype"));
                    if (!showDamageType)
                        damageTypeCombo.SelectedItem = null;
                    if (!showDamageTargetType)
                        damageTargetTypeAcb.Text = "";
                }
                modifyTypeAcb.TextChanged += async (_, _) => { RefreshConditionalModifyFields(); if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                damageTypeCombo.SelectionChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                damageTargetTypeAcb.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                RefreshConditionalModifyFields();
                state.AdditionalFieldControls["modifytype"] = modifyTypeAcb;
                state.AdditionalFieldControls["modifydamagetype"] = damageTypeCombo;
                state.AdditionalFieldControls["modifydamagetargettype"] = damageTargetTypeAcb;

                var modeRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                var modeOptions = inverseAura
                    ? new[] { "Rate By Type" }
                    : new[] { "Multiplier", "Amount" };
                var modeCombo = new ComboBox
                {
                    ItemsSource = modeOptions,
                    SelectedItem = mode.Replace("Modify ", ""),
                    Width = 140,
                    IsEnabled = !_isReadOnly && !inverseAura,
                    Margin = new Thickness(8, 0, 0, 0)
                };
                modifyRow.Children.Add(modeCombo);
                modifyTypeAcb.SelectionChanged += (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    foreach (var tag in new[] { "modifyamount", "modifymultiplier", "modifybase", "modifyexponent" })
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                    state.AdditionalFieldControls.Remove("modifyamount");
                    state.AdditionalFieldControls.Remove("modifymultiplier");

                    if (inverseAura)
                    {
                        state.SelectedFlagTags.Add("modifyratebytype");
                        state.ForcedVisibleFieldTags.Add("rate");
                        if (ProtoConstants.GetModifyTypeValueMode(modifyTypeAcb.Text?.Trim() ?? "") == ProtoConstants.ModifyTypeValueMode.Multiplier)
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifybase", "1.0");
                        return;
                    }

                    var defaultMode = ProtoConstants.GetModifyTypeValueMode(modifyTypeAcb.Text?.Trim() ?? "") == ProtoConstants.ModifyTypeValueMode.Amount
                        ? "Amount"
                        : "Multiplier";
                    state.CustomValues["likebonus.mode"] = defaultMode;
                    modeCombo.SelectedItem = defaultMode;
                };
                var modifierValueTb = new TextBox { Text = mode.Contains("Multiplier", StringComparison.OrdinalIgnoreCase) ? GetValue("modifymultiplier") : GetValue("modifyamount"), Width = 120, IsEnabled = !_isReadOnly };
                AttachProtoActionDecimalBehavior(modifierValueTb);
                var modifierValueGroup = CreateLabeledFieldGroup("Value:", modifierValueTb);
                modifierValueGroup.Margin = new Thickness(8, 0, 0, 0);
                modifyRow.Children.Add(modifierValueGroup);
                state.AdditionalFieldControls["modifyamount"] = modifierValueTb;
                state.AdditionalFieldControls["modifymultiplier"] = modifierValueTb;
                state.AdditionalFieldsContainer.Children.Add(modifyRow);

                void ApplyLikeBonusMode(bool clearUnused)
                {
                    var selectedMode = modeCombo.SelectedItem as string ?? "Amount";
                    var rateByType = selectedMode == "Rate By Type";
                    state.AdditionalFieldControls.Remove("modifyamount");
                    state.AdditionalFieldControls.Remove("modifymultiplier");
                    modifierValueGroup.IsVisible = !rateByType;
                    if (rateByType)
                    {
                        state.SelectedFlagTags.Add("modifyratebytype");
                        state.ForcedVisibleFieldTags.Add("rate");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(
                            state.Model,
                            "modifybase",
                            ProtoConstants.GetModifyTypeValueMode(modifyTypeAcb.Text?.Trim() ?? "") == ProtoConstants.ModifyTypeValueMode.Multiplier ? "1.0" : "");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifyexponent", "");
                        if (clearUnused)
                        {
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifyamount", "");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifymultiplier", "");
                        }
                    }
                    else
                    {
                        state.AdditionalFieldControls[selectedMode == "Multiplier" ? "modifymultiplier" : "modifyamount"] = modifierValueTb;
                        state.SelectedFlagTags.Remove("modifyratebytype");
                        state.ForcedVisibleFieldTags.Remove("rate");
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "rate", []);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifyexponent", "1.0");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifybase", selectedMode == "Multiplier" ? "1.0" : "");
                        if (clearUnused)
                        {
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, selectedMode == "Multiplier" ? "modifyamount" : "modifymultiplier", "");
                        }
                    }
                    RenderProtoActionFlags(state);
                }
                ApplyLikeBonusMode(false);
                modifierValueTb.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                modeCombo.SelectionChanged += async (_, _) =>
                {
                    if (_isPopulating) return;
                    state.CustomValues["likebonus.mode"] = modeCombo.SelectedItem as string ?? "Amount";
                    var selectedMode = modeCombo.SelectedItem as string ?? "Amount";
                    if (selectedMode is "Amount" or "Multiplier")
                    {
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(
                            state.Model,
                            selectedMode == "Multiplier" ? "modifymultiplier" : "modifyamount",
                            modifierValueTb.Text?.Trim() ?? "");
                    }
                    if (!await CheckStartLocalMod()) return;
                    ApplyLikeBonusMode(true);
                    MarkDirty();
                    RefreshProtoActionMetadataPanels(state);
                };

                var showRateCap = !string.IsNullOrWhiteSpace(GetValue("modifyratecap")) || state.ForcedVisibleFieldTags.Contains("modifyratecap");
                var showTargetLimit = !string.IsNullOrWhiteSpace(GetValue("modifytargetlimit")) || state.ForcedVisibleFieldTags.Contains("modifytargetlimit");
                if (mode == "Rate By Type" && showRateCap)
                {
                    modeRow.Children.Add(CreateLabeledFieldGroup("Modify Rate Cap:", CreateSimpleEditor("modifyratecap")));
                    if (!_isReadOnly)
                    {
                        var remove = new Button { Classes = { "remove-button" } };
                        remove.Click += async (_, _) => { if (await CheckStartLocalMod()) { state.ForcedVisibleFieldTags.Remove("modifyratecap"); state.AdditionalFieldControls.Remove("modifyratecap"); ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifyratecap", ""); RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                        modeRow.Children.Add(remove);
                    }
                }
                if (mode != "Rate By Type" && showTargetLimit)
                {
                    modeRow.Children.Add(CreateLabeledFieldGroup("Max Targets:", CreateSimpleEditor("modifytargetlimit")));
                    if (!_isReadOnly)
                    {
                        var remove = new Button { Classes = { "remove-button" }, Margin = new Thickness(2, 0, 0, 0) };
                        remove.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            state.ForcedVisibleFieldTags.Remove("modifytargetlimit");
                            state.AdditionalFieldControls.Remove("modifytargetlimit");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifytargetlimit", "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        modeRow.Children.Add(remove);
                    }
                }
                if (!_isReadOnly && mode == "Rate By Type" && !showRateCap)
                {
                    var button = new Button { Content = "Modify Rate Cap", Classes = { "add-component" } };
                    button.Click += async (_, _) => { if (await CheckStartLocalMod()) { state.ForcedVisibleFieldTags.Add("modifyratecap"); RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                    modeRow.Children.Add(button);
                }
                if (!_isReadOnly && mode != "Rate By Type" && !showTargetLimit)
                {
                    var button = new Button { Content = "Max Targets", Classes = { "add-component" } };
                    button.Click += async (_, _) => { if (await CheckStartLocalMod()) { state.ForcedVisibleFieldTags.Add("modifytargetlimit"); RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                    modeRow.Children.Add(button);
                }

                if (modeRow.Children.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(modeRow);

                var targetAttachmentVisible = state.ForcedVisibleFieldTags.Contains("targetattachment") || !string.IsNullOrWhiteSpace(GetValue("targetattachment")) || !string.IsNullOrWhiteSpace(GetValue("targetattachmentbone"));
                if (targetAttachmentVisible)
                {
                    var targetAttachmentRow = CreateCompactRow(("targetattachment", "Target Attachment"), ("targetattachmentbone", "Bone"));
                    if (!_isReadOnly)
                    {
                        var remove = new Button { Classes = { "remove-button" } };
                        remove.Click += async (_, _) => { if (await CheckStartLocalMod()) { foreach (var tag in new[] { "targetattachment", "targetattachmentbone" }) { state.ForcedVisibleFieldTags.Remove(tag); state.AdditionalFieldControls.Remove(tag); ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, ""); } RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                        targetAttachmentRow.Children.Add(remove);
                    }
                    state.AdditionalFieldsContainer.Children.Add(targetAttachmentRow);
                }
                else if (!_isReadOnly)
                {
                    var button = new Button { Content = "Add Target Attachment", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left };
                    button.Click += async (_, _) => { if (await CheckStartLocalMod()) { state.ForcedVisibleFieldTags.Add("targetattachment"); state.ForcedVisibleFieldTags.Add("targetattachmentbone"); RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                    state.AdditionalFieldsContainer.Children.Add(button);
                }
            }
            else if (IsSelfModifyActionType(actionType))
            {
                var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
                    .Select(ProtoConstants.GetModifyTypeDisplayName)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var currentModifyTypeValue = currentValues.TryGetValue("modifytype", out var currentModifyType)
                    ? currentModifyType
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifytype");
                var currentModifyAmountValue = currentValues.TryGetValue("modifyamount", out var currentModifyAmount)
                    ? currentModifyAmount
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifyamount");
                var currentModifyMultiplierValue = currentValues.TryGetValue("modifymultiplier", out var currentModifyMultiplier)
                    ? currentModifyMultiplier
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifymultiplier");
                var useMultiplier = !string.IsNullOrWhiteSpace(currentModifyMultiplierValue) ||
                                    (string.IsNullOrWhiteSpace(currentModifyAmountValue) &&
                                     ProtoConstants.GetModifyTypeValueMode(currentModifyTypeValue ?? "") == ProtoConstants.ModifyTypeValueMode.Multiplier);

                var modifyGrid = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 220, 160, Auto, 140"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                modifyGrid.Children.Add(new TextBlock
                {
                    Text = "Modify:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                var modifyTypeDisplayValue = ProtoConstants.GetModifyTypeDisplayName(ProtoConstants.GetModifyTypeValue(currentModifyTypeValue ?? ""));
                var modifyTypeAcb = new AutoCompleteBox
                {
                    Text = modifyTypeDisplayValue,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly,
                    Width = 220
                };
                ConfigureStrictSuggestionAutoComplete(modifyTypeAcb, modifyTypeSuggestions, modifyTypeDisplayValue);
                modifyTypeAcb.TextChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };
                Grid.SetColumn(modifyTypeAcb, 1);
                modifyGrid.Children.Add(modifyTypeAcb);
                state.AdditionalFieldControls["modifytype"] = modifyTypeAcb;

                var modifyDamageTypeRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 8, Margin = new Thickness(0, 2, 0, 2) };
                modifyDamageTypeRow.Children.Add(new TextBlock { Text = "Damage Type:", VerticalAlignment = VerticalAlignment.Center });
                var currentModifyDamageTypeValue = currentValues.TryGetValue("modifydamagetype", out var currentModifyDamageType)
                    ? currentModifyDamageType
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifydamagetype");
                var modifyDamageTypeAcb = new ComboBox
                {
                    IsEnabled = !_isReadOnly,
                    Width = 100
                };
                RefreshProtoActionDamageTypeCombo(modifyDamageTypeAcb, modifyTypeDisplayValue, currentModifyDamageTypeValue);
                modifyDamageTypeRow.Children.Add(modifyDamageTypeAcb);

                var modifyDamageTargetTypeRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 8, Margin = new Thickness(0, 2, 0, 2) };
                modifyDamageTargetTypeRow.Children.Add(new TextBlock { Text = "Target:", VerticalAlignment = VerticalAlignment.Center });
                var currentDamageTargetType = currentValues.TryGetValue("modifydamagetargettype", out var currentModifyDamageTargetType)
                    ? currentModifyDamageTargetType
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifydamagetargettype");
                var damageTargetSuggestions = GetKnownUnitTypeNames()
                    .Concat(GetAvailableTrainUnitNames())
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var modifyDamageTargetTypeAcb = new AutoCompleteBox
                {
                    Text = currentDamageTargetType,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly,
                    Width = 180
                };
                ConfigureStrictSuggestionAutoComplete(modifyDamageTargetTypeAcb, damageTargetSuggestions, currentDamageTargetType);
                modifyDamageTargetTypeRow.Children.Add(modifyDamageTargetTypeAcb);
                void RefreshSelfModifyDamageTypeVisibility()
                {
                    var modifyType = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                    var showDamageType = modifyType is "ArmorSpecific" or "DamageSpecific";
                    var showDamageTargetType = modifyType.Equals("DamageByTargetType", StringComparison.OrdinalIgnoreCase);
                    modifyDamageTypeRow.IsVisible = showDamageType;
                    modifyDamageTargetTypeRow.IsVisible = showDamageTargetType;
                    RefreshProtoActionDamageTypeCombo(modifyDamageTypeAcb, modifyType, currentModifyDamageTypeValue);
                    if (!showDamageType)
                        modifyDamageTypeAcb.SelectedItem = null;
                    if (!showDamageTargetType)
                        modifyDamageTargetTypeAcb.Text = "";
                }
                modifyDamageTypeAcb.SelectionChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                modifyDamageTargetTypeAcb.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                modifyTypeAcb.TextChanged += (_, _) => RefreshSelfModifyDamageTypeVisibility();
                RefreshSelfModifyDamageTypeVisibility();
                state.AdditionalFieldControls["modifydamagetype"] = modifyDamageTypeAcb;
                state.AdditionalFieldControls["modifydamagetargettype"] = modifyDamageTargetTypeAcb;

                var modeCombo = new ComboBox
                {
                    ItemsSource = new[] { "Modify Amount", "Modify Multiplier" },
                    SelectedItem = useMultiplier ? "Modify Multiplier" : "Modify Amount",
                    IsEnabled = !_isReadOnly,
                    Width = 160
                };
                Grid.SetColumn(modeCombo, 2);
                modifyGrid.Children.Add(modeCombo);

                var valueLabel = new TextBlock
                {
                    Text = "Value:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(12, 4, 10, 4)
                };
                Grid.SetColumn(valueLabel, 3);
                modifyGrid.Children.Add(valueLabel);

                var valueHost = new Grid();
                Grid.SetColumn(valueHost, 4);
                modifyGrid.Children.Add(valueHost);

                var modifyAmountTb = new TextBox
                {
                    Text = currentModifyAmountValue,
                    IsEnabled = !_isReadOnly,
                    Width = 140
                };
                AttachProtoActionDecimalBehavior(modifyAmountTb);
                modifyAmountTb.TextChanged += async (_, _) =>
                {
                    if (_isPopulating || !string.Equals(modeCombo.SelectedItem as string, "Modify Amount", StringComparison.OrdinalIgnoreCase))
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                var modifyMultiplierTb = new TextBox
                {
                    Text = currentModifyMultiplierValue,
                    IsEnabled = !_isReadOnly,
                    Width = 140
                };
                AttachProtoActionDecimalBehavior(modifyMultiplierTb);
                modifyMultiplierTb.TextChanged += async (_, _) =>
                {
                    if (_isPopulating || !string.Equals(modeCombo.SelectedItem as string, "Modify Multiplier", StringComparison.OrdinalIgnoreCase))
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                void RenderSelfModifyValueEditor()
                {
                    var useModifyMultiplier = string.Equals(modeCombo.SelectedItem as string, "Modify Multiplier", StringComparison.OrdinalIgnoreCase);
                    if (useModifyMultiplier)
                    {
                        if (string.IsNullOrWhiteSpace(modifyMultiplierTb.Text))
                            modifyMultiplierTb.Text = modifyAmountTb.Text;
                        modifyAmountTb.Text = "";
                        valueHost.Children.Clear();
                        valueHost.Children.Add(modifyMultiplierTb);
                    }
                    else
                    {
                        if (string.IsNullOrWhiteSpace(modifyAmountTb.Text))
                            modifyAmountTb.Text = modifyMultiplierTb.Text;
                        modifyMultiplierTb.Text = "";
                        valueHost.Children.Clear();
                        valueHost.Children.Add(modifyAmountTb);
                    }
                }

                state.AdditionalFieldControls["modifyamount"] = modifyAmountTb;
                state.AdditionalFieldControls["modifymultiplier"] = modifyMultiplierTb;
                RenderSelfModifyValueEditor();

                modeCombo.SelectionChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    RenderSelfModifyValueEditor();
                    MarkDirty();
                };

                state.AdditionalFieldsContainer.Children.Add(modifyGrid);
                state.AdditionalFieldsContainer.Children.Add(modifyDamageTypeRow);
                state.AdditionalFieldsContainer.Children.Add(modifyDamageTargetTypeRow);
            }
            else if (IsReleaseSkyLanternActionType(actionType))
            {
                var animRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 200"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                animRow.Children.Add(new TextBlock
                {
                    Text = "Animation:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                var animEditor = CreateSimpleEditor("anim");
                animEditor.Width = 200;
                Grid.SetColumn(animEditor, 1);
                animRow.Children.Add(animEditor);

                var timingRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                var modifyDurationEditor = CreateSimpleEditor("modifyduration");
                timingRow.Children.Add(CreateLabeledFieldGroup(
                    "Modify Duration (ms):",
                    modifyDurationEditor));
                var timerEditor = CreateSimpleEditor("timer");
                if (timerEditor is TextBox timerTb)
                    timerTb.Width = 140;
                else if (timerEditor is AutoCompleteBox timerAcb)
                    timerAcb.Width = 140;
                timingRow.Children.Add(CreateLabeledFieldGroup("Timer (s):", timerEditor));
                state.AdditionalFieldsContainer.Children.Add(timingRow);
            }
            else if (IsAutoRangedModifyActionType(actionType) || IsAreaMutateActionType(actionType) || IsAutoRangedAttachActionType(actionType))
            {
                var isAutoRangedModify = IsAutoRangedModifyActionType(actionType);
                string GetAutoRangedValue(string tag) => currentValues.TryGetValue(tag, out var currentValue)
                    ? currentValue
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                var autoRangedUnitTypeSuggestions = GetKnownUnitTypeNames();
                if (isAutoRangedModify)
                {
                primaryFieldTags.RemoveAll(tag => new[]
                {
                    "modifytype", "modifyamount", "modifymultiplier", "modifydamagetype", "modifydamagetargettype",
                    "modifystacklimit", "modifytargetlimit", "slowhealmultiplier", "timer", "modifyduration",
                    "modifyupdateinterval", "infectionrange", "infectionrof", "infectionchance", "infectionduration",
                    "infectionattachment", "infectionattachmentbone", "modifyabstracttype", "forbidabstracttype",
                    "modifyprotoid", "forbidunittype"
                }.Contains(tag, StringComparer.OrdinalIgnoreCase));

                var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
                    .Select(ProtoConstants.GetModifyTypeDisplayName)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var modifyTypeValue = GetAutoRangedValue("modifytype");
                var modifyTypeRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                modifyTypeRow.Children.Add(new TextBlock { Text = "Modify:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                var modifyTypeAcb = new AutoCompleteBox
                {
                    Text = ProtoConstants.GetModifyTypeDisplayName(ProtoConstants.GetModifyTypeValue(modifyTypeValue)),
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly,
                    Width = 230
                };
                ConfigureStrictSuggestionAutoComplete(modifyTypeAcb, modifyTypeSuggestions, modifyTypeAcb.Text ?? "");
                modifyTypeRow.Children.Add(modifyTypeAcb);
                state.AdditionalFieldControls["modifytype"] = modifyTypeAcb;

                var damageTypePanel = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(16, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                damageTypePanel.Children.Add(new TextBlock { Text = "Damage Type:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
                var damageTypeEditor = new ComboBox { Width = 140, IsEnabled = !_isReadOnly };
                RefreshProtoActionDamageTypeCombo(damageTypeEditor, modifyTypeAcb.Text, GetAutoRangedValue("modifydamagetype"));
                damageTypeEditor.SelectionChanged += async (_, _) =>
                {
                    if (!_isPopulating && await CheckStartLocalMod())
                        MarkDirty();
                };
                state.AdditionalFieldControls["modifydamagetype"] = damageTypeEditor;
                damageTypePanel.Children.Add(damageTypeEditor);
                modifyTypeRow.Children.Add(damageTypePanel);

                var damageTargetTypePanel = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(16, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                damageTargetTypePanel.Children.Add(new TextBlock
                {
                    Text = "Target:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                var damageTargetTypeAcb = new AutoCompleteBox
                {
                    Text = GetAutoRangedValue("modifydamagetargettype"),
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly,
                    Width = 180
                };
                var damageTargetSuggestions = autoRangedUnitTypeSuggestions
                    .Concat(GetAvailableTrainUnitNames())
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                ConfigureStrictSuggestionAutoComplete(damageTargetTypeAcb, damageTargetSuggestions, damageTargetTypeAcb.Text ?? "");
                damageTargetTypeAcb.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                state.AdditionalFieldControls["modifydamagetargettype"] = damageTargetTypeAcb;
                damageTargetTypePanel.Children.Add(damageTargetTypeAcb);
                modifyTypeRow.Children.Add(damageTargetTypePanel);

                var amountValue = GetAutoRangedValue("modifyamount");
                var multiplierValue = GetAutoRangedValue("modifymultiplier");
                var savedMode = state.CustomValues.GetValueOrDefault("autorangedmodify.value.mode", "");
                var mode = savedMode is "Multiplier" or "Amount"
                    ? savedMode
                    : !string.IsNullOrWhiteSpace(multiplierValue)
                    ? "Multiplier"
                    : !string.IsNullOrWhiteSpace(amountValue)
                        ? "Amount"
                        : ProtoConstants.GetModifyTypeValueMode(modifyTypeValue) == ProtoConstants.ModifyTypeValueMode.Amount
                            ? "Amount"
                            : "Multiplier";
                var modeCombo = new ComboBox
                {
                    ItemsSource = new[] { "Multiplier", "Amount" },
                    SelectedItem = mode,
                    IsEnabled = !_isReadOnly,
                    Width = 140
                };
                modifyTypeRow.Children.Add(modeCombo);
                modifyTypeRow.Children.Add(new TextBlock { Text = "Value:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(12, 4, 8, 4) });
                var modifierValueEditor = new TextBox
                {
                    Text = mode == "Multiplier" ? multiplierValue : amountValue,
                    IsEnabled = !_isReadOnly,
                    Width = 120
                };
                AttachProtoActionDecimalBehavior(modifierValueEditor, () =>
                    string.Equals(modeCombo.SelectedItem as string, "Amount", StringComparison.OrdinalIgnoreCase));
                modifyTypeRow.Children.Add(modifierValueEditor);
                var isInitialHealRate = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "")
                    .Equals("HealRate", StringComparison.OrdinalIgnoreCase);
                if (isInitialHealRate)
                {
                    var slowHealValue = GetAutoRangedValue("slowhealmultiplier");
                    var slowHealPanel = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(16, 0, 0, 0), VerticalAlignment = VerticalAlignment.Center };
                    if (state.ForcedVisibleFieldTags.Contains("slowhealmultiplier") || !string.IsNullOrWhiteSpace(slowHealValue))
                    {
                        slowHealPanel.Children.Add(new TextBlock { Text = "Slow Heal Multiplier:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
                        var slowHealEditor = CreateSimpleEditor("slowhealmultiplier");
                        if (slowHealEditor is TextBox slowHealTextBox) slowHealTextBox.Width = 100;
                        slowHealPanel.Children.Add(slowHealEditor);
                        if (!_isReadOnly)
                        {
                            var removeSlowHealButton = new Button { Classes = { "remove-button" }, Margin = new Thickness(6, 0, 0, 0) };
                            removeSlowHealButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod()) return;
                                state.ForcedVisibleFieldTags.Remove("slowhealmultiplier");
                                state.AdditionalFieldControls.Remove("slowhealmultiplier");
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "slowhealmultiplier", "");
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            slowHealPanel.Children.Add(removeSlowHealButton);
                        }
                    }
                    else if (!_isReadOnly)
                    {
                        var addSlowHealButton = new Button { Content = "Slow Heal Multiplier", Classes = { "add-component" } };
                        addSlowHealButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            state.ForcedVisibleFieldTags.Add("slowhealmultiplier");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        slowHealPanel.Children.Add(addSlowHealButton);
                    }
                    modifyTypeRow.Children.Add(slowHealPanel);
                }
                state.AdditionalFieldsContainer.Children.Add(modifyTypeRow);
                void ApplyAutoRangedModifyValueMode(bool clearUnused)
                {
                    var selectedMode = modeCombo.SelectedItem as string ?? "Multiplier";
                    state.AdditionalFieldControls.Remove("modifyamount");
                    state.AdditionalFieldControls.Remove("modifymultiplier");
                    state.AdditionalFieldControls[selectedMode == "Multiplier" ? "modifymultiplier" : "modifyamount"] = modifierValueEditor;
                    if (clearUnused)
                    {
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, selectedMode == "Multiplier" ? "modifyamount" : "modifymultiplier", "");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, selectedMode == "Multiplier" ? "modifymultiplier" : "modifyamount", modifierValueEditor.Text?.Trim() ?? "");
                    }
                }
                ApplyAutoRangedModifyValueMode(false);
                modifierValueEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                modeCombo.SelectionChanged += async (_, _) =>
                {
                    if (_isPopulating || !await CheckStartLocalMod())
                        return;

                    state.CustomValues["autorangedmodify.value.mode"] = modeCombo.SelectedItem as string ?? "Multiplier";
                    ApplyAutoRangedModifyValueMode(true);
                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                };

                void RefreshAutoRangedModifyTypeFields()
                {
                    var type = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                    RefreshProtoActionDamageTypeCombo(damageTypeEditor, type);
                    damageTypePanel.IsVisible = type is "ArmorSpecific" or "DamageSpecific";
                    damageTargetTypePanel.IsVisible = type.Equals("DamageByTargetType", StringComparison.OrdinalIgnoreCase);
                }
                modifyTypeAcb.TextChanged += async (_, _) =>
                {
                    RefreshAutoRangedModifyTypeFields();
                    var normalizedModifyType = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                    var previousModifyType = state.CustomValues.GetValueOrDefault("autorangedmodify.modifytype", "");
                    var modifyTypeChanged = !string.Equals(previousModifyType, normalizedModifyType, StringComparison.OrdinalIgnoreCase);
                    var hasConfirmedModifyTypeSelection = modifyTypeAcb.SelectedItem is string selectedModifyType &&
                        selectedModifyType.Equals(modifyTypeAcb.Text?.Trim(), StringComparison.OrdinalIgnoreCase);
                    if (modifyTypeChanged && hasConfirmedModifyTypeSelection)
                    {
                        if (normalizedModifyType is not "ArmorSpecific" and not "DamageSpecific")
                        {
                            state.AdditionalFieldControls.Remove("modifydamagetype");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifydamagetype", "");
                        }
                        if (!normalizedModifyType.Equals("DamageByTargetType", StringComparison.OrdinalIgnoreCase))
                        {
                            state.AdditionalFieldControls.Remove("modifydamagetargettype");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifydamagetargettype", "");
                        }
                        if (previousModifyType.Equals("InventoryAmount", StringComparison.OrdinalIgnoreCase) &&
                            !normalizedModifyType.Equals("InventoryAmount", StringComparison.OrdinalIgnoreCase))
                        {
                            state.StructuredFieldRows.Remove("rate");
                            ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "rate", []);
                        }
                        if (previousModifyType.Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase) &&
                            !normalizedModifyType.Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase))
                        {
                            state.EmpowerTargetStates.Clear();
                            foreach (var sectionTag in EmpowerSectionTags)
                            {
                                state.ForcedVisibleFieldTags.Remove(sectionTag);
                                RemoveProtoActionAdditionalElement(state.Model, sectionTag);
                            }
                        }
                        var defaultMode = ProtoConstants.GetModifyTypeValueMode(normalizedModifyType) == ProtoConstants.ModifyTypeValueMode.Amount
                            ? "Amount"
                            : "Multiplier";
                        state.CustomValues["autorangedmodify.modifytype"] = normalizedModifyType;
                        state.CustomValues["autorangedmodify.value.mode"] = defaultMode;
                        if (!string.Equals(modeCombo.SelectedItem as string, defaultMode, StringComparison.OrdinalIgnoreCase))
                            modeCombo.SelectedItem = defaultMode;
                    }
                    if (!_isPopulating && await CheckStartLocalMod())
                    {
                        MarkDirty();
                        if (modifyTypeChanged && hasConfirmedModifyTypeSelection)
                            RefreshProtoActionMetadataPanels(state);
                    }
                };
                state.CustomValues["autorangedmodify.modifytype"] = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                RefreshAutoRangedModifyTypeFields();

                var stackRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                void AddOptionalLimit(string tag, string label)
                {
                    var isVisible = state.ForcedVisibleFieldTags.Contains(tag) || !string.IsNullOrWhiteSpace(GetAutoRangedValue(tag));
                    if (!isVisible)
                    {
                        if (!_isReadOnly)
                        {
                            var addButton = new Button { Content = label, Classes = { "add-component" }, Margin = new Thickness(stackRow.Children.Count > 0 ? 10 : 0, 0, 0, 0) };
                            addButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;

                                state.ForcedVisibleFieldTags.Add(tag);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            stackRow.Children.Add(addButton);
                        }
                        return;
                    }

                    stackRow.Children.Add(new TextBlock { Text = label + ":", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(stackRow.Children.Count > 0 ? 16 : 0, 4, 8, 4) });
                    var editor = CreateSimpleEditor(tag);
                    if (editor is TextBox textBox) textBox.Width = 100;
                    stackRow.Children.Add(editor);
                    if (!_isReadOnly)
                    {
                        var removeButton = new Button { Classes = { "remove-button" } };
                        removeButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.ForcedVisibleFieldTags.Remove(tag);
                            state.AdditionalFieldControls.Remove(tag);
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        stackRow.Children.Add(removeButton);
                    }
                }
                AddOptionalLimit("modifystacklimit", "Stack Limit");
                AddOptionalLimit("modifytargetlimit", "Target Limit");

                void AddFlagCheckBox(string tag, string label)
                {
                    var checkBox = new CheckBox
                    {
                        Content = label,
                        IsChecked = state.SelectedFlagTags.Contains(tag),
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(16, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    checkBox.IsCheckedChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod())
                            return;

                        if (checkBox.IsChecked == true)
                            state.SelectedFlagTags.Add(tag);
                        else
                            state.SelectedFlagTags.Remove(tag);
                        RenderProtoActionFlags(state);
                        MarkDirty();
                    };
                    stackRow.Children.Add(checkBox);
                }
                if (!_isReadOnly || state.SelectedFlagTags.Contains("nostack"))
                    AddFlagCheckBox("nostack", "No Stack");
                if (!_isReadOnly || state.SelectedFlagTags.Contains("nostackignorepuid"))
                    AddFlagCheckBox("nostackignorepuid", "Ignore PUID");
                if (stackRow.Children.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(stackRow);

                var isHealRate = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "")
                    .Equals("HealRate", StringComparison.OrdinalIgnoreCase);
                if (isHealRate)
                {
                    var bonusSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 2) };
                    bonusSection.Children.Add(new TextBlock { Text = "Damage Bonuses:", FontWeight = FontWeight.Bold, Margin = new Thickness(0, 4, 0, 2) });
                    var bonusRowsPanel = new WrapPanel { Orientation = Orientation.Horizontal };
                    bonusSection.Children.Add(bonusRowsPanel);
                    var existingBonuses = state.BonusRows.Count > 0
                        ? state.BonusRows.Select(row => (Type: row.TypeAcb.Text?.Trim() ?? "", Value: row.ValTb.Text?.Trim() ?? "")).ToList()
                        : effectiveAction.DamageBonuses.Select(bonus => (Type: bonus.UnitType, Value: bonus.Multiplier)).ToList();
                    state.BonusRows.Clear();
                    var bonusSuggestions = GetKnownUnitTypeNames()
                        .Concat(_barData?.UnitNames ?? [])
                        .Where(value => !string.IsNullOrWhiteSpace(value))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    void AddAutoRangedBonusRow(string type, string value)
                    {
                        var row = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 6, Margin = new Thickness(0, 0, 8, 0) };
                        var typeEditor = new AutoCompleteBox { Text = type, FilterMode = AutoCompleteFilterMode.Contains, ItemsSource = bonusSuggestions, Width = 180, IsEnabled = !_isReadOnly };
                        EnableDropdownAutoComplete(typeEditor);
                        var valueEditor = new TextBox { Text = value, Width = 80, IsEnabled = !_isReadOnly };
                        AttachProtoActionDecimalBehavior(valueEditor);
                        row.Children.Add(typeEditor);
                        row.Children.Add(valueEditor);
                        var rowState = new BonusRowState { RowPanel = row, TypeAcb = typeEditor, ValTb = valueEditor };
                        state.BonusRows.Add(rowState);
                        if (!_isReadOnly)
                        {
                            var removeButton = new Button { Classes = { "remove-button" } };
                            removeButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod()) return;
                                state.BonusRows.Remove(rowState);
                                bonusRowsPanel.Children.Remove(row);
                                MarkDirty();
                            };
                            row.Children.Add(removeButton);
                        }
                        bonusRowsPanel.Children.Add(row);
                    }
                    foreach (var bonus in existingBonuses)
                        AddAutoRangedBonusRow(bonus.Type, bonus.Value);
                    if (!_isReadOnly)
                    {
                        var addBonusButton = new Button { Content = "+ Bonus", Classes = { "add-component" }, Margin = new Thickness(0, 2, 0, 0), HorizontalAlignment = HorizontalAlignment.Left };
                        addBonusButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            AddAutoRangedBonusRow("AbstractInfantry", "1.0");
                            MarkDirty();
                        };
                        bonusSection.Children.Add(addBonusButton);
                    }
                    state.AdditionalFieldsContainer.Children.Add(bonusSection);
                }

                var isInventoryAmount = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "")
                    .Equals("InventoryAmount", StringComparison.OrdinalIgnoreCase);
                if (isInventoryAmount)
                {
                    var rateSection = new StackPanel { Spacing = 3, Margin = new Thickness(0, 2, 0, 2) };
                    rateSection.Children.Add(new TextBlock { Text = "Rate:", FontWeight = FontWeight.Bold });
                    var rateRowsPanel = new StackPanel { Spacing = 3 };
                    rateSection.Children.Add(rateRowsPanel);
                    var rateEntries = GetCurrentStructuredEntries("rate");
                    state.StructuredFieldRows["rate"] = [];
                    var rateSuggestions = GetKnownUnitTypeNames()
                        .Concat(GetAvailableTrainUnitNames())
                        .Where(value => !string.IsNullOrWhiteSpace(value))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    void AddAutoRangedRateRow(ProtoActionStructuredFieldEntry? entry = null)
                    {
                        var row = new WrapPanel { Orientation = Orientation.Horizontal };
                        row.Children.Add(new TextBlock { Text = "Type:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
                        var initialType = entry != null && entry.Attributes.TryGetValue("type", out var entryType) ? entryType : "";
                        var tacticsRateEntry = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsRateAction)
                            ? ProtoXmlHandler.GetProtoActionStructuredFieldEntries(tacticsRateAction, "rate")
                                .FirstOrDefault(candidate => candidate.Attributes.TryGetValue("type", out var candidateType) &&
                                    candidateType.Equals(initialType, StringComparison.OrdinalIgnoreCase))
                            : null;
                        var protoRateEntry = ProtoXmlHandler.GetProtoActionStructuredFieldEntries(state.Model, "rate")
                            .FirstOrDefault(candidate => candidate.Attributes.TryGetValue("type", out var candidateType) &&
                                candidateType.Equals(initialType, StringComparison.OrdinalIgnoreCase));
                        var isInheritedRateType = tacticsRateEntry != null;
                        var typeEditor = new AutoCompleteBox { Text = initialType, FilterMode = AutoCompleteFilterMode.Contains, Width = 180, IsEnabled = !_isReadOnly };
                        ConfigureStrictSuggestionAutoComplete(typeEditor, rateSuggestions, initialType);
                        typeEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                        row.Children.Add(typeEditor);
                        if (tacticsRateEntry != null)
                        {
                            AddProtoActionSourceMarker(
                                state,
                                typeEditor,
                                GetProtoActionValueSource(initialType, protoRateEntry == null ? "" : initialType, initialType),
                                initialType);
                        }
                        var valueEditor = new TextBox { Text = entry?.Value ?? "1.0", Width = 90, IsEnabled = !_isReadOnly };
                        AttachProtoActionDecimalBehavior(valueEditor);
                        valueEditor.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        row.Children.Add(valueEditor);
                        var rowState = new ProtoActionStructuredFieldRowState { Tag = "rate", RowPanel = row, ValueTb = valueEditor, IncludeInSerialization = true };
                        rowState.AttributeEditors["type"] = typeEditor;
                        state.StructuredFieldRows["rate"].Add(rowState);
                        if (!_isReadOnly)
                        {
                            var removeButton = new Button { Classes = { "remove-button" }, Margin = new Thickness(6, 0, 0, 0) };
                            removeButton.Click += async (_, _) =>
                            {
                                if (isInheritedRateType)
                                {
                                    await new Prompt(
                                        PromptType.Error,
                                        "Inherited Attribute",
                                        $"Rate type '{initialType}' is defined by the linked tactics file and cannot be removed. You may override its value.")
                                        .ShowDialog(this);
                                    return;
                                }
                                if (!await CheckStartLocalMod()) return;
                                state.StructuredFieldRows["rate"].Remove(rowState);
                                rateRowsPanel.Children.Remove(row);
                                MarkDirty();
                            };
                            row.Children.Add(removeButton);
                        }
                        rateRowsPanel.Children.Add(row);
                    }
                    foreach (var entry in rateEntries)
                        AddAutoRangedRateRow(entry);
                    if (!_isReadOnly)
                    {
                        var addRateButton = new Button { Content = "Add Rate", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left };
                        addRateButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            AddAutoRangedRateRow();
                            MarkDirty();
                        };
                        rateSection.Children.Add(addRateButton);
                    }
                    state.AdditionalFieldsContainer.Children.Add(rateSection);
                }

                }

                var autoRangedProtoUnitSuggestions = GetAvailableTrainUnitNames();
                List<string> GetAutoRangedList(string tag)
                {
                    var stateKey = "autorangedmodify." + tag;
                    if (state.CustomValues.TryGetValue(stateKey, out var storedValues))
                    {
                        var values = storedValues.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList();
                        return IsAreaMutateActionType(actionType) && tag.Equals("modifyprotoid", StringComparison.OrdinalIgnoreCase)
                            ? values.TakeLast(1).ToList()
                            : values;
                    }

                    var entries = GetCurrentStructuredEntries(tag)
                        .Select(entry => entry.Value?.Trim() ?? "")
                        .Where(value => !string.IsNullOrWhiteSpace(value))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    return IsAreaMutateActionType(actionType) && tag.Equals("modifyprotoid", StringComparison.OrdinalIgnoreCase)
                        ? entries.TakeLast(1).ToList()
                        : entries;
                }
                WrapPanel CreateAutoRangedListRow(string tag, string label, IReadOnlyList<string> suggestions, List<string> values)
                {
                    var row = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                    row.Children.Add(new TextBlock { Text = label + ":", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                    var picker = new AutoCompleteBox
                    {
                        FilterMode = AutoCompleteFilterMode.Contains,
                        IsEnabled = !_isReadOnly,
                        MinWidth = 120,
                        MaxWidth = 200,
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    ConfigureStrictSuggestionAutoComplete(picker, suggestions.Where(value => !values.Contains(value, StringComparer.OrdinalIgnoreCase)).ToList(), "");
                    row.Children.Add(picker);
                    var tacticsEntries = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsListAction)
                        ? ProtoXmlHandler.GetProtoActionStructuredFieldEntries(tacticsListAction, tag)
                        : [];
                    foreach (var value in values)
                    {
                        var selectedValue = value;
                        var isInherited = tacticsEntries.Any(entry => string.Equals(
                            entry.Value?.Trim() ?? "",
                            selectedValue,
                            StringComparison.OrdinalIgnoreCase));
                        var source = isInherited
                            ? ProtoActionValueSource.TacticsInherited
                            : ProtoActionValueSource.ProtoOnly;
                        var tacticsValue = isInherited ? selectedValue : "";
                        var chip = CreateChip(selectedValue, async () =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            if (isInherited)
                            {
                                await new Prompt(
                                    PromptType.Error,
                                    "Inherited Attribute",
                                    $"{label} '{selectedValue}' is defined by the linked tactics file and cannot be deleted from the protoaction.")
                                    .ShowDialog(this);
                                return;
                            }

                            values.RemoveAll(item => item.Equals(selectedValue, StringComparison.OrdinalIgnoreCase));
                            state.CustomValues["autorangedmodify." + tag] = string.Join("|", values);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                            CommitChipAdditionAndRefreshXmlPreview();
                        }, source, tacticsValue);
                        row.Children.Add(chip);
                    }
                    async Task AddSelectedValueAsync()
                    {
                        if (_isPopulating || !await CheckStartLocalMod())
                            return;

                        var selectedValue = picker.Text?.Trim() ?? "";
                        if (string.IsNullOrWhiteSpace(selectedValue) || !suggestions.Contains(selectedValue, StringComparer.OrdinalIgnoreCase))
                            return;

                        if (IsAreaMutateActionType(actionType) && tag.Equals("modifyprotoid", StringComparison.OrdinalIgnoreCase))
                            values.Clear();
                        if (!values.Contains(selectedValue, StringComparer.OrdinalIgnoreCase))
                            values.Add(selectedValue);
                        state.CustomValues["autorangedmodify." + tag] = string.Join("|", values);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                        CommitChipAdditionAndRefreshXmlPreview();
                    }
                    picker.SelectionChanged += async (_, _) =>
                    {
                        if (picker.SelectedItem is string selectedValue)
                        {
                            picker.Text = selectedValue;
                            await AddSelectedValueAsync();
                        }
                    };
                    return row;
                }
                WrapPanel CreateAutoRangedUnitTypeReadOnlyRow(string tag, string label, IEnumerable<string> values)
                {
                    var row = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                    row.Children.Add(new TextBlock { Text = label + ":", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                    var tacticsEntries = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsListAction)
                        ? ProtoXmlHandler.GetProtoActionStructuredFieldEntries(tacticsListAction, tag)
                        : [];
                    foreach (var value in values)
                    {
                        var isInherited = tacticsEntries.Any(entry => string.Equals(
                            entry.Value?.Trim() ?? "",
                            value,
                            StringComparison.OrdinalIgnoreCase));
                        var chip = CreateChip(
                            value,
                            () => { },
                            isInherited ? ProtoActionValueSource.TacticsInherited : ProtoActionValueSource.ProtoOnly,
                            isInherited ? value : "");
                        row.Children.Add(chip);
                    }
                    return row;
                }
                // AreaMutate uses modifyprotoid as the transformation result, not a target filter.
                var mutateIntoValues = GetAutoRangedList("modifyprotoid");
                if (IsAreaMutateActionType(actionType) && (!_isReadOnly || mutateIntoValues.Count > 0))
                {
                    var mutateRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                    mutateRow.Children.Add(new TextBlock { Text = "Mutate into:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                    var mutateEditor = new AutoCompleteBox
                    {
                        Text = mutateIntoValues.LastOrDefault() ?? "",
                        FilterMode = AutoCompleteFilterMode.Contains,
                        IsEnabled = !_isReadOnly,
                        Width = _isReadOnly ? GetCompactReadOnlyEditorWidth(mutateIntoValues.LastOrDefault() ?? "") : 200
                    };
                    ConfigureStrictSuggestionAutoComplete(mutateEditor, autoRangedProtoUnitSuggestions, mutateEditor.Text ?? "");
                    mutateEditor.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating && await CheckStartLocalMod())
                            MarkDirty();
                    };
                    state.AdditionalFieldControls["modifyprotoid"] = mutateEditor;
                    mutateRow.Children.Add(mutateEditor);
                    state.AdditionalFieldsContainer.Children.Add(mutateRow);
                }
                if (IsAutoRangedAttachActionType(actionType))
                {
                    var attachValue = GetAutoRangedValue("attachprotounit");
                    if (!_isReadOnly || !string.IsNullOrWhiteSpace(attachValue))
                    {
                        var attachRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                        attachRow.Children.Add(new TextBlock { Text = "Attach Proto Unit:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                        var attachEditor = CreateSimpleEditor("attachprotounit");
                        if (attachEditor is TextBox attachTextBox) attachTextBox.Width = 200;
                        if (attachEditor is AutoCompleteBox attachAutoCompleteBox) attachAutoCompleteBox.Width = 200;
                        attachRow.Children.Add(attachEditor);
                        state.AdditionalFieldsContainer.Children.Add(attachRow);
                    }
                }
                var targetUnitTypes = GetAutoRangedList("modifyabstracttype");
                if (!_isReadOnly)
                    state.AdditionalFieldsContainer.Children.Add(CreateAutoRangedListRow("modifyabstracttype", "Target Unit Type", autoRangedUnitTypeSuggestions, targetUnitTypes));
                else if (targetUnitTypes.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(CreateAutoRangedUnitTypeReadOnlyRow("modifyabstracttype", "Target Unit Type", targetUnitTypes));
                var forbiddenUnitTypes = GetAutoRangedList("forbidabstracttype");
                if (!_isReadOnly)
                    state.AdditionalFieldsContainer.Children.Add(CreateAutoRangedListRow("forbidabstracttype", "Forbid Unit Type", autoRangedUnitTypeSuggestions, forbiddenUnitTypes));
                else if (forbiddenUnitTypes.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(CreateAutoRangedUnitTypeReadOnlyRow("forbidabstracttype", "Forbid Unit Type", forbiddenUnitTypes));

                WrapPanel? AddOptionalProtoUnitList(string tag, string label, WrapPanel closedButtonHost)
                {
                    var values = GetAutoRangedList(tag);
                    if (_isReadOnly)
                    {
                        if (values.Count > 0)
                            state.AdditionalFieldsContainer.Children.Add(CreateAutoRangedUnitTypeReadOnlyRow(tag, label, values));
                        return null;
                    }

                    if (values.Count > 0 || state.ForcedVisibleFieldTags.Contains(tag))
                    {
                        var openRow = CreateAutoRangedListRow(tag, label, autoRangedProtoUnitSuggestions, values);
                        state.AdditionalFieldsContainer.Children.Add(openRow);
                        return openRow;
                    }

                    var addButton = new Button { Content = label, Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 2, 0, 2) };
                    addButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Add(tag);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    closedButtonHost.Children.Add(addButton);
                    return null;
                }
                var protoUnitOptionButtons = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                state.AdditionalFieldsContainer.Children.Add(protoUnitOptionButtons);
                WrapPanel? targetProtoUnitRow = null;
                if (!IsAreaMutateActionType(actionType))
                    targetProtoUnitRow = AddOptionalProtoUnitList("modifyprotoid", "Target Proto Unit", protoUnitOptionButtons);
                var forbidProtoUnitButtonHost = targetProtoUnitRow != null
                    ? new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) }
                    : protoUnitOptionButtons;
                if (targetProtoUnitRow != null)
                    state.AdditionalFieldsContainer.Children.Add(forbidProtoUnitButtonHost);
                AddOptionalProtoUnitList("forbidunittype", "Forbid Proto Unit", forbidProtoUnitButtonHost);
                if (protoUnitOptionButtons.Children.Count == 0)
                    state.AdditionalFieldsContainer.Children.Remove(protoUnitOptionButtons);
                if (targetProtoUnitRow != null && forbidProtoUnitButtonHost.Children.Count == 0)
                    state.AdditionalFieldsContainer.Children.Remove(forbidProtoUnitButtonHost);

                var targetFlagOptions = new[]
                {
                    ("targetenemy", "Enemy"),
                    ("targetenemyincludenature", "Enemy Include Nature"),
                    ("targetnature", "Nature"),
                    ("targetnonally", "Non Ally"),
                    ("includeally", "Include Allies"),
                    ("includenature", "Include Nature"),
                    ("modifyself", "Include Source"),
                    ("modifyflyingunits", "Include Flying Units"),
                    ("includeunbuilt", "Include Unbuilt"),
                    ("targetunbuilt", "Target Unbuilt"),
                    ("modifyselfonly", "Source Only")
                };
                if (!_isReadOnly)
                {
                    var targetFlagsRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 2) };
                    targetFlagsRow.Children.Add(new TextBlock { Text = "Targets:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                    var targetFlagPicker = new ComboBox
                    {
                        ItemsSource = targetFlagOptions
                            .Where(option => !state.SelectedFlagTags.Contains(option.Item1))
                            .Select(option => option.Item2)
                            .ToList(),
                        IsEnabled = !_isReadOnly,
                        Width = 190
                    };
                    targetFlagsRow.Children.Add(targetFlagPicker);
                    foreach (var selectedTargetFlag in targetFlagOptions.Where(option => state.SelectedFlagTags.Contains(option.Item1)))
                    {
                        var targetFlag = selectedTargetFlag.Item1;
                        var protoFlagValue = GetProtoActionSimpleSourceValue(state.Model, targetFlag);
                        var tacticsFlagValue = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsTargetAction)
                            ? GetProtoActionSimpleSourceValue(tacticsTargetAction, targetFlag)
                            : "";
                        var flagSource = GetProtoActionValueSource("1", protoFlagValue, tacticsFlagValue);
                        var targetFlagChip = CreateChip(selectedTargetFlag.Item2, async () =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            // Removing an inherited target is a supported flag override. The shared
                            // flag serializer writes <flag>0</flag> when tactics enables the flag.
                            state.SelectedFlagTags.Remove(targetFlag);
                            RenderProtoActionFlags(state);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                            CommitChipAdditionAndRefreshXmlPreview();
                        }, flagSource, tacticsFlagValue);
                        targetFlagsRow.Children.Add(targetFlagChip);
                    }
                    targetFlagPicker.SelectionChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod() || targetFlagPicker.SelectedItem is not string selectedLabel)
                            return;

                        var targetFlag = targetFlagOptions.FirstOrDefault(option => option.Item2.Equals(selectedLabel, StringComparison.OrdinalIgnoreCase)).Item1;
                        if (string.IsNullOrWhiteSpace(targetFlag))
                            return;

                        state.SelectedFlagTags.Add(targetFlag);
                        RenderProtoActionFlags(state);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                        CommitChipAdditionAndRefreshXmlPreview();
                    };
                    state.AdditionalFieldsContainer.Children.Add(targetFlagsRow);
                }
                else
                {
                    var existingTargetFlags = targetFlagOptions
                        .Where(option => state.SelectedFlagTags.Contains(option.Item1))
                        .Select(option => option.Item2)
                        .ToList();
                    if (existingTargetFlags.Count > 0)
                        state.AdditionalFieldsContainer.Children.Add(CreateAutoRangedUnitTypeReadOnlyRow("", "Targets", existingTargetFlags));
                }

                if (isAutoRangedModify)
                {
                bool HasAutoRangedValue(string tag) => !string.IsNullOrWhiteSpace(GetAutoRangedValue(tag));
                void AddAutoRangedFlagCheckBox(Panel panel, string tag, string label)
                {
                    var checkBox = new CheckBox
                    {
                        Content = label,
                        IsChecked = state.SelectedFlagTags.Contains(tag),
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(12, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    state.CustomFlagControls[tag] = checkBox;
                    RegisterProtoActionFlagSourceControl(state, checkBox, tag);
                    checkBox.IsCheckedChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod()) return;
                        if (checkBox.IsChecked == true) state.SelectedFlagTags.Add(tag);
                        else state.SelectedFlagTags.Remove(tag);
                        RenderProtoActionFlags(state);
                        MarkDirty();
                    };
                    panel.Children.Add(checkBox);
                }
                void AddAutoRangedLabeledField(Panel panel, string tag, string label, double width = 100)
                {
                    var editor = CreateSimpleEditor(tag);
                    if (editor is TextBox textBox) textBox.Width = width;
                    if (editor is AutoCompleteBox autoCompleteBox) autoCompleteBox.Width = width;
                    if (editor is AssetPathEditor pathEditor)
                    {
                        pathEditor.Width = width;
                        pathEditor.Editor.Width = width;
                        pathEditor.Editor.MaxWidth = width;
                    }
                    panel.Children.Add(CreateLabeledFieldGroup(
                        label + ":",
                        editor,
                        new Thickness(12, 0, 0, 4)));
                }

                var showAdditionalProperties = state.CustomValues.GetValueOrDefault("autorangedmodify.additionalproperties", "0") == "1" ||
                    new[] { "timer", "modifyduration", "modifyupdateinterval" }.Any(HasAutoRangedValue) ||
                    state.SelectedFlagTags.Contains("modifyupdateintervalrandomness");
                if (showAdditionalProperties)
                {
                    var propertiesRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 2) };
                    propertiesRow.Children.Add(new TextBlock { Text = "Additional Properties", FontWeight = FontWeight.Bold, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 4, 4) });
                    AddAutoRangedLabeledField(propertiesRow, "timer", "Timer");
                    AddAutoRangedLabeledField(propertiesRow, "modifyduration", "Duration");
                    AddAutoRangedLabeledField(propertiesRow, "modifyupdateinterval", "Update Interval");
                    AddAutoRangedFlagCheckBox(propertiesRow, "modifyupdateintervalrandomness", "Random");
                    if (!_isReadOnly)
                    {
                        var removePropertiesButton = new Button { Classes = { "remove-button" }, Margin = new Thickness(8, 0, 0, 0) };
                        removePropertiesButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            foreach (var tag in new[] { "timer", "modifyduration", "modifyupdateinterval" })
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            }
                            state.SelectedFlagTags.Remove("modifyupdateintervalrandomness");
                            state.CustomValues["autorangedmodify.additionalproperties"] = "0";
                            RenderProtoActionFlags(state);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        propertiesRow.Children.Add(removePropertiesButton);
                    }
                    state.AdditionalFieldsContainer.Children.Add(propertiesRow);
                }
                else if (!_isReadOnly)
                {
                    var addPropertiesButton = new Button { Content = "Additional Properties", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 4, 0, 2) };
                    addPropertiesButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.CustomValues["autorangedmodify.additionalproperties"] = "1";
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    state.AdditionalFieldsContainer.Children.Add(addPropertiesButton);
                }

                var infectionTags = new[] { "infectionrange", "infectionrof", "infectionchance", "infectionduration", "infectionattachment", "infectionattachmentbone" };
                var showInfection = state.CustomValues.GetValueOrDefault("autorangedmodify.infection", "0") == "1" ||
                    infectionTags.Any(HasAutoRangedValue) || state.SelectedFlagTags.Contains("modifyselfifinfection") || state.SelectedFlagTags.Contains("modifyattachonce");
                if (showInfection)
                {
                    var infectionSection = new StackPanel { Spacing = 3, Margin = new Thickness(0, 4, 0, 2) };
                    var infectionHeader = new WrapPanel { Orientation = Orientation.Horizontal };
                    infectionHeader.Children.Add(new TextBlock { Text = "Infection", FontWeight = FontWeight.Bold, VerticalAlignment = VerticalAlignment.Center });
                    if (!_isReadOnly)
                    {
                        var removeInfectionButton = new Button { Classes = { "remove-button" }, Margin = new Thickness(8, 0, 0, 0) };
                        removeInfectionButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            foreach (var tag in infectionTags)
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            }
                            state.SelectedFlagTags.Remove("modifyselfifinfection");
                            state.SelectedFlagTags.Remove("modifyattachonce");
                            state.CustomValues["autorangedmodify.infection"] = "0";
                            RenderProtoActionFlags(state);
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        infectionHeader.Children.Add(removeInfectionButton);
                    }
                    infectionSection.Children.Add(infectionHeader);
                    var infectionValuesRow = new WrapPanel { Orientation = Orientation.Horizontal };
                    AddAutoRangedLabeledField(infectionValuesRow, "infectionrange", "Range");
                    AddAutoRangedLabeledField(infectionValuesRow, "infectionrof", "ROF");
                    AddAutoRangedLabeledField(infectionValuesRow, "infectionchance", "Chance");
                    AddAutoRangedLabeledField(infectionValuesRow, "infectionduration", "Duration");
                    infectionSection.Children.Add(infectionValuesRow);
                    var infectionAttachmentRow = new WrapPanel { Orientation = Orientation.Horizontal };
                    AddAutoRangedLabeledField(infectionAttachmentRow, "infectionattachment", "Attachment", 200);
                    AddAutoRangedLabeledField(infectionAttachmentRow, "infectionattachmentbone", "Bone", 100);
                    AddAutoRangedFlagCheckBox(infectionAttachmentRow, "modifyselfifinfection", "Include Source");
                    AddAutoRangedFlagCheckBox(infectionAttachmentRow, "modifyattachonce", "Attach Once");
                    infectionSection.Children.Add(infectionAttachmentRow);
                    state.AdditionalFieldsContainer.Children.Add(infectionSection);
                }
                else if (!_isReadOnly)
                {
                    var addInfectionButton = new Button { Content = "Infection", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left, Margin = new Thickness(0, 4, 0, 2) };
                    addInfectionButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.CustomValues["autorangedmodify.infection"] = "1";
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    state.AdditionalFieldsContainer.Children.Add(addInfectionButton);
                }
                }
            }
            else if (IsConditionalShieldActionType(actionType))
            {
                primaryFieldTags.RemoveAll(tag => new[]
                {
                    "shieldpoints", "shielddecayrate", "maximumduration", "modifytargetlimit",
                    "slowhealmultiplier", "modelattachment", "modelattachmentbone",
                    "targetattachment", "targetattachmentbone"
                }.Contains(tag, StringComparer.OrdinalIgnoreCase));

                var rawDamageFlags = currentValues.TryGetValue("damageflags", out var editedDamageFlags)
                    ? editedDamageFlags
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "damageflags");
                var originalFlags = rawDamageFlags.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                var damageEnabled = IsConditionalShieldDamageEnabled(state, effectiveAction);
                var healEnabled = state.CustomValues.TryGetValue("conditionalshield.heal", out var storedHeal)
                    ? storedHeal == "1"
                    : !damageEnabled || originalFlags.Contains("Ally", StringComparer.OrdinalIgnoreCase);

                var modeRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                var healCheckBox = new CheckBox { Content = "Heal", IsChecked = healEnabled, IsEnabled = !_isReadOnly, Margin = new Thickness(0, 0, 14, 0) };
                var damageCheckBox = new CheckBox { Content = "Damage", IsChecked = damageEnabled, IsEnabled = !_isReadOnly, Margin = new Thickness(0, 0, 14, 0) };
                modeRow.Children.Add(healCheckBox);
                modeRow.Children.Add(damageCheckBox);
                state.AdditionalFieldsContainer.Children.Add(modeRow);

                var updatingModes = false;
                async Task UpdateConditionalShieldModesAsync(bool healChanged)
                {
                    if (_isPopulating || updatingModes || !await CheckStartLocalMod())
                        return;

                    updatingModes = true;
                    if (healChanged)
                    {
                        if (healCheckBox.IsChecked == true)
                            damageCheckBox.IsChecked = false;
                        else if (damageCheckBox.IsChecked != true)
                            damageCheckBox.IsChecked = true;
                    }
                    else
                    {
                        if (damageCheckBox.IsChecked == true)
                            healCheckBox.IsChecked = false;
                        else if (healCheckBox.IsChecked != true)
                            healCheckBox.IsChecked = true;
                    }

                    state.CustomValues["conditionalshield.heal"] = healCheckBox.IsChecked == true ? "1" : "0";
                    state.CustomValues["conditionalshield.damage"] = damageCheckBox.IsChecked == true ? "1" : "0";
                    if (damageCheckBox.IsChecked == true)
                    {
                        state.ForcedVisibleFieldTags.Remove("slowhealmultiplier");
                        state.AdditionalFieldControls.Remove("slowhealmultiplier");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "slowhealmultiplier", "");
                    }
                    state.ForcedVisibleFieldTags.Add("damageflags");
                    updatingModes = false;
                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                }

                healCheckBox.IsCheckedChanged += async (_, _) => await UpdateConditionalShieldModesAsync(true);
                damageCheckBox.IsCheckedChanged += async (_, _) => await UpdateConditionalShieldModesAsync(false);

                var shieldRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                void AddShieldField(string tag, string label)
                {
                    shieldRow.Children.Add(new TextBlock { Text = label + ":", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(shieldRow.Children.Count == 0 ? 0 : 12, 4, 6, 4) });
                    var editor = CreateSimpleEditor(tag);
                    if (editor is TextBox textBox) textBox.Width = 100;
                    shieldRow.Children.Add(editor);
                }
                AddShieldField("shieldpoints", "Shield Points");
                AddShieldField("shielddecayrate", "Decay Rate");
                AddShieldField("maximumduration", "Max Duration");
                var targetLimitValue = currentValues.TryGetValue("modifytargetlimit", out var currentTargetLimit)
                    ? currentTargetLimit
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifytargetlimit");
                var showTargetLimit = state.ForcedVisibleFieldTags.Contains("modifytargetlimit") || !string.IsNullOrWhiteSpace(targetLimitValue);
                if (showTargetLimit)
                {
                    AddShieldField("modifytargetlimit", "Target Limit");
                    if (!_isReadOnly)
                    {
                        var removeTargetLimit = new Button { Classes = { "remove-button" } };
                        removeTargetLimit.Click += async (_, _) => { if (await CheckStartLocalMod()) { state.ForcedVisibleFieldTags.Remove("modifytargetlimit"); ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modifytargetlimit", ""); RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                        shieldRow.Children.Add(removeTargetLimit);
                    }
                }
                else if (!_isReadOnly)
                {
                    var addTargetLimit = new Button { Content = "Target Limit", Classes = { "add-component" }, Margin = new Thickness(20, 0, 0, 0) };
                    addTargetLimit.Click += async (_, _) => { if (await CheckStartLocalMod()) { state.ForcedVisibleFieldTags.Add("modifytargetlimit"); RefreshProtoActionMetadataPanels(state); MarkDirty(); } };
                    shieldRow.Children.Add(addTargetLimit);
                }

                var slowHealMultiplierValue = currentValues.TryGetValue("slowhealmultiplier", out var currentSlowHealMultiplier)
                    ? currentSlowHealMultiplier
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "slowhealmultiplier");
                var showSlowHealMultiplier = healEnabled &&
                                             (state.ForcedVisibleFieldTags.Contains("slowhealmultiplier") ||
                                              !string.IsNullOrWhiteSpace(slowHealMultiplierValue));
                if (showSlowHealMultiplier)
                {
                    AddShieldField("slowhealmultiplier", "Slow Heal Multiplier");
                    if (!_isReadOnly)
                    {
                        var removeSlowHealMultiplier = new Button { Classes = { "remove-button" } };
                        removeSlowHealMultiplier.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.ForcedVisibleFieldTags.Remove("slowhealmultiplier");
                            state.AdditionalFieldControls.Remove("slowhealmultiplier");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "slowhealmultiplier", "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        shieldRow.Children.Add(removeSlowHealMultiplier);
                    }
                }
                else if (healEnabled && !_isReadOnly)
                {
                    var addSlowHealMultiplier = new Button { Content = "Slow Heal Multiplier", Classes = { "add-component" }, Margin = new Thickness(20, 0, 0, 0) };
                    addSlowHealMultiplier.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.ForcedVisibleFieldTags.Add("slowhealmultiplier");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    shieldRow.Children.Add(addSlowHealMultiplier);
                }
                state.AdditionalFieldsContainer.Children.Add(shieldRow);

                var damageFlagsStorage = new TextBox
                {
                    Text = string.Join("|", AbductDamageFlagValues.Where(flag =>
                        (flag == "Ally" && healEnabled) ||
                        (flag == "Enemy" && damageEnabled) ||
                        (flag == "Nature" && damageEnabled && originalFlags.Contains("Nature", StringComparer.OrdinalIgnoreCase)))),
                    IsVisible = false
                };
                state.AdditionalFieldControls["damageflags"] = damageFlagsStorage;

                var attachmentButtonsRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    HorizontalAlignment = HorizontalAlignment.Left,
                    Tag = "conditionalshield.attachment-buttons"
                };

                void RenderOptionalAttachmentPair(string attachmentTag, string attachmentLabel, string boneTag, string boneLabel, string addLabel)
                {
                    var attachmentValue = currentValues.TryGetValue(attachmentTag, out var currentAttachment)
                        ? currentAttachment
                        : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, attachmentTag);
                    var boneValue = currentValues.TryGetValue(boneTag, out var currentBone)
                        ? currentBone
                        : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, boneTag);
                    var visible = state.ForcedVisibleFieldTags.Contains(attachmentTag) ||
                                  state.ForcedVisibleFieldTags.Contains(boneTag) ||
                                  !string.IsNullOrWhiteSpace(attachmentValue) ||
                                  !string.IsNullOrWhiteSpace(boneValue);
                    if (!visible)
                    {
                        if (!_isReadOnly)
                        {
                            var addButton = new Button
                            {
                                Content = addLabel,
                                Classes = { "add-component" },
                                HorizontalAlignment = HorizontalAlignment.Left,
                                Margin = new Thickness(0, 0, 8, 0)
                            };
                            addButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;

                                state.ForcedVisibleFieldTags.Add(attachmentTag);
                                state.ForcedVisibleFieldTags.Add(boneTag);
                                RefreshProtoActionMetadataPanels(state);
                                MarkDirty();
                            };
                            attachmentButtonsRow.Children.Add(addButton);
                        }
                        return;
                    }

                    var attachmentEditor = CreateSimpleEditor(attachmentTag);
                    var boneEditor = CreateSimpleEditor(boneTag);
                    var row = new AttachmentEditor(
                        attachmentEditor,
                        boneEditor,
                        attachmentLabel + ":",
                        boneLabel + ":");
                    if (!_isReadOnly)
                    {
                        var remove = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        remove.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            foreach (var tag in new[] { attachmentTag, boneTag })
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                            }
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        row.Children.Add(remove);
                    }
                    state.AdditionalFieldsContainer.Children.Add(row);
                }

                RenderOptionalAttachmentPair("modelattachment", "Model Attachment", "modelattachmentbone", "Bone", "Add Model Attachment");
                RenderOptionalAttachmentPair("targetattachment", "Target Attachment", "targetattachmentbone", "Bone", "Add Target Attachment");
                if (attachmentButtonsRow.Children.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(attachmentButtonsRow);
            }
            else if (IsHealActionType(actionType))
            {
                state.CoreFieldsGrid.IsVisible = false;
                state.MaxRangeLabel.IsVisible = false;
                state.MaxRangeTb.IsVisible = false;

                var areaHealVisible =
                    state.ForcedVisibleFieldTags.Contains("modifyamount") ||
                    state.ForcedVisibleFieldTags.Contains("modifytargetlimit") ||
                    state.ForcedVisibleFieldTags.Contains("outerdamageareadistance") ||
                    !string.IsNullOrWhiteSpace(currentValues.TryGetValue("modifyamount", out var currentModifyAmount) ? currentModifyAmount : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifyamount")) ||
                    !string.IsNullOrWhiteSpace(currentValues.TryGetValue("modifytargetlimit", out var currentTargetLimit) ? currentTargetLimit : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifytargetlimit")) ||
                    !string.IsNullOrWhiteSpace(currentValues.TryGetValue("outerdamageareadistance", out var currentRadius) ? currentRadius : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "outerdamageareadistance"));

                var maxRangeMirror = new TextBox
                {
                    Text = state.MaxRangeTb.Text,
                    IsEnabled = !_isReadOnly,
                    Width = 140
                };
                AttachProtoActionDecimalBehavior(maxRangeMirror);
                state.MirroredSimpleSourceControls[maxRangeMirror] = "maxrange";
                maxRangeMirror.TextChanged += async (_, _) =>
                {
                    state.MaxRangeTb.Text = maxRangeMirror.Text;
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                var topRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                topRow.Children.Add(CreateLabeledFieldGroup("Max Range:", maxRangeMirror));
                var areaHealGroup = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(8, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                areaHealGroup.Children.Add(new TextBlock
                {
                    Text = "Area Heal:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                var areaHealCheckBox = new CheckBox
                {
                    IsChecked = areaHealVisible,
                    IsEnabled = !_isReadOnly,
                    VerticalAlignment = VerticalAlignment.Center
                };
                areaHealCheckBox.IsCheckedChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    if (areaHealCheckBox.IsChecked == true)
                    {
                        state.ForcedVisibleFieldTags.Add("modifyamount");
                        state.ForcedVisibleFieldTags.Add("outerdamageareadistance");
                    }
                    else
                    {
                        foreach (var tag in new[] { "modifyamount", "modifytargetlimit", "outerdamageareadistance" })
                        {
                            state.ForcedVisibleFieldTags.Remove(tag);
                            state.AdditionalFieldControls.Remove(tag);
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                        }
                    }

                    MarkDirty();
                    RefreshProtoActionMetadataPanels(state);
                };
                areaHealGroup.Children.Add(areaHealCheckBox);
                topRow.Children.Add(areaHealGroup);
                state.AdditionalFieldsContainer.Children.Add(topRow);

                var animEditor = CreateSimpleEditor("anim");
                var animRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 200"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                animRow.Children.Add(new TextBlock
                {
                    Text = "Animation:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                Grid.SetColumn(animEditor, 1);
                animRow.Children.Add(animEditor);
                state.AdditionalFieldsContainer.Children.Add(animRow);

                var rateEntries = GetCurrentStructuredEntries("rate");
                state.StructuredFieldRows["rate"] = [];
                var rateRowsContainer = new StackPanel { Spacing = 4 };
                state.AdditionalFieldsContainer.Children.Add(rateRowsContainer);

                void AddHealRateRow(ProtoActionStructuredFieldEntry? initialEntry = null, bool canRemove = true)
                {
                    var row = new Grid
                    {
                        ColumnDefinitions = new ColumnDefinitions("60, Auto, 180, 100, 32"),
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    row.Children.Add(new TextBlock
                    {
                        Text = "Rate:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 8, 4)
                    });
                    var typeLabel = new TextBlock
                    {
                        Text = "Type:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 8, 4)
                    };
                    Grid.SetColumn(typeLabel, 1);
                    row.Children.Add(typeLabel);
                    var typeAcb = new AutoCompleteBox
                    {
                        Text = initialEntry?.Attributes.GetValueOrDefault("type") ?? "",
                        Width = 180,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = GetAvailableBuildLimitTargets(),
                        IsEnabled = !_isReadOnly
                    };
                    EnableDropdownAutoComplete(typeAcb);
                    var valueTb = new TextBox { Text = initialEntry?.Value ?? "1", Width = 100, IsEnabled = !_isReadOnly };
                    AttachProtoActionDecimalBehavior(valueTb);
                    typeAcb.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                    valueTb.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                    Grid.SetColumn(typeAcb, 2);
                    row.Children.Add(typeAcb);
                    Grid.SetColumn(valueTb, 3);
                    row.Children.Add(valueTb);
                    var rowState = new ProtoActionStructuredFieldRowState { Tag = "rate", RowPanel = row, ValueTb = valueTb };
                    rowState.AttributeEditors["type"] = typeAcb;
                    if (!_isReadOnly && canRemove)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0)
                        };
                        removeButton.Click += async (_, _) =>
                        {
                            if (await CheckStartLocalMod())
                            {
                                state.StructuredFieldRows["rate"].Remove(rowState);
                                rateRowsContainer.Children.Remove(row);
                                MarkDirty();
                            }
                        };
                        Grid.SetColumn(removeButton, 4);
                        row.Children.Add(removeButton);
                    }
                    state.StructuredFieldRows["rate"].Add(rowState);
                    rateRowsContainer.Children.Add(row);
                }

                var displayedRateEntries = rateEntries.Count > 0
                    ? rateEntries
                    : [new ProtoActionStructuredFieldEntry { Value = state.IsNewCustomAction ? "1" : "" }];
                for (var rateIndex = 0; rateIndex < displayedRateEntries.Count; rateIndex++)
                    AddHealRateRow(displayedRateEntries[rateIndex], canRemove: rateIndex > 0);
                if (!_isReadOnly)
                {
                    var addRateButton = new Button { Content = "Add Rate", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left };
                    addRateButton.Click += async (_, _) =>
                    {
                        if (await CheckStartLocalMod())
                        {
                            AddHealRateRow();
                            MarkDirty();
                        }
                    };
                    state.AdditionalFieldsContainer.Children.Add(addRateButton);
                }

                const string SlowHealMultiplierHiddenStateKey = "heal.slowhealmultiplier.hidden";
                var rawSlowHealMultiplier = currentValues.TryGetValue("slowhealmultiplier", out var currentSlowHealMultiplier)
                    ? currentSlowHealMultiplier
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "slowhealmultiplier");
                var showSlowHealMultiplier = state.CustomValues.GetValueOrDefault(SlowHealMultiplierHiddenStateKey) != "1" &&
                                             (state.ForcedVisibleFieldTags.Contains("slowhealmultiplier") ||
                                              !string.IsNullOrWhiteSpace(rawSlowHealMultiplier));
                if (showSlowHealMultiplier)
                {
                    var slowHealRow = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 2, Margin = new Thickness(0, 2, 0, 2) };
                    slowHealRow.Children.Add(new TextBlock { Text = "Slow Heal Multiplier:", VerticalAlignment = VerticalAlignment.Center });
                    var slowHealEditor = CreateSimpleEditor("slowhealmultiplier");
