                state.MaxRangeTb.IsVisible = false;

                bool ShouldShowMaintainOptionalField(string tag)
                    => state.ForcedVisibleFieldTags.Contains(tag) ||
                       !string.IsNullOrWhiteSpace(
                           currentValues.TryGetValue(tag, out var currentValue)
                               ? currentValue
                               : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag));

                bool ShouldShowMaintainSpawnRange()
                    => state.ForcedVisibleFieldTags.Contains("maxrange") ||
                       !string.IsNullOrWhiteSpace(
                           currentValues.TryGetValue("maxrange", out var currentSpawnRange)
                               ? currentSpawnRange
                                : effectiveAction.MaxRange);

                bool IsNewMaintainAction()
                    => state.IsNewCustomAction &&
                       string.IsNullOrWhiteSpace(state.Model.Type) &&
                       string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "maintaintrainpoints"));

                bool ShouldShowMaintainTrainPoints()
                    => !string.Equals(state.CustomValues.GetValueOrDefault(MaintainTrainPointsHiddenStateKey), "1", StringComparison.OrdinalIgnoreCase) &&
                       (state.ForcedVisibleFieldTags.Contains("maintaintrainpoints") ||
                        !string.IsNullOrWhiteSpace(
                            currentValues.TryGetValue("maintaintrainpoints", out var currentMaintainTrainPoints)
                                ? currentMaintainTrainPoints
                                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "maintaintrainpoints")) ||
                        IsNewMaintainAction());

                if (!state.CustomValues.ContainsKey(MaintainPausableValueStateKey))
                {
                    var rawPausableValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "pausable");
                    state.CustomValues[MaintainPausableValueStateKey] = (!string.IsNullOrWhiteSpace(rawPausableValue)
                        ? IsProtoActionFlagEnabledValue(rawPausableValue)
                        : true)
                        ? "1"
                        : "0";
                }

                if (state.CustomValues.GetValueOrDefault(MaintainPausableValueStateKey, "1").Equals("1", StringComparison.OrdinalIgnoreCase))
                    state.SelectedFlagTags.Add("pausable");
                else
                    state.SelectedFlagTags.Remove("pausable");

                if (!state.CustomValues.ContainsKey(MaintainShowQueueWhileWaitingValueStateKey))
                {
                    var rawShowQueueWhileWaitingValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "showqueuewhilewaiting");
                    state.CustomValues[MaintainShowQueueWhileWaitingValueStateKey] = (!string.IsNullOrWhiteSpace(rawShowQueueWhileWaitingValue)
                        ? IsProtoActionFlagEnabledValue(rawShowQueueWhileWaitingValue)
                        : true)
                        ? "1"
                        : "0";
                }

                if (state.CustomValues.GetValueOrDefault(MaintainShowQueueWhileWaitingValueStateKey, "1").Equals("1", StringComparison.OrdinalIgnoreCase))
                    state.SelectedFlagTags.Add("showqueuewhilewaiting");
                else
                    state.SelectedFlagTags.Remove("showqueuewhilewaiting");

                if (ShouldShowMaintainTrainPoints())
                {
                    var maintainPointsRow = new Grid
                    {
                        ColumnDefinitions = !_isReadOnly
                            ? new ColumnDefinitions("Auto, 100, 32")
                            : new ColumnDefinitions("Auto, 100"),
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    maintainPointsRow.Children.Add(new TextBlock
                    {
                        Text = "Maintain Train Points:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 10, 4)
                    });
                    var maintainPointsEditor = CreateSimpleEditor("maintaintrainpoints");
                    if (maintainPointsEditor is TextBox maintainPointsTb)
                        maintainPointsTb.Width = 140;
                    Grid.SetColumn(maintainPointsEditor, 1);
                    maintainPointsRow.Children.Add(maintainPointsEditor);

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(8, 0, 0, 0)
                        };
                        removeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            state.CustomValues[MaintainTrainPointsHiddenStateKey] = "1";
                            state.ForcedVisibleFieldTags.Remove("maintaintrainpoints");
                            state.AdditionalFieldControls.Remove("maintaintrainpoints");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "maintaintrainpoints", "");
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };
                        Grid.SetColumn(removeButton, 2);
                        maintainPointsRow.Children.Add(removeButton);
                    }

                    state.AdditionalFieldsContainer.Children.Add(maintainPointsRow);
                }
                else if (!_isReadOnly)
                {
                    var addMaintainTrainPointsButton = new Button
                    {
                        Content = "Maintain Train Points",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addMaintainTrainPointsButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        state.CustomValues.Remove(MaintainTrainPointsHiddenStateKey);
                        state.ForcedVisibleFieldTags.Add("maintaintrainpoints");
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    };
                    state.AdditionalFieldsContainer.Children.Add(addMaintainTrainPointsButton);
                }

                var optionalSpawnRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 6)
                };

                void AddMaintainOptionalCell(
                    string tag,
                    string label,
                    bool isVisible,
                    Control? editor,
                    Action? onRemove,
                    Action? onAdd)
                {
                    if (isVisible)
                    {
                        var cell = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 6,
                            Margin = new Thickness(0, 0, 14, 0)
                        };
                        cell.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 10, 4)
                        });
                        if (editor != null)
                            cell.Children.Add(editor);

                        if (!_isReadOnly && onRemove != null)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(2, 0, 0, 0)
                            };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                onRemove();
                                MarkDirty();
                                RefreshProtoActionMetadataPanels(state);
                            };
                            cell.Children.Add(removeButton);
                        }

                        optionalSpawnRow.Children.Add(cell);
                    }
                    else if (!_isReadOnly && onAdd != null)
                    {
                        var addButton = new Button
                        {
                            Content = label,
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 12, 0)
                        };
                        addButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            onAdd();
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };
                        optionalSpawnRow.Children.Add(addButton);
                    }
                }

                var spawnRangeVisible = ShouldShowMaintainSpawnRange();
                var spawnRangeEditor = new TextBox
                {
                    Text = GetProtoActionDefaultSimpleValue(
                        "maxrange",
                        currentValues.TryGetValue("maxrange", out var currentSpawnRange)
                            ? currentSpawnRange
                            : state.MaxRangeTb.Text ?? ""),
                    Width = 90,
                    IsEnabled = !_isReadOnly
                };
                AttachProtoActionDecimalBehavior(spawnRangeEditor);
                spawnRangeEditor.TextChanged += async (_, _) =>
                {
                    state.MaxRangeTb.Text = spawnRangeEditor.Text;
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                void RemoveMaintainSimpleField(string tag)
                {
                    state.ForcedVisibleFieldTags.Remove(tag);
                    state.AdditionalFieldControls.Remove(tag);
                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                }

                AddMaintainOptionalCell(
                    "maxrange",
                    "Spawn Range",
                    spawnRangeVisible,
                    spawnRangeEditor,
                    onRemove: () =>
                    {
                        state.ForcedVisibleFieldTags.Remove("maxrange");
                        state.MaxRangeTb.Text = "";
                        state.Model.MaxRange = "";
                    },
                    onAdd: () => state.ForcedVisibleFieldTags.Add("maxrange"));

                Control? CreateMaintainSimpleEditor(string tag, double width = 90)
                {
                    if (!ShouldShowMaintainOptionalField(tag))
                        return null;

                    var editor = CreateSimpleEditor(tag);
                    if (editor is TextBox tb)
                        tb.Width = width;
                    else if (editor is AutoCompleteBox acb)
                        acb.Width = width;
                    return editor;
                }

                AddMaintainOptionalCell(
                    "modifybase",
                    "Base Spawn Number",
                    ShouldShowMaintainOptionalField("modifybase"),
                    CreateMaintainSimpleEditor("modifybase"),
                    onRemove: () => RemoveMaintainSimpleField("modifybase"),
                    onAdd: () => state.ForcedVisibleFieldTags.Add("modifybase"));

                AddMaintainOptionalCell(
                    "modifytargetlimit",
                    "Max Spawn In Range",
                    ShouldShowMaintainOptionalField("modifytargetlimit"),
                    CreateMaintainSimpleEditor("modifytargetlimit"),
                    onRemove: () => RemoveMaintainSimpleField("modifytargetlimit"),
                    onAdd: () => state.ForcedVisibleFieldTags.Add("modifytargetlimit"));

                if (optionalSpawnRow.Children.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(optionalSpawnRow);

                var rateEntries = GetCurrentStructuredEntries("rate");
                state.StructuredFieldRows["rate"] = [];
                var rateSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
                var ratesContainer = new StackPanel { Spacing = 4 };
                rateSection.Children.Add(new TextBlock
                {
                    Text = "Rate",
                    FontWeight = FontWeight.Bold
                });
                rateSection.Children.Add(ratesContainer);

                void AddMaintainRateRow(ProtoActionStructuredFieldEntry? initialEntry = null)
                {
                    var rowPanel = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 6 };
                    var typeAcb = new AutoCompleteBox
                    {
                        Text = initialEntry?.Attributes.TryGetValue("type", out var typeValue) == true ? typeValue : "",
                        Width = 180,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = GetAvailableTrainUnitNames(),
                        IsEnabled = !_isReadOnly
                    };
                    EnableDropdownAutoComplete(typeAcb);
                    typeAcb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };

                    var valueTb = new TextBox
                    {
                        Text = initialEntry?.Value ?? "1.0",
                        Width = 100,
                        IsEnabled = !_isReadOnly
                    };
                    AttachProtoActionDecimalBehavior(valueTb);
                    valueTb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };

                    var rowState = new ProtoActionStructuredFieldRowState
                    {
                        Tag = "rate",
                        RowPanel = rowPanel,
                        ValueTb = valueTb
                    };
                    rowState.AttributeEditors["type"] = typeAcb;
                    state.StructuredFieldRows["rate"].Add(rowState);

                    rowPanel.Children.Add(new TextBlock { Text = "Type:", VerticalAlignment = VerticalAlignment.Center });
                    rowPanel.Children.Add(typeAcb);
                    rowPanel.Children.Add(valueTb);

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" } };
                        removeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            ratesContainer.Children.Remove(rowPanel);
                            state.StructuredFieldRows["rate"].Remove(rowState);
                            MarkDirty();
                        };
                        rowPanel.Children.Add(removeButton);
                    }

                    ratesContainer.Children.Add(rowPanel);
                }

                if (rateEntries.Count == 0 && !_isReadOnly)
                    AddMaintainRateRow();
                else
                {
                    foreach (var entry in rateEntries)
                        AddMaintainRateRow(entry);
                }

                if (!_isReadOnly)
                {
                    var addRateButton = new Button
                    {
                        Content = "Add Rate",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addRateButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        AddMaintainRateRow();
                        MarkDirty();
                    };
                    rateSection.Children.Add(addRateButton);
                }

                state.AdditionalFieldsContainer.Children.Add(rateSection);

                var optionalFlagsRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                optionalFlagsRow.Children.Add(new TextBlock
                {
                    Text = "Optional Flags:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });

                CheckBox CreateMaintainCheckBox(string tag, string label)
                {
                    var checkBox = new CheckBox
                    {
                        Content = label,
                        IsChecked = tag.Equals("pausable", StringComparison.OrdinalIgnoreCase)
                            ? state.CustomValues.GetValueOrDefault(MaintainPausableValueStateKey, "1").Equals("1", StringComparison.OrdinalIgnoreCase)
                            : tag.Equals("showqueuewhilewaiting", StringComparison.OrdinalIgnoreCase)
                                ? state.CustomValues.GetValueOrDefault(MaintainShowQueueWhileWaitingValueStateKey, "1").Equals("1", StringComparison.OrdinalIgnoreCase)
                                : state.SelectedFlagTags.Contains(tag),
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(0, 0, 16, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    checkBox.IsCheckedChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        if (tag.Equals("pausable", StringComparison.OrdinalIgnoreCase))
                        {
                            var isChecked = checkBox.IsChecked == true;
                            state.CustomValues[MaintainPausableValueStateKey] = isChecked ? "1" : "0";
                            if (isChecked)
                                state.SelectedFlagTags.Add(tag);
                            else
                                state.SelectedFlagTags.Remove(tag);
                        }
                        else if (tag.Equals("showqueuewhilewaiting", StringComparison.OrdinalIgnoreCase))
                        {
                            var isChecked = checkBox.IsChecked == true;
                            state.CustomValues[MaintainShowQueueWhileWaitingValueStateKey] = isChecked ? "1" : "0";
                            if (isChecked)
                                state.SelectedFlagTags.Add(tag);
                            else
                                state.SelectedFlagTags.Remove(tag);
                        }
                        else if (checkBox.IsChecked == true)
                            state.SelectedFlagTags.Add(tag);
                        else
                            state.SelectedFlagTags.Remove(tag);

                        RenderProtoActionFlags(state);
                        MarkDirty();
                    };
                    return checkBox;
                }

                optionalFlagsRow.Children.Add(CreateMaintainCheckBox("randomtrainunit", "Random Train Unit"));
                optionalFlagsRow.Children.Add(CreateMaintainCheckBox("killontrain", "Kill On Train"));
                state.AdditionalFieldsContainer.Children.Add(optionalFlagsRow);

                var queueRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 6, 0, 2) };
                queueRow.Children.Add(new TextBlock
                {
                    Text = "Queue:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                queueRow.Children.Add(CreateMaintainCheckBox("pausable", "Pausable"));
                queueRow.Children.Add(CreateMaintainCheckBox("showqueuewhilewaiting", "Show Queue While Waiting"));
                queueRow.Children.Add(CreateMaintainCheckBox("hidefromglobalqueue", "Hide From Global Queue"));
                state.AdditionalFieldsContainer.Children.Add(queueRow);
            }
            else if (IsAutoGatherActionType(actionType))
            {
                state.CoreFieldsGrid.IsVisible = false;
                state.RofLabel.IsVisible = false;
                state.RofTb.IsVisible = false;
                state.MaxRangeLabel.IsVisible = false;
                state.MaxRangeTb.IsVisible = false;

                bool ShouldShowAutoGatherOptionalField(string tag)
                    => state.ForcedVisibleFieldTags.Contains(tag) ||
                       !string.IsNullOrWhiteSpace(
                           currentValues.TryGetValue(tag, out var currentValue)
                               ? currentValue
                               : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag));

                var rateEntries = GetCurrentStructuredEntries("rate");
                state.StructuredFieldRows["rate"] = [];
                var rateSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
                var ratesContainer = new WrapPanel { Orientation = Orientation.Horizontal };
                rateSection.Children.Add(new TextBlock
                {
                    Text = "Rate",
                    FontWeight = FontWeight.Bold
                });
                rateSection.Children.Add(ratesContainer);
                var refreshingRateChoices = false;
                Button? addAutoGatherRateButton = null;

                void RefreshAutoGatherResourceChoices()
                {
                    if (refreshingRateChoices)
                        return;

                    refreshingRateChoices = true;
                    try
                    {
                        foreach (var row in state.StructuredFieldRows["rate"])
                        {
                            if (!row.AttributeEditors.TryGetValue("type", out var control) || control is not ComboBox combo)
                                continue;

                            var current = combo.SelectedItem?.ToString() ?? "";
                            var usedByOtherRows = state.StructuredFieldRows["rate"]
                                .Where(other => !ReferenceEquals(other, row))
                                .Select(other => other.AttributeEditors.TryGetValue("type", out var otherControl) && otherControl is ComboBox otherCombo
                                    ? otherCombo.SelectedItem?.ToString() ?? ""
                                    : "")
                                .Where(value => !string.IsNullOrWhiteSpace(value))
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                            var choices = ProtoConstants.KnownResourceTypes
                                .Where(resource => resource.Equals(current, StringComparison.OrdinalIgnoreCase) || !usedByOtherRows.Contains(resource))
                                .ToList();
                            combo.ItemsSource = choices;
                            combo.SelectedItem = choices.FirstOrDefault(resource => resource.Equals(current, StringComparison.OrdinalIgnoreCase));
                        }

                        if (addAutoGatherRateButton != null)
                        {
                            var usedResources = state.StructuredFieldRows["rate"]
                                .Select(row => row.AttributeEditors.TryGetValue("type", out var control) && control is ComboBox combo
                                    ? combo.SelectedItem?.ToString() ?? ""
                                    : "")
                                .Where(value => !string.IsNullOrWhiteSpace(value))
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                            addAutoGatherRateButton.IsVisible = ProtoConstants.KnownResourceTypes.Any(resource => !usedResources.Contains(resource));
                        }
                    }
                    finally
                    {
                        refreshingRateChoices = false;
                    }
                }

                void AddAutoGatherRateRow(ProtoActionStructuredFieldEntry? initialEntry = null)
                {
                    var initialResourceType = initialEntry?.Attributes.TryGetValue("type", out var typeValue) == true ? typeValue : "";
                    var isInheritedRateType = IsInheritedStructuredProtoActionEntry(
                        state,
                        "rate",
                        "type",
                        initialResourceType);
                    var typeCombo = new ComboBox
                    {
                        Width = 110,
                        ItemsSource = ProtoConstants.KnownResourceTypes,
                        SelectedItem = ProtoConstants.KnownResourceTypes.FirstOrDefault(resource =>
                            resource.Equals(initialResourceType, StringComparison.OrdinalIgnoreCase)),
                        IsEnabled = !_isReadOnly && !isInheritedRateType
                    };
                    typeCombo.SelectionChanged += async (_, _) =>
                    {
                        RefreshAutoGatherResourceChoices();
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };

                    var valueTb = new TextBox
                    {
                        Text = initialEntry?.Value ?? "1.0",
                        Width = 80,
                        IsEnabled = !_isReadOnly
                    };
                    AttachProtoActionDecimalBehavior(valueTb);
                    valueTb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };

                    var rowPanel = new RateEditor(
                        typeCombo,
                        valueTb,
                        "Resource:",
                        showRemoveButton: !_isReadOnly);

                    var rowState = new ProtoActionStructuredFieldRowState
                    {
                        Tag = "rate",
                        RowPanel = rowPanel,
                        ValueTb = valueTb
                    };
                    rowState.AttributeEditors["type"] = typeCombo;
                    state.StructuredFieldRows["rate"].Add(rowState);

                    if (rowPanel.RemoveButton != null)
                    {
                        rowPanel.RemoveButton.Click += async (_, _) =>
                        {
                            var selectedResource = typeCombo.SelectedItem?.ToString()?.Trim() ?? "";
                            if (await BlockInheritedStructuredProtoActionEntryRemovalAsync(
                                    state,
                                    "rate",
                                    "type",
                                    selectedResource,
                                    "Rate type"))
                            {
                                return;
                            }

                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            ratesContainer.Children.Remove(rowPanel);
                            state.StructuredFieldRows["rate"].Remove(rowState);
                            RefreshAutoGatherResourceChoices();
                            MarkDirty();
                        };
                    }

                    if (addAutoGatherRateButton != null)
                        ratesContainer.Children.Remove(addAutoGatherRateButton);
                    ratesContainer.Children.Add(rowPanel);
                    if (addAutoGatherRateButton != null)
                        ratesContainer.Children.Add(addAutoGatherRateButton);
                    RefreshAutoGatherResourceChoices();
                }

                if (rateEntries.Count == 0 && !_isReadOnly)
                    AddAutoGatherRateRow();
                else
                {
                    foreach (var entry in rateEntries)
                        AddAutoGatherRateRow(entry);
                }

                if (!_isReadOnly)
                {
                    addAutoGatherRateButton = new Button
                    {
                        Content = "Add Rate",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left,
                        VerticalAlignment = VerticalAlignment.Top,
                        Margin = new Thickness(0, 0, 0, 4)
                    };
                    addAutoGatherRateButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        AddAutoGatherRateRow();
                        MarkDirty();
                    };
                    ratesContainer.Children.Add(addAutoGatherRateButton);
                    RefreshAutoGatherResourceChoices();
                }

                state.AdditionalFieldsContainer.Children.Add(rateSection);

                var optionalFlagsPanel = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 2) };
                optionalFlagsPanel.Children.Add(new TextBlock
                {
                    Text = "Additional Properties",
                    FontWeight = FontWeight.Bold
                });
                var optionalFlagsRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                optionalFlagsPanel.Children.Add(optionalFlagsRow);

                CheckBox CreateAutoGatherFlagCheckBox(string tag, string label)
                {
                    var checkBox = new CheckBox
                    {
                        Content = label,
                        IsChecked = state.SelectedFlagTags.Contains(tag),
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(0, 0, 16, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    checkBox.IsCheckedChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        if (checkBox.IsChecked == true)
                            state.SelectedFlagTags.Add(tag);
                        else
                            state.SelectedFlagTags.Remove(tag);

                        RenderProtoActionFlags(state);
                        MarkDirty();
                    };
                    return checkBox;
                }

                optionalFlagsRow.Children.Add(CreateAutoGatherFlagCheckBox("addresourcestoinventory", "Add Resources To Inventory"));
                optionalFlagsRow.Children.Add(CreateAutoGatherFlagCheckBox("autogatherscalebygatherrate", "Scale by gather rate"));
                optionalFlagsRow.Children.Add(CreateAutoGatherFlagCheckBox("donotautogatherifgathered", "Do Not Auto Gather If Gathered"));
                state.AdditionalFieldsContainer.Children.Add(optionalFlagsPanel);

                var gatheringTypes = state.StructuredFieldRows.TryGetValue("donotautogatherunlessgatheringtypes", out var existingGatheringTypeRows)
                    ? existingGatheringTypeRows
                        .Select(x => ReadTextLikeControlValue(x.ValueTb))
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList()
                    : GetProtoActionNestedUnitTypeValues(effectiveAction, "donotautogatherunlessgatheringtypes");
                state.StructuredFieldRows["donotautogatherunlessgatheringtypes"] = [];
                var showGatheringTypes = gatheringTypes.Count > 0 || state.ForcedVisibleFieldTags.Contains("donotautogatherunlessgatheringtypes");
                if (showGatheringTypes)
                {
                    var gatheringTypesSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 6) };
                    gatheringTypesSection.Children.Add(new TextBlock
                    {
                        Text = "Do Not Auto Gather Unless Gathering Types",
                        FontWeight = FontWeight.Bold
                    });
                    var selectorRow = new WrapPanel { Orientation = Orientation.Horizontal };
                    selectorRow.Children.Add(new TextBlock
                    {
                        Text = "Unit Type:",
                        FontWeight = FontWeight.SemiBold,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 0, 8, 0)
                    });
                    gatheringTypesSection.Children.Add(selectorRow);
                    var gatheringTypeChips = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                    var gatheringTypeSuggestions = GetAvailableBuildLimitTargets();

                    void AddGatheringTypeChip(string value)
                    {
                        var normalizedValue = value?.Trim() ?? "";
                        if (string.IsNullOrWhiteSpace(normalizedValue) ||
                            state.StructuredFieldRows["donotautogatherunlessgatheringtypes"].Any(row =>
                                ReadTextLikeControlValue(row.ValueTb).Equals(normalizedValue, StringComparison.OrdinalIgnoreCase)))
                        {
                            return;
                        }

                        var valueControl = new AutoCompleteBox { Text = normalizedValue };
                        ConfigureStrictSuggestionAutoComplete(valueControl, gatheringTypeSuggestions, normalizedValue);
                        var rowState = new ProtoActionStructuredFieldRowState
                        {
                            Tag = "donotautogatherunlessgatheringtypes",
                            RowPanel = gatheringTypeChips,
                            ValueTb = valueControl,
                            IncludeInSerialization = true
                        };
                        state.StructuredFieldRows["donotautogatherunlessgatheringtypes"].Add(rowState);
                        var tacticsValues = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction)
                            ? GetProtoActionNestedUnitTypeValues(tacticsAction, "donotautogatherunlessgatheringtypes")
                            : [];
                        var isInherited = tacticsValues.Contains(normalizedValue, StringComparer.OrdinalIgnoreCase);
                        Border? chip = null;
                        chip = CreateChip(normalizedValue, async () =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            if (isInherited)
                            {
                                await new Prompt(PromptType.Error, "Inherited Attribute",
                                    $"Unit Type '{normalizedValue}' is defined by the linked tactics file and cannot be deleted from the protoaction.")
                                    .ShowDialog(this);
                                return;
                            }

                            state.StructuredFieldRows["donotautogatherunlessgatheringtypes"].Remove(rowState);
                            if (chip != null)
                                gatheringTypeChips.Children.Remove(chip);
                            if (state.StructuredFieldRows["donotautogatherunlessgatheringtypes"].Count == 0)
                            {
                                state.ForcedVisibleFieldTags.Remove("donotautogatherunlessgatheringtypes");
                                RefreshProtoActionMetadataPanels(state);
                            }
                            MarkDirty();
                            CommitChipAdditionAndRefreshXmlPreview();
                        }, isInherited ? ProtoActionValueSource.TacticsInherited : ProtoActionValueSource.ProtoOnly,
                            isInherited ? normalizedValue : "");
                        gatheringTypeChips.Children.Add(chip);
                    }

                    if (!_isReadOnly)
                    {
                        var picker = new AutoCompleteBox
                        {
                            FilterMode = AutoCompleteFilterMode.Contains,
                            MinWidth = 120,
                            MaxWidth = 200,
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        ConfigureStrictSuggestionAutoComplete(picker, gatheringTypeSuggestions, "");
                        picker.SelectionChanged += async (_, _) =>
                        {
                            if (_isPopulating || picker.SelectedItem is not string selectedValue || !await CheckStartLocalMod())
                                return;
                            AddGatheringTypeChip(selectedValue);
                            picker.Text = "";
                            MarkDirty();
                            CommitChipAdditionAndRefreshXmlPreview();
                        };
                        selectorRow.Children.Add(picker);
                    }

                    foreach (var gatheringType in gatheringTypes)
                        AddGatheringTypeChip(gatheringType);
                    gatheringTypesSection.Children.Add(gatheringTypeChips);

                    state.AdditionalFieldsContainer.Children.Add(gatheringTypesSection);
                }
                else if (!_isReadOnly)
                {
                    var addGatheringTypesButton = new Button
                    {
                        Content = "Do Not Auto Gather Unless Gathering Types",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 2, 0, 6)
                    };
                    addGatheringTypesButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Add("donotautogatherunlessgatheringtypes");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    state.AdditionalFieldsContainer.Children.Add(addGatheringTypesButton);
                }

                var modifyRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2)
                };

                void AddAutoGatherOptionalCell(string tag, string label)
                {
                    var isVisible = ShouldShowAutoGatherOptionalField(tag);
                    if (isVisible)
                    {
                        var cell = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 6,
                            Margin = new Thickness(0, 0, 14, 0)
                        };
                        cell.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 10, 4)
                        });
                        var editor = CreateSimpleEditor(tag);
                        if (editor is TextBox tb)
                            tb.Width = 90;
                        cell.Children.Add(editor);
                        if (!_isReadOnly)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" } };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                MarkDirty();
                                RefreshProtoActionMetadataPanels(state);
                            };
                            cell.Children.Add(removeButton);
                        }
                        modifyRow.Children.Add(cell);
                    }
                    else if (!_isReadOnly)
                    {
                        var addButton = new Button
                        {
                            Content = label,
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 12, 0)
                        };
                        addButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            state.ForcedVisibleFieldTags.Add(tag);
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };
                        modifyRow.Children.Add(addButton);
                    }
                }

                foreach (var option in new[]
                         {
                             (Tag: "modifybase", Label: "Modify Base"),
                             (Tag: "modifymultiplier", Label: "Modify Multiplier"),
                             (Tag: "modifyratecap", Label: "Modify Rate Cap")
                         }
                         .OrderByDescending(option => ShouldShowAutoGatherOptionalField(option.Tag)))
                {
                    AddAutoGatherOptionalCell(option.Tag, option.Label);
                }
                if (modifyRow.Children.Count > 0)
                    state.AdditionalFieldsContainer.Children.Add(modifyRow);
            }
            else if (IsConvertActionType(actionType))
            {
                state.CoreFieldsGrid.IsVisible = false;
                state.RofLabel.IsVisible = false;
                state.RofTb.IsVisible = false;
                state.MaxRangeLabel.IsVisible = false;
                state.MaxRangeTb.IsVisible = false;

                bool IsCharmedConvert()
                    => state.SelectedFlagTags.Contains("charmedconvert");

                bool ShouldShowConvertOptionalField(string tag)
                    => state.ForcedVisibleFieldTags.Contains(tag) ||
                       !string.IsNullOrWhiteSpace(
                           currentValues.TryGetValue(tag, out var currentValue)
                               ? currentValue
                               : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag));

                var topRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, Auto, 120, Auto"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                topRow.Children.Add(new TextBlock
                {
                    Text = "Max Range:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(8, 4, 8, 4)
                });
                Grid.SetColumn(topRow.Children[^1], 1);
                var maxRangeMirror = new TextBox
                {
                    Text = GetProtoActionDefaultSimpleValue(
                        "maxrange",
                        currentValues.TryGetValue("maxrange", out var currentMaxRange)
                            ? currentMaxRange
                            : state.MaxRangeTb.Text ?? ""),
                    IsEnabled = !_isReadOnly,
                    Width = 120
                };
                AttachProtoActionDecimalBehavior(maxRangeMirror);
                state.MirroredSimpleSourceControls[maxRangeMirror] = "maxrange";
                maxRangeMirror.TextChanged += async (_, _) =>
                {
                    state.MaxRangeTb.Text = maxRangeMirror.Text;
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };
                Grid.SetColumn(maxRangeMirror, 2);
                topRow.Children.Add(maxRangeMirror);
                var charmedCheckBox = new CheckBox
                {
                    Content = "Charmed Convert",
                    IsChecked = IsCharmedConvert(),
                    IsEnabled = !_isReadOnly,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(8, 0, 0, 0)
                };
                charmedCheckBox.IsCheckedChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    if (charmedCheckBox.IsChecked == true)
                        state.SelectedFlagTags.Add("charmedconvert");
                    else
                    {
                        state.SelectedFlagTags.Remove("charmedconvert");
                        state.ForcedVisibleFieldTags.Remove("typedduration");
                        state.StructuredFieldRows.Remove("typedduration");
                        state.StructuredFieldRows.Remove("typedstunduration");
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "typedduration", []);
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "typedstunduration", []);
                    }

                    RenderProtoActionFlags(state);
                    MarkDirty();
                    RefreshProtoActionMetadataPanels(state);
                };
                Grid.SetColumn(charmedCheckBox, 3);
                topRow.Children.Add(charmedCheckBox);

                var minRangeVisible = ShouldShowConvertOptionalField("minrange");
                if (minRangeVisible)
                {
                    var minRangeGroup = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 6,
                        Margin = new Thickness(0, 0, 8, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    minRangeGroup.Children.Add(new TextBlock { Text = "Min Range:", VerticalAlignment = VerticalAlignment.Center });
                    var minRangeEditor = CreateSimpleEditor("minrange");
                    minRangeEditor.Width = 100;
                    minRangeGroup.Children.Add(minRangeEditor);
                    if (!_isReadOnly)
                    {
                        var removeMinRange = new Button { Classes = { "remove-button" }, Margin = new Thickness(2, 0, 0, 0) };
                        removeMinRange.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            state.ForcedVisibleFieldTags.Remove("minrange");
                            state.AdditionalFieldControls.Remove("minrange");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "minrange", "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        minRangeGroup.Children.Add(removeMinRange);
                    }
                    Grid.SetColumn(minRangeGroup, 0);
                    topRow.Children.Add(minRangeGroup);
                }
                else if (!_isReadOnly)
                {
                    var addMinRange = new Button
                    {
                        Content = "Min Range",
                        Classes = { "add-component" },
                        Margin = new Thickness(0, 0, 8, 0)
                    };
                    addMinRange.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Add("minrange");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    Grid.SetColumn(addMinRange, 0);
                    topRow.Children.Add(addMinRange);
                }
                state.AdditionalFieldsContainer.Children.Add(topRow);

                var rateEntries = GetCurrentStructuredEntries("rate");
                var minRateEntries = GetCurrentStructuredEntries("minrate");
                var supportsRateLinkedConversion = SupportsRateLinkedConversion(IsCharmedConvert());
                var conversionProtoEntries = supportsRateLinkedConversion
                    ? GetCurrentStructuredEntries("conversionprotoid")
                    : [];
                state.StructuredFieldRows["rate"] = [];
                state.StructuredFieldRows["minrate"] = [];
                if (supportsRateLinkedConversion)
                    state.StructuredFieldRows["conversionprotoid"] = [];

                var minRateEntriesByType = minRateEntries
                    .GroupBy(entry => entry.Attributes.TryGetValue("type", out var typeValue) ? typeValue?.Trim() ?? "" : "",
                        StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(group => group.Key, group => new Queue<ProtoActionStructuredFieldEntry>(group), StringComparer.OrdinalIgnoreCase);
                var conversionProtoEntriesBySourceType = conversionProtoEntries
                    .GroupBy(entry => entry.Attributes.TryGetValue("srctype", out var sourceTypeValue) ? sourceTypeValue?.Trim() ?? "" : "",
                        StringComparer.OrdinalIgnoreCase)
                    .ToDictionary(group => group.Key, group => new Queue<ProtoActionStructuredFieldEntry>(group), StringComparer.OrdinalIgnoreCase);
                ProtoActionStructuredFieldEntry? ConsumeMinRateEntryForType(string type)
                {
                    var key = type?.Trim() ?? "";
                    if (minRateEntriesByType.TryGetValue(key, out var matchingEntries) && matchingEntries.Count > 0)
                        return matchingEntries.Dequeue();

                    return null;
                }

                ProtoActionStructuredFieldEntry? ConsumeConversionProtoEntryForSourceType(string type)
                {
                    if (!supportsRateLinkedConversion)
                        return null;

                    var key = type?.Trim() ?? "";
                    if (conversionProtoEntriesBySourceType.TryGetValue(key, out var matchingEntries) && matchingEntries.Count > 0)
                        return matchingEntries.Dequeue();

                    return null;
                }

                var convertRatesSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 6) };
                var convertRatesContainer = new StackPanel { Spacing = 4 };
                convertRatesSection.Children.Add(convertRatesContainer);

                void AddConvertRateRow(
                    ProtoActionStructuredFieldEntry? initialRateEntry = null,
                    ProtoActionStructuredFieldEntry? initialMinRateEntry = null,
                    ProtoActionStructuredFieldEntry? initialConversionProtoEntry = null)
                {
                    var rateEntry = initialRateEntry ?? new ProtoActionStructuredFieldEntry();
                    var minRateEntry = initialMinRateEntry ?? new ProtoActionStructuredFieldEntry();
                    var conversionProtoEntry = initialConversionProtoEntry ?? new ProtoActionStructuredFieldEntry();

                    var rowGrid = new Grid
                    {
                        ColumnDefinitions = supportsRateLinkedConversion
                            ? !_isReadOnly
                                ? new ColumnDefinitions("70, 150, 8, 90, 80, 90, Auto, 180, 32, 20, 32")
                                : new ColumnDefinitions("70, 150, 8, 90, 80, 90, Auto, 180")
                            : !_isReadOnly
                                ? new ColumnDefinitions("70, 150, 8, 90, 80, 90, 20, 32")
                                : new ColumnDefinitions("70, 150, 8, 90, 80, 90"),
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };

                    var rateTypeAcb = new AutoCompleteBox
                    {
                        Text = rateEntry.Attributes.TryGetValue("type", out var currentRateType) ? currentRateType : "",
                        Width = 150,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = GetAvailableBuildLimitTargets(),
                        IsEnabled = !_isReadOnly
                    };
                    EnableDropdownAutoComplete(rateTypeAcb);
                    var rateValueTb = new TextBox
                    {
                        Text = rateEntry.Value ?? "1.0",
                        Width = 100,
                        IsEnabled = !_isReadOnly
                    };
                    AttachProtoActionDecimalBehavior(rateValueTb);
                    var rateRowState = new ProtoActionStructuredFieldRowState
                    {
                        Tag = "rate",
                        RowPanel = rowGrid,
                        ValueTb = rateValueTb
                    };
                    rateRowState.AttributeEditors["type"] = rateTypeAcb;
                    state.StructuredFieldRows["rate"].Add(rateRowState);

                    var minRateValueTb = new TextBox
                    {
                        Text = minRateEntry.Value ?? (string.Equals(rateEntry.Value?.Trim(), "0", StringComparison.OrdinalIgnoreCase) ||
                                                     string.Equals(rateEntry.Value?.Trim(), "0.0", StringComparison.OrdinalIgnoreCase) ||
                                                     string.Equals(rateEntry.Value?.Trim(), "0.000000", StringComparison.OrdinalIgnoreCase)
                            ? "0"
                            : rateEntry.Value ?? "1.0"),
                        Width = 90,
                        IsEnabled = !_isReadOnly
                    };
                    AttachProtoActionDecimalBehavior(minRateValueTb);
                    var minRateRowState = new ProtoActionStructuredFieldRowState
                    {
                        Tag = "minrate",
                        RowPanel = rowGrid,
                        ValueTb = minRateValueTb
                    };
                    minRateRowState.AttributeEditors["type"] = rateTypeAcb;
                    state.StructuredFieldRows["minrate"].Add(minRateRowState);

                    AutoCompleteBox? conversionProtoAcb = null;
                    ProtoActionStructuredFieldRowState? conversionProtoRowState = null;
                    if (supportsRateLinkedConversion)
                    {
                        conversionProtoAcb = new AutoCompleteBox
                        {
                            Text = conversionProtoEntry.Value ?? "",
                            Width = 150,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            ItemsSource = GetAvailableTrainUnitNames(),
                            IsEnabled = !_isReadOnly
                        };
                        EnableDropdownAutoComplete(conversionProtoAcb);
                        conversionProtoRowState = new ProtoActionStructuredFieldRowState
                        {
                            Tag = "conversionprotoid",
                            RowPanel = rowGrid,
                            ValueTb = conversionProtoAcb,
                            IncludeInSerialization = !string.IsNullOrWhiteSpace(conversionProtoEntry.Value)
                        };
                        conversionProtoRowState.AttributeEditors["srctype"] = rateTypeAcb;
                        state.StructuredFieldRows["conversionprotoid"].Add(conversionProtoRowState);
                    }

                    var minRateMirrorsRate = string.IsNullOrWhiteSpace(minRateEntry.Value) ||
                                             string.Equals(minRateEntry.Value?.Trim(), rateEntry.Value?.Trim(), StringComparison.OrdinalIgnoreCase);

                    void SyncMinRateFromRate()
                    {
                        if (minRateMirrorsRate)
                            minRateValueTb.Text = rateValueTb.Text;
                    }

                    rateTypeAcb.TextChanged += async (_, _) =>
                    {
                        SyncMinRateFromRate();
                        if (_isPopulating)
                            return;
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };
                    rateValueTb.TextChanged += async (_, _) =>
                    {
                        SyncMinRateFromRate();
                        if (_isPopulating)
                            return;
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };
                    minRateValueTb.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                            minRateMirrorsRate = string.Equals(minRateValueTb.Text?.Trim(), rateValueTb.Text?.Trim(), StringComparison.OrdinalIgnoreCase);

                        if (_isPopulating)
                            return;

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };
                    if (conversionProtoAcb != null)
                    {
                        conversionProtoAcb.TextChanged += async (_, _) =>
                        {
                            if (_isPopulating)
                                return;
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        };
                    }
                    SyncMinRateFromRate();

                    rowGrid.Children.Add(new TextBlock { Text = "Rate:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                    Grid.SetColumn(rateTypeAcb, 1);
                    rowGrid.Children.Add(rateTypeAcb);
                    Grid.SetColumn(rateValueTb, 3);
                    rowGrid.Children.Add(rateValueTb);
                    var minRateLabel = new TextBlock { Text = "Min Rate:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(12, 4, 10, 4) };
                    Grid.SetColumn(minRateLabel, 4);
                    rowGrid.Children.Add(minRateLabel);
                    Grid.SetColumn(minRateValueTb, 5);
                    rowGrid.Children.Add(minRateValueTb);

                    if (conversionProtoAcb != null && conversionProtoRowState != null)
                    {
                        var conversionProtoLabel = new TextBlock
                        {
                            Text = "Transform into:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(20, 4, 10, 4),
                            IsVisible = !string.IsNullOrWhiteSpace(conversionProtoEntry.Value)
                        };
                        Grid.SetColumn(conversionProtoLabel, 6);
                        rowGrid.Children.Add(conversionProtoLabel);
                        conversionProtoAcb.IsVisible = conversionProtoLabel.IsVisible;
                        Grid.SetColumn(conversionProtoAcb, 7);
                        rowGrid.Children.Add(conversionProtoAcb);

                        Button? addConversionButton = null;
                        Button? removeConversionButton = null;
                        if (!_isReadOnly)
                        {
                            addConversionButton = new Button
                            {
                                Content = "Transform into",
                                Classes = { "add-component" },
                                HorizontalAlignment = HorizontalAlignment.Left,
                                Margin = new Thickness(8, 0, 0, 0),
                                IsVisible = !conversionProtoLabel.IsVisible
                            };
                            addConversionButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                conversionProtoLabel.IsVisible = true;
                                conversionProtoAcb.IsVisible = true;
                                conversionProtoRowState.IncludeInSerialization = true;
                                addConversionButton.IsVisible = false;
                                if (removeConversionButton != null)
                                    removeConversionButton.IsVisible = true;
                                MarkDirty();
                            };
                            Grid.SetColumn(addConversionButton, 6);
                            Grid.SetColumnSpan(addConversionButton, 2);
                            rowGrid.Children.Add(addConversionButton);

                            removeConversionButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(8, 0, 0, 0),
                                IsVisible = conversionProtoLabel.IsVisible
                            };
                            removeConversionButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                conversionProtoAcb.Text = "";
                                conversionProtoLabel.IsVisible = false;
                                conversionProtoAcb.IsVisible = false;
                                conversionProtoRowState.IncludeInSerialization = false;
                                removeConversionButton.IsVisible = false;
                                if (addConversionButton != null)
                                    addConversionButton.IsVisible = true;
                                MarkDirty();
                            };
                            Grid.SetColumn(removeConversionButton, 8);
                            rowGrid.Children.Add(removeConversionButton);
                        }
                    }

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" } };
                        removeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            convertRatesContainer.Children.Remove(rowGrid);
                            state.StructuredFieldRows["rate"].Remove(rateRowState);
                            state.StructuredFieldRows["minrate"].Remove(minRateRowState);
                            if (conversionProtoRowState != null &&
                                state.StructuredFieldRows.TryGetValue("conversionprotoid", out var conversionRows))
                            {
                                conversionRows.Remove(conversionProtoRowState);
                            }
                            MarkDirty();
                        };
                        Grid.SetColumn(removeButton, supportsRateLinkedConversion ? 10 : 7);
                        rowGrid.Children.Add(removeButton);
                    }

                    convertRatesContainer.Children.Add(rowGrid);
                }

                if (rateEntries.Count == 0)
                {
                    if (!_isReadOnly)
                        AddConvertRateRow();
                }
                else
                {
                    foreach (var rateEntry in rateEntries)
                    {
                        var rateType = rateEntry.Attributes.TryGetValue("type", out var currentRateType) ? currentRateType : "";
                        AddConvertRateRow(
                            rateEntry,
                            ConsumeMinRateEntryForType(rateType),
                            ConsumeConversionProtoEntryForSourceType(rateType));
                    }
                }

                if (!_isReadOnly)
                {
                    var addRateButton = new Button
                    {
                        Content = "Add Rate",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addRateButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;
                        AddConvertRateRow();
                        MarkDirty();
                    };
                    convertRatesSection.Children.Add(addRateButton);
                }

                state.AdditionalFieldsContainer.Children.Add(convertRatesSection);

                void AddConvertOptionalSimpleRow(string tag, string label)
                {
                    var isVisible = ShouldShowConvertOptionalField(tag);
                    if (isVisible)
                    {
                        var row = new Grid
                        {
                            ColumnDefinitions = !_isReadOnly
                                ? new ColumnDefinitions("180, 140, 32")
                                : new ColumnDefinitions("180, 140"),
                            Margin = new Thickness(0, 2, 0, 2),
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        row.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 10, 4)
                        });
                        var editor = CreateSimpleEditor(tag);
                        if (editor is TextBox tb)
                            tb.Width = 140;
                        else if (editor is AutoCompleteBox acb)
                            acb.Width = 140;
                        Grid.SetColumn(editor, 1);
                        row.Children.Add(editor);
                        if (!_isReadOnly)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(8, 0, 0, 0)
                            };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                MarkDirty();
                                RefreshProtoActionMetadataPanels(state);
                            };
                            Grid.SetColumn(removeButton, 2);
                            row.Children.Add(removeButton);
                        }
                        state.AdditionalFieldsContainer.Children.Add(row);
                    }
                    else if (!_isReadOnly)
                    {
                        var addButton = new Button
                        {
                            Content = label,
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;
                            state.ForcedVisibleFieldTags.Add(tag);
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };
                        state.AdditionalFieldsContainer.Children.Add(addButton);
                    }
                }

                var extraRateVisible = ShouldShowConvertOptionalField("extraratepertargethp");
                var workingRangeVisible = ShouldShowConvertOptionalField("workingrangeslack");
                if (extraRateVisible || workingRangeVisible)
                {
                    var sharedOptionalRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };

                    void AddSharedOptionalField(string tag, string label)
                    {
                        if (!ShouldShowConvertOptionalField(tag))
                            return;

                        var fieldGroup = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 6,
                            Margin = new Thickness(sharedOptionalRow.Children.Count == 0 ? 0 : 12, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center,
                        };
                        fieldGroup.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center
                        });

                        var editor = CreateSimpleEditor(tag);
                        if (editor is TextBox tb)
                            tb.Width = 120;
                        else if (editor is AutoCompleteBox acb)
                            acb.Width = 120;
                        fieldGroup.Children.Add(editor);

                        if (!_isReadOnly)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(2, 0, 0, 0)
                            };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;
                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                MarkDirty();
                                RefreshProtoActionMetadataPanels(state);
                            };
                            fieldGroup.Children.Add(removeButton);
                        }

                        sharedOptionalRow.Children.Add(fieldGroup);
                    }

                    AddSharedOptionalField("extraratepertargethp", "Extra Rate Per Target HP");
                    AddSharedOptionalField("workingrangeslack", "Working Range Slack");
                    state.AdditionalFieldsContainer.Children.Add(sharedOptionalRow);
                }

                if (!_isReadOnly)
                {
                    var optionalButtonsRow = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Margin = new Thickness(0, 2, 0, 2)
                    };

                    void AddOptionalButton(string tag, string label)
                    {
                        var addButton = new Button
                        {
                            Content = label,
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;
                            state.ForcedVisibleFieldTags.Add(tag);
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };
                        optionalButtonsRow.Children.Add(addButton);
                    }

                    if (!extraRateVisible)
                        AddOptionalButton("extraratepertargethp", "Extra Rate Per Target HP");
                    if (!workingRangeVisible)
                        AddOptionalButton("workingrangeslack", "Working Range Slack");
                    if (optionalButtonsRow.Children.Count > 0)
                        state.AdditionalFieldsContainer.Children.Add(optionalButtonsRow);
                }

                var animationRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 200"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                animationRow.Children.Add(new TextBlock
                {
                    Text = "Animation:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                var animEditor = CreateSimpleEditor("anim");
                animEditor.Width = 200;
                Grid.SetColumn(animEditor, 1);
                animationRow.Children.Add(animEditor);
                state.AdditionalFieldsContainer.Children.Add(animationRow);

                if (_isReadOnly || ShouldShowConvertOptionalField("attachprotounit"))
                    AddConvertOptionalSimpleRow("attachprotounit", "Attach Proto Unit");

                if (IsCharmedConvert())
                {
                    var typedDurationEntries = GetCurrentStructuredEntries("typedduration");
                    var typedStunEntries = GetCurrentStructuredEntries("typedstunduration");
                    state.StructuredFieldRows["typedduration"] = [];
                    state.StructuredFieldRows["typedstunduration"] = [];

                    var typedStunEntriesByType = typedStunEntries
                        .GroupBy(entry => entry.Attributes.TryGetValue("type", out var typeValue) ? typeValue?.Trim() ?? "" : "",
                            StringComparer.OrdinalIgnoreCase)
                        .ToDictionary(group => group.Key, group => new Queue<ProtoActionStructuredFieldEntry>(group), StringComparer.OrdinalIgnoreCase);

                    ProtoActionStructuredFieldEntry? ConsumeTypedStunEntryForType(string type)
                    {
                        var key = type?.Trim() ?? "";
                        if (typedStunEntriesByType.TryGetValue(key, out var matchingEntries) && matchingEntries.Count > 0)
                            return matchingEntries.Dequeue();

                        return null;
                    }

                    var typedSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 6) };
                    typedSection.Children.Add(new TextBlock
                    {
                        Text = "Duration by type:",
                        FontWeight = FontWeight.SemiBold
                    });
                    var typedRowsContainer = new StackPanel { Spacing = 4 };
                    typedSection.Children.Add(typedRowsContainer);

                    void AddTypedDurationRow(
                        ProtoActionStructuredFieldEntry? initialDurationEntry = null,
                        ProtoActionStructuredFieldEntry? initialStunEntry = null)
                    {
                        var durationEntry = initialDurationEntry ?? new ProtoActionStructuredFieldEntry();
                        var stunEntry = initialStunEntry ?? new ProtoActionStructuredFieldEntry();
                        var hasStun = initialStunEntry != null &&
                                      (!string.IsNullOrWhiteSpace(stunEntry.Value) || stunEntry.Attributes.Count > 0);

                        var rowGrid = new Grid
                        {
                            ColumnDefinitions = !_isReadOnly
                                ? new ColumnDefinitions("70, 180, 80, 100, Auto, 130, 100, 32, 20, 32")
                                : new ColumnDefinitions("70, 180, 80, 100, Auto, 130, 100"),
                            Margin = new Thickness(0, 2, 0, 2),
                            HorizontalAlignment = HorizontalAlignment.Left
                        };

                        var durationTypeAcb = new AutoCompleteBox
                        {
                            Text = durationEntry.Attributes.TryGetValue("type", out var durationTypeValue) ? durationTypeValue : "",
                            Width = 180,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            ItemsSource = GetAvailableBuildLimitTargets(),
                            IsEnabled = !_isReadOnly
                        };
                        EnableDropdownAutoComplete(durationTypeAcb);
                        durationTypeAcb.TextChanged += async (_, _) =>
                        {
                            if (_isPopulating)
                                return;
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        };
                        var durationValueTb = new TextBox
                        {
                            Text = durationEntry.Value ?? "",
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        };
                        AttachProtoActionDecimalBehavior(durationValueTb);
                        durationValueTb.TextChanged += async (_, _) =>
                        {
                            if (_isPopulating)
                                return;
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        };
                        var durationRowState = new ProtoActionStructuredFieldRowState
                        {
                            Tag = "typedduration",
                            RowPanel = rowGrid,
                            ValueTb = durationValueTb
                        };
                        durationRowState.AttributeEditors["type"] = durationTypeAcb;
                        state.StructuredFieldRows["typedduration"].Add(durationRowState);

                        var stunValueTb = new TextBox
                        {
                            Text = stunEntry.Value ?? "",
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        };
                        AttachProtoActionDecimalBehavior(stunValueTb);
                        stunValueTb.TextChanged += async (_, _) =>
                        {
                            if (_isPopulating)
                                return;
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        };
                        var stunRowState = new ProtoActionStructuredFieldRowState
                        {
                            Tag = "typedstunduration",
                            RowPanel = rowGrid,
                            ValueTb = stunValueTb,
                            IncludeInSerialization = hasStun
                        };
                        stunRowState.AttributeEditors["type"] = durationTypeAcb;
                        state.StructuredFieldRows["typedstunduration"].Add(stunRowState);

                        rowGrid.Children.Add(new TextBlock { Text = "Type:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                        Grid.SetColumn(durationTypeAcb, 1);
                        rowGrid.Children.Add(durationTypeAcb);
                        var durationValueLabel = new TextBlock { Text = "Duration:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(12, 4, 10, 4) };
                        Grid.SetColumn(durationValueLabel, 2);
                        rowGrid.Children.Add(durationValueLabel);
                        Grid.SetColumn(durationValueTb, 3);
                        rowGrid.Children.Add(durationValueTb);

                        var stunValueLabel = new TextBlock
                        {
                            Text = "Stun Duration:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(20, 4, 10, 4),
                            IsVisible = hasStun
                        };
                        Grid.SetColumn(stunValueLabel, 5);
                        rowGrid.Children.Add(stunValueLabel);
                        stunValueTb.IsVisible = hasStun;
                        Grid.SetColumn(stunValueTb, 6);
                        rowGrid.Children.Add(stunValueTb);

                        Button? addTypedStunButton = null;
                        Button? removeTypedStunButton = null;
                        if (!_isReadOnly)
                        {
                            addTypedStunButton = new Button
                            {
                                Content = "Stun duration by Type",
                                Classes = { "add-component" },
                                HorizontalAlignment = HorizontalAlignment.Left,
                                Margin = new Thickness(8, 0, 0, 0),
                                IsVisible = !hasStun
                            };
                            addTypedStunButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                stunValueLabel.IsVisible = true;
                                stunValueTb.IsVisible = true;
                                stunRowState.IncludeInSerialization = true;
                                addTypedStunButton.IsVisible = false;
                                if (removeTypedStunButton != null)
                                    removeTypedStunButton.IsVisible = true;
                                MarkDirty();
                            };
                            Grid.SetColumn(addTypedStunButton, 5);
                            Grid.SetColumnSpan(addTypedStunButton, 2);
                            rowGrid.Children.Add(addTypedStunButton);

                            removeTypedStunButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(2, 0, 0, 0),
                                IsVisible = hasStun
                            };
                            removeTypedStunButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                stunValueTb.Text = "";
                                stunValueLabel.IsVisible = false;
                                stunValueTb.IsVisible = false;
                                stunRowState.IncludeInSerialization = false;
                                removeTypedStunButton.IsVisible = false;
                                if (addTypedStunButton != null)
                                    addTypedStunButton.IsVisible = true;
                                MarkDirty();
                            };
                            Grid.SetColumn(removeTypedStunButton, 7);
                            rowGrid.Children.Add(removeTypedStunButton);
                        }

                        if (!_isReadOnly)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(12, 0, 0, 0) };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;
                                typedRowsContainer.Children.Remove(rowGrid);
                                state.StructuredFieldRows["typedduration"].Remove(durationRowState);
                                state.StructuredFieldRows["typedstunduration"].Remove(stunRowState);
                                MarkDirty();
                            };
                            Grid.SetColumn(removeButton, 9);
                            rowGrid.Children.Add(removeButton);
                        }

                        typedRowsContainer.Children.Add(rowGrid);
                    }

                    if (typedDurationEntries.Count == 0)
                    {
                        if (!_isReadOnly)
                            AddTypedDurationRow();
                    }
                    else
                    {
                        foreach (var typedDurationEntry in typedDurationEntries)
                        {
                            var typedDurationType = typedDurationEntry.Attributes.TryGetValue("type", out var durationTypeValue) ? durationTypeValue : "";
                            AddTypedDurationRow(
                                typedDurationEntry,
                                ConsumeTypedStunEntryForType(typedDurationType));
                        }
                    }

                    if (!_isReadOnly)
                    {
                        var addButton = new Button
                        {
                            Content = "Add Duration by Type",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;
                            AddTypedDurationRow();
                            MarkDirty();
                        };
                        typedSection.Children.Add(addButton);
                    }
                    var rateSectionIndex = state.AdditionalFieldsContainer.Children.IndexOf(convertRatesSection);
                    state.AdditionalFieldsContainer.Children.Insert(Math.Max(0, rateSectionIndex), typedSection);
                }
            }
            else if (IsSpawnActionType(actionType))
            {
                state.CoreFieldsGrid.IsVisible = false;
                state.RofLabel.IsVisible = false;
                state.RofTb.IsVisible = false;
                state.MaxRangeLabel.IsVisible = false;
                state.MaxRangeTb.IsVisible = false;

                void AddSpawnOptionalSimpleRow(string tag, string label)
                {
                    var currentValue = currentValues.TryGetValue(tag, out var overriddenValue)
                        ? overriddenValue
                        : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
                    var isVisible = !string.IsNullOrWhiteSpace(currentValue) || state.ForcedVisibleFieldTags.Contains(tag);
                    if (isVisible)
                    {
                        var row = new Grid
                        {
                            ColumnDefinitions = !_isReadOnly
                                ? new ColumnDefinitions("Auto, 200, 32")
                                : new ColumnDefinitions("Auto, 200"),
                            Margin = new Thickness(0, 2, 0, 2),
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        row.Children.Add(new TextBlock
                        {
                            Text = label + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 10, 4)
                        });
                        var editor = CreateSimpleEditor(tag);
                        editor.Width = 200;
                        Grid.SetColumn(editor, 1);
                        row.Children.Add(editor);
                        if (!_isReadOnly)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(2, 0, 0, 0)
                            };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                state.ForcedVisibleFieldTags.Remove(tag);
                                state.AdditionalFieldControls.Remove(tag);
                                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                                MarkDirty();
                                RefreshProtoActionMetadataPanels(state);
                            };
                            Grid.SetColumn(removeButton, 2);
                            row.Children.Add(removeButton);
                        }
                        state.AdditionalFieldsContainer.Children.Add(row);
                    }
                    else if (!_isReadOnly)
                    {
                        var addButton = new Button
                        {
                            Content = label,
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            state.ForcedVisibleFieldTags.Add(tag);
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };
                        state.AdditionalFieldsContainer.Children.Add(addButton);
                    }
                }

                var rateEntries = GetCurrentStructuredEntries("rate");
                var minRateEntries = GetCurrentStructuredEntries("minrate");
                state.StructuredFieldRows["rate"] = [];
                state.StructuredFieldRows["minrate"] = [];

                var spawnAtTargetSection = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 4) };
                var spawnedUnitsSection = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 6) };
                Button? addSpawnAtTargetButton = null;
                Button? addSpawnedUnitButton = null;

                void AddSpawnAtTargetRow(ProtoActionStructuredFieldEntry? initialEntry = null)
                {
                    var entry = initialEntry ?? new ProtoActionStructuredFieldEntry();
                    var row = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                    row.Children.Add(new TextBlock { Text = "Spawn At Target:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
                    var typeEditor = new AutoCompleteBox
                    {
                        Text = entry.Attributes.TryGetValue("type", out var typeValue) ? typeValue : "",
                        Width = 180,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = GetAvailableBuildLimitTargets(),
                        IsEnabled = !_isReadOnly
                    };
                    EnableDropdownAutoComplete(typeEditor);
                    var valueEditor = new TextBox { Text = entry.Value ?? "", Width = 90, IsEnabled = !_isReadOnly, Margin = new Thickness(8, 0, 0, 0) };
                    AttachProtoActionDecimalBehavior(valueEditor);
                    row.Children.Add(typeEditor);
                    row.Children.Add(valueEditor);
                    var rowState = new ProtoActionStructuredFieldRowState { Tag = "minrate", RowPanel = row, ValueTb = valueEditor };
                    rowState.AttributeEditors["type"] = typeEditor;
                    state.StructuredFieldRows["minrate"].Add(rowState);
                    typeEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                    valueEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                    if (!_isReadOnly && state.StructuredFieldRows["minrate"].Count > 1)
                    {
                        var remove = new Button { Classes = { "remove-button" }, Margin = new Thickness(2, 0, 0, 0) };
                        remove.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            state.StructuredFieldRows["minrate"].Remove(rowState);
                            spawnAtTargetSection.Children.Remove(row);
                            MarkDirty();
                        };
                        row.Children.Add(remove);
                    }
                    var addButtonIndex = addSpawnAtTargetButton == null ? -1 : spawnAtTargetSection.Children.IndexOf(addSpawnAtTargetButton);
                    if (addButtonIndex >= 0)
                        spawnAtTargetSection.Children.Insert(addButtonIndex, row);
                    else
                        spawnAtTargetSection.Children.Add(row);
                }

                void AddSpawnedUnitRow(ProtoActionStructuredFieldEntry? initialEntry = null)
                {
                    var entry = initialEntry ?? new ProtoActionStructuredFieldEntry();
                    var row = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                    row.Children.Add(new TextBlock { Text = "Spawned unit:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
                    var protoUnitEditor = new AutoCompleteBox
                    {
                        Text = entry.Attributes.TryGetValue("type", out var protoUnitValue) ? protoUnitValue : "",
                        Width = 180,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        IsEnabled = !_isReadOnly
                    };
                    ConfigureStrictSuggestionAutoComplete(protoUnitEditor, GetAvailableTrainUnitNames(), protoUnitEditor.Text ?? "");
                    var valueEditor = new TextBox { Text = entry.Value ?? "1.0", Width = 90, IsEnabled = !_isReadOnly, Margin = new Thickness(8, 0, 0, 0) };
                    AttachProtoActionDecimalBehavior(valueEditor);
                    row.Children.Add(protoUnitEditor);
                    row.Children.Add(valueEditor);
                    var rowState = new ProtoActionStructuredFieldRowState { Tag = "rate", RowPanel = row, ValueTb = valueEditor };
                    rowState.AttributeEditors["type"] = protoUnitEditor;
                    state.StructuredFieldRows["rate"].Add(rowState);
                    protoUnitEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                    valueEditor.TextChanged += async (_, _) => { if (!_isPopulating && await CheckStartLocalMod()) MarkDirty(); };
                    if (!_isReadOnly && state.StructuredFieldRows["rate"].Count > 1)
                    {
                        var remove = new Button { Classes = { "remove-button" }, Margin = new Thickness(2, 0, 0, 0) };
                        remove.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            state.StructuredFieldRows["rate"].Remove(rowState);
                            spawnedUnitsSection.Children.Remove(row);
                            MarkDirty();
                        };
                        row.Children.Add(remove);
                    }
                    var addButtonIndex = addSpawnedUnitButton == null ? -1 : spawnedUnitsSection.Children.IndexOf(addSpawnedUnitButton);
                    if (addButtonIndex >= 0)
                        spawnedUnitsSection.Children.Insert(addButtonIndex, row);
                    else
                        spawnedUnitsSection.Children.Add(row);
                }

                foreach (var entry in minRateEntries)
                    AddSpawnAtTargetRow(entry);
                if (minRateEntries.Count == 0)
                    AddSpawnAtTargetRow();
                if (!_isReadOnly)
                {
                    addSpawnAtTargetButton = new Button { Content = "Add Spawn At Target", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left };
                    addSpawnAtTargetButton.Click += async (_, _) => { if (await CheckStartLocalMod()) { AddSpawnAtTargetRow(); MarkDirty(); } };
                    spawnAtTargetSection.Children.Add(addSpawnAtTargetButton);
                }

                foreach (var entry in rateEntries)
                    AddSpawnedUnitRow(entry);
                if (rateEntries.Count == 0)
                    AddSpawnedUnitRow();
                if (!_isReadOnly)
                {
                    addSpawnedUnitButton = new Button { Content = "Add Spawned Unit", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left };
                    addSpawnedUnitButton.Click += async (_, _) => { if (await CheckStartLocalMod()) { AddSpawnedUnitRow(); MarkDirty(); } };
                    spawnedUnitsSection.Children.Add(addSpawnedUnitButton);
                }

                state.AdditionalFieldsContainer.Children.Add(spawnedUnitsSection);
                state.AdditionalFieldsContainer.Children.Add(spawnAtTargetSection);
                AddSpawnOptionalSimpleRow("anim", "Animation");
            }
            else if (IsTradeActionType(actionType))
            {
                state.CoreFieldsGrid.IsVisible = false;
                state.RofLabel.IsVisible = false;
                state.RofTb.IsVisible = false;
                state.MaxRangeLabel.IsVisible = false;
                state.MaxRangeTb.IsVisible = false;

                var maxRangeMirror = new TextBox
                {
                    Text = state.MaxRangeTb.Text,
                    IsEnabled = !_isReadOnly,
                    Width = 90
                };
                AttachProtoActionDecimalBehavior(maxRangeMirror);
                state.MirroredSimpleSourceControls[maxRangeMirror] = "maxrange";
                maxRangeMirror.TextChanged += async (_, _) =>
                {
                    state.MaxRangeTb.Text = maxRangeMirror.Text;
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                var maxRangeRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 90"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                maxRangeRow.Children.Add(new TextBlock
                {
                    Text = "Max Range:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                Grid.SetColumn(maxRangeMirror, 1);
                maxRangeRow.Children.Add(maxRangeMirror);
                state.AdditionalFieldsContainer.Children.Add(maxRangeRow);

                var rateEntries = GetCurrentStructuredEntries("rate");
                state.StructuredFieldRows["rate"] = [];

                var tradeRatesSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 6) };
                var tradeRatesContainer = new StackPanel { Spacing = 4 };
                tradeRatesSection.Children.Add(tradeRatesContainer);

                void AddTradeRateRow(ProtoActionStructuredFieldEntry? initialRateEntry = null)
                {
                    var rateEntry = initialRateEntry ?? new ProtoActionStructuredFieldEntry();
                    var rowGrid = new Grid
                    {
                        ColumnDefinitions = !_isReadOnly
                            ? new ColumnDefinitions("Auto, 180, 90, 32")
                            : new ColumnDefinitions("Auto, 180, 90"),
                        Margin = new Thickness(0, 2, 0, 2),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };

                    var rateTypeAcb = new AutoCompleteBox
                    {
                        Text = rateEntry.Attributes.TryGetValue("type", out var currentRateType) ? currentRateType : "",
                        Width = 180,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = GetAvailableBuildLimitTargets(),
                        IsEnabled = !_isReadOnly
                    };
                    EnableDropdownAutoComplete(rateTypeAcb);
                    var rateValueTb = new TextBox
                    {
                        Text = rateEntry.Value ?? "1.0",
                        Width = 90,
                        IsEnabled = !_isReadOnly
                    };
                    AttachProtoActionDecimalBehavior(rateValueTb);
                    var rateRowState = new ProtoActionStructuredFieldRowState
                    {
                        Tag = "rate",
                        RowPanel = rowGrid,
                        ValueTb = rateValueTb
                    };
                    rateRowState.AttributeEditors["type"] = rateTypeAcb;
                    state.StructuredFieldRows["rate"].Add(rateRowState);

                    rateTypeAcb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };
                    rateValueTb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    };

                    rowGrid.Children.Add(new TextBlock { Text = "Rate:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) });
                    Grid.SetColumn(rateTypeAcb, 1);
                    rowGrid.Children.Add(rateTypeAcb);
                    Grid.SetColumn(rateValueTb, 2);
                    rowGrid.Children.Add(rateValueTb);

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0) };
                        removeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            tradeRatesContainer.Children.Remove(rowGrid);
                            state.StructuredFieldRows["rate"].Remove(rateRowState);
                            MarkDirty();
                        };
                        Grid.SetColumn(removeButton, 3);
                        rowGrid.Children.Add(removeButton);
                    }

                    tradeRatesContainer.Children.Add(rowGrid);
                }

                if (rateEntries.Count == 0)
                {
                    if (!_isReadOnly)
                        AddTradeRateRow();
                }
                else
                {
                    foreach (var rateEntry in rateEntries)
                        AddTradeRateRow(rateEntry);
                }

                if (!_isReadOnly)
                {
                    var addRateButton = new Button
                    {
                        Content = "Add Rate",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addRateButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        AddTradeRateRow();
                        MarkDirty();
                    };
                    tradeRatesSection.Children.Add(addRateButton);
                }

                state.AdditionalFieldsContainer.Children.Add(tradeRatesSection);

                var tradeOtherResourceTypes = ProtoConstants.KnownResourceTypes
                    .Where(resource => !resource.Equals("Gold", StringComparison.OrdinalIgnoreCase))
                    .ToArray();
                var otherResourceEntries = GetCurrentStructuredEntries("minrate");
                state.StructuredFieldRows["minrate"] = [];
                var showGrantOtherResources = state.ForcedVisibleFieldTags.Contains("minrate") || otherResourceEntries.Count > 0;
                var tradeGrantButtonsRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2)
                };

                var modifyAmountValue = currentValues.TryGetValue("modifyamount", out var currentModifyAmount)
                    ? currentModifyAmount
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifyamount");
                var modifyExponentValue = currentValues.TryGetValue("modifyexponent", out var currentModifyExponent)
                    ? currentModifyExponent
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifyexponent");
                var showGrantResourcesToAlly = state.ForcedVisibleFieldTags.Contains("modifyamount") ||
                                               !string.IsNullOrWhiteSpace(modifyAmountValue) ||
                                               !string.IsNullOrWhiteSpace(modifyExponentValue);

                if (showGrantOtherResources)
                {
                    var grantsContainer = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Margin = new Thickness(0, 2, 0, 2)
                    };
                    grantsContainer.Children.Add(new TextBlock
                    {
                        Text = "Grants:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 8, 4)
                    });
                    Button? addOtherResourceButton = null;
                    var refreshingResourceChoices = false;

                    void RefreshResourceChoices()
                    {
                        if (refreshingResourceChoices)
                            return;

                        refreshingResourceChoices = true;
                        try
                        {
                            foreach (var grantRow in state.StructuredFieldRows["minrate"])
                            {
                                if (!grantRow.AttributeEditors.TryGetValue("type", out var editor) || editor is not ComboBox combo)
                                    continue;

                                var selected = combo.SelectedItem?.ToString() ?? "";
                                var usedByOtherRows = state.StructuredFieldRows["minrate"]
                                    .Where(other => !ReferenceEquals(other, grantRow))
                                    .Select(other => other.AttributeEditors.TryGetValue("type", out var otherEditor) && otherEditor is ComboBox otherCombo
                                        ? otherCombo.SelectedItem?.ToString() ?? ""
                                        : "")
                                    .Where(value => !string.IsNullOrWhiteSpace(value))
                                    .ToHashSet(StringComparer.OrdinalIgnoreCase);
                                var choices = tradeOtherResourceTypes
                                    .Where(resource => resource.Equals(selected, StringComparison.OrdinalIgnoreCase) || !usedByOtherRows.Contains(resource))
                                    .ToList();
                                if (!string.IsNullOrWhiteSpace(selected) &&
                                    !choices.Contains(selected, StringComparer.OrdinalIgnoreCase) &&
                                    !tradeOtherResourceTypes.Contains(selected, StringComparer.OrdinalIgnoreCase))
                                {
                                    // Preserve a legacy value already present in XML without offering it for new rows.
                                    choices.Insert(0, selected);
                                }
                                combo.ItemsSource = choices;
                                combo.SelectedItem = choices.FirstOrDefault(resource => resource.Equals(selected, StringComparison.OrdinalIgnoreCase));
                            }

                            if (addOtherResourceButton != null)
                            {
                                var usedResources = state.StructuredFieldRows["minrate"]
                                    .Select(row => row.AttributeEditors.TryGetValue("type", out var editor) && editor is ComboBox combo
                                        ? combo.SelectedItem?.ToString() ?? ""
                                        : "")
                                    .Where(value => !string.IsNullOrWhiteSpace(value))
                                    .ToHashSet(StringComparer.OrdinalIgnoreCase);
                                addOtherResourceButton.IsVisible = state.StructuredFieldRows["minrate"].Count < tradeOtherResourceTypes.Length &&
                                                                   tradeOtherResourceTypes.Any(resource => !usedResources.Contains(resource));
                            }
                        }
                        finally
                        {
                            refreshingResourceChoices = false;
                        }
                    }

                    void AddGrantRow(ProtoActionStructuredFieldEntry? initialEntry = null)
                    {
                        if (initialEntry == null && state.StructuredFieldRows["minrate"].Count >= tradeOtherResourceTypes.Length)
                            return;

                        var entry = initialEntry ?? new ProtoActionStructuredFieldEntry();
                        var row = new WrapPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        var resourceValue = entry.Attributes.TryGetValue("type", out var currentResource) ? currentResource : "";
                        if (string.IsNullOrWhiteSpace(resourceValue))
                        {
                            var alreadyUsed = state.StructuredFieldRows["minrate"]
                                .Select(existing => existing.AttributeEditors.TryGetValue("type", out var editor) && editor is ComboBox combo
                                    ? combo.SelectedItem?.ToString() ?? ""
                                    : "")
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                            resourceValue = tradeOtherResourceTypes.FirstOrDefault(resource => !alreadyUsed.Contains(resource)) ?? "";
                        }
                        var initialChoices = tradeOtherResourceTypes.ToList();
                        if (!string.IsNullOrWhiteSpace(resourceValue) &&
                            !initialChoices.Contains(resourceValue, StringComparer.OrdinalIgnoreCase))
                        {
                            initialChoices.Insert(0, resourceValue);
                        }
                        var resourceCombo = new ComboBox
                        {
                            ItemsSource = initialChoices,
                            SelectedItem = initialChoices.FirstOrDefault(resource =>
                                resource.Equals(resourceValue, StringComparison.OrdinalIgnoreCase)),
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        };
                        var valueEditor = new TextBox
                        {
                            Text = entry.Value ?? "",
                            Width = 90,
                            IsEnabled = !_isReadOnly,
                            Margin = new Thickness(8, 0, 0, 0)
                        };
                        AttachProtoActionDecimalBehavior(valueEditor);
                        row.Children.Add(resourceCombo);
                        row.Children.Add(valueEditor);
                        var rowState = new ProtoActionStructuredFieldRowState
                        {
                            Tag = "minrate",
                            RowPanel = row,
                            ValueTb = valueEditor
                        };
                        rowState.AttributeEditors["type"] = resourceCombo;
                        state.StructuredFieldRows["minrate"].Add(rowState);
                        resourceCombo.SelectionChanged += async (_, _) =>
                        {
                            if (refreshingResourceChoices)
                                return;

                            RefreshResourceChoices();
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        valueEditor.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        if (!_isReadOnly)
                        {
                            var removeButton = new Button { Classes = { "remove-button" }, Margin = new Thickness(2, 0, 0, 0) };
                            removeButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;
                                state.StructuredFieldRows["minrate"].Remove(rowState);
                                grantsContainer.Children.Remove(row);
                                RefreshResourceChoices();
                                if (state.StructuredFieldRows["minrate"].Count == 0)
                                {
                                    state.ForcedVisibleFieldTags.Remove("minrate");
                                    ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "minrate", []);
                                    RefreshProtoActionMetadataPanels(state);
                                }
                                MarkDirty();
                            };
                            row.Children.Add(removeButton);
                        }
                        var addButtonIndex = addOtherResourceButton == null
                            ? -1
                            : grantsContainer.Children.IndexOf(addOtherResourceButton);
                        if (addButtonIndex >= 0)
                            grantsContainer.Children.Insert(addButtonIndex, row);
                        else
                            grantsContainer.Children.Add(row);
                        RefreshResourceChoices();
                    }

                    foreach (var entry in otherResourceEntries)
                        AddGrantRow(entry);
                    if (otherResourceEntries.Count == 0)
                        AddGrantRow();
                    if (!_isReadOnly)
                    {
                        addOtherResourceButton = new Button { Content = "Add other resource", Classes = { "add-component" }, HorizontalAlignment = HorizontalAlignment.Left };
                        addOtherResourceButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            AddGrantRow();
                            MarkDirty();
                        };
                        grantsContainer.Children.Add(addOtherResourceButton);
                        RefreshResourceChoices();
                    }
                    state.AdditionalFieldsContainer.Children.Add(grantsContainer);
                }
                else if (!_isReadOnly)
                {
                    var addButton = new Button
                    {
                        Content = "Grant Other Resources",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        state.ForcedVisibleFieldTags.Add("minrate");
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    };
                    tradeGrantButtonsRow.Children.Add(addButton);
                }

                if (!showGrantOtherResources || !showGrantResourcesToAlly)
                    state.AdditionalFieldsContainer.Children.Add(tradeGrantButtonsRow);

                async Task RemoveGrantResourcesToAllyAsync()
