                var maxRangeMirror = new TextBox
                {
                    Text = state.MaxRangeTb.Text,
                    IsEnabled = !_isReadOnly
                };
                AttachProtoActionDecimalBehavior(maxRangeMirror);
                state.MirroredSimpleSourceControls[maxRangeMirror] = "maxrange";
                maxRangeMirror.TextChanged += async (_, _) =>
                {
                    state.MaxRangeTb.Text = maxRangeMirror.Text;
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                            MarkDirty();
                    }
                };

                var maxRangeRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                maxRangeRow.Children.Add(new TextBlock
                {
                    Text = "Max Range:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                maxRangeMirror.Width = 100;
                maxRangeRow.Children.Add(maxRangeMirror);
                state.AdditionalFieldsContainer.Children.Add(maxRangeRow);

                var row2 = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                ApplyProtoActionFieldWidth(animEditor, "anim");
                row2.Children.Add(CreateLabeledFieldGroup("Animation:", animEditor, new Thickness(0, 0, 16, 4)));
                var projectileEditor = CreateSimpleEditor("projectile");
                ApplyProtoActionFieldWidth(projectileEditor, "projectile");
                row2.Children.Add(CreateLabeledFieldGroup("Projectile:", projectileEditor, new Thickness(0, 0, 0, 4)));
                state.AdditionalFieldsContainer.Children.Add(row2);

                var rateDefinition = ProtoActionMetadataCatalog.GetFieldDefinition("rate");
                var rateEntries = GetCurrentStructuredEntries("rate");
                var rateSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
                rateSection.Children.Add(new TextBlock { Text = rateDefinition.Label + ":", FontWeight = FontWeight.SemiBold });
                var ratesContainer = new StackPanel { Spacing = 4 };
                rateSection.Children.Add(ratesContainer);
                state.StructuredFieldRows["rate"] = [];

                void AddRateRowForBolster(ProtoActionStructuredFieldEntry? initialEntry = null)
                {
                    var rowPanel = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 6 };
                    var valueTb = new TextBox
                    {
                        Text = initialEntry?.Value ?? "",
                        Width = 140,
                        IsEnabled = !_isReadOnly
                    };
                    AttachProtoActionDecimalBehavior(valueTb);
                    valueTb.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        }
                    };
                    var rowState = new ProtoActionStructuredFieldRowState
                    {
                        Tag = "rate",
                        RowPanel = rowPanel,
                        ValueTb = valueTb
                    };
                    var typeAcb = new AutoCompleteBox
                    {
                        Text = initialEntry?.Attributes.TryGetValue("type", out var typeValue) == true ? typeValue : "",
                        Width = 170,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = GetAvailableBuildLimitTargets(),
                        IsEnabled = !_isReadOnly
                    };
                    EnableDropdownAutoComplete(typeAcb);
                    typeAcb.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        }
                    };
                    rowState.AttributeEditors["type"] = typeAcb;
                    rowPanel.Children.Add(new TextBlock { Text = "Type:", VerticalAlignment = VerticalAlignment.Center });
                    rowPanel.Children.Add(typeAcb);
                    rowPanel.Children.Add(valueTb);
                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" } };
                        removeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;
                            ratesContainer.Children.Remove(rowPanel);
                            state.StructuredFieldRows["rate"].Remove(rowState);
                            MarkDirty();
                        };
                        rowPanel.Children.Add(removeButton);
                    }
                    state.StructuredFieldRows["rate"].Add(rowState);
                    ratesContainer.Children.Add(rowPanel);
                }

                foreach (var entry in rateEntries)
                    AddRateRowForBolster(entry);
                if (rateEntries.Count == 0 && !_isReadOnly)
                    AddRateRowForBolster();

                if (!_isReadOnly)
                {
                    var addRateButton = new Button
                    {
                        Content = "Add Rate",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addRateButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;
                        AddRateRowForBolster();
                        MarkDirty();
                    };
                    rateSection.Children.Add(addRateButton);
                }
                state.AdditionalFieldsContainer.Children.Add(rateSection);
            }
        }

        if (IsAutoBoostActionType(actionType))
        {
            var modifyProtoEntries = GetCurrentStructuredEntries("modifyprotoid");
            var showModifyProtoId = state.ForcedVisibleFieldTags.Contains("modifyprotoid") || modifyProtoEntries.Count > 0;

            async Task RemoveAutoBoostModifyProtoIdAsync()
            {
                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                state.ForcedVisibleFieldTags.Remove("modifyprotoid");
                state.StructuredFieldRows.Remove("modifyprotoid");
                ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, "modifyprotoid", []);
                MarkDirty();
                RefreshProtoActionMetadataPanels(state);
            }

            if (showModifyProtoId)
            {
                var currentModifyProtoEntry = modifyProtoEntries.FirstOrDefault() ?? new ProtoActionStructuredFieldEntry();
                var modifyProtoAcb = new AutoCompleteBox
                {
                    Text = currentModifyProtoEntry.Value ?? "",
                    Width = 220,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    ItemsSource = GetAvailableTrainUnitNames(),
                    IsEnabled = !_isReadOnly
                };
                ConfigureStrictSuggestionAutoComplete(modifyProtoAcb, GetAvailableTrainUnitNames(), modifyProtoAcb.Text ?? "");
                modifyProtoAcb.Width = 200;
                modifyProtoAcb.MinWidth = 200;
                modifyProtoAcb.MaxWidth = 200;
                modifyProtoAcb.VerticalAlignment = VerticalAlignment.Center;
                modifyProtoAcb.TextChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };
                var modifyProtoRowState = new ProtoActionStructuredFieldRowState
                {
                    Tag = "modifyprotoid",
                    RowPanel = new StackPanel(),
                    ValueTb = modifyProtoAcb
                };
                state.StructuredFieldRows["modifyprotoid"] = [modifyProtoRowState];

                var modifyProtoRow = new Grid
                {
                    ColumnDefinitions = !_isReadOnly
                        ? new ColumnDefinitions("Auto, 200, 32")
                        : new ColumnDefinitions("Auto, 200"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left,
                    VerticalAlignment = VerticalAlignment.Center
                };
                modifyProtoRow.Children.Add(new TextBlock
                {
                    Text = "VFX:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });
                Grid.SetColumn(modifyProtoAcb, 1);
                modifyProtoRow.Children.Add(modifyProtoAcb);
                if (!_isReadOnly)
                {
                    var removeButton = new Button
                    {
                        Classes = { "remove-button" },
                        Margin = new Thickness(2, 0, 0, 0) };
                    removeButton.Click += async (_, _) => await RemoveAutoBoostModifyProtoIdAsync();
                    Grid.SetColumn(removeButton, 2);
                    modifyProtoRow.Children.Add(removeButton);
                }
                state.AdditionalFieldsContainer.Children.Add(modifyProtoRow);
                state.AutoBoostModifyProtoControl = modifyProtoRow;
            }
            else if (!_isReadOnly)
            {
                var addModifyProtoButton = new Button
                {
                    Content = "VFX",
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                addModifyProtoButton.Click += async (_, _) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    state.ForcedVisibleFieldTags.Add("modifyprotoid");
                    MarkDirty();
                    RefreshProtoActionMetadataPanels(state);
                };
                state.AdditionalFieldsContainer.Children.Add(addModifyProtoButton);
                state.AutoBoostModifyProtoControl = addModifyProtoButton;
            }
        }

        state.CustomFlagControls.Clear();
        if (IsAutoConvertActionType(actionType))
        {
            var convertPanel = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 8, 0, 2) };
            convertPanel.Children.Add(new TextBlock
            {
                Text = "Can be converted by:",
                FontWeight = FontWeight.SemiBold,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 10, 0)
            });

            var checkboxRow = convertPanel;

            CheckBox CreateConvertCheckBox(string label, bool isChecked, bool isEnabled = true)
                => new()
                {
                    Content = label,
                    IsChecked = isChecked,
                    IsEnabled = !_isReadOnly && isEnabled,
                    Margin = new Thickness(0, 0, 16, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };

            var playerCheckBox = CreateConvertCheckBox("Player", true, false);
            checkboxRow.Children.Add(playerCheckBox);

            async void WireFlagCheckBox(CheckBox checkBox, string flagTag, bool checkedMeansPresent)
            {
                checkBox.IsCheckedChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    var shouldHaveFlag = checkedMeansPresent
                        ? checkBox.IsChecked == true
                        : checkBox.IsChecked != true;

                    if (shouldHaveFlag)
                        state.SelectedFlagTags.Add(flagTag);
                    else
                        state.SelectedFlagTags.Remove(flagTag);

                    RenderProtoActionFlags(state);
                    MarkDirty();
                };
            }

            var alliesCheckBox = CreateConvertCheckBox(
                "Allies",
                !state.SelectedFlagTags.Contains("cannotbeconvertedbyallies"));
            state.CustomFlagControls["cannotbeconvertedbyallies"] = alliesCheckBox;
            RegisterProtoActionFlagSourceControl(state, alliesCheckBox, "cannotbeconvertedbyallies");
            checkboxRow.Children.Add(alliesCheckBox);
            WireFlagCheckBox(alliesCheckBox, "cannotbeconvertedbyallies", checkedMeansPresent: false);

            var enemiesCheckBox = CreateConvertCheckBox(
                "Enemies",
                !state.SelectedFlagTags.Contains("cannotbeconvertedbyenemies"));
            state.CustomFlagControls["cannotbeconvertedbyenemies"] = enemiesCheckBox;
            RegisterProtoActionFlagSourceControl(state, enemiesCheckBox, "cannotbeconvertedbyenemies");
            checkboxRow.Children.Add(enemiesCheckBox);
            WireFlagCheckBox(enemiesCheckBox, "cannotbeconvertedbyenemies", checkedMeansPresent: false);

            var natureCheckBox = CreateConvertCheckBox(
                "Nature",
                state.SelectedFlagTags.Contains("includenature"));
            state.CustomFlagControls["includenature"] = natureCheckBox;
            RegisterProtoActionFlagSourceControl(state, natureCheckBox, "includenature");
            checkboxRow.Children.Add(natureCheckBox);
            WireFlagCheckBox(natureCheckBox, "includenature", checkedMeansPresent: true);

            state.AdditionalFieldsContainer.Children.Add(convertPanel);
        }
        else if (IsReflectAttackActionType(actionType))
        {
            var reflectPanel = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 8, 0, 2),
                VerticalAlignment = VerticalAlignment.Center
            };
            reflectPanel.Children.Add(new TextBlock
            {
                Text = "Reflects attacks",
                Margin = new Thickness(0, 4, 8, 4),
                VerticalAlignment = VerticalAlignment.Center
            });

            CheckBox CreateReflectCheckBox(string label, bool isChecked)
                => new()
                {
                    Content = label,
                    IsChecked = isChecked,
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 0, 16, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };

            async void WireReflectFlagCheckBox(CheckBox checkBox, string flagTag)
            {
                checkBox.IsCheckedChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    if (checkBox.IsChecked == true)
                        state.SelectedFlagTags.Add(flagTag);
                    else
                        state.SelectedFlagTags.Remove(flagTag);

                    RenderProtoActionFlags(state);
                    MarkDirty();
                };
            }

            var meleeCheckBox = CreateReflectCheckBox(
                "Melee",
                state.SelectedFlagTags.Contains("reflecthandattacks"));
            state.CustomFlagControls["reflecthandattacks"] = meleeCheckBox;
            RegisterProtoActionFlagSourceControl(state, meleeCheckBox, "reflecthandattacks");
            reflectPanel.Children.Add(meleeCheckBox);
            WireReflectFlagCheckBox(meleeCheckBox, "reflecthandattacks");

            var rangedCheckBox = CreateReflectCheckBox(
                "Ranged",
                state.SelectedFlagTags.Contains("reflectrangedattacks"));
            state.CustomFlagControls["reflectrangedattacks"] = rangedCheckBox;
            RegisterProtoActionFlagSourceControl(state, rangedCheckBox, "reflectrangedattacks");
            reflectPanel.Children.Add(rangedCheckBox);
            WireReflectFlagCheckBox(rangedCheckBox, "reflectrangedattacks");

            state.AdditionalFieldsContainer.Children.Insert(0, reflectPanel);
        }
        if (showOptionalModelAttachmentFields)
        {
            async Task RemoveOptionalModelAttachmentAsync()
            {
                if (await BlockInheritedProtoActionRemovalAsync(
                        state,
                        OptionalModelAttachmentTags,
                        "Model Attachment"))
                {
                    return;
                }

                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                foreach (var tag in OptionalModelAttachmentTags)
                {
                    state.ForcedVisibleFieldTags.Remove(tag);
                    state.AdditionalFieldControls.Remove(tag);
                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                }
                if (IsAutoRangedModifyActionType(actionType))
                    state.SelectedFlagTags.Remove("modelattachmentonself");
                state.CustomValues[OptionalModelAttachmentHiddenStateKey] = "1";

                RenderProtoActionFlags(state);
                MarkDirty();
                RefreshProtoActionMetadataPanels(state);
            }

            Control CreateAttachmentEditor(string tag, string valueOverride, double? width = null)
            {
                var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
                Control editor = GetProtoActionValueSuggestions(tag) is List<string> suggestions
                    ? new AutoCompleteBox
                    {
                        Text = valueOverride,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = suggestions,
                        IsEnabled = !_isReadOnly,
                        Width = width ?? double.NaN
                    }
                    : new TextBox
                    {
                        Text = valueOverride,
                        IsEnabled = !_isReadOnly,
                        Width = width ?? double.NaN
                    };

                if (editor is TextBox textBox && definition.EditorKind == ProtoActionFieldEditorKind.Number)
                    AttachProtoActionDecimalBehavior(textBox);
                else if (AssetPathFieldTags.Contains(tag) && editor is TextBox assetTextBox)
                {
                    EditorTextFieldStyle.ConfigureTextBox(assetTextBox);
                }
                else if (editor is TextBox normalTextBox)
                    EditorTextFieldStyle.ConfigureTextBox(normalTextBox);
                if (editor is AutoCompleteBox autoCompleteBox)
                {
                    if (AssetPathFieldTags.Contains(tag))
                        EditorTextFieldStyle.ConfigureSelector(autoCompleteBox);
                    else
                        EditorTextFieldStyle.ConfigureSelector(autoCompleteBox);
                    EnableDropdownAutoComplete(autoCompleteBox);
                }

                if (AssetPathFieldTags.Contains(tag))
                    editor = CreateAssetPathEditor(tag, valueOverride, GetProtoActionValueSuggestions(tag) ?? []);
                ApplyProtoActionFieldWidth(editor, tag);

                if (!AssetPathFieldTags.Contains(tag) && editor is TextBox textEditor)
                {
                    textEditor.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        }
                    };
                }
                else if (!AssetPathFieldTags.Contains(tag) && editor is AutoCompleteBox autoEditor)
                {
                    autoEditor.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                                MarkDirty();
                        }
                    };
                }

                state.AdditionalFieldControls[tag] = editor;
                return editor;
            }

            var modelAttachmentValue = GetProtoActionDefaultSimpleValue(
                "modelattachment",
                currentValues.TryGetValue("modelattachment", out var currentModelAttachment)
                    ? currentModelAttachment
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modelattachment"));
            var modelAttachmentBoneValue = GetProtoActionDefaultSimpleValue(
                "modelattachmentbone",
                currentValues.TryGetValue("modelattachmentbone", out var currentBone)
                    ? currentBone
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modelattachmentbone"));
            var sharedAttachmentEditors = CreateProtoActionModelAttachmentEditors(
                modelAttachmentValue,
                modelAttachmentBoneValue);
            var modelAttachmentEditor = sharedAttachmentEditors.Attachment;
            var modelAttachmentBoneEditor = sharedAttachmentEditors.Bone;
            state.AdditionalFieldControls["modelattachment"] = modelAttachmentEditor;
            state.AdditionalFieldControls["modelattachmentbone"] = modelAttachmentBoneEditor;
            var modelAttachmentRow = new AttachmentEditor(
                modelAttachmentEditor,
                modelAttachmentBoneEditor);

            var modelAttachmentTimerValue = GetProtoActionDefaultSimpleValue(
                "modelattachmenttimer",
                currentValues.TryGetValue("modelattachmenttimer", out var currentTimer)
                    ? currentTimer
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modelattachmenttimer"));
            var attachmentProfile = ProtoActionMetadataCatalog.GetEditorProfile(actionType);
            var showTimer = !string.IsNullOrWhiteSpace(modelAttachmentTimerValue) ||
                            attachmentProfile.DefaultVisibleTags.Contains("modelattachmenttimer", StringComparer.OrdinalIgnoreCase) ||
                            state.ForcedVisibleFieldTags.Contains("modelattachmenttimer");
            if (showTimer)
            {
                var timerEditor = CreateAttachmentEditor("modelattachmenttimer", modelAttachmentTimerValue, 90);
                modelAttachmentRow.Children.Add(CreateLabeledFieldGroup("Timer (ms):", timerEditor));
                if (!_isReadOnly)
                {
                    var removeTimerButton = new Button
                    {
                        Classes = { "remove-button" },
                        Margin = new Thickness(2, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    removeTimerButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod()) return;
                        state.ForcedVisibleFieldTags.Remove("modelattachmenttimer");
                        state.AdditionalFieldControls.Remove("modelattachmenttimer");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "modelattachmenttimer", "");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    modelAttachmentRow.Children.Add(removeTimerButton);
                }
            }
            else if (!_isReadOnly)
            {
                var addTimerButton = new Button
                {
                    Content = "Timer",
                    Classes = { "add-component" },
                    Margin = new Thickness(8, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                addTimerButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod()) return;
                    state.ForcedVisibleFieldTags.Add("modelattachmenttimer");
                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                };
                modelAttachmentRow.Children.Add(addTimerButton);
            }

            if (IsAutoRangedModifyActionType(actionType) &&
                (!_isReadOnly || state.SelectedFlagTags.Contains("modelattachmentonself")))
            {
                var onSelfCheckBox = new CheckBox
                {
                    Content = "On self",
                    IsChecked = state.SelectedFlagTags.Contains("modelattachmentonself"),
                    IsEnabled = !_isReadOnly,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(10, 0, 12, 6)
                };
                state.CustomFlagControls["modelattachmentonself"] = onSelfCheckBox;
                RegisterProtoActionFlagSourceControl(state, onSelfCheckBox, "modelattachmentonself");
                if (!_isReadOnly)
                {
                    onSelfCheckBox.IsCheckedChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod()) return;
                        if (onSelfCheckBox.IsChecked == true)
                            state.SelectedFlagTags.Add("modelattachmentonself");
                        else
                            state.SelectedFlagTags.Remove("modelattachmentonself");
                        RenderProtoActionFlags(state);
                        MarkDirty();
                    };
                }
                modelAttachmentRow.Children.Add(onSelfCheckBox);
            }

            if (!_isReadOnly)
            {
                var removeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeButton.Click += async (_, _) => await RemoveOptionalModelAttachmentAsync();
                modelAttachmentRow.Children.Add(removeButton);
            }

            state.AdditionalFieldsContainer.Children.Add(modelAttachmentRow);
          }

        if (!_isReadOnly && SupportsOptionalModelAttachmentActionType(actionType) && !showOptionalModelAttachmentFields)
        {
            var addModelAttachmentButton = new Button
            {
                Content = "Add Model Attachment",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left,
                Margin = new Thickness(0, 4, 0, 2)
            };
            addModelAttachmentButton.Click += async (_, _) =>
            {
                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                  state.ForcedVisibleFieldTags.Add("modelattachment");
                  state.ForcedVisibleFieldTags.Add("modelattachmentbone");
                  state.CustomValues.Remove(OptionalModelAttachmentHiddenStateKey);

                  RefreshProtoActionMetadataPanels(state);
                  MarkDirty();
              };
            state.AdditionalFieldsContainer.Children.Add(addModelAttachmentButton);
        }

        if (IsAutoBoostActionType(actionType) && state.AutoBoostModifyProtoControl != null)
        {
            state.AdditionalFieldsContainer.Children.Remove(state.AutoBoostModifyProtoControl);
            state.AdditionalFieldsContainer.Children.Add(state.AutoBoostModifyProtoControl);
        }
    }

    private static void RefreshProtoActionDamageHeader(ProtoActionWidgetState state)
    {
        var header = state.DamageSectionContainer.Children
            .OfType<TextBlock>()
            .FirstOrDefault(control => string.Equals(control.Tag as string, DamageHeaderTag, StringComparison.Ordinal));
        if (header == null)
            return;

        var hasDamageArea = state.DamageExtrasContainer.Children
            .OfType<Control>()
            .Any(control => string.Equals(control.Tag as string, DamageAreaRowTag, StringComparison.Ordinal));
        header.IsVisible = state.DamageRows.Count > 0 || state.BonusRows.Count > 0 || hasDamageArea;
    }

    private static void InitializeDamageAreaDefaults(ProtoActionWidgetState state, bool requireAreaSortMode)
    {
        if (!state.CustomValues.ContainsKey(DamageAreaTargetsInitializedStateKey))
        {
            var currentTargets = ProtoXmlHandler.GetProtoActionSimpleFieldValue(state.Model, "damageflags");
            if (string.IsNullOrWhiteSpace(currentTargets))
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "damageflags", "Enemy");
            state.CustomValues[DamageAreaTargetsInitializedStateKey] = "1";
        }

        if (requireAreaSortMode &&
            string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(state.Model, "areasortmode")))
        {
            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "areasortmode", "Radial");
        }
    }

    private void RenderProtoActionDamageExtras(ProtoActionWidgetState state, Dictionary<string, string> currentValues)
    {
        state.DamageExtrasContainer.Children.Clear();
        RefreshProtoActionDamageHeader(state);

        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        var isAutoBoost = IsAutoBoostActionType(actionType);
        var isSelfOnlyAutoBoost = isAutoBoost &&
                                  IsAutoBoostSelfEnabled(state, effectiveAction) &&
                                  !IsAutoBoostAreaEnabled(state, effectiveAction);
        if (isSelfOnlyAutoBoost)
        {
            RefreshProtoActionDamageHeader(state);
            return;
        }
        var isJumpAttack = IsJumpAttackActionType(actionType);
        var isMaul = IsMaulActionType(actionType);
        var isTeleportAttack = IsTeleportAttackActionType(actionType);
        var isGore = IsGoreActionType(actionType);
        var isThrow = IsThrowActionType(actionType);
        var isConditionalShield = IsConditionalShieldActionType(actionType);
        var attackMode = IsAttackActionType(actionType) ? GetAttackMode(state) : "";
        var isSpecialAttackAreaMode = attackMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) ||
                                      attackMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase);
        var showsDefaultAttackDamageArea = isSpecialAttackAreaMode &&
            state.ForcedVisibleFieldTags.Contains("damagearea");
        foreach (var existingSpawnAssistNote in state.DamageSectionContainer.Children
                     .OfType<Control>()
                     .Where(control => string.Equals(control.Tag as string, "spawnassist.damage.note", StringComparison.Ordinal))
                     .ToList())
        {
            state.DamageSectionContainer.Children.Remove(existingSpawnAssistNote);
        }
        if (IsSpawnAssistActionType(actionType))
        {
            state.DamageSectionContainer.Children.Insert(0, new TextBlock
            {
                Tag = "spawnassist.damage.note",
                Text = "Only for display in the UI, actual damages are defined in the spawned assist unit AssistAttack",
                FontStyle = FontStyle.Italic,
                Opacity = 0.78,
                Margin = new Thickness(0, 0, 0, 4)
            });
        }
        var showOptionalDamageAreaFields = ShouldShowOptionalAbductDamageAreaFields(state, actionType, effectiveAction, currentValues);
        var hasDamageAreaData = OptionalAbductDamageAreaTags.Any(tag =>
            state.ForcedVisibleFieldTags.Contains(tag) ||
            (currentValues.TryGetValue(tag, out var currentValue) && !string.IsNullOrWhiteSpace(currentValue)) ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
        var showJumpAttackDamageAreaFields = (isJumpAttack || isMaul || isTeleportAttack || isGore || isThrow) && OptionalAbductDamageAreaTags.Any(tag =>
            state.ForcedVisibleFieldTags.Contains(tag) ||
            (currentValues.TryGetValue(tag, out var currentValue) && !string.IsNullOrWhiteSpace(currentValue)) ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
        var showDamageAreaFields = isConditionalShield ||
                                   showsDefaultAttackDamageArea ||
                                   showJumpAttackDamageAreaFields ||
                                   showOptionalDamageAreaFields ||
                                   hasDamageAreaData;
        if (!isAutoBoost && !isJumpAttack && !isMaul && !isTeleportAttack && !isGore && !isThrow &&
            !isConditionalShield && !SupportsOptionalAbductDamageAreaActionType(actionType) && !hasDamageAreaData)
            return;

        if (showDamageAreaFields)
        {
            Control CreateDamageAreaEditor(string tag, string valueOverride)
            {
                var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
                var editor = new TextBox
                {
                    Text = valueOverride,
                    IsEnabled = !_isReadOnly,
                    Width = 120
                };

                if (definition.EditorKind == ProtoActionFieldEditorKind.Number)
                    AttachProtoActionDecimalBehavior(editor);

                editor.TextChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                        MarkDirty();
                };

                state.AdditionalFieldControls[tag] = editor;
                return editor;
            }

            async Task RemoveOptionalDamageAreaAsync()
            {
                var inheritedDamageAreaTags = isSpecialAttackAreaMode
                    ? OptionalAbductDamageAreaTags.Append("areasortmode")
                    : OptionalAbductDamageAreaTags;
                if (await BlockInheritedProtoActionRemovalAsync(
                        state,
                        inheritedDamageAreaTags,
                        "Damage Area"))
                {
                    return;
                }

                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                var tagsToRemove = isSpecialAttackAreaMode
                    ? OptionalAbductDamageAreaTags.Append("areasortmode")
                    : OptionalAbductDamageAreaTags;
                foreach (var tag in tagsToRemove)
                {
                    state.ForcedVisibleFieldTags.Remove(tag);
                    state.AdditionalFieldControls.Remove(tag);
                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                }
                state.CustomValues.Remove(DamageAreaTargetsInitializedStateKey);
                MarkDirty();
                RefreshProtoActionMetadataPanels(state);
            }

            var damageAreaRow = new WrapPanel
            {
                Tag = DamageAreaRowTag,
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };
            if (!isConditionalShield)
            {
                var damageAreaValue = currentValues.TryGetValue("damagearea", out var currentDamageArea)
                    ? currentDamageArea
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "damagearea");
                damageAreaRow.Children.Add(new TextBlock
                {
                    Text = "Damage Area:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                var damageAreaEditor = CreateDamageAreaEditor("damagearea", damageAreaValue);
                damageAreaRow.Children.Add(damageAreaEditor);

                if (!_isReadOnly && !isSpecialAttackAreaMode)
                {
                    var removeButton = new Button
                    {
                        Classes = { "remove-button" },
                        Margin = new Thickness(8, 0, 0, 0),
                        HorizontalAlignment = HorizontalAlignment.Center,
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    removeButton.Click += async (_, _) => await RemoveOptionalDamageAreaAsync();
                    damageAreaRow.Children.Add(removeButton);
                }

            }

            var rawDamageFlagsValue = currentValues.TryGetValue("damageflags", out var currentDamageFlags)
                ? currentDamageFlags
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "damageflags");
            var damageFlagsStorage = new TextBox
            {
                Text = rawDamageFlagsValue,
                IsVisible = false
            };
            state.AdditionalFieldControls["damageflags"] = damageFlagsStorage;

            var selectedDamageFlags = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (!string.IsNullOrWhiteSpace(rawDamageFlagsValue))
            {
                foreach (var value in rawDamageFlagsValue.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
                    selectedDamageFlags.Add(value);
            }
            var conditionalShieldHealEnabled = false;
            if (isConditionalShield)
            {
                selectedDamageFlags.Clear();
                conditionalShieldHealEnabled = state.CustomValues.TryGetValue("conditionalshield.heal", out var healValue)
                    ? healValue == "1"
                    : !IsConditionalShieldDamageEnabled(state, effectiveAction) ||
                      rawDamageFlagsValue.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                          .Contains("Ally", StringComparer.OrdinalIgnoreCase);
                if (conditionalShieldHealEnabled)
                    selectedDamageFlags.Add("Ally");
                if (IsConditionalShieldDamageEnabled(state, effectiveAction))
                {
                    selectedDamageFlags.Add("Enemy");
                    if (rawDamageFlagsValue.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                        .Contains("Nature", StringComparer.OrdinalIgnoreCase))
                    {
                        selectedDamageFlags.Add("Nature");
                    }
                }
                damageFlagsStorage.Text = string.Join("|", AbductDamageFlagValues.Where(selectedDamageFlags.Contains));
            }

            damageAreaRow.Children.Add(new TextBlock
            {
                Text = "Targets:",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(14, 4, 8, 4)
            });

            void SyncDamageFlagsStorage()
            {
                damageFlagsStorage.Text = string.Join("|", AbductDamageFlagValues.Where(selectedDamageFlags.Contains));
            }

            var availableDamageFlags = isConditionalShield
                ? (conditionalShieldHealEnabled ? new[] { "Ally" } : new[] { "Enemy", "Nature" })
                : AbductDamageFlagValues;
            foreach (var damageFlag in availableDamageFlags)
            {
                var damageFlagCheckBox = new CheckBox
                {
                    Content = damageFlag,
                    IsChecked = selectedDamageFlags.Contains(damageFlag),
                    IsEnabled = !_isReadOnly && (!isConditionalShield || damageFlag.Equals("Nature", StringComparison.OrdinalIgnoreCase)),
                    Margin = new Thickness(0, 0, 10, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                damageFlagCheckBox.IsCheckedChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    if (damageFlagCheckBox.IsChecked == true)
                        selectedDamageFlags.Add(damageFlag);
                    else
                        selectedDamageFlags.Remove(damageFlag);

                    SyncDamageFlagsStorage();
                    MarkDirty();
                };
                damageAreaRow.Children.Add(damageFlagCheckBox);
            }

            if (!isConditionalShield)
            {
                var currentAreaSortMode = currentValues.TryGetValue("areasortmode", out var editedAreaSortMode)
                    ? editedAreaSortMode
                    : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "areasortmode");
                var showAreaSortMode = isSpecialAttackAreaMode ||
                                       state.ForcedVisibleFieldTags.Contains("areasortmode") ||
                                       !string.IsNullOrWhiteSpace(currentAreaSortMode);

                if (showAreaSortMode)
                {
                    if (isSpecialAttackAreaMode && string.IsNullOrWhiteSpace(currentAreaSortMode))
                        currentAreaSortMode = "Radial";

                    damageAreaRow.Children.Add(new TextBlock
                    {
                        Text = "Area Sort:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 8, 4)
                    });

                    var areaSortOptions = new[] { "Directional", "Radial" };
                    var areaSortModeCombo = new ComboBox
                    {
                        ItemsSource = areaSortOptions,
                        SelectedItem = areaSortOptions.FirstOrDefault(value =>
                            value.Equals(currentAreaSortMode, StringComparison.OrdinalIgnoreCase)),
                        IsEnabled = !_isReadOnly,
                        Width = 110
                    };
                    areaSortModeCombo.SelectionChanged += async (_, _) =>
                    {
                        if (_isPopulating || !await CheckStartLocalMod())
                            return;

                        var selectedAreaSortMode = areaSortModeCombo.SelectedItem as string ?? "";
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(
                            state.Model,
                            "areasortmode",
                            selectedAreaSortMode);
                        state.ForcedVisibleFieldTags.Add("areasortmode");
                        MarkDirty();
                    };
                    state.AdditionalFieldControls["areasortmode"] = areaSortModeCombo;
                    damageAreaRow.Children.Add(areaSortModeCombo);

                    if (!_isReadOnly && !isSpecialAttackAreaMode)
                    {
                        var removeAreaSortButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(8, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        removeAreaSortButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            state.ForcedVisibleFieldTags.Remove("areasortmode");
                            state.AdditionalFieldControls.Remove("areasortmode");
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "areasortmode", "");
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        damageAreaRow.Children.Add(removeAreaSortButton);
                    }
                }
                else if (!_isReadOnly)
                {
                    var addAreaSortButton = new Button
                    {
                        Content = "Area Sort",
                        Classes = { "add-component" },
                        Margin = new Thickness(14, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    addAreaSortButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.ForcedVisibleFieldTags.Add("areasortmode");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, "areasortmode", "Radial");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    damageAreaRow.Children.Add(addAreaSortButton);
                }
            }

            state.DamageExtrasContainer.Children.Add(damageAreaRow);
        }

        var canAddAutoBoostDamageArea = isAutoBoost && IsAutoBoostAreaEnabled(state, effectiveAction);
        if (!_isReadOnly && !isConditionalShield &&
            (!isAutoBoost || canAddAutoBoostDamageArea) &&
            !showDamageAreaFields && !showOptionalDamageAreaFields && !showJumpAttackDamageAreaFields)
        {
            var addDamageAreaButton = new Button
            {
                Content = "Add Damage Area",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left,
                Margin = new Thickness(0, 4, 0, 2)
            };
            addDamageAreaButton.Click += async (_, _) =>
            {
                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                foreach (var tag in OptionalAbductDamageAreaTags)
                    state.ForcedVisibleFieldTags.Add(tag);
                InitializeDamageAreaDefaults(state, requireAreaSortMode: false);

                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            state.DamageExtrasContainer.Children.Add(addDamageAreaButton);
        }

        RefreshProtoActionDamageHeader(state);
    }

    private static XElement? GetProtoActionAdditionalElement(ProtoAction action, string tag)
        => action.AdditionalElements.FirstOrDefault(x => x.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));

    private static string GetExplicitProtoActionLaunchPointValue(ProtoAction action)
    {
        var simpleValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(action, "launchpoint");
        if (!string.IsNullOrWhiteSpace(simpleValue))
            return simpleValue;

        var actionAttributeValue = action.SourceElement?
            .Attributes()
            .FirstOrDefault(attribute => attribute.Name.LocalName.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
            ?.Value?.Trim();
        if (!string.IsNullOrWhiteSpace(actionAttributeValue))
            return actionAttributeValue;

        return GetProtoActionAdditionalElement(action, "projectile")?
            .Attributes()
            .FirstOrDefault(attribute => attribute.Name.LocalName.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
            ?.Value?.Trim() ?? "";
    }

    private static string GetProtoActionLaunchPointValue(ProtoAction action)
    {
        var explicitValue = GetExplicitProtoActionLaunchPointValue(action);
        if (!string.IsNullOrWhiteSpace(explicitValue))
            return explicitValue;

        var source = action.SourceElement;
        if (source == null)
            return "";

        // Tactics use more than one XML form for launchpoint, so preserve the value
        // regardless of whether it is a child tag or an action/projectile attribute.
        var childValue = source.DescendantsAndSelf()
            .FirstOrDefault(element => element.Name.LocalName.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
            ?.Value?.Trim();
        if (!string.IsNullOrWhiteSpace(childValue))
            return childValue;

        return source.DescendantsAndSelf()
            .Attributes()
            .FirstOrDefault(attribute => attribute.Name.LocalName.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
            ?.Value?.Trim() ?? "";
    }

    private static bool UsesProtoActionLaunchPointAttribute(ProtoAction? action)
        => action?.SourceElement?.Attributes()
            .Any(attribute => attribute.Name.LocalName.Equals("launchpoint", StringComparison.OrdinalIgnoreCase)) == true;

    private static bool UsesProjectileLaunchPointAttribute(ProtoAction? action)
        => action != null && GetProtoActionAdditionalElement(action, "projectile")?
            .Attributes()
            .Any(attribute => attribute.Name.LocalName.Equals("launchpoint", StringComparison.OrdinalIgnoreCase)) == true;

    private static string GetProtoActionNestedChildValue(ProtoAction action, string parentTag, string childTag)
        => GetProtoActionAdditionalElement(action, parentTag)?
            .Elements()
            .FirstOrDefault(x => x.Name.LocalName.Equals(childTag, StringComparison.OrdinalIgnoreCase))
            ?.Value
            ?.Trim()
           ?? "";

    private static List<string> GetProtoActionNestedUnitTypeValues(ProtoAction action, string parentTag)
        => GetProtoActionAdditionalElement(action, parentTag)?
            .Elements()
            .Where(x => x.Name.LocalName.Equals("unittype", StringComparison.OrdinalIgnoreCase))
            .Select(x => x.Value?.Trim() ?? "")
            .Where(x => !string.IsNullOrWhiteSpace(x))
            .ToList()
           ?? [];

    private static void SaveProtoActionNestedUnitTypeListElement(ProtoAction action, string parentTag, IEnumerable<string> values)
    {
        action.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals(parentTag, StringComparison.OrdinalIgnoreCase));

        var validValues = values
            .Where(x => !string.IsNullOrWhiteSpace(x))
            .Select(x => x.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();

        if (validValues.Count == 0)
            return;

        var parent = new XElement(parentTag,
            validValues.Select(x => new XElement("unittype", x)));
        action.AdditionalElements.Add(parent);
    }

    private static void SaveProtoActionStackControlElement(
        ProtoAction action,
        string stackMax,
        string stackAddAction,
        string stackSubAction)
    {
        action.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals("stackcontrol", StringComparison.OrdinalIgnoreCase));

        if (string.IsNullOrWhiteSpace(stackMax) &&
            string.IsNullOrWhiteSpace(stackAddAction) &&
            string.IsNullOrWhiteSpace(stackSubAction))
        {
            return;
        }

        var stackControl = new XElement("stackcontrol");
        if (!string.IsNullOrWhiteSpace(stackMax))
            stackControl.Add(new XElement("stackmax", stackMax.Trim()));
        if (!string.IsNullOrWhiteSpace(stackAddAction))
            stackControl.Add(new XElement("stackaddaction", stackAddAction.Trim()));
        if (!string.IsNullOrWhiteSpace(stackSubAction))
            stackControl.Add(new XElement("stacksubaction", stackSubAction.Trim()));

        action.AdditionalElements.Add(stackControl);
    }

    private static void SaveProtoActionNestedChildElement(
        ProtoAction action,
        string parentTag,
        string childTag,
        string value)
    {
        action.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals(parentTag, StringComparison.OrdinalIgnoreCase));

        var trimmedValue = value?.Trim() ?? "";
        if (string.IsNullOrWhiteSpace(trimmedValue))
            return;

        action.AdditionalElements.Add(new XElement(parentTag, new XElement(childTag, trimmedValue)));
    }

    private static bool StackControlValuesEqual(
        string leftMax,
        string leftAddAction,
        string leftSubAction,
        string rightMax,
        string rightAddAction,
        string rightSubAction)
        => string.Equals(leftMax?.Trim() ?? "", rightMax?.Trim() ?? "", StringComparison.Ordinal) &&
           string.Equals(leftAddAction?.Trim() ?? "", rightAddAction?.Trim() ?? "", StringComparison.Ordinal) &&
           string.Equals(leftSubAction?.Trim() ?? "", rightSubAction?.Trim() ?? "", StringComparison.Ordinal);

    private void RenderProtoActionStackControlFields(ProtoActionWidgetState state, Dictionary<string, string> currentValues)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        var hasStackControlElement = GetProtoActionAdditionalElement(effectiveAction, "stackcontrol") != null;
        var isAdditionalStackControl = !IsStackControlActionType(actionType);
        if (!IsStackControlActionType(actionType) &&
            !state.ForcedVisibleFieldTags.Contains("stackcontrol") &&
            !hasStackControlElement)
            return;

        string GetCurrentOrEffectiveValue(string tag)
            => currentValues.TryGetValue(tag, out var currentValue)
                ? currentValue
                : GetProtoActionNestedChildValue(effectiveAction, "stackcontrol", tag);

        var availableActionNames = _protoActionWidgets
            .Select(other => other.NameAcb.Text?.Trim() ?? "")
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();

        TextBox CreateStackMaxEditor(string value)
        {
            var editor = new TextBox
            {
                Text = value,
                Width = 100,
                IsEnabled = !_isReadOnly
            };
            AttachProtoActionDecimalBehavior(editor);
            editor.TextChanged += async (_, _) =>
            {
                if (_isPopulating)
                    return;
                if (await CheckStartLocalMod())
                    MarkDirty();
            };
            state.AdditionalFieldControls["stackmax"] = editor;
            return editor;
        }

        ComboBox CreateActionSelector(string tag, string value)
        {
            var editor = new ComboBox
            {
                ItemsSource = availableActionNames,
                SelectedItem = availableActionNames.FirstOrDefault(name =>
                    name.Equals(value, StringComparison.OrdinalIgnoreCase)),
                Width = 180,
                IsEnabled = !_isReadOnly
            };
            editor.SelectionChanged += async (_, _) =>
            {
                if (_isPopulating)
                    return;
                if (await CheckStartLocalMod())
                    MarkDirty();
            };
            state.AdditionalFieldControls[tag] = editor;
            return editor;
        }

        var stackControlHost = new StackPanel
        {
            Tag = "protoaction.additional.stackcontrol",
            Spacing = 4
        };
        var headerRow = new WrapPanel
        {
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 6, 0, 2)
        };
        headerRow.Children.Add(new TextBlock
        {
            Text = "Stack Control",
            FontWeight = FontWeight.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        });
        if (isAdditionalStackControl && !_isReadOnly)
        {
            var removeSectionButton = new Button
            {
                Classes = { "remove-button" },
                Margin = new Thickness(8, 0, 0, 0)
            };
            removeSectionButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;
                state.ForcedVisibleFieldTags.Remove("stackcontrol");
                foreach (var childTag in ManagedStackControlChildTags)
                    state.AdditionalFieldControls.Remove(childTag);
                RemoveProtoActionAdditionalElement(state.Model, "stackcontrol");
                MarkDirty();
                RefreshProtoActionMetadataPanels(state);
            };
            headerRow.Children.Add(removeSectionButton);
        }
        stackControlHost.Children.Add(headerRow);

        var stackMaxRow = new WrapPanel
        {
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 2, 0, 2)
        };
        stackMaxRow.Children.Add(new TextBlock
        {
            Text = "Stack Max:",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 4, 8, 4)
        });
        stackMaxRow.Children.Add(CreateStackMaxEditor(GetCurrentOrEffectiveValue("stackmax")));
        stackControlHost.Children.Add(stackMaxRow);

        var actionSelectorsRow = new WrapPanel
        {
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 2, 0, 2),
            VerticalAlignment = VerticalAlignment.Center
        };
        actionSelectorsRow.Children.Add(new TextBlock
        {
            Text = "Add Action:",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 4, 8, 4)
        });
        actionSelectorsRow.Children.Add(CreateActionSelector(
            "stackaddaction",
            GetCurrentOrEffectiveValue("stackaddaction")));
        actionSelectorsRow.Children.Add(new TextBlock
        {
            Text = "Sub Action:",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(12, 4, 8, 4)
        });
        actionSelectorsRow.Children.Add(CreateActionSelector(
            "stacksubaction",
            GetCurrentOrEffectiveValue("stacksubaction")));
        stackControlHost.Children.Add(actionSelectorsRow);
        state.AdditionalFieldsContainer.Children.Add(stackControlHost);
    }

    private void RenderProtoActionEmpowerSections(
        ProtoActionWidgetState state,
        IReadOnlyDictionary<string, XElement?>? currentSections = null)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        state.EmpowerTargetStates.Clear();
        var currentModifyType = state.AdditionalFieldControls.TryGetValue("modifytype", out var modifyTypeControl)
            ? ProtoConstants.GetModifyTypeValue(ReadTextLikeControlValue(modifyTypeControl))
            : ProtoConstants.GetModifyTypeValue(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "modifytype"));
        var usesNativeEmpowerLayout = IsEmpowerActionType(actionType) ||
            (IsAutoRangedModifyActionType(actionType) &&
             currentModifyType.Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase));
        var supportsEmpowerSections = usesNativeEmpowerLayout ||
            EmpowerSectionTags.Any(tag =>
                state.ForcedVisibleFieldTags.Contains(tag) ||
                currentSections?.ContainsKey(tag) == true ||
                GetProtoActionAdditionalElement(effectiveAction, tag) != null);
        if (!supportsEmpowerSections)
            return;

        var targetSuggestions = GetKnownUnitTypeNames();
        var animationSuggestions = GetAvailableProtoActionAnimationNames();
        var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
            .Select(ProtoConstants.GetModifyTypeDisplayName)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();

        string GetSectionLabel(string sectionTag)
            => sectionTag.Equals("empowerdata", StringComparison.OrdinalIgnoreCase) ? "Empower Data"
             : sectionTag.Equals("enemyempowerdata", StringComparison.OrdinalIgnoreCase) ? "Enemy Empower Data"
             : "Nature Empower Data";

        async Task<bool> HandleEditorChangedAsync()
        {
            if (_isPopulating)
                return false;

            var proceed = await CheckStartLocalMod();
            if (proceed)
                MarkDirty();
            return proceed;
        }

        void WireTextBox(TextBox textBox, bool numeric = false)
        {
            if (numeric)
                AttachProtoActionDecimalBehavior(textBox);

            textBox.TextChanged += async (_, _) => await HandleEditorChangedAsync();
        }

        void WireAutoCompleteBox(AutoCompleteBox autoCompleteBox, IEnumerable<string>? suggestions = null)
        {
            if (suggestions != null)
                autoCompleteBox.ItemsSource = suggestions;
            EnableDropdownAutoComplete(autoCompleteBox);
            autoCompleteBox.TextChanged += async (_, _) => await HandleEditorChangedAsync();
        }

        void WireCheckBox(CheckBox checkBox)
        {
            checkBox.IsCheckedChanged += async (_, _) => await HandleEditorChangedAsync();
        }

        void RenderEmpowerTargetSection(string sectionTag)
        {
            var sectionStateList = new List<ProtoActionEmpowerTargetState>();
            state.EmpowerTargetStates[sectionTag] = sectionStateList;
            var existingSection = currentSections?.TryGetValue(sectionTag, out var currentSection) == true
                ? currentSection
                : GetProtoActionAdditionalElement(effectiveAction, sectionTag);
            var sectionHasTargets = existingSection?.Elements().Any() == true;

            var sectionHost = new StackPanel
            {
                Tag = $"protoaction.additional.{sectionTag}",
                Spacing = 6,
                Margin = new Thickness(0, 8, 0, 2)
            };
            var sectionHeader = new TextBlock
            {
                Text = GetSectionLabel(sectionTag),
                FontWeight = FontWeight.Bold,
                IsVisible = sectionHasTargets
            };
            sectionHost.Children.Add(sectionHeader);

            var targetsContainer = new StackPanel { Spacing = 8, IsVisible = sectionHasTargets };
            sectionHost.Children.Add(targetsContainer);

            void AddTargetCard(XElement? initialTarget = null)
            {
                var card = new Border
                {
                    BorderBrush = Brush.Parse("#4C4031"),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(6),
                    Padding = new Thickness(8),
                    Background = Brush.Parse("#191C1A")
                };
                targetsContainer.Children.Add(card);

                var cardStack = new StackPanel { Spacing = 6 };
                var cardRoot = new Grid();
                cardRoot.Children.Add(cardStack);
                card.Child = cardRoot;

                var headerGrid = new Grid
                {
                    ColumnDefinitions = !_isReadOnly
                        ? new ColumnDefinitions("Auto, 200, Auto")
                        : new ColumnDefinitions("Auto, 200, Auto"),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                headerGrid.Children.Add(new TextBlock
                {
                    Text = "Target:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                });

                var targetAcb = new AutoCompleteBox
                {
                    Text = initialTarget?.Name.LocalName ?? "",
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly,
                    Width = 200
                };
                EditorTextFieldStyle.ConfigureSelector(targetAcb);
                targetAcb.Width = 200;
                WireAutoCompleteBox(targetAcb, targetSuggestions);
                Grid.SetColumn(targetAcb, 1);
                headerGrid.Children.Add(targetAcb);

                cardStack.Children.Add(headerGrid);

                if (!_isReadOnly)
                {
                    var removeButton = new Button
                    {
                        Content = "Remove",
                        Background = Brush.Parse("#7A1F1C"),
            BorderBrush = Brush.Parse("#B55640"),
                        HorizontalAlignment = HorizontalAlignment.Right,
                        VerticalAlignment = VerticalAlignment.Top
                    };
                    removeButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        targetsContainer.Children.Remove(card);
                        sectionStateList.RemoveAll(x => ReferenceEquals(x.Container, card));
                        if (targetsContainer.Children.Count == 0)
                        {
                            sectionHeader.IsVisible = false;
                            targetsContainer.IsVisible = false;
                            state.ForcedVisibleFieldTags.Remove(sectionTag);
                        }
                        MarkDirty();
                    };
                    cardRoot.Children.Add(removeButton);
                }

                var activeCb = new CheckBox
                {
                    Content = "Active",
                    IsChecked = initialTarget == null ||
                                !string.Equals(initialTarget.Element("active")?.Value?.Trim(), "0", StringComparison.OrdinalIgnoreCase),
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(8, 0, 0, 0)
                };
                WireCheckBox(activeCb);
                Grid.SetColumn(activeCb, 2);
                headerGrid.Children.Add(activeCb);

                var animAcb = new AutoCompleteBox
                {
                    Text = initialTarget?.Element("anim")?.Value?.Trim() ?? "",
                    FilterMode = AutoCompleteFilterMode.Contains,
                    IsEnabled = !_isReadOnly
                };
                EditorTextFieldStyle.ConfigureSelector(animAcb);
                ApplyProtoActionFieldWidth(animAcb, "anim");
                WireAutoCompleteBox(animAcb, animationSuggestions);

                var empowerAreaTb = new TextBox
                {
                    Text = initialTarget?.Element("empowerarea")?.Value?.Trim() ?? "",
                    IsEnabled = !_isReadOnly
                };
                WireTextBox(empowerAreaTb, numeric: true);

                var modelAttachmentValue = initialTarget?.Element("modelattachment")?.Value?.Trim() ?? "";
                var modelAttachmentBoneValue = initialTarget?.Element("modelattachmentbone")?.Value?.Trim() ?? "";
                var sharedAttachmentEditors = CreateProtoActionModelAttachmentEditors(
                    modelAttachmentValue,
                    modelAttachmentBoneValue);
                var modelAttachmentTb = sharedAttachmentEditors.Attachment;
                modelAttachmentTb.Margin = new Thickness(0);
                var modelAttachmentBoneAcb = sharedAttachmentEditors.Bone;

                var targetIndex = sectionStateList.Count;
                var animationVisibilityKey = $"{sectionTag}:{targetIndex}:empower-specific-animation";
                var empowerAuraVisibilityKey = $"{sectionTag}:{targetIndex}:empower-aura";

                var targetState = new ProtoActionEmpowerTargetState
                {
                    SectionTag = sectionTag,
                    Container = card,
                    TargetAcb = targetAcb,
                    ActiveCb = activeCb,
                    AnimAcb = animAcb,
                    EmpowerAreaTb = empowerAreaTb,
                    ModelAttachmentEditor = modelAttachmentTb,
                    ModelAttachmentBoneAcb = modelAttachmentBoneAcb,
                    IsAnimVisible = !string.IsNullOrWhiteSpace(animAcb.Text) || state.ForcedVisibleFieldTags.Contains(animationVisibilityKey),
                    IsEmpowerAreaVisible = !string.IsNullOrWhiteSpace(empowerAreaTb.Text) || state.ForcedVisibleFieldTags.Contains(empowerAuraVisibilityKey),
                    IsModelAttachmentVisible = !string.IsNullOrWhiteSpace(modelAttachmentValue) ||
                                               !string.IsNullOrWhiteSpace(modelAttachmentBoneValue),
                };
                sectionStateList.Add(targetState);

                var forbidHeader = new TextBlock
                {
                    Text = "Forbid Unit Types",
                    FontWeight = FontWeight.SemiBold,
                    Margin = new Thickness(0, 4, 0, 2),
                    IsVisible = initialTarget?.Elements("forbidunittype").Any() == true
                };
                cardStack.Children.Add(forbidHeader);

                var forbidContainer = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    IsVisible = true
                };
                cardStack.Children.Add(forbidContainer);

                Button? addForbidButton = null;

                void AddForbidRow(string value = "")
                {
                    var row = new Grid
                    {
                        ColumnDefinitions = !_isReadOnly
                            ? new ColumnDefinitions("200, 32")
                            : new ColumnDefinitions("200"),
                        Width = !_isReadOnly ? 232 : 200,
                        Margin = new Thickness(0, 0, 8, 4),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    var acb = new AutoCompleteBox
                    {
                        Text = value,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        IsEnabled = !_isReadOnly,
                        Width = 200
                    };
                    EditorTextFieldStyle.ConfigureSelector(acb);
                    acb.Width = 200;
                    WireAutoCompleteBox(acb, targetSuggestions);
                    row.Children.Add(acb);
                    targetState.ForbidTypeAcbs.Add(acb);

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" } };
                        removeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            forbidContainer.Children.Remove(row);
                            targetState.ForbidTypeAcbs.Remove(acb);
                            if (targetState.ForbidTypeAcbs.Count == 0)
                                forbidHeader.IsVisible = false;
                            MarkDirty();
                        };
                        Grid.SetColumn(removeButton, 1);
                        row.Children.Add(removeButton);
                    }

                    var buttonIndex = addForbidButton == null
                        ? -1
                        : forbidContainer.Children.IndexOf(addForbidButton);
                    if (buttonIndex >= 0)
                        forbidContainer.Children.Insert(buttonIndex, row);
                    else
                        forbidContainer.Children.Add(row);
                }

                foreach (var forbidValue in initialTarget?.Elements("forbidunittype").Select(x => x.Value?.Trim() ?? "").Where(x => !string.IsNullOrWhiteSpace(x)) ?? [])
                    AddForbidRow(forbidValue);

                if (!_isReadOnly)
                {
                    addForbidButton = new Button
                    {
                        Content = "Add Forbid Unit Type",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addForbidButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        forbidHeader.IsVisible = true;
                        forbidContainer.IsVisible = true;
                        AddForbidRow();
                        MarkDirty();
                    };
                    forbidContainer.Children.Add(addForbidButton);
                }

                var attachmentHost = new StackPanel
                {
                    Spacing = 2,
                    Margin = new Thickness(8, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };

                void RenderModelAttachment()
                {
                    attachmentHost.Children.Clear();
                    if (!targetState.IsModelAttachmentVisible)
                    {
                        if (_isReadOnly)
                            return;

                        var addAttachment = new Button
                        {
                            Content = "Add Model Attachment",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addAttachment.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            targetState.IsModelAttachmentVisible = true;
                            RenderModelAttachment();
                            MarkDirty();
                        };
                        attachmentHost.Children.Add(addAttachment);
                        return;
                    }

                    var attachmentRow = new AttachmentEditor(
                        targetState.ModelAttachmentEditor,
                        targetState.ModelAttachmentBoneAcb,
                        rowMargin: new Thickness(0),
                        attachmentGroupMargin: new Thickness(0, 0, 12, 0),
                        boneGroupMargin: new Thickness(0));
                    if (!_isReadOnly)
                    {
                        var removeAttachment = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        removeAttachment.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            var emptyAttachmentEditors = CreateProtoActionModelAttachmentEditors("", "");
                            emptyAttachmentEditors.Attachment.Margin = new Thickness(0);
                            targetState.ModelAttachmentEditor = emptyAttachmentEditors.Attachment;
                            targetState.ModelAttachmentBoneAcb = emptyAttachmentEditors.Bone;
                            targetState.IsModelAttachmentVisible = false;
                            RenderModelAttachment();
                            MarkDirty();
                        };
                        attachmentRow.Children.Add(removeAttachment);
                    }
                    attachmentHost.Children.Add(attachmentRow);
                }
                RenderModelAttachment();

                async Task<bool> AddSpecificAnimation()
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return false;

                    targetState.IsAnimVisible = true;
                    state.ForcedVisibleFieldTags.Add(animationVisibilityKey);
                    MarkDirty();
                    return true;
                }

                async Task<bool> RemoveSpecificAnimation()
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return false;

                    animAcb.Text = "";
                    targetState.IsAnimVisible = false;
                    state.ForcedVisibleFieldTags.Remove(animationVisibilityKey);
                    MarkDirty();
                    return true;
                }

                async Task<bool> AddEmpowerAura()
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return false;

                    targetState.IsEmpowerAreaVisible = true;
                    state.ForcedVisibleFieldTags.Add(empowerAuraVisibilityKey);
                    MarkDirty();
                    return true;
                }

                async Task<bool> RemoveEmpowerAura()
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return false;

                    empowerAreaTb.Text = "";
                    targetState.IsEmpowerAreaVisible = false;
                    state.ForcedVisibleFieldTags.Remove(empowerAuraVisibilityKey);
                    MarkDirty();
                    return true;
                }

                var empowerAuraCell = new OptionalFieldHost(
                    "Empower Area:",
                    empowerAreaTb,
                    "Empower Area",
                    targetState.IsEmpowerAreaVisible,
                    _isReadOnly,
                    AddEmpowerAura,
                    RemoveEmpowerAura);
                var specificAnimationCell = new OptionalFieldHost(
                    "Specific Animation:",
                    animAcb,
                    "Specific Animation",
                    targetState.IsAnimVisible,
                    _isReadOnly,
                    AddSpecificAnimation,
                    RemoveSpecificAnimation);

                var empowerAreaRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                empowerAreaRow.Children.Add(empowerAuraCell);
                cardStack.Children.Add(empowerAreaRow);

                var visualOptionsRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left,
                    VerticalAlignment = VerticalAlignment.Center
                };
                visualOptionsRow.Children.Add(specificAnimationCell);
                visualOptionsRow.Children.Add(attachmentHost);
                cardStack.Children.Add(visualOptionsRow);

                var ratesHeader = new TextBlock
                {
                    Text = "Empower Rates",
                    FontWeight = FontWeight.SemiBold,
                    Margin = new Thickness(0, 4, 0, 2),
                    IsVisible = initialTarget?.Elements("empowerrate").Any() == true
                };
                cardStack.Children.Add(ratesHeader);

                var ratesContainer = new StackPanel { Spacing = 4, IsVisible = ratesHeader.IsVisible };
                cardStack.Children.Add(ratesContainer);

                void AddRateRow(string modifyType = "", string value = "", string damageType = "")
                {
                    var modifyTypeAcb = new AutoCompleteBox
                    {
                        Text = ProtoConstants.GetModifyTypeDisplayName(modifyType),
                        FilterMode = AutoCompleteFilterMode.Contains,
                        IsEnabled = !_isReadOnly,
                        Width = 180
                    };
                    EditorTextFieldStyle.ConfigureSelector(modifyTypeAcb);
                    modifyTypeAcb.Width = 180;
                    WireAutoCompleteBox(modifyTypeAcb, modifyTypeSuggestions);

                    var valueTb = new TextBox
                    {
                        Text = value,
                        IsEnabled = !_isReadOnly,
                        Width = 100
                    };
                    WireTextBox(valueTb, numeric: true);

                    var damageTypeCb = new ComboBox
                    {
                        IsEnabled = !_isReadOnly,
                        Width = 120
                    };
                    RefreshProtoActionDamageTypeCombo(damageTypeCb, modifyTypeAcb.Text, damageType);
                    damageTypeCb.SelectionChanged += async (_, _) => await HandleEditorChangedAsync();

                    var row = new ModifierEditor(
                        modifyTypeAcb,
                        valueTb,
                        damageTypeCb,
                        showRemoveButton: !_isReadOnly);

                    void RefreshDamageTypeVisibility()
                    {
                        var visible = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "") is "DamageSpecific" or "ArmorSpecific";
                        row.SetDamageTypeVisible(visible);
                        if (!visible)
                            damageTypeCb.SelectedItem = null;
                        else
                            RefreshProtoActionDamageTypeCombo(
                                damageTypeCb,
                                modifyTypeAcb.Text,
                                damageTypeCb.SelectedItem?.ToString() ?? damageType);
                    }

                    modifyTypeAcb.TextChanged += (_, _) => RefreshDamageTypeVisibility();
                    RefreshDamageTypeVisibility();

                    var rowState = new ProtoActionEmpowerRateRowState
                    {
                        RowPanel = row,
                        ModifyTypeAcb = modifyTypeAcb,
                        ValueTb = valueTb,
                        DamageTypeCb = damageTypeCb,
                        DamageTypeLabel = row.DamageTypeLabel!
                    };
                    targetState.RateRows.Add(rowState);

                    if (row.RemoveButton != null)
                    {
                        row.RemoveButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            ratesContainer.Children.Remove(row);
                            targetState.RateRows.Remove(rowState);
                            if (targetState.RateRows.Count == 0)
                            {
                                ratesHeader.IsVisible = false;
                                ratesContainer.IsVisible = false;
                            }
                            MarkDirty();
                        };
                    }

                    ratesContainer.Children.Add(row);
                }

                foreach (var rate in initialTarget?.Elements("empowerrate") ?? [])
                {
                    AddRateRow(
                        (string?)rate.Attribute("modifytype") ?? (string?)rate.Attribute("modifyType") ?? "",
                        rate.Value?.Trim() ?? "",
                        (string?)rate.Attribute("damagetype") ?? (string?)rate.Attribute("damageType") ?? "");
                }

                if (!_isReadOnly && targetState.RateRows.Count == 0)
                {
                    ratesHeader.IsVisible = true;
                    ratesContainer.IsVisible = true;
                    AddRateRow();
                }

                if (!_isReadOnly)
                {
                    var addRateButton = new Button
                    {
                        Content = "Add Empower Rate",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addRateButton.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        ratesHeader.IsVisible = true;
                        ratesContainer.IsVisible = true;
                        AddRateRow();
                        MarkDirty();
                    };
                    cardStack.Children.Add(addRateButton);
                }
            }

            foreach (var initialTarget in existingSection?.Elements() ?? [])
                AddTargetCard(initialTarget);

            if (!_isReadOnly &&
                existingSection == null &&
                state.ForcedVisibleFieldTags.Contains(sectionTag))
            {
                sectionHeader.IsVisible = true;
                targetsContainer.IsVisible = true;
                AddTargetCard();
            }

            if (!_isReadOnly)
            {
                var addTargetButton = new Button
                {
                    Content = $"Add {GetSectionLabel(sectionTag)} Target",
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                addTargetButton.Click += async (_, _) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    state.ForcedVisibleFieldTags.Add(sectionTag);
                    sectionHeader.IsVisible = true;
                    targetsContainer.IsVisible = true;
                    AddTargetCard();
                    MarkDirty();
                };
                sectionHost.Children.Add(addTargetButton);
            }

            state.AdditionalFieldsContainer.Children.Add(sectionHost);
        }

        foreach (var sectionTag in EmpowerSectionTags)
        {
            if (usesNativeEmpowerLayout ||
                state.ForcedVisibleFieldTags.Contains(sectionTag) ||
                currentSections?.ContainsKey(sectionTag) == true ||
                GetProtoActionAdditionalElement(effectiveAction, sectionTag) != null)
            {
                RenderEmpowerTargetSection(sectionTag);
            }
        }
    }

    private void RenderProtoActionChargedFields(
        ProtoActionWidgetState state,
        IReadOnlyList<XElement>? currentElements = null)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        state.ChargedRows.Clear();
        if (!IsBolsterActionType(actionType))
            return;

        var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
            .Select(ProtoConstants.GetModifyTypeDisplayName)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();

        var isAdditionalChargedSection = !IsBolsterActionType(actionType) && !IsRampageActionType(actionType);
        var chargedHeaderText = new TextBlock
        {
            Text = "Charged Modifiers",
            FontWeight = FontWeight.SemiBold,
            Margin = new Thickness(0, 6, 0, 2)
        };
        if (isAdditionalChargedSection && !_isReadOnly)
        {
            var chargedHeader = new WrapPanel
            {
                Tag = "protoaction.charged",
                Orientation = Orientation.Horizontal
            };
            chargedHeader.Children.Add(chargedHeaderText);
            var removeChargedButton = new Button
            {
                Classes = { "remove-button" },
                Margin = new Thickness(2, 0, 0, 0),
                VerticalAlignment = VerticalAlignment.Center
            };
            removeChargedButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;
                state.ForcedVisibleFieldTags.Remove("charged");
                state.ChargedRows.Clear();
                state.Model.AdditionalElements.RemoveAll(element =>
                    element.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase));
                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            chargedHeader.Children.Add(removeChargedButton);
            state.AdditionalFieldsContainer.Children.Add(chargedHeader);
        }
        else
        {
            chargedHeaderText.Tag = "protoaction.charged";
            state.AdditionalFieldsContainer.Children.Add(chargedHeaderText);
        }

        var chargedContainer = new StackPanel { Tag = "protoaction.charged", Spacing = 4 };
        state.AdditionalFieldsContainer.Children.Add(chargedContainer);

        async Task<bool> HandleChangedAsync()
        {
            if (_isPopulating)
                return false;
            var proceed = await CheckStartLocalMod();
            if (proceed)
                MarkDirty();
            return proceed;
        }

        void AddChargedRow(string modifyType = "", string value = "", string param = "", string applyType = "", string modifyAmountCap = "")
        {
            var rowGrid = new Grid
            {
                ColumnDefinitions = !_isReadOnly
                    ? new ColumnDefinitions("Auto, 180, 100, Auto, 90, Auto, 90, Auto")
                    : new ColumnDefinitions("Auto, 180, 100, Auto, 90, Auto, 90"),
                Margin = new Thickness(0, 2, 0, 2),
                HorizontalAlignment = HorizontalAlignment.Left
            };

            rowGrid.Children.Add(new TextBlock
            {
                Text = "Modify:",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 4, 6, 4)
            });
            var modifyTypeAcb = new AutoCompleteBox
            {
                Text = ProtoConstants.GetModifyTypeDisplayName(modifyType),
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = modifyTypeSuggestions,
                IsEnabled = !_isReadOnly
            };
            EnableDropdownAutoComplete(modifyTypeAcb);
            modifyTypeAcb.TextChanged += async (_, _) => await HandleChangedAsync();
            Grid.SetColumn(modifyTypeAcb, 1);
            rowGrid.Children.Add(modifyTypeAcb);

            var applyTypeCb = new ComboBox
            {
                ItemsSource = new[] { "Multiply", "Add", "Set" },
                SelectedItem = string.IsNullOrWhiteSpace(applyType)
                    ? "Multiply"
                    : new[] { "Multiply", "Add", "Set" }.FirstOrDefault(x => x.Equals(applyType, StringComparison.OrdinalIgnoreCase)) ?? "Multiply",
                IsEnabled = !_isReadOnly,
                Width = 100,
                Margin = new Thickness(8, 0, 0, 0)
            };
            applyTypeCb.SelectionChanged += async (_, _) => await HandleChangedAsync();
            Grid.SetColumn(applyTypeCb, 2);
            rowGrid.Children.Add(applyTypeCb);

            var paramLabel = new TextBlock
            {
                Text = "Damage Type:",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(8, 4, 6, 4)
            };
            Grid.SetColumn(paramLabel, 3);
            rowGrid.Children.Add(paramLabel);

            var paramCb = new ComboBox
            {
                IsEnabled = !_isReadOnly,
                Width = 90
            };
            paramCb.SelectionChanged += async (_, _) => await HandleChangedAsync();
            Grid.SetColumn(paramCb, 4);
            rowGrid.Children.Add(paramCb);

            var valueLabel = new TextBlock
            {
                Text = "Value:",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(8, 4, 6, 4)
            };
            Grid.SetColumn(valueLabel, 5);
            rowGrid.Children.Add(valueLabel);

            var valueTb = new TextBox
            {
                Text = value,
                IsEnabled = !_isReadOnly
            };
            AttachProtoActionDecimalBehavior(valueTb, () => true);
            valueTb.TextChanged += async (_, _) => await HandleChangedAsync();
            Grid.SetColumn(valueTb, 6);
            rowGrid.Children.Add(valueTb);

            var capTb = new TextBox
            {
                Text = modifyAmountCap,
                IsVisible = false
            };

            void RefreshParamVisibility()
            {
                var modifyTypeValue = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                var visible = modifyTypeValue is "DamageSpecific" or "ArmorSpecific";
                RefreshProtoActionDamageTypeCombo(paramCb, modifyTypeValue, param);
                paramLabel.IsVisible = visible;
                paramCb.IsVisible = visible;
                rowGrid.ColumnDefinitions[3].Width = visible ? GridLength.Auto : new GridLength(0);
                rowGrid.ColumnDefinitions[4].Width = visible ? new GridLength(90) : new GridLength(0);
                if (!visible)
                    paramCb.SelectedItem = null;
            }

            modifyTypeAcb.TextChanged += (_, _) => RefreshParamVisibility();
            RefreshParamVisibility();

            var rowState = new ProtoActionChargedRowState
            {
                Container = rowGrid,
                ModifyTypeAcb = modifyTypeAcb,
                ApplyTypeCb = applyTypeCb,
                ValueTb = valueTb,
                ParamCb = paramCb,
                ParamLabel = paramLabel,
                ModifyAmountCapTb = capTb
            };
            state.ChargedRows.Add(rowState);

            if (!_isReadOnly)
            {
                var removeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 0, 0, 0)
                };
                removeButton.Click += async (_, _) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    chargedContainer.Children.Remove(rowGrid);
                    state.ChargedRows.Remove(rowState);
                    if (state.ChargedRows.Count == 0 &&
                        !IsBolsterActionType(actionType) &&
                        !IsRampageActionType(actionType))
                    {
                        state.ForcedVisibleFieldTags.Remove("charged");
                        RefreshProtoActionMetadataPanels(state);
                    }
                    MarkDirty();
                };
                Grid.SetColumn(removeButton, 7);
                rowGrid.Children.Add(removeButton);
            }

            chargedContainer.Children.Add(rowGrid);
        }

        var chargedElements = currentElements ?? effectiveAction.AdditionalElements
            .Where(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase))
            .ToList();
        foreach (var chargedElement in chargedElements)
        {
            var chargedModify = chargedElement.Elements().FirstOrDefault(x => x.Name.LocalName.Equals("chargedmodify", StringComparison.OrdinalIgnoreCase));
            if (chargedModify == null)
                continue;

            AddChargedRow(
                (string?)chargedModify.Attribute("modifytype") ?? (string?)chargedModify.Attribute("modifyType") ?? "",
                chargedModify.Value?.Trim() ?? "",
                (string?)chargedModify.Attribute("param") ?? "",
                (string?)chargedModify.Attribute("applytype") ?? (string?)chargedModify.Attribute("applyType") ?? "",
                (string?)chargedModify.Attribute("modifyamountcap") ?? (string?)chargedModify.Attribute("modifyAmountCap") ?? "");
        }

        if (!_isReadOnly && !state.IsLinkedMaulAreaAction)
        {
            var addButton = new Button
            {
                Tag = "protoaction.charged",
                Content = "Charged Modifier",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left
            };
            addButton.Click += async (_, _) =>
            {
                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                AddChargedRow();
                MarkDirty();
            };
            state.AdditionalFieldsContainer.Children.Add(addButton);
        }
    }

    private static readonly string[] ChargedModifyActivationTypes =
    [
        "Combat",
        "BelowHitpointsThreshold",
        "AfterAction",
        "KillEnemy",
        "UseByAbility",
        "UseOnce",
        "TerrainType",
        "Always",
        "ChargedActionActive",
        "AuxChargedActionActive",
    ];

    private void RenderProtoActionFullChargedFields(
        ProtoActionWidgetState state,
        IReadOnlyList<XElement>? currentElements = null)
    {
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        state.FullChargedRows.Clear();
        if (IsBolsterActionType(actionType))
            return;

        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var hasChargedData = effectiveAction.AdditionalElements.Any(element =>
            element.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase));
        var usesFullActionLayout = IsChargedModifyActionType(actionType);
        var usesSharedOptionalLayout = !usesFullActionLayout;
        var showChargedModifiers = usesFullActionLayout ||
                                   IsRampageActionType(actionType) ||
                                   state.ForcedVisibleFieldTags.Contains("charged") ||
                                   (hasChargedData && !IsBolsterActionType(actionType));
        if (!showChargedModifiers)
            return;

        var chargedElements = currentElements?.Select(x => new XElement(x)).ToList()
            ?? effectiveAction.AdditionalElements
                .Where(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase))
                .Select(x => new XElement(x))
                .ToList();

        if (chargedElements.Count == 0 && !_isReadOnly)
            chargedElements.Add(new XElement("charged"));
        if (chargedElements.Count == 0)
            return;

        var isAdditionalChargedSection = usesSharedOptionalLayout &&
                                         !IsRampageActionType(actionType);
        var chargedHeader = new WrapPanel
        {
            Tag = "protoaction.charged",
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 6, 0, 2)
        };
        chargedHeader.Children.Add(new TextBlock
        {
            Text = "Charged Modifier Configuration",
            FontWeight = FontWeight.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        });
        if (isAdditionalChargedSection && !_isReadOnly)
        {
            var removeChargedButton = new Button
            {
                Classes = { "remove-button" },
                Margin = new Thickness(2, 0, 0, 0),
                VerticalAlignment = VerticalAlignment.Center
            };
            removeChargedButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;
                state.ForcedVisibleFieldTags.Remove("charged");
                state.FullChargedRows.Clear();
                state.PendingFullChargedElements.Clear();
                state.Model.AdditionalElements.RemoveAll(element =>
                    element.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase));
                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            chargedHeader.Children.Add(removeChargedButton);
        }
        state.AdditionalFieldsContainer.Children.Add(chargedHeader);

        var cardsHost = new StackPanel { Tag = "protoaction.charged", Spacing = 8 };
        state.AdditionalFieldsContainer.Children.Add(cardsHost);

        var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
            .Select(ProtoConstants.GetModifyTypeDisplayName)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var protoUnitSuggestions = GetAvailableTrainUnitNames();
        var attachmentSuggestions = GetAvailableProtoActionAttachmentPaths();
        var attachmentBoneSuggestions = GetAvailableProtoActionModelAttachmentBones();
        var isInitializingFullChargedEditor = true;

        async Task HandleChangedAsync()
        {
            if (_isPopulating || isInitializingFullChargedEditor)
                return;
            var proceed = await CheckStartLocalMod();
            if (proceed)
                MarkDirty();
        }

        static XElement? FindChild(XElement parent, string tag)
            => parent.Elements().FirstOrDefault(x => x.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));

        foreach (var sourceElement in chargedElements)
        {
            var originalElement = new XElement(sourceElement);
            var chargedModify = FindChild(sourceElement, "chargedmodify");
            var activationValue = FindChild(sourceElement, "activationtype")?.Value?.Trim() ?? "";
            var terrainValue = FindChild(sourceElement, "terraintype")?.Value?.Trim() ?? "";
            var stealthElement = FindChild(sourceElement, "stealth");
            var chargedRemoveElement = FindChild(sourceElement, "chargedremove");

            var card = new ChargedEditor(
                _isReadOnly,
                showRemoveButton: chargedElements.Count > 1);
            var cardStack = card.Body;

            if (card.RemoveButton != null)
            {
                card.RemoveButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;

                    var cardIndex = cardsHost.Children.IndexOf(card);
                    if (cardIndex >= 0 && cardIndex < state.FullChargedRows.Count)
                        state.FullChargedRows.RemoveAt(cardIndex);

                    RefreshProtoActionMetadataPanels(state);
                    MarkDirty();
                };
            }

            // Keep each label/editor pair together, but allow complete pairs to wrap
            // when the editor pane becomes narrow.
            var modifierRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center,
                IsVisible = !usesSharedOptionalLayout || chargedModify != null
            };

            var modifyTypeGroup = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = new Thickness(0, 0, 10, 4),
                VerticalAlignment = VerticalAlignment.Center
            };
            modifyTypeGroup.Children.Add(new TextBlock
            {
                Text = "Modify:",
                VerticalAlignment = VerticalAlignment.Center
            });
            var modifyTypeAcb = new AutoCompleteBox
            {
                Text = ProtoConstants.GetModifyTypeDisplayName(
                    (string?)chargedModify?.Attribute("modifytype") ??
                    (string?)chargedModify?.Attribute("modifyType") ?? ""),
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = modifyTypeSuggestions,
                IsEnabled = !_isReadOnly,
                Width = 180
            };
            EnableDropdownAutoComplete(modifyTypeAcb);
            modifyTypeGroup.Children.Add(modifyTypeAcb);
            modifierRow.Children.Add(modifyTypeGroup);

            var applyTypeGroup = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = new Thickness(0, 0, 10, 4),
                VerticalAlignment = VerticalAlignment.Center
            };
            applyTypeGroup.Children.Add(new TextBlock
            {
                Text = "Apply Type:",
                VerticalAlignment = VerticalAlignment.Center
            });
            var applyTypeValue = (string?)chargedModify?.Attribute("applytype") ??
                                 (string?)chargedModify?.Attribute("applyType") ?? "Multiply";
            var applyTypeCb = new ComboBox
            {
                ItemsSource = new[] { "Multiply", "Add", "Set" },
                SelectedItem = new[] { "Multiply", "Add", "Set" }
                    .FirstOrDefault(x => x.Equals(applyTypeValue, StringComparison.OrdinalIgnoreCase)) ?? "Multiply",
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            applyTypeGroup.Children.Add(applyTypeCb);
            modifierRow.Children.Add(applyTypeGroup);

            var paramGroup = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = new Thickness(0, 0, 10, 4),
                VerticalAlignment = VerticalAlignment.Center
            };
            var paramLabel = new TextBlock
            {
                Text = "Damage Type:",
                VerticalAlignment = VerticalAlignment.Center
            };
            paramGroup.Children.Add(paramLabel);
            var paramValue = (string?)chargedModify?.Attribute("param") ?? "";
            var paramCb = new ComboBox
            {
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            RefreshProtoActionDamageTypeCombo(paramCb, modifyTypeAcb.Text, paramValue);
            paramGroup.Children.Add(paramCb);
            modifierRow.Children.Add(paramGroup);

            var valueGroup = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = new Thickness(0, 0, 0, 4),
                VerticalAlignment = VerticalAlignment.Center
            };
            valueGroup.Children.Add(new TextBlock
            {
                Text = "Value:",
                VerticalAlignment = VerticalAlignment.Center
            });
            var valueTb = new TextBox
            {
                Text = chargedModify?.Value?.Trim() ?? "",
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            AttachProtoActionDecimalBehavior(valueTb, () => true);
            valueGroup.Children.Add(valueTb);
            modifierRow.Children.Add(valueGroup);
            // Activation-specific fields stay beside Activation Type and wrap as complete label/editor groups.
            var activationRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center,
                IsVisible = !usesSharedOptionalLayout || !string.IsNullOrWhiteSpace(activationValue)
            };
            var activationTypeCb = new ComboBox
            {
                ItemsSource = ChargedModifyActivationTypes,
                SelectedItem = ChargedModifyActivationTypes.FirstOrDefault(x => x.Equals(activationValue, StringComparison.OrdinalIgnoreCase)),
                IsEnabled = !_isReadOnly,
                Width = 190
            };
            activationRow.Children.Add(CreateLabeledFieldGroup("Activation Type:", activationTypeCb));

            var thresholdTb = new TextBox
            {
                Text = FindChild(sourceElement, "hitpointsratiothreshold")?.Value?.Trim() ?? "",
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            AttachProtoActionDecimalBehavior(thresholdTb);
            var thresholdRow = CreateLabeledFieldGroup(
                "Hitpoints Ratio Threshold:",
                thresholdTb);
            activationRow.Children.Add(thresholdRow);

            var terrainTypeCb = new ComboBox
            {
                ItemsSource = new[] { "Water", "Land" },
                SelectedItem = new[] { "Water", "Land" }.FirstOrDefault(x => x.Equals(terrainValue, StringComparison.OrdinalIgnoreCase)),
                IsEnabled = !_isReadOnly,
                Width = 120
            };
            var terrainRow = CreateLabeledFieldGroup("Terrain Type:", terrainTypeCb);
            activationRow.Children.Add(terrainRow);

            Button? addActivationButton = null;
            if (usesSharedOptionalLayout && !_isReadOnly)
            {
                var removeActivationButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 0, 0, 4),
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeActivationButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    activationTypeCb.SelectedItem = null;
                    thresholdTb.Text = "";
                    terrainTypeCb.SelectedItem = null;
                    activationRow.IsVisible = false;
                    if (addActivationButton != null)
                        addActivationButton.IsVisible = true;
                    MarkDirty();
                };
                activationRow.Children.Add(removeActivationButton);

                addActivationButton = new Button
                {
                    Content = "Activation Type",
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left,
                    IsVisible = !activationRow.IsVisible,
                    Margin = new Thickness(0, 0, 0, 4)
                };
                addActivationButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    activationRow.IsVisible = true;
                    addActivationButton.IsVisible = false;
                    MarkDirty();
                };
                cardStack.Children.Add(addActivationButton);
            }
            cardStack.Children.Add(activationRow);

            Button? addModifierButton = null;
            if (usesSharedOptionalLayout && !_isReadOnly)
            {
                var removeModifierButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 0, 0, 4),
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeModifierButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    modifyTypeAcb.Text = "";
                    applyTypeCb.SelectedItem = "Multiply";
                    paramCb.SelectedItem = null;
                    valueTb.Text = "";
                    modifierRow.IsVisible = false;
                    if (addModifierButton != null)
                        addModifierButton.IsVisible = true;
                    MarkDirty();
                };
                modifierRow.Children.Add(removeModifierButton);

                addModifierButton = new Button
                {
                    Content = "Add Modifier",
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left,
                    IsVisible = !modifierRow.IsVisible,
                    Margin = new Thickness(0, 0, 0, 4)
                };
                addModifierButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    modifierRow.IsVisible = true;
                    addModifierButton.IsVisible = false;
                    MarkDirty();
                };
                cardStack.Children.Add(addModifierButton);
            }
            cardStack.Children.Add(modifierRow);

            // Timing and stealth share their own row below activation.
            var timingRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center
            };
            var cooldownTb = new TextBox
            {
                Text = FindChild(sourceElement, "cooldown")?.Value?.Trim() ?? "",
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            AttachProtoActionDecimalBehavior(cooldownTb);
            var cooldownGroup = CreateLabeledFieldGroup("Cooldown (s):", cooldownTb);
            cooldownGroup.IsVisible = !usesSharedOptionalLayout || FindChild(sourceElement, "cooldown") != null;
            timingRow.Children.Add(cooldownGroup);

            var durationTb = new TextBox
            {
                Text = FindChild(sourceElement, "duration")?.Value?.Trim() ?? "",
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            AttachProtoActionDecimalBehavior(durationTb);
            var durationGroup = CreateLabeledFieldGroup("Duration (s):", durationTb);
            durationGroup.IsVisible = !usesSharedOptionalLayout || FindChild(sourceElement, "duration") != null;
            timingRow.Children.Add(durationGroup);

            Button? addCooldownButton = null;
            Button? addDurationButton = null;
            if (usesSharedOptionalLayout && !_isReadOnly)
            {
                void AddTimingRemoveButton(Control group, TextBox editor, Action showAddButton)
                {
                    if (group is not Panel panel)
                        return;
                    var removeButton = new Button
                    {
                        Classes = { "remove-button" },
                        Margin = new Thickness(2, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    removeButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;
                        editor.Text = "";
                        group.IsVisible = false;
                        showAddButton();
                        MarkDirty();
                    };
                    panel.Children.Add(removeButton);
                }

                addCooldownButton = new Button
                {
                    Content = "Cooldown",
                    Classes = { "add-component" },
                    IsVisible = !cooldownGroup.IsVisible,
                    Margin = new Thickness(0, 0, 6, 4)
                };
                addCooldownButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    cooldownGroup.IsVisible = true;
                    addCooldownButton.IsVisible = false;
                    MarkDirty();
                };
                timingRow.Children.Add(addCooldownButton);
                AddTimingRemoveButton(cooldownGroup, cooldownTb, () => addCooldownButton.IsVisible = true);

                addDurationButton = new Button
                {
                    Content = "Duration",
                    Classes = { "add-component" },
                    IsVisible = !durationGroup.IsVisible,
                    Margin = new Thickness(0, 0, 6, 4)
                };
                addDurationButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    durationGroup.IsVisible = true;
                    addDurationButton.IsVisible = false;
                    MarkDirty();
                };
                timingRow.Children.Add(addDurationButton);
                AddTimingRemoveButton(durationGroup, durationTb, () => addDurationButton.IsVisible = true);
            }

            var stealthCb = new CheckBox
            {
                Content = "Activate stealth",
                IsChecked = stealthElement != null &&
                            !stealthElement.Value.Trim().Equals("0", StringComparison.OrdinalIgnoreCase),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 12, 6)
            };
            timingRow.Children.Add(stealthCb);

            var removeChargeCb = new CheckBox
            {
                Content = "Remove charge",
                IsChecked = chargedRemoveElement != null &&
                            !chargedRemoveElement.Value.Trim().Equals("0", StringComparison.OrdinalIgnoreCase) &&
                            !chargedRemoveElement.Value.Trim().Equals("false", StringComparison.OrdinalIgnoreCase),
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 12, 6)
            };
            timingRow.Children.Add(removeChargeCb);
            cardStack.Children.Add(timingRow);

            var optionalRowsHost = new StackPanel { Spacing = 4 };
            cardStack.Children.Add(optionalRowsHost);

            var vfxRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Left,
                IsVisible = FindChild(sourceElement, "chargedmodifyvfx") != null ||
                            FindChild(sourceElement, "chargedmodifyvfxduration") != null
            };
            var vfxAcb = new AutoCompleteBox
            {
                Text = FindChild(sourceElement, "chargedmodifyvfx")?.Value?.Trim() ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = protoUnitSuggestions,
                IsEnabled = !_isReadOnly,
                Width = 220
            };
            EnableDropdownAutoComplete(vfxAcb);
            vfxRow.Children.Add(CreateLabeledFieldGroup("Activation VFX:", vfxAcb));

            var vfxDurationTb = new TextBox
            {
                Text = FindChild(sourceElement, "chargedmodifyvfxduration")?.Value?.Trim() ?? "",
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            AttachProtoActionDecimalBehavior(vfxDurationTb);
            vfxRow.Children.Add(CreateLabeledFieldGroup("VFX Duration (s):", vfxDurationTb));
            optionalRowsHost.Children.Add(vfxRow);

            var setTacticRow = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Left,
                IsVisible = FindChild(sourceElement, "settactic") != null
            };
            var setTacticTb = new TextBox
            {
                Text = FindChild(sourceElement, "settactic")?.Value?.Trim() ?? "",
                IsEnabled = !_isReadOnly,
                Width = 260
            };
            setTacticRow.Children.Add(CreateLabeledFieldGroup("Set Tactic:", setTacticTb));
            optionalRowsHost.Children.Add(setTacticRow);

            var attachmentRow = new Grid
            {
                HorizontalAlignment = HorizontalAlignment.Stretch,
                IsVisible = FindChild(sourceElement, "chargedmodelattachment") != null ||
                            FindChild(sourceElement, "chargedmodelattachmentbone") != null
            };
            var attachmentWrap = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center
            };
            attachmentRow.Children.Add(attachmentWrap);

            var attachmentPathGroup = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = new Thickness(0, 0, 10, 4),
                VerticalAlignment = VerticalAlignment.Center
            };
            attachmentPathGroup.Children.Add(new TextBlock
            {
                Text = "Charged Model Attachment:",
                VerticalAlignment = VerticalAlignment.Center
            });
            var attachmentEditor = CreateAssetPathEditor(
                "chargedmodelattachment",
                FindChild(sourceElement, "chargedmodelattachment")?.Value?.Trim() ?? "",
                attachmentSuggestions);
            attachmentEditor.Width = 200;
            attachmentPathGroup.Children.Add(attachmentEditor);
            attachmentWrap.Children.Add(attachmentPathGroup);

            var attachmentBoneGroup = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 6,
                Margin = new Thickness(0, 0, 10, 4),
                VerticalAlignment = VerticalAlignment.Center
            };
            attachmentBoneGroup.Children.Add(new TextBlock
            {
                Text = "Bone:",
                VerticalAlignment = VerticalAlignment.Center
            });
            var attachmentBoneAcb = new AutoCompleteBox
            {
                Text = FindChild(sourceElement, "chargedmodelattachmentbone")?.Value?.Trim() ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = attachmentBoneSuggestions,
                IsEnabled = !_isReadOnly,
                Width = 100
            };
            EnableDropdownAutoComplete(attachmentBoneAcb);
            attachmentBoneGroup.Children.Add(attachmentBoneAcb);
            attachmentWrap.Children.Add(attachmentBoneGroup);
            optionalRowsHost.Children.Add(attachmentRow);

            Button? addVfxButton = null;
            Button? addSetTacticButton = null;
            Button? addAttachmentButton = null;

            void RefreshOptionalButtons()
            {
                if (addVfxButton != null)
                    addVfxButton.IsVisible = !vfxRow.IsVisible;
                if (addSetTacticButton != null)
                    addSetTacticButton.IsVisible = !setTacticRow.IsVisible;
                if (addAttachmentButton != null)
                    addAttachmentButton.IsVisible = !attachmentRow.IsVisible;
            }

            if (!_isReadOnly)
            {
                Button CreateRemoveButton(Action clearAndHide)
                {
                    var button = new Button
                    {
                        Classes = { "remove-button" } };
                    button.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;
                        clearAndHide();
                        RefreshOptionalButtons();
                        MarkDirty();
                    };
                    return button;
                }

                var removeVfxButton = CreateRemoveButton(() =>
                {
                    vfxAcb.Text = "";
                    vfxDurationTb.Text = "";
                    vfxRow.IsVisible = false;
                });
                vfxRow.Children.Add(removeVfxButton);

                var removeSetTacticButton = CreateRemoveButton(() =>
                {
                    setTacticTb.Text = "";
                    setTacticRow.IsVisible = false;
                });
                setTacticRow.Children.Add(removeSetTacticButton);

                var removeAttachmentButton = CreateRemoveButton(() =>
                {
                    attachmentEditor.Configure("", attachmentSuggestions, HandleAssetPathChangedAsync);
                    attachmentBoneAcb.Text = "";
                    attachmentRow.IsVisible = false;
                });
                removeAttachmentButton.Margin = new Thickness(0, 0, 0, 4);
                attachmentWrap.Children.Add(removeAttachmentButton);

                var optionalButtons = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 3, 0, 0)
                };
                cardStack.Children.Add(optionalButtons);

                Button CreateAddButton(string text, Action show)
                {
                    var button = new Button
                    {
                        Content = text,
                        Classes = { "add-component" },
                        Margin = new Thickness(0, 0, 6, 4)
                    };
                    button.Click += async (_, _) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;
                        show();
                        RefreshOptionalButtons();
                        MarkDirty();
                    };
                    optionalButtons.Children.Add(button);
                    return button;
                }

                addVfxButton = CreateAddButton("VFX", () => vfxRow.IsVisible = true);
                addSetTacticButton = CreateAddButton("Set Tactic", () => setTacticRow.IsVisible = true);
                addAttachmentButton = CreateAddButton("Model Attachment", () => attachmentRow.IsVisible = true);
                RefreshOptionalButtons();
            }

            void RefreshConditionalRows()
            {
                var selectedActivation = activationTypeCb.SelectedItem as string ?? "";
                thresholdRow.IsVisible = selectedActivation.Equals("BelowHitpointsThreshold", StringComparison.OrdinalIgnoreCase);
                terrainRow.IsVisible = selectedActivation.Equals("TerrainType", StringComparison.OrdinalIgnoreCase);
            }

            void RefreshParamVisibility()
            {
                var modifyTypeValue = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                var visible = modifyTypeValue is "DamageSpecific" or "ArmorSpecific";
                RefreshProtoActionDamageTypeCombo(paramCb, modifyTypeValue, paramValue);
                paramGroup.IsVisible = visible;
            }

            modifyTypeAcb.TextChanged += async (_, _) =>
            {
                RefreshParamVisibility();
                await HandleChangedAsync();
            };
            applyTypeCb.SelectionChanged += async (_, _) => await HandleChangedAsync();
            paramCb.SelectionChanged += async (_, _) => await HandleChangedAsync();
            valueTb.TextChanged += async (_, _) => await HandleChangedAsync();
            activationTypeCb.SelectionChanged += async (_, _) =>
            {
                RefreshConditionalRows();
                await HandleChangedAsync();
            };
            cooldownTb.TextChanged += async (_, _) => await HandleChangedAsync();
            durationTb.TextChanged += async (_, _) => await HandleChangedAsync();
            thresholdTb.TextChanged += async (_, _) => await HandleChangedAsync();
            terrainTypeCb.SelectionChanged += async (_, _) => await HandleChangedAsync();
            stealthCb.IsCheckedChanged += async (_, _) => await HandleChangedAsync();
            removeChargeCb.IsCheckedChanged += async (_, _) => await HandleChangedAsync();
            vfxAcb.TextChanged += async (_, _) => await HandleChangedAsync();
            vfxDurationTb.TextChanged += async (_, _) => await HandleChangedAsync();
            setTacticTb.TextChanged += async (_, _) => await HandleChangedAsync();
            attachmentBoneAcb.TextChanged += async (_, _) => await HandleChangedAsync();

            RefreshParamVisibility();
            RefreshConditionalRows();

            state.FullChargedRows.Add(new ProtoActionFullChargedState
            {
                OriginalElement = originalElement,
                ModifyTypeAcb = modifyTypeAcb,
                ApplyTypeCb = applyTypeCb,
                ParamCb = paramCb,
                ValueTb = valueTb,
                ModifierRow = modifierRow,
                ActivationTypeCb = activationTypeCb,
                ActivationRow = activationRow,
                CooldownTb = cooldownTb,
                CooldownGroup = cooldownGroup,
                DurationTb = durationTb,
                DurationGroup = durationGroup,
                ThresholdRow = thresholdRow,
                ThresholdTb = thresholdTb,
                TerrainRow = terrainRow,
                TerrainTypeCb = terrainTypeCb,
                StealthCb = stealthCb,
                RemoveChargeCb = removeChargeCb,
                VfxRow = vfxRow,
                VfxAcb = vfxAcb,
                VfxDurationTb = vfxDurationTb,
                SetTacticRow = setTacticRow,
                SetTacticTb = setTacticTb,
                AttachmentRow = attachmentRow,
                ChargedModelAttachmentEditor = attachmentEditor,
                ChargedModelAttachmentBoneAcb = attachmentBoneAcb
            });

            cardsHost.Children.Add(card);
        }

        // ComboBox and AutoCompleteBox initialization can raise selection events while
        // the card is still being assembled. Do not let those events re-enter the editor
        // refresh/save pipeline with a partially constructed ChargedModify state.
        isInitializingFullChargedEditor = false;

        if (!_isReadOnly)
        {
            var addContainerButton = new Button
            {
                Tag = "protoaction.charged",
                Content = "Charged Container",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left,
                Margin = new Thickness(0, 4, 0, 0)
            };
            addContainerButton.Click += async (_, _) =>
            {
                if (!await CheckStartLocalMod())
                    return;

                state.PendingFullChargedElements.Add(new XElement("charged"));
                RefreshProtoActionMetadataPanels(state);
                MarkDirty();
            };
            state.AdditionalFieldsContainer.Children.Add(addContainerButton);
        }
    }

    private List<ProtoActionOnHitEffectEntry> CollectProtoActionOnHitEffectEntries(ProtoActionWidgetState state)
    {
        var result = new List<ProtoActionOnHitEffectEntry>();
        foreach (var row in state.OnHitEffectRows)
        {
            if (!row.IsSupported)
            {
                result.Add(new ProtoActionOnHitEffectEntry
                {
                    Element = new XElement(row.OriginalElement),
                    IsSupported = false
                });
                continue;
            }

            var effectType = row.TypeCb.Text?.Trim() ?? "";
            // Dead Only remains compatible with existing/manual XML, but is no longer
            // offered when creating a new effect.
            var hasExistingDeadOnly = row.OriginalElement.Attribute("deadonly") != null;
            var canPreserveOriginal = row.OriginalElement.Attribute("type")?.Value?.Trim()
                .Equals(effectType, StringComparison.OrdinalIgnoreCase) == true;
            var element = canPreserveOriginal
                ? new XElement(row.OriginalElement)
                : new XElement("onhiteffect");
            RemoveWhitespaceOnlyTextNodes(element);

            foreach (var attributeName in new[]
                     {
                         "type", "active", "deadonly", "duration", "targetunittype", "rate", "prob", "globalprob",
                         "hidevfx", "freezetype", "damage", "proto", "attachbone", "stacklimit", "delay", "radius",
                         "ignoredeadhuntables", "stealthonly", "shadingtype", "fadetime", "factor", "anim", "protoaction", "freezeduration",
                         "rewardtype", "amount", "additive", "relativity", "byunittype", "terraintype", "playerrelation"
                     })
            {
                element.Attributes(attributeName).Remove();
            }

            if (!string.IsNullOrWhiteSpace(effectType))
                element.SetAttributeValue("type", effectType);
            if (row.ActiveCb.IsChecked != true)
                element.SetAttributeValue("active", "0");
            if (hasExistingDeadOnly)
                element.SetAttributeValue("deadonly", row.DeadOnlyCb.IsChecked == true ? "1" : "0");

            var duration = row.DurationTb.Text?.Trim() ?? "";
            var delay = row.DelayTb.Text?.Trim() ?? "";
            var radius = row.RadiusTb.Text?.Trim() ?? "";
            var stackLimit = row.StackLimitTb.Text?.Trim() ?? "";
            var targetUnitType = row.TargetUnitTypeAcb.Text?.Trim() ?? "";
            var anim = row.AnimAcb.Text?.Trim() ?? "";
            var protoAction = row.ProtoActionAcb.Text?.Trim() ?? "";
            var attachProto = row.AttachProtoAcb.Text?.Trim() ?? "";
            var attachBone = row.AttachBoneAcb.Text?.Trim() ?? "";
            var rate = row.RateTb.Text?.Trim() ?? "";
            var prob = row.ProbTb.Text?.Trim() ?? "";
            var globalProb = row.GlobalProbTb.Text?.Trim() ?? "";
            var playerRelation = row.PlayerRelationAcb.Text?.Trim() ?? "";
            var rewardType = row.RewardTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
            var amount = row.AmountTb.Text?.Trim() ?? "";
            var relativity = row.RelativityCb.SelectedItem?.ToString()?.Trim().ToLowerInvariant() ?? "";
            var byUnitType = row.ByUnitTypeAcb.Text?.Trim() ?? "";
            var terrainType = row.TerrainTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
            var shadingType = ProtoConstants.GetShadingTypeXmlValue(row.ShadingTypeAcb.Text);
            var fadeTime = row.FadeTimeTb.Text?.Trim() ?? "";
            var factor = row.FactorTb.Text?.Trim() ?? "";
            var freezeDuration = row.FreezeDurationTb.Text?.Trim() ?? "";
            if (!effectType.Equals("TreeFlatten", StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(duration))
                element.SetAttributeValue("duration", duration);
            if (!string.IsNullOrWhiteSpace(delay))
                element.SetAttributeValue("delay", delay);
            if (!string.IsNullOrWhiteSpace(radius))
                element.SetAttributeValue("radius", radius);
            if (!string.IsNullOrWhiteSpace(stackLimit))
                element.SetAttributeValue("stacklimit", stackLimit);
            var usesMultipleTargets = string.Equals(
                row.TargetModeCb.SelectedItem?.ToString() ?? row.TargetModeCb.SelectedValue?.ToString(),
                "Multiple",
                StringComparison.OrdinalIgnoreCase);
            if (!usesMultipleTargets && !string.IsNullOrWhiteSpace(targetUnitType))
                element.SetAttributeValue("targetunittype", targetUnitType);
            if (!string.IsNullOrWhiteSpace(anim))
                element.SetAttributeValue("anim", anim);
            if (!string.IsNullOrWhiteSpace(protoAction))
                element.SetAttributeValue("protoaction", protoAction);
            if (!string.IsNullOrWhiteSpace(attachProto))
                element.SetAttributeValue("proto", attachProto);
            if (!string.IsNullOrWhiteSpace(attachBone))
                element.SetAttributeValue("attachbone", attachBone);
            if (!string.IsNullOrWhiteSpace(rate))
                element.SetAttributeValue("rate", rate);
            if (!string.IsNullOrWhiteSpace(prob))
                element.SetAttributeValue("prob", prob);
            if (!string.IsNullOrWhiteSpace(globalProb))
                element.SetAttributeValue("globalprob", globalProb);
            if (!string.IsNullOrWhiteSpace(playerRelation))
                element.SetAttributeValue("playerrelation", playerRelation);
            if (!string.IsNullOrWhiteSpace(rewardType))
                element.SetAttributeValue("rewardtype", rewardType);
            if (!string.IsNullOrWhiteSpace(amount))
                element.SetAttributeValue("amount", amount);
            if (effectType.Equals("KillReward", StringComparison.OrdinalIgnoreCase))
                element.SetAttributeValue("additive", row.AdditiveCb.IsChecked == true ? "1" : "0");
            if (effectType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(relativity))
                element.SetAttributeValue("relativity", relativity);
            if (!string.IsNullOrWhiteSpace(byUnitType))
                element.SetAttributeValue("byunittype", byUnitType);
            if (!string.IsNullOrWhiteSpace(terrainType))
                element.SetAttributeValue("terraintype", terrainType);
            if (row.IgnoreDeadHuntablesCb.IsChecked == true)
                element.SetAttributeValue("ignoredeadhuntables", "");
            if (row.StealthOnlyCb.IsChecked == true)
                element.SetAttributeValue("stealthonly", "true");
            if (!string.IsNullOrWhiteSpace(shadingType))
                element.SetAttributeValue("shadingtype", shadingType);
            if (!string.IsNullOrWhiteSpace(fadeTime))
                element.SetAttributeValue("fadetime", fadeTime);
            if (!string.IsNullOrWhiteSpace(factor))
                element.SetAttributeValue("factor", factor);

            element.Elements()
                .Where(x => x.Name.LocalName.Equals("target", StringComparison.OrdinalIgnoreCase))
                .Remove();

            if (usesMultipleTargets)
            {
                foreach (var attackType in row.ChildAttackTypeAcbs
                             .Select(x => x.Text?.Trim() ?? "")
                             .Where(x => !string.IsNullOrWhiteSpace(x)))
                {
                    element.Add(new XElement("target", new XAttribute("attacktype", attackType)));
                }

                foreach (var ignoreType in row.ChildIgnoreTypeAcbs
                             .Select(x => x.Text?.Trim() ?? "")
                             .Where(x => !string.IsNullOrWhiteSpace(x)))
                {
                    element.Add(new XElement("target", new XAttribute("ignoretype", ignoreType)));
                }
            }

            element.Elements()
                .Where(x => x.Name.LocalName.Equals("damage", StringComparison.OrdinalIgnoreCase))
                .Remove();

            foreach (var damageRow in row.DamageRows)
            {
                var damageType = damageRow.DamageTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
                var damageValue = damageRow.ValueTb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(damageType) || string.IsNullOrWhiteSpace(damageValue))
                    continue;

                var damageElement = damageRow.OriginalElement.Name.LocalName.Equals("damage", StringComparison.OrdinalIgnoreCase)
                    ? new XElement(damageRow.OriginalElement)
                    : new XElement("damage");
                RemoveWhitespaceOnlyTextNodes(damageElement);
                damageElement.Attributes("type").Remove();
                damageElement.SetAttributeValue("type", damageType);
                damageElement.Value = damageValue;
                element.Add(damageElement);
            }

            element.Elements()
                .Where(x => x.Name.LocalName.Equals("modify", StringComparison.OrdinalIgnoreCase))
                .Remove();

            foreach (var modifyRow in row.ModifyRows)
            {
                var modifyType = ProtoConstants.GetModifyTypeValue(modifyRow.ModifyTypeAcb.Text?.Trim() ?? "");
                var applyType = modifyRow.ApplyTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
                var damageType = modifyRow.DamageTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
                var modifyValue = modifyRow.ValueTb.Text?.Trim() ?? "";
                var stackEnabled = modifyRow.StackCb.IsChecked == true;
                if (string.IsNullOrWhiteSpace(modifyType) || string.IsNullOrWhiteSpace(modifyValue))
                    continue;

                var modifyElement = modifyRow.OriginalElement.Name.LocalName.Equals("modify", StringComparison.OrdinalIgnoreCase)
                    ? new XElement(modifyRow.OriginalElement)
                    : new XElement("modify");
                RemoveWhitespaceOnlyTextNodes(modifyElement);
                foreach (var attrName in new[] { "type", "applytype", "dmgtype", "stack" })
                    modifyElement.Attributes(attrName).Remove();
                modifyElement.SetAttributeValue("type", modifyType);
                if (!string.IsNullOrWhiteSpace(applyType) && !applyType.Equals("Multiply", StringComparison.OrdinalIgnoreCase))
                    modifyElement.SetAttributeValue("applytype", applyType);
                if (modifyType is "DamageSpecific" or "ArmorSpecific" && !string.IsNullOrWhiteSpace(damageType))
                    modifyElement.SetAttributeValue("dmgtype", damageType);
                if (stackEnabled)
                    modifyElement.SetAttributeValue("stack", "");
                modifyElement.Value = modifyValue;
                element.Add(modifyElement);
            }

            element.Elements()
                .Where(x => x.Name.LocalName.Equals("modifyramp", StringComparison.OrdinalIgnoreCase))
                .Remove();

            foreach (var modifyRampRow in row.ModifyRampRows)
            {
                var modifyType = ProtoConstants.GetModifyTypeValue(modifyRampRow.ModifyTypeAcb.Text?.Trim() ?? "");
                var damageType = modifyRampRow.DamageTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
                var initValue = modifyRampRow.InitTb.Text?.Trim() ?? "";
                var finalValue = modifyRampRow.FinalTb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(modifyType) ||
                    string.IsNullOrWhiteSpace(initValue) ||
                    string.IsNullOrWhiteSpace(finalValue))
                {
                    continue;
                }

                var modifyRampElement = modifyRampRow.OriginalElement.Name.LocalName.Equals("modifyramp", StringComparison.OrdinalIgnoreCase)
                    ? new XElement(modifyRampRow.OriginalElement)
                    : new XElement("modifyramp");
                RemoveWhitespaceOnlyTextNodes(modifyRampElement);
                foreach (var attrName in new[] { "type", "dmgtype", "init", "final" })
                    modifyRampElement.Attributes(attrName).Remove();
                modifyRampElement.SetAttributeValue("type", modifyType);
                if (modifyType is "DamageSpecific" or "ArmorSpecific" && !string.IsNullOrWhiteSpace(damageType))
                    modifyRampElement.SetAttributeValue("dmgtype", damageType);
                modifyRampElement.SetAttributeValue("init", initValue);
                modifyRampElement.SetAttributeValue("final", finalValue);
                modifyRampElement.Value = "";
                element.Add(modifyRampElement);
            }

            if (effectType.Equals("Stun", StringComparison.OrdinalIgnoreCase))
            {
                if (row.HideVfxCb.IsChecked == true)
                    element.SetAttributeValue("hidevfx", "true");
            }
            else if (effectType.Equals("Freeze", StringComparison.OrdinalIgnoreCase))
            {
                var freezeType = GetOnHitEffectFreezeTypeXmlValue(
                    row.FreezeTypeCb.SelectedItem as string ?? row.FreezeTypeCb.Text);
                var damage = row.FreezeDamageTb.Text?.Trim() ?? "";
                if (!string.IsNullOrWhiteSpace(freezeType))
                    element.SetAttributeValue("freezetype", freezeType);
                if (!string.IsNullOrWhiteSpace(damage))
                    element.SetAttributeValue("damage", damage);
            }
            else if (effectType.Equals("ProgFreeze", StringComparison.OrdinalIgnoreCase) ||
                     effectType.Equals("ProgFreezeSpeed", StringComparison.OrdinalIgnoreCase) ||
                     effectType.Equals("ProgFreezeROF", StringComparison.OrdinalIgnoreCase))
            {
                if (!string.IsNullOrWhiteSpace(freezeDuration))
                    element.SetAttributeValue("freezeduration", freezeDuration);
            }

            result.Add(new ProtoActionOnHitEffectEntry
            {
                Element = element,
                IsSupported = true
            });
        }

        return result;
    }

    private void RenderProtoActionOnHitEffects(
        ProtoActionWidgetState state,
        List<ProtoActionOnHitEffectEntry>? currentEntries = null,
        IReadOnlyList<string>? newEffectTypes = null,
        string? defaultNewEffectType = null)
    {
        var newEffectTypeOptions = newEffectTypes ?? SupportedOnHitEffectTypes;
        bool IsSupportedEffectType(string? effectType)
            => !string.IsNullOrWhiteSpace(effectType) &&
               SupportedOnHitEffectTypes.Contains(effectType.Trim(), StringComparer.OrdinalIgnoreCase);

        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var isAutoBoostAction = IsAutoBoostActionType(ResolveProtoActionType(
            state.NameAcb.Text?.Trim() ?? "",
            state.TypeAcb.Text?.Trim() ?? ""));
        var effectEntries = currentEntries ?? GetProtoActionOnHitEffectElements(effectiveAction)
            .Select(x => new ProtoActionOnHitEffectEntry
            {
                Element = x,
                IsSupported = IsSupportedOnHitEffectType((string?)x.Attribute("type"))
            })
            .ToList();
        if (isAutoBoostAction)
        {
            if (state.CustomValues.Remove(AutoBoostResetOnHitEffectStateKey, out var resetEffectType))
            {
                effectEntries =
                [
                    new ProtoActionOnHitEffectEntry
                    {
                        Element = new XElement("onhiteffect", new XAttribute("type", resetEffectType)),
                        IsSupported = true
                    }
                ];
            }

            var selfMode = IsAutoBoostSelfEnabled(state, effectiveAction) &&
                           !IsAutoBoostAreaEnabled(state, effectiveAction);
            if (selfMode)
            {
                effectEntries = effectEntries
                    .Where(entry =>
                    {
                        var type = ((string?)entry.Element.Attribute("type") ?? "").Trim();
                        return type.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) ||
                               type.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase);
                    })
                    .ToList();
            }

            if (effectEntries.Count == 0 && !string.IsNullOrWhiteSpace(defaultNewEffectType))
            {
                effectEntries.Add(new ProtoActionOnHitEffectEntry
                {
                    Element = new XElement("onhiteffect", new XAttribute("type", defaultNewEffectType)),
                    IsSupported = true
                });
            }
        }
        var protoOnHitEffects = GetProtoActionOnHitEffectElements(state.Model);
        var tacticsOnHitEffects = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction)
            ? GetProtoActionOnHitEffectElements(tacticsAction)
            : [];

        static XElement? FindOnHitEffectByType(IEnumerable<XElement> effects, string effectType)
            => effects.FirstOrDefault(effect => string.Equals(
                ((string?)effect.Attribute("type") ?? "").Trim(),
                effectType,
                StringComparison.OrdinalIgnoreCase));

        ProtoActionValueSource GetOnHitEffectSource(XElement currentElement)
        {
            var currentType = ((string?)currentElement.Attribute("type") ?? "").Trim();
            if (string.IsNullOrWhiteSpace(currentType))
                return ProtoActionValueSource.ProtoOnly;

            var tacticsMatch = FindOnHitEffectByType(tacticsOnHitEffects, currentType);
            if (tacticsMatch == null)
                return ProtoActionValueSource.ProtoOnly;

            if (XNode.DeepEquals(currentElement, tacticsMatch))
                return ProtoActionValueSource.TacticsInherited;

            var protoMatch = FindOnHitEffectByType(protoOnHitEffects, currentType);
            return protoMatch != null || !XNode.DeepEquals(currentElement, tacticsMatch)
                ? ProtoActionValueSource.ProtoOverride
                : ProtoActionValueSource.TacticsInherited;
        }

        if (effectEntries.Count == 0 &&
            !_isReadOnly &&
            state.IsNewCustomAction &&
            !string.IsNullOrWhiteSpace(defaultNewEffectType))
        {
            effectEntries.Add(new ProtoActionOnHitEffectEntry
            {
                Element = new XElement("onhiteffect", new XAttribute("type", defaultNewEffectType)),
                IsSupported = true
            });
        }

        state.OnHitEffectsContainer.Children.Clear();
        state.OnHitEffectRows.Clear();

        if (effectEntries.Count == 0 && _isReadOnly)
            return;

        var unitTypeSuggestions = GetKnownUnitTypeNames()
            .Concat(GetAvailableTrainUnitNames())
            .Where(x => !string.IsNullOrWhiteSpace(x))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var protoActionNameSuggestions = _currentUnitProtoActionTypeMap.Keys
            .Concat(_protoActionWidgets.Select(widget => widget.NameAcb.Text?.Trim() ?? ""))
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();
        var protoUnitSuggestions = GetAvailableTrainUnitNames();
        var animationSuggestions = GetAvailableProtoActionAnimationNames(useGlobalCatalog: true);
        var modelAttachmentBoneSuggestions = GetAvailableProtoActionModelAttachmentBones();

        state.OnHitEffectsContainer.Children.Add(new TextBlock
        {
            Text = "On Hit Effects",
            FontWeight = FontWeight.Bold,
            Margin = new Thickness(0, 6, 0, 2)
        });

        var cardsContainer = new StackPanel { Spacing = 6 };
        state.OnHitEffectsContainer.Children.Add(cardsContainer);

        async Task<bool> HandleChangedAsync()
        {
            if (_isPopulating)
                return false;

            var proceed = await CheckStartLocalMod();
            if (proceed)
                MarkDirty();
            return proceed;
        }

        void AddOnHitEffectCard(ProtoActionOnHitEffectEntry entry)
        {
            Action refreshOnHitSourceMarker = () => { };

            async Task<bool> HandleCardChangedAsync()
            {
                var proceed = await HandleChangedAsync();
                if (proceed)
                {
                    Dispatcher.UIThread.Post(
                        refreshOnHitSourceMarker,
                        DispatcherPriority.Background);
                }
                return proceed;
            }

            var element = entry.Element;
            var effectType = (string?)element.Attribute("type") ?? "";
            var isNewEffect = string.IsNullOrWhiteSpace(effectType);
            var useModeEffectTypes = newEffectTypes != null &&
                                     (isNewEffect || newEffectTypes.Contains(effectType, StringComparer.OrdinalIgnoreCase));
            var selectableEffectTypes = useModeEffectTypes ? newEffectTypeOptions : SupportedOnHitEffectTypes;
            var isSupported = entry.IsSupported &&
                              (isNewEffect || IsSupportedEffectType(effectType));

            var typeCb = new AutoCompleteBox
            {
                Text = selectableEffectTypes.FirstOrDefault(x => x.Equals(effectType, StringComparison.OrdinalIgnoreCase)) ?? effectType,
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = selectableEffectTypes,
                Width = 170,
                IsEnabled = !_isReadOnly && isSupported
            };
            EnableDropdownAutoComplete(typeCb);

            var activeCb = new CheckBox
            {
                IsChecked = IsOnHitEffectEnabledValue((string?)element.Attribute("active")),
                IsEnabled = !_isReadOnly && isSupported,
                VerticalAlignment = VerticalAlignment.Center
            };
            activeCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();

            var onHitEffectSource = GetOnHitEffectSource(element);
            var onHitSourceMarker = CreateProtoActionSourceMarker(onHitEffectSource);
            if (onHitSourceMarker != null)
            {
                ToolTip.SetTip(onHitSourceMarker,
                    onHitEffectSource == ProtoActionValueSource.TacticsInherited
                        ? "On Hit Effect inherited from tactics"
                        : "This On Hit Effect overrides the tactics effect of the same type");
            }

            var card = new OnHitEffectEditor(
                typeCb,
                activeCb,
                _isReadOnly,
                isSupported,
                onHitSourceMarker);
            var cardStack = card.Body;

            if (card.RemoveButton != null)
            {
                card.RemoveButton.Click += async (_, _) =>
                {
                    var rowToRemove = state.OnHitEffectRows.FirstOrDefault(x => ReferenceEquals(x.Card, card));
                    if (rowToRemove == null)
                        return;

                    var rowIndex = state.OnHitEffectRows.IndexOf(rowToRemove);
                    var currentEntries = CollectProtoActionOnHitEffectEntries(state);
                    var currentElement = rowIndex >= 0 && rowIndex < currentEntries.Count
                        ? currentEntries[rowIndex].Element
                        : element;
                    var currentType = ((string?)currentElement.Attribute("type") ?? "").Trim();
                    var isDefinedInTactics = !string.IsNullOrWhiteSpace(currentType) &&
                                             FindOnHitEffectByType(tacticsOnHitEffects, currentType) != null;
                    if (isDefinedInTactics)
                    {
                        await new Prompt(
                            PromptType.Error,
                            "Inherited On Hit Effect",
                            "This On Hit Effect is defined by the linked tactics file and cannot be deleted from the protoaction. You may override its values, but the tactics entry will always remain.")
                            .ShowDialog(this);
                        return;
                    }

                    var proceed = await CheckStartLocalMod();
                    if (!proceed)
                        return;

                    state.OnHitEffectRows.Remove(rowToRemove);
                    cardsContainer.Children.Remove(card);
                    MarkDirty();
                };
            }

            var targetUnitTypeAcb = new AutoCompleteBox
            {
                Text = (string?)element.Attribute("targetunittype") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = unitTypeSuggestions,
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("targetunittype") ?? "")
                    : 220,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EnableDropdownAutoComplete(targetUnitTypeAcb);
            targetUnitTypeAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var animAcb = new AutoCompleteBox
            {
                Text = (string?)element.Attribute("anim") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = animationSuggestions,
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("anim") ?? "")
                    : 180,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EnableDropdownAutoComplete(animAcb);
            FreezeActionsScrollWhileDropDownIsOpen(animAcb);
            animAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var protoActionAcb = new AutoCompleteBox
            {
                Text = (string?)element.Attribute("protoaction") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = protoActionNameSuggestions,
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("protoaction") ?? "")
                    : 200,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            ConfigureStrictSuggestionAutoComplete(
                protoActionAcb,
                protoActionNameSuggestions,
                (string?)element.Attribute("protoaction") ?? "");
            protoActionAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var attachProtoAcb = new AutoCompleteBox
            {
                Text = (string?)element.Attribute("proto") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = protoUnitSuggestions,
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("proto") ?? "")
                    : 240,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            if (effectType.Equals("Root", StringComparison.OrdinalIgnoreCase))
                ConfigureStrictSuggestionAutoComplete(attachProtoAcb, protoUnitSuggestions, (string?)element.Attribute("proto") ?? "");
            else
                EnableDropdownAutoComplete(attachProtoAcb);
            attachProtoAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var attachBoneAcb = new AutoCompleteBox
            {
                Text = (string?)element.Attribute("attachbone") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = modelAttachmentBoneSuggestions,
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("attachbone") ?? "")
                    : 180,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EnableDropdownAutoComplete(attachBoneAcb);
            attachBoneAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var durationTb = new TextBox
            {
                Text = (string?)element.Attribute("duration") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("duration") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(durationTb);
            durationTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var delayTb = new TextBox
            {
                Text = (string?)element.Attribute("delay") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("delay") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(delayTb);
            delayTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var radiusTb = new TextBox
            {
                Text = (string?)element.Attribute("radius") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("radius") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(radiusTb);
            radiusTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var stackLimitTb = new TextBox
            {
                Text = (string?)element.Attribute("stacklimit") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("stacklimit") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(stackLimitTb);
            stackLimitTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var rateTb = new TextBox
            {
                Text = (string?)element.Attribute("rate") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("rate") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(rateTb);
            rateTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var probTb = new TextBox
            {
                Text = (string?)element.Attribute("prob") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("prob") ?? "")
                    : 90
            };
            AttachProtoActionProbabilityBehavior(probTb);
            probTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var globalProbTb = new TextBox
            {
                Text = (string?)element.Attribute("globalprob") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("globalprob") ?? "")
                    : 90
            };
            AttachProtoActionProbabilityBehavior(globalProbTb);
            globalProbTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var playerRelationAcb = new AutoCompleteBox
            {
                Text = (string?)element.Attribute("playerrelation") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = new[] { "Enemy", "Ally", "Self", "Nature", "Any" },
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("playerrelation") ?? "")
                    : 120,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EnableDropdownAutoComplete(playerRelationAcb);
            playerRelationAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var rewardTypeCb = new ComboBox
            {
                ItemsSource = ProtoConstants.KnownResourceTypes,
                SelectedItem = ProtoConstants.KnownResourceTypes.FirstOrDefault(x =>
                    x.Equals((string?)element.Attribute("rewardtype") ?? "", StringComparison.OrdinalIgnoreCase)),
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("rewardtype") ?? "")
                    : 130,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            rewardTypeCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();

            var amountTb = new TextBox
            {
                Text = (string?)element.Attribute("amount") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("amount") ?? "")
                    : 90
            };
            if (effectType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase))
                AttachProtoActionProbabilityBehavior(amountTb, 1d);
            else
                AttachProtoActionDecimalBehavior(amountTb);
            amountTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var relativityCb = new ComboBox
            {
                ItemsSource = new[] { "Set", "Add", "Multiply" },
                SelectedItem = new[] { "Set", "Add", "Multiply" }.FirstOrDefault(value =>
                    value.Equals((string?)element.Attribute("relativity") ?? "Set", StringComparison.OrdinalIgnoreCase)) ?? "Set",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("relativity") ?? "")
                    : 110,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            relativityCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();

            var byUnitTypeAcb = new AutoCompleteBox
            {
                Text = GetAvailableBuildLimitTargets().FirstOrDefault(x =>
                           x.Equals((string?)element.Attribute("byunittype") ?? "", StringComparison.OrdinalIgnoreCase))
                       ?? (string?)element.Attribute("byunittype") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = GetAvailableBuildLimitTargets(),
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("byunittype") ?? "")
                    : 170,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EnableDropdownAutoComplete(byUnitTypeAcb);
            byUnitTypeAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var terrainTypeCb = new ComboBox
            {
                ItemsSource = new[] { "Land", "Water" },
                SelectedItem = new[] { "Land", "Water" }.FirstOrDefault(value =>
                    value.Equals((string?)element.Attribute("terraintype") ?? "", StringComparison.OrdinalIgnoreCase)),
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("terraintype") ?? "")
                    : 120,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            terrainTypeCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();

            var additiveCb = new CheckBox
            {
                IsChecked = IsProtoActionFlagEnabledValue((string?)element.Attribute("additive")),
                IsEnabled = !_isReadOnly && isSupported,
                VerticalAlignment = VerticalAlignment.Center
            };
            additiveCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();

            var deadOnlyCb = new CheckBox
            {
                IsChecked = IsProtoActionFlagEnabledValue((string?)element.Attribute("deadonly")),
                IsEnabled = !_isReadOnly && isSupported,
                VerticalAlignment = VerticalAlignment.Center
            };
            deadOnlyCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();

            var hideVfxCb = new CheckBox
            {
                IsChecked = IsProtoActionFlagEnabledValue((string?)element.Attribute("hidevfx")),
                IsEnabled = !_isReadOnly && isSupported,
                VerticalAlignment = VerticalAlignment.Center
            };
            hideVfxCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();

            var ignoreDeadHuntablesCb = new CheckBox
            {
                IsChecked = element.Attribute("ignoredeadhuntables") != null,
                IsEnabled = !_isReadOnly && isSupported,
                VerticalAlignment = VerticalAlignment.Center
            };
            ignoreDeadHuntablesCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();

            var stealthOnlyCb = new CheckBox
            {
                IsChecked = string.Equals((string?)element.Attribute("stealthonly"), "true", StringComparison.OrdinalIgnoreCase) ||
                            string.Equals((string?)element.Attribute("stealthonly"), "1", StringComparison.OrdinalIgnoreCase),
                IsEnabled = !_isReadOnly && isSupported,
                VerticalAlignment = VerticalAlignment.Center
            };
            stealthOnlyCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();

            var freezeTypeCb = new ComboBox
            {
                ItemsSource = KnownOnHitEffectFreezeTypeDisplayNames,
                SelectedItem = KnownOnHitEffectFreezeTypeDisplayNames.FirstOrDefault(x =>
                    x.Equals((string?)element.Attribute("freezetype") ?? "", StringComparison.OrdinalIgnoreCase)),
                IsEnabled = !_isReadOnly && isSupported,
                Width = 130
            };
            if (freezeTypeCb.SelectedItem == null && !string.IsNullOrWhiteSpace((string?)element.Attribute("freezetype")))
                freezeTypeCb.SelectedItem = KnownOnHitEffectFreezeTypeDisplayNames.FirstOrDefault(x =>
                    x.Equals((string?)element.Attribute("freezetype"), StringComparison.OrdinalIgnoreCase));
            freezeTypeCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();

            var shadingTypeAcb = new AutoCompleteBox
            {
                Text = KnownInitialShadingTypes.FirstOrDefault(x => x.Equals((string?)element.Attribute("shadingtype") ?? "", StringComparison.OrdinalIgnoreCase)) ?? (string?)element.Attribute("shadingtype") ?? "",
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = KnownInitialShadingTypes,
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("shadingtype") ?? "")
                    : 150,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EnableDropdownAutoComplete(shadingTypeAcb);
            shadingTypeAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var fadeTimeTb = new TextBox
            {
                Text = (string?)element.Attribute("fadetime") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("fadetime") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(fadeTimeTb);
            fadeTimeTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var factorTb = new TextBox
            {
                Text = (string?)element.Attribute("factor") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("factor") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(factorTb);
            factorTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var freezeDurationTb = new TextBox
            {
                Text = (string?)element.Attribute("freezeduration") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("freezeduration") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(freezeDurationTb);
            freezeDurationTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var freezeDamageTb = new TextBox
            {
                Text = (string?)element.Attribute("damage") ?? "",
                IsEnabled = !_isReadOnly && isSupported,
                Width = _isReadOnly
                    ? GetCompactReadOnlyEditorWidth((string?)element.Attribute("damage") ?? "")
                    : 90
            };
            AttachProtoActionDecimalBehavior(freezeDamageTb);
            freezeDamageTb.TextChanged += async (_, _) => await HandleCardChangedAsync();

            var rawXmlTb = new TextEditor
            {
                Text = GetCompactOnHitEffectXml(element),
                IsReadOnly = true,
                WordWrap = true,
                MinHeight = 52,
                IsVisible = !isSupported
            };
            XmlSyntaxEditorService.Configure(rawXmlTb);

            var childAttackTypes = element.Elements()
                .Where(x => x.Name.LocalName.Equals("target", StringComparison.OrdinalIgnoreCase))
                .Select(x => (string?)x.Attribute("attacktype"))
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x!.Trim())
                .ToList();
            var childIgnoreTypes = element.Elements()
                .Where(x => x.Name.LocalName.Equals("target", StringComparison.OrdinalIgnoreCase))
                .Select(x => (string?)x.Attribute("ignoretype"))
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Select(x => x!.Trim())
                .ToList();
            var targetModeCb = new ComboBox
            {
                ItemsSource = new[] { "Simple", "Multiple" },
                SelectedItem = childAttackTypes.Count > 0 || childIgnoreTypes.Count > 0 ? "Multiple" : "Simple",
                IsEnabled = !_isReadOnly && isSupported,
                Width = 110,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            var childDamageEntries = element.Elements()
                .Where(x => x.Name.LocalName.Equals("damage", StringComparison.OrdinalIgnoreCase))
                .Select(x => new
                {
                    Element = x,
                    Type = (string?)x.Attribute("type") ?? "",
                    Value = x.Value?.Trim() ?? ""
                })
                .Where(x => !string.IsNullOrWhiteSpace(x.Type) || !string.IsNullOrWhiteSpace(x.Value))
                .ToList();
            var childModifyEntries = element.Elements()
                .Where(x => x.Name.LocalName.Equals("modify", StringComparison.OrdinalIgnoreCase))
                .Select(x => new
                {
                    Element = x,
                    Type = (string?)x.Attribute("type") ?? "",
                    ApplyType = (string?)x.Attribute("applytype") ?? "",
                    DamageType = (string?)x.Attribute("dmgtype") ?? "",
                    Value = x.Value?.Trim() ?? ""
                })
                .Where(x => !string.IsNullOrWhiteSpace(x.Type) || !string.IsNullOrWhiteSpace(x.Value))
                .ToList();
            var childModifyRampEntries = element.Elements()
                .Where(x => x.Name.LocalName.Equals("modifyramp", StringComparison.OrdinalIgnoreCase))
                .Select(x => new
                {
                    Element = x,
                    Type = (string?)x.Attribute("type") ?? "",
                    DamageType = (string?)x.Attribute("dmgtype") ?? "",
                    Init = (string?)x.Attribute("init") ?? "",
                    Final = (string?)x.Attribute("final") ?? ""
                })
                .Where(x => !string.IsNullOrWhiteSpace(x.Type) || !string.IsNullOrWhiteSpace(x.DamageType) || !string.IsNullOrWhiteSpace(x.Init) || !string.IsNullOrWhiteSpace(x.Final))
                .ToList();

            var rowState = new ProtoActionOnHitEffectRowState
            {
                Card = card,
                TypeCb = typeCb,
                ActiveCb = activeCb,
                DeadOnlyCb = deadOnlyCb,
                TargetModeCb = targetModeCb,
                TargetUnitTypeAcb = targetUnitTypeAcb,
                AnimAcb = animAcb,
                ProtoActionAcb = protoActionAcb,
                AttachProtoAcb = attachProtoAcb,
                AttachBoneAcb = attachBoneAcb,
                DurationTb = durationTb,
                DelayTb = delayTb,
                RadiusTb = radiusTb,
                StackLimitTb = stackLimitTb,
                RateTb = rateTb,
                ProbTb = probTb,
                GlobalProbTb = globalProbTb,
                PlayerRelationAcb = playerRelationAcb,
                RewardTypeCb = rewardTypeCb,
                AmountTb = amountTb,
                RelativityCb = relativityCb,
                ByUnitTypeAcb = byUnitTypeAcb,
                TerrainTypeCb = terrainTypeCb,
                AdditiveCb = additiveCb,
                HideVfxCb = hideVfxCb,
                IgnoreDeadHuntablesCb = ignoreDeadHuntablesCb,
                StealthOnlyCb = stealthOnlyCb,
                ShadingTypeAcb = shadingTypeAcb,
                FadeTimeTb = fadeTimeTb,
                FactorTb = factorTb,
                FreezeDurationTb = freezeDurationTb,
                FreezeTypeCb = freezeTypeCb,
                FreezeDamageTb = freezeDamageTb,
                RawXmlTb = rawXmlTb,
                OriginalElement = new XElement(element),
                IsSupported = isSupported
            };

            refreshOnHitSourceMarker = () =>
            {
                if (onHitSourceMarker == null)
                    return;

                var rowIndex = state.OnHitEffectRows.IndexOf(rowState);
                if (rowIndex < 0)
                    return;

                var currentEntries = CollectProtoActionOnHitEffectEntries(state);
                if (rowIndex >= currentEntries.Count)
                    return;

                var source = GetOnHitEffectSource(currentEntries[rowIndex].Element);
                var inherited = source == ProtoActionValueSource.TacticsInherited;
                onHitSourceMarker.IsVisible = source != ProtoActionValueSource.ProtoOnly;
                onHitSourceMarker.Background = Brush.Parse(inherited ? "#28d7e5" : "#f59e0b");
                ToolTip.SetTip(onHitSourceMarker,
                    inherited
                        ? "On Hit Effect inherited from tactics"
                        : "This On Hit Effect overrides the tactics effect of the same type");
            };

            if (isSupported)
            {
                var currentSupportedType = effectType;
                var showDelayField = !string.IsNullOrWhiteSpace(delayTb.Text);
                var showStackLimitField = !string.IsNullOrWhiteSpace(stackLimitTb.Text);
                var showProbField = !string.IsNullOrWhiteSpace(probTb.Text);
                var showGlobalProbField = !string.IsNullOrWhiteSpace(globalProbTb.Text);
                var showSpawnTerrainField = terrainTypeCb.SelectedItem != null;
                var showSpawnDurationField = !string.IsNullOrWhiteSpace(durationTb.Text);
                var showPlayerRelationField = !string.IsNullOrWhiteSpace(playerRelationAcb.Text);
                var showFreezeShadingTypeField = !string.IsNullOrWhiteSpace(shadingTypeAcb.Text);
                var showIgnoreDeadHuntablesField = currentSupportedType.Equals("Throw", StringComparison.OrdinalIgnoreCase);

                var sharedRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    ItemHeight = double.NaN,
                    Margin = new Thickness(0, 2, 0, 0)
                };

                Control CreateOnHitLabeledControlGroup(
                    string label,
                    Control control,
                    Action? clearOptionalValue = null)
                {
                    if (control.Margin == default)
                        control.Margin = new Thickness(0);
                    var group = CreateLabeledFieldGroup(label, control);
                    if (!_isReadOnly && clearOptionalValue != null && group is Panel panel)
                    {
                        var remove = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0)
                        };
                        remove.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            clearOptionalValue();
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        panel.Children.Add(remove);
                    }
                    return group;
                }

                void AddLabeledControl(string label, Control control, Action? clearOptionalValue = null)
                {
                    sharedRow.Children.Add(CreateOnHitLabeledControlGroup(label, control, clearOptionalValue));
                }

                if (currentSupportedType.Equals("Stun", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("Flee", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("Exile", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("DamageOverTime", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("StatModify", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Snare", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("Lifesteal", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("ProgFreeze", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("ProgFreezeSpeed", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("ProgFreezeROF", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Rate:", rateTb);
                    if (currentSupportedType.Equals("Snare", StringComparison.OrdinalIgnoreCase))
                        AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Freeze", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Freeze Type:", freezeTypeCb);
                    if (showFreezeShadingTypeField)
                        AddLabeledControl("Shading Type:", shadingTypeAcb, () => shadingTypeAcb.Text = "");
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Attach", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Proto:", attachProtoAcb);
                    AddLabeledControl("Bone:", attachBoneAcb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Reincarnation", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Proto:", attachProtoAcb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Proto:", attachProtoAcb);
                }

                if (currentSupportedType.Equals("Spawn", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Proto:", attachProtoAcb);
                    AddLabeledControl("Amount:", amountTb);
                    if (showSpawnTerrainField)
                        AddLabeledControl("Terrain:", terrainTypeCb, () => terrainTypeCb.SelectedItem = null);
                    if (showSpawnDurationField)
                        AddLabeledControl("Duration:", durationTb, () => durationTb.Text = "");
                }

                if (currentSupportedType.Equals("Infect", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Infect Action:", protoActionAcb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Root", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Rate:", amountTb);
                    AddLabeledControl("Proto:", attachProtoAcb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Throw", StringComparison.OrdinalIgnoreCase))
                {
                    if (showDelayField)
                        AddLabeledControl("Delay:", delayTb);
                }

                if (currentSupportedType.Equals("Boost", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Radius:", radiusTb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Pull", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("Push", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Force:", radiusTb);
                }

                if (currentSupportedType.Equals("AnimOverride", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Animation:", animAcb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Chaos", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("Sleep", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("KillReward", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Amount:", amountTb);
                    AddLabeledControl("Resource:", rewardTypeCb);
                    AddLabeledControl("Duration:", durationTb);

                    var additiveGroup = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Margin = new Thickness(0, 0, 14, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    additiveGroup.Children.Add(new TextBlock
                    {
                        Text = "Additive:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 0, 4)
                    });
                    additiveCb.Margin = new Thickness(0);
                    additiveGroup.Children.Add(additiveCb);
                    sharedRow.Children.Add(additiveGroup);
                }

                if (currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Chance:", amountTb);
                    AddLabeledControl("Relativity:", relativityCb);
                    AddLabeledControl("By Unit Type:", byUnitTypeAcb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("ShadingFade", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Shading Type:", shadingTypeAcb);
                    AddLabeledControl("Fade Time:", fadeTimeTb);
                    AddLabeledControl("Factor:", factorTb);
                    AddLabeledControl("Duration:", durationTb);
                }

                if (currentSupportedType.Equals("Shading", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Shading Type:", shadingTypeAcb);
                    AddLabeledControl("Factor:", factorTb);
                }

                if (currentSupportedType.Equals("ProgShading", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Shading Type:", shadingTypeAcb);
                }

                if (currentSupportedType.Equals("ProgFreeze", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("ProgFreezeSpeed", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("ProgFreezeROF", StringComparison.OrdinalIgnoreCase))
                {
                    AddLabeledControl("Duration:", durationTb);
                    AddLabeledControl("Freeze Duration:", freezeDurationTb);
                }

                if (currentSupportedType.Equals("DamageOverTime", StringComparison.OrdinalIgnoreCase) && showStackLimitField)
                    AddLabeledControl("Stack:", stackLimitTb, () => stackLimitTb.Text = "");
                if (!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                    !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase) &&
                    !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                    !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                    showProbField)
                    AddLabeledControl("Probability:", probTb, () => probTb.Text = "");
                if (!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                    !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase) &&
                    !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                    !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                    showGlobalProbField)
                    AddLabeledControl("Global Probability:", globalProbTb, () => globalProbTb.Text = "");

                if (showIgnoreDeadHuntablesField)
                {
                    var ignoreDeadHuntablesGroup = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Margin = new Thickness(0, 0, 14, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    ignoreDeadHuntablesGroup.Children.Add(new TextBlock
                    {
                        Text = "Ignore Dead Huntables:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 0, 4)
                    });
                    ignoreDeadHuntablesCb.Margin = new Thickness(0);
                    ignoreDeadHuntablesGroup.Children.Add(ignoreDeadHuntablesCb);
                    sharedRow.Children.Add(ignoreDeadHuntablesGroup);
                }

                // Keep Dead Only visible only for effects that already define it in XML.
                // New effects intentionally do not offer this legacy/manual-only option.
                var hasExistingDeadOnly = element.Attribute("deadonly") != null;
                var deadOnlyGroup = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 8,
                    Margin = new Thickness(0, 0, 14, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                deadOnlyGroup.Children.Add(new TextBlock
                {
                    Text = "Dead Only:",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 0, 4)
                });
                deadOnlyCb.Margin = new Thickness(0);
                deadOnlyGroup.Children.Add(deadOnlyCb);
                if (hasExistingDeadOnly)
                    sharedRow.Children.Add(deadOnlyGroup);

                void InsertOptionalLabeledControl(
                    string label,
                    Control control,
                    Action clearOptionalValue,
                    Control? beforeControl = null)
                {
                    var insertIndex = beforeControl == null ? -1 : sharedRow.Children.IndexOf(beforeControl);
                    if (insertIndex < 0)
                        insertIndex = sharedRow.Children.IndexOf(deadOnlyGroup);
                    if (insertIndex < 0)
                        insertIndex = sharedRow.Children.Count;
                    sharedRow.Children.Insert(
                        insertIndex,
                        CreateOnHitLabeledControlGroup(label, control, clearOptionalValue));
                }

                if (currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase))
                {
                    var stealthOnlyGroup = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Spacing = 8,
                        Margin = new Thickness(0, 0, 14, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    stealthOnlyGroup.Children.Add(new TextBlock
                    {
                        Text = "Stealth Only:",
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 8, 4)
                    });
                    stealthOnlyCb.Margin = new Thickness(0);
                    stealthOnlyGroup.Children.Add(stealthOnlyCb);
                    sharedRow.Children.Add(stealthOnlyGroup);
                }

                if (currentSupportedType.Equals("DamageOverTime", StringComparison.OrdinalIgnoreCase) &&
                    !showStackLimitField && !_isReadOnly)
                {
                    var addStackButton = new Button
                    {
                        Content = "Stack",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 0, 8, 0)
                    };
                    addStackButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;
                        var buttonIndex = sharedRow.Children.IndexOf(addStackButton);
                        sharedRow.Children.Remove(addStackButton);
                        stackLimitTb.Text = "0";
                        sharedRow.Children.Insert(
                            Math.Max(0, buttonIndex),
                            CreateOnHitLabeledControlGroup("Stack:", stackLimitTb, () => stackLimitTb.Text = ""));
                        MarkDirty();
                    };
                    sharedRow.Children.Insert(Math.Min(1, sharedRow.Children.Count), addStackButton);
                }

                var deferPrimaryRowsUntilAfterDamage = currentSupportedType.Equals("DamageOverTime", StringComparison.OrdinalIgnoreCase);
                Control? deferredOnHitOptionalRow = null;
                if (!deferPrimaryRowsUntilAfterDamage)
                    cardStack.Children.Add(sharedRow);

                var needsOptionalRow = !_isReadOnly &&
                                       ((!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("Spawn", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase)) ||
                                        showDelayField == false ||
                                        showStackLimitField == false ||
                                        (currentSupportedType.Equals("Stun", StringComparison.OrdinalIgnoreCase) && showPlayerRelationField == false) ||
                                        (currentSupportedType.Equals("Freeze", StringComparison.OrdinalIgnoreCase) && showFreezeShadingTypeField == false) ||
                                        (!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("Spawn", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase) &&
                                         showProbField == false) ||
                                        (!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("Spawn", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                                         !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase) &&
                                         showGlobalProbField == false));
                if (needsOptionalRow)
                {
                    var optionalRow = new WrapPanel
                    {
                        Orientation = Orientation.Horizontal,
                        ItemHeight = double.NaN,
                        Margin = new Thickness(0, 2, 0, 0)
                    };

                    if (currentSupportedType.Equals("Spawn", StringComparison.OrdinalIgnoreCase) && !showSpawnTerrainField)
                    {
                        var addTerrainButton = new Button
                        {
                            Content = "Terrain",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        addTerrainButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            optionalRow.Children.Remove(addTerrainButton);
                            InsertOptionalLabeledControl("Terrain:", terrainTypeCb, () => terrainTypeCb.SelectedItem = null);
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addTerrainButton);
                    }

                    if (currentSupportedType.Equals("Spawn", StringComparison.OrdinalIgnoreCase) && !showSpawnDurationField)
                    {
                        var addDurationButton = new Button
                        {
                            Content = "Duration",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        addDurationButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            optionalRow.Children.Remove(addDurationButton);
                            InsertOptionalLabeledControl("Duration:", durationTb, () => durationTb.Text = "");
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addDurationButton);
                    }

                    if (currentSupportedType.Equals("Stun", StringComparison.OrdinalIgnoreCase) && !showPlayerRelationField)
                    {
                        var addPlayerRelationButton = new Button
                        {
                            Content = "Player Relation",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        addPlayerRelationButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            optionalRow.Children.Remove(addPlayerRelationButton);
                            InsertOptionalLabeledControl("Player Relation:", playerRelationAcb, () => playerRelationAcb.Text = "");
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addPlayerRelationButton);
                    }

                    if (currentSupportedType.Equals("Freeze", StringComparison.OrdinalIgnoreCase) && !showFreezeShadingTypeField)
                    {
                        var addShadingTypeButton = new Button
                        {
                            Content = "Shading Type",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        addShadingTypeButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            optionalRow.Children.Remove(addShadingTypeButton);
                            shadingTypeAcb.Text = KnownInitialShadingTypes.FirstOrDefault() ?? "Default";
                            RefreshProtoActionMetadataPanels(state);
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addShadingTypeButton);
                    }

                    if (currentSupportedType.Equals("Throw", StringComparison.OrdinalIgnoreCase) && !showDelayField)
                    {
                        var addDelayButton = new Button
                        {
                            Content = "Delay",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        addDelayButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            optionalRow.Children.Remove(addDelayButton);
                            InsertOptionalLabeledControl("Delay:", delayTb, () => delayTb.Text = "");
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addDelayButton);
                    }

                    if (!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                        !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                        !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                        !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase) &&
                        !showProbField)
                    {
                        var addProbButton = new Button
                        {
                            Content = "Probability",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left,
                            Margin = new Thickness(0, 0, 8, 0)
                        };
                        addProbButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            optionalRow.Children.Remove(addProbButton);
                            probTb.Text = "0";
                            InsertOptionalLabeledControl("Probability:", probTb, () => probTb.Text = "");
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addProbButton);
                    }

                    if (!currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) &&
                        !currentSupportedType.Equals("InstantKillablePercentChance", StringComparison.OrdinalIgnoreCase) &&
                        !currentSupportedType.Equals("MutateNature", StringComparison.OrdinalIgnoreCase) &&
                        !currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase) &&
                        !showGlobalProbField)
                    {
                        var addGlobalProbButton = new Button
                        {
                            Content = "Global Probability",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addGlobalProbButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            optionalRow.Children.Remove(addGlobalProbButton);
                            globalProbTb.Text = "0";
                            InsertOptionalLabeledControl("Global Probability:", globalProbTb, () => globalProbTb.Text = "");
                            MarkDirty();
                        };
                        optionalRow.Children.Add(addGlobalProbButton);
                    }

                    if (optionalRow.Children.Count > 0)
                    {
                        if (deferPrimaryRowsUntilAfterDamage)
                            deferredOnHitOptionalRow = optionalRow;
                        else
                            cardStack.Children.Add(optionalRow);
                    }
                }

                var supportsTargetModes = true;

                StackPanel? deferredTargetFiltersSection = null;

                if (supportsTargetModes)
                {
                    var targetFilterEditors = new Grid
                    {
                        ColumnDefinitions = new ColumnDefinitions("Auto,Auto"),
                        ColumnSpacing = 18,
                        HorizontalAlignment = HorizontalAlignment.Left
                    };

                    Control CreateTargetFilterChipEditor(
                        string title,
                        IEnumerable<string> initialValues,
                        List<AutoCompleteBox> storedValues)
                    {
                        var host = new StackPanel { Spacing = 2, Width = 330 };
                        var pickerRow = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 8,
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        pickerRow.Children.Add(new TextBlock
                        {
                            Text = title + ":",
                            VerticalAlignment = VerticalAlignment.Center
                        });
                        var picker = new AutoCompleteBox
                        {
                            FilterMode = AutoCompleteFilterMode.Contains,
                            IsEnabled = !_isReadOnly && isSupported,
                            Width = 200,
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        EnableDropdownAutoComplete(picker);
                        pickerRow.Children.Add(picker);
                        if (!_isReadOnly)
                            host.Children.Add(pickerRow);

                        var chips = new WrapPanel { Orientation = Orientation.Horizontal };
                        host.Children.Add(chips);

                        void RefreshPickerSuggestions()
                        {
                            var selected = storedValues
                                .Select(value => value.Text?.Trim() ?? "")
                                .Where(value => !string.IsNullOrWhiteSpace(value))
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                            picker.ItemsSource = unitTypeSuggestions.Where(value => !selected.Contains(value)).ToList();
                        }

                        void AddChipValue(string value)
                        {
                            var normalized = value.Trim();
                            if (string.IsNullOrWhiteSpace(normalized) ||
                                storedValues.Any(existing => (existing.Text?.Trim() ?? "").Equals(normalized, StringComparison.OrdinalIgnoreCase)))
                                return;

                            var storedValue = new AutoCompleteBox { Text = normalized };
                            storedValues.Add(storedValue);
                            chips.Children.Add(CreateChip(normalized, async () =>
                            {
                                if (!await HandleCardChangedAsync())
                                    return;
                                storedValues.Remove(storedValue);
                                RefreshPickerSuggestions();
                                RefreshProtoActionMetadataPanels(state);
                                CommitChipAdditionAndRefreshXmlPreview();
                            }));
                            RefreshPickerSuggestions();
                        }

                        async Task CommitPickerAsync()
                        {
                            var value = picker.SelectedItem as string ?? picker.Text?.Trim() ?? "";
                            if (string.IsNullOrWhiteSpace(value) || !await HandleCardChangedAsync())
                                return;
                            AddChipValue(value);
                            picker.SelectedItem = null;
                            picker.Text = "";
                            MarkDirty();
                            CommitChipAdditionAndRefreshXmlPreview();
                        }

                        picker.SelectionChanged += (_, _) =>
                        {
                            if (!_isPopulating && picker.SelectedItem != null)
                                Dispatcher.UIThread.Post(async () => await CommitPickerAsync(), DispatcherPriority.Background);
                        };
                        picker.KeyDown += async (_, e) =>
                        {
                            if (e.Key != Key.Enter)
                                return;
                            e.Handled = true;
                            await CommitPickerAsync();
                        };

                        foreach (var value in initialValues)
                            AddChipValue(value);
                        RefreshPickerSuggestions();
                        return host;
                    }

                    var attackTypeEditor = CreateTargetFilterChipEditor("Attack Type", childAttackTypes, rowState.ChildAttackTypeAcbs);
                    targetFilterEditors.Children.Add(attackTypeEditor);
                    var ignoreTypeEditor = CreateTargetFilterChipEditor("Ignore Type", childIgnoreTypes, rowState.ChildIgnoreTypeAcbs);
                    Grid.SetColumn(ignoreTypeEditor, 1);
                    targetFilterEditors.Children.Add(ignoreTypeEditor);
                    var targetFiltersSection = new TargetFilterEditor(
                        targetModeCb,
                        targetUnitTypeAcb,
                        targetFilterEditors);

                    targetModeCb.SelectionChanged += async (_, _) =>
                    {
                        if (_isPopulating)
                            return;
                        if (!await HandleCardChangedAsync())
                            return;
                        targetFiltersSection.RefreshModeVisibility();
                        MarkDirty();
                        CommitChipAdditionAndRefreshXmlPreview();
                    };
                    targetFiltersSection.RefreshModeVisibility();

                    var targetsSelf = currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase) ||
                                      currentSupportedType.Equals("SelfStealth", StringComparison.OrdinalIgnoreCase);
                    var addTargetFiltersSection = !targetsSelf &&
                                                  (!_isReadOnly ||
                                                   !string.IsNullOrWhiteSpace(targetUnitTypeAcb.Text) ||
                                                   rowState.ChildAttackTypeAcbs.Count > 0 ||
                                                   rowState.ChildIgnoreTypeAcbs.Count > 0);

                    if (addTargetFiltersSection)
                    {
                        if (currentSupportedType.Equals("DamageOverTime", StringComparison.OrdinalIgnoreCase))
                            deferredTargetFiltersSection = targetFiltersSection;
                        else
                            cardStack.Children.Add(targetFiltersSection);
                    }
                }

                if (currentSupportedType.Equals("DamageOverTime", StringComparison.OrdinalIgnoreCase))
                {
                    var damageSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 0) };
                    damageSection.Children.Add(new TextBlock
                    {
                        Text = "Damage",
                        FontWeight = FontWeight.Bold
                    });

                    var damageRowsHost = new WrapPanel { Orientation = Orientation.Horizontal };
                    damageSection.Children.Add(damageRowsHost);

                    var damageTypeLabel = new TextBlock
                    {
                        Text = "Type:",
                        Margin = new Thickness(0, 4, 8, 4),
                        VerticalAlignment = VerticalAlignment.Center,
                        IsVisible = false
                    };
                    damageRowsHost.Children.Add(damageTypeLabel);

                    Button? addDamageButton = null;
                    var isRefreshingDamageTypes = false;

                    void RefreshDamageTypeOptions()
                    {
                        if (isRefreshingDamageTypes)
                            return;
                        isRefreshingDamageTypes = true;
                        foreach (var row in rowState.DamageRows)
                        {
                            var currentType = row.DamageTypeCb.SelectedItem?.ToString() ?? "";
                            var usedByOtherRows = rowState.DamageRows
                                .Where(other => !ReferenceEquals(other, row))
                                .Select(other => other.DamageTypeCb.SelectedItem?.ToString() ?? "")
                                .Where(type => !string.IsNullOrWhiteSpace(type))
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                            var availableTypes = ProtoConstants.KnownDamageTypes
                                .Where(type => type.Equals(currentType, StringComparison.OrdinalIgnoreCase) || !usedByOtherRows.Contains(type))
                                .ToList();
                            row.DamageTypeCb.ItemsSource = availableTypes;
                            row.DamageTypeCb.SelectedItem = availableTypes.FirstOrDefault(type =>
                                type.Equals(currentType, StringComparison.OrdinalIgnoreCase));
                        }
                        isRefreshingDamageTypes = false;
                    }

                    void EnsureAddDamageButton()
                    {
                        damageTypeLabel.IsVisible = rowState.DamageRows.Count > 0;
                        if (_isReadOnly)
                            return;
                        if (rowState.DamageRows.Count >= ProtoConstants.KnownDamageTypes.Length)
                        {
                            if (addDamageButton != null)
                                damageRowsHost.Children.Remove(addDamageButton);
                            return;
                        }
                        addDamageButton ??= new Button
                        {
                            Content = "Add Damage",
                            Classes = { "add-component" },
                            Margin = new Thickness(2, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        damageRowsHost.Children.Remove(addDamageButton);
                        damageRowsHost.Children.Add(addDamageButton);
                    }

                    void AddDamageRow(XElement? originalElement = null, string initialType = "", string initialValue = "")
                    {
                        var rowPanel = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 4,
                            Margin = new Thickness(0, 0, 8, 0)
                        };

                        var damageTypeCb = new ComboBox
                        {
                            ItemsSource = ProtoConstants.KnownDamageTypes,
                            SelectedItem = ProtoConstants.KnownDamageTypes.FirstOrDefault(type =>
                                type.Equals(initialType, StringComparison.OrdinalIgnoreCase)),
                            IsEnabled = !_isReadOnly && isSupported,
                            Width = 110
                        };
                        rowPanel.Children.Add(damageTypeCb);

                        var valueTb = new TextBox
                        {
                            Text = initialValue,
                            IsEnabled = !_isReadOnly && isSupported,
                            Width = _isReadOnly
                                ? GetCompactReadOnlyEditorWidth(initialValue)
                                : 70
                        };
                        AttachProtoActionDecimalBehavior(valueTb);
                        valueTb.TextChanged += async (_, _) => await HandleCardChangedAsync();
                        rowPanel.Children.Add(valueTb);

                        var damageRowState = new OnHitEffectDamageRowState
                        {
                            RowPanel = rowPanel,
                            DamageTypeCb = damageTypeCb,
                            ValueTb = valueTb,
                            OriginalElement = originalElement != null ? new XElement(originalElement) : new XElement("damage")
                        };
                        rowState.DamageRows.Add(damageRowState);
                        damageTypeCb.SelectionChanged += async (_, _) =>
                        {
                            if (isRefreshingDamageTypes)
                                return;
                            if (await HandleCardChangedAsync())
                            {
                                RefreshDamageTypeOptions();
                                CommitChipAdditionAndRefreshXmlPreview();
                            }
                        };

                        if (!_isReadOnly)
                        {
                            var removeDamageButton = new Button
                            {
                                Classes = { "remove-button" } };
                            removeDamageButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                rowState.DamageRows.Remove(damageRowState);
                                damageRowsHost.Children.Remove(rowPanel);
                                RefreshDamageTypeOptions();
                                EnsureAddDamageButton();
                                MarkDirty();
                                CommitChipAdditionAndRefreshXmlPreview();
                            };
                            rowPanel.Children.Add(removeDamageButton);
                        }

                        damageRowsHost.Children.Add(rowPanel);
                        RefreshDamageTypeOptions();
                        EnsureAddDamageButton();
                    }

                    foreach (var damageEntry in childDamageEntries)
                        AddDamageRow(damageEntry.Element, damageEntry.Type, damageEntry.Value);

                    if (!_isReadOnly)
                    {
                        EnsureAddDamageButton();
                        addDamageButton!.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            var usedTypes = rowState.DamageRows
                                .Select(row => row.DamageTypeCb.SelectedItem?.ToString() ?? "")
                                .Where(type => !string.IsNullOrWhiteSpace(type))
                                .ToHashSet(StringComparer.OrdinalIgnoreCase);
                            var nextType = ProtoConstants.KnownDamageTypes.FirstOrDefault(type => !usedTypes.Contains(type));
                            if (string.IsNullOrWhiteSpace(nextType))
                                return;
                            AddDamageRow(initialType: nextType, initialValue: "0");
                            MarkDirty();
                            CommitChipAdditionAndRefreshXmlPreview();
                        };
                    }

                    if (_isReadOnly)
                    {
                        if (rowState.DamageRows.Count > 0)
                            cardStack.Children.Add(damageSection);
                    }
                    else
                    {
                        cardStack.Children.Add(damageSection);
                    }

                    cardStack.Children.Add(sharedRow);
                    if (deferredOnHitOptionalRow != null)
                        cardStack.Children.Add(deferredOnHitOptionalRow);

                    if (deferredTargetFiltersSection != null)
                        cardStack.Children.Add(deferredTargetFiltersSection);
                }

                if (currentSupportedType.Equals("StatModify", StringComparison.OrdinalIgnoreCase) ||
                    currentSupportedType.Equals("SelfModify", StringComparison.OrdinalIgnoreCase))
                {
                    var modifyTypeSuggestions = ProtoConstants.KnownModifyTypes
                        .Select(ProtoConstants.GetModifyTypeDisplayName)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    var modifySection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 0) };
                    modifySection.Children.Add(new TextBlock
                    {
                        Text = "Modifiers",
                        FontWeight = FontWeight.Bold
                    });

                    var modifyRowsHost = new StackPanel { Spacing = 4 };
                    modifySection.Children.Add(modifyRowsHost);

                    void AddModifyRow(XElement? originalElement = null, string initialType = "", string initialApplyType = "", string initialDamageType = "", string initialValue = "", bool initialStack = false)
                    {
                        var rowGrid = new Grid
                        {
                            ColumnDefinitions = !_isReadOnly
                                ? new ColumnDefinitions("Auto, 180, 100, Auto, 90, Auto, 100, Auto, Auto, 32")
                                : new ColumnDefinitions("Auto, 180, 100, Auto, 90, Auto, 100, Auto, Auto"),
                            Margin = new Thickness(0, 2, 0, 2),
                            HorizontalAlignment = HorizontalAlignment.Stretch
                        };

                        rowGrid.Children.Add(new TextBlock
                        {
                            Text = "Modify:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 6, 4)
                        });

                        var modifyTypeAcb = new AutoCompleteBox
                        {
                            Text = ProtoConstants.GetModifyTypeDisplayName(initialType),
                            FilterMode = AutoCompleteFilterMode.Contains,
                            ItemsSource = modifyTypeSuggestions,
                            IsEnabled = !_isReadOnly
                        };
                        EnableDropdownAutoComplete(modifyTypeAcb);
                        modifyTypeAcb.TextChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(modifyTypeAcb, 1);
                        rowGrid.Children.Add(modifyTypeAcb);

                        var applyTypeCb = new ComboBox
                        {
                            ItemsSource = new[] { "Multiply", "Add", "Set" },
                            SelectedItem = string.IsNullOrWhiteSpace(initialApplyType)
                                ? "Multiply"
                                : new[] { "Multiply", "Add", "Set" }.FirstOrDefault(x => x.Equals(initialApplyType, StringComparison.OrdinalIgnoreCase)) ?? "Multiply",
                            IsEnabled = !_isReadOnly,
                            Width = 100,
                            Margin = new Thickness(8, 0, 0, 0)
                        };
                        applyTypeCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(applyTypeCb, 2);
                        rowGrid.Children.Add(applyTypeCb);

                        var damageTypeLabel = new TextBlock
                        {
                            Text = "Damage Type:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(8, 4, 6, 4)
                        };
                        Grid.SetColumn(damageTypeLabel, 3);
                        rowGrid.Children.Add(damageTypeLabel);

                        var damageTypeCb = new ComboBox
                        {
                            IsEnabled = !_isReadOnly,
                            Width = 90
                        };
                        RefreshProtoActionDamageTypeCombo(damageTypeCb, initialType, initialDamageType);
                        damageTypeCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(damageTypeCb, 4);
                        rowGrid.Children.Add(damageTypeCb);

                        var valueLabel = new TextBlock
                        {
                            Text = "Value:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(8, 4, 6, 4)
                        };
                        Grid.SetColumn(valueLabel, 5);
                        rowGrid.Children.Add(valueLabel);

                        var valueTb = new TextBox
                        {
                            Text = initialValue,
                            IsEnabled = !_isReadOnly
                        };
                        AttachProtoActionDecimalBehavior(valueTb);
                        valueTb.TextChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(valueTb, 6);
                        rowGrid.Children.Add(valueTb);

                        TextBlock? stackLabel = null;
                        CheckBox? stackCb = null;
                        if (currentSupportedType.Equals("StatModify", StringComparison.OrdinalIgnoreCase))
                        {
                            stackLabel = new TextBlock
                            {
                                Text = "Stack:",
                                VerticalAlignment = VerticalAlignment.Center,
                                Margin = new Thickness(8, 4, 6, 4)
                            };
                            Grid.SetColumn(stackLabel, 7);
                            rowGrid.Children.Add(stackLabel);

                            stackCb = new CheckBox
                            {
                                IsChecked = initialStack,
                                IsEnabled = !_isReadOnly,
                                VerticalAlignment = VerticalAlignment.Center
                            };
                            stackCb.IsCheckedChanged += async (_, _) => await HandleCardChangedAsync();
                            Grid.SetColumn(stackCb, 8);
                            rowGrid.Children.Add(stackCb);
                        }

                        void RefreshDamageTypeVisibility()
                        {
                            var visible = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "") is "DamageSpecific" or "ArmorSpecific";
                            damageTypeLabel.IsVisible = visible;
                            damageTypeCb.IsVisible = visible;
                            rowGrid.ColumnDefinitions[3].Width = visible ? GridLength.Auto : new GridLength(0);
                            rowGrid.ColumnDefinitions[4].Width = visible ? new GridLength(90) : new GridLength(0);
                            if (!visible)
                                damageTypeCb.SelectedItem = null;
                            else
                                RefreshProtoActionDamageTypeCombo(damageTypeCb, modifyTypeAcb.Text, damageTypeCb.SelectedItem?.ToString() ?? initialDamageType);
                        }

                        modifyTypeAcb.TextChanged += (_, _) => RefreshDamageTypeVisibility();
                        RefreshDamageTypeVisibility();

                        var modifyRowState = new OnHitEffectModifyRowState
                        {
                            RowPanel = rowGrid,
                            ModifyTypeAcb = modifyTypeAcb,
                            ApplyTypeCb = applyTypeCb,
                            DamageTypeCb = damageTypeCb,
                            DamageTypeLabel = damageTypeLabel,
                            ValueTb = valueTb,
                            StackCb = stackCb ?? new CheckBox { IsChecked = false, IsVisible = false },
                            OriginalElement = originalElement != null ? new XElement(originalElement) : new XElement("modify")
                        };
                        rowState.ModifyRows.Add(modifyRowState);

                        if (!_isReadOnly)
                        {
                            var removeModifyButton = new Button
                            {
                                Classes = { "remove-button" } };
                            removeModifyButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                rowState.ModifyRows.Remove(modifyRowState);
                                modifyRowsHost.Children.Remove(rowGrid);
                                MarkDirty();
                            };
                            Grid.SetColumn(removeModifyButton, currentSupportedType.Equals("StatModify", StringComparison.OrdinalIgnoreCase) ? 9 : 7);
                            rowGrid.Children.Add(removeModifyButton);
                        }

                        modifyRowsHost.Children.Add(rowGrid);
                    }

                    foreach (var modifyEntry in childModifyEntries)
                        AddModifyRow(modifyEntry.Element, modifyEntry.Type, modifyEntry.ApplyType, modifyEntry.DamageType, modifyEntry.Value, modifyEntry.Element.Attribute("stack") != null);

                    if (!_isReadOnly)
                    {
                        var addModifyButton = new Button
                        {
                            Content = "Modifier",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addModifyButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            AddModifyRow(initialType: "Speed", initialValue: "1.0");
                            MarkDirty();
                        };
                        modifySection.Children.Add(addModifyButton);
                    }

                    if (_isReadOnly)
                    {
                        if (rowState.ModifyRows.Count > 0)
                            cardStack.Children.Add(modifySection);
                    }
                    else
                    {
                        cardStack.Children.Add(modifySection);
                    }

                    var modifyRampSection = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 0) };
                    modifyRampSection.Children.Add(new TextBlock
                    {
                        Text = "Modifier Ramps",
                        FontWeight = FontWeight.Bold
                    });

                    var modifyRampRowsHost = new StackPanel { Spacing = 4 };
                    modifyRampSection.Children.Add(modifyRampRowsHost);

                    void AddModifyRampRowForModifyEffects(XElement? originalElement = null, string initialType = "", string initialDamageType = "", string initialInit = "", string initialFinal = "")
                    {
                        var rowGrid = new Grid
                        {
                            ColumnDefinitions = !_isReadOnly
                                ? new ColumnDefinitions("Auto, 170, Auto, 90, Auto, 100, Auto, 100, 32")
                                : new ColumnDefinitions("Auto, 170, Auto, 90, Auto, 100, Auto, 100"),
