                        void UpdateDamageTypeVisibility()
                        {
                            var currentType = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "");
                            var showDamageType = currentType is "DamageSpecific" or "ArmorSpecific";
