                            Margin = new Thickness(8, 4, 6, 4)
                        };
                        Grid.SetColumn(damageTypeLabel, 2);
                        rowGrid.Children.Add(damageTypeLabel);

                        var damageTypeCb = new ComboBox
                        {
                            IsEnabled = !_isReadOnly,
                            Width = 90
                        };
                        RefreshProtoActionDamageTypeCombo(damageTypeCb, initialType, initialDamageType);
                        damageTypeCb.SelectionChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(damageTypeCb, 3);
                        rowGrid.Children.Add(damageTypeCb);

                        var initLabel = new TextBlock
                        {
                            Text = "Init Value:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(8, 4, 6, 4)
                        };
                        Grid.SetColumn(initLabel, 4);
                        rowGrid.Children.Add(initLabel);

                        var initTb = new TextBox
                        {
                            Text = initialInit,
                            IsEnabled = !_isReadOnly,
                            Width = _isReadOnly ? GetCompactReadOnlyEditorWidth(initialInit) : 100
                        };
                        AttachProtoActionDecimalBehavior(initTb);
                        initTb.TextChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(initTb, 5);
                        rowGrid.Children.Add(initTb);

                        var finalLabel = new TextBlock
                        {
                            Text = "Final Value:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(8, 4, 6, 4)
                        };
                        Grid.SetColumn(finalLabel, 6);
                        rowGrid.Children.Add(finalLabel);

                        var finalTb = new TextBox
                        {
                            Text = initialFinal,
                            IsEnabled = !_isReadOnly,
                            Width = _isReadOnly ? GetCompactReadOnlyEditorWidth(initialFinal) : 100
                        };
                        AttachProtoActionDecimalBehavior(finalTb);
                        finalTb.TextChanged += async (_, _) => await HandleCardChangedAsync();
                        Grid.SetColumn(finalTb, 7);
                        rowGrid.Children.Add(finalTb);

                        void RefreshDamageTypeVisibility()
                        {
                            var visible = ProtoConstants.GetModifyTypeValue(modifyTypeAcb.Text?.Trim() ?? "") is "DamageSpecific" or "ArmorSpecific";
                            damageTypeLabel.IsVisible = visible;
                            damageTypeCb.IsVisible = visible;
                            rowGrid.ColumnDefinitions[2].Width = visible ? GridLength.Auto : new GridLength(0);
                            rowGrid.ColumnDefinitions[3].Width = visible ? new GridLength(90) : new GridLength(0);
                            if (!visible)
                                damageTypeCb.SelectedItem = null;
                            else
                                RefreshProtoActionDamageTypeCombo(damageTypeCb, modifyTypeAcb.Text, damageTypeCb.SelectedItem?.ToString() ?? initialDamageType);
                        }

                        modifyTypeAcb.TextChanged += (_, _) => RefreshDamageTypeVisibility();
                        RefreshDamageTypeVisibility();

                        var modifyRampRowState = new OnHitEffectModifyRampRowState
                        {
                            RowPanel = rowGrid,
                            ModifyTypeAcb = modifyTypeAcb,
                            DamageTypeCb = damageTypeCb,
                            DamageTypeLabel = damageTypeLabel,
                            InitTb = initTb,
                            FinalTb = finalTb,
                            OriginalElement = originalElement != null ? new XElement(originalElement) : new XElement("modifyramp")
                        };
                        rowState.ModifyRampRows.Add(modifyRampRowState);

                        if (!_isReadOnly)
                        {
                            var removeButton = new Button
                            {
                                Classes = { "remove-button" } };
                            removeButton.Click += async (_, _) =>
                            {
                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                rowState.ModifyRampRows.Remove(modifyRampRowState);
                                modifyRampRowsHost.Children.Remove(rowGrid);
                                MarkDirty();
                            };
                            Grid.SetColumn(removeButton, 8);
                            rowGrid.Children.Add(removeButton);
                        }

                        modifyRampRowsHost.Children.Add(rowGrid);
                    }

                    foreach (var modifyRampEntry in childModifyRampEntries)
                        AddModifyRampRow(modifyRampEntry.Element, modifyRampEntry.Type, modifyRampEntry.DamageType, modifyRampEntry.Init, modifyRampEntry.Final);

                    if (!_isReadOnly)
                    {
                        var addModifyRampButton = new Button
                        {
                            Content = "Modifier Ramp",
                            Classes = { "add-component" },
                            HorizontalAlignment = HorizontalAlignment.Left
                        };
                        addModifyRampButton.Click += async (_, _) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            AddModifyRampRow();
                            MarkDirty();
                        };
                        modifyRampSection.Children.Add(addModifyRampButton);
                    }

                    if (!_isReadOnly || rowState.ModifyRampRows.Count > 0)
                        cardStack.Children.Add(modifyRampSection);
                }

                if (currentSupportedType.Equals("Stun", StringComparison.OrdinalIgnoreCase))
                {
                    var deadOnlyIndex = sharedRow.Children.IndexOf(deadOnlyGroup);
                    if (deadOnlyIndex >= 0)
                    {
                        var hideVfxGroup = new StackPanel
                        {
                            Orientation = Orientation.Horizontal,
                            Spacing = 8,
                            Margin = new Thickness(0, 0, 14, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        hideVfxGroup.Children.Add(new TextBlock
                        {
                            Text = "Hide VFX:",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(0, 4, 0, 4)
                        });
                        hideVfxCb.Margin = new Thickness(0);
                        hideVfxGroup.Children.Add(hideVfxCb);
                        sharedRow.Children.Insert(deadOnlyIndex + 1, hideVfxGroup);

                        if (showPlayerRelationField)
                        {
                            var playerRelationGroup = new StackPanel
                            {
                                Orientation = Orientation.Horizontal,
                                Spacing = 8,
                                Margin = new Thickness(0, 0, 14, 0),
                                VerticalAlignment = VerticalAlignment.Center
                            };
                            playerRelationGroup.Children.Add(new TextBlock
                            {
                                Text = "Player Relation:",
                                VerticalAlignment = VerticalAlignment.Center,
                                Margin = new Thickness(0, 4, 0, 4)
                            });
                            playerRelationAcb.Margin = new Thickness(0);
                            playerRelationGroup.Children.Add(playerRelationAcb);
                            sharedRow.Children.Insert(deadOnlyIndex + 2, playerRelationGroup);
                        }
                    }
                }
                else if (currentSupportedType.Equals("Freeze", StringComparison.OrdinalIgnoreCase))
                {
                    var freezeRow = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 0) };
                    var showDamage = !string.IsNullOrWhiteSpace(freezeDamageTb.Text) ||
                                     string.Equals(freezeTypeCb.SelectedItem as string ?? freezeTypeCb.SelectedValue?.ToString() ?? "",
                                         "StoneDamage", StringComparison.OrdinalIgnoreCase);
                    if (showDamage)
                        freezeRow.Children.Add(CreateOnHitLabeledControlGroup("Damage:", freezeDamageTb));
                    if (freezeRow.Children.Count > 0)
                        cardStack.Children.Add(freezeRow);
                }
            }
            else
            {
                cardStack.Children.Add(rawXmlTb);
            }

            typeCb.TextChanged += async (_, _) =>
            {
                if (_isPopulating || !isSupported)
                    return;

                var selectedType = typeCb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(selectedType) ||
                    !selectableEffectTypes.Contains(selectedType, StringComparer.OrdinalIgnoreCase))
                    return;
                if (selectedType.Equals(effectType, StringComparison.OrdinalIgnoreCase))
                    return;

                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                if (effectType.Equals("Throw", StringComparison.OrdinalIgnoreCase) &&
                    !selectedType.Equals("Throw", StringComparison.OrdinalIgnoreCase))
                {
                    var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
                    var hasAnotherThrowEffect = state.OnHitEffectRows.Any(row =>
                        !ReferenceEquals(row.TypeCb, typeCb) &&
                        row.TypeCb.Text?.Trim().Equals("Throw", StringComparison.OrdinalIgnoreCase) == true);
                    if (!hasAnotherThrowEffect && (IsAttackActionType(actionType) || IsLinearAreaAttackActionType(actionType)))
                        ClearProtoActionThrowConfiguration(state);
                }

                var currentRows = CollectProtoActionOnHitEffectEntries(state);
                var currentRowIndex = state.OnHitEffectRows.IndexOf(rowState);
                if (currentRowIndex >= 0 && currentRowIndex < currentRows.Count)
                {
                    var replacement = CreateOnHitEffectTypeReplacement(selectedType, activeCb.IsChecked == true);
                    currentRows[currentRowIndex] = new ProtoActionOnHitEffectEntry
                    {
                        Element = replacement,
                        IsSupported = true
                    };
                }

                MarkDirty();
                RenderProtoActionOnHitEffects(state, currentRows, newEffectTypes, defaultNewEffectType);
            };

            state.OnHitEffectRows.Add(rowState);
            cardsContainer.Children.Add(card);
        }

        foreach (var entry in effectEntries)
            AddOnHitEffectCard(entry);

        if (!_isReadOnly)
        {
            var addButton = new Button
            {
                Content = "Add On Hit Effect",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left
            };
            addButton.Click += async (_, _) =>
            {
                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                var newElement = new XElement("onhiteffect");
                AddOnHitEffectCard(new ProtoActionOnHitEffectEntry
                {
                    Element = newElement,
                    IsSupported = true
                });
                MarkDirty();
            };
            state.OnHitEffectsContainer.Children.Add(addButton);
        }
    }

    private void RenderProtoActionStructuredFields(ProtoActionWidgetState state, Dictionary<string, List<ProtoActionStructuredFieldEntry>> currentValues)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        var preservedCustomRateRows = (IsBolsterActionType(actionType) || IsDrainResurrectionActionType(actionType) || IsDevoteMinorActionType(actionType) || IsHealActionType(actionType) || IsConditionalTransformActionType(actionType) || IsDelayedTransformActionType(actionType) || IsMaintainActionType(actionType) || IsAutoGatherActionType(actionType) || actionType.Equals("ModifyGather", StringComparison.OrdinalIgnoreCase) || IsConvertActionType(actionType) || IsSpawnActionType(actionType) || IsTradeActionType(actionType) || IsAreaRestrictActionType(actionType) || IsLureActionType(actionType) || IsAutoRangedModifyActionType(actionType)) &&
                                      state.StructuredFieldRows.TryGetValue("rate", out var customRateRows)
            ? customRateRows
            : null;
        var preservedConditionalTransformRuleRows = IsConditionalTransformActionType(actionType) &&
                                                    state.StructuredFieldRows.TryGetValue("conditionaltransformrule", out var conditionalTransformRuleRows)
            ? conditionalTransformRuleRows
            : null;
        var preservedConditionalTransformModifyProtoRows = IsConditionalTransformActionType(actionType) &&
                                                           state.StructuredFieldRows.TryGetValue("modifyprotoid", out var conditionalTransformModifyProtoRows)
            ? conditionalTransformModifyProtoRows
            : null;
        var preservedDelayedTransformModifyProtoRows = IsDelayedTransformActionType(actionType) &&
                                                       state.StructuredFieldRows.TryGetValue("modifyprotoid", out var delayedTransformModifyProtoRows)
            ? delayedTransformModifyProtoRows
            : null;
        var preservedAutoBoostModifyProtoRows = IsAutoBoostActionType(actionType) &&
                                                  state.StructuredFieldRows.TryGetValue("modifyprotoid", out var autoBoostModifyProtoRows)
            ? autoBoostModifyProtoRows
            : null;
        var preservedCustomMinRateRows = IsDistanceModifyActionType(actionType) &&
                                         state.StructuredFieldRows.TryGetValue("minrate", out var customMinRateRows)
            ? customMinRateRows
            : null;
        var preservedConvertMinRateRows = IsConvertActionType(actionType) &&
                                          state.StructuredFieldRows.TryGetValue("minrate", out var convertMinRateRows)
            ? convertMinRateRows
            : null;
        var preservedSpawnMinRateRows = IsSpawnActionType(actionType) &&
                                        state.StructuredFieldRows.TryGetValue("minrate", out var spawnMinRateRows)
            ? spawnMinRateRows
            : null;
        var preservedTradeMinRateRows = IsTradeActionType(actionType) &&
                                        state.StructuredFieldRows.TryGetValue("minrate", out var tradeMinRateRows)
            ? tradeMinRateRows
            : null;
        var preservedAutoGatherGatheringTypeRows = IsAutoGatherActionType(actionType) &&
                                                   state.StructuredFieldRows.TryGetValue("donotautogatherunlessgatheringtypes", out var autoGatherGatheringTypeRows)
            ? autoGatherGatheringTypeRows
            : null;
        var preservedConvertTypedDurationRows = IsConvertActionType(actionType) &&
                                                state.StructuredFieldRows.TryGetValue("typedduration", out var convertTypedDurationRows)
            ? convertTypedDurationRows
            : null;
        var preservedConvertTypedStunDurationRows = IsConvertActionType(actionType) &&
                                                    state.StructuredFieldRows.TryGetValue("typedstunduration", out var convertTypedStunDurationRows)
            ? convertTypedStunDurationRows
            : null;
        var fieldTags = GetVisibleProtoActionStructuredFieldTags(state, effectiveAction, actionType);
        if (IsAutoConvertActionType(actionType))
            fieldTags.RemoveAll(tag => tag.Equals("modifyunittype", StringComparison.OrdinalIgnoreCase));
        if (actionType.Equals("ModifyGather", StringComparison.OrdinalIgnoreCase))
            fieldTags.RemoveAll(tag => tag.Equals("rate", StringComparison.OrdinalIgnoreCase));
        if (IsLikeBonusActionType(actionType) && !state.SelectedFlagTags.Contains("modifyratebytype"))
            fieldTags.RemoveAll(tag => tag.Equals("rate", StringComparison.OrdinalIgnoreCase));
        var suggestedFieldTags = GetSuggestedProtoActionStructuredFieldTags(actionType);
        if (actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
            actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase) ||
            IsGatherActionType(actionType) ||
            actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase))
        {
            var actionCardTypedTags = actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase)
                ? new[] { "typedmaxrange" }
                : new[] { "typedanim", "typedmaxrange" };
            foreach (var typedTag in actionCardTypedTags)
            {
                if (fieldTags.Contains(typedTag, StringComparer.OrdinalIgnoreCase) &&
                    !suggestedFieldTags.Contains(typedTag, StringComparer.OrdinalIgnoreCase))
                {
                    suggestedFieldTags.Add(typedTag);
                }
            }
        }
        var primaryFieldTags = fieldTags
            .Where(x => suggestedFieldTags.Contains(x, StringComparer.OrdinalIgnoreCase))
            .ToList();

        state.StructuredFieldsContainer.Children.Clear();
        state.StructuredFieldRows.Clear();
        if (preservedConditionalTransformRuleRows != null)
            state.StructuredFieldRows["conditionaltransformrule"] = preservedConditionalTransformRuleRows;
        if (preservedConditionalTransformModifyProtoRows != null)
            state.StructuredFieldRows["modifyprotoid"] = preservedConditionalTransformModifyProtoRows;
        if (preservedDelayedTransformModifyProtoRows != null)
            state.StructuredFieldRows["modifyprotoid"] = preservedDelayedTransformModifyProtoRows;
        if (preservedAutoBoostModifyProtoRows != null)
            state.StructuredFieldRows["modifyprotoid"] = preservedAutoBoostModifyProtoRows;
        if (preservedCustomRateRows != null)
            state.StructuredFieldRows["rate"] = preservedCustomRateRows;
        if (preservedCustomMinRateRows != null)
            state.StructuredFieldRows["minrate"] = preservedCustomMinRateRows;
        if (preservedConvertMinRateRows != null)
            state.StructuredFieldRows["minrate"] = preservedConvertMinRateRows;
        if (preservedSpawnMinRateRows != null)
            state.StructuredFieldRows["minrate"] = preservedSpawnMinRateRows;
        if (preservedTradeMinRateRows != null)
            state.StructuredFieldRows["minrate"] = preservedTradeMinRateRows;
        if (preservedAutoGatherGatheringTypeRows != null)
            state.StructuredFieldRows["donotautogatherunlessgatheringtypes"] = preservedAutoGatherGatheringTypeRows;
        if (preservedConvertTypedDurationRows != null)
            state.StructuredFieldRows["typedduration"] = preservedConvertTypedDurationRows;
        if (preservedConvertTypedStunDurationRows != null)
            state.StructuredFieldRows["typedstunduration"] = preservedConvertTypedStunDurationRows;

        if (actionType.Equals("Trail", StringComparison.OrdinalIgnoreCase))
        {
            var entries = currentValues.TryGetValue("trailprotounit", out var editedEntries)
                ? editedEntries
                : GetProtoActionStructuredFieldEntriesForEditor(effectiveAction, actionType, "trailprotounit");
            var entry = entries.FirstOrDefault() ?? new ProtoActionStructuredFieldEntry();
            var frequency = entry.Attributes.TryGetValue("frequency", out var currentFrequency) &&
                            !string.IsNullOrWhiteSpace(currentFrequency)
                ? currentFrequency
                : "1";
            var row = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 2, 0, 2)
            };
            var protoUnitEditor = new AutoCompleteBox
            {
                Text = entry.Value ?? "",
                Width = 180,
                IsEnabled = !_isReadOnly
            };
            ConfigureStrictSuggestionAutoComplete(protoUnitEditor, GetAvailableTrainUnitNames(), entry.Value ?? "");
            var frequencyEditor = new TextBox
            {
                Text = frequency,
                Width = 90,
                IsEnabled = !_isReadOnly
            };
            AttachProtoActionDecimalBehavior(frequencyEditor);
            void RefreshFrequencyValidation()
            {
                var isValid = double.TryParse(
                                  frequencyEditor.Text?.Trim(),
                                  NumberStyles.Float,
                                  CultureInfo.InvariantCulture,
                                  out var parsedFrequency) && parsedFrequency > 0;
                if (isValid)
                {
                    frequencyEditor.ClearValue(TemplatedControl.BorderBrushProperty);
                    frequencyEditor.ClearValue(TemplatedControl.BorderThicknessProperty);
                }
                else
                {
                    frequencyEditor.BorderBrush = Brush.Parse("#d64545");
                    frequencyEditor.BorderThickness = new Thickness(2);
                }
                ToolTip.SetTip(frequencyEditor, isValid ? null : "Frequency must be a number greater than 0.");
            }
            protoUnitEditor.TextChanged += async (_, _) =>
            {
                if (!_isPopulating && await CheckStartLocalMod())
                    MarkDirty();
            };
            frequencyEditor.TextChanged += async (_, _) =>
            {
                RefreshFrequencyValidation();
                if (!_isPopulating && await CheckStartLocalMod())
                    MarkDirty();
            };
            RefreshFrequencyValidation();

            row.Children.Add(new TextBlock { Text = "Trail Proto Unit:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 8, 4) });
            row.Children.Add(protoUnitEditor);
            row.Children.Add(new TextBlock { Text = "Frequency(s):", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(16, 4, 8, 4) });
            row.Children.Add(frequencyEditor);

            var rowState = new ProtoActionStructuredFieldRowState
            {
                Tag = "trailprotounit",
                RowPanel = row,
                ValueTb = protoUnitEditor
            };
            rowState.AttributeEditors["frequency"] = frequencyEditor;
            state.StructuredFieldRows["trailprotounit"] = [rowState];
            state.StructuredFieldsContainer.Children.Add(row);
            return;
        }

        if (primaryFieldTags.Count == 0)
            return;

        static bool IsStandardTargetListTag(string tag)
            => tag.Equals("modifyabstracttype", StringComparison.OrdinalIgnoreCase) ||
               tag.Equals("forbidabstracttype", StringComparison.OrdinalIgnoreCase) ||
               tag.Equals("modifyprotoid", StringComparison.OrdinalIgnoreCase) ||
               tag.Equals("forbidunittype", StringComparison.OrdinalIgnoreCase);

        IReadOnlyList<string> GetStandardTargetListSuggestions(string tag)
        {
            if (tag.Equals("modifyabstracttype", StringComparison.OrdinalIgnoreCase) && IsAutoConvertActionType(actionType))
                return GetAvailableBuildLimitTargets();

            if (tag.Equals("modifyabstracttype", StringComparison.OrdinalIgnoreCase) ||
                tag.Equals("forbidabstracttype", StringComparison.OrdinalIgnoreCase))
            {
                return GetKnownUnitTypeNames();
            }

            return GetAvailableTrainUnitNames();
        }

        void RenderStandardTargetList(string tag, ProtoActionFieldDefinition definition, List<ProtoActionStructuredFieldEntry> entries)
        {
            var section = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
            var label = tag.Equals("modifyabstracttype", StringComparison.OrdinalIgnoreCase) ? "Target Unit Type"
                : tag.Equals("forbidabstracttype", StringComparison.OrdinalIgnoreCase) ? "Forbid Unit Type"
                : tag.Equals("modifyprotoid", StringComparison.OrdinalIgnoreCase) ? "Target Proto Unit"
                : tag.Equals("forbidunittype", StringComparison.OrdinalIgnoreCase) ? "Forbid Proto Unit"
                : definition.Label;
            var selectorRow = new WrapPanel { Orientation = Orientation.Horizontal };
            selectorRow.Children.Add(new TextBlock
            {
                Text = label + ":",
                FontWeight = FontWeight.SemiBold,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 8, 0)
            });
            section.Children.Add(selectorRow);
            var chips = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
            state.StructuredFieldRows[tag] = [];
            var suggestions = GetStandardTargetListSuggestions(tag);

            void AddEntry(string value)
            {
                var normalizedValue = value?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(normalizedValue) ||
                    state.StructuredFieldRows[tag].Any(row => ReadTextLikeControlValue(row.ValueTb).Equals(normalizedValue, StringComparison.OrdinalIgnoreCase)))
                {
                    return;
                }

                var valueControl = new AutoCompleteBox { Text = normalizedValue };
                ConfigureStrictSuggestionAutoComplete(valueControl, suggestions, normalizedValue);
                var rowState = new ProtoActionStructuredFieldRowState
                {
                    Tag = tag,
                    RowPanel = chips,
                    ValueTb = valueControl,
                    IncludeInSerialization = true
                };
                state.StructuredFieldRows[tag].Add(rowState);
                var tacticsEntries = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsTargetAction)
                    ? ProtoXmlHandler.GetProtoActionStructuredFieldEntries(tacticsTargetAction, tag)
                    : [];
                var tacticsValue = tacticsEntries.FirstOrDefault(entry =>
                    string.Equals(entry.Value?.Trim() ?? "", normalizedValue, StringComparison.OrdinalIgnoreCase))?.Value ?? "";
                var isInherited = !string.IsNullOrWhiteSpace(tacticsValue);
                var source = isInherited
                    ? ProtoActionValueSource.TacticsInherited
                    : ProtoActionValueSource.ProtoOnly;

                Border? chip = null;
                chip = CreateChip(normalizedValue, async () =>
                {
                    if (!await CheckStartLocalMod())
                        return;

                    if (isInherited)
                    {
                        await new Prompt(
                            PromptType.Error,
                            "Inherited Attribute",
                            $"{label} '{normalizedValue}' is defined by the linked tactics file and cannot be deleted from the protoaction.")
                            .ShowDialog(this);
                        return;
                    }

                    state.StructuredFieldRows[tag].Remove(rowState);
                    if (chip != null)
                        chips.Children.Remove(chip);
                    MarkDirty();
                }, source, tacticsValue);
                chips.Children.Add(chip);
            }

            if (!_isReadOnly)
            {
                var picker = new AutoCompleteBox
                {
                    FilterMode = AutoCompleteFilterMode.Contains,
                    MinWidth = 120,
                    MaxWidth = 200,
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                ConfigureStrictSuggestionAutoComplete(picker, suggestions, "");
                picker.SelectionChanged += async (_, _) =>
                {
                    if (_isPopulating || picker.SelectedItem is not string selectedValue || !await CheckStartLocalMod())
                        return;

                    AddEntry(selectedValue);
                    picker.Text = "";
                    MarkDirty();
                };
                selectorRow.Children.Add(picker);
            }

            foreach (var entry in entries)
                AddEntry(entry.Value);
            section.Children.Add(chips);
            state.StructuredFieldsContainer.Children.Add(section);
        }

        foreach (var tag in primaryFieldTags)
        {
            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
            var fieldLabel = GetProtoActionStructuredFieldLabel(actionType, tag, definition.Label);
            var entries = currentValues.TryGetValue(tag, out var editedEntries)
                ? editedEntries
                : GetProtoActionStructuredFieldEntriesForEditor(effectiveAction, actionType, tag);
            if (IsStandardTargetListTag(tag))
            {
                RenderStandardTargetList(tag, definition, entries);
                continue;
            }

            var isDeferredTypedField =
                ((IsGatherActionType(actionType) ||
                  actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
                  actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase)) &&
                 (tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase) ||
                  tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase))) ||
                ((actionType.Equals("Hunting", StringComparison.OrdinalIgnoreCase) ||
                  actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase)) &&
                 tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase));
            if (isDeferredTypedField &&
                entries.Count == 0 &&
                !state.ForcedVisibleFieldTags.Contains(tag))
            {
                state.StructuredFieldRows[tag] = [];
                var isPositionedByActionLayout =
                    IsGatherActionType(actionType) ||
                    actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
                    actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase) ||
                    actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase);
                if (!_isReadOnly && !isPositionedByActionLayout)
                {
                    var addTypedFieldButton = new Button
                    {
                        Content = tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase)
                            ? "Add Animation by Type"
                            : "Add Max Range by Type",
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 0, 0, 6)
                    };
                    addTypedFieldButton.Click += async (_, _) =>
                    {
                        if (!await CheckStartLocalMod())
                            return;

                        state.ForcedVisibleFieldTags.Add(tag);
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    };
                    state.StructuredFieldsContainer.Children.Add(addTypedFieldButton);
                }
                continue;
            }
            if (entries.Count == 0 &&
                !_isReadOnly &&
                IsAutoBoostActionType(actionType) &&
                tag.Equals("rate", StringComparison.OrdinalIgnoreCase))
            {
                var defaultRate = new ProtoActionStructuredFieldEntry { Value = "1" };
                defaultRate.Attributes["type"] = "Unit";
                entries = [defaultRate];
            }
            if (entries.Count == 0 &&
                !_isReadOnly &&
                (actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
                 actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase) ||
                 IsGatherActionType(actionType) ||
                 actionType.Equals("Hunting", StringComparison.OrdinalIgnoreCase) ||
                 actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase)) &&
                state.ForcedVisibleFieldTags.Contains(tag) &&
                (tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase) ||
                 tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase)))
            {
                entries = [new ProtoActionStructuredFieldEntry()];
            }

            var section = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
            var sectionHeader = new Grid
            {
                ColumnDefinitions = !_isReadOnly && IsUserAddedProtoActionField(state, tag)
                    ? new ColumnDefinitions("*, Auto")
                    : new ColumnDefinitions("*")
            };
            sectionHeader.Children.Add(new TextBlock
            {
                Text = fieldLabel + ":",
                FontWeight = FontWeight.SemiBold
            });
            if (!_isReadOnly && IsUserAddedProtoActionField(state, tag) &&
                !(IsLikeBonusActionType(actionType) && tag.Equals("rate", StringComparison.OrdinalIgnoreCase)))
            {
                var removeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(8, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        state.ForcedVisibleFieldTags.Remove(tag);
                        state.StructuredFieldRows.Remove(tag);
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, tag, []);
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    }
                };
                Grid.SetColumn(removeButton, 1);
                sectionHeader.Children.Add(removeButton);
            }
            section.Children.Add(sectionHeader);

            var rowsContainer = new StackPanel { Spacing = 4 };
            section.Children.Add(rowsContainer);
            state.StructuredFieldRows[tag] = [];

            void AddRow(ProtoActionStructuredFieldEntry? initialEntry = null)
            {
                ProtoActionStructuredFieldEntry? inheritedEntry = null;
                if ((tag.Equals("rate", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("minrate", StringComparison.OrdinalIgnoreCase)) &&
                    initialEntry != null &&
                    TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction))
                {
                    var initialType = initialEntry.Attributes.TryGetValue("type", out var typeValue) ? typeValue.Trim() : "";
                    inheritedEntry = GetProtoActionStructuredFieldEntriesForEditor(tacticsAction, actionType, tag)
                        .FirstOrDefault(entry => entry.Attributes.TryGetValue("type", out var candidateType) &&
                                                 candidateType.Equals(initialType, StringComparison.OrdinalIgnoreCase));
                }
                var isInheritedRateType = inheritedEntry != null;

                var rowPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 6
                };

                var rowState = new ProtoActionStructuredFieldRowState
                {
                    Tag = tag,
                    RowPanel = rowPanel,
                    ValueTb = GetProtoActionValueSuggestions(tag) is List<string> suggestions
                        ? new AutoCompleteBox
                        {
                            Text = string.IsNullOrWhiteSpace(initialEntry?.Value) && tag.Equals("rate", StringComparison.OrdinalIgnoreCase)
                                ? "1.0"
                                : initialEntry?.Value ?? "",
                            Width = 140,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            ItemsSource = suggestions,
                            IsEnabled = !_isReadOnly
                        }
                        : new TextBox
                        {
                            Text = string.IsNullOrWhiteSpace(initialEntry?.Value) && tag.Equals("rate", StringComparison.OrdinalIgnoreCase)
                                ? "1.0"
                                : initialEntry?.Value ?? "",
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        }
                };
                if (IsDistanceModifyActionType(actionType) &&
                    tag.Equals("minrate", StringComparison.OrdinalIgnoreCase) &&
                    initialEntry != null)
                {
                    foreach (var attribute in initialEntry.Attributes.Where(attribute =>
                                 !attribute.Key.Equals("type", StringComparison.OrdinalIgnoreCase)))
                    {
                        rowState.PreservedAttributes[attribute.Key] = attribute.Value;
                    }
                }
                ApplyProtoActionFieldWidth(rowState.ValueTb, tag);
                if (rowState.ValueTb is TextBox valueTextBox)
                    AttachProtoActionDecimalBehavior(valueTextBox);
                else if (rowState.ValueTb is AutoCompleteBox valueAutoCompleteBox)
                {
                    ConfigureProtoActionValueAutoComplete(valueAutoCompleteBox, tag, initialEntry?.Value ?? "");
                }

                if (rowState.ValueTb is TextBox rowValueTb)
                {
                    rowValueTb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                MarkDirty();
                            }
                        }
                    };
                }
                else if (rowState.ValueTb is AutoCompleteBox rowValueAcb)
                {
                    rowValueAcb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                MarkDirty();
                            }
                        }
                    };
                }

                var attributeNames = definition.XmlAttributeNames?.ToList() ?? [];
                var orderedAttributeNames = new List<string>();
                if (attributeNames.Any(x => x.Equals("type", StringComparison.OrdinalIgnoreCase)))
                    orderedAttributeNames.Add(attributeNames.First(x => x.Equals("type", StringComparison.OrdinalIgnoreCase)));
                orderedAttributeNames.AddRange(attributeNames.Where(x =>
                    !x.Equals("type", StringComparison.OrdinalIgnoreCase) &&
                    !(tag.Equals("minrate", StringComparison.OrdinalIgnoreCase) &&
                      x.Equals("resource", StringComparison.OrdinalIgnoreCase))));

                var visibleAttributeNames = new HashSet<string>(
                    GetDefaultVisibleProtoActionStructuredAttributeNames(actionType, tag),
                    StringComparer.OrdinalIgnoreCase);
                if (initialEntry != null &&
                    !(IsDistanceModifyActionType(actionType) && tag.Equals("minrate", StringComparison.OrdinalIgnoreCase)))
                {
                    foreach (var attributeName in initialEntry.Attributes.Keys)
                        visibleAttributeNames.Add(attributeName);
                }

                bool valueAdded = false;

                void AddValueEditor()
                {
                    if (valueAdded)
                        return;

                    var valueLabel = GetProtoActionStructuredValueLabel(tag);
                    if (!string.IsNullOrWhiteSpace(valueLabel))
                    {
                        rowPanel.Children.Add(new TextBlock
                        {
                            Text = valueLabel,
                            VerticalAlignment = VerticalAlignment.Center
                        });
                    }
                    rowPanel.Children.Add(rowState.ValueTb);
                    valueAdded = true;
                }

                void AddAttributeEditor(string attributeName, Control? insertBefore = null)
                {
                    var isGatherOptionalRateAttribute =
                        IsGatherActionType(actionType) &&
                        tag.Equals("rate", StringComparison.OrdinalIgnoreCase) &&
                        attributeName is "resource" or "yield" or "overrideResource";
                    var attributeLabel = new TextBlock
                    {
                        Text = tag.Equals("conversionprotoid", StringComparison.OrdinalIgnoreCase) &&
                               attributeName.Equals("srctype", StringComparison.OrdinalIgnoreCase)
                            ? "Source:"
                            : attributeName.Equals("type", StringComparison.OrdinalIgnoreCase)
                            ? "Type:"
                            : attributeName.Equals("resource", StringComparison.OrdinalIgnoreCase)
                                ? "Resource:"
                            : attributeName.Equals("overrideResource", StringComparison.OrdinalIgnoreCase)
                                    ? "Override Resource:"
                            : attributeName.Equals("class", StringComparison.OrdinalIgnoreCase) &&
                              tag.Equals("sizeclassanim", StringComparison.OrdinalIgnoreCase)
                                ? "Size Class:"
                            : attributeName.Equals("frequency", StringComparison.OrdinalIgnoreCase)
                                ? "Frequency(s):"
                                : attributeName.Equals("yield", StringComparison.OrdinalIgnoreCase)
                                    ? (actionType.Equals("Eat", StringComparison.OrdinalIgnoreCase) ? "Veterancy Yield:" : "Yield:")
                                  : attributeName + ":",
                        VerticalAlignment = VerticalAlignment.Center
                    };

                    var attributeValue = initialEntry != null && initialEntry.Attributes.TryGetValue(attributeName, out var existingAttributeValue)
                        ? existingAttributeValue
                        : "";
                    List<string>? attributeSuggestions =
                        tag.Equals("rate", StringComparison.OrdinalIgnoreCase) &&
                        actionType.Equals("ModifyGather", StringComparison.OrdinalIgnoreCase) &&
                        attributeName.Equals("type", StringComparison.OrdinalIgnoreCase)
                            ? [.. ProtoConstants.KnownResourceTypes]
                            : GetProtoActionStructuredAttributeSuggestions(tag, attributeName);
                    Control attributeEditor;
                    if (isGatherOptionalRateAttribute &&
                        attributeSuggestions != null &&
                        (attributeName.Equals("resource", StringComparison.OrdinalIgnoreCase) ||
                         attributeName.Equals("overrideResource", StringComparison.OrdinalIgnoreCase)))
                    {
                        var attributeCombo = new ComboBox
                        {
                            ItemsSource = attributeSuggestions,
                            SelectedItem = attributeSuggestions.FirstOrDefault(option =>
                                option.Equals(attributeValue, StringComparison.OrdinalIgnoreCase)),
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        };
                        attributeCombo.SelectionChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        attributeEditor = attributeCombo;
                    }
                    else if (attributeSuggestions != null)
                    {
                        var attributeAcb = new AutoCompleteBox
                        {
                            Text = attributeValue,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            Width = tag.Equals("conversionprotoid", StringComparison.OrdinalIgnoreCase)
                                ? 200
                                : isGatherOptionalRateAttribute &&
                                    (attributeName.Equals("resource", StringComparison.OrdinalIgnoreCase) ||
                                     attributeName.Equals("overrideResource", StringComparison.OrdinalIgnoreCase))
                                ? 100
                                : 150,
                            IsEnabled = !_isReadOnly
                        };
                        ConfigureStrictSuggestionAutoComplete(attributeAcb, attributeSuggestions, attributeValue);
                        if (isGatherOptionalRateAttribute &&
                            (attributeName.Equals("resource", StringComparison.OrdinalIgnoreCase) ||
                             attributeName.Equals("overrideResource", StringComparison.OrdinalIgnoreCase)))
                        {
                            attributeAcb.Width = 100;
                        }
                        attributeAcb.TextChanged += async (s, e) =>
                        {
                            if (!_isPopulating)
                            {
                                var proceed = await CheckStartLocalMod();
                                if (proceed)
                                {
                                    MarkDirty();
                                }
                            }
                        };
                        attributeEditor = attributeAcb;
                    }
                    else
                    {
                        var attributeTextBox = new TextBox
                        {
                            Text = attributeValue,
                            Width = 110,
                            IsEnabled = !_isReadOnly
                        };
                        attributeTextBox.TextChanged += async (s, e) =>
                        {
                            if (!_isPopulating)
                            {
                                var proceed = await CheckStartLocalMod();
                                if (proceed)
                                {
                                    MarkDirty();
                                }
                            }
                        };
                        attributeEditor = attributeTextBox;
                        if (tag.Equals("sizeclassanim", StringComparison.OrdinalIgnoreCase) &&
                            attributeName.Equals("class", StringComparison.OrdinalIgnoreCase))
                        {
                            AttachProtoActionIntegerBehavior(attributeTextBox);
                        }
                    }

                    if (isInheritedRateType &&
                        attributeName.Equals("type", StringComparison.OrdinalIgnoreCase))
                    {
                        attributeEditor.IsEnabled = false;
                    }

                    rowState.AttributeEditors[attributeName] = attributeEditor;
                    var insertIndex = insertBefore != null ? rowPanel.Children.IndexOf(insertBefore) : -1;
                    if (insertIndex >= 0)
                    {
                        rowPanel.Children.Insert(insertIndex, attributeLabel);
                        rowPanel.Children.Insert(insertIndex + 1, attributeEditor);
                    }
                    else
                    {
                        rowPanel.Children.Add(attributeLabel);
                        rowPanel.Children.Add(attributeEditor);
                    }

                    if (!_isReadOnly && isGatherOptionalRateAttribute)
                    {
                        var removeAttributeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        };
                        removeAttributeButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;

                            rowState.AttributeEditors.Remove(attributeName);
                            MarkDirty();
                            RefreshProtoActionMetadataPanels(state);
                        };

                        var editorIndex = rowPanel.Children.IndexOf(attributeEditor);
                        if (editorIndex >= 0)
                            rowPanel.Children.Insert(editorIndex + 1, removeAttributeButton);
                        else
                            rowPanel.Children.Add(removeAttributeButton);
                    }

                    if (attributeName.Equals("type", StringComparison.OrdinalIgnoreCase))
                        AddValueEditor();
                }

                foreach (var attributeName in orderedAttributeNames.Where(x => visibleAttributeNames.Contains(x)))
                    AddAttributeEditor(attributeName);

                AddValueEditor();

                if (!_isReadOnly &&
                    tag.Equals("rate", StringComparison.OrdinalIgnoreCase) &&
                    actionType.Equals("Eat", StringComparison.OrdinalIgnoreCase) &&
                    !rowState.AttributeEditors.ContainsKey("yield"))
                {
                    var addVeterancyYieldButton = new Button
                    {
                        Content = "Veterancy Yield",
                        Classes = { "add-component" },
                        VerticalAlignment = VerticalAlignment.Center
                    };

                    addVeterancyYieldButton.Click += (s, e) =>
                    {
                        if (rowPanel.Children.Contains(addVeterancyYieldButton))
                            rowPanel.Children.Remove(addVeterancyYieldButton);

                        AddAttributeEditor("yield", rowPanel.Children.OfType<Button>().FirstOrDefault());
                        MarkDirty();
                    };

                    rowPanel.Children.Add(addVeterancyYieldButton);
                }

                if (!_isReadOnly &&
                    tag.Equals("rate", StringComparison.OrdinalIgnoreCase) &&
                    actionType.Equals("Gather", StringComparison.OrdinalIgnoreCase))
                {
                    void AddGatherRateAttributeButton(string attributeName, string buttonLabel)
                    {
                        if (rowState.AttributeEditors.ContainsKey(attributeName))
                            return;

                        var addButton = new Button
                        {
                            Content = buttonLabel,
                            Classes = { "add-component" },
                            VerticalAlignment = VerticalAlignment.Center
                        };

                        addButton.Click += (s, e) =>
                        {
                            if (rowPanel.Children.Contains(addButton))
                                rowPanel.Children.Remove(addButton);

                            AddAttributeEditor(attributeName, rowPanel.Children.OfType<Button>().FirstOrDefault());
                            MarkDirty();
                        };

                        rowPanel.Children.Add(addButton);
                    }

                    AddGatherRateAttributeButton("resource", "Resource");
                    AddGatherRateAttributeButton("yield", "Yield");
                    AddGatherRateAttributeButton("overrideResource", "Override Resource");
                }

                if (!_isReadOnly && tag.Equals("minrate", StringComparison.OrdinalIgnoreCase) &&
                    !IsDistanceModifyActionType(actionType) &&
                    !rowState.AttributeEditors.ContainsKey("resource"))
                {
                    var addResourceButton = new Button
                    {
                        Content = "Resource",
                        Classes = { "add-component" },
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    addResourceButton.Click += (_, _) =>
                    {
                        if (rowPanel.Children.Contains(addResourceButton))
                            rowPanel.Children.Remove(addResourceButton);
                        AddAttributeEditor("resource", rowPanel.Children.OfType<Button>().FirstOrDefault());
                        MarkDirty();
                    };
                    rowPanel.Children.Add(addResourceButton);
                }

                if (!_isReadOnly && ShouldShowProtoActionStructuredOtherAttributeButton(actionType, tag))
                {
                    var hiddenAttributeNames = orderedAttributeNames
                        .Where(x => !visibleAttributeNames.Contains(x))
                        .ToList();
                    if (hiddenAttributeNames.Count > 0)
                    {
                        var addOtherButton = new Button
                        {
                            Content = definition.Label.Equals("Rate", StringComparison.OrdinalIgnoreCase)
                                ? "Other Rate Attribute"
                                : $"Other {definition.Label} Attribute",
                            Classes = { "add-component" },
                            VerticalAlignment = VerticalAlignment.Center
                        };

                        addOtherButton.Click += (s, e) =>
                        {
                            if (rowPanel.Children.Contains(addOtherButton))
                                rowPanel.Children.Remove(addOtherButton);

                            var pickerAcb = new AutoCompleteBox
                            {
                                FilterMode = AutoCompleteFilterMode.Contains,
                                ItemsSource = hiddenAttributeNames
                                    .Where(x => !rowState.AttributeEditors.ContainsKey(x))
                                    .Select(x => x.Equals("type", StringComparison.OrdinalIgnoreCase) ? "Type" : x)
                                    .ToList(),
                                MinimumPrefixLength = 0,
                                MinimumPopulateDelay = TimeSpan.Zero,
                                Width = 170,
                                IsEnabled = !_isReadOnly
                            };
                            EnableDropdownAutoComplete(pickerAcb, selectAllOnFirstClick: false);

                            async void AddSelectedAttribute()
                            {
                                var input = pickerAcb.Text?.Trim() ?? "";
                                var selectedAttributeName = hiddenAttributeNames.FirstOrDefault(x =>
                                    x.Equals(input, StringComparison.OrdinalIgnoreCase) ||
                                    (x.Equals("type", StringComparison.OrdinalIgnoreCase) && input.Equals("Type", StringComparison.OrdinalIgnoreCase)));
                                if (string.IsNullOrWhiteSpace(selectedAttributeName) ||
                                    rowState.AttributeEditors.ContainsKey(selectedAttributeName))
                                {
                                    return;
                                }

                                var proceed = await CheckStartLocalMod();
                                if (!proceed)
                                    return;

                                var insertIndex = rowPanel.Children.IndexOf(pickerAcb);
                                if (insertIndex < 0)
                                    insertIndex = rowPanel.Children.Count;

                                rowPanel.Children.Remove(pickerAcb);
                                AddAttributeEditor(selectedAttributeName, addOtherButton);
                                MarkDirty();
                            }

                            pickerAcb.SelectionChanged += (s, e) =>
                            {
                                if (pickerAcb.SelectedItem is string selected)
                                {
                                    pickerAcb.Text = selected;
                                    AddSelectedAttribute();
                                }
                            };

                            var insertAt = rowPanel.Children.IndexOf(addOtherButton);
                            rowPanel.Children.Insert(insertAt, pickerAcb);
                            Dispatcher.UIThread.Post(() => pickerAcb.IsDropDownOpen = true, DispatcherPriority.Background);
                        };

                        rowPanel.Children.Add(addOtherButton);
                    }
                }

                if (!_isReadOnly && !(IsLikeBonusActionType(actionType) && tag.Equals("rate", StringComparison.OrdinalIgnoreCase)))
                {
                    var deleteButton = new Button
                    {
                        Classes = { "remove-button" },
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    deleteButton.Click += async (s, e) =>
                    {
                        if (isInheritedRateType)
                        {
                            var inheritedType = initialEntry?.Attributes.TryGetValue("type", out var typeValue) == true ? typeValue : "Rate";
                            await new Prompt(
                                PromptType.Error,
                                "Inherited Attribute",
                                $"Rate type '{inheritedType}' is defined by the linked tactics file and cannot be removed. You may override its value.")
                                .ShowDialog(this);
                            return;
                        }

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            state.StructuredFieldRows[tag].Remove(rowState);
                            rowsContainer.Children.Remove(rowPanel);
                            if ((IsGatherActionType(actionType) ||
                                 actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) ||
                                 actionType.Equals("Repair", StringComparison.OrdinalIgnoreCase) ||
                                 actionType.Equals("Hunting", StringComparison.OrdinalIgnoreCase) ||
                                 actionType.Equals("NoWork", StringComparison.OrdinalIgnoreCase)) &&
                                state.StructuredFieldRows[tag].Count == 0 &&
                                (tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase) ||
                                 tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase)))
                            {
                                state.ForcedVisibleFieldTags.Remove(tag);
                                RefreshProtoActionMetadataPanels(state);
                            }
                            MarkDirty();
                        }
                    };
                    rowPanel.Children.Add(deleteButton);
                }

                state.StructuredFieldRows[tag].Add(rowState);
                rowsContainer.Children.Add(rowPanel);
            }

            foreach (var entry in entries)
                AddRow(entry);

            if (!_isReadOnly && !tag.Equals("trailprotounit", StringComparison.OrdinalIgnoreCase))
            {
                var addButton = new Button
                {
                    Content = actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) &&
                              tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase)
                        ? "Add Animation by Type"
                        : actionType.Equals("Build", StringComparison.OrdinalIgnoreCase) &&
                          tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase)
                            ? "Add Max Range by Type"
                            : tag.Equals("typedanim", StringComparison.OrdinalIgnoreCase)
                                ? "Add Animation by Type"
                                : tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase)
                                    ? "Add Max Range by Type"
                            : tag.Equals("rate", StringComparison.OrdinalIgnoreCase) ||
                              tag.Equals("minrate", StringComparison.OrdinalIgnoreCase)
                                ? "Add " + definition.Label
                                : "+ Add " + definition.Label,
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                addButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        AddRow();
                        MarkDirty();
                    }
                };
                section.Children.Add(addButton);
            }

            state.StructuredFieldsContainer.Children.Add(section);
        }
    }

    private void RenderProtoActionFlags(ProtoActionWidgetState state)
    {
        state.FlagsContainer.Children.Clear();

        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        if (string.IsNullOrWhiteSpace(actionType) && state.SelectedFlagTags.Count == 0)
            return;

        var flagsHeaderRow = new WrapPanel
        {
            Orientation = Orientation.Horizontal,
            Margin = new Thickness(0, 6, 0, 2)
        };
        flagsHeaderRow.Children.Add(new TextBlock
        {
            Text = "Flags:",
            FontWeight = FontWeight.Bold,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 0, 8, 0)
        });
        state.FlagsContainer.Children.Add(flagsHeaderRow);

        var flagsWrap = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 4, 0, 4) };
        state.FlagsContainer.Children.Add(flagsWrap);
        var availableFlags = ProtoActionMetadataCatalog.GetKnownFlagTags()
            .Where(x => !x.Equals("active", StringComparison.OrdinalIgnoreCase))
            .Where(x => !IsInvertedDefaultProtoActionFlag(x))
            .Concat(InvertedDefaultProtoActionFlags.Values)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(GetProtoActionFlagDisplayLabel, StringComparer.OrdinalIgnoreCase)
            .ToList();
        AutoCompleteBox? protoActionFlagPicker = null;

        void SyncFlagCheckboxesFromFlags()
        {
            foreach (var (control, flagTags) in state.CustomFlagSourceControls.ToList())
            {
                if (control is not CheckBox checkBox || flagTags.Length != 1 || checkBox.Parent == null)
                    continue;

                var tag = flagTags[0];
                if (tag.Equals("active", StringComparison.OrdinalIgnoreCase))
                {
                    checkBox.IsChecked = state.CustomValues
                        .GetValueOrDefault(ProtoActionActiveValueStateKey, "0")
                        .Equals("1", StringComparison.OrdinalIgnoreCase);
                    continue;
                }

                var isInverted = tag.Equals("cannotbeconvertedbyallies", StringComparison.OrdinalIgnoreCase) ||
                                 tag.Equals("cannotbeconvertedbyenemies", StringComparison.OrdinalIgnoreCase);
                checkBox.IsChecked = isInverted
                    ? !state.SelectedFlagTags.Contains(tag)
                    : state.SelectedFlagTags.Contains(tag);
            }
        }

        void RefreshFlagsDisplay()
        {
            flagsWrap.Children.Clear();
            foreach (var tag in state.SelectedFlagTags
                         .Where(x => !x.Equals("active", StringComparison.OrdinalIgnoreCase))
                         .OrderBy(GetProtoActionFlagDisplayLabel, StringComparer.OrdinalIgnoreCase))
            {
                var protoFlagValue = GetProtoActionSimpleSourceValue(state.Model, tag);
                var tacticsFlagValue = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsFlagAction)
                    ? GetProtoActionSimpleSourceValue(tacticsFlagAction, tag)
                    : "";
                var flagSource = GetProtoActionValueSource("1", protoFlagValue, tacticsFlagValue);
                var chip = CreateChip(GetProtoActionFlagDisplayLabel(tag), async () =>
                {
                    var actionName = state.NameAcb.Text?.Trim() ?? "";
                    if ((tag.Equals("chargeaction", StringComparison.OrdinalIgnoreCase) || tag.Equals("auxchargeaction", StringComparison.OrdinalIgnoreCase)) &&
                        IsAbilityActionFlagProtected(actionName, tag))
                    {
                        await new Prompt(PromptType.Error, "Ability-linked action",
                            "This action is used by an ability. The recharge action flag cannot be removed while that ability is linked to it.")
                            .ShowDialog(this);
                        return;
                    }
                    if ((tag.Equals("chargeaction", StringComparison.OrdinalIgnoreCase) || tag.Equals("auxchargeaction", StringComparison.OrdinalIgnoreCase)) &&
                        IsActionFlagProtectedByTactics(actionName, tag))
                    {
                        await new Prompt(PromptType.Error, "Inherited flag",
                            "This recharge action flag is required by the linked tactics file and cannot be removed here.")
                            .ShowDialog(this);
                        return;
                    }
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        state.SelectedFlagTags.Remove(tag);
                        state.DefaultInjectedFlagTags.Remove(tag);
                        SyncFlagCheckboxesFromFlags();
                        MarkDirty();
                        RefreshFlagsDisplay();
                        // AutoRangedModify Targets are a second visual representation of these
                        // flags. Rebuild that panel so removing a flag chip removes its target chip.
                        RefreshProtoActionMetadataPanels(state);
                    }
                }, flagSource, tacticsFlagValue);
                flagsWrap.Children.Add(chip);
            }

            // Keep this picker in sync with the chips, like the protounit flag picker.
            // This prevents a selected flag remaining as a selectable autocomplete item.
            if (protoActionFlagPicker != null)
            {
                protoActionFlagPicker.ItemsSource = availableFlags
                    .Where(flag => !state.SelectedFlagTags.Contains(flag))
                    .Select(GetProtoActionFlagDisplayLabel)
                    .ToList();
            }
        }

        RefreshFlagsDisplay();

        if (_isReadOnly)
            return;

        var acbAdd = new AutoCompleteBox
        {
            FilterMode = AutoCompleteFilterMode.Contains,
            ItemsSource = availableFlags
                .Where(flag => !state.SelectedFlagTags.Contains(flag))
                .Select(GetProtoActionFlagDisplayLabel)
                .ToList(),
            MinWidth = 120,
            MaxWidth = 200,
            HorizontalAlignment = HorizontalAlignment.Left
        };
        protoActionFlagPicker = acbAdd;
        EnableDropdownAutoComplete(acbAdd, selectAllOnFirstClick: false);
        flagsHeaderRow.Children.Add(acbAdd);

        async void PerformAddFlag()
        {
            var input = acbAdd.Text?.Trim() ?? "";
            var matchLabel = availableFlags
                .Where(flag => !state.SelectedFlagTags.Contains(flag))
                .Select(GetProtoActionFlagDisplayLabel)
                .FirstOrDefault(x => x.Equals(input, StringComparison.OrdinalIgnoreCase));
            if (string.IsNullOrWhiteSpace(matchLabel))
                return;

            var tag = availableFlags.FirstOrDefault(x =>
                !state.SelectedFlagTags.Contains(x) &&
                GetProtoActionFlagDisplayLabel(x).Equals(matchLabel, StringComparison.OrdinalIgnoreCase));
            if (string.IsNullOrWhiteSpace(tag) || state.SelectedFlagTags.Contains(tag))
                return;

            var proceed = await CheckStartLocalMod();
            if (proceed)
            {
                state.SelectedFlagTags.Add(tag);
                // From this point the flag is an explicit user choice, even if it was
                // also a default of a type previewed earlier.
                state.DefaultInjectedFlagTags.Remove(tag);
                SyncFlagCheckboxesFromFlags();
                acbAdd.Text = "";
                MarkDirty();
                RefreshFlagsDisplay();
                // Keep paired AutoRangedModify target chips synchronized when a flag is
                // re-added from the generic Flags editor.
                RefreshProtoActionMetadataPanels(state);
                Dispatcher.UIThread.Post(() =>
                {
                    CommitChipAdditionAndRefreshXmlPreview();
                    if (acbAdd.IsEnabled && string.IsNullOrWhiteSpace(acbAdd.Text))
                        acbAdd.IsDropDownOpen = true;
                });
            }
        }

        acbAdd.SelectionChanged += (s, e) =>
        {
            if (acbAdd.SelectedItem is string selected)
            {
                acbAdd.Text = selected;
                PerformAddFlag();
            }
        };
    }

    private void RenderAdditionalGatheringTypeChips(
        ProtoActionWidgetState state,
        IEnumerable<string> initialValues,
        Panel destination)
        => RenderAdditionalStructuredValueChips(
            state,
            "donotautogatherunlessgatheringtypes",
            "Do Not Auto Gather Unless Gathering Types",
            "Unit Type",
            GetAvailableBuildLimitTargets(),
            initialValues,
            destination,
            usesNestedUnitTypeContainer: true);

    private void RenderAdditionalStructuredValueChips(
        ProtoActionWidgetState state,
        string tag,
        string header,
        string fieldLabel,
        IReadOnlyList<string> suggestions,
        IEnumerable<string> initialValues,
        Panel destination,
        bool usesNestedUnitTypeContainer = false)
    {
        var rows = new List<ProtoActionStructuredFieldRowState>();
        state.StructuredFieldRows[tag] = rows;

        var section = new StackPanel { Spacing = 4, Margin = new Thickness(0, 2, 0, 6) };
        var headerRow = new Grid
        {
            ColumnDefinitions = !_isReadOnly ? new ColumnDefinitions("Auto, Auto") : new ColumnDefinitions("Auto")
        };
        headerRow.Children.Add(new TextBlock
        {
            Text = header,
            FontWeight = FontWeight.Bold,
            VerticalAlignment = VerticalAlignment.Center
        });
        if (!_isReadOnly)
        {
            var removeSectionButton = new Button
            {
                Classes = { "remove-button" },
                Margin = new Thickness(2, 0, 0, 0),
                VerticalAlignment = VerticalAlignment.Center
            };
            removeSectionButton.Click += async (_, _) =>
            {
                if (await BlockInheritedStructuredProtoActionRemovalAsync(state, tag, header))
                    return;
                if (!await CheckStartLocalMod())
                    return;

                state.ForcedVisibleFieldTags.Remove(tag);
                state.StructuredFieldRows.Remove(tag);
                if (usesNestedUnitTypeContainer)
                    SaveProtoActionNestedUnitTypeListElement(state.Model, tag, []);
                else
                    ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, tag, []);
                MarkDirty();
                RefreshProtoActionMetadataPanels(state);
                CommitChipAdditionAndRefreshXmlPreview();
            };
            Grid.SetColumn(removeSectionButton, 1);
            headerRow.Children.Add(removeSectionButton);
        }
        section.Children.Add(headerRow);
        var selectorRow = new WrapPanel { Orientation = Orientation.Horizontal };
        selectorRow.Children.Add(new TextBlock
        {
            Text = fieldLabel + ":",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 0, 8, 0)
        });
        section.Children.Add(selectorRow);
        var chips = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(6, 0, 0, 0) };

        AutoCompleteBox? picker = null;
        void RefreshPickerSuggestions()
        {
            if (picker == null)
                return;
            var used = rows
                .Select(row => ReadTextLikeControlValue(row.ValueTb))
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            picker.ItemsSource = suggestions.Where(value => !used.Contains(value)).ToList();
        }

        void AddChip(string value)
        {
            var normalized = value?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(normalized) ||
                rows.Any(row => ReadTextLikeControlValue(row.ValueTb).Equals(normalized, StringComparison.OrdinalIgnoreCase)))
            {
                return;
            }

            var valueControl = new AutoCompleteBox { Text = normalized };
            ConfigureStrictSuggestionAutoComplete(valueControl, suggestions, normalized);
            var rowState = new ProtoActionStructuredFieldRowState
            {
                Tag = tag,
                RowPanel = chips,
                ValueTb = valueControl,
                IncludeInSerialization = true
            };
            rows.Add(rowState);
            var tacticsValues = TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction)
                ? usesNestedUnitTypeContainer
                    ? GetProtoActionNestedUnitTypeValues(tacticsAction, tag)
                    : ProtoXmlHandler.GetProtoActionStructuredFieldEntries(tacticsAction, tag)
                        .Select(entry => entry.Value?.Trim() ?? "")
                        .Where(entryValue => !string.IsNullOrWhiteSpace(entryValue))
                        .ToList()
                : [];
            var isInherited = tacticsValues.Contains(normalized, StringComparer.OrdinalIgnoreCase);
            Border? chip = null;
            chip = CreateChip(normalized, async () =>
            {
                if (!await CheckStartLocalMod())
                    return;
                if (isInherited)
                {
                    await new Prompt(
                        PromptType.Error,
                        "Inherited Attribute",
                        $"Unit Type '{normalized}' is defined by the linked tactics file and cannot be deleted from the protoaction.")
                        .ShowDialog(this);
                    return;
                }
                rows.Remove(rowState);
                if (chip != null)
                    chips.Children.Remove(chip);
                RefreshPickerSuggestions();
                if (rows.Count == 0)
                {
                    state.ForcedVisibleFieldTags.Remove(tag);
                    if (usesNestedUnitTypeContainer)
                        SaveProtoActionNestedUnitTypeListElement(state.Model, tag, []);
                    else
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, tag, []);
                    RefreshProtoActionMetadataPanels(state);
                }
                MarkDirty();
                CommitChipAdditionAndRefreshXmlPreview();
            },
                isInherited ? ProtoActionValueSource.TacticsInherited : ProtoActionValueSource.ProtoOnly,
                isInherited ? normalized : "");
            chips.Children.Add(chip);
            RefreshPickerSuggestions();
        }

        if (!_isReadOnly)
        {
            picker = new AutoCompleteBox
            {
                FilterMode = AutoCompleteFilterMode.Contains,
                Width = 100,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            EditorTextFieldStyle.ConfigureSelector(picker);
            picker.Width = 100;
            picker.MinWidth = 100;
            picker.MaxWidth = 100;
            ConfigureStrictSuggestionAutoComplete(picker, suggestions, "");
            FreezeEditorScrollWhileDropDownIsOpen(picker, _editorScroll);
            picker.SelectionChanged += async (_, _) =>
            {
                if (_isPopulating || picker.SelectedItem is not string selectedValue || !await CheckStartLocalMod())
                    return;
                AddChip(selectedValue);
                picker.Text = "";
                picker.SelectedItem = null;
                RefreshPickerSuggestions();
                MarkDirty();
                CommitChipAdditionAndRefreshXmlPreview();
            };
            selectorRow.Children.Add(picker);
        }

        selectorRow.Children.Add(chips);

        foreach (var value in initialValues.Where(value => !string.IsNullOrWhiteSpace(value)).Distinct(StringComparer.OrdinalIgnoreCase))
            AddChip(value);
        destination.Children.Add(section);
        RefreshPickerSuggestions();
    }

    private void RenderProtoActionOptionalFields(
        ProtoActionWidgetState state,
        Dictionary<string, string> currentSimpleValues,
        Dictionary<string, List<ProtoActionStructuredFieldEntry>> currentStructuredValues)
    {
        var effectiveAction = CreateEffectiveProtoActionSnapshot(state);
        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        var showOptionalModelAttachmentFields = ShouldShowOptionalModelAttachmentFields(state, actionType, effectiveAction, currentSimpleValues);
        var visibleSimpleTags = GetVisibleProtoActionSimpleFieldTags(state, effectiveAction, actionType);
        var visibleStructuredTags = GetVisibleProtoActionStructuredFieldTags(state, effectiveAction, actionType);
        var hasDamageAreaData = OptionalAbductDamageAreaTags.Any(tag =>
            state.ForcedVisibleFieldTags.Contains(tag) ||
            (currentSimpleValues.TryGetValue(tag, out var currentValue) && !string.IsNullOrWhiteSpace(currentValue)) ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag)));
        var suggestedSimpleTags = GetSuggestedProtoActionSimpleFieldTags(actionType);
        if (IsRampageActionType(actionType))
        {
            foreach (var optionalTag in new[] { "maxsizeclass", "projectile" })
            {
                if (visibleSimpleTags.Contains(optionalTag, StringComparer.OrdinalIgnoreCase) &&
                    !suggestedSimpleTags.Contains(optionalTag, StringComparer.OrdinalIgnoreCase))
                {
                    suggestedSimpleTags.Add(optionalTag);
                }
            }
        }
        var suggestedStructuredTags = GetSuggestedProtoActionStructuredFieldTags(actionType);
        var showAdditionalGatheringTypes = !IsAutoGatherActionType(actionType) &&
            visibleStructuredTags.Contains("donotautogatherunlessgatheringtypes", StringComparer.OrdinalIgnoreCase);
        var additionalChipTags = visibleStructuredTags
            .Where(tag => tag.Equals("forbidabstracttype", StringComparison.OrdinalIgnoreCase) ||
                          tag.Equals("forbidunittype", StringComparison.OrdinalIgnoreCase))
            .Where(tag => !IsAutoRangedModifyActionType(actionType))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        var additionalSimpleTags = visibleSimpleTags
            .Where(x => !suggestedSimpleTags.Contains(x, StringComparer.OrdinalIgnoreCase) ||
                        (x.Equals("maxrange", StringComparison.OrdinalIgnoreCase) &&
                         state.CustomValues.GetValueOrDefault("additional.maxrange") == "1") ||
                        (x.Equals("rof", StringComparison.OrdinalIgnoreCase) &&
                         state.CustomValues.GetValueOrDefault("additional.rof") == "1"))
            .Where(x => !IsActionCardManagedOptionalFieldTag(actionType, x))
            .Where(x => !(hasDamageAreaData &&
                          OptionalAbductDamageAreaTags.Contains(x, StringComparer.OrdinalIgnoreCase)))
            .Where(x => !(showOptionalModelAttachmentFields &&
                          OptionalModelAttachmentTags.Contains(x, StringComparer.OrdinalIgnoreCase)))
            .ToList();
        var additionalStructuredTags = visibleStructuredTags
            .Where(x => !suggestedStructuredTags.Contains(x, StringComparer.OrdinalIgnoreCase))
            .Where(x => !IsActionCardManagedOptionalFieldTag(actionType, x))
            .Where(x => !IsAutoConvertManagedStructuredFieldTag(actionType, x))
            .Where(x => !x.Equals("charged", StringComparison.OrdinalIgnoreCase))
            .Where(x => !x.Equals("donotautogatherunlessgatheringtypes", StringComparison.OrdinalIgnoreCase))
            .Where(x => !additionalChipTags.Contains(x))
            .ToList();
        var pickerOptions = GetAvailableProtoActionAttributePickerOptions(state);

        state.OptionalFieldsContainer.Children.Clear();

        if (additionalSimpleTags.Count == 0 && additionalStructuredTags.Count == 0 && _isReadOnly)
            return;

        state.OptionalFieldsContainer.Children.Add(new TextBlock
        {
            Text = "Additional Attributes",
            FontWeight = FontWeight.Bold,
            Margin = new Thickness(0, 6, 0, 2)
        });

        if (!_isReadOnly)
        {
            var pickerHost = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
            var addButton = new Button
            {
                Content = "Add Attribute From Full List",
                Classes = { "add-component" },
                HorizontalAlignment = HorizontalAlignment.Left
            };
            pickerHost.Children.Add(addButton);

            string? selectedAttributeLabel = null;
            addButton.Click += (s, e) =>
            {
                if (pickerHost.Children.Count > 1)
                    return;

                var pickerRow = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("200, Auto"),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                var optionLabels = pickerOptions.Select(x => x.Label).ToList();
                var pickerAcb = new AutoCompleteBox
                {
                    FilterMode = AutoCompleteFilterMode.Contains,
                    ItemsSource = optionLabels,
                    MinimumPrefixLength = 0,
                    MinimumPopulateDelay = TimeSpan.Zero,
                    Width = 200,
                    IsEnabled = !_isReadOnly
                };
                EditorTextFieldStyle.ConfigureSelector(pickerAcb);
                pickerAcb.Width = 200;
                pickerAcb.MinWidth = 200;
                pickerAcb.MaxWidth = 200;
                EnableDropdownAutoComplete(pickerAcb, selectAllOnFirstClick: false);
                FreezeEditorScrollWhileDropDownIsOpen(pickerAcb, _editorScroll);
                Grid.SetColumn(pickerAcb, 0);
                pickerRow.Children.Add(pickerAcb);

                async void PerformAdd()
                {
                    var input = pickerAcb.Text?.Trim() ?? "";
                    var match = optionLabels.FirstOrDefault(x => x.Equals(input, StringComparison.OrdinalIgnoreCase))
                        ?? optionLabels.FirstOrDefault(x => x.Equals(selectedAttributeLabel, StringComparison.OrdinalIgnoreCase));
                    if (string.IsNullOrWhiteSpace(match))
                        return;

                    var option = pickerOptions.FirstOrDefault(x => x.Label.Equals(match, StringComparison.OrdinalIgnoreCase));
                    if (string.IsNullOrWhiteSpace(option.Tag))
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        state.ForcedVisibleFieldTags.Add(option.Tag);
                        if (option.Tag.Equals("maxrange", StringComparison.OrdinalIgnoreCase))
                            state.CustomValues["additional.maxrange"] = "1";
                        if (option.Tag.Equals("rof", StringComparison.OrdinalIgnoreCase))
                            state.CustomValues["additional.rof"] = "1";
                        if (option.Tag.Equals("areasortmode", StringComparison.OrdinalIgnoreCase))
                            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, option.Tag, "Radial");
                        if (IsRampageActionType(actionType) && option.Tag.Equals("projectile", StringComparison.OrdinalIgnoreCase))
                            state.CustomValues.Remove("rampage.projectile.hidden");
                        RefreshProtoActionMetadataPanels(state);
                        MarkDirty();
                    }
                }

                pickerAcb.SelectionChanged += (s, e) =>
                {
                    if (pickerAcb.SelectedItem is string selected)
                    {
                        selectedAttributeLabel = selected;
                        pickerAcb.Text = selected;
                        PerformAdd();
                    }
                };

                var closeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 0, 0, 0)
                };
                closeButton.Click += (s, e) => pickerHost.Children.Remove(pickerRow);
                Grid.SetColumn(closeButton, 1);
                pickerRow.Children.Add(closeButton);
                pickerHost.Children.Add(pickerRow);
                Dispatcher.UIThread.Post(() => pickerAcb.Focus(), DispatcherPriority.Background);
            };

            state.OptionalFieldsContainer.Children.Add(pickerHost);
        }

        foreach (var tag in additionalSimpleTags)
        {
            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
            var rawValue = currentSimpleValues.TryGetValue(tag, out var editedValue)
                ? editedValue
                : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, tag);
            var value = GetProtoActionDefaultSimpleValue(tag, rawValue);

            var rowGrid = new Grid
            {
                ColumnDefinitions = !_isReadOnly && CanRemoveProtoActionAdditionalField(actionType, tag)
                    ? new ColumnDefinitions("Auto, Auto, Auto")
                    : new ColumnDefinitions("Auto, Auto"),
                Margin = new Thickness(0, 2, 0, 2),
                HorizontalAlignment = HorizontalAlignment.Left
            };

            rowGrid.Children.Add(new TextBlock
            {
                Text = definition.Label + ":",
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 4, 8, 4)
            });

            Control editor;
            if (tag.Equals("areasortmode", StringComparison.OrdinalIgnoreCase))
            {
                var areaSortModes = new[] { "Radial", "Directional" };
                editor = new ComboBox
                {
                    ItemsSource = areaSortModes,
                    SelectedItem = areaSortModes.FirstOrDefault(option => option.Equals(value, StringComparison.OrdinalIgnoreCase)) ?? "Radial",
                    Width = 120,
                    IsEnabled = !_isReadOnly
                };
            }
            else if (tag.Equals("castpowertargettype", StringComparison.OrdinalIgnoreCase))
            {
                var targetSuggestions = GetKnownUnitTypeNames()
                    .Concat(GetAvailableTrainUnitNames())
                    .Where(option => !string.IsNullOrWhiteSpace(option))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(option => option, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                var initialTarget = string.IsNullOrWhiteSpace(value) ? "Unit" : value;
                var targetEditor = new AutoCompleteBox
                {
                    Text = initialTarget,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    Width = 200,
                    IsEnabled = !_isReadOnly
                };
                EditorTextFieldStyle.ConfigureSelector(targetEditor);
                ConfigureStrictSuggestionAutoComplete(targetEditor, targetSuggestions, initialTarget);
                editor = targetEditor;
            }
            else if (tag.Equals("displaynameid", StringComparison.OrdinalIgnoreCase))
            {
                var displayNameEditor = new TextBox
                {
                    Text = value,
                    Width = 200,
                    IsEnabled = !_isReadOnly
                };
                EditorTextFieldStyle.ConfigureTextBox(displayNameEditor);
                state.CustomValues["displaynameid.stringid"] = value;
                _ = PopulateProtoActionDisplayNameOverrideAsync(state, displayNameEditor, value);
                editor = displayNameEditor;
            }
            else if (tag.Equals("modifydamagetype", StringComparison.OrdinalIgnoreCase))
            {
                var options = ProtoConstants.KnownDamageTypes;
                editor = new ComboBox
                {
                    ItemsSource = options,
                    SelectedItem = options.FirstOrDefault(option => option.Equals(value, StringComparison.OrdinalIgnoreCase)),
                    Width = 120,
                    IsEnabled = !_isReadOnly
                };
            }
            else if (tag.Equals("modifyresourcesubtype", StringComparison.OrdinalIgnoreCase))
            {
                var options = GetKnownResourceSubtypeNames();
                editor = new ComboBox
                {
                    ItemsSource = options,
                    SelectedItem = options.FirstOrDefault(option => option.Equals(value, StringComparison.OrdinalIgnoreCase)),
                    Width = 150,
                    IsEnabled = !_isReadOnly
                };
            }
            else if (tag.Equals("landanim", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("wateranim", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("splashvfxproto", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("modifydamagetargettype", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("restrictempowertype", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("modifyciv", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("modifytype", StringComparison.OrdinalIgnoreCase))
            {
                var suggestions = GetProtoActionValueSuggestions(tag) ?? [];
                var initialValue = tag.Equals("modifytype", StringComparison.OrdinalIgnoreCase)
                    ? ProtoConstants.GetModifyTypeDisplayName(ProtoConstants.GetModifyTypeValue(value))
                    : value;
                var strictEditor = new AutoCompleteBox
                {
                    Text = initialValue,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    Width = 200,
                    IsEnabled = !_isReadOnly
                };
                ConfigureStrictSuggestionAutoComplete(strictEditor, suggestions, initialValue);
                FreezeEditorScrollWhileDropDownIsOpen(strictEditor, _editorScroll);
                editor = strictEditor;
            }
            else
            {
                editor = GetProtoActionValueSuggestions(tag) is List<string> suggestions
                    ? new AutoCompleteBox
                    {
                        Text = value,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = suggestions,
                        IsEnabled = !_isReadOnly
                    }
                    : new TextBox
                    {
                        Text = value,
                        IsEnabled = !_isReadOnly
                    };
            }
            if (editor is TextBox numericEditorTextBox && definition.EditorKind == ProtoActionFieldEditorKind.Number)
                AttachProtoActionNumberBehavior(numericEditorTextBox, tag);
            else if (AssetPathFieldTags.Contains(tag) && editor is TextBox assetTextBox)
            {
                EditorTextFieldStyle.ConfigureTextBox(assetTextBox);
            }
            else if (editor is TextBox textBox)
                EditorTextFieldStyle.ConfigureTextBox(textBox);
            if (editor is AutoCompleteBox editorAcb)
            {
                if (AssetPathFieldTags.Contains(tag))
                    EditorTextFieldStyle.ConfigureSelector(editorAcb);
                else
                    EditorTextFieldStyle.ConfigureSelector(editorAcb);
                ConfigureProtoActionValueAutoComplete(editorAcb, tag, value);
            }

            if (AssetPathFieldTags.Contains(tag))
                editor = CreateAssetPathEditor(tag, value, GetProtoActionValueSuggestions(tag) ?? []);

            if (definition.EditorKind != ProtoActionFieldEditorKind.Number && editor is not ComboBox)
            {
                editor.Width = 200;
                editor.MinWidth = 200;
                editor.MaxWidth = 200;
            }
            ApplyProtoActionFieldWidth(editor, tag);

            if (!AssetPathFieldTags.Contains(tag) && editor is TextBox editorTb)
            {
                editorTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating &&
                        !(tag.Equals("displaynameid", StringComparison.OrdinalIgnoreCase) &&
                          state.CustomValues.ContainsKey("displaynameid.resolving")))
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
            }
            else if (!AssetPathFieldTags.Contains(tag) && editor is AutoCompleteBox editorAutoComplete)
            {
                editorAutoComplete.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
            }
            else if (!AssetPathFieldTags.Contains(tag) && editor is ComboBox editorComboBox)
            {
                editorComboBox.SelectionChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
            }

            Grid.SetColumn(editor, 1);
            rowGrid.Children.Add(editor);
            state.AdditionalFieldControls[tag] = editor;

            if (!_isReadOnly && CanRemoveProtoActionAdditionalField(actionType, tag))
            {
                var removeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 0, 0, 0),
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeButton.Click += async (s, e) =>
                {
                    if (await BlockInheritedProtoActionRemovalAsync(state, [tag], definition.Label))
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        state.ForcedVisibleFieldTags.Remove(tag);
                        if (tag.Equals("maxrange", StringComparison.OrdinalIgnoreCase))
                            state.CustomValues.Remove("additional.maxrange");
                        if (tag.Equals("rof", StringComparison.OrdinalIgnoreCase))
                            state.CustomValues.Remove("additional.rof");
                        state.AdditionalFieldControls.Remove(tag);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, tag, "");
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    }
                };
                Grid.SetColumn(removeButton, 2);
                rowGrid.Children.Add(removeButton);
            }

            state.OptionalFieldsContainer.Children.Add(rowGrid);
        }

        if (showAdditionalGatheringTypes)
        {
            var gatheringTypeValues = currentStructuredValues.TryGetValue(
                "donotautogatherunlessgatheringtypes",
                out var editedGatheringTypes)
                ? editedGatheringTypes.Select(entry => entry.Value)
                : GetProtoActionNestedUnitTypeValues(effectiveAction, "donotautogatherunlessgatheringtypes");
            RenderAdditionalGatheringTypeChips(state, gatheringTypeValues, state.OptionalFieldsContainer);
        }

        foreach (var tag in additionalChipTags)
        {
            var values = currentStructuredValues.TryGetValue(tag, out var editedValues)
                ? editedValues.Select(entry => entry.Value)
                : GetProtoActionStructuredFieldEntriesForEditor(effectiveAction, actionType, tag).Select(entry => entry.Value);
            var suggestions = tag.Equals("forbidabstracttype", StringComparison.OrdinalIgnoreCase)
                ? GetKnownUnitTypeNames()
                : GetAvailableTrainUnitNames();
            RenderAdditionalStructuredValueChips(
                state,
                tag,
                ProtoActionMetadataCatalog.GetFieldDefinition(tag).Label,
                "Unit Type",
                suggestions,
                values,
                state.OptionalFieldsContainer);
        }

        foreach (var tag in additionalStructuredTags)
        {
            var definition = ProtoActionMetadataCatalog.GetFieldDefinition(tag);
            var entries = currentStructuredValues.TryGetValue(tag, out var editedEntries)
                ? editedEntries
                : GetProtoActionStructuredFieldEntriesForEditor(effectiveAction, actionType, tag);

            var section = new StackPanel { Spacing = 4, Margin = new Thickness(0, 0, 0, 6) };
            var sectionHeader = new Grid
            {
                ColumnDefinitions = !_isReadOnly ? new ColumnDefinitions("*, Auto") : new ColumnDefinitions("*")
            };
            sectionHeader.Children.Add(new TextBlock
            {
                Text = definition.Label + ":",
                FontWeight = FontWeight.SemiBold
            });
            if (!_isReadOnly)
            {
                var removeButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(8, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                removeButton.Click += async (s, e) =>
                {
                    if (await BlockInheritedStructuredProtoActionRemovalAsync(state, tag, definition.Label))
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        state.ForcedVisibleFieldTags.Remove(tag);
                        state.StructuredFieldRows.Remove(tag);
                        ProtoXmlHandler.SetProtoActionStructuredFieldEntries(state.Model, tag, []);
                        MarkDirty();
                        RefreshProtoActionMetadataPanels(state);
                    }
                };
                Grid.SetColumn(removeButton, 1);
                sectionHeader.Children.Add(removeButton);
            }
            section.Children.Add(sectionHeader);

            var rowsContainer = new StackPanel { Spacing = 4 };
            section.Children.Add(rowsContainer);
            state.StructuredFieldRows[tag] = [];

            void AddRow(ProtoActionStructuredFieldEntry? initialEntry = null)
            {
                ProtoActionStructuredFieldEntry? inheritedEntry = null;
                if ((tag.Equals("rate", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("typedmaxrange", StringComparison.OrdinalIgnoreCase) ||
                     tag.Equals("minrate", StringComparison.OrdinalIgnoreCase)) &&
                    initialEntry != null &&
                    TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction))
                {
                    var initialType = initialEntry.Attributes.TryGetValue("type", out var typeValue) ? typeValue.Trim() : "";
                    inheritedEntry = GetProtoActionStructuredFieldEntriesForEditor(tacticsAction, actionType, tag)
                        .FirstOrDefault(entry => entry.Attributes.TryGetValue("type", out var candidateType) &&
                                                 candidateType.Equals(initialType, StringComparison.OrdinalIgnoreCase));
                }
                var isInheritedRateType = inheritedEntry != null;

                var rowPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 6
                };

                var rowState = new ProtoActionStructuredFieldRowState
                {
                    Tag = tag,
                    RowPanel = rowPanel,
                    ValueTb = GetProtoActionValueSuggestions(tag) is List<string> suggestions
                        ? new AutoCompleteBox
                        {
                            Text = string.IsNullOrWhiteSpace(initialEntry?.Value) && tag.Equals("rate", StringComparison.OrdinalIgnoreCase)
                                ? "1.0"
                                : initialEntry?.Value ?? "",
                            Width = 140,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            ItemsSource = suggestions,
                            IsEnabled = !_isReadOnly
                        }
                        : new TextBox
                        {
                            Text = string.IsNullOrWhiteSpace(initialEntry?.Value) && tag.Equals("rate", StringComparison.OrdinalIgnoreCase)
                                ? "1.0"
                                : initialEntry?.Value ?? "",
                            Width = 100,
                            IsEnabled = !_isReadOnly
                        }
                };
                if (rowState.ValueTb is TextBox valueTextBox)
                    AttachProtoActionDecimalBehavior(valueTextBox);
                else if (rowState.ValueTb is AutoCompleteBox valueAutoCompleteBox)
                {
                    ConfigureProtoActionValueAutoComplete(valueAutoCompleteBox, tag, initialEntry?.Value ?? "");
                }
                ApplyProtoActionFieldWidth(rowState.ValueTb, tag);

                if (rowState.ValueTb is TextBox rowValueTb)
                {
                    rowValueTb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed) MarkDirty();
                        }
                    };
                }
                else if (rowState.ValueTb is AutoCompleteBox rowValueAcb)
                {
                    rowValueAcb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed) MarkDirty();
                        }
                    };
                }

                var attributeNames = definition.XmlAttributeNames?.ToList() ?? [];
                var orderedAttributeNames = new List<string>();
                if (attributeNames.Any(x => x.Equals("type", StringComparison.OrdinalIgnoreCase)))
                    orderedAttributeNames.Add(attributeNames.First(x => x.Equals("type", StringComparison.OrdinalIgnoreCase)));
                orderedAttributeNames.AddRange(attributeNames.Where(attributeName =>
                    !attributeName.Equals("type", StringComparison.OrdinalIgnoreCase) &&
                    !(tag.Equals("minrate", StringComparison.OrdinalIgnoreCase) &&
                      attributeName.Equals("resource", StringComparison.OrdinalIgnoreCase)) &&
                    !(tag.Equals("rate", StringComparison.OrdinalIgnoreCase) &&
                      attributeName is "resource" or "yield" or "overrideResource" or "inventoryRate")));

                bool valueAdded = false;
                void AddValueEditor()
                {
                    if (valueAdded)
                        return;

                    rowPanel.Children.Add(new TextBlock { Text = GetProtoActionStructuredValueLabel(tag), VerticalAlignment = VerticalAlignment.Center });
                    rowPanel.Children.Add(rowState.ValueTb);
                    valueAdded = true;
                }

                var attributeLabels = new Dictionary<string, TextBlock>(StringComparer.OrdinalIgnoreCase);
                foreach (var attributeName in orderedAttributeNames)
                {
                    var attributeLabel = new TextBlock
                    {
                        Text = tag.Equals("conversionprotoid", StringComparison.OrdinalIgnoreCase) &&
                               attributeName.Equals("srctype", StringComparison.OrdinalIgnoreCase)
                            ? "Source:"
                            : attributeName.Equals("type", StringComparison.OrdinalIgnoreCase)
                            ? "Type:"
                            : attributeName.Equals("class", StringComparison.OrdinalIgnoreCase) &&
                              tag.Equals("sizeclassanim", StringComparison.OrdinalIgnoreCase)
                                ? "Size Class:"
                                : attributeName + ":",
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    attributeLabels[attributeName] = attributeLabel;
                    rowPanel.Children.Add(attributeLabel);

                    var attributeValue = initialEntry != null && initialEntry.Attributes.TryGetValue(attributeName, out var existingAttributeValue)
                        ? existingAttributeValue
                        : "";
                    if (tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase) &&
                        attributeName.Equals("type", StringComparison.OrdinalIgnoreCase))
                    {
                        attributeValue = GetProtoActionStructuredAttributeSuggestions(tag, attributeName)?
                            .FirstOrDefault(option => option.Replace(" ", "", StringComparison.Ordinal)
                                .Equals(attributeValue, StringComparison.OrdinalIgnoreCase)) ?? attributeValue;
                    }
                    var attributeSuggestions = GetProtoActionStructuredAttributeSuggestions(tag, attributeName);
                    Control attributeEditor;
                    if (tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase) &&
                        attributeName.Equals("type", StringComparison.OrdinalIgnoreCase) &&
                        attributeSuggestions != null)
                    {
                        var attributeCombo = new ComboBox
                        {
                            ItemsSource = attributeSuggestions,
                            SelectedItem = attributeSuggestions.FirstOrDefault(option => option.Equals(attributeValue, StringComparison.OrdinalIgnoreCase))
                                           ?? attributeSuggestions.FirstOrDefault(),
                            Width = 180,
                            IsEnabled = !_isReadOnly
                        };
                        attributeCombo.SelectionChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };
                        attributeEditor = attributeCombo;
                    }
                    else if (attributeSuggestions != null)
                    {
                        var attributeAcb = new AutoCompleteBox
                        {
                            Text = attributeValue,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            Width = tag.Equals("conversionprotoid", StringComparison.OrdinalIgnoreCase) ? 200 : 150,
                            IsEnabled = !_isReadOnly
                        };
                        ConfigureStrictSuggestionAutoComplete(attributeAcb, attributeSuggestions, attributeValue);
                        attributeAcb.TextChanged += async (s, e) =>
                        {
                            if (!_isPopulating)
                            {
                                var proceed = await CheckStartLocalMod();
                                if (proceed) MarkDirty();
                            }
                        };
                        attributeEditor = attributeAcb;
                    }
                    else
                    {
                        var attributeTextBox = new TextBox
                        {
                            Text = attributeValue,
                            Width = 110,
                            IsEnabled = !_isReadOnly
                        };
                        attributeTextBox.TextChanged += async (s, e) =>
                        {
                            if (!_isPopulating)
                            {
                                var proceed = await CheckStartLocalMod();
                                if (proceed) MarkDirty();
                            }
                        };
                        attributeEditor = attributeTextBox;
                        if (tag.Equals("sizeclassanim", StringComparison.OrdinalIgnoreCase) &&
                            attributeName.Equals("class", StringComparison.OrdinalIgnoreCase))
                        {
                            AttachProtoActionIntegerBehavior(attributeTextBox);
                        }
                    }

                    var isInheritedRateTypeEditor =
                        isInheritedRateType &&
                        attributeName.Equals("type", StringComparison.OrdinalIgnoreCase);
                    if (isInheritedRateTypeEditor)
                        attributeEditor.IsEnabled = false;

                    rowState.AttributeEditors[attributeName] = attributeEditor;
                    rowPanel.Children.Add(attributeEditor);

                    if (attributeName.Equals("type", StringComparison.OrdinalIgnoreCase))
                    {
                        if (isInheritedRateType)
                            AddProtoActionSourceMarker(state, attributeEditor, ProtoActionValueSource.TacticsInherited, attributeValue);
                        AddValueEditor();
                    }
                }

                if (tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase) &&
                    rowState.AttributeEditors.TryGetValue("type", out var ruleTypeEditor) &&
                    rowState.AttributeEditors.TryGetValue("actiontype", out var ruleActionTypeEditor) &&
                    attributeLabels.TryGetValue("actiontype", out var ruleActionTypeLabel))
                {
                    void RefreshRuleActionTypeVisibility()
                    {
                        var isOnAction = ReadProtoActionStructuredAttributeValue(ruleTypeEditor)
                            .Replace(" ", "", StringComparison.Ordinal)
                            .Equals("OnAction", StringComparison.OrdinalIgnoreCase);
                        ruleActionTypeLabel.IsVisible = isOnAction;
                        ruleActionTypeEditor.IsVisible = isOnAction;
                    }

                    if (ruleTypeEditor is ComboBox ruleTypeCombo)
                        ruleTypeCombo.SelectionChanged += (_, _) => RefreshRuleActionTypeVisibility();
                    RefreshRuleActionTypeVisibility();
                }

                AddValueEditor();

                Button? rowDeleteButton = null;
                void AddOptionalAttribute(string attributeName, string buttonLabel, bool useResourceCombo)
                {
                    Button? addAttributeButton = null;
                    void ShowEditor(string initialValue, int insertIndex)
                    {
                        if (addAttributeButton != null)
                            rowPanel.Children.Remove(addAttributeButton);

                        var attributeLabel = new TextBlock
                        {
                            Text = buttonLabel + ":",
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(insertIndex > 0 ? 8 : 0, 0, 0, 0)
                        };
                        Control attributeEditor;
                        if (useResourceCombo)
                        {
                            var options = ProtoConstants.KnownResourceTypes
                                .Concat(string.IsNullOrWhiteSpace(initialValue) ? [] : new[] { initialValue })
                                .Distinct(StringComparer.OrdinalIgnoreCase)
                                .ToList();
                            var comboBox = new ComboBox
                            {
                                ItemsSource = options,
                                SelectedItem = options.FirstOrDefault(option => option.Equals(initialValue, StringComparison.OrdinalIgnoreCase)),
                                Width = 100,
                                IsEnabled = !_isReadOnly
                            };
                            comboBox.SelectionChanged += async (_, _) =>
                            {
                                if (!_isPopulating && await CheckStartLocalMod())
                                    MarkDirty();
                            };
                            attributeEditor = comboBox;
                        }
                        else
                        {
                            var textBox = new TextBox
                            {
                                Text = initialValue,
                                Width = 100,
                                IsEnabled = !_isReadOnly
                            };
                            AttachProtoActionDecimalBehavior(textBox);
                            textBox.TextChanged += async (_, _) =>
                            {
                                if (!_isPopulating && await CheckStartLocalMod())
                                    MarkDirty();
                            };
                            attributeEditor = textBox;
                        }

                        rowState.AttributeEditors[attributeName] = attributeEditor;
                        insertIndex = Math.Clamp(insertIndex, 0, rowPanel.Children.Count);
                        rowPanel.Children.Insert(insertIndex, attributeLabel);
                        rowPanel.Children.Insert(insertIndex + 1, attributeEditor);

                        if (!_isReadOnly)
                        {
                            var removeAttributeButton = new Button
                            {
                                Classes = { "remove-button" },
                                Margin = new Thickness(2, 0, 0, 0),
                                VerticalAlignment = VerticalAlignment.Center
                            };
                            removeAttributeButton.Click += async (_, _) =>
                            {
                                if (!await CheckStartLocalMod())
                                    return;
                                var restoreIndex = rowPanel.Children.IndexOf(attributeLabel);
                                rowState.AttributeEditors.Remove(attributeName);
                                rowPanel.Children.Remove(attributeLabel);
                                rowPanel.Children.Remove(attributeEditor);
                                rowPanel.Children.Remove(removeAttributeButton);
                                rowPanel.Children.Insert(Math.Clamp(restoreIndex, 0, rowPanel.Children.Count), addAttributeButton!);
                                MarkDirty();
                            };
                            rowPanel.Children.Insert(insertIndex + 2, removeAttributeButton);
                        }
                    }

                    addAttributeButton = new Button
                    {
                        Content = buttonLabel,
                        Classes = { "add-component" },
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    addAttributeButton.Click += async (_, _) =>
                    {
                        if (await CheckStartLocalMod())
                        {
                            var insertIndex = rowPanel.Children.IndexOf(addAttributeButton);
                            ShowEditor("", insertIndex < 0 ? rowPanel.Children.Count : insertIndex);
                            MarkDirty();
                        }
                    };
                    var initialValue = initialEntry?.Attributes.GetValueOrDefault(attributeName) ?? "";
                    if (string.IsNullOrWhiteSpace(initialValue))
                        rowPanel.Children.Add(addAttributeButton);
                    else
                        ShowEditor(initialValue, rowPanel.Children.Count);
                }

                if (tag.Equals("minrate", StringComparison.OrdinalIgnoreCase))
                    AddOptionalAttribute("resource", "Resource", useResourceCombo: true);
                else if (tag.Equals("rate", StringComparison.OrdinalIgnoreCase))
                {
                    AddOptionalAttribute("resource", "Resource", useResourceCombo: true);
                    AddOptionalAttribute("yield", "Yield", useResourceCombo: false);
                    AddOptionalAttribute("overrideResource", "Override Resource", useResourceCombo: true);
                    AddOptionalAttribute("inventoryRate", "Inventory Rate", useResourceCombo: false);
                }

                if (!_isReadOnly && !tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase))
                {
                    rowDeleteButton = new Button
                    {
                        Classes = { "remove-button" },
                        VerticalAlignment = VerticalAlignment.Center
                    };
                    rowDeleteButton.Click += async (s, e) =>
                    {
                        if (isInheritedRateType)
                        {
                            var inheritedType = initialEntry?.Attributes.TryGetValue("type", out var typeValue) == true ? typeValue : "Rate";
                            await new Prompt(
                                PromptType.Error,
                                "Inherited Attribute",
                                $"Rate type '{inheritedType}' is defined by the linked tactics file and cannot be removed. You may override its value.")
                                .ShowDialog(this);
                            return;
                        }

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            state.StructuredFieldRows[tag].Remove(rowState);
                            rowsContainer.Children.Remove(rowPanel);
                            MarkDirty();
                        }
                    };
                    rowPanel.Children.Add(rowDeleteButton);
                }

                state.StructuredFieldRows[tag].Add(rowState);
                rowsContainer.Children.Add(rowPanel);
            }

            foreach (var entry in entries.Take(tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase) ? 1 : int.MaxValue))
                AddRow(entry);

            if (entries.Count == 0 && tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase))
                AddRow(new ProtoActionStructuredFieldEntry { Value = "1.0" });

            if (!_isReadOnly && !tag.Equals("conditionaltransformrule", StringComparison.OrdinalIgnoreCase))
            {
                var addButton = new Button
                {
                    Content = "Add " + definition.Label,
                    Classes = { "add-component" },
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                addButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        AddRow();
                        MarkDirty();
                    }
                };
                section.Children.Add(addButton);
            }

            state.OptionalFieldsContainer.Children.Add(section);
        }

        if (!IsBolsterActionType(actionType) &&
            !IsRampageActionType(actionType) &&
            !IsChargedModifyActionType(actionType) &&
            (state.ForcedVisibleFieldTags.Contains("charged") || state.FullChargedRows.Count > 0))
        {
            var chargedControls = state.AdditionalFieldsContainer.Children
                .Where(control => string.Equals(control.Tag as string, "protoaction.charged", StringComparison.OrdinalIgnoreCase))
                .ToList();
            foreach (var chargedControl in chargedControls)
            {
                state.AdditionalFieldsContainer.Children.Remove(chargedControl);
                state.OptionalFieldsContainer.Children.Add(chargedControl);
            }
        }

        var nativeEmpowerLayout = IsEmpowerActionType(actionType) ||
                                  (IsAutoRangedModifyActionType(actionType) &&
                                   state.AdditionalFieldControls.TryGetValue("modifytype", out var modifyTypeEditor) &&
                                   ProtoConstants.GetModifyTypeValue(ReadTextLikeControlValue(modifyTypeEditor))
                                       .Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase));
        var additionalComplexControlTags = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (!IsStackControlActionType(actionType))
            additionalComplexControlTags.Add("protoaction.additional.stackcontrol");
        if (!nativeEmpowerLayout)
        {
            foreach (var sectionTag in EmpowerSectionTags)
                additionalComplexControlTags.Add($"protoaction.additional.{sectionTag}");
        }

        var additionalComplexControls = state.AdditionalFieldsContainer.Children
            .Where(control => control.Tag is string controlTag && additionalComplexControlTags.Contains(controlTag))
            .ToList();
        foreach (var complexControl in additionalComplexControls)
        {
            state.AdditionalFieldsContainer.Children.Remove(complexControl);
            state.OptionalFieldsContainer.Children.Add(complexControl);
        }
    }

    private async Task PopulateProtoActionDisplayNameOverrideAsync(
        ProtoActionWidgetState state,
        TextBox editor,
        string stringId)
    {
        if (string.IsNullOrWhiteSpace(stringId))
            return;

        var resolved = _pendingUnitStringUpdates.TryGetValue(stringId, out var pendingText)
            ? pendingText
            : await ResolveDisplayStringAsync(stringId);
        if (string.IsNullOrWhiteSpace(resolved) || editor.Text != stringId)
            return;

        state.CustomValues["displaynameid.resolving"] = "1";
        try
        {
            editor.Text = resolved;
        }
        finally
        {
            state.CustomValues.Remove("displaynameid.resolving");
        }
    }

    private static void RemoveProtoActionAdditionalElement(ProtoAction action, string tag)
        => action.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));

    private static void SetProtoActionAdditionalElement(ProtoAction action, string tag, XElement? element)
    {
        RemoveProtoActionAdditionalElement(action, tag);
        if (element != null)
            action.AdditionalElements.Add(new XElement(element));
    }

    private XElement? BuildEmpowerSectionElement(ProtoActionWidgetState state, string sectionTag)
    {
        if (!state.EmpowerTargetStates.TryGetValue(sectionTag, out var targetStates) || targetStates.Count == 0)
            return null;

        var sectionElement = new XElement(sectionTag);
        var validTargets = GetKnownUnitTypeNames();
        var validAnimations = GetAvailableProtoActionAnimationNames();
        var validBones = GetAvailableProtoActionModelAttachmentBones();

        foreach (var targetState in targetStates)
        {
            var targetName = targetState.TargetAcb.Text?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(targetName))
                continue;

            targetName = validTargets.FirstOrDefault(x => x.Equals(targetName, StringComparison.OrdinalIgnoreCase)) ?? targetName;
            var targetElement = new XElement(targetName);

            targetElement.Add(new XElement("active", targetState.ActiveCb.IsChecked == true ? "1" : "0"));

            var animValue = targetState.AnimAcb.Text?.Trim() ?? "";
            animValue = validAnimations.FirstOrDefault(x => x.Equals(animValue, StringComparison.OrdinalIgnoreCase)) ?? animValue;
            if (!string.IsNullOrWhiteSpace(animValue))
                targetElement.Add(new XElement("anim", animValue));

            var empowerAreaValue = targetState.EmpowerAreaTb.Text?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(empowerAreaValue))
                targetElement.Add(new XElement("empowerarea", empowerAreaValue));

            if (targetState.IsModelAttachmentVisible)
            {
                var modelAttachmentValue = targetState.ModelAttachmentEditor.FullValue;
                if (!string.IsNullOrWhiteSpace(modelAttachmentValue))
                    targetElement.Add(new XElement("modelattachment", modelAttachmentValue));

                var modelAttachmentBoneValue = targetState.ModelAttachmentBoneAcb.Text?.Trim() ?? "";
                modelAttachmentBoneValue = validBones.FirstOrDefault(x => x.Equals(modelAttachmentBoneValue, StringComparison.OrdinalIgnoreCase)) ?? modelAttachmentBoneValue;
                if (!string.IsNullOrWhiteSpace(modelAttachmentBoneValue))
                    targetElement.Add(new XElement("modelattachmentbone", modelAttachmentBoneValue));
            }

            foreach (var forbidTypeAcb in targetState.ForbidTypeAcbs)
            {
                var forbidValue = forbidTypeAcb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(forbidValue))
                    continue;

                forbidValue = validTargets.FirstOrDefault(x => x.Equals(forbidValue, StringComparison.OrdinalIgnoreCase)) ?? forbidValue;
                targetElement.Add(new XElement("forbidunittype", forbidValue));
            }

            foreach (var rateRow in targetState.RateRows)
            {
                var modifyTypeValue = ProtoConstants.GetModifyTypeValue(rateRow.ModifyTypeAcb.Text?.Trim() ?? "");
                var rateValue = rateRow.ValueTb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(modifyTypeValue) || string.IsNullOrWhiteSpace(rateValue))
                    continue;

                var rateElement = new XElement("empowerrate",
                    new XAttribute("modifytype", modifyTypeValue),
                    rateValue);
                if (modifyTypeValue is "DamageSpecific" or "ArmorSpecific")
                {
                    var damageTypeValue = rateRow.DamageTypeCb.SelectedItem?.ToString()?.Trim() ?? "";
                    damageTypeValue = ProtoConstants.KnownDamageTypes.FirstOrDefault(x => x.Equals(damageTypeValue, StringComparison.OrdinalIgnoreCase)) ?? "";
                    if (!string.IsNullOrWhiteSpace(damageTypeValue))
                        rateElement.SetAttributeValue("damagetype", damageTypeValue);
                }
                targetElement.Add(rateElement);
            }

            if (targetElement.HasElements)
                sectionElement.Add(targetElement);
        }

        return sectionElement.HasElements ? sectionElement : null;
    }

    private static bool EmpowerSectionElementsEqual(XElement? left, XElement? right)
    {
        if (left == null && right == null)
            return true;
        if (left == null || right == null)
            return false;

        return XNode.DeepEquals(new XElement(left), new XElement(right));
    }

    private List<XElement> BuildChargedElements(ProtoActionWidgetState state, bool includeEmptyRows = false)
    {
        var elements = new List<XElement>();
        foreach (var row in state.ChargedRows)
        {
            var modifyTypeValue = ProtoConstants.GetModifyTypeValue(row.ModifyTypeAcb.Text?.Trim() ?? "");
            var value = row.ValueTb.Text?.Trim() ?? "";
            if (!includeEmptyRows && (string.IsNullOrWhiteSpace(modifyTypeValue) || string.IsNullOrWhiteSpace(value)))
                continue;

            var chargedModify = new XElement("chargedmodify", value);
            if (!string.IsNullOrWhiteSpace(modifyTypeValue))
                chargedModify.SetAttributeValue("modifytype", modifyTypeValue);

            var applyType = row.ApplyTypeCb.SelectedItem as string ?? row.ApplyTypeCb.SelectedValue?.ToString() ?? "";
            if (!string.IsNullOrWhiteSpace(applyType) && !applyType.Equals("Multiply", StringComparison.OrdinalIgnoreCase))
                chargedModify.SetAttributeValue("applytype", applyType);

            if (modifyTypeValue is "DamageSpecific" or "ArmorSpecific")
            {
                var paramValue = row.ParamCb.SelectedItem?.ToString() ?? "";
                var param = ProtoConstants.KnownDamageTypes.FirstOrDefault(x => x.Equals(paramValue, StringComparison.OrdinalIgnoreCase)) ?? "";
                if (!string.IsNullOrWhiteSpace(param))
                    chargedModify.SetAttributeValue("param", param);
            }

            var modifyAmountCap = row.ModifyAmountCapTb.Text?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(modifyAmountCap))
                chargedModify.SetAttributeValue("modifyamountcap", modifyAmountCap);

            elements.Add(new XElement("charged", chargedModify));
        }

        return elements;
    }

    private List<XElement> BuildFullChargedElements(ProtoActionWidgetState state, bool includeEmptyRows = false)
    {
        var elements = new List<XElement>();

        static XElement? FindChild(XElement parent, string tag)
            => parent.Elements().FirstOrDefault(x => x.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));

        static void SetChildValue(XElement parent, string tag, string value)
        {
            var matches = parent.Elements()
                .Where(x => x.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase))
                .ToList();

            if (string.IsNullOrWhiteSpace(value))
            {
                foreach (var match in matches)
                    match.Remove();
                return;
            }

            var child = matches.FirstOrDefault();
            if (child == null)
            {
                parent.Add(new XElement(tag, value));
                return;
            }

            child.Name = tag;
            child.Value = value;
            foreach (var duplicate in matches.Skip(1))
                duplicate.Remove();
        }

        foreach (var row in state.FullChargedRows)
        {
            var modifierVisible = row.ModifierRow.IsVisible;
            var modifyType = modifierVisible
                ? ProtoConstants.GetModifyTypeValue(row.ModifyTypeAcb.Text?.Trim() ?? "")
                : "";
            var applyType = modifierVisible ? row.ApplyTypeCb.SelectedItem as string ?? "Multiply" : "Multiply";
            var param = modifierVisible ? row.ParamCb.SelectedItem?.ToString()?.Trim() ?? "" : "";
            var value = modifierVisible ? row.ValueTb.Text?.Trim() ?? "" : "";
            var activationType = row.ActivationRow.IsVisible ? row.ActivationTypeCb.SelectedItem as string ?? "" : "";
            var cooldown = row.CooldownGroup.IsVisible ? row.CooldownTb.Text?.Trim() ?? "" : "";
            var duration = row.DurationGroup.IsVisible ? row.DurationTb.Text?.Trim() ?? "" : "";
            var threshold = row.ThresholdTb.Text?.Trim() ?? "";
            var terrainType = row.TerrainTypeCb.SelectedItem as string ?? "";
            var vfx = row.VfxRow.IsVisible ? row.VfxAcb.Text?.Trim() ?? "" : "";
            var vfxDuration = row.VfxRow.IsVisible ? row.VfxDurationTb.Text?.Trim() ?? "" : "";
            var setTactic = row.SetTacticRow.IsVisible ? row.SetTacticTb.Text?.Trim() ?? "" : "";
            var attachment = row.AttachmentRow.IsVisible ? row.ChargedModelAttachmentEditor.FullValue : "";
            var attachmentBone = row.AttachmentRow.IsVisible ? row.ChargedModelAttachmentBoneAcb.Text?.Trim() ?? "" : "";
            var stealthEnabled = row.StealthCb.IsChecked == true;
            var removeChargeEnabled = row.RemoveChargeCb.IsChecked == true;
            var hasModifyContent =
                !string.IsNullOrWhiteSpace(modifyType) ||
                !string.IsNullOrWhiteSpace(value) ||
                !string.IsNullOrWhiteSpace(param) ||
                !applyType.Equals("Multiply", StringComparison.OrdinalIgnoreCase);

            var hasCurrentContent =
                hasModifyContent ||
                !string.IsNullOrWhiteSpace(activationType) ||
                !string.IsNullOrWhiteSpace(cooldown) ||
                !string.IsNullOrWhiteSpace(duration) ||
                !string.IsNullOrWhiteSpace(param) ||
                !string.IsNullOrWhiteSpace(threshold) ||
                !string.IsNullOrWhiteSpace(terrainType) ||
                !string.IsNullOrWhiteSpace(vfx) ||
                !string.IsNullOrWhiteSpace(vfxDuration) ||
                !string.IsNullOrWhiteSpace(setTactic) ||
                !string.IsNullOrWhiteSpace(attachment) ||
                !string.IsNullOrWhiteSpace(attachmentBone) ||
                stealthEnabled ||
                removeChargeEnabled;

            if (!row.OriginalElement.HasElements && !row.OriginalElement.HasAttributes && !hasCurrentContent)
            {
                if (includeEmptyRows)
                    elements.Add(new XElement("charged"));
                continue;
            }

            var charged = new XElement(row.OriginalElement);
            charged.Name = "charged";

            var chargedModify = FindChild(charged, "chargedmodify");
            var shouldHaveChargedModify = modifierVisible && (chargedModify != null || hasModifyContent);
            if (shouldHaveChargedModify)
            {
                if (chargedModify == null)
                {
                    chargedModify = new XElement("chargedmodify");
                    charged.AddFirst(chargedModify);
                }
                else
                {
                    chargedModify.Name = "chargedmodify";
                }

                foreach (var attribute in chargedModify.Attributes()
                    .Where(x => x.Name.LocalName.Equals("modifytype", StringComparison.OrdinalIgnoreCase) ||
                                x.Name.LocalName.Equals("applytype", StringComparison.OrdinalIgnoreCase) ||
                                x.Name.LocalName.Equals("param", StringComparison.OrdinalIgnoreCase))
                    .ToList())
                {
                    attribute.Remove();
                }

                if (!string.IsNullOrWhiteSpace(modifyType))
                    chargedModify.SetAttributeValue("modifytype", modifyType);
                if (!string.IsNullOrWhiteSpace(applyType) &&
                    !applyType.Equals("Multiply", StringComparison.OrdinalIgnoreCase))
                {
                    chargedModify.SetAttributeValue("applytype", applyType);
                }

                if (modifyType is "DamageSpecific" or "ArmorSpecific" && !string.IsNullOrWhiteSpace(param))
                {
                    var normalizedParam = ProtoConstants.KnownDamageTypes
                        .FirstOrDefault(x => x.Equals(param, StringComparison.OrdinalIgnoreCase)) ?? param;
                    chargedModify.SetAttributeValue("param", normalizedParam);
                }

                chargedModify.Value = value;
            }
            else
            {
                chargedModify?.Remove();
            }

            SetChildValue(charged, "activationtype", activationType);
            SetChildValue(charged, "cooldown", cooldown);
            SetChildValue(charged, "duration", duration);
            SetChildValue(
                charged,
                "hitpointsratiothreshold",
                activationType.Equals("BelowHitpointsThreshold", StringComparison.OrdinalIgnoreCase) ? threshold : "");
            SetChildValue(
                charged,
                "terraintype",
                activationType.Equals("TerrainType", StringComparison.OrdinalIgnoreCase) ? terrainType : "");
            SetChildValue(charged, "chargedmodifyvfx", vfx);
            SetChildValue(charged, "chargedmodifyvfxduration", vfxDuration);
            SetChildValue(charged, "settactic", setTactic);
            SetChildValue(charged, "chargedmodelattachment", attachment);
            SetChildValue(charged, "chargedmodelattachmentbone", attachmentBone);
            SetChildValue(charged, "stealth", stealthEnabled ? "1" : "");
            SetChildValue(charged, "chargedremove", removeChargeEnabled ? "true" : "");

            elements.Add(charged);
        }

        return elements;
    }

    private static bool ChargedElementsEqual(IReadOnlyList<XElement> left, IReadOnlyList<XElement> right)
    {
        if (left.Count != right.Count)
            return false;

        for (var i = 0; i < left.Count; i++)
        {
            if (!XNode.DeepEquals(new XElement(left[i]), new XElement(right[i])))
                return false;
        }

        return true;
    }

    private bool HasReflectAttackProtoAction()
    {
        foreach (var pw in _protoActionWidgets)
        {
            var actionType = TryResolveProtoActionType(pw.NameAcb.Text?.Trim() ?? "", out var resolvedType)
                ? resolvedType
                : GetExactProtoActionTypeMatch(pw.TypeAcb.Text);

            if (IsReflectAttackActionType(actionType ?? ""))
                return true;
        }

        return false;
    }

    private bool HasAutoCastBySelfProtoAction()
    {
        foreach (var pw in _protoActionWidgets)
        {
            if (pw.SelectedFlagTags.Contains("autocastbyself"))
                return true;
        }

        return false;
    }

    private bool HasTradeAddAllyResourcesProtoAction()
    {
        foreach (var pw in _protoActionWidgets)
        {
            var actionType = TryResolveProtoActionType(pw.NameAcb.Text?.Trim() ?? "", out var resolvedType)
                ? resolvedType
                : GetExactProtoActionTypeMatch(pw.TypeAcb.Text);

            if (!IsTradeActionType(actionType ?? ""))
                continue;

            if (pw.AdditionalFieldControls.TryGetValue("modifyamount", out var control))
            {
                var value = ReadProtoActionFieldControlValue(control, ProtoActionMetadataCatalog.GetFieldDefinition("modifyamount"));
                if (!string.IsNullOrWhiteSpace(value))
                    return true;
            }
            else if (!string.IsNullOrWhiteSpace(ProtoXmlHandler.GetProtoActionSimpleFieldValue(CreateEffectiveProtoActionSnapshot(pw), "modifyamount")))
            {
                return true;
            }
        }

        return false;
    }

    private bool HasHealProtoAction()
    {
        foreach (var pw in _protoActionWidgets)
        {
            var actionType = TryResolveProtoActionType(pw.NameAcb.Text?.Trim() ?? "", out var resolvedType)
                ? resolvedType
                : GetExactProtoActionTypeMatch(pw.TypeAcb.Text);

            if (IsHealActionType(actionType ?? ""))
                return true;
        }

        return false;
    }

    private string ResolveProtoActionType(string actionName, string currentType = "")
    {
        if (!string.IsNullOrWhiteSpace(currentType))
            return currentType;

        if (TryResolveProtoActionType(actionName, out var mappedType))
            return mappedType;

        return currentType;
    }

    private string GetAttackMode(ProtoActionWidgetState state)
    {
        var savedMode = state.CustomValues.GetValueOrDefault("attack.mode", "");
        if (!string.IsNullOrWhiteSpace(savedMode))
            return savedMode;

        var actionType = ResolveProtoActionType(state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? "");
        if (!IsAttackActionType(actionType))
            return "";

        var actionName = state.NameAcb.Text?.Trim() ?? "";
        var selfDestructAction = GetCurrentUnitActionReference("selfdestructprotoaction");
        if (!string.IsNullOrWhiteSpace(selfDestructAction) &&
            actionName.Equals(selfDestructAction, StringComparison.OrdinalIgnoreCase))
            return "Self-Destruct Attack";

        var birthAction = GetCurrentUnitActionReference("birthprotoaction");
        if (!string.IsNullOrWhiteSpace(birthAction) &&
            actionName.Equals(birthAction, StringComparison.OrdinalIgnoreCase))
            return "Birth Attack";

        if (state.SelectedFlagTags.Contains("handlogic")) return "Hand Attack";
        if (state.SelectedFlagTags.Contains("rangedlogic")) return "Ranged Attack";
        return "";
    }

    internal static bool TryGetDefaultAttackModeFromActionName(string actionName, out string attackMode)
        => DefaultAttackModesByActionName.TryGetValue(actionName.Trim(), out attackMode!);

    private bool ApplyDefaultAttackModeForNewAction(
        ProtoActionWidgetState state,
        string actionName,
        string actionType)
    {
        if (!state.IsNewCustomAction ||
            state.CustomValues.ContainsKey("attack.mode") ||
            !IsAttackActionType(actionType) ||
            !TryGetDefaultAttackModeFromActionName(actionName, out var defaultAttackMode))
        {
            return false;
        }

        state.CustomValues["attack.mode"] = defaultAttackMode;
        state.SelectedFlagTags.Remove("handlogic");
        state.SelectedFlagTags.Remove("rangedlogic");
        if (defaultAttackMode.Equals("Hand Attack", StringComparison.OrdinalIgnoreCase))
            state.SelectedFlagTags.Add("handlogic");
        else if (defaultAttackMode.Equals("Ranged Attack", StringComparison.OrdinalIgnoreCase))
            state.SelectedFlagTags.Add("rangedlogic");

        if (IsExclusiveAttackMode(defaultAttackMode))
        {
            state.ForcedVisibleFieldTags.Add("damagearea");
            state.ForcedVisibleFieldTags.Add("damageflags");
            state.ForcedVisibleFieldTags.Add("areasortmode");
            InitializeDamageAreaDefaults(state, requireAreaSortMode: true);
        }

        return true;
    }

    private string GetCurrentUnitActionReference(string tag)
    {
        if (_fieldControls.TryGetValue(tag, out var control))
        {
            var value = control switch
            {
                AutoCompleteBox acb => acb.Text?.Trim() ?? "",
                TextBox tb => tb.Text?.Trim() ?? "",
                _ => ""
            };
            if (!string.IsNullOrWhiteSpace(value))
                return value;
        }

        var unit = _modXmlRoot != null && !string.IsNullOrWhiteSpace(_currentUnitName)
            ? ProtoXmlHandler.GetUnitElement(_modXmlRoot, _currentUnitName)
            : null;
        unit ??= _barXmlRoot != null && !string.IsNullOrWhiteSpace(_currentUnitName)
            ? ProtoXmlHandler.GetUnitElement(_barXmlRoot, _currentUnitName)
            : null;
        return unit == null ? "" : ProtoXmlHandler.GetSimpleField(unit, tag)?.Trim() ?? "";
    }

    private void SetCurrentUnitActionReference(string tag, string actionName)
    {
        if (tag.Equals("stackprotoaction", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("selfdestructprotoaction", StringComparison.OrdinalIgnoreCase) ||
            tag.Equals("birthprotoaction", StringComparison.OrdinalIgnoreCase))
        {
            SyncManagedProtoActionStatsEditor(tag, actionName);
            return;
        }

        if (!_fieldControls.TryGetValue(tag, out var control))
            return;

        switch (control)
        {
            case AutoCompleteBox acb:
                acb.Text = actionName;
                break;
            case TextBox tb:
                tb.Text = actionName;
                break;
        }
    }

    private void SyncManagedProtoActionStatsEditor(string tag, string? actionName)
    {
        var normalizedName = actionName?.Trim() ?? "";
        if (string.IsNullOrWhiteSpace(normalizedName))
        {
            if (_otherSpecificAttributeContainers.TryGetValue(tag, out var existingRow))
            {
                _otherSpecificAttributesPanel?.Children.Remove(existingRow);
                _otherSpecificAttributeContainers.Remove(tag);
            }
            _fieldControls.Remove(tag);
            return;
        }

        if (_fieldControls.TryGetValue(tag, out var existingEditor))
        {
            existingEditor.IsEnabled = false;
            switch (existingEditor)
            {
                case AutoCompleteBox autoCompleteBox:
                    autoCompleteBox.Text = normalizedName;
                    break;
                case TextBox textBox:
                    textBox.Text = normalizedName;
                    break;
            }
            return;
        }

        if (_otherSpecificAttributesPanel == null)
            return;

        var row = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("150, Auto"),
            Margin = new Thickness(0, 2, 0, 2),
            HorizontalAlignment = HorizontalAlignment.Left
        };
        row.Children.Add(new TextBlock
        {
            Text = GetOtherSpecificAttributeLabel(tag),
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 4, 10, 4)
        });
        var editor = new TextBox
        {
            Text = normalizedName,
            IsEnabled = false
        };
        EditorTextFieldStyle.ConfigureTextBox(editor);
        ToolTip.SetTip(
            editor,
            tag.Equals("transformcommand", StringComparison.OrdinalIgnoreCase)
                ? "This reference is managed automatically by the unique Transform command."
                : "This reference is managed automatically by its ProtoAction.");
        Grid.SetColumn(editor, 1);
        row.Children.Add(editor);

        _fieldControls[tag] = editor;
        _otherSpecificAttributeContainers[tag] = row;
        var pickerIndex = _otherSpecificAttributeContainers.TryGetValue("__picker", out var picker)
            ? _otherSpecificAttributesPanel.Children.IndexOf(picker)
            : -1;
        if (pickerIndex >= 0)
            _otherSpecificAttributesPanel.Children.Insert(pickerIndex, row);
        else
            _otherSpecificAttributesPanel.Children.Add(row);
    }

    private bool IsAttackModeClaimedByAnother(ProtoActionWidgetState state, string attackMode)
        => _protoActionWidgets.Any(other =>
            !ReferenceEquals(other, state) &&
            GetAttackMode(other).Equals(attackMode, StringComparison.OrdinalIgnoreCase));

    private static bool IsExclusiveAttackMode(string attackMode)
        => attackMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase) ||
           attackMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase);

    private string GetCurrentExclusiveAttackActionName(string attackMode, string referenceTag)
    {
        var candidates = _protoActionWidgets
            .Where(actionState => GetAttackMode(actionState).Equals(attackMode, StringComparison.OrdinalIgnoreCase))
            .Select(actionState => actionState.NameAcb.Text?.Trim() ?? "")
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .ToList();
        var existingReference = GetCurrentUnitActionReference(referenceTag);
        return candidates.FirstOrDefault(name => name.Equals(existingReference, StringComparison.OrdinalIgnoreCase))
               ?? candidates.FirstOrDefault()
               ?? "";
    }

    private void RefreshExclusiveAttackActionReferences()
    {
        SetCurrentUnitActionReference(
            "selfdestructprotoaction",
            GetCurrentExclusiveAttackActionName("Self-Destruct Attack", "selfdestructprotoaction"));
        SetCurrentUnitActionReference(
            "birthprotoaction",
            GetCurrentExclusiveAttackActionName("Birth Attack", "birthprotoaction"));
        ScheduleXmlPreviewRefresh();
    }

    private bool IsStackControlTypeClaimedByAnother(ProtoActionWidgetState state)
        => _protoActionWidgets.Any(other =>
            !ReferenceEquals(other, state) &&
            IsStackControlActionType(ResolveProtoActionType(
                other.NameAcb.Text?.Trim() ?? "",
                other.TypeAcb.Text?.Trim() ?? "")));

    private List<string> GetProtoActionTypeOptionsForState(ProtoActionWidgetState state, string? preferredType = null)
    {
        var currentType = GetExactProtoActionTypeMatch(preferredType ?? state.TypeAcb.Text) ?? "";
        return GetProtoActionTypeOptions(currentType);
    }

    private void RefreshStackControlTypeOptions()
    {
        foreach (var actionState in _protoActionWidgets)
        {
            var currentText = actionState.TypeAcb.Text?.Trim() ?? "";
            actionState.TypeAcb.ItemsSource = GetProtoActionTypeOptionsForState(actionState);
            if (!string.IsNullOrWhiteSpace(currentText) &&
                !currentText.Equals(actionState.TypeAcb.Text?.Trim() ?? "", StringComparison.OrdinalIgnoreCase))
            {
                actionState.TypeAcb.Text = currentText;
            }
        }
    }

    private string GetCurrentStackControlActionName()
        => _protoActionWidgets
            .Where(actionState => IsStackControlActionType(ResolveProtoActionType(
                actionState.NameAcb.Text?.Trim() ?? "",
                actionState.TypeAcb.Text?.Trim() ?? "")))
            .Select(actionState => actionState.NameAcb.Text?.Trim() ?? "")
            .FirstOrDefault(name => !string.IsNullOrWhiteSpace(name)) ?? "";

    private void RefreshStackProtoActionReference()
    {
        SetCurrentUnitActionReference("stackprotoaction", GetCurrentStackControlActionName());
        ScheduleXmlPreviewRefresh();
    }

    private void RefreshTransformCommandStatsReference()
    {
        var uniqueCommandName = _transformCommandAssignments.UniqueAssignment?.CommandName?.Trim() ?? "";
        SyncManagedProtoActionStatsEditor("transformcommand", uniqueCommandName);
        ScheduleXmlPreviewRefresh();
    }

    private bool TryResolveProtoActionType(string actionName, out string mappedType)
    {
        mappedType = "";
        if (string.IsNullOrWhiteSpace(actionName))
            return false;

        var normalizedName = actionName.Trim();

        if (_currentUnitProtoActionTypeMap.TryGetValue(normalizedName, out var unitProtoType) &&
            !string.IsNullOrWhiteSpace(unitProtoType))
        {
            mappedType = unitProtoType;
            return true;
        }

        if (_currentUnitTacticsActionTypeMap.TryGetValue(normalizedName, out var unitTacticsType) &&
            !string.IsNullOrWhiteSpace(unitTacticsType))
        {
            mappedType = unitTacticsType;
            return true;
        }

        if (_protoActionTypeMap.TryGetValue(normalizedName, out var globalType) &&
            !string.IsNullOrWhiteSpace(globalType))
        {
            mappedType = globalType;
            return true;
        }

        mappedType = "";
        return false;
    }

    private List<string> GetProtoActionTypeOptions(string? currentType = null)
    {
        var options = _protoActionTypeSuggestions;

        var set = new HashSet<string>(options.Where(x => !string.IsNullOrWhiteSpace(x)), StringComparer.OrdinalIgnoreCase);
        if (!string.IsNullOrWhiteSpace(currentType))
            set.Add(currentType);

        return set.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
    }

    private string GetExactProtoActionTypeMatch(string? value)
    {
        var normalized = value?.Trim() ?? "";
        if (string.IsNullOrWhiteSpace(normalized))
            return "";

        return _protoActionTypeSuggestions.FirstOrDefault(x => x.Equals(normalized, StringComparison.OrdinalIgnoreCase)) ?? "";
    }

    private void EnableDropdownAutoComplete(AutoCompleteBox autoCompleteBox, bool selectAllOnFirstClick = true)
        => EditorAutoCompleteService.EnableDropdown(autoCompleteBox, () => _isPopulating, selectAllOnFirstClick);

    private void FreezeActionsScrollWhileDropDownIsOpen(AutoCompleteBox autoCompleteBox)
        => FreezeEditorScrollWhileDropDownIsOpen(autoCompleteBox, _actionsEditorScroll);

    private static void FreezeEditorScrollWhileDropDownIsOpen(
        AutoCompleteBox autoCompleteBox,
        ScrollViewer ownerScroll)
    {
        void FreezeEditorWheel(object? sender, PointerWheelEventArgs args)
        {
            var sourceIsInsideEditor = args.Source is Visual source &&
                (ReferenceEquals(source, ownerScroll) ||
                 source.GetVisualAncestors().Any(ancestor => ReferenceEquals(ancestor, ownerScroll)));
            if (autoCompleteBox.IsDropDownOpen && sourceIsInsideEditor)
                args.Handled = true;
        }

        ownerScroll.AddHandler(
            InputElement.PointerWheelChangedEvent,
            FreezeEditorWheel,
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        autoCompleteBox.DetachedFromVisualTree += (_, _) =>
            ownerScroll.RemoveHandler(InputElement.PointerWheelChangedEvent, FreezeEditorWheel);
    }

    private static void AttachNoWhitespaceNameBehavior(AutoCompleteBox autoCompleteBox)
    {
        var normalizing = false;
        autoCompleteBox.TextChanged += (_, _) =>
        {
            if (normalizing)
                return;
            var text = autoCompleteBox.Text ?? "";
            var filtered = new string(text.Where(ch => !char.IsWhiteSpace(ch)).ToArray());
            if (string.Equals(text, filtered, StringComparison.Ordinal))
                return;
            normalizing = true;
            autoCompleteBox.Text = filtered;
            normalizing = false;
        };
    }

    private static void AttachProtoActionIntegerBehavior(TextBox textBox, Func<bool>? allowNegative = null)
    {
        EditorNumericFieldStyle.ConfigureNumericTextBox(textBox);
        textBox.TextChanged += (_, _) =>
        {
            var text = textBox.Text ?? "";
            var canBeNegative = allowNegative?.Invoke() == true;
            var filtered = new string(text.Where(ch => char.IsDigit(ch) || (canBeNegative && ch == '-')).ToArray());
            if (filtered.Count(ch => ch == '-') > 1 || (filtered.Contains('-') && !filtered.StartsWith('-')))
                filtered = (filtered.StartsWith('-') ? "-" : "") + filtered.Replace("-", "", StringComparison.Ordinal);
            if (!string.Equals(text, filtered, StringComparison.Ordinal))
                textBox.Text = filtered;
        };
    }

    private static void AttachProtoActionNumberBehavior(TextBox textBox, string tag)
    {
        if (tag.Equals("unintentionaldamagemultiplier", StringComparison.OrdinalIgnoreCase))
        {
            AttachProtoActionDecimalBehavior(textBox);
            textBox.LostFocus += (_, _) =>
            {
                if (double.TryParse(textBox.Text, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsed) && parsed < 0)
                    textBox.Text = "0";
            };
            return;
        }

        if (!tag.Equals("maxsizeclass", StringComparison.OrdinalIgnoreCase))
        {
            AttachProtoActionDecimalBehavior(textBox);
            return;
        }

        AttachProtoActionIntegerBehavior(textBox);
        textBox.LostFocus += (_, _) =>
        {
            if (!int.TryParse(textBox.Text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsed) || parsed <= 0)
                textBox.Text = "1";
        };
    }

    private static IReadOnlyList<string> GetProtoActionSpecificDamageTypes(string? modifyType)
        => ProtoConstants.GetModifyTypeValue(modifyType?.Trim() ?? "") switch
        {
            "ArmorSpecific" => ["Hack", "Pierce", "Crush"],
            "DamageSpecific" => ["Hack", "Pierce", "Crush", "Divine"],
            _ => []
        };

    private static void RefreshProtoActionDamageTypeCombo(ComboBox comboBox, string? modifyType, string? preferredValue = null)
    {
        var choices = GetProtoActionSpecificDamageTypes(modifyType);
        var current = comboBox.SelectedItem?.ToString() ?? preferredValue?.Trim() ?? "";
        comboBox.ItemsSource = choices;
        comboBox.SelectedItem = choices.FirstOrDefault(choice => choice.Equals(current, StringComparison.OrdinalIgnoreCase));
    }

    private void UpdateProtoActionTypeEditor(AutoCompleteBox typeAcb, string actionName)
    {
        if (string.IsNullOrWhiteSpace(actionName))
        {
            typeAcb.IsEnabled = false;
            typeAcb.IsDropDownOpen = false;
            return;
        }

        if (TryResolveProtoActionType(actionName, out var mappedType) && !string.IsNullOrWhiteSpace(mappedType))
        {
            typeAcb.ItemsSource = GetProtoActionTypeOptions(mappedType);
            typeAcb.Text = mappedType;
            typeAcb.IsEnabled = false;
            typeAcb.IsDropDownOpen = false;
            return;
        }

        var currentValue = typeAcb.Text?.Trim() ?? "";
        var exactType = GetExactProtoActionTypeMatch(currentValue);
        if (!string.IsNullOrWhiteSpace(exactType))
            typeAcb.Text = exactType;

        typeAcb.ItemsSource = GetProtoActionTypeOptions(string.IsNullOrWhiteSpace(exactType) ? currentValue : exactType);
        typeAcb.IsEnabled = !_isReadOnly;
    }

    private static Dictionary<string, ProtoAction> CloneProtoActionMap(
        IReadOnlyDictionary<string, ProtoAction> source)
    {
        var clone = new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
        foreach (var entry in source)
        {
            if (!string.IsNullOrWhiteSpace(entry.Key))
                clone[entry.Key.Trim()] = entry.Value.Clone();
        }

        return clone;
    }

    private void MigrateProtoActionsForTacticsChange(
        XElement unit,
        IReadOnlyDictionary<string, ProtoAction> oldTacticsActions,
        IReadOnlyDictionary<string, ProtoAction> newTacticsActions)
    {
        var existingProtoActions = ProtoXmlHandler.GetProtoActions(unit);
        var migratedActions = BuildMigratedProtoActionsForTacticsChange(
            existingProtoActions,
            oldTacticsActions,
            newTacticsActions);
        ProtoXmlHandler.SetProtoActions(unit, migratedActions);
    }

    internal static List<ProtoAction> BuildMigratedProtoActionsForTacticsChange(
        IReadOnlyList<ProtoAction> existingProtoActions,
        IReadOnlyDictionary<string, ProtoAction> oldTacticsActions,
        IReadOnlyDictionary<string, ProtoAction> newTacticsActions)
    {
        var migratedActions = new List<ProtoAction>();
        var representedActionNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var protoAction in existingProtoActions)
        {
            var actionName = protoAction.Name?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(actionName))
                representedActionNames.Add(actionName);

            oldTacticsActions.TryGetValue(actionName, out var oldTacticsAction);
            var wasTacticsBacked = string.IsNullOrWhiteSpace(protoAction.Type) &&
                                   !string.IsNullOrWhiteSpace(actionName) &&
                                   oldTacticsAction is not null &&
                                   !string.IsNullOrWhiteSpace(oldTacticsAction.Type);
            ProtoAction? newTacticsAction = null;
            var stillExistsInNewTactics = !string.IsNullOrWhiteSpace(actionName) &&
                                          newTacticsActions.TryGetValue(actionName, out newTacticsAction);
            var tacticsTypeChanged = wasTacticsBacked &&
                                     stillExistsInNewTactics &&
                                     !string.Equals(
                                         oldTacticsAction!.Type?.Trim() ?? "",
                                         newTacticsAction!.Type?.Trim() ?? "",
                                         StringComparison.OrdinalIgnoreCase);

            if (!wasTacticsBacked || stillExistsInNewTactics && !tacticsTypeChanged)
            {
                // Shared actions keep their raw proto overlay. The new tactics action becomes
                // their base automatically, and any proto value continues to take priority.
                migratedActions.Add(protoAction);
                continue;
            }

            // The action disappeared, or the same name now refers to a different action type.
            // Materialize the complete old effective action in either case. Applying a raw
            // overlay to a new, incompatible base type would silently reinterpret its fields.
            var inheritedType = oldTacticsAction?.Type?.Trim() ?? "";
            var materialized = CreateEffectiveProtoActionSnapshot(
                protoAction,
                actionName,
                inheritedType,
                oldTacticsActions);
            materialized.Name = actionName;
            materialized.Type = inheritedType;
            materialized.SourceElement = null;
            migratedActions.Add(materialized);
        }

        foreach (var oldEntry in oldTacticsActions)
        {
            var actionName = oldEntry.Key?.Trim() ?? "";
            newTacticsActions.TryGetValue(actionName, out var replacementTacticsAction);
            var stillInheritedWithSameType = replacementTacticsAction is not null &&
                                             string.Equals(
                                                 oldEntry.Value.Type?.Trim() ?? "",
                                                 replacementTacticsAction.Type?.Trim() ?? "",
                                                 StringComparison.OrdinalIgnoreCase);
            if (string.IsNullOrWhiteSpace(actionName) ||
                stillInheritedWithSameType ||
                representedActionNames.Contains(actionName))
            {
                continue;
            }

            // This was a completely inherited action with no proto overlay. If it disappeared,
            // or its name now identifies another type, preserve the old behavior as a complete,
            // normal proto-owned action.
            var materialized = oldEntry.Value.Clone();
            materialized.Name = actionName;
            materialized.Type = oldEntry.Value.Type?.Trim() ?? "";
            materialized.SourceElement = null;
            migratedActions.Add(materialized);
        }

        return migratedActions;
    }

    private void RefreshCurrentUnitProtoActionMetadata(XElement unit)
    {
        InvalidateProtoActionValueSuggestionCaches();
        _currentUnitProtoActionTypeMap.Clear();
        _currentUnitTacticsActionTypeMap.Clear();
        _currentUnitTacticsActions.Clear();
        _currentUnitTacticsLoadDiagnostic = "";

        foreach (var action in ProtoXmlHandler.GetProtoActions(unit))
        {
            if (!string.IsNullOrWhiteSpace(action.Name) && !string.IsNullOrWhiteSpace(action.Type))
                _currentUnitProtoActionTypeMap[action.Name.Trim()] = action.Type.Trim();
        }

        var tacticsName = ProtoXmlHandler.GetSimpleField(unit, "tactics")?.Trim() ?? "";
        var tacticsActions = LoadProtoActionsForTactics(tacticsName);
        foreach (var kvp in tacticsActions)
        {
            if (!string.IsNullOrWhiteSpace(kvp.Key))
            {
                _currentUnitTacticsActions[kvp.Key.Trim()] = kvp.Value.Clone();
                if (!string.IsNullOrWhiteSpace(kvp.Value.Type))
                    _currentUnitTacticsActionTypeMap[kvp.Key.Trim()] = kvp.Value.Type.Trim();
            }
        }

        if (!string.IsNullOrWhiteSpace(tacticsName) &&
            _tacticsLoadDiagnostics.TryGetValue(tacticsName.Trim(), out var diagnostic))
            _currentUnitTacticsLoadDiagnostic = diagnostic;
    }

    private Dictionary<string, ProtoAction> LoadProtoActionsForTactics(string tacticsName)
    {
        if (string.IsNullOrWhiteSpace(tacticsName))
            return new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);

        var cacheKey = tacticsName.Trim();
        if (_tacticsActionCache.TryGetValue(cacheKey, out var cached))
            return cached;

        // Active-mod/loose tactics override Data.bar. This is important for imported
        // mods that intentionally use the same tactics name as a built-in definition.
        foreach (var path in GetTacticsCandidatePaths(cacheKey))
        {
            if (!File.Exists(path))
                continue;

            try
            {
                var xml = path.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase)
                    ? XmbReader.ToFormattedXml(File.ReadAllBytes(path))
                    : File.ReadAllText(path);

                if (string.IsNullOrWhiteSpace(xml))
                    throw new InvalidDataException("The tactics file is empty or could not be decoded.");

                var parsed = ParseTacticsActions(xml);
                _tacticsLoadDiagnostics.Remove(cacheKey);
                _resolvedTacticsActionSources.Add(cacheKey);
                _tacticsActionCache[cacheKey] = parsed;
                return parsed;
            }
            catch (Exception ex)
            {
                // An existing active-mod/loose file is authoritative. Falling through to
                // Data.bar would display unrelated inherited actions and hide the defect.
                return CacheInvalidTacticsResult(cacheKey, path, ex);
            }
        }

        var barResolved = LoadProtoActionsFromBarTactics(cacheKey);
        if (barResolved.Count > 0)
        {
            _tacticsLoadDiagnostics.Remove(cacheKey);
            _resolvedTacticsActionSources.Add(cacheKey);
            _tacticsActionCache[cacheKey] = barResolved;
            return barResolved;
        }

        var emptyResult = new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
        _tacticsActionCache[cacheKey] = emptyResult;
        return emptyResult;
    }

    private Dictionary<string, ProtoAction> CacheInvalidTacticsResult(
        string tacticsName,
        string source,
        Exception exception)
    {
        var sourceName = string.IsNullOrWhiteSpace(source) ? "unknown source" : source;
        var detail = exception is InvalidDataException or System.Xml.XmlException
            ? exception.Message
            : $"{exception.GetType().Name}: {exception.Message}";
        var diagnostic = $"Unable to load tactics '{tacticsName}' from '{sourceName}': {detail}";
        var empty = new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
        _tacticsLoadDiagnostics[tacticsName] = diagnostic;
        _resolvedTacticsActionSources.Add(tacticsName);
        _tacticsActionCache[tacticsName] = empty;
        return empty;
    }

    private string ResolveProtoActionTypeForUnitAction(ProtoAction action, string actionName, IReadOnlyDictionary<string, ProtoAction> tacticsActions)
    {
        if (!string.IsNullOrWhiteSpace(action.Type))
            return action.Type.Trim();

        var normalizedName = actionName?.Trim() ?? "";
        if (!string.IsNullOrWhiteSpace(normalizedName) &&
            tacticsActions.TryGetValue(normalizedName, out var tacticsAction) &&
            !string.IsNullOrWhiteSpace(tacticsAction.Type))
        {
            return tacticsAction.Type.Trim();
        }

        if (!string.IsNullOrWhiteSpace(normalizedName) &&
            _protoActionTypeMap.TryGetValue(normalizedName, out var mappedType) &&
            !string.IsNullOrWhiteSpace(mappedType))
        {
            return mappedType.Trim();
        }

        return "";
    }

    private List<CopyableProtoActionSourceUnit> GetCopyableProtoActionSourceUnits()
    {
        var result = new List<CopyableProtoActionSourceUnit>();

        if (_modXmlRoot != null)
        {
            foreach (var unitName in ProtoXmlHandler.GetUnitNames(_modXmlRoot).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                if (string.IsNullOrWhiteSpace(unitName) ||
                    unitName.Equals(_currentUnitName ?? "", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                var unit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, unitName);
                if (unit != null)
                {
                    result.Add(new CopyableProtoActionSourceUnit
                    {
                        UnitName = unitName,
                        Group = "Modified",
                        UnitElement = unit
                    });
                }
            }
        }

        if (_barXmlRoot != null)
        {
            foreach (var unitName in ProtoXmlHandler.GetUnitNames(_barXmlRoot).OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
            {
                if (string.IsNullOrWhiteSpace(unitName) ||
                    unitName.Equals(_currentUnitName ?? "", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                var unit = ProtoXmlHandler.GetUnitElement(_barXmlRoot, unitName);
                if (unit != null)
                {
                    result.Add(new CopyableProtoActionSourceUnit
                    {
                        UnitName = unitName,
                        Group = "Original",
                        UnitElement = unit
                    });
                }
            }
        }

        return result;
    }

    private List<ProtoAction> GetCopyableEffectiveProtoActionsForUnit(XElement unit)
    {
        var result = new List<ProtoAction>();
        var protoActions = ProtoXmlHandler.GetProtoActions(unit);
        var tacticsActions = LoadProtoActionsForTactics(ProtoXmlHandler.GetSimpleField(unit, "tactics")?.Trim() ?? "");
        var seenActionNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var protoAction in protoActions)
        {
            var actionName = protoAction.Name?.Trim() ?? "";
            var resolvedType = ResolveProtoActionTypeForUnitAction(protoAction, actionName, tacticsActions);
            var effectiveAction = CreateEffectiveProtoActionSnapshot(protoAction, actionName, resolvedType, tacticsActions);
            effectiveAction.SourceElement = null;
            result.Add(effectiveAction);

            if (!string.IsNullOrWhiteSpace(actionName))
                seenActionNames.Add(actionName);
        }

        foreach (var kvp in tacticsActions.OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
        {
            if (string.IsNullOrWhiteSpace(kvp.Key) || seenActionNames.Contains(kvp.Key))
                continue;

            var tacticsOnlyAction = kvp.Value.Clone();
            tacticsOnlyAction.Name = kvp.Key.Trim();
            tacticsOnlyAction.Type = ResolveProtoActionTypeForUnitAction(tacticsOnlyAction, tacticsOnlyAction.Name, tacticsActions);
            tacticsOnlyAction.SourceElement = null;
            result.Add(tacticsOnlyAction);
        }

        return result;
    }

    private async Task CopyProtoActionFromAnotherUnitAsync(Action<ProtoAction> addProtoActionWidget)
    {
        var proceed = await CheckStartLocalMod();
        if (!proceed)
            return;

        var sourceUnits = GetCopyableProtoActionSourceUnits();
        if (sourceUnits.Count == 0)
        {
            var prompt = new Prompt(PromptType.Error, "No Source Units", "No other units are available to copy protoactions from.");
            await prompt.ShowDialog(this);
            return;
        }

        var unitPicker = new PickerWindow(
            "Copy ProtoAction From Unit",
            sourceUnits.Select(x => new PickerItem { Display = x.UnitName, Group = x.Group }).ToList(),
            null);
        await unitPicker.ShowDialog(this);
        if (unitPicker.PickedIndex is not int selectedUnitIndex ||
            selectedUnitIndex < 0 ||
            selectedUnitIndex >= sourceUnits.Count)
        {
            return;
        }

        var sourceUnit = sourceUnits[selectedUnitIndex];
        var sourceActions = GetCopyableEffectiveProtoActionsForUnit(sourceUnit.UnitElement);
        if (sourceActions.Count == 0)
        {
            var prompt = new Prompt(PromptType.Error, "No Source Actions", $"Unit '{sourceUnit.UnitName}' has no protoactions to copy.");
            await prompt.ShowDialog(this);
            return;
        }

        var actionPicker = new PickerWindow(
            $"Select Action From {sourceUnit.UnitName}",
            sourceActions.Select(x => new PickerItem
            {
                Display = string.IsNullOrWhiteSpace(x.Name) ? "<unnamed action>" : x.Name,
                Group = string.IsNullOrWhiteSpace(x.Type) ? null : x.Type
            }).ToList(),
            null);
        await actionPicker.ShowDialog(this);
        if (actionPicker.PickedIndex is not int selectedActionIndex ||
            selectedActionIndex < 0 ||
            selectedActionIndex >= sourceActions.Count)
        {
            return;
        }

        var sourceAction = sourceActions[selectedActionIndex].Clone();
        sourceAction.SourceElement = null;

        if (!string.IsNullOrWhiteSpace(sourceAction.Name) && IsProtoActionNameInUse(sourceAction.Name))
        {
            var baseSuggestedName = sourceAction.Name + "Copy";
            var suggestedName = baseSuggestedName;
            var suffix = 2;
            while (IsProtoActionNameInUse(suggestedName))
            {
                suggestedName = baseSuggestedName + suffix.ToString();
                suffix++;
            }

            while (true)
            {
                var renamePrompt = new InputPromptWindow(
                    $"A protoaction named '{sourceAction.Name}' already exists on this unit.\nEnter a new name for the copied protoaction:",
                    suggestedName);
                await renamePrompt.ShowDialog(this);

                var renamedActionName = renamePrompt.InputText?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(renamedActionName))
                    return;

                if (IsProtoActionNameInUse(renamedActionName))
                {
                    var duplicatePrompt = new Prompt(
                        PromptType.Error,
                        "Action Already Exists",
                        $"The current unit already has a protoaction named '{renamedActionName}'. Please choose a different name.");
                    await duplicatePrompt.ShowDialog(this);
                    suggestedName = renamedActionName;
                    continue;
                }

                sourceAction.Name = renamedActionName;
                break;
            }
        }

        addProtoActionWidget(sourceAction);
        MarkDirty();
    }

    private bool IsProtoActionNameInUse(string actionName, ProtoActionWidgetState? excludedState = null)
    {
        if (string.IsNullOrWhiteSpace(actionName))
            return false;

        return _protoActionWidgets.Any(state =>
            !ReferenceEquals(state, excludedState) &&
            string.Equals(state.NameAcb.Text?.Trim() ?? state.Model.Name?.Trim() ?? "", actionName.Trim(), StringComparison.OrdinalIgnoreCase));
    }

    private bool RefreshProtoActionNameValidation(ProtoActionWidgetState state)
    {
        var actionName = state.NameAcb.Text?.Trim() ?? "";
        var hasDuplicate = !string.IsNullOrWhiteSpace(actionName) &&
                           IsProtoActionNameInUse(actionName, state);
        var actionType = ResolveProtoActionType(actionName, state.TypeAcb.Text?.Trim() ?? "");
        var hasStackControlConflict = _protoActionHostAdapter.Context.EnforcesProtoUnitOnlyConstraints &&
                                      IsStackControlActionType(actionType) &&
                                      IsStackControlTypeClaimedByAnother(state);
        var attackMode = GetAttackMode(state);
        var hasExclusiveAttackModeConflict = _protoActionHostAdapter.Context.EnforcesProtoUnitOnlyConstraints &&
                                             IsExclusiveAttackMode(attackMode) &&
                                             IsAttackModeClaimedByAnother(state, attackMode);
        state.HasDuplicateName = hasDuplicate;
        state.HasStackControlConflict = hasStackControlConflict;
        state.HasExclusiveAttackModeConflict = hasExclusiveAttackModeConflict;

        if (hasDuplicate || hasStackControlConflict || hasExclusiveAttackModeConflict)
        {
            state.NameValidationFrame.BorderBrush = Brush.Parse("#d64545");
            state.NameValidationFrame.BorderThickness = new Thickness(2);
            ToolTip.SetTip(
                state.NameValidationFrame,
                hasDuplicate
                    ? $"Another protoaction on this unit is already named '{actionName}'. Rename or remove this action before continuing."
                    : hasStackControlConflict
                        ? "A unit can contain only one StackControl action. Change this action's type or remove it before saving."
                        : $"A unit can contain only one {attackMode} action. Change this action's mode or remove it before saving.");
        }
        else
        {
            state.NameValidationFrame.BorderBrush = null;
            state.NameValidationFrame.BorderThickness = new Thickness(0);
            ToolTip.SetTip(state.NameValidationFrame, null);
        }

        if (hasStackControlConflict || hasExclusiveAttackModeConflict)
        {
            state.TypeValidationFrame.BorderBrush = Brush.Parse("#d64545");
            state.TypeValidationFrame.BorderThickness = new Thickness(2);
            ToolTip.SetTip(
                state.TypeValidationFrame,
                hasStackControlConflict
                    ? "A unit can contain only one StackControl action."
                    : $"A unit can contain only one {attackMode} action.");
        }
        else
        {
            state.TypeValidationFrame.BorderBrush = null;
            state.TypeValidationFrame.BorderThickness = new Thickness(0);
            ToolTip.SetTip(state.TypeValidationFrame, null);
        }

        var identityIsLocked = state.IsLinkedMaulAreaAction ||
                               state.IsLinkedAbductDropAction ||
                               state.IsTacticsOnlyAction;
        var hasActionName = !string.IsNullOrWhiteSpace(actionName);
        state.TypeAcb.IsEnabled = !_isReadOnly && !identityIsLocked && !hasDuplicate && hasActionName;
        ToolTip.SetTip(state.TypeAcb, hasActionName ? null : "Enter an action name before choosing its type.");
        state.ActiveCheckBox.IsEnabled = !_isReadOnly && !hasDuplicate;
        state.BodyContainer.IsEnabled = !hasDuplicate;
        return !hasDuplicate;
    }

    private void RefreshAllProtoActionNameValidation()
    {
        foreach (var state in _protoActionWidgets)
            RefreshProtoActionNameValidation(state);
    }

    private IReadOnlyList<string> GetDuplicateProtoActionNames()
    {
        return _protoActionWidgets
            .Select(state => state.NameAcb.Text?.Trim() ?? state.Model.Name?.Trim() ?? "")
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .GroupBy(name => name, StringComparer.OrdinalIgnoreCase)
            .Where(group => group.Count() > 1)
            .Select(group => group.First())
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private async Task<bool> EnsureUniqueProtoActionNamesBeforeSaveAsync()
    {
        var invalidNames = _protoActionWidgets
            .Where(state =>
            {
                var name = state.NameAcb.Text?.Trim() ?? "";
                return !InternalNamePolicy.IsValidOrUnchangedLegacy(name, state.Model.Name) ||
                       state.IsNewCustomAction && !InternalNamePolicy.IsValid(name);
            })
            .ToList();
        if (invalidNames.Count > 0)
        {
            var invalidPrompt = new Prompt(
                PromptType.Error,
                "Invalid ProtoAction Name",
                "New or renamed ProtoAction names can contain only letters, digits, '_' and '-'.");
            await invalidPrompt.ShowDialog(this);
            invalidNames[0].NameAcb.Focus();
            return false;
        }

        var missingNewActionType = _protoActionWidgets.FirstOrDefault(state =>
        {
            var actionName = state.NameAcb.Text?.Trim() ?? "";
            var resolvedType = _protoActionHostAdapter.ResolveActionType(
                actionName,
                state.TypeAcb.Text,
                name => TryResolveProtoActionType(name, out var mappedType) ? mappedType : null,
                GetExactProtoActionTypeMatch);
            return ProtoActionIntegrityPolicy.IsMissingRequiredType(
                state.IsNewCustomAction,
                resolvedType);
        });
        if (missingNewActionType != null)
        {
            var missingTypePrompt = new Prompt(
                PromptType.Error,
                "Missing ProtoAction Type",
                "Every new ProtoAction requires a valid action type before it can be saved.");
            await missingTypePrompt.ShowDialog(this);
            missingNewActionType.TypeAcb.Focus();
            return false;
        }

        var invalidTrailFrequency = _protoActionWidgets
            .Where(state => ResolveProtoActionType(
                    state.NameAcb.Text?.Trim() ?? "",
                    state.TypeAcb.Text?.Trim() ?? "")
                .Equals("Trail", StringComparison.OrdinalIgnoreCase))
            .SelectMany(state => state.StructuredFieldRows.TryGetValue("trailprotounit", out var rows)
                ? rows
                : [])
            .Select(row => row.AttributeEditors.TryGetValue("frequency", out var editor) ? editor : null)
            .FirstOrDefault(editor => editor == null ||
                                      !double.TryParse(
                                          ReadProtoActionStructuredAttributeValue(editor),
                                          NumberStyles.Float,
                                          CultureInfo.InvariantCulture,
                                          out var frequency) || frequency <= 0);
        if (invalidTrailFrequency != null)
        {
            var frequencyPrompt = new Prompt(
                PromptType.Error,
                "Invalid Trail Frequency",
                "Trail Frequency must be a number greater than 0.");
            await frequencyPrompt.ShowDialog(this);
            invalidTrailFrequency.Focus();
            return false;
        }

        var duplicateNames = GetDuplicateProtoActionNames();
        if (duplicateNames.Count > 0)
        {
            var nameList = string.Join("\n", duplicateNames.Select(name => "- " + name));
            var prompt = new Prompt(
                PromptType.Error,
                "Duplicate ProtoAction Names",
                $"Every protoaction on a unit must have a unique name. Rename or remove the duplicates before saving:\n{nameList}");
            await prompt.ShowDialog(this);
            return false;
        }

        foreach (var exclusiveMode in new[] { "Self-Destruct Attack", "Birth Attack" })
        {
            var conflictingActions = _protoActionWidgets
                .Where(state => GetAttackMode(state).Equals(exclusiveMode, StringComparison.OrdinalIgnoreCase))
                .ToList();
            if (conflictingActions.Count <= 1)
                continue;

            RefreshAllProtoActionNameValidation();
            var modePrompt = new Prompt(
                PromptType.Error,
                $"Duplicate {exclusiveMode} Actions",
                $"A unit can contain only one {exclusiveMode} action. Change the extra action's mode or remove it before saving.");
            await modePrompt.ShowDialog(this);
            conflictingActions[1].TypeAcb.Focus();
            return false;
        }

        var stackControlConflicts = _protoActionWidgets
            .Where(state => IsStackControlActionType(ResolveProtoActionType(
                state.NameAcb.Text?.Trim() ?? "",
                state.TypeAcb.Text?.Trim() ?? "")))
            .ToList();
        if (stackControlConflicts.Count <= 1)
            return true;

        RefreshAllProtoActionNameValidation();
        var stackPrompt = new Prompt(
            PromptType.Error,
            "Duplicate StackControl Actions",
            "A unit can contain only one StackControl action. Change the extra action's type or remove it before saving.");
        await stackPrompt.ShowDialog(this);
        stackControlConflicts[1].TypeAcb.Focus();
        return false;
    }

    private const string NewTacticsTemplate = """
<tactics>
	<tactic>Default</tactic>
</tactics>
""";

    private string? GetModTacticsDirectory()
    {
        if (string.IsNullOrWhiteSpace(_modFilePath))
            return null;
        var gameplayDirectory = Path.GetDirectoryName(_modFilePath);
        return string.IsNullOrWhiteSpace(gameplayDirectory)
            ? null
            : Path.Combine(gameplayDirectory, "tactics");
    }

    private static string NormalizeManagedTacticsName(string value)
    {
        var normalized = value.Trim().Replace('/', '\\');
        if (!normalized.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase))
            normalized += ".tactics";
        return normalized;
    }

    private string? GetCustomTacticsPath(string tacticsName)
    {
        var directory = GetModTacticsDirectory();
        if (directory == null)
            return null;
        var relative = NormalizeManagedTacticsName(tacticsName).Replace('\\', Path.DirectorySeparatorChar);
        return Path.Combine(directory, relative);
    }

    private HashSet<string> GetCustomTacticsNames()
    {
        var result = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var directory = GetModTacticsDirectory();
        if (directory == null || !Directory.Exists(directory))
            return result;

        foreach (var path in Directory.GetFiles(directory, "*", SearchOption.AllDirectories))
        {
            var fileName = Path.GetFileName(path);
            if (!fileName.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase) &&
                !fileName.EndsWith(".tactics.xmb", StringComparison.OrdinalIgnoreCase))
                continue;

            var relative = Path.GetRelativePath(directory, path).Replace(Path.DirectorySeparatorChar, '\\');
            if (relative.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
                relative = relative[..^4];
            result.Add(NormalizeManagedTacticsName(relative));
        }
        return result;
    }

    private Dictionary<string, int> GetTacticsUsageCounts()
    {
        var result = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        if (_modXmlRoot == null)
            return result;

        foreach (var tacticsElement in _modXmlRoot.Descendants()
                     .Where(element => element.Name.LocalName.Equals("tactics", StringComparison.OrdinalIgnoreCase)))
        {
            var name = NormalizeManagedTacticsName(tacticsElement.Value);
            if (string.IsNullOrWhiteSpace(name))
                continue;
            result[name] = result.GetValueOrDefault(name) + 1;
        }
        return result;
    }


    private HashSet<string> GetCustomAbilityPowerNames()
    {
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var path = GetCurrentModGameplayFilePath("powers_mods.xml");
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            return names;
        try
        {
            var doc = XDocument.Load(path, LoadOptions.PreserveWhitespace);
            foreach (var power in doc.Root?.Elements().Where(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase)) ?? [])
            {
                var name = GetAbilityElementName(power);
                if (!string.IsNullOrWhiteSpace(name)) names.Add(name);
            }
        }
        catch { }
        return names;
    }

    private Dictionary<string, int> GetAbilityUsageCounts()
    {
        var result = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        void CountDocument(XDocument doc)
        {
            if (doc.Root == null) return;
            foreach (var ability in doc.Root.Descendants().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)))
            {
                var name = GetAbilityElementName(ability);
                if (!string.IsNullOrWhiteSpace(name)) result[name] = result.GetValueOrDefault(name) + 1;
            }
        }

        var gameplay = ResolveBaseGameplayDirectory();
        var loosePath = string.IsNullOrWhiteSpace(gameplay) ? null : Path.Combine(gameplay, "abilities", "abilities.xml");
        var countedBase = false;
        if (!string.IsNullOrWhiteSpace(loosePath) && File.Exists(loosePath))
        {
            try { CountDocument(XDocument.Load(loosePath, LoadOptions.PreserveWhitespace)); countedBase = true; }
            catch { }
        }
        if (!countedBase && _protoDataBarFile != null && !string.IsNullOrWhiteSpace(_protoDataBarPath) && File.Exists(_protoDataBarPath))
        {
            foreach (var doc in ExtractAbilityDocumentsFromBar(_protoDataBarFile, _protoDataBarPath))
                if (doc.Root?.Name.LocalName.Equals("abilities", StringComparison.OrdinalIgnoreCase) == true)
                    CountDocument(doc);
        }

        var modPath = GetCurrentModAbilitiesFilePath("abilities_mods.xml");
        if (!string.IsNullOrWhiteSpace(modPath) && File.Exists(modPath))
        {
            try { CountDocument(XDocument.Load(modPath, LoadOptions.PreserveWhitespace)); }
            catch { }
        }
        return result;
    }

    private int ResolveManagedAbilityUsageCount(string abilityName)
    {
        var usage = GetAbilityUsageCounts().GetValueOrDefault(abilityName);
        if (!_isAbilityDefinitionEditorMode && _abilityDrafts.Values.Any(draft => draft.Name.Equals(abilityName, StringComparison.OrdinalIgnoreCase)))
            usage = Math.Max(1, usage);
        return usage;
    }

    private int CountProtoUnitCommandUsage(string commandName)
        => CountProtoUnitCommandUsage(commandName, ignoredUnitName: null);

    private int CountProtoUnitCommandUsage(string commandName, string? ignoredUnitName)
    {
        var count = 0;
        if (_modXmlRoot == null) return count;
        foreach (var unit in _modXmlRoot.Descendants("unit"))
        {
            if (!string.IsNullOrWhiteSpace(ignoredUnitName) &&
                string.Equals(unit.Attribute("name")?.Value?.Trim(), ignoredUnitName, StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            var used = ProtoXmlHandler.GetCommandEntries(unit).Any(x => x.Value.Equals(commandName, StringComparison.OrdinalIgnoreCase)) ||
                       ProtoXmlHandler.GetOptionalCommandEntries(unit).Any(x => x.Value.Equals(commandName, StringComparison.OrdinalIgnoreCase)) ||
                       string.Equals(ProtoXmlHandler.GetSimpleField(unit, "transformcommand"), commandName, StringComparison.OrdinalIgnoreCase);
            if (used) count++;
        }
        return count;
    }

