    private async Task<bool> MoveCustomIconAsync(IconManagerItem item, AssetDestination destination)
    {
        var resourcesDirectory = GetCurrentModIconResourcesDirectory();
        if (resourcesDirectory == null) return false;
        var relative = IconManagerWindow.RemoveResourcesPrefix(item.FullPath);
        if (!TryResolveExistingAsset(resourcesDirectory, relative, ".png", "resources", out var sourcePath))
            return await ShowAssetMoveErrorAsync("Icon unavailable", "The custom icon could not be found inside this mod.");
        return await MoveCustomAssetAsync(sourcePath, item.FullPath, destination, "icon", "icon");
    }

    private async Task<bool> MoveCustomAnimFileAsync(AnimFileCatalogEntry item, AssetDestination destination)
    {
        var artDirectory = GetCurrentModArtDirectory();
        if (artDirectory == null) return false;
        if (!TryResolveExistingAsset(artDirectory, item.Path, ".xml", "", out var sourcePath))
            return await ShowAssetMoveErrorAsync("Anim File unavailable", "The custom animation file could not be found inside this mod.");
        return await MoveCustomAssetAsync(sourcePath, item.Path, destination, "animfile", "animation file");
    }

    private async Task<bool> MoveCustomSoundSetAsync(AnimFileCatalogEntry item, AssetDestination destination)
    {
        var soundDirectory = GetCurrentModSoundDirectory();
        if (soundDirectory == null) return false;
        if (!TryResolveExistingAsset(soundDirectory, item.Path, ".xml", "", out var sourcePath))
            return await ShowAssetMoveErrorAsync("Sound Set unavailable", "The custom sound set could not be found inside this mod.");
        return await MoveCustomAssetAsync(sourcePath, item.Path, destination, "soundsetfile", "sound set");
    }

    private static bool TryResolveExistingAsset(
        string rootDirectory,
        string relativePath,
        string extension,
        string xmlPrefix,
        out string absolutePath)
    {
        var normalized = relativePath.Replace('/', '\\');
        var folder = Path.GetDirectoryName(normalized) ?? "";
        var name = Path.GetFileNameWithoutExtension(normalized);
        if (AssetDestinationPolicy.TryResolve(rootDirectory, folder, name, extension, xmlPrefix, out var destination, out _) &&
            destination != null && File.Exists(destination.AbsolutePath))
        {
            absolutePath = destination.AbsolutePath;
            return true;
        }
        absolutePath = "";
        return false;
    }

    private async Task<bool> MoveCustomAssetAsync(
        string sourcePath,
        string oldXmlValue,
        AssetDestination destination,
        string elementName,
        string assetLabel)
    {
        if (_modXmlDoc?.Root == null || string.IsNullOrWhiteSpace(_modFilePath))
            return false;
        if (_isDirty || _dirtyUnitNames.Count > 0)
        {
            await new Prompt(
                PromptType.Error,
                "Save changes first",
                $"Save the current ProtoUnit changes before renaming or moving this {assetLabel}. This prevents unvalidated edits from being committed by the asset migration.").ShowDialog(this);
            return false;
        }
        if (File.Exists(destination.AbsolutePath))
            return await ShowAssetMoveErrorAsync("Destination exists", "A file already exists at the selected destination.");

        var impact = ProtoUnitAssetReferenceMigration.Inspect(_modXmlDoc.Root, elementName, oldXmlValue);
        var units = impact.UnitNames.Count == 0
            ? "No ProtoUnit currently references this asset."
            : $"{impact.ReferenceCount} reference(s) in {impact.UnitNames.Count} ProtoUnit(s) will be updated:\n" +
              string.Join(", ", impact.UnitNames.Take(12)) + (impact.UnitNames.Count > 12 ? ", …" : "");
        var moveTitle = elementName.ToLowerInvariant() switch
        {
            "icon" => "Rename/Move Icon",
            "soundsetfile" => "Rename/Move Sound Set",
            _ => "Rename/Move Anim File"
        };
        var confirmation = new Prompt(
            PromptType.Confirm,
            moveTitle,
            $"{oldXmlValue}\n→ {destination.XmlValue}\n\n{units}\n\nThe file move and reference updates will be saved together.",
            confirmButtonText: "Save");
        await confirmation.ShowDialog(this);
        if (!confirmation.Confirmed) return false;

        var documentBackup = new XDocument(_modXmlDoc);
        try
        {
            FileIntegrityTransaction.Execute(
                [sourcePath, destination.AbsolutePath, _modFilePath],
                () =>
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(destination.AbsolutePath)!);
                    File.Move(sourcePath, destination.AbsolutePath, overwrite: false);
                    ProtoUnitAssetReferenceMigration.Replace(_modXmlDoc.Root!, elementName, oldXmlValue, destination.XmlValue);
                    SaveXmlDocumentAtomic(_modXmlDoc, _modFilePath);
                });
            InvalidateSuggestionCaches();
            _statusMessage.Text = $"Custom {assetLabel} moved and ProtoUnit references updated.";
            return true;
        }
        catch (Exception exception)
        {
            _modXmlDoc = documentBackup;
            _modXmlRoot = documentBackup.Root;
            await new Prompt(PromptType.Error, "Asset move failed", exception.Message).ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> ShowAssetMoveErrorAsync(string title, string message)
    {
        await new Prompt(PromptType.Error, title, message).ShowDialog(this);
        return false;
    }

    private int CountUnitTypeUsage(string unitTypeName)
    {
        var unitNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        void Count(XElement? root)
        {
            if (root == null) return;
            foreach (var unit in root.Elements().Where(element =>
                         element.Name.LocalName.Equals("unit", StringComparison.OrdinalIgnoreCase)))
            {
                if (!unit.Elements().Any(element =>
                        element.Name.LocalName.Equals("unittype", StringComparison.OrdinalIgnoreCase) &&
                        element.Value.Trim().Equals(unitTypeName, StringComparison.OrdinalIgnoreCase)))
                {
                    continue;
                }
                unitNames.Add(unit.Attribute("name")?.Value?.Trim() ?? unit.Element("name")?.Value?.Trim() ?? "(unnamed)");
            }
        }
        Count(_barXmlRoot);
        Count(_modXmlRoot);
        return unitNames.Count;
    }

    private async Task<bool> CreateUnitTypeAsync(string name)
        => await MutateUnitTypeDocumentAsync("create Unit Type", document =>
        {
            EnsureUnitTypeNameAvailable(name);
            UnitTypeCatalog.AddDefinition(document, name);
        });

    private async Task<bool> DuplicateUnitTypeAsync(string sourceName, bool sourceIsBuiltIn, string newName)
    {
        var source = GetUnitTypeDefinitions().FirstOrDefault(definition =>
            definition.Name.Equals(sourceName, StringComparison.OrdinalIgnoreCase) &&
            definition.IsBuiltIn == sourceIsBuiltIn)
            ?? GetUnitTypeDefinitions().FirstOrDefault(definition =>
                definition.Name.Equals(sourceName, StringComparison.OrdinalIgnoreCase));
        if (source == null)
        {
            await new Prompt(PromptType.Error, "Unable to duplicate Unit Type", $"Could not load '{sourceName}'.").ShowDialog(this);
            return false;
        }

        return await MutateUnitTypeDocumentAsync("duplicate Unit Type", document =>
        {
            EnsureUnitTypeNameAvailable(newName);
            UnitTypeCatalog.AddDefinition(document, newName, source.SourceElement);
        });
    }

    private async Task<bool> RenameUnitTypeAsync(string oldName, string newName)
    {
        var unitTypePath = GetCurrentModGameplayFilePath("abstract_unit_types_mods.xml");
        if (string.IsNullOrWhiteSpace(unitTypePath) || string.IsNullOrWhiteSpace(_modFilePath) || _modXmlDoc == null)
            return false;

        try
        {
            EnsureUnitTypeNameAvailable(newName, oldName);
            var unitTypeDocument = UnitTypeCatalog.LoadOrCreateModDocument(unitTypePath);
            if (!UnitTypeCatalog.RenameDefinition(unitTypeDocument, oldName, newName))
                throw new InvalidOperationException($"Custom Unit Type '{oldName}' was not found.");

            var protoDocument = new XDocument(_modXmlDoc);
            UnitTypeCatalog.RenameUnitAssignments(protoDocument, oldName, newName);

            FileIntegrityTransaction.Execute([unitTypePath, _modFilePath], () =>
            {
                SaveUnitTypeXmlDocument(unitTypeDocument, unitTypePath);
                SaveXmlDocumentAtomic(protoDocument, _modFilePath);
            });
            AdoptSavedProtoDocument(protoDocument);
            InvalidateSuggestionCaches();
            _statusMessage.Text = $"Unit Type '{oldName}' renamed to '{newName}'.";
            return true;
        }
        catch (Exception ex)
        {
            await new Prompt(PromptType.Error, "Unable to rename Unit Type", ex.Message).ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> DeleteUnitTypeAsync(string name)
    {
        var unitTypePath = GetCurrentModGameplayFilePath("abstract_unit_types_mods.xml");
        if (string.IsNullOrWhiteSpace(unitTypePath) || string.IsNullOrWhiteSpace(_modFilePath) || _modXmlDoc == null)
            return false;

        try
        {
            var unitTypeDocument = UnitTypeCatalog.LoadOrCreateModDocument(unitTypePath);
            if (!UnitTypeCatalog.DeleteDefinition(unitTypeDocument, name))
                throw new InvalidOperationException($"Custom Unit Type '{name}' was not found.");

            var protoDocument = new XDocument(_modXmlDoc);
            var removedAssignments = UnitTypeCatalog.RemoveUnitAssignments(protoDocument, name);
            FileIntegrityTransaction.Execute([unitTypePath, _modFilePath], () =>
            {
                SaveUnitTypeXmlDocument(unitTypeDocument, unitTypePath);
                SaveXmlDocumentAtomic(protoDocument, _modFilePath);
            });

            AdoptSavedProtoDocument(protoDocument);
            InvalidateSuggestionCaches();
            _statusMessage.Text = removedAssignments == 0
                ? $"Unit Type '{name}' removed."
                : $"Unit Type '{name}' and {removedAssignments} unit assignment(s) removed.";
            return true;
        }
        catch (Exception ex)
        {
            await new Prompt(PromptType.Error, "Unable to remove Unit Type", ex.Message).ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> MutateUnitTypeDocumentAsync(string operation, Action<XDocument> mutation)
    {
        var path = GetCurrentModGameplayFilePath("abstract_unit_types_mods.xml");
        if (string.IsNullOrWhiteSpace(path))
            return false;
        try
        {
            var document = UnitTypeCatalog.LoadOrCreateModDocument(path);
            mutation(document);
            FileIntegrityTransaction.Execute([path], () => SaveUnitTypeXmlDocument(document, path));
            InvalidateSuggestionCaches();
            _statusMessage.Text = $"Unit Type changes saved.";
            return true;
        }
        catch (Exception ex)
        {
            await new Prompt(PromptType.Error, $"Unable to {operation}", ex.Message).ShowDialog(this);
            return false;
        }
    }

    private void EnsureUnitTypeNameAvailable(string name, string? ignoredCustomName = null)
    {
        if (!UnitTypeCatalog.IsValidName(name))
            throw new InvalidOperationException("Unit Type names can contain only letters, digits, '_' and '-'.");
        if (GetUnitTypeDefinitions().Any(definition =>
                !definition.Name.Equals(ignoredCustomName, StringComparison.OrdinalIgnoreCase) &&
                definition.Name.Equals(name, StringComparison.OrdinalIgnoreCase)))
        {
            throw new InvalidOperationException($"Unit Type '{name}' already exists.");
        }
    }

    private bool IsCustomProtoUnitCommand(string name)
    {
        var path = GetCurrentModGameplayFilePath("proto_unit_command_mods.xml");
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return false;
        try
        {
            var doc = XDocument.Load(path, LoadOptions.PreserveWhitespace);
            return doc.Descendants().Any(e => e.Name.LocalName.Equals("protounitcommand", StringComparison.OrdinalIgnoreCase) && GetProtoUnitCommandName(e).Equals(name, StringComparison.OrdinalIgnoreCase));
        }
        catch { return false; }
    }

    private async Task OpenAbilitiesManagerAsync()
    {
        if (string.IsNullOrWhiteSpace(_modFilePath))
        {
            var prompt = new Prompt(PromptType.Error, "No active mod", "Load or create a local mod before managing abilities.");
            await prompt.ShowDialog(this);
            return;
        }

        _captureAbilityEditorCurrent?.Invoke();
        EnsureAbilityCatalogLoadedForManager();
        var customNames = GetCustomAbilityPowerNames();
        var usageCounts = GetAbilityUsageCounts();
        foreach (var draft in _abilityDrafts.Values.Where(draft => !string.IsNullOrWhiteSpace(draft.Name)))
            usageCounts[draft.Name] = Math.Max(1, usageCounts.GetValueOrDefault(draft.Name));
        var items = _abilityPowerCatalog.Keys
            .Union(customNames, StringComparer.OrdinalIgnoreCase)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Select(name => new AbilityManagerItem(
                name,
                IsBuiltIn: !customNames.Contains(name),
                UsageCount: usageCounts.GetValueOrDefault(name)))
            .ToList();

        var window = new AbilitiesManagerWindow(
            items,
            OpenManagedAbilityEditorAsync,
            CreateManagedAbilityAsync,
            DuplicateManagedAbilityAsync,
            RenameManagedAbilityAsync,
            DeleteManagedAbilityAsync,
            ResolveManagedAbilityUsageCount);
        await window.ShowDialog(this);
    }

    private void EnsureAbilityCatalogLoadedForManager()
    {
        if (_abilityPowerCatalog.Count > 0)
            return;

        // The main document now intentionally starts empty, so the normal per-unit
        // ability loader may not have run before the global manager is opened.
        // Preserve every in-memory unit draft while using a non-unit key to load only
        // the shared ability/power catalog.
        var preservedDrafts = CloneAbilityDrafts(_abilityDrafts);
        var preservedNames = _availableAbilityNames.ToList();
        LoadAbilitySources("__ability_manager_catalog__");

        _abilityDrafts.Clear();
        foreach (var entry in preservedDrafts)
            _abilityDrafts[entry.Key] = entry.Value;
        _availableAbilityNames = preservedNames
            .Concat(_abilityPowerCatalog.Keys)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();
    }

    private async Task<bool> CreateManagedAbilityAsync(string abilityName)
    {
        var path = GetCurrentModGameplayFilePath("powers_mods.xml");
        if (string.IsNullOrWhiteSpace(path)) return false;
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            var doc = LoadAbilityXmlDocumentForUpdate(path, "powersmod");
            if (doc.Root == null) doc.Add(new XElement("powersmod"));
            doc.Root!.Name = "powersmod";
            if (doc.Root.Elements().Any(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) &&
                                             GetAbilityElementName(e).Equals(abilityName, StringComparison.OrdinalIgnoreCase)))
                return false;
            var power = new XElement("power", new XAttribute("name", abilityName), new XAttribute("type", "UnitAction"));
            doc.Root.Add(power);
            SaveAbilityXmlDocument(doc, path);
            _abilityPowerCatalog[abilityName] = new XElement(power);
            RegisterAvailableAbilityName(abilityName);
            return true;
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to create ability", ex.Message);
            await prompt.ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> DuplicateManagedAbilityAsync(string sourceName, bool sourceIsBuiltIn, string newName)
    {
        if (!_abilityPowerCatalog.TryGetValue(sourceName, out var source))
            return false;
        var clone = new XElement(source);
        clone.SetAttributeValue("name", newName);
        try
        {
            var stringEntries = LoadCurrentModStringEntries(requireReadable: true);
            var stringsChanged = false;
            foreach (var tag in new[] { "displaynameid", "rolloverid" })
            {
                var element = clone.Elements().FirstOrDefault(e => e.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));
                var sourceId = element?.Value?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(sourceId))
                    continue;

                string? sourceText = null;
                if (!stringEntries.TryGetValue(sourceId, out sourceText))
                    sourceText = await _gameData.LookupStringKeyAsync(sourceId);
                if (sourceText == null)
                    throw new InvalidOperationException($"Could not resolve string '{sourceId}' while duplicating '{sourceName}'. The duplicate was not created.");

                var rollover = tag.Equals("rolloverid", StringComparison.OrdinalIgnoreCase);
                var newId = BuildUniqueAbilityStringId(newName, rollover, stringEntries);
                element!.Value = newId;
                stringEntries[newId] = sourceText;
                stringsChanged = true;
            }
            if (stringsChanged)
                SaveCurrentModStringEntries(stringEntries);
            await SaveManagedAbilityPowerAsync(newName, clone, originalName: null);
            _abilityPowerCatalog[newName] = new XElement(clone);
            RegisterAvailableAbilityName(newName);
            return true;
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to duplicate ability", ex.Message);
            await prompt.ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> RenameManagedAbilityAsync(string oldName, string newName)
    {
        if (!_abilityPowerCatalog.TryGetValue(oldName, out var power))
            return false;
        try
        {
            var renamed = new XElement(power);
            renamed.SetAttributeValue("name", newName);
            await SaveManagedAbilityPowerAsync(newName, renamed, oldName);
            _abilityPowerCatalog.Remove(oldName);
            _abilityPowerCatalog[newName] = new XElement(renamed);
            if (!_isDirty && !string.IsNullOrWhiteSpace(_currentUnitName))
                BuildEditorPanel(_currentUnitName, resetScroll: false);
            return true;
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to rename ability", ex.Message);
            await prompt.ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> DeleteManagedAbilityAsync(string abilityName)
    {
        var result = new AbilityManagerResult();
        result.DeletedNames.Add(abilityName);
        await ApplyAbilityManagerChangesAsync(result);
        return !_abilityPowerCatalog.ContainsKey(abilityName);
    }

    private async Task<string?> OpenManagedAbilityEditorAsync(Window owner, string abilityName, bool isBuiltIn)
    {
        if (!_abilityPowerCatalog.TryGetValue(abilityName, out var power))
        {
            var prompt = new Prompt(PromptType.Error, "Ability not found", $"Could not load '{abilityName}'.");
            await prompt.ShowDialog(this);
            return null;
        }

        var editor = new AbilityEditorWindow(_gameData);
        await editor.InitializeAbilityDefinitionEditorAsync(
            abilityName,
            isBuiltIn,
            new XElement(power),
            _modFilePath,
            isBuiltIn ? null : async (originalName, updatedPower) =>
            {
                var newName = GetAbilityElementName(updatedPower);
                await SaveManagedAbilityPowerAsync(newName, updatedPower, originalName);
                if (!originalName.Equals(newName, StringComparison.OrdinalIgnoreCase))
                    _abilityPowerCatalog.Remove(originalName);
                _abilityPowerCatalog[newName] = new XElement(updatedPower);

                // The standalone ability editor has its own string cache. It may have just
                // written Display Name/Rollover values to stringmods.txt, so never rebuild
                // the ProtoUnit ability UI from this window's stale cache.
                InvalidateModStringEntriesCache();
                if (!_isDirty && !string.IsNullOrWhiteSpace(_currentUnitName))
                    BuildEditorPanel(_currentUnitName, resetScroll: false);
            },
            _abilityPowerCatalog.Keys);
        await editor.ShowDialog(owner);
        return editor.CurrentAbilityDefinitionName;
    }

    private async Task SaveManagedAbilityPowerAsync(string abilityName, XElement updatedPower, string? originalName)
    {
        var path = GetCurrentModGameplayFilePath("powers_mods.xml");
        if (string.IsNullOrWhiteSpace(path))
            throw new InvalidOperationException("The active mod powers_mods.xml path could not be resolved.");
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var doc = LoadAbilityXmlDocumentForUpdate(path, "powersmod");
        if (doc.Root == null) doc.Add(new XElement("powersmod"));
        doc.Root!.Name = "powersmod";

        var oldName = string.IsNullOrWhiteSpace(originalName) ? abilityName : originalName;
        if (!oldName.Equals(abilityName, StringComparison.OrdinalIgnoreCase))
        {
            var collision = doc.Root.Elements().Any(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) &&
                                                         GetAbilityElementName(e).Equals(abilityName, StringComparison.OrdinalIgnoreCase));
            collision |= _abilityPowerCatalog.Keys.Any(name =>
                !name.Equals(oldName, StringComparison.OrdinalIgnoreCase) &&
                name.Equals(abilityName, StringComparison.OrdinalIgnoreCase));
            if (collision)
                throw new InvalidOperationException($"An ability named '{abilityName}' already exists. Choose a different internal name.");
        }
        var existing = doc.Root.Elements().FirstOrDefault(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) &&
                                                                GetAbilityElementName(e).Equals(oldName, StringComparison.OrdinalIgnoreCase));
        var replacement = new XElement(updatedPower);
        replacement.Name = "power";
        replacement.SetAttributeValue("name", abilityName);
        // The user may have edited powers_mods.xml manually while this editor was open.
        // Preserve unsupported placement attributes from the current on-disk power, not only
        // from the stale PowerSource captured when the editor window was opened.
        MergeUnknownPlacementAttributes(existing, replacement);

        Dictionary<string, string>? renamedStringEntries = null;
        var oldStringIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (!oldName.Equals(abilityName, StringComparison.OrdinalIgnoreCase))
        {
            renamedStringEntries = LoadCurrentModStringEntries(requireReadable: true);
            foreach (var tag in new[] { "displaynameid", "rolloverid" })
            {
                var replacementElement = replacement.Elements().FirstOrDefault(e => e.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));
                var sourceId = replacementElement?.Value?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(sourceId))
                    continue;

                string? sourceText = null;
                if (!renamedStringEntries.TryGetValue(sourceId, out sourceText))
                    sourceText = await _gameData.LookupStringKeyAsync(sourceId);
                if (sourceText == null)
                    throw new InvalidOperationException($"Could not resolve string '{sourceId}' while renaming '{oldName}'. The ability was not renamed.");

                var rollover = tag.Equals("rolloverid", StringComparison.OrdinalIgnoreCase);
                var newId = BuildUniqueAbilityStringId(abilityName, rollover, renamedStringEntries);
                replacementElement!.Value = newId;
                var updatedElement = updatedPower.Elements().FirstOrDefault(e => e.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));
                if (updatedElement != null)
                    updatedElement.Value = newId;
                renamedStringEntries[newId] = sourceText;
                oldStringIds.Add(sourceId);
            }

            // Write the new IDs before changing powers_mods.xml. If the XML write then fails,
            // the only side effect is harmless unused strings rather than a power that points
            // at missing string IDs.
            if (oldStringIds.Count > 0)
                SaveCurrentModStringEntries(renamedStringEntries);
        }

        if (existing != null) existing.ReplaceWith(replacement); else doc.Root.Add(replacement);
        SaveAbilityXmlDocument(doc, path);
        _abilityPowerCatalog[abilityName] = new XElement(replacement);
        RegisterAvailableAbilityName(abilityName);

        if (!oldName.Equals(abilityName, StringComparison.OrdinalIgnoreCase))
        {
            RenameAbilityReferencesInMods(oldName, abilityName);

            // Clean the previous generated IDs only after the power rename succeeded. A
            // cleanup failure leaves harmless orphan strings but never breaks the renamed
            // ability's references.
            if (renamedStringEntries != null && oldStringIds.Count > 0)
            {
                var referencedIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var power in doc.Root.Elements().Where(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase)))
                    foreach (var id in GetAbilityDefinitionStringIds(power))
                        referencedIds.Add(id);
                foreach (var catalogEntry in _abilityPowerCatalog)
                {
                    if (catalogEntry.Key.Equals(oldName, StringComparison.OrdinalIgnoreCase))
                        continue;
                    foreach (var id in GetAbilityDefinitionStringIds(catalogEntry.Value))
                        referencedIds.Add(id);
                }

                var cleanupChanged = false;
                foreach (var oldId in oldStringIds)
                {
                    if (oldId.StartsWith("STR_ABILITY_", StringComparison.OrdinalIgnoreCase) && !referencedIds.Contains(oldId))
                        cleanupChanged |= renamedStringEntries.Remove(oldId);
                }
                if (cleanupChanged)
                {
                    try { SaveCurrentModStringEntries(renamedStringEntries); }
                    catch { /* The rename is already safe; leave an orphan string rather than fail it. */ }
                }
            }
        }
    }

    private void RenameAbilityReferencesInMods(string oldName, string newName)
    {
        var path = GetCurrentModAbilitiesFilePath("abilities_mods.xml");
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path)) return;
        var doc = LoadAbilityXmlDocumentForUpdate(path, "abilitiesmods");
        var changed = false;
        foreach (var ability in doc.Root?.Descendants().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)) ?? [])
        {
            if (!GetAbilityElementName(ability).Equals(oldName, StringComparison.OrdinalIgnoreCase)) continue;
            foreach (var text in ability.Nodes().OfType<XText>().Where(t => !string.IsNullOrWhiteSpace(t.Value)).ToList()) text.Remove();
            ability.AddFirst(new XText(newName));
            changed = true;
        }
        if (changed) SaveAbilityXmlDocument(doc, path);
    }

    private static IEnumerable<string> GetAbilityDefinitionStringIds(XElement power)
    {
        foreach (var tag in new[] { "displaynameid", "rolloverid" })
        {
            var id = power.Elements()
                .FirstOrDefault(element => element.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase))
                ?.Value?.Trim();
            if (!string.IsNullOrWhiteSpace(id))
                yield return id;
        }
    }

    private bool IsStringIdReferencedByCurrentProtoData(string id)
    {
        if (string.IsNullOrWhiteSpace(id) || _modXmlRoot == null)
            return false;

        return _modXmlRoot.Descendants()
            .Any(element => string.Equals(element.Value?.Trim(), id, StringComparison.OrdinalIgnoreCase));
    }

    private async Task ApplyAbilityManagerChangesAsync(AbilityManagerResult result)
    {
        var powersPath = GetCurrentModGameplayFilePath("powers_mods.xml");
        if (string.IsNullOrWhiteSpace(powersPath)) return;
        try
        {
            var doc = LoadAbilityXmlDocumentForUpdate(powersPath, "powersmod");
            if (doc.Root == null) doc.Add(new XElement("powersmod"));
            doc.Root!.Name = "powersmod";

            var deletedNames = result.DeletedNames.ToHashSet(StringComparer.OrdinalIgnoreCase);
            var deletedStringIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var power in doc.Root.Elements().Where(element =>
                         element.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) &&
                         deletedNames.Contains(GetAbilityElementName(element))))
            {
                foreach (var id in GetAbilityDefinitionStringIds(power))
                    deletedStringIds.Add(id);
            }

            // Read stringmods before changing powers_mods.xml. If stringmods is locked
            // or unreadable, deletion aborts instead of leaving a partially applied change.
            Dictionary<string, string>? stringEntries = null;
            if (deletedStringIds.Count > 0)
                stringEntries = LoadCurrentModStringEntries(requireReadable: true);

            foreach (var rename in result.Renames)
            {
                var power = doc.Root.Elements().FirstOrDefault(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) &&
                                                                    GetAbilityElementName(e).Equals(rename.OldName, StringComparison.OrdinalIgnoreCase));
                if (power == null) continue;
                power.SetAttributeValue("name", rename.NewName);
                RenameAbilityReferencesInMods(rename.OldName, rename.NewName);
                if (_abilityPowerCatalog.Remove(rename.OldName, out var cached))
                {
                    cached.SetAttributeValue("name", rename.NewName);
                    _abilityPowerCatalog[rename.NewName] = cached;
                }
            }

            foreach (var deletedName in result.DeletedNames)
            {
                foreach (var power in doc.Root.Elements().Where(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) &&
                                                                      GetAbilityElementName(e).Equals(deletedName, StringComparison.OrdinalIgnoreCase)).ToList())
                    power.Remove();
                _abilityPowerCatalog.Remove(deletedName);
            }

            var stringsChanged = false;
            if (stringEntries != null && deletedStringIds.Count > 0)
            {
                var remainingAbilityStringIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach (var power in doc.Root.Elements().Where(element => element.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase)))
                    foreach (var id in GetAbilityDefinitionStringIds(power))
                        remainingAbilityStringIds.Add(id);

                // The catalog contains base-game powers too, so a string override that is
                // still referenced by another Original/shared ability is kept.
                foreach (var catalogEntry in _abilityPowerCatalog)
                {
                    if (deletedNames.Contains(catalogEntry.Key))
                        continue;
                    foreach (var id in GetAbilityDefinitionStringIds(catalogEntry.Value))
                        remainingAbilityStringIds.Add(id);
                }

                foreach (var id in deletedStringIds)
                {
                    // Only clean ability-owned IDs, and only if nothing else we know about
                    // still references them. This avoids deleting unrelated shared strings.
                    if (!id.StartsWith("STR_ABILITY_", StringComparison.OrdinalIgnoreCase) ||
                        remainingAbilityStringIds.Contains(id) ||
                        IsStringIdReferencedByCurrentProtoData(id))
                    {
                        continue;
                    }
                    stringsChanged |= stringEntries.Remove(id);
                }
            }

            SaveAbilityXmlDocument(doc, powersPath);
            if (stringsChanged && stringEntries != null)
                SaveCurrentModStringEntries(stringEntries);
            if (!_isDirty && !string.IsNullOrWhiteSpace(_currentUnitName))
                BuildEditorPanel(_currentUnitName, resetScroll: false);
            _statusMessage.Text = "Ability changes saved.";
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to manage abilities", ex.Message);
            await prompt.ShowDialog(this);
        }
    }

    private async Task OpenTacticsManagerAsync()
    {
        if (_modXmlRoot == null && !await EnsureLocalModAsync())
            return;
        if (_modXmlRoot == null || string.IsNullOrWhiteSpace(_modFilePath))
            return;

        ApplyCurrentEdits();
        var customNames = GetCustomTacticsNames();
        var builtInNames = GetBuiltInTacticsNames();
        var usageCounts = GetTacticsUsageCounts();
        var items = GetAvailableTacticsNames()
            .Select(name => new TacticsManagerItem(
                name,
                IsBuiltIn: !customNames.Contains(name),
                IsModifiedBuiltIn: customNames.Contains(name) && builtInNames.Contains(name),
                UsageCount: usageCounts.GetValueOrDefault(name)))
            .ToList();

        var window = new TacticsManagerWindow(
            items,
            OpenManagedTacticsEditorAsync,
            CreateManagedTacticsFileAsync,
            DuplicateManagedTacticsFileAsync,
            RenameManagedTacticsFileAsync,
            DeleteManagedTacticsFileAsync);
        await window.ShowDialog(this);
    }

    private async Task<bool> CreateManagedTacticsFileAsync(string tacticsName)
    {
        var path = GetCustomTacticsPath(tacticsName);
        if (path == null)
            return false;

        try
        {
            if (File.Exists(path))
            {
                var existingPrompt = new Prompt(
                    PromptType.Error,
                    "Tactics already exists",
                    $"A tactics file named '{tacticsName}' already exists.");
                await existingPrompt.ShowDialog(this);
                return false;
            }

            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            WriteTacticsTextAtomic(path, NewTacticsTemplate);
            _tacticsActionCache.Clear();
            _tacticsLoadDiagnostics.Clear();
            _resolvedTacticsActionSources.Clear();
            return true;
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to create tactics", ex.Message);
            await prompt.ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> DuplicateManagedTacticsFileAsync(string sourceName, bool sourceIsBuiltIn, string newName)
    {
        var targetPath = GetCustomTacticsPath(newName);
        if (targetPath == null)
            return false;

        try
        {
            if (File.Exists(targetPath))
            {
                var existingPrompt = new Prompt(
                    PromptType.Error,
                    "Tactics already exists",
                    $"A tactics file named '{newName}' already exists.");
                await existingPrompt.ShowDialog(this);
                return false;
            }

            Directory.CreateDirectory(Path.GetDirectoryName(targetPath)!);

            if (!sourceIsBuiltIn)
            {
                var sourcePath = GetCustomTacticsPath(sourceName);
                if (sourcePath == null || !File.Exists(sourcePath))
                {
                    var missingPrompt = new Prompt(
                        PromptType.Error,
                        "Tactics file not found",
                        $"Could not find '{sourceName}' in the active mod tactics folder.");
                    await missingPrompt.ShowDialog(this);
                    return false;
                }

                CopyTacticsFileAtomic(sourcePath, targetPath);
            }
            else
            {
                var document = LoadBuiltInTacticsDocumentForManagerEditor(sourceName);
                if (document?.Root == null)
                {
                    var loadPrompt = new Prompt(
                        PromptType.Error,
                        "Unable to duplicate tactics",
                        $"The full tactics definition for '{sourceName}' could not be loaded from Data.bar. Duplication was cancelled to avoid creating an incomplete tactics file.");
                    await loadPrompt.ShowDialog(this);
                    return false;
                }

                RemoveFormattingWhitespace(document);
                SaveTacticsDocumentAtomic(document, targetPath);
            }

            _tacticsActionCache.Clear();
            _tacticsLoadDiagnostics.Clear();
            _resolvedTacticsActionSources.Clear();
            return true;
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to duplicate tactics", ex.Message);
            await prompt.ShowDialog(this);
            return false;
        }
    }

    private async Task<bool> RenameManagedTacticsFileAsync(string oldName, string newName)
    {
        var result = new TacticsManagerResult();
        result.Renames.Add(new TacticsRenameOperation(oldName, newName));
        await ApplyTacticsManagerChangesAsync(result);

        var oldPath = GetCustomTacticsPath(oldName);
        var newPath = GetCustomTacticsPath(newName);
        return newPath != null && File.Exists(newPath) && (oldPath == null || !File.Exists(oldPath));
    }

    private async Task<bool> DeleteManagedTacticsFileAsync(string tacticsName)
    {
        var result = new TacticsManagerResult();
        result.DeletedNames.Add(tacticsName);
        await ApplyTacticsManagerChangesAsync(result);

        var path = GetCustomTacticsPath(tacticsName);
        return path == null || !File.Exists(path);
    }

    private async Task OpenManagedTacticsEditorAsync(Window owner, string tacticsName, bool isBuiltIn)
    {
        XDocument document;
        string? customPath = null;

        if (!isBuiltIn)
        {
            customPath = GetCustomTacticsPath(tacticsName);
            if (customPath == null || !File.Exists(customPath))
            {
                var prompt = new Prompt(PromptType.Error, "Tactics file not found", $"Could not find '{tacticsName}' in the active mod tactics folder.");
                await prompt.ShowDialog(this);
                return;
            }

            try
            {
                document = XDocument.Load(customPath, LoadOptions.PreserveWhitespace);
            }
            catch (Exception originalException)
            {
                // Repair the exact malformed armoroverride closing tag produced by older
                // editor builds, but do not broadly "fix" unrelated invalid XML.
                try
                {
                    var raw = File.ReadAllText(customPath);
                    var repaired = Regex.Replace(
                        raw,
                        @"(<armoroverride\b[^>]*>[^<]*)</armor>",
                        "$1</armoroverride>",
                        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
                    if (string.Equals(raw, repaired, StringComparison.Ordinal))
                    {
                        var prompt = new Prompt(PromptType.Error, "Unable to open tactics", originalException.Message);
                        await prompt.ShowDialog(this);
                        return;
                    }
                    document = XDocument.Parse(repaired, LoadOptions.PreserveWhitespace);
                    // Persist the exact legacy repair immediately. Otherwise the preview is fixed
                    // in memory while the malformed source file remains broken on disk.
                    SaveTacticsDocumentAtomic(document, customPath);
                }
                catch
                {
                    var prompt = new Prompt(PromptType.Error, "Unable to open tactics", originalException.Message);
                    await prompt.ShowDialog(this);
                    return;
                }
            }
        }
        else
        {
            document = LoadBuiltInTacticsDocumentForManagerEditor(tacticsName)
                ?? BuildTacticsDocumentFromLoadedActions(tacticsName);

            if (document.Root == null ||
                !document.Root.Elements().Any(element =>
                    element.Name.LocalName.Equals("action", StringComparison.OrdinalIgnoreCase)))
            {
                var prompt = new Prompt(
                    PromptType.Error,
                    "Unable to load tactics",
                    $"No action definitions could be loaded from '{tacticsName}'.");
                await prompt.ShowDialog(this);
                return;
            }
        }

        var editor = new TacticsEditorWindow();
        var expectedCustomHash = customPath == null ? null : ComputeFileSha256(customPath);
        await editor.InitializeTacticsActionEditorAsync(
            tacticsName,
            isBuiltIn,
            document,
            customPath == null
                ? null
                : async updatedDocument =>
                {
                    var currentHash = ComputeFileSha256(customPath);
                    if (!string.Equals(expectedCustomHash, currentHash, StringComparison.OrdinalIgnoreCase))
                    {
                        var changedPrompt = new Prompt(
                            PromptType.Confirm,
                            "Tactics changed on disk",
                            "This tactics file changed on disk after it was opened. Saving now will overwrite those external changes. Continue?",
                            confirmButtonText: "Save");
                        await changedPrompt.ShowDialog(editor);
                        if (!changedPrompt.Confirmed)
                            return TacticsDocumentSaveOutcome.Cancelled;
                    }

                    RemoveFormattingWhitespace(updatedDocument);
                    SaveTacticsDocumentAtomic(updatedDocument, customPath);
                    expectedCustomHash = ComputeFileSha256(customPath);
                    _tacticsActionCache.Clear();
                    _tacticsLoadDiagnostics.Clear();
                    _resolvedTacticsActionSources.Clear();
                    if (!string.IsNullOrWhiteSpace(_currentUnitName) && _modXmlRoot != null)
                    {
                        var currentUnit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, _currentUnitName);
                        if (currentUnit != null)
                            RefreshCurrentUnitProtoActionMetadata(currentUnit);
                        BuildEditorPanel(_currentUnitName, resetScroll: false);
                    }

                    return TacticsDocumentSaveOutcome.Saved;
                });
        await editor.ShowDialog(owner);
    }


    private static string? ComputeFileSha256(string path)
    {
        if (!File.Exists(path))
            return null;
        using var stream = File.Open(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
        return Convert.ToHexString(SHA256.HashData(stream));
    }

    private static void SaveXmlDocumentAtomic(XDocument document, string path)
    {
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);

        var tempPath = path + ".tmp." + Guid.NewGuid().ToString("N");
        try
        {
            ProtoXmlHandler.SaveProtoXml(document, tempPath);
            File.Move(tempPath, path, overwrite: true);
        }
        finally
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
    }

    private static void SaveTacticsDocumentAtomic(XDocument document, string path)
        => SaveXmlDocumentAtomic(document, path);

    private static void WriteTacticsTextAtomic(string path, string contents)
    {
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);

        var tempPath = path + ".tmp." + Guid.NewGuid().ToString("N");
        try
        {
            File.WriteAllText(tempPath, contents, new UTF8Encoding(false));
            File.Move(tempPath, path, overwrite: false);
        }
        finally
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
    }

    private static void CopyTacticsFileAtomic(string sourcePath, string targetPath)
    {
        var directory = Path.GetDirectoryName(targetPath);
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);

        var tempPath = targetPath + ".tmp." + Guid.NewGuid().ToString("N");
        try
        {
            File.Copy(sourcePath, tempPath, overwrite: false);
            File.Move(tempPath, targetPath, overwrite: false);
        }
        finally
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
    }

    private static void RemoveFormattingWhitespace(XDocument document)
    {
        foreach (var textNode in document.DescendantNodes().OfType<XText>()
                     .Where(node => string.IsNullOrWhiteSpace(node.Value))
                     .ToList())
        {
            textNode.Remove();
        }
    }

    private XDocument BuildTacticsDocumentFromLoadedActions(string tacticsName)
    {
        var root = new XElement("tactics");
        var loadedActions = LoadTacticsActionsForManagerEditor(tacticsName);
        foreach (var action in loadedActions.Values
                     .OrderBy(action => action.Name, StringComparer.OrdinalIgnoreCase))
        {
            var temporaryUnit = new XElement("unit");
            ProtoXmlHandler.SetProtoActions(temporaryUnit, [action.Clone()]);
            var serialized = temporaryUnit.Element("protoaction");
            if (serialized == null)
                continue;

            serialized.Name = "action";
            root.Add(serialized);
        }

        return new XDocument(root);
    }

    private XDocument? LoadBuiltInTacticsDocumentForManagerEditor(string tacticsName)
    {
        var candidateFileNames = BuildTacticsCandidateRelativePaths(tacticsName)
            .Select(path => path.Replace('\\', '/').Split('/').LastOrDefault())
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .Cast<string>()
            .ToHashSet(StringComparer.OrdinalIgnoreCase);

        if (candidateFileNames.Count == 0)
            return null;

        try
        {
            if (_protoDataBarFile != null && !string.IsNullOrWhiteSpace(_protoDataBarPath))
            {
                var cachedBarDocument = ExtractTacticsDocumentFromBar(
                    _protoDataBarFile,
                    _protoDataBarPath,
                    candidateFileNames);
                if (cachedBarDocument != null)
                    return cachedBarDocument;
            }

            var dataBarPath = ResolveDataBarPath();
            if (!string.IsNullOrWhiteSpace(dataBarPath) && File.Exists(dataBarPath))
            {
                using var stream = File.OpenRead(dataBarPath);
                var barFile = new BarArchive(stream);
                if (barFile.Load(out _))
                {
                    return ExtractTacticsDocumentFromBar(
                        barFile,
                        dataBarPath,
                        candidateFileNames);
                }
            }
        }
        catch
        {
            // The action-map fallback below still gives older cached setups a chance.
        }

        return null;
    }

    private static XDocument? ExtractTacticsDocumentFromBar(
        BarArchive barFile,
        string barPath,
        HashSet<string> candidateFileNames)
    {
        var entries = barFile.Entries;
        if (entries == null)
            return null;

        var matchingEntries = entries
            .Where(entry =>
            {
                var normalizedEntryName = entry.Name.Replace('\\', '/');
                var fileName = normalizedEntryName.Split('/').LastOrDefault() ?? "";
                return normalizedEntryName.Contains("tactics", StringComparison.OrdinalIgnoreCase) &&
                       fileName.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase) &&
                       candidateFileNames.Contains(fileName);
            })
            .ToList();

        using var dataStream = File.OpenRead(barPath);
        foreach (var entry in matchingEntries)
        {
            var size = entry.IsCompressed ? entry.SizeUncompressed : entry.SizeInArchive;
            var decompressed = new byte[size];
            var readBytes = entry.ReadDataDecompressed(dataStream, decompressed);
            if (readBytes <= 0)
                continue;

            var xml = XmbReader.ToFormattedXml(decompressed.AsSpan(0, readBytes));
            if (string.IsNullOrWhiteSpace(xml))
                continue;

            var document = XDocument.Parse(xml, LoadOptions.PreserveWhitespace);
            if (document.Root != null &&
                document.Root.Name.LocalName.Equals("tactics", StringComparison.OrdinalIgnoreCase))
            {
                return document;
            }
        }

        return null;
    }


    private Dictionary<string, ProtoAction> LoadTacticsActionsForManagerEditor(string tacticsName)
    {
        var candidates = new List<string>();

        void AddCandidate(string? value)
        {
            var normalized = value?.Trim() ?? "";
            if (normalized.Length > 0 && !candidates.Contains(normalized, StringComparer.OrdinalIgnoreCase))
                candidates.Add(normalized);
        }

        AddCandidate(tacticsName);
        if (tacticsName.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase))
            AddCandidate(tacticsName[..^".tactics".Length]);
        else
            AddCandidate(tacticsName + ".tactics");

        // Most unit references omit the extension while the manager deliberately
        // displays it. Reuse whichever alias was populated during the startup scan
        // before performing another BAR lookup.
        foreach (var candidate in candidates)
        {
            if (_tacticsActionCache.TryGetValue(candidate, out var cached) &&
                (cached.Count > 0 || _resolvedTacticsActionSources.Contains(candidate)))
                return cached;
        }

        foreach (var candidate in candidates)
        {
            var loaded = LoadProtoActionsForTactics(candidate);
            if (loaded.Count > 0 || _resolvedTacticsActionSources.Contains(candidate))
                return loaded;
        }

        return new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
    }

    private async Task ApplyTacticsManagerChangesAsync(TacticsManagerResult result)
    {
        if (_modXmlRoot == null || _modXmlDoc == null || string.IsNullOrWhiteSpace(_modFilePath))
            return;

        var tacticsDirectory = GetModTacticsDirectory();
        if (tacticsDirectory == null)
            return;
        Directory.CreateDirectory(tacticsDirectory);

        try
        {
            foreach (var rename in result.Renames)
            {
                var oldPath = GetCustomTacticsPath(rename.OldName);
                var newPath = GetCustomTacticsPath(rename.NewName);
                if (oldPath == null || newPath == null || !File.Exists(oldPath))
                    continue;
                if (File.Exists(newPath))
                    throw new IOException($"A tactics file named '{rename.NewName}' already exists.");

                var xmlBackup = new XDocument(_modXmlDoc);
                var moved = false;
                try
                {
                    Directory.CreateDirectory(Path.GetDirectoryName(newPath)!);
                    File.Move(oldPath, newPath);
                    moved = true;
                    RenameTacticsReferences(rename.OldName, rename.NewName);
                    SaveXmlDocumentAtomic(_modXmlDoc, _modFilePath);
                }
                catch
                {
                    _modXmlDoc = xmlBackup;
                    _modXmlRoot = xmlBackup.Root;
                    if (moved && File.Exists(newPath) && !File.Exists(oldPath))
                        File.Move(newPath, oldPath);
                    throw;
                }
            }

            foreach (var createdName in result.CreatedNames)
            {
                var path = GetCustomTacticsPath(createdName);
                if (path == null || File.Exists(path))
                    continue;
                Directory.CreateDirectory(Path.GetDirectoryName(path)!);
                WriteTacticsTextAtomic(path, NewTacticsTemplate);
            }

            foreach (var deletedName in result.DeletedNames)
            {
                var path = GetCustomTacticsPath(deletedName);
                if (path != null && File.Exists(path))
                    File.Delete(path);
            }

            _tacticsActionCache.Clear();
            _tacticsLoadDiagnostics.Clear();
            _resolvedTacticsActionSources.Clear();
            // Managing tactics writes its own files immediately, but must not
            // clear unsaved ProtoUnit drafts captured by the main editor.
            _isDirty = _dirtyUnitNames.Count > 0;
            _fileLabel.Text = _modFilePath;
            if (_isDirty)
                _fileLabel.Text += " *";
            _statusMessage.Text = "Tactics changes saved.";

            if (!string.IsNullOrWhiteSpace(_currentUnitName))
                BuildEditorPanel(_currentUnitName, resetScroll: false);
        }
        catch (Exception ex)
        {
            var prompt = new Prompt(PromptType.Error, "Unable to manage tactics", ex.Message);
            await prompt.ShowDialog(this);
        }
    }

    private void RenameTacticsReferences(string oldName, string newName)
    {
        if (_modXmlRoot == null)
            return;

        var normalizedOld = NormalizeManagedTacticsName(oldName);
        var normalizedNew = NormalizeManagedTacticsName(newName);
        foreach (var tacticsElement in _modXmlRoot.Descendants()
                     .Where(element => element.Name.LocalName.Equals("tactics", StringComparison.OrdinalIgnoreCase)))
        {
            if (NormalizeManagedTacticsName(tacticsElement.Value)
                .Equals(normalizedOld, StringComparison.OrdinalIgnoreCase))
            {
                tacticsElement.Value = normalizedNew;
            }
        }
    }

    private HashSet<string> GetBuiltInTacticsNames()
    {
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        static string NormalizeBarTacticsName(string entryName)
        {
            var normalized = entryName.Replace('/', '\\').Trim();
            var marker = "tactics\\";
            var index = normalized.LastIndexOf(marker, StringComparison.OrdinalIgnoreCase);
            if (index >= 0)
                normalized = normalized[(index + marker.Length)..];
            else
                normalized = Path.GetFileName(normalized);

            if (normalized.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
                normalized = normalized[..^4];
            if (!normalized.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase))
                normalized += ".tactics";
            return normalized;
        }

        void AddBarEntries(BarArchive? barFile)
        {
            if (barFile?.Entries == null)
                return;

            foreach (var entry in barFile.Entries)
            {
                if (!entry.Name.Contains("tactics", StringComparison.OrdinalIgnoreCase) ||
                    !entry.Name.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
                    continue;

                var name = NormalizeBarTacticsName(entry.Name);
                if (!string.IsNullOrWhiteSpace(name))
                    names.Add(name);
            }
        }

        AddBarEntries(_protoDataBarFile);

        return names;
    }

    private List<string> GetAvailableTacticsNames()
    {
        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        static string NormalizeTacticsName(string pathOrEntry, string? tacticsRoot = null)
        {
            var normalized = pathOrEntry.Replace('/', Path.DirectorySeparatorChar).Replace('\\', Path.DirectorySeparatorChar);
            if (!string.IsNullOrWhiteSpace(tacticsRoot))
                normalized = Path.GetRelativePath(tacticsRoot, normalized);
            else
            {
                var marker = $"tactics{Path.DirectorySeparatorChar}";
                var index = normalized.LastIndexOf(marker, StringComparison.OrdinalIgnoreCase);
                if (index >= 0)
                    normalized = normalized[(index + marker.Length)..];
                else
                    normalized = Path.GetFileName(normalized);
            }

            if (normalized.EndsWith(".tactics.xmb", StringComparison.OrdinalIgnoreCase))
                normalized = normalized[..^".xmb".Length];
            else if (normalized.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
                normalized = normalized[..^".xmb".Length];

            normalized = normalized.Replace(Path.DirectorySeparatorChar, '\\').Trim();
            if (!normalized.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase))
                normalized += ".tactics";
            return normalized;
        }

        static void AddLooseDirectory(HashSet<string> target, string? gameplayDirectory)
        {
            if (string.IsNullOrWhiteSpace(gameplayDirectory))
                return;
            var tacticsDirectory = Path.Combine(gameplayDirectory, "tactics");
            if (!Directory.Exists(tacticsDirectory))
                return;

            foreach (var path in Directory.GetFiles(tacticsDirectory, "*", SearchOption.AllDirectories))
            {
                var fileName = Path.GetFileName(path);
                if (!fileName.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase) &&
                    !fileName.EndsWith(".tactics.xmb", StringComparison.OrdinalIgnoreCase) &&
                    !fileName.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
                    continue;
                var name = NormalizeTacticsName(path, tacticsDirectory);
                if (!string.IsNullOrWhiteSpace(name))
                    target.Add(name);
            }
        }

        void AddBarEntries(BarArchive? barFile)
        {
            if (barFile?.Entries == null)
                return;
            foreach (var entry in barFile.Entries)
            {
                if (!entry.Name.Contains("tactics", StringComparison.OrdinalIgnoreCase) ||
                    !entry.Name.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
                    continue;
                var name = NormalizeTacticsName(entry.Name);
                if (!string.IsNullOrWhiteSpace(name))
                    names.Add(name);
            }
        }

        AddBarEntries(_protoDataBarFile);

        AddLooseDirectory(names, ResolveBaseGameplayDirectory());
        AddLooseDirectory(names, string.IsNullOrWhiteSpace(_modFilePath) ? null : Path.GetDirectoryName(_modFilePath));

        return names.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
    }

    private IEnumerable<string> GetTacticsCandidatePaths(string tacticsName)
    {
        var relatives = BuildTacticsCandidateRelativePaths(tacticsName);
        var yielded = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        void AddDirectory(string? tacticsDirectory, List<string> output)
        {
            if (string.IsNullOrWhiteSpace(tacticsDirectory))
                return;

            foreach (var relative in relatives)
            {
                var candidate = ResolveContainedTacticsPath(tacticsDirectory, relative);
                if (candidate != null && yielded.Add(candidate))
                    output.Add(candidate);
            }
        }

        var candidates = new List<string>();

        // The active mod must be checked as well as Data.bar/base data. Custom tactics
        // discovered by the selector otherwise appeared valid but had no inherited actions.
        AddDirectory(GetModTacticsDirectory(), candidates);

        var baseGameplayDir = ResolveBaseGameplayDirectory();
        AddDirectory(
            string.IsNullOrWhiteSpace(baseGameplayDir) ? null : Path.Combine(baseGameplayDir, "tactics"),
            candidates);

        foreach (var candidate in candidates)
            yield return candidate;
    }

    private static List<string> BuildTacticsCandidateRelativePaths(string tacticsName)
    {
        var requestedName = tacticsName.Trim();
        if (string.IsNullOrWhiteSpace(requestedName) || Path.IsPathRooted(requestedName))
            return [];

        var normalized = requestedName
            .Replace('/', Path.DirectorySeparatorChar)
            .Replace('\\', Path.DirectorySeparatorChar);

        var segments = normalized.Split(
            Path.DirectorySeparatorChar,
            StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (segments.Length == 0 ||
            segments.Any(segment => segment is "." or ".." || segment.Contains(':')))
        {
            return [];
        }

        normalized = Path.Combine(segments);

        var tacticsPrefix = $"tactics{Path.DirectorySeparatorChar}";
        if (normalized.StartsWith(tacticsPrefix, StringComparison.OrdinalIgnoreCase))
            normalized = normalized[tacticsPrefix.Length..];

        var candidates = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        void AddCandidate(string candidate)
        {
            if (!string.IsNullOrWhiteSpace(candidate))
                candidates.Add(candidate);
        }

        AddCandidate(normalized);

        if (normalized.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase))
        {
            AddCandidate(normalized + ".XMB");
        }
        else if (normalized.EndsWith(".tactics.xmb", StringComparison.OrdinalIgnoreCase) ||
                 normalized.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase))
        {
            // Exact path already added.
        }
        else
        {
            AddCandidate(normalized + ".tactics");
            AddCandidate(normalized + ".tactics.XMB");
            AddCandidate(normalized + ".XMB");
        }

        return candidates.ToList();
    }

    internal static string? ResolveContainedTacticsPath(string tacticsDirectory, string relativePath)
    {
        if (string.IsNullOrWhiteSpace(tacticsDirectory) ||
            string.IsNullOrWhiteSpace(relativePath) ||
            Path.IsPathRooted(relativePath))
        {
            return null;
        }

        var root = Path.GetFullPath(tacticsDirectory);
        var candidate = Path.GetFullPath(Path.Combine(root, relativePath));
        var relativeToRoot = Path.GetRelativePath(root, candidate);
        if (relativeToRoot.Equals("..", StringComparison.Ordinal) ||
            relativeToRoot.StartsWith($"..{Path.DirectorySeparatorChar}", StringComparison.Ordinal) ||
            Path.IsPathRooted(relativeToRoot))
        {
            return null;
        }

        return candidate;
    }

    private Dictionary<string, ProtoAction> LoadProtoActionsFromBarTactics(string tacticsName)
    {
        try
        {
            var candidateFileNames = BuildTacticsCandidateRelativePaths(tacticsName)
                .Select(Path.GetFileName)
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Cast<string>()
                .ToHashSet(StringComparer.OrdinalIgnoreCase);

            if (candidateFileNames.Count == 0)
                return new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);

            if (_protoDataBarFile != null && !string.IsNullOrWhiteSpace(_protoDataBarPath))
            {
                return ExtractTacticsActionsFromBar(_protoDataBarFile, _protoDataBarPath, candidateFileNames);
            }

            var dataBarPath = ResolveDataBarPath();
            if (!string.IsNullOrWhiteSpace(dataBarPath) && File.Exists(dataBarPath))
            {
                using var stream = File.OpenRead(dataBarPath);
                var file = new BarArchive(stream);
                if (file.Load(out _))
                    return ExtractTacticsActionsFromBar(file, dataBarPath, candidateFileNames);
            }
        }
        catch (Exception ex)
        {
            return CacheInvalidTacticsResult(tacticsName, "Data.bar", ex);
        }

        return new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
    }

    internal static Dictionary<string, ProtoAction> ParseTacticsActions(string xml)
    {
        var doc = XDocument.Parse(xml, LoadOptions.PreserveWhitespace);
        var result = new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
        var duplicateNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var actionElement in doc.Descendants("action"))
        {
            // Tactics documents also contain unnamed <action> nodes in their tactic
            // rules. Only named nodes are ProtoAction definitions; the others must
            // remain available to the tactic parser and are intentionally skipped here.
            var actionName = actionElement.Element("name")?.Value?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(actionName))
                continue;

            var parsed = ProtoXmlHandler.ParseProtoActionLikeElement(actionElement);

            if (!result.TryAdd(actionName, parsed))
                duplicateNames.Add(actionName);
        }

        if (duplicateNames.Count > 0)
        {
            throw new InvalidDataException(
                $"Invalid tactics actions: duplicate action name(s): {string.Join(", ", duplicateNames.OrderBy(name => name, StringComparer.OrdinalIgnoreCase))}.");
        }

        return result;
    }

    private static void MergeTacticsActionTypes(Dictionary<string, string> result, string xml)
    {
        var doc = XDocument.Parse(xml, LoadOptions.PreserveWhitespace);
        foreach (var action in doc.Descendants("action"))
        {
            var actionName = action.Element("name")?.Value?.Trim();
            var actionType = action.Element("type")?.Value?.Trim();
            if (!string.IsNullOrWhiteSpace(actionName) && !string.IsNullOrWhiteSpace(actionType))
                result[actionName] = actionType;
        }
    }

    private static Dictionary<string, ProtoAction> ExtractTacticsActionsFromBar(BarArchive barFile, string barPath, HashSet<string> candidateFileNames)
    {
        var result = new Dictionary<string, ProtoAction>(StringComparer.OrdinalIgnoreCase);
        var entries = barFile.Entries;
        if (entries == null || candidateFileNames.Count == 0)
            return result;

        var tacticsEntries = entries
            .Where(e => e.Name.Contains("tactics", StringComparison.OrdinalIgnoreCase)
                     && e.Name.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase)
                     && candidateFileNames.Contains(Path.GetFileName(e.Name.Replace('/', '\\'))))
            .OrderBy(e => e.Name, StringComparer.OrdinalIgnoreCase)
            .ToList();

        using var tempStream = File.OpenRead(barPath);
        foreach (var entry in tacticsEntries)
        {
            int size = entry.IsCompressed ? entry.SizeUncompressed : entry.SizeInArchive;
            byte[] decompressed = new byte[size];
            int readBytes = entry.ReadDataDecompressed(tempStream, decompressed);
            if (readBytes <= 0)
                continue;

            var xml = XmbReader.ToFormattedXml(decompressed.AsSpan(0, readBytes));
            if (string.IsNullOrWhiteSpace(xml))
                continue;

            var parsedActions = ParseTacticsActions(xml);
            foreach (var (actionName, action) in parsedActions)
            {
                if (!result.TryAdd(actionName, action))
                    throw new InvalidDataException(
                        $"Invalid tactics archive match: duplicate action name '{actionName}' across matching entries.");
            }
        }

        return result;
    }

    private void EnsureBarProtoActionSuggestionDataLoaded()
    {
        if (_barProtoActionSuggestionDataLoaded)
            return;

        try
        {
            if (_protoDataBarFile != null && !string.IsNullOrWhiteSpace(_protoDataBarPath))
            {
                (_barProtoActionAnimationNames, _barProtoActionAttachmentPaths, _barProtoActionModelAttachmentBones) =
                    ExtractProtoActionSuggestionDataFromBar(_protoDataBarFile, _protoDataBarPath);
            }
        }
        catch
        {
            // Leave the BAR-derived suggestion sets empty if the scan is unavailable.
        }

        _barProtoActionSuggestionDataLoaded = true;
    }

    private static (List<string> AnimationNames, List<string> AttachmentPaths, List<string> ModelAttachmentBones) ExtractProtoActionSuggestionDataFromBar(BarArchive barFile, string barPath)
    {
        var animationNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var attachmentPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var modelAttachmentBones = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var entries = barFile.Entries;
        if (entries == null)
            return ([], [], []);

        var candidateEntries = entries
            .Where(e =>
                e.Name.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase) &&
                (e.Name.Contains("proto", StringComparison.OrdinalIgnoreCase) ||
                 e.Name.Contains("tactics", StringComparison.OrdinalIgnoreCase)))
            .ToList();

        using var tempStream = File.OpenRead(barPath);
        foreach (var entry in candidateEntries)
        {
            try
            {
                int size = entry.IsCompressed ? entry.SizeUncompressed : entry.SizeInArchive;
                byte[] decompressed = new byte[size];
                int readBytes = entry.ReadDataDecompressed(tempStream, decompressed);
                if (readBytes <= 0)
                    continue;

                var xml = XmbReader.ToFormattedXml(decompressed.AsSpan(0, readBytes));
                if (string.IsNullOrWhiteSpace(xml))
                    continue;

                var doc = XDocument.Parse(xml, LoadOptions.PreserveWhitespace);
                animationNames.UnionWith(ExtractGlobalAnimationNames(doc));
                foreach (var element in doc
                    .Descendants()
                    .Where(x =>
                        x.Name.LocalName.Equals("protoaction", StringComparison.OrdinalIgnoreCase) ||
                        x.Name.LocalName.Equals("action", StringComparison.OrdinalIgnoreCase))
                    .Elements())
                {
                    var value = element.Value?.Trim();
                    if (string.IsNullOrWhiteSpace(value))
                        continue;

                    if (GlobalAnimationValueTags.Contains(element.Name.LocalName))
                    {
                        animationNames.Add(value);
                        continue;
                    }

                    if (AttachmentPathTags.Contains(element.Name.LocalName, StringComparer.OrdinalIgnoreCase))
                    {
                        attachmentPaths.Add(value);
                        continue;
                    }

                    if (element.Name.LocalName.Equals("modelattachmentbone", StringComparison.OrdinalIgnoreCase))
                        modelAttachmentBones.Add(value);
                }

                foreach (var bone in doc
                    .Descendants()
                    .Where(x => x.Name.LocalName.Equals("onhiteffect", StringComparison.OrdinalIgnoreCase))
                    .Attributes("attachbone")
                    .Select(x => x.Value?.Trim())
                    .Where(x => !string.IsNullOrWhiteSpace(x)))
                {
                    modelAttachmentBones.Add(bone!);
                }
            }
            catch
            {
                // Skip malformed or unsupported entries and keep scanning.
            }
        }

        return (
            animationNames.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList(),
            attachmentPaths.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList(),
            modelAttachmentBones.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList());
    }

    private void ResetEditorScrollToTop()
    {
        _editorScroll.Offset = new Vector(0, 0);
        _actionsEditorScroll.Offset = new Vector(0, 0);
        _commandsEditorScroll.Offset = new Vector(0, 0);
        _abilitiesEditorScroll.Offset = new Vector(0, 0);
        _trainResearchEditorScroll.Offset = new Vector(0, 0);
        Dispatcher.UIThread.Post(() => _editorScroll.Offset = new Vector(0, 0), DispatcherPriority.Loaded);
        Dispatcher.UIThread.Post(() => _actionsEditorScroll.Offset = new Vector(0, 0), DispatcherPriority.Loaded);
        Dispatcher.UIThread.Post(() => _commandsEditorScroll.Offset = new Vector(0, 0), DispatcherPriority.Loaded);
        Dispatcher.UIThread.Post(() => _abilitiesEditorScroll.Offset = new Vector(0, 0), DispatcherPriority.Loaded);
        Dispatcher.UIThread.Post(() => _trainResearchEditorScroll.Offset = new Vector(0, 0), DispatcherPriority.Loaded);
    }

    private void ClearEditorPanels()
    {
        _statsEditorPanel.Children.Clear();
        _actionsEditorPanel.Children.Clear();
        _commandsEditorPanel.Children.Clear();
        _abilitiesEditorPanel.Children.Clear();
        _trainResearchEditorPanel.Children.Clear();
        _suppressUnitNameChange = true;
        _unitNameBox.Text = "";
        _suppressUnitNameChange = false;
        _unitNameBox.IsEnabled = false;
    }

    private void BuildEditorPanel(string unitName, bool resetScroll = true)
    {
        // A newly selected unit should always show the persisted XML first.
        // This avoids projecting a form while its asynchronous fields are still
        // being populated. MarkDirty switches back to the live form projection.
        _showStoredRawXml = true;
        _xmlPreviewRefreshTimer.Stop();
        _isPopulating = true;
        foreach (var editor in _animationValidationOriginalBorders.Keys.ToList())
            ClearProtoActionAnimationValidationError(editor);
        var buildGeneration = ++_editorBuildGeneration;
        _statsEditorPanel.Children.Clear();
        _actionsEditorPanel.Children.Clear();
        _commandsEditorPanel.Children.Clear();
        _abilitiesEditorPanel.Children.Clear();
        _trainResearchEditorPanel.Children.Clear();
        _activeEditorPanel = _statsEditorPanel;
        _activeEditorTabIndex = 0;
        if (resetScroll)
            ResetEditorScrollToTop();
        _sectionJumpTargets.Clear();
        RebuildSectionJumpFlyout();
        ClearProtoUnitStatsValidationState();
        _fieldControls.Clear();
        _otherSpecificAttributeContainers.Clear();
        _otherSpecificAttributesPanel = null;
        _currentStringFieldIds.Clear();
        _costControls.Clear();
        _armorControls.Clear();
        _currentUnitTypes = null;
        _currentFlags = null;
        _currentContains = null;
        _currentNotContains = null;
        _containEjectCommandCheckBox = null;
        _addUnitCommandRow = null;
        _removeUnitCommandRows = null;
        _syncingContainEjectCommand = false;
        _containRemovedDuringEdit = false;
        _statsRechargeModeEditors.Clear();
        _statsRechargeValueEditors.Clear();
        _statsRechargeStartChargedEditors.Clear();
        _statsRechargeRemoveButtons.Clear();
        _abilityRechargeModeEditors.Clear();
        _abilityRechargeValueEditors.Clear();
        _abilityRechargeStartChargedEditors.Clear();
        _syncingSharedRechargeEditors = false;
        _cultureFieldRows.Clear();
        _trainCommandRows.Clear();
        _techCommandRows.Clear();
        _unitCommandRows.Clear();
        _transformCommandAssignments.Clear();
        _validateTransformAssignmentsBeforeUnitSaveAsync = null;
        _saveActiveTransformCommandBeforeUnitSaveAsync = null;
        _optionalCommandRows.Clear();
        _protoActionWidgets.Clear();
        _buildLimitRows.Clear();
        _resourceConversionRows.Clear();
        _dependentUnitRows.Clear();
        _spawnRows.Clear();
        _veterancyRankRows.Clear();
        _veterancyBonusRows.Clear();

        XElement? unit = null;
        if (_modXmlRoot != null)
        {
            unit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, unitName);
        }

        if (unit == null && _barXmlRoot != null)
        {
            unit = ProtoXmlHandler.GetUnitElement(_barXmlRoot, unitName);
            _isReadOnly = true;
        }
        else
        {
            _isReadOnly = _isAbilityDefinitionEditorMode
                ? _abilityDefinitionEditorReadOnly
                : _protoActionHostAdapter.Context.UsesStandaloneDocumentLifecycle && _tacticsEditorSession?.IsReadOnly == true;
        }

        if (unit == null)
        {
            _pageSearchTargets.Clear();
            _pageSearchMatches.Clear();
            ClearPageSearchHighlights();
            RebuildSectionJumpFlyout();
            UpdatePageSearchUiState(hasMatches: false, hasQuery: !string.IsNullOrWhiteSpace(_pageSearchBox.Text), hasValidPattern: true);
            if (resetScroll)
                ResetEditorScrollToTop();
            _isPopulating = false;
            UpdateXmlPreview(force: true);
            return;
        }

        _currentUnitName = unitName;
        // Switch the preview source before controls for the new unit begin
        // populating, so a pending projection from the previous mod unit cannot
        // flash in the right pane.
        UpdateXmlPreview(force: true);
        RefreshCurrentUnitProtoActionMetadata(unit);
        InitializeCurrentUnitAnimationCatalog(unit, buildGeneration);
        var persistedUnitTypes = new HashSet<string>(
            unit.Elements("unittype")
                .Select(x => x.Value?.Trim() ?? "")
                .Where(x => x.Length > 0),
            StringComparer.OrdinalIgnoreCase);
        var storedTrainPoints = ProtoXmlHandler.GetSimpleField(unit, "trainpoints") ?? "";
        var storedBuildPoints = ProtoXmlHandler.GetSimpleField(unit, "buildpoints") ?? "";
        string ResolvePointsTag(IEnumerable<string> unitTypes)
            => ProtoUnitStatsConditionalPolicy.ResolvePointsTag(
                unitTypes,
                !string.IsNullOrWhiteSpace(storedTrainPoints),
                !string.IsNullOrWhiteSpace(storedBuildPoints));

        var initialPointsTag = ResolvePointsTag(persistedUnitTypes);
        TextBlock? pointsRowLabel = null;
        TextBox? pointsEditor = null;

        void UpdatePointsMode(IEnumerable<string> unitTypes)
        {
            if (pointsRowLabel == null || pointsEditor == null)
                return;
            var desiredTag = ResolvePointsTag(unitTypes);
            pointsRowLabel.Text = desiredTag.Equals("buildpoints", StringComparison.OrdinalIgnoreCase)
                ? "Build Points"
                : "Train Points";
            _fieldControls.Remove("trainpoints");
            _fieldControls.Remove("buildpoints");
            _fieldControls[desiredTag] = pointsEditor;
        }

        bool useBuildingLayout =
            persistedUnitTypes.Contains("Building") ||
            !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetSimpleField(unit, "buildpoints"));
        bool CanOfferBuildingOnlyAttributes()
            => ProtoUnitStatsConditionalPolicy.CanOfferBuildingOnlyAttribute(
                _currentUnitTypes ?? persistedUnitTypes);

        _suppressUnitNameChange = true;
        _unitNameBox.Text = unitName;
        _suppressUnitNameChange = false;
        _unitNameBox.IsReadOnly = _isReadOnly;
        _unitNameBox.IsEnabled = !_isReadOnly;
        _fieldControls[ProtoUnitNameFieldKey] = _unitNameBox;

        AddSectionHeader("Properties");

        var propertiesGrid = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("150, *"),
        };
        var iconPreview = new IconPreviewControl(_iconPreviewService)
        {
            Margin = new Thickness(IconPreviewControl.PropertyGridLeftOffset, 4, 8, 4),
            HorizontalAlignment = HorizontalAlignment.Left,
            VerticalAlignment = VerticalAlignment.Top
        };
        int gridRow = 0;

        foreach (var field in ProtoConstants.SimpleFields)
        {
            if (field.Tag.Equals("buildlimit", StringComparison.OrdinalIgnoreCase) ||
                field.Tag.Equals("tactics", StringComparison.OrdinalIgnoreCase) ||
                field.Tag.Equals("maxcontained", StringComparison.OrdinalIgnoreCase))
                continue;

            if ((field.Tag.Equals("trainpoints", StringComparison.OrdinalIgnoreCase) ||
                 field.Tag.Equals("buildpoints", StringComparison.OrdinalIgnoreCase)) &&
                !field.Tag.Equals(initialPointsTag, StringComparison.OrdinalIgnoreCase))
                continue;

            if (field.Tag.Equals("turnrate", StringComparison.OrdinalIgnoreCase))
                continue;

            if (field.Tag.Equals("weightclass", StringComparison.OrdinalIgnoreCase) && useBuildingLayout)
                continue;

            if (field.Tag.Equals("obstructionradiusz", StringComparison.OrdinalIgnoreCase) ||
                field.Tag.Equals("maxvelocity", StringComparison.OrdinalIgnoreCase) ||
                field.Tag.Equals("maxrunvelocity", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            if (field.Tag.Equals("maxhitpoints", StringComparison.OrdinalIgnoreCase))
                continue;

            if (field.Tag.Equals("displaynameid", StringComparison.OrdinalIgnoreCase))
            {
                var displayNameId = ProtoXmlHandler.GetSimpleField(unit, "displaynameid") ?? "";
                var editorNameId = ProtoXmlHandler.GetSimpleField(unit, "editornameid") ?? "";
                _currentStringFieldIds["displaynameid"] = displayNameId;

                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var displayLabel = new TextBlock
                {
                    Text = "Display Name",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4)
                };
                Grid.SetRow(displayLabel, gridRow);
                propertiesGrid.Children.Add(displayLabel);

                var displayRow = new WrapPanel { Orientation = Orientation.Horizontal };
                var displayNameTb = EditorTextFieldStyle.ConfigureTextBox(new TextBox
                {
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 8, 4)
                });
                displayNameTb.TextChanged += async (_, _) =>
                {
                    if (!_isPopulating && await CheckStartLocalMod()) MarkDirty();
                };
                displayRow.Children.Add(displayNameTb);
                _fieldControls["displaynameid"] = displayNameTb;

                Grid.SetColumn(displayRow, 1);
                Grid.SetRow(displayRow, gridRow);
                propertiesGrid.Children.Add(displayRow);
                gridRow++;

                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var editorLabel = new TextBlock
                {
                    Text = "Editor Name",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4),
                    IsVisible = !_isReadOnly || !string.IsNullOrWhiteSpace(editorNameId)
                };
                Grid.SetRow(editorLabel, gridRow);
                propertiesGrid.Children.Add(editorLabel);

                var editorRow = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    IsVisible = !_isReadOnly || !string.IsNullOrWhiteSpace(editorNameId)
                };
                var editorNameTb = EditorTextFieldStyle.ConfigureTextBox(new TextBox
                {
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 0, 4)
                });
                editorRow.Children.Add(editorNameTb);
                Grid.SetColumn(editorRow, 1);
                Grid.SetRow(editorRow, gridRow);
                propertiesGrid.Children.Add(editorRow);

                if (!_isReadOnly || !string.IsNullOrWhiteSpace(editorNameId))
                {
                    _currentStringFieldIds["editornameid"] = string.IsNullOrWhiteSpace(editorNameId)
                        ? displayNameId
                        : editorNameId;
                    _fieldControls["editornameid"] = editorNameTb;
                }

                editorNameTb.TextChanged += async (_, _) =>
                {
                    if (_isPopulating || !_fieldControls.ContainsKey("editornameid")) return;
                    _currentStringFieldIds["editornameid"] = string.Equals(editorNameTb.Text, displayNameTb.Text, StringComparison.Ordinal)
                        ? _currentStringFieldIds.GetValueOrDefault("displaynameid", "")
                        : BuildStringIdForUnit(_currentUnitName ?? unitName, GetStringSuffixForField("editornameid"));
                    if (await CheckStartLocalMod()) MarkDirty();
                };

                gridRow++;
                continue;
            }

            if (field.Tag.Equals("editornameid", StringComparison.OrdinalIgnoreCase))
                continue;

            if (field.Tag.Equals("obstructionradiusx", StringComparison.OrdinalIgnoreCase))
            {
                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var obstructionLabel = new TextBlock
                {
                    Text = "Obstruction Radius",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                };
                Grid.SetColumn(obstructionLabel, 0);
                Grid.SetRow(obstructionLabel, gridRow);
                propertiesGrid.Children.Add(obstructionLabel);

                var obstructionGrid = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("Auto, 105, Auto, 105, Auto, 105")
                };

                var obstructionXLabel = new TextBlock
                {
                    Text = "X",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4)
                };
                Grid.SetColumn(obstructionXLabel, 0);
                obstructionGrid.Children.Add(obstructionXLabel);

                var obstructionXTb = new TextBox
                {
                    Text = ProtoXmlHandler.GetSimpleField(unit, "obstructionradiusx") ?? "",
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 8, 4)
                };
                AttachDecimalBehavior(obstructionXTb);
                obstructionXTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(obstructionXTb, 1);
                obstructionGrid.Children.Add(obstructionXTb);

                var obstructionZLabel = new TextBlock
                {
                    Text = "Z",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4)
                };
                Grid.SetColumn(obstructionZLabel, 2);
                obstructionGrid.Children.Add(obstructionZLabel);

                var obstructionZTb = new TextBox
                {
                    Text = ProtoXmlHandler.GetSimpleField(unit, "obstructionradiusz") ?? "",
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 0, 4)
                };
                AttachDecimalBehavior(obstructionZTb);
                obstructionZTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(obstructionZTb, 3);
                obstructionGrid.Children.Add(obstructionZTb);

                var turnRateLabel = new TextBlock
                {
                    Text = "Turn Rate",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(8, 4, 6, 4)
                };
                Grid.SetColumn(turnRateLabel, 4);
                obstructionGrid.Children.Add(turnRateLabel);

                var turnRateTb = new TextBox
                {
                    Text = ProtoXmlHandler.GetSimpleField(unit, "turnrate") ?? "",
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 0, 4)
                };
                AttachDecimalBehavior(turnRateTb);
                turnRateTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(turnRateTb, 5);
                obstructionGrid.Children.Add(turnRateTb);

                Grid.SetColumn(obstructionGrid, 1);
                Grid.SetRow(obstructionGrid, gridRow);
                propertiesGrid.Children.Add(obstructionGrid);

                _fieldControls["obstructionradiusx"] = obstructionXTb;
                _fieldControls["obstructionradiusz"] = obstructionZTb;
                _fieldControls["turnrate"] = turnRateTb;
                gridRow++;
                continue;
            }

            if (field.Tag.Equals("initialhitpoints", StringComparison.OrdinalIgnoreCase))
            {
                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var hitPointsRowLabel = new TextBlock
                {
                    Text = "Hitpoints",
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 10, 10, 4)
                };
                Grid.SetColumn(hitPointsRowLabel, 0);
                Grid.SetRow(hitPointsRowLabel, gridRow);
                propertiesGrid.Children.Add(hitPointsRowLabel);

                string maxHitPointsInitial = ProtoXmlHandler.GetSimpleField(unit, "maxhitpoints") ?? "";
                string initialHitPointsStored = ProtoXmlHandler.GetSimpleField(unit, "initialhitpoints") ?? "";
                string initialHitPointsInitial = !string.IsNullOrWhiteSpace(initialHitPointsStored)
                    ? initialHitPointsStored
                    : maxHitPointsInitial;

                bool initialHitPointsLinkedToMax =
                    string.IsNullOrWhiteSpace(initialHitPointsStored) ||
                    string.Equals(initialHitPointsStored, maxHitPointsInitial, StringComparison.OrdinalIgnoreCase);

                var unitRegenElement = unit.Element("unitregen");
                string unitRegenInitial = unitRegenElement?.Value?.Trim() ?? "";
                string unitRegenIdleTimeoutInitial = unitRegenElement?.Attribute("idletimeout")?.Value?.Trim()
                    ?? unitRegenElement?.Attribute("idleTimeout")?.Value?.Trim()
                    ?? "";
                string unitRegenDamageTimeoutInitial = unitRegenElement?.Attribute("damagetimeout")?.Value?.Trim()
                    ?? unitRegenElement?.Attribute("damageTimeout")?.Value?.Trim()
                    ?? "";
                string unitRegenCombatMultiplierInitial = unitRegenElement?.Attribute("combatmultiplier")?.Value?.Trim()
                    ?? unitRegenElement?.Attribute("combatMultiplier")?.Value?.Trim()
                    ?? "";
                string unitRegenRateLimitInitial = unitRegenElement?.Attribute("ratelimit")?.Value?.Trim()
                    ?? unitRegenElement?.Attribute("rateLimit")?.Value?.Trim()
                    ?? unitRegenElement?.Attribute("ratelimit")?.Value?.Trim()
                    ?? "";

                var hitPointsGrid = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    ItemHeight = double.NaN
                };
                var unitRegenControls = new List<Control>();

                Grid CreateInlineField(string label, double width, string value, out TextBox textBox, bool signedNumeric = false)
                {
                    var grid = new Grid
                    {
                        ColumnDefinitions = new ColumnDefinitions($"Auto, {width}"),
                        Margin = new Thickness(0, 0, 4, 0)
                    };

                    var textLabel = new TextBlock
                    {
                        Text = label,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 10, 4)
                    };
                    Grid.SetColumn(textLabel, 0);
                    grid.Children.Add(textLabel);

                    textBox = new TextBox
                    {
                        Text = value,
                        IsEnabled = !_isReadOnly,
                        Width = width,
                        Margin = new Thickness(0, 4, 0, 4)
                    };
                    if (signedNumeric)
                        AttachSignedDecimalBehavior(textBox);
                    else
                        AttachDecimalBehavior(textBox);

                    Grid.SetColumn(textBox, 1);
                    grid.Children.Add(textBox);
                    return grid;
                }

                void AddProgressiveRegenEditors(
                    WrapPanel host,
                    string regenKey,
                    string regenLabel,
                    string regenValue,
                    IReadOnlyList<(string Key, string Label, string Value, string DefaultValue)> modifiers,
                    List<Control> directControls,
                    Action onRemoved)
                {
                    if (_fieldControls.ContainsKey(regenKey))
                        return;

                    var regenGrid = CreateInlineField(regenLabel, 90, string.IsNullOrWhiteSpace(regenValue) ? "0" : regenValue, out var regenTb, true);
                    host.Children.Add(regenGrid);
                    directControls.Add(regenGrid);
                    _fieldControls[regenKey] = regenTb;
                    regenTb.TextChanged += async (_, _) =>
                    {
                        if (!_isPopulating && await CheckStartLocalMod())
                            MarkDirty();
                    };

                    var modifiersHost = new WrapPanel { Orientation = Orientation.Horizontal };
                    host.Children.Add(modifiersHost);
                    directControls.Add(modifiersHost);

                    void ShowModifierAddButton((string Key, string Label, string Value, string DefaultValue) modifier)
                    {
                        if (_isReadOnly)
                            return;

                        var addButton = new Button
                        {
                            Content = modifier.Label,
                            Classes = { "add-component" },
                            Margin = new Thickness(0, 4, 8, 4)
                        };
                        addButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            modifiersHost.Children.Remove(addButton);
                            ShowModifierField(modifier, modifier.DefaultValue, insertAtStart: true);
                            MarkDirty();
                        };
                        modifiersHost.Children.Add(addButton);
                    }

                    void ShowModifierField((string Key, string Label, string Value, string DefaultValue) modifier, string value, bool insertAtStart = false)
                    {
                        var fieldGrid = CreateInlineField(modifier.Label, 90, value, out var fieldTb, true);
                        fieldGrid.Margin = new Thickness(0);
                        if (insertAtStart)
                            modifiersHost.Children.Insert(0, fieldGrid);
                        else
                            modifiersHost.Children.Add(fieldGrid);
                        _fieldControls[modifier.Key] = fieldTb;
                        fieldTb.TextChanged += async (_, _) =>
                        {
                            if (!_isPopulating && await CheckStartLocalMod())
                                MarkDirty();
                        };

                        if (_isReadOnly)
                            return;

                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 4, 8, 4)
                        };
                        removeButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            _fieldControls.Remove(modifier.Key);
                            modifiersHost.Children.Remove(fieldGrid);
                            modifiersHost.Children.Remove(removeButton);
                            ShowModifierAddButton((modifier.Key, modifier.Label, "", modifier.DefaultValue));
                            MarkDirty();
                        };
                        if (insertAtStart)
                            modifiersHost.Children.Insert(1, removeButton);
                        else
                            modifiersHost.Children.Add(removeButton);
                    }

                    void ShowModifierChoices()
                    {
                        modifiersHost.Children.Clear();
                        foreach (var modifier in modifiers)
                        {
                            if (!string.IsNullOrWhiteSpace(modifier.Value))
                                ShowModifierField(modifier, modifier.Value);
                            else
                                ShowModifierAddButton(modifier);
                        }
                    }

                    if (modifiers.Any(modifier => !string.IsNullOrWhiteSpace(modifier.Value)))
                    {
                        ShowModifierChoices();
                    }
                    else if (!_isReadOnly)
                    {
                        var addModifiersButton = new Button
                        {
                            Content = "Add Modifiers",
                            Classes = { "add-component" },
                            Margin = new Thickness(0, 4, 8, 4)
                        };
                        addModifiersButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            ShowModifierChoices();
                        };
                        modifiersHost.Children.Add(addModifiersButton);
                    }

                    if (!_isReadOnly)
                    {
                        var removeRegenButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 4, 0, 4)
                        };
                        removeRegenButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod())
                                return;
                            _fieldControls.Remove(regenKey);
                            foreach (var modifier in modifiers)
                                _fieldControls.Remove(modifier.Key);
                            foreach (var control in directControls.ToList())
                                host.Children.Remove(control);
                            host.Children.Remove(removeRegenButton);
                            directControls.Clear();
                            onRemoved();
                            MarkDirty();
                        };
                        host.Children.Add(removeRegenButton);
                        directControls.Add(removeRegenButton);
                    }
                }

                var maxHitPointsGrid = CreateInlineField("Max", 120, maxHitPointsInitial, out var maxHitPointsTb);
                hitPointsGrid.Children.Add(maxHitPointsGrid);

                var initialHitPointsGrid = CreateInlineField("Initial", 120, initialHitPointsInitial, out var initialHitPointsTb);
                hitPointsGrid.Children.Add(initialHitPointsGrid);

                Button? addRegenButton = null;

                Button CreateAddRegenButton()
                {
                    var button = new Button
                    {
                        Content = "Add Regen",
                        Classes = { "add-component" },
                        Margin = new Thickness(0, 4, 0, 4)
                    };
                    button.Click += async (s, e) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        button.IsVisible = false;
                        AddUnitRegenEditors();
                        MarkDirty();
                    };
                    return button;
                }

                void AddUnitRegenEditors()
                {
                    if (_fieldControls.ContainsKey("unitregen"))
                        return;

                    if (string.IsNullOrWhiteSpace(unitRegenInitial))
                        unitRegenInitial = "0";
                    AddProgressiveRegenEditors(
                        hitPointsGrid,
                        "unitregen",
                        "Regen",
                        unitRegenInitial,
                        [
                            ("unitregen.idleTimeout", "Idle Timeout", unitRegenIdleTimeoutInitial, "0"),
                            ("unitregen.damageTimeout", "Damage Timeout", unitRegenDamageTimeoutInitial, "0"),
                            ("unitregen.combatMultiplier", "Combat Multiplier", unitRegenCombatMultiplierInitial, "1"),
                            ("unitregen.ratelimit", "Rate Limit", unitRegenRateLimitInitial, "1")
                        ],
                        unitRegenControls,
                        () =>
                        {
                            unitRegenInitial = "";
                            unitRegenIdleTimeoutInitial = "";
                            unitRegenDamageTimeoutInitial = "";
                            unitRegenCombatMultiplierInitial = "";
                            unitRegenRateLimitInitial = "";
                            if (addRegenButton == null)
                            {
                                addRegenButton = CreateAddRegenButton();
                                hitPointsGrid.Children.Add(addRegenButton);
                            }
                            else
                            {
                                addRegenButton.IsVisible = true;
                            }
                        });
                }

                if (!string.IsNullOrWhiteSpace(unitRegenInitial) || unitRegenElement != null)
                {
                    AddUnitRegenEditors();
                }
                else if (!_isReadOnly)
                {
                    addRegenButton = CreateAddRegenButton();
                    hitPointsGrid.Children.Add(addRegenButton);
                }

                maxHitPointsTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        if (initialHitPointsLinkedToMax)
                        {
                            initialHitPointsTb.Text = maxHitPointsTb.Text;
                        }

                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };

                initialHitPointsTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                initialHitPointsTb.GotFocus += (s, e) =>
                {
                    if (!_isPopulating)
                        initialHitPointsLinkedToMax = false;
                };

                Grid.SetColumn(hitPointsGrid, 1);
                Grid.SetRow(hitPointsGrid, gridRow);
                propertiesGrid.Children.Add(hitPointsGrid);

                _fieldControls["maxhitpoints"] = maxHitPointsTb;
                _fieldControls["initialhitpoints"] = initialHitPointsTb;
                gridRow++;

                string maxShieldInitial = ProtoXmlHandler.GetSimpleField(unit, "maxshieldpoints") ?? "";
                string initialShieldStored = ProtoXmlHandler.GetSimpleField(unit, "initialshieldpoints") ?? "";
                string initialShieldInitial = !string.IsNullOrWhiteSpace(initialShieldStored)
                    ? initialShieldStored
                    : maxShieldInitial;
                var shieldRegenElement = unit.Element("unitshieldregen");
                string shieldRegenInitial = shieldRegenElement?.Value?.Trim() ?? "";
                string shieldRegenIdleTimeoutInitial = shieldRegenElement?.Attribute("idletimeout")?.Value?.Trim()
                    ?? shieldRegenElement?.Attribute("idleTimeout")?.Value?.Trim()
                    ?? "";
                string shieldRegenDamageTimeoutInitial = shieldRegenElement?.Attribute("damagetimeout")?.Value?.Trim()
                    ?? shieldRegenElement?.Attribute("damageTimeout")?.Value?.Trim()
                    ?? "";
                string shieldRegenCombatMultiplierInitial = shieldRegenElement?.Attribute("combatmultiplier")?.Value?.Trim()
                    ?? shieldRegenElement?.Attribute("combatMultiplier")?.Value?.Trim()
                    ?? "";
                string shieldRegenRateLimitInitial = shieldRegenElement?.Attribute("ratelimit")?.Value?.Trim()
                    ?? shieldRegenElement?.Attribute("rateLimit")?.Value?.Trim()
                    ?? "";

                bool initialShieldLinkedToMax =
                    string.IsNullOrWhiteSpace(initialShieldStored) ||
                    string.Equals(initialShieldStored, maxShieldInitial, StringComparison.OrdinalIgnoreCase);

                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var shieldRowLabel = new TextBlock
                {
                    Text = "Shield",
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 10, 10, 4),
                    IsVisible = !string.IsNullOrWhiteSpace(maxShieldInitial) || !string.IsNullOrWhiteSpace(initialShieldStored) || !string.IsNullOrWhiteSpace(shieldRegenInitial) || shieldRegenElement != null
                };
                Grid.SetColumn(shieldRowLabel, 0);
                Grid.SetRow(shieldRowLabel, gridRow);
                propertiesGrid.Children.Add(shieldRowLabel);

                var shieldGrid = new WrapPanel
                {
                    Orientation = Orientation.Horizontal,
                    ItemHeight = double.NaN
                };
                var shieldControls = new List<Control>();
                var shieldRegenControls = new List<Control>();
                Button? addShieldButton = null;
                Button? addShieldRegenButton = null;

                Button CreateAddShieldButton()
                {
                    var button = new Button
                    {
                        Content = "Add Shield",
                        Classes = { "add-component" },
                        Margin = new Thickness(0, 4, 0, 4)
                    };
                    button.Click += async (s, e) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (!proceed)
                            return;

                        shieldRowLabel.IsVisible = true;
                        button.IsVisible = false;
                        AddShieldEditors();
                        MarkDirty();
                    };
                    return button;
                }

                void AddShieldEditors()
                {
                    if (_fieldControls.ContainsKey("maxshieldpoints"))
                        return;

                    if (string.IsNullOrWhiteSpace(maxShieldInitial))
                        maxShieldInitial = "0";
                    if (string.IsNullOrWhiteSpace(initialShieldInitial))
                        initialShieldInitial = maxShieldInitial;

                    var maxShieldGrid = CreateInlineField("Max", 120, maxShieldInitial, out var maxShieldTb);
                    shieldGrid.Children.Add(maxShieldGrid);
                    shieldControls.Add(maxShieldGrid);
                    _fieldControls["maxshieldpoints"] = maxShieldTb;

                    var initialShieldGrid = CreateInlineField("Initial", 120, initialShieldInitial, out var initialShieldTb);
                    shieldGrid.Children.Add(initialShieldGrid);
                    shieldControls.Add(initialShieldGrid);
                    _fieldControls["initialshieldpoints"] = initialShieldTb;

                    void AddShieldRegenEditors()
                    {
                        if (_fieldControls.ContainsKey("unitshieldregen"))
                            return;
                        if (string.IsNullOrWhiteSpace(shieldRegenInitial))
                            shieldRegenInitial = "0";
                        addShieldRegenButton?.IsVisible = false;
                        AddProgressiveRegenEditors(
                            shieldGrid,
                            "unitshieldregen",
                            "Regen",
                            shieldRegenInitial,
                            [
                                ("unitshieldregen.idletimeout", "Idle Timeout", shieldRegenIdleTimeoutInitial, "0"),
                                ("unitshieldregen.damagetimeout", "Damage Timeout", shieldRegenDamageTimeoutInitial, "0"),
                                ("unitshieldregen.combatmultiplier", "Combat Multiplier", shieldRegenCombatMultiplierInitial, "1"),
                                ("unitshieldregen.ratelimit", "Rate Limit", shieldRegenRateLimitInitial, "1")
                            ],
                            shieldRegenControls,
                            () =>
                            {
                                shieldRegenInitial = "";
                                shieldRegenIdleTimeoutInitial = "";
                                shieldRegenDamageTimeoutInitial = "";
                                shieldRegenCombatMultiplierInitial = "";
                                shieldRegenRateLimitInitial = "";
                                if (addShieldRegenButton == null)
                                {
                                    addShieldRegenButton = new Button
                                    {
                                        Content = "Add Regen",
                                        Classes = { "add-component" },
                                        Margin = new Thickness(0, 4, 8, 4)
                                    };
                                    addShieldRegenButton.Click += async (_, _) =>
                                    {
                                        if (await CheckStartLocalMod())
                                        {
                                            AddShieldRegenEditors();
                                            MarkDirty();
                                        }
                                    };
                                    shieldGrid.Children.Add(addShieldRegenButton);
                                }
                                else
                                {
                                    addShieldRegenButton.IsVisible = true;
                                }
                            });
                    }

                    var hasShieldRegen = shieldRegenElement != null ||
                                         !string.IsNullOrWhiteSpace(shieldRegenInitial) ||
                                         !string.IsNullOrWhiteSpace(shieldRegenIdleTimeoutInitial) ||
                                         !string.IsNullOrWhiteSpace(shieldRegenDamageTimeoutInitial) ||
                                         !string.IsNullOrWhiteSpace(shieldRegenCombatMultiplierInitial) ||
                                         !string.IsNullOrWhiteSpace(shieldRegenRateLimitInitial);
                    if (hasShieldRegen)
                    {
                        AddShieldRegenEditors();
                    }
                    else if (!_isReadOnly)
                    {
                        addShieldRegenButton = new Button
                        {
                            Content = "Add Regen",
                            Classes = { "add-component" },
                            Margin = new Thickness(0, 4, 8, 4)
                        };
                        addShieldRegenButton.Click += async (_, _) =>
                        {
                            if (await CheckStartLocalMod())
                            {
                                AddShieldRegenEditors();
                                MarkDirty();
                            }
                        };
                        shieldGrid.Children.Add(addShieldRegenButton);
                    }

                    maxShieldTb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            if (initialShieldLinkedToMax)
                                initialShieldTb.Text = maxShieldTb.Text;

                            var proceed = await CheckStartLocalMod();
                            if (proceed) MarkDirty();
                        }
                    };

                    initialShieldTb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed) MarkDirty();
                        }
                    };
                    initialShieldTb.GotFocus += (s, e) =>
                    {
                        if (!_isPopulating)
                            initialShieldLinkedToMax = false;
                    };

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button
                        {
                            Classes = { "remove-button" },
                            Margin = new Thickness(2, 4, 0, 4)
                        };
                        removeButton.Click += async (s, e) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (!proceed)
                                return;

                            foreach (var key in new[] { "maxshieldpoints", "initialshieldpoints", "unitshieldregen", "unitshieldregen.idletimeout", "unitshieldregen.damagetimeout", "unitshieldregen.combatmultiplier", "unitshieldregen.ratelimit" })
                                _fieldControls.Remove(key);
                            foreach (var control in shieldControls.ToList())
                                shieldGrid.Children.Remove(control);
                            foreach (var control in shieldRegenControls.ToList())
                                shieldGrid.Children.Remove(control);
                            if (addShieldRegenButton != null)
                                shieldGrid.Children.Remove(addShieldRegenButton);
                            shieldGrid.Children.Remove(removeButton);
                            shieldControls.Clear();
                            shieldRegenControls.Clear();
                            maxShieldInitial = "";
                            initialShieldInitial = "";
                            shieldRegenInitial = "";
                            shieldRegenIdleTimeoutInitial = "";
                            shieldRegenDamageTimeoutInitial = "";
                            shieldRegenCombatMultiplierInitial = "";
                            shieldRegenRateLimitInitial = "";
                            shieldRowLabel.IsVisible = false;
                            if (addShieldButton == null)
                            {
                                addShieldButton = CreateAddShieldButton();
                                shieldGrid.Children.Add(addShieldButton);
                            }
                            else
                            {
                                addShieldButton.IsVisible = true;
                            }
                            MarkDirty();
                        };
                        shieldGrid.Children.Add(removeButton);
                        shieldControls.Add(removeButton);
                    }
                }

                if (!string.IsNullOrWhiteSpace(maxShieldInitial) || !string.IsNullOrWhiteSpace(initialShieldStored) || !string.IsNullOrWhiteSpace(shieldRegenInitial) || shieldRegenElement != null)
                {
                    AddShieldEditors();
                }
                else if (!_isReadOnly)
                {
                    addShieldButton = CreateAddShieldButton();
                    shieldGrid.Children.Add(addShieldButton);
                }

                Grid.SetColumn(shieldGrid, 1);
                Grid.SetRow(shieldGrid, gridRow);
                propertiesGrid.Children.Add(shieldGrid);
                gridRow++;
                continue;
            }

            if (field.Tag.Equals(initialPointsTag, StringComparison.OrdinalIgnoreCase))
            {
                var pointsTag = initialPointsTag;
                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var rowLabel = new TextBlock
                {
                    Text = pointsTag.Equals("buildpoints", StringComparison.OrdinalIgnoreCase) ? "Build Points" : "Train Points",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4)
                };
                Grid.SetRow(rowLabel, gridRow);
                propertiesGrid.Children.Add(rowLabel);

                var row = new Grid { ColumnDefinitions = new ColumnDefinitions("120,Auto,120") };
                var pointsTb = new TextBox
                {
                    Text = !string.IsNullOrWhiteSpace(ProtoXmlHandler.GetSimpleField(unit, pointsTag))
                        ? ProtoXmlHandler.GetSimpleField(unit, pointsTag)
                        : pointsTag.Equals("buildpoints", StringComparison.OrdinalIgnoreCase)
                            ? storedTrainPoints
                            : storedBuildPoints,
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 12, 4)
                };
                AttachDecimalBehavior(pointsTb);
                pointsTb.TextChanged += async (_, _) =>
                {
                    if (!_isPopulating && await CheckStartLocalMod()) MarkDirty();
                };
                row.Children.Add(pointsTb);

                var populationLabel = new TextBlock
                {
                    Text = "Population Count",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4)
                };
                Grid.SetColumn(populationLabel, 1);
                row.Children.Add(populationLabel);
                var populationTb = new TextBox
                {
                    Text = ProtoXmlHandler.GetSimpleField(unit, "populationcount") ?? "",
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 0, 4)
                };
                EditorNumericFieldStyle.ConfigureNumericTextBox(populationTb);
                populationTb.AddHandler(InputElement.TextInputEvent, (_, args) =>
                {
                    if (string.IsNullOrWhiteSpace(args.Text) || !args.Text.All(char.IsDigit)) args.Handled = true;
                }, RoutingStrategies.Tunnel);
                populationTb.TextChanged += async (_, _) =>
                {
                    if (_isPopulating) return;
                    var digits = new string((populationTb.Text ?? "").Where(char.IsDigit).ToArray());
                    if (!string.Equals(populationTb.Text, digits, StringComparison.Ordinal)) populationTb.Text = digits;
                    if (await CheckStartLocalMod()) MarkDirty();
                };
                Grid.SetColumn(populationTb, 2);
                row.Children.Add(populationTb);

                Grid.SetColumn(row, 1);
                Grid.SetRow(row, gridRow);
                propertiesGrid.Children.Add(row);
                _fieldControls[pointsTag] = pointsTb;
                pointsRowLabel = rowLabel;
                pointsEditor = pointsTb;
                _fieldControls["populationcount"] = populationTb;
                gridRow++;
                continue;
            }

            if (field.Tag.Equals("populationcount", StringComparison.OrdinalIgnoreCase))
                continue;

            if (field.Tag.Equals("weightclass", StringComparison.OrdinalIgnoreCase) ||
                field.Tag.Equals("unitaitype", StringComparison.OrdinalIgnoreCase))
                continue;

            if (field.Tag.Equals("impacttype", StringComparison.OrdinalIgnoreCase))
            {
                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
                var rowLabel = new TextBlock
                {
                    Text = "Unit AI Type",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4)
                };
                Grid.SetRow(rowLabel, gridRow);
                propertiesGrid.Children.Add(rowLabel);

                var behaviorRow = new Grid
                {
                    ColumnDefinitions = useBuildingLayout
                        ? new ColumnDefinitions("140,Auto,140")
                        : new ColumnDefinitions("140,Auto,140,Auto,105")
                };

                ComboBox CreateBehaviorCombo(string tag)
                {
                    var options = ProtoConstants.FieldSuggestions.TryGetValue(tag, out var values) ? values : [];
                    var initial = ProtoXmlHandler.GetSimpleField(unit, tag)?.Trim() ?? "";
                    var displayOptions = options
                        .Concat(string.IsNullOrWhiteSpace(initial) ? [] : [initial])
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    var combo = new ComboBox
                    {
                        ItemsSource = displayOptions,
                        SelectedItem = options.FirstOrDefault(value => value.Equals(initial, StringComparison.OrdinalIgnoreCase))
                                       ?? (string.IsNullOrWhiteSpace(initial) ? null : initial),
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(0, 4, 12, 4)
                    };
                    combo.SelectionChanged += async (_, _) =>
                    {
                        if (!_isPopulating && await CheckStartLocalMod()) MarkDirty();
                    };
                    return combo;
                }

                var unitAiCb = CreateBehaviorCombo("unitaitype");
                behaviorRow.Children.Add(unitAiCb);
                var impactLabel = new TextBlock { Text = "Impact Type", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 6, 4) };
                Grid.SetColumn(impactLabel, 1);
                behaviorRow.Children.Add(impactLabel);
                var impactCb = CreateBehaviorCombo("impacttype");
                Grid.SetColumn(impactCb, 2);
                behaviorRow.Children.Add(impactCb);

                _fieldControls["unitaitype"] = unitAiCb;
                _fieldControls["impacttype"] = impactCb;
                if (!useBuildingLayout)
                {
                    var weightLabel = new TextBlock { Text = "Weight Class", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 6, 4) };
                    Grid.SetColumn(weightLabel, 3);
                    behaviorRow.Children.Add(weightLabel);
                    var weightTb = new TextBox
                    {
                        Text = ProtoXmlHandler.GetSimpleField(unit, "weightclass") ?? "",
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(0, 4, 0, 4)
                    };
                    EditorNumericFieldStyle.ConfigureNumericTextBox(weightTb);
                    weightTb.AddHandler(InputElement.TextInputEvent, (_, args) =>
                    {
                        if (string.IsNullOrWhiteSpace(args.Text) || !args.Text.All(char.IsDigit)) args.Handled = true;
                    }, RoutingStrategies.Tunnel);
                    weightTb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating) return;
                        var digits = new string((weightTb.Text ?? "").Where(char.IsDigit).ToArray());
                        if (!string.Equals(weightTb.Text, digits, StringComparison.Ordinal)) weightTb.Text = digits;
                        if (await CheckStartLocalMod()) MarkDirty();
                    };
                    Grid.SetColumn(weightTb, 4);
                    behaviorRow.Children.Add(weightTb);
                    _fieldControls["weightclass"] = weightTb;
                }

                Grid.SetColumn(behaviorRow, 1);
                Grid.SetRow(behaviorRow, gridRow);
                propertiesGrid.Children.Add(behaviorRow);
                gridRow++;
                continue;
            }

            if (field.Tag.Equals("movementtype", StringComparison.OrdinalIgnoreCase))
            {
                if (useBuildingLayout)
                    continue;

                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var movementLabel = new TextBlock
                {
                    Text = "Movement",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                };
                Grid.SetColumn(movementLabel, 0);
                Grid.SetRow(movementLabel, gridRow);
                propertiesGrid.Children.Add(movementLabel);

                var movementGrid = new Grid
                {
                    ColumnDefinitions = new ColumnDefinitions("140, Auto, 120, Auto, Auto, Auto")
                };

                var movementOptions = ProtoConstants.FieldSuggestions.TryGetValue("movementtype", out var movementList)
                    ? movementList
                    : [];
                string maxVelocityInitial = ProtoXmlHandler.GetSimpleField(unit, "maxvelocity") ?? "";
                string maxRunVelocityStored = ProtoXmlHandler.GetSimpleField(unit, "maxrunvelocity") ?? "";
                var hasMaxRunVelocity = !string.IsNullOrWhiteSpace(maxRunVelocityStored);

                var movementTypeCb = new ComboBox
                {
                    ItemsSource = movementOptions
                        .Concat(string.IsNullOrWhiteSpace(ProtoXmlHandler.GetSimpleField(unit, "movementtype"))
                            ? []
                            : [ProtoXmlHandler.GetSimpleField(unit, "movementtype")!.Trim()])
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList(),
                    SelectedItem = movementOptions.FirstOrDefault(x => x.Equals(ProtoXmlHandler.GetSimpleField(unit, "movementtype") ?? "", StringComparison.OrdinalIgnoreCase))
                                   ?? ProtoXmlHandler.GetSimpleField(unit, "movementtype"),
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 16, 4)
                };
                movementTypeCb.SelectionChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(movementTypeCb, 0);
                movementGrid.Children.Add(movementTypeCb);

                var maxVelocityLabel = new TextBlock
                {
                    Text = "Max Velocity",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 10, 4)
                };
                Grid.SetColumn(maxVelocityLabel, 1);
                movementGrid.Children.Add(maxVelocityLabel);

                var maxVelocityTb = new TextBox
                {
                    Text = maxVelocityInitial,
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 16, 4)
                };
                AttachDecimalBehavior(maxVelocityTb);
                maxVelocityTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(maxVelocityTb, 2);
                movementGrid.Children.Add(maxVelocityTb);

                var maxRunVelocityLabel = new TextBlock
                {
                    Text = "Max Run Velocity",
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 4, 6, 4),
                    IsVisible = hasMaxRunVelocity
                };
                Grid.SetColumn(maxRunVelocityLabel, 3);
                movementGrid.Children.Add(maxRunVelocityLabel);

                var maxRunVelocityTb = new TextBox
                {
                    Text = maxRunVelocityStored,
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 0, 4),
                    IsVisible = hasMaxRunVelocity
                };
                AttachDecimalBehavior(maxRunVelocityTb);
                maxRunVelocityTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(maxRunVelocityTb, 4);
                movementGrid.Children.Add(maxRunVelocityTb);

                var removeMaxRunVelocityButton = new Button
                {
                    Classes = { "remove-button" },
                    Margin = new Thickness(2, 4, 0, 4),
                    IsVisible = !_isReadOnly && hasMaxRunVelocity
                };
                Grid.SetColumn(removeMaxRunVelocityButton, 5);
                movementGrid.Children.Add(removeMaxRunVelocityButton);

                var addMaxRunVelocityButton = new Button
                {
                    Content = "Add Max Run Velocity",
                    Classes = { "add-component" },
                    Margin = new Thickness(0, 4, 0, 4),
                    IsVisible = !_isReadOnly && !hasMaxRunVelocity
                };
                Grid.SetColumn(addMaxRunVelocityButton, 3);
                Grid.SetColumnSpan(addMaxRunVelocityButton, 2);
                movementGrid.Children.Add(addMaxRunVelocityButton);

                addMaxRunVelocityButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod()) return;
                    maxRunVelocityTb.Text = maxVelocityTb.Text;
                    maxRunVelocityLabel.IsVisible = true;
                    maxRunVelocityTb.IsVisible = true;
                    removeMaxRunVelocityButton.IsVisible = true;
                    addMaxRunVelocityButton.IsVisible = false;
                    _fieldControls["maxrunvelocity"] = maxRunVelocityTb;
                    MarkDirty();
                };
                removeMaxRunVelocityButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod()) return;
                    _fieldControls.Remove("maxrunvelocity");
                    maxRunVelocityTb.Text = "";
                    ProtoXmlHandler.RemoveSimpleField(unit, "maxrunvelocity");
                    maxRunVelocityLabel.IsVisible = false;
                    maxRunVelocityTb.IsVisible = false;
                    removeMaxRunVelocityButton.IsVisible = false;
                    addMaxRunVelocityButton.IsVisible = true;
                    MarkDirty();
                };

                Grid.SetColumn(movementGrid, 1);
                Grid.SetRow(movementGrid, gridRow);
                propertiesGrid.Children.Add(movementGrid);

                _fieldControls["movementtype"] = movementTypeCb;
                _fieldControls["maxvelocity"] = maxVelocityTb;
                if (hasMaxRunVelocity)
                    _fieldControls["maxrunvelocity"] = maxRunVelocityTb;
                gridRow++;
                continue;
            }

            if (IsCultureAwareSimpleField(field.Tag))
            {
                propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                var cultureFieldLabel = new TextBlock
                {
                    Text = field.Label,
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(0, 10, 6, 4)
                };
                Grid.SetColumn(cultureFieldLabel, 0);
                Grid.SetRow(cultureFieldLabel, gridRow);
                propertiesGrid.Children.Add(cultureFieldLabel);

                var fieldEntries = ProtoXmlHandler.GetCultureAwareSimpleFields(unit, field.Tag);
                var defaultEntry = fieldEntries.FirstOrDefault(x => string.IsNullOrWhiteSpace(x.Culture));
                var cultureEntries = fieldEntries
                    .Where(x => !string.IsNullOrWhiteSpace(x.Culture))
                    .ToList();
                var suggestionList = ProtoConstants.FieldSuggestions.TryGetValue(field.Tag, out var suggestions)
                    ? suggestions
                    : [];

                var fieldStack = new StackPanel { Spacing = 4 };
                var rowStates = new List<CultureFieldRowState>();
                _cultureFieldRows[field.Tag] = rowStates;
                AssetPathEditor? defaultAcb = null;
                Grid? defaultRow = null;
                Button? btnAddCulture = null;
                var defaultRowHasSelector = cultureEntries.Count > 0;

                void RefreshCultureIconPreview()
                {
                    if (!field.Tag.Equals("icon", StringComparison.OrdinalIgnoreCase))
                        return;

                    var options = new List<(string Path, string? Culture)>();
                    if (defaultAcb != null)
                        options.Add((defaultAcb.FullValue, null));
                    options.AddRange(rowStates.Select(state => (
                        state.ValueEditor.FullValue,
                        state.CultureCb.SelectedItem as string ?? state.CultureCb.SelectedValue as string)));
                    _ = iconPreview.ShowOptionsAsync(options);
                }

                AssetPathEditor CreateValueEditor(string value, Thickness margin)
                {
                    var allCulturePathValues = suggestionList
                        .Concat(fieldEntries.Select(entry => entry.Value));
                    var editor = CreateAssetPathEditor(field.Tag, value, GetAssetPathSuggestions(field.Tag, allCulturePathValues));
                    editor.IsEnabled = !_isReadOnly;
                    editor.Margin = margin;
                    if (field.Tag.Equals("animfile", StringComparison.OrdinalIgnoreCase))
                        editor.FullValueChanged += (_, _) => RefreshCurrentUnitAnimationCatalogFromEditors();
                    return editor;
                }

                ComboBox CreateDefaultCultureSelector() => new()
                {
                    ItemsSource = new[] { "Default" },
                    SelectedItem = "Default",
                    Width = 100,
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 8, 4)
                };

                void ConfigureDefaultRow()
                {
                    if (defaultAcb == null || defaultRow == null)
                        return;
                    defaultRow.Children.Clear();
                    defaultRow.ColumnDefinitions.Clear();
                    if (defaultRowHasSelector)
                    {
                        defaultRow.ColumnDefinitions.Add(new ColumnDefinition(100, GridUnitType.Pixel));
                        defaultRow.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
                        defaultRow.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
                        defaultRow.Children.Add(CreateDefaultCultureSelector());
                        Grid.SetColumn(defaultAcb, 1);
                    }
                    else
                    {
                        defaultRow.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
                        defaultRow.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Auto));
                        Grid.SetColumn(defaultAcb, 0);
                    }
                    defaultAcb.Margin = new Thickness(0, 4, 8, 4);
                    defaultRow.Children.Add(defaultAcb);
                    if (btnAddCulture != null)
                    {
                        Grid.SetColumn(btnAddCulture, defaultRowHasSelector ? 2 : 1);
                        defaultRow.Children.Add(btnAddCulture);
                    }
                }

                bool showDefaultRow = !_isReadOnly || defaultEntry != null || cultureEntries.Count == 0;
                if (showDefaultRow)
                {
                    defaultAcb = CreateValueEditor(defaultEntry?.Value ?? "", new Thickness(0, 4, 8, 4));
                    if (field.Tag.Equals("icon", StringComparison.OrdinalIgnoreCase))
                        defaultAcb.FullValueChanged += (_, _) => RefreshCultureIconPreview();
                    defaultRow = new Grid { HorizontalAlignment = HorizontalAlignment.Left };
                    _fieldControls[field.Tag] = defaultAcb;
                    ConfigureDefaultRow();
                    fieldStack.Children.Add(defaultRow);
                }

                void AddCultureRow(string cultureLabel, string value)
                {
                    var rowGrid = new Grid
                    {
                        ColumnDefinitions = new ColumnDefinitions("100, Auto, Auto"),
                        Margin = new Thickness(0, 0, 0, 0),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };

                    var cultureCb = new ComboBox
                    {
                        ItemsSource = SupportedCultureLabels
                            .Concat(string.IsNullOrWhiteSpace(cultureLabel) ? [] : [cultureLabel])
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList(),
                        SelectedItem = SupportedCultureLabels.FirstOrDefault(x => x.Equals(cultureLabel, StringComparison.OrdinalIgnoreCase)) ?? cultureLabel,
                        IsEnabled = !_isReadOnly,
                        Width = 80,
                        Margin = new Thickness(0, 4, 8, 4)
                    };
                    cultureCb.SelectionChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed) MarkDirty();
                        }
                        RefreshCultureIconPreview();
                    };
                    Grid.SetColumn(cultureCb, 0);
                    rowGrid.Children.Add(cultureCb);

                    var valueAcb = CreateValueEditor(value, new Thickness(0, 4, 8, 4));
                    if (field.Tag.Equals("icon", StringComparison.OrdinalIgnoreCase))
                        valueAcb.FullValueChanged += (_, _) => RefreshCultureIconPreview();
                    Grid.SetColumn(valueAcb, 1);
                    rowGrid.Children.Add(valueAcb);

                    var rowState = new CultureFieldRowState
                    {
                        RowPanel = rowGrid,
                        CultureCb = cultureCb,
                        ValueEditor = valueAcb
                    };
                    rowStates.Add(rowState);

                    if (!_isReadOnly)
                    {
                        var btnDel = new Button
                        {
                            Classes = { "remove-button" },
                            VerticalAlignment = VerticalAlignment.Center,
                            Margin = new Thickness(2, 4, 0, 4)
                        };
                        btnDel.Click += async (s, e) =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                rowStates.Remove(rowState);
                                fieldStack.Children.Remove(rowGrid);
                                RefreshCultureIconPreview();
                                if (field.Tag.Equals("animfile", StringComparison.OrdinalIgnoreCase))
                                    RefreshCurrentUnitAnimationCatalogFromEditors();
                                MarkDirty();
                            }
                        };
                        Grid.SetColumn(btnDel, 2);
                        rowGrid.Children.Add(btnDel);
                    }

                    fieldStack.Children.Add(rowGrid);
                }

                foreach (var entry in cultureEntries)
                    AddCultureRow(GetCultureLabel(entry.Culture), entry.Value);
                RefreshCultureIconPreview();

                if (!_isReadOnly)
                {
                    btnAddCulture = new Button
                    {
                        Content = field.Tag.Equals("icon", StringComparison.OrdinalIgnoreCase)
                            ? "Add Culture Specific Icon"
                            : "Add Culture Specific Animfile",
                        Classes = { "add-component" },
                        Margin = new Thickness(0, 4, 0, 4),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    btnAddCulture.Click += async (s, e) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            var usedCultures = new HashSet<string>(
                                rowStates
                                    .Select(x => GetCultureValue(x.CultureCb.SelectedItem as string ?? x.CultureCb.SelectedValue as string ?? "")),
                                StringComparer.OrdinalIgnoreCase);
                            var nextCulture = SupportedCultures
                                .Select(x => x.Label)
                                .FirstOrDefault(x => !usedCultures.Contains(GetCultureValue(x)))
                                ?? SupportedCultures[0].Label;
                            if (!defaultRowHasSelector)
                            {
                                defaultRowHasSelector = true;
                                ConfigureDefaultRow();
                            }
                            AddCultureRow(nextCulture, "");
                            RefreshCultureIconPreview();
                            MarkDirty();
                        }
                    };
                    ConfigureDefaultRow();
                }

                Grid.SetColumn(fieldStack, 1);
                Grid.SetRow(fieldStack, gridRow);
                propertiesGrid.Children.Add(fieldStack);
                gridRow++;
                continue;
            }

            propertiesGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var label = new TextBlock
            {
                Text = field.Label,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 4, 10, 4)
            };
            Grid.SetColumn(label, 0);
            Grid.SetRow(label, gridRow);
            propertiesGrid.Children.Add(label);

            string initialValue = ProtoXmlHandler.GetSimpleField(unit, field.Tag) ?? "";
            if (field.Tag.Equals("editornameid", StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(initialValue))
                initialValue = ProtoXmlHandler.GetSimpleField(unit, "displaynameid") ?? "";
            if (IsStringBackedField(field.Tag))
                _currentStringFieldIds[field.Tag] = initialValue;

            Control control;
            if (field.Mode == FieldInputMode.Suggest)
            {
                if (ProtoConstants.FieldSuggestions.TryGetValue(field.Tag, out var list))
                {
                    if (IsSelectionOnlySimpleField(field.Tag))
                    {
                        var selectionOptions = list
                            .Concat(string.IsNullOrWhiteSpace(initialValue) ? [] : [initialValue])
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList();
                        var combo = new ComboBox
                        {
                            ItemsSource = selectionOptions,
                            SelectedItem = list.FirstOrDefault(x => x.Equals(initialValue, StringComparison.OrdinalIgnoreCase))
                                           ?? (string.IsNullOrWhiteSpace(initialValue) ? null : initialValue),
                            IsEnabled = !_isReadOnly,
                            Margin = new Thickness(0, 4, 0, 4)
                        };
                        combo.SelectionChanged += async (s, e) =>
                        {
                            if (!_isPopulating)
                            {
                                var proceed = await CheckStartLocalMod();
                                if (proceed) MarkDirty();
                            }
                        };
                        control = combo;
                    }
                    else
                    {
                        var acb = new AutoCompleteBox
                        {
                            Text = initialValue,
                            FilterMode = AutoCompleteFilterMode.Contains,
                            IsEnabled = !_isReadOnly,
                            Margin = new Thickness(0, 4, 0, 4),
                            ItemsSource = list
                        };
                        if (AssetPathFieldTags.Contains(field.Tag))
                            EditorTextFieldStyle.ConfigureSelector(acb);
                        else
                            EditorTextFieldStyle.ConfigureSelector(acb);
                        EnableDropdownAutoComplete(acb);

                        if (!AssetPathFieldTags.Contains(field.Tag))
                        {
                            acb.TextChanged += async (s, e) =>
                            {
                                if (!_isPopulating)
                                {
                                    var proceed = await CheckStartLocalMod();
                                    if (proceed) MarkDirty();
                                }
                            };
                        }

                        control = acb;
                    }
                }
                else
                {
                    var acb = new AutoCompleteBox
                    {
                        Text = initialValue,
                        FilterMode = AutoCompleteFilterMode.Contains,
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(0, 4, 0, 4)
                    };
                    EditorTextFieldStyle.ConfigureSelector(acb);
                    EnableDropdownAutoComplete(acb);

                    acb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed) MarkDirty();
                        }
                    };

                    control = acb;
                }
            }
            else
            {
                var tb = new TextBox
                {
                    Text = IsStringBackedField(field.Tag) ? "" : initialValue,
                    IsEnabled = !_isReadOnly,
                    Margin = new Thickness(0, 4, 0, 4)
                };

                if (field.Mode != FieldInputMode.Number)
                    EditorTextFieldStyle.ConfigureTextBox(tb);

                if (field.Tag.Equals("rollovertextid", StringComparison.OrdinalIgnoreCase))
                {
                    tb.MinHeight = 54;
                    tb.AcceptsReturn = true;
                    tb.TextWrapping = TextWrapping.Wrap;
                }

                tb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };

                control = tb;
            }

            if (AssetPathFieldTags.Contains(field.Tag))
            {
                control = CreateAssetPathEditor(field.Tag, initialValue, GetAssetPathSuggestions(field.Tag));
            }
            else if (field.Mode == FieldInputMode.Number && control is TextBox numericTextBox)
                AttachDecimalBehavior(numericTextBox);

            Grid.SetColumn(control, 1);
            Grid.SetRow(control, gridRow);
            propertiesGrid.Children.Add(control);

            _fieldControls[field.Tag] = control;
            gridRow++;
        }

        var propertiesLayout = new Grid
        {
            HorizontalAlignment = HorizontalAlignment.Left
        };
        propertiesLayout.Children.Add(propertiesGrid);
        propertiesLayout.Children.Add(iconPreview);
        _activeEditorPanel.Children.Add(propertiesLayout);

        var structureEditorsContainer = new StackPanel { Spacing = 4, Margin = new Thickness(0, 4, 0, 0) };
        var structureAddButtonsRow = new WrapPanel { Orientation = Orientation.Horizontal };
        structureEditorsContainer.Children.Add(structureAddButtonsRow);
        _activeEditorPanel.Children.Add(structureEditorsContainer);

        void PlaceStructureAddButtonsAfter(Control? expandedEditor)
        {
            structureEditorsContainer.Children.Remove(structureAddButtonsRow);
            if (expandedEditor == null)
                structureEditorsContainer.Children.Insert(0, structureAddButtonsRow);
            else
                structureEditorsContainer.Children.Insert(structureEditorsContainer.Children.IndexOf(expandedEditor) + 1, structureAddButtonsRow);
        }

        string? blVal = ProtoXmlHandler.GetSimpleField(unit, "buildlimit");
        var initialDynamicBuildLimitEntries = ProtoXmlHandler.GetDynamicBuildLimitUnitTypes(unit)
            .Select(x => new ProtoBuildLimitEntry { Value = x })
            .ToList();
        var initialSharedBuildLimitEntries = ProtoXmlHandler.GetSharedBuildLimitEntries(unit);
        var buildLimitSuggestions = GetAvailableBuildLimitTargets();
        var buildLimitContainer = new StackPanel { Spacing = 4, IsVisible = false };
        structureEditorsContainer.Children.Add(buildLimitContainer);
        Button? addBuildLimitButton = null;

        BuildLimitMode GetInitialBuildLimitMode()
        {
            if (initialSharedBuildLimitEntries.Count > 0)
                return BuildLimitMode.Shared;
            if (initialDynamicBuildLimitEntries.Count > 0)
                return BuildLimitMode.Dynamic;
            return BuildLimitMode.Standard;
        }

        List<ProtoBuildLimitEntry> GetInitialBuildLimitEntries(BuildLimitMode mode) => mode switch
        {
            BuildLimitMode.Dynamic => initialDynamicBuildLimitEntries
                .Select(x => new ProtoBuildLimitEntry { Value = x.Value })
                .ToList(),
            BuildLimitMode.Shared => initialSharedBuildLimitEntries
                .Select(x => new ProtoBuildLimitEntry { Value = x.Value, Weight = x.Weight })
                .ToList(),
            _ => []
        };

        List<ProtoBuildLimitEntry> ReadCurrentBuildLimitEntries()
            => _buildLimitRows
                .Select(row => new ProtoBuildLimitEntry
                {
                    Value = row.ValueAcb.Text?.Trim() ?? "",
                    Weight = row.WeightTb?.Text?.Trim() ?? "",
                })
                .Where(x => !string.IsNullOrWhiteSpace(x.Value) || !string.IsNullOrWhiteSpace(x.Weight))
                .ToList();

        void ShowBuildLimit(string initialLimit, BuildLimitMode initialMode, IEnumerable<ProtoBuildLimitEntry>? initialEntries = null)
        {
            if (addBuildLimitButton != null)
                structureAddButtonsRow.Children.Remove(addBuildLimitButton);
            buildLimitContainer.IsVisible = true;
            PlaceStructureAddButtonsAfter(buildLimitContainer);
            buildLimitContainer.Children.Clear();
            _buildLimitRows.Clear();
            _currentBuildLimitMode = initialMode;
            var grid = new Grid { ColumnDefinitions = new ColumnDefinitions("150, 90, Auto, Auto") };

            var lbl = new TextBlock { Text = "Build Limit", VerticalAlignment = VerticalAlignment.Center };
            Grid.SetColumn(lbl, 0);
            grid.Children.Add(lbl);

            var tb = new TextBox { Text = initialLimit, IsEnabled = !_isReadOnly, Margin = new Thickness(0, 0, 20, 0) };
            AttachDecimalBehavior(tb);
            tb.TextChanged += async (s, e) =>
            {
                if (!_isPopulating)
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        MarkDirty();
                    }
                }
            };
            Grid.SetColumn(tb, 1);
            grid.Children.Add(tb);
            _fieldControls["buildlimit"] = tb;

            var modePanel = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 8,
                VerticalAlignment = VerticalAlignment.Center
            };

            modePanel.Children.Add(new TextBlock
            {
                Text = "Type",
                VerticalAlignment = VerticalAlignment.Center
            });

            var modeCb = new ComboBox
            {
                ItemsSource = new[]
                {
                    GetBuildLimitModeLabel(BuildLimitMode.Standard),
                    GetBuildLimitModeLabel(BuildLimitMode.Dynamic),
                    GetBuildLimitModeLabel(BuildLimitMode.Shared)
                },
                SelectedItem = GetBuildLimitModeLabel(initialMode),
                IsEnabled = !_isReadOnly,
                Width = 180
            };
            modePanel.Children.Add(modeCb);
            Grid.SetColumn(modePanel, 2);
            grid.Children.Add(modePanel);

            var detailsContainer = new StackPanel { Spacing = 4, Margin = new Thickness(150, 0, 0, 0) };

            void AddBuildLimitTargetRow(BuildLimitMode mode, ProtoBuildLimitEntry? entry = null)
            {
                var rowPanel = new Grid
                {
                    ColumnDefinitions = mode == BuildLimitMode.Shared
                        ? new ColumnDefinitions("380, 90, Auto")
                        : new ColumnDefinitions("380, Auto"),
                    Margin = new Thickness(0, 2, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };

                var valueAcb = CreateValidatedOtherSuggestionBox(
                    entry?.Value ?? "",
                    buildLimitSuggestions,
                    mode == BuildLimitMode.Dynamic ? "Unit Type or Proto Unit" : "Shared Unit Type or Proto Unit");
                valueAcb.Width = 380;
                valueAcb.MaxWidth = 380;
                valueAcb.Margin = mode == BuildLimitMode.Shared
                    ? new Thickness(0, 0, 8, 0)
                    : new Thickness(0);
                valueAcb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                Grid.SetColumn(valueAcb, 0);
                rowPanel.Children.Add(valueAcb);

                TextBox? weightTb = null;
                if (mode == BuildLimitMode.Shared)
                {
                    weightTb = new TextBox
                    {
                        Text = string.IsNullOrWhiteSpace(entry?.Weight) ? "1" : entry!.Weight,
                        PlaceholderText = "Weight",
                        IsEnabled = !_isReadOnly,
                        Margin = new Thickness(0)
                    };
                    AttachDecimalBehavior(weightTb);
                    weightTb.TextChanged += async (s, e) =>
                    {
                        if (!_isPopulating)
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                var text = weightTb.Text ?? "";
                                if (!string.IsNullOrWhiteSpace(text) &&
                                    (!double.TryParse(text, out double weight) || weight < 0))
                                {
                                    var filtered = new string(text
                                        .Where(ch => char.IsDigit(ch) || ch == '.')
                                        .ToArray());

                                    var dotIndex = filtered.IndexOf('.');
                                    if (dotIndex >= 0)
                                    {
                                        filtered = filtered[..(dotIndex + 1)] + filtered[(dotIndex + 1)..].Replace(".", "", StringComparison.Ordinal);
                                    }

                                    if (filtered.Length == 0)
                                        filtered = "0";

                                    if (double.TryParse(filtered, out var filteredWeight) && filteredWeight < 0)
                                        filtered = "0";

                                    if (!string.Equals(weightTb.Text, filtered, StringComparison.Ordinal))
                                        weightTb.Text = filtered;
                                }

                                MarkDirty();
                            }
                        }
                    };
                    Grid.SetColumn(weightTb, 1);
                    rowPanel.Children.Add(weightTb);
                }

                var rowState = new BuildLimitTargetRowState
                {
                    RowPanel = rowPanel,
                    ValueAcb = valueAcb,
                    WeightTb = weightTb
                };
                _buildLimitRows.Add(rowState);

                if (!_isReadOnly)
                {
                    var btnDelRow = new Button
                    {
                        Classes = { "remove-button" },
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(2, 0, 0, 0)
                    };
                    btnDelRow.Click += async (s, e) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            _buildLimitRows.Remove(rowState);
                            detailsContainer.Children.Remove(rowPanel);
                            MarkDirty();
                        }
                    };
                    Grid.SetColumn(btnDelRow, mode == BuildLimitMode.Shared ? 2 : 1);
                    rowPanel.Children.Add(btnDelRow);
                }

                if (!_isReadOnly &&
                    detailsContainer.Children.Count > 0 &&
                    detailsContainer.Children[^1] is Button)
                {
                    detailsContainer.Children.Insert(detailsContainer.Children.Count - 1, rowPanel);
                }
                else
                {
                    detailsContainer.Children.Add(rowPanel);
                }
            }

            void RenderBuildLimitModeDetails(BuildLimitMode mode, IEnumerable<ProtoBuildLimitEntry>? seedEntries = null)
            {
                _currentBuildLimitMode = mode;
                _buildLimitRows.Clear();
                detailsContainer.Children.Clear();

                if (mode == BuildLimitMode.Standard)
                    return;

                var headerGrid = new Grid
                {
                    ColumnDefinitions = mode == BuildLimitMode.Shared
                        ? new ColumnDefinitions("380, 90, Auto")
                        : new ColumnDefinitions("380, Auto"),
                    Margin = new Thickness(0, 0, 0, 2),
                    HorizontalAlignment = HorizontalAlignment.Left
                };

                var valueHeader = new TextBlock
                {
                    Text = "Unit Type / Proto Unit",
                    FontWeight = FontWeight.Bold,
                    Margin = new Thickness(0, 0, 8, 0)
                };
                Grid.SetColumn(valueHeader, 0);
                headerGrid.Children.Add(valueHeader);

                if (mode == BuildLimitMode.Shared)
                {
                    var weightHeader = new TextBlock
                    {
                        Text = "Weight",
                        FontWeight = FontWeight.Bold,
                        Margin = new Thickness(0, 0, 8, 0)
                    };
                    Grid.SetColumn(weightHeader, 1);
                    headerGrid.Children.Add(weightHeader);
                }

                detailsContainer.Children.Add(headerGrid);

                foreach (var entry in seedEntries ?? [])
                    AddBuildLimitTargetRow(mode, entry);

                if (!_isReadOnly)
                {
                    var btnAddTarget = new Button
                    {
                        Content = mode == BuildLimitMode.Dynamic ? "Add Dynamic Type" : "Add Shared Type",
                        Classes = { "add-component" },
                        Margin = new Thickness(0, 4, 0, 4),
                        HorizontalAlignment = HorizontalAlignment.Left
                    };
                    btnAddTarget.Click += async (s, e) =>
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            AddBuildLimitTargetRow(mode);
                            MarkDirty();
                        }
                    };
                    detailsContainer.Children.Add(btnAddTarget);
                }
            }

            modeCb.SelectionChanged += async (s, e) =>
            {
                if (_isPopulating)
                    return;

                var proceed = await CheckStartLocalMod();
                if (!proceed)
                    return;

                var seedEntries = ReadCurrentBuildLimitEntries();
                var selectedMode = ParseBuildLimitMode(modeCb.SelectedItem as string);
                RenderBuildLimitModeDetails(selectedMode, seedEntries);
                MarkDirty();
            };

            if (!_isReadOnly)
            {
                var btnDel = new Button { Classes = { "remove-button" }, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(2, 0, 0, 0) };
                btnDel.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        _fieldControls.Remove("buildlimit");
                        MarkDirty();
                        ShowAddBuildLimitButton();
                    }
                };
                Grid.SetColumn(btnDel, 3);
                grid.Children.Add(btnDel);
            }
            buildLimitContainer.Children.Add(grid);
            buildLimitContainer.Children.Add(detailsContainer);
            RenderBuildLimitModeDetails(initialMode, initialEntries);
        }

        void ShowAddBuildLimitButton()
        {
            buildLimitContainer.Children.Clear();
            buildLimitContainer.IsVisible = false;
            if (addBuildLimitButton != null)
                structureAddButtonsRow.Children.Remove(addBuildLimitButton);
            _fieldControls.Remove("buildlimit");
            _buildLimitRows.Clear();
            _currentBuildLimitMode = BuildLimitMode.Standard;
            if (!_isReadOnly)
            {
                addBuildLimitButton = new Button { Content = "Add a Build Limit", Classes = { "add-component" }, Margin = new Thickness(0, 4, 8, 4) };
                addBuildLimitButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        MarkDirty();
                        ShowBuildLimit("1", BuildLimitMode.Standard);
                    }
                };
                structureAddButtonsRow.Children.Add(addBuildLimitButton);
            }
            var lastExpanded = structureEditorsContainer.Children.OfType<StackPanel>().LastOrDefault(panel => panel.IsVisible);
            PlaceStructureAddButtonsAfter(lastExpanded);
        }

        var initialBuildLimitMode = GetInitialBuildLimitMode();
        bool hasBuildLimitData = !string.IsNullOrWhiteSpace(blVal)
            || initialDynamicBuildLimitEntries.Count > 0
            || initialSharedBuildLimitEntries.Count > 0;

        if (hasBuildLimitData)
        {
            ShowBuildLimit(blVal ?? "1", initialBuildLimitMode, GetInitialBuildLimitEntries(initialBuildLimitMode));
        }
        else
        {
            ShowAddBuildLimitButton();
        }

        string? maxContainedValue = ProtoXmlHandler.GetSimpleField(unit, "maxcontained");
        string containedHitPointBonusValue = ProtoXmlHandler.GetSimpleField(unit, "containedhitpointbonus") ?? "";
        string containedSpeedBonusValue = ProtoXmlHandler.GetSimpleField(unit, "containedspeedbonus") ?? "";
        string containedRegenRateValue = ProtoXmlHandler.GetSimpleField(unit, "containedregenrate") ?? "";
        var initialContains = new HashSet<string>(ProtoXmlHandler.GetContainList(unit), StringComparer.OrdinalIgnoreCase);
        var initialNotContains = new HashSet<string>(ProtoXmlHandler.GetNotContainList(unit), StringComparer.OrdinalIgnoreCase);
        var initialContainExternal = unit.Elements("contain").Any(element =>
            string.Equals((string?)element.Attribute("external"), "1", StringComparison.OrdinalIgnoreCase));
        var initialContainEjectCommand = ProtoXmlHandler.GetCommandEntries(unit).Any(entry =>
            entry.Value.Equals("Eject", StringComparison.OrdinalIgnoreCase));
        var containSuggestions = GetAvailableBuildLimitTargets();
        var containContainer = new StackPanel { Spacing = 4, IsVisible = false };
        structureEditorsContainer.Children.Add(containContainer);
        Button? addContainButton = null;

        void ShowContainEditor(string initialMaxContained)
        {
            if (addContainButton != null)
                structureAddButtonsRow.Children.Remove(addContainButton);
            containContainer.IsVisible = true;
            PlaceStructureAddButtonsAfter(containContainer);
            containContainer.Children.Clear();

            var containValues = new HashSet<string>(initialContains, StringComparer.OrdinalIgnoreCase);
            var notContainValues = new HashSet<string>(initialNotContains, StringComparer.OrdinalIgnoreCase);
            _currentContains = containValues;
            _currentNotContains = notContainValues;

            void AttachIntegerOnlyBehavior(TextBox textBox, string defaultValue)
            {
                EditorNumericFieldStyle.ConfigureNumericTextBox(textBox);
                textBox.AddHandler(InputElement.TextInputEvent, (sender, args) =>
                {
                    if (string.IsNullOrWhiteSpace(args.Text) || !args.Text.All(char.IsDigit))
                        args.Handled = true;
                }, RoutingStrategies.Tunnel);
                textBox.TextChanged += (_, _) =>
                {
                    var filtered = new string((textBox.Text ?? "").Where(char.IsDigit).ToArray());
                    if (!string.Equals(textBox.Text, filtered, StringComparison.Ordinal))
                        textBox.Text = filtered;
                };

                textBox.LostFocus += (s, e) =>
                {
                    if (string.IsNullOrWhiteSpace(textBox.Text))
                        textBox.Text = defaultValue;
                };
            }

            var topGrid = new Grid { ColumnDefinitions = new ColumnDefinitions("150, 90, Auto, Auto, Auto") };

            var lbl = new TextBlock { Text = "Contain", VerticalAlignment = VerticalAlignment.Center };
            Grid.SetColumn(lbl, 0);
            topGrid.Children.Add(lbl);

            var maxContainedTb = new TextBox
            {
                Text = initialMaxContained,
                IsEnabled = !_isReadOnly,
                Margin = new Thickness(0, 0, 10, 0)
            };
            AttachIntegerOnlyBehavior(maxContainedTb, "0");
            maxContainedTb.TextChanged += async (s, e) =>
            {
                if (!_isPopulating)
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        var filtered = new string((maxContainedTb.Text ?? "").Where(char.IsDigit).ToArray());
                        if (!string.Equals(maxContainedTb.Text, filtered, StringComparison.Ordinal))
                            maxContainedTb.Text = filtered;
                        MarkDirty();
                    }
                }
            };
            Grid.SetColumn(maxContainedTb, 1);
            topGrid.Children.Add(maxContainedTb);
            _fieldControls["maxcontained"] = maxContainedTb;

            var externalCheckBox = new CheckBox
            {
                Content = "External",
                IsChecked = initialContainExternal,
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(8, 0, 0, 0)
            };
            externalCheckBox.Click += async (_, _) =>
            {
                if (_isPopulating) return;
                if (!await CheckStartLocalMod())
                {
                    externalCheckBox.IsChecked = externalCheckBox.IsChecked != true;
                    return;
                }
                MarkDirty();
            };
            Grid.SetColumn(externalCheckBox, 2);
            topGrid.Children.Add(externalCheckBox);
            _fieldControls["contain.external"] = externalCheckBox;

            var ejectCommandCheckBox = new CheckBox
            {
                Content = "Eject command",
                IsChecked = initialContainEjectCommand,
                IsEnabled = !_isReadOnly,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(8, 0, 0, 0)
            };
            _containEjectCommandCheckBox = ejectCommandCheckBox;
            ejectCommandCheckBox.Click += async (_, _) =>
            {
                if (_isPopulating || _syncingContainEjectCommand) return;
                if (!await CheckStartLocalMod())
                {
                    _syncingContainEjectCommand = true;
                    ejectCommandCheckBox.IsChecked = ejectCommandCheckBox.IsChecked != true;
                    _syncingContainEjectCommand = false;
                    return;
                }

                if (ejectCommandCheckBox.IsChecked == true)
                {
                    _addUnitCommandRow?.Invoke(new ProtoCommandEntry
                    {
                        Value = "Eject",
                        Row = "3",
                        Column = "1"
                    });
                }
                else
                {
                    _removeUnitCommandRows?.Invoke("Eject");
                }
                MarkDirty();
            };
            Grid.SetColumn(ejectCommandCheckBox, 3);
            topGrid.Children.Add(ejectCommandCheckBox);

            if (!_isReadOnly)
            {
                var btnDel = new Button { Classes = { "remove-button" }, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(2, 0, 0, 0) };
                btnDel.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        _fieldControls.Remove("maxcontained");
                        _fieldControls.Remove("contain.external");
                        _currentContains = null;
                        _currentNotContains = null;
                        initialContainExternal = false;
                        initialContainEjectCommand = false;
                        _containRemovedDuringEdit = true;
                        _removeUnitCommandRows?.Invoke("Eject");
                        _containEjectCommandCheckBox = null;
                        MarkDirty();
                        ShowAddContainButton();
                    }
                };
                Grid.SetColumn(btnDel, 4);
                topGrid.Children.Add(btnDel);
            }

            containContainer.Children.Add(topGrid);

            StackPanel CreateContainPicker(string title, HashSet<string> values)
            {
                var group = new StackPanel { Spacing = 2 };
                AutoCompleteBox? acbAdd = null;
                var selectorRow = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 6,
                    VerticalAlignment = VerticalAlignment.Center
                };
                var titleLabel = new TextBlock
                {
                    Text = title,
                    FontWeight = FontWeight.Bold,
                    VerticalAlignment = VerticalAlignment.Center
                };
                selectorRow.Children.Add(titleLabel);
                group.Children.Add(selectorRow);

                var wrap = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 2, 0, 2) };
                group.Children.Add(wrap);

                void RefreshDisplay()
                {
                    if (acbAdd != null)
                        acbAdd.ItemsSource = containSuggestions.Where(value => !values.Contains(value)).ToList();
                    wrap.Children.Clear();
                    foreach (var value in values.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                    {
                        var chip = CreateChip(value, async () =>
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                values.Remove(value);
                                MarkDirty();
                                RefreshDisplay();
                                CommitChipAdditionAndRefreshXmlPreview();
                            }
                        });
                        wrap.Children.Add(chip);
                    }
                }

                RefreshDisplay();

                if (!_isReadOnly)
                {
                    acbAdd = new AutoCompleteBox
                    {
                        FilterMode = AutoCompleteFilterMode.Contains,
                        ItemsSource = containSuggestions.Where(value => !values.Contains(value)).ToList(),
                        Width = 150,
                        MaxWidth = 150,
                        HorizontalAlignment = HorizontalAlignment.Left,
                        Margin = new Thickness(0, 4, 0, 4)
                    };
                    EnableDropdownAutoComplete(acbAdd, selectAllOnFirstClick: false);

                    async void PerformAdd()
                    {
                        string input = acbAdd.Text?.Trim() ?? "";
                        string? match = containSuggestions.FirstOrDefault(x => x.Equals(input, StringComparison.OrdinalIgnoreCase));
                        if (!string.IsNullOrEmpty(match) && !values.Contains(match))
                        {
                            var proceed = await CheckStartLocalMod();
                            if (proceed)
                            {
                                values.Add(match);
                                acbAdd.Text = "";
                                acbAdd.SelectedItem = null;
                                MarkDirty();
                                RefreshDisplay();
                                CommitChipAdditionAndRefreshXmlPreview();
                                Dispatcher.UIThread.Post(() =>
                                {
                                    if (acbAdd.IsEnabled && string.IsNullOrWhiteSpace(acbAdd.Text))
                                        acbAdd.IsDropDownOpen = true;
                                });
                            }
                        }
                    }

                    acbAdd.SelectionChanged += (s, e) =>
                    {
                        if (acbAdd.SelectedItem is string sel)
                        {
                            acbAdd.Text = sel;
                            PerformAdd();
                        }
                    };
                    selectorRow.Children.Add(acbAdd);
                }

                return group;
            }

            var containPickersRow = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,*"),
                ColumnSpacing = 16,
                Margin = new Thickness(150, 0, 0, 0)
            };
            containPickersRow.Children.Add(CreateContainPicker("Contain", containValues));
            var notContainPicker = CreateContainPicker("Not Contain", notContainValues);
            Grid.SetColumn(notContainPicker, 1);
            containPickersRow.Children.Add(notContainPicker);
            containContainer.Children.Add(containPickersRow);

            var containBonusContainer = new StackPanel { Spacing = 4 };
            containContainer.Children.Add(containBonusContainer);

            string GetContainBonusValue(string key) => key switch
            {
                "containedhitpointbonus" => containedHitPointBonusValue,
                "containedspeedbonus" => containedSpeedBonusValue,
                "containedregenrate" => containedRegenRateValue,
                _ => ""
            };

            void SetContainBonusValue(string key, string value)
            {
                if (key.Equals("containedhitpointbonus", StringComparison.OrdinalIgnoreCase)) containedHitPointBonusValue = value;
                else if (key.Equals("containedspeedbonus", StringComparison.OrdinalIgnoreCase)) containedSpeedBonusValue = value;
                else if (key.Equals("containedregenrate", StringComparison.OrdinalIgnoreCase)) containedRegenRateValue = value;
            }

            void RenderContainBonusFields(string? preferredKey = null)
            {
                containBonusContainer.Children.Clear();
                foreach (var key in new[] { "containedhitpointbonus", "containedspeedbonus", "containedregenrate" })
                    _fieldControls.Remove(key);

                var definitions = new[]
                {
                    (Key: "containedhitpointbonus", Label: "HP"),
                    (Key: "containedspeedbonus", Label: "Speed"),
                    (Key: "containedregenrate", Label: "Regen rate")
                };
                var hasAnyField = definitions.Any(definition => !string.IsNullOrWhiteSpace(GetContainBonusValue(definition.Key)));
                if (hasAnyField)
                {
                    containBonusContainer.Children.Add(new TextBlock
                    {
                        Text = "Contain Bonus Stats",
                        FontWeight = FontWeight.Bold,
                        Margin = new Thickness(150, 4, 0, 2)
                    });
                }

                var row = new WrapPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(150, 0, 0, 0) };
                var orderedDefinitions = definitions
                    .OrderBy(definition => definition.Key.Equals(preferredKey, StringComparison.OrdinalIgnoreCase)
                        ? 0
                        : string.IsNullOrWhiteSpace(GetContainBonusValue(definition.Key)) ? 2 : 1)
                    .ToList();
                foreach (var definition in orderedDefinitions)
                {
                    var value = GetContainBonusValue(definition.Key);
                    if (string.IsNullOrWhiteSpace(value))
                    {
                        if (_isReadOnly) continue;
                        var addButton = new Button
                        {
                            Content = definition.Label,
                            Classes = { "add-component" },
                            Margin = new Thickness(0, 4, 8, 4)
                        };
                        addButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            SetContainBonusValue(definition.Key, "0");
                            RenderContainBonusFields(definition.Key);
                            MarkDirty();
                        };
                        row.Children.Add(addButton);
                        continue;
                    }

                    var fieldGroup = new Grid { ColumnDefinitions = new ColumnDefinitions("Auto,90,Auto"), Margin = new Thickness(0, 0, 8, 0) };
                    fieldGroup.Children.Add(new TextBlock
                    {
                        Text = definition.Label,
                        VerticalAlignment = VerticalAlignment.Center,
                        Margin = new Thickness(0, 4, 6, 4)
                    });
                    var tb = new TextBox { Text = value, IsEnabled = !_isReadOnly, Margin = new Thickness(0, 4, 0, 4) };
                    AttachSignedDecimalBehavior(tb);
                    tb.LostFocus += (_, _) =>
                    {
                        if (string.IsNullOrWhiteSpace(tb.Text))
                            tb.Text = "0";
                    };
                    tb.TextChanged += async (_, _) =>
                    {
                        if (_isPopulating) return;
                        SetContainBonusValue(definition.Key, tb.Text ?? "");
                        if (await CheckStartLocalMod()) MarkDirty();
                    };
                    Grid.SetColumn(tb, 1);
                    fieldGroup.Children.Add(tb);
                    _fieldControls[definition.Key] = tb;

                    if (!_isReadOnly)
                    {
                        var removeButton = new Button { Classes = { "remove-button" }, Margin = new Thickness(2, 4, 0, 4) };
                        removeButton.Click += async (_, _) =>
                        {
                            if (!await CheckStartLocalMod()) return;
                            SetContainBonusValue(definition.Key, "");
                            RenderContainBonusFields();
                            MarkDirty();
                        };
                        Grid.SetColumn(removeButton, 2);
                        fieldGroup.Children.Add(removeButton);
                    }
                    row.Children.Add(fieldGroup);
                }

                if (row.Children.Count > 0)
                    containBonusContainer.Children.Add(row);
            }

            RenderContainBonusFields();
        }

        void ShowAddContainButton()
        {
            containContainer.Children.Clear();
            containContainer.IsVisible = false;
            if (addContainButton != null)
                structureAddButtonsRow.Children.Remove(addContainButton);
            _fieldControls.Remove("maxcontained");
            _fieldControls.Remove("contain.external");
            _currentContains = null;
            _currentNotContains = null;
            _containEjectCommandCheckBox = null;

            if (!_isReadOnly)
            {
                addContainButton = new Button
                {
                    Content = "Add Contain",
                    Classes = { "add-component" },
                    Margin = new Thickness(0, 4, 8, 4),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                addContainButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        initialContains = [];
                        initialNotContains = [];
                        initialContainExternal = false;
                        initialContainEjectCommand = false;
                        _containRemovedDuringEdit = false;
                        MarkDirty();
                        ShowContainEditor("0");
                    }
                };
                structureAddButtonsRow.Children.Add(addContainButton);
            }
            var lastExpanded = structureEditorsContainer.Children.OfType<StackPanel>().LastOrDefault(panel => panel.IsVisible);
            PlaceStructureAddButtonsAfter(lastExpanded);
        }

        bool hasContainData = !string.IsNullOrWhiteSpace(maxContainedValue) || initialContains.Count > 0 || initialNotContains.Count > 0;
        if (hasContainData)
            ShowContainEditor(maxContainedValue ?? "0");
        else
            ShowAddContainButton();

        var otherSpecificContainer = new StackPanel { Margin = new Thickness(0, -2, 0, 4), Spacing = 4 };
        _otherSpecificAttributesPanel = otherSpecificContainer;
        _activeEditorPanel.Children.Add(otherSpecificContainer);
        _currentSharedSelectionUnitTypes = null;
        _currentRechargeIncludeTypes = null;
        _currentRechargeExcludeTypes = null;
        _currentAuxRechargeIncludeTypes = null;
        _currentAuxRechargeExcludeTypes = null;
        _currentVeterancyIncludeTypes = null;
        _currentVeterancyExcludeTypes = null;
        _currentRespawnTrainTypes = null;
        _currentRespawnTrainExcludeTypes = null;
        _onDamageModifyRows.Clear();

        var otherAttributeSuggestions = GetAvailableBuildLimitTargets();
        var otherProtoUnitSuggestions = GetAvailableTrainUnitNames();
        var protoActionSuggestions = _protoActionNameSuggestions;

        void AttachDecimalBehavior(TextBox textBox)
            => EditorNumericInputBehavior.AttachUnsignedDecimal(textBox);

        void AttachSignedDecimalBehavior(TextBox textBox)
            => EditorNumericInputBehavior.AttachSignedDecimal(textBox);

        async Task HandleOtherFieldChangedAsync()
        {
            if (_isPopulating || _syncingSharedRechargeEditors)
                return;

            var proceed = await CheckStartLocalMod();
            if (proceed)
                MarkDirty();
        }

        void RegisterOtherSpecificContainer(string key, Control control)
            => _otherSpecificAttributeContainers[key] = control;

        void RemoveOtherSpecificContainer(string key, params string[] fieldKeys)
        {
            if (_otherSpecificAttributeContainers.TryGetValue(key, out var control))
            {
                otherSpecificContainer.Children.Remove(control);
                _otherSpecificAttributeContainers.Remove(key);
            }

            foreach (var fieldKey in fieldKeys)
                _fieldControls.Remove(fieldKey);
        }

        static IReadOnlyList<string> MaterializeSuggestionItems(IEnumerable<string> suggestions)
        {
            if (suggestions is IReadOnlyList<string> readOnlyList)
                return readOnlyList;

            return suggestions.ToList();
        }

        AutoCompleteBox CreateOtherSuggestionBox(string initialValue, IEnumerable<string> suggestions, string? placeholder = null)
        {
            var acb = new AutoCompleteBox
            {
                Text = initialValue,
                PlaceholderText = placeholder,
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = MaterializeSuggestionItems(suggestions),
                IsEnabled = !_isReadOnly
            };
            EditorTextFieldStyle.ConfigureSelector(acb);
            EnableDropdownAutoComplete(acb, selectAllOnFirstClick: false);
            FreezeEditorScrollWhileDropDownIsOpen(acb, _editorScroll);
            acb.TextChanged += async (s, e) => await HandleOtherFieldChangedAsync();
            return acb;
        }

        AutoCompleteBox CreateValidatedOtherSuggestionBox(string initialValue, IEnumerable<string> suggestions, string? placeholder = null, bool allowCustom = false, bool suggestionsAlreadyNormalized = false)
        {
            var authoritativeSuggestions = (suggestionsAlreadyNormalized
                ? MaterializeSuggestionItems(suggestions).ToList()
                : suggestions
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .ToList());
            var suggestionList = authoritativeSuggestions.ToList();

            var normalizedInitialValue = initialValue?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(normalizedInitialValue) &&
                !suggestionList.Any(x => x.Equals(normalizedInitialValue, StringComparison.OrdinalIgnoreCase)))
            {
                // Existing values from newer game data or another mod remain valid
                // preservation choices. Users still cannot commit a different custom value.
                suggestionList.Add(normalizedInitialValue);
            }

            var acb = CreateOtherSuggestionBox(normalizedInitialValue, suggestionList, placeholder);
            string? selectedValue = suggestionList.FirstOrDefault(x => x.Equals(initialValue, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(selectedValue))
                acb.Text = selectedValue;

            acb.SelectionChanged += (s, e) =>
            {
                if (acb.SelectedItem is string selected)
                {
                    selectedValue = selected;
                    acb.Text = selected;
                }
            };

            acb.LostFocus += (s, e) =>
            {
                if (_isPopulating)
                    return;

                Dispatcher.UIThread.Post(() =>
                {
                    if (_isPopulating)
                        return;

                    var input = acb.Text?.Trim() ?? "";
                    if (string.IsNullOrWhiteSpace(input))
                    {
                        if (!allowCustom)
                            selectedValue = null;
                        return;
                    }

                    var match = suggestionList.FirstOrDefault(x => x.Equals(input, StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(match))
                    {
                        acb.Text = match;
                        selectedValue = match;
                        return;
                    }

                    if (allowCustom)
                    {
                        selectedValue = input;
                        return;
                    }

                    SetStatsReferenceValidationError(
                        acb,
                        $"{placeholder ?? "This reference"} must match an existing value.");
                }, DispatcherPriority.Background);
            };

            if (!allowCustom)
            {
                RegisterStatsStrictReferenceEditor(
                    placeholder ?? "Reference",
                    acb,
                    () => acb.Text?.Trim() ?? "",
                    normalizedInitialValue,
                    authoritativeSuggestions,
                    allowEmpty: true);
            }

            return acb;
        }

        StrictSearchableComboBox CreateStrictSearchableOtherComboBox(
            string initialValue,
            IEnumerable<string> options,
            string? placeholder = null)
        {
            var comboBox = new StrictSearchableComboBox(
                options,
                initialValue,
                preserveUnknownInitialValue: true)
            {
                PlaceholderText = placeholder,
                IsEnabled = !_isReadOnly
            };
            comboBox.Width = EditorTextFieldStyle.StandardWidth;
            comboBox.MaxWidth = EditorTextFieldStyle.StandardWidth;
            comboBox.HorizontalAlignment = HorizontalAlignment.Left;
            comboBox.ValueCommitted += async (_, _) => await HandleOtherFieldChangedAsync();
            RegisterStatsStrictReferenceEditor(
                placeholder ?? "Option",
                comboBox,
                () => comboBox.Text?.Trim() ?? "",
                initialValue?.Trim() ?? "",
                comboBox.Options,
                allowEmpty: true);
            return comboBox;
        }

        TextBox CreateOtherTextBox(string initialValue, bool numeric = false, bool signedNumeric = false)
        {
            var tb = new TextBox
            {
                Text = initialValue,
                IsEnabled = !_isReadOnly
            };
            if (numeric)
            {
                EditorNumericFieldStyle.ConfigureNumericTextBox(tb);
                if (signedNumeric)
                    AttachSignedDecimalBehavior(tb);
                else
                    AttachDecimalBehavior(tb);
            }
            else
            {
                EditorTextFieldStyle.ConfigureTextBox(tb);
            }
            tb.TextChanged += async (s, e) => await HandleOtherFieldChangedAsync();
            return tb;
        }

        void AddSimpleOtherSpecificAttribute(string key, string tag)
        {
            if (IsOtherSpecificAttributeVisible(key, _otherSpecificAttributeContainers))
                return;

            var attributeLabel = GetOtherSpecificAttributeLabel(key);
            var labelColumnWidth = attributeLabel.Length * 7.5 + 12 > 150
                ? Math.Min(180, attributeLabel.Length * 7.5 + 12)
                : 150;
            var rowGrid = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions($"{labelColumnWidth}, Auto, Auto"),
                Margin = new Thickness(0, 2, 0, 2),
                HorizontalAlignment = HorizontalAlignment.Left
            };
            var label = new TextBlock { Text = attributeLabel, VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 4, 10, 4) };
            Grid.SetColumn(label, 0);
            rowGrid.Children.Add(label);

            Control editor;
            var initialValue = ProtoXmlHandler.GetSimpleField(unit, tag) ?? "";
            if (tag.Equals("dodgechance", StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(initialValue))
                initialValue = "0";
            if (tag.Equals("conversionresistance", StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(initialValue))
                initialValue = "1";
            if (tag.Equals("formationorder", StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(initialValue))
                initialValue = "0";
            if (tag.Equals("workersoftlimit", StringComparison.OrdinalIgnoreCase) && string.IsNullOrWhiteSpace(initialValue))
                initialValue = "0";
            if (OtherSpecificSimpleSuggestionTags.Contains(tag))
            {
                IEnumerable<string> suggestions = tag switch
                {
                    "culture" => SupportedCultureLabels,
                    "resourcesubtype" => GetKnownResourceSubtypeNames(),
                    "hotkeycontext" => GetKnownHotkeyContexts(),
                    "allyhotkeycontext" => GetKnownHotkeyContexts(),
                    "partisantype" => otherProtoUnitSuggestions,
                    "socketunittype" => otherAttributeSuggestions,
                    "disguiseprotoid" or "deadreplacement" or "deadtransform" or "eidolonprotoid" => otherProtoUnitSuggestions,
                    "initialunitaistance" => KnownInitialUnitAiStances,
                    "pathabilityflags" => GetKnownPathabilityFlags(),
                    "placementfile" => GetKnownPlacementFileNames(),
                    "selfdestructprotoaction" or "birthprotoaction" or "stackprotoaction" => protoActionSuggestions,
                    "transformcommand" => GetAvailableCommandNames(),
                    _ => Array.Empty<string>()
                };
                editor = tag switch
                {
                    "placementfile" => CreateValidatedOtherSuggestionBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key), allowCustom: true),
                    "partisantype" => CreateValidatedOtherSuggestionBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key), suggestionsAlreadyNormalized: true),
                    "disguiseprotoid" or "deadreplacement" or "deadtransform" or "eidolonprotoid"
                        => CreateValidatedOtherSuggestionBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key), suggestionsAlreadyNormalized: true),
                    "pathabilityflags" or "resourcesubtype" => new ComboBox
                    {
                        ItemsSource = MaterializeSuggestionItems(suggestions)
                            .Concat(string.IsNullOrWhiteSpace(initialValue) ? [] : [initialValue.Trim()])
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList(),
                        SelectedItem = suggestions.FirstOrDefault(x => x.Equals(initialValue, StringComparison.OrdinalIgnoreCase))
                                       ?? (string.IsNullOrWhiteSpace(initialValue) ? null : initialValue.Trim()),
                        IsEnabled = !_isReadOnly
                    },
                    "culture" or "initialunitaistance"
                        => CreateStrictSearchableOtherComboBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key)),
                    "hotkeycontext" or "allyhotkeycontext"
                        => CreateValidatedOtherSuggestionBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key)),
                    "selfdestructprotoaction" or "birthprotoaction" or "stackprotoaction" or "transformcommand"
                        => CreateValidatedOtherSuggestionBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key)),
                    _ => CreateOtherSuggestionBox(initialValue, suggestions, GetOtherSpecificAttributeLabel(key))
                };
                if (editor is ComboBox simpleComboBox && editor is not StrictSearchableComboBox)
                    simpleComboBox.SelectionChanged += async (_, _) => await HandleOtherFieldChangedAsync();
            }
            else
            {
                var signedNumeric = tag.Equals("heighthitpointbaroffset", StringComparison.OrdinalIgnoreCase) ||
                                    tag.Equals("allowedheightvariance", StringComparison.OrdinalIgnoreCase) ||
                                    tag.Equals("bloodscalemodify", StringComparison.OrdinalIgnoreCase) ||
                                    tag.Equals("bonescalemodify", StringComparison.OrdinalIgnoreCase);
                editor = CreateOtherTextBox(initialValue, OtherSpecificSimpleNumberTags.Contains(tag), signedNumeric);
            }

            Grid.SetColumn(editor, 1);
            rowGrid.Children.Add(editor);
            _fieldControls[tag] = editor;

            var isManagedProtoActionReference = tag.Equals("stackprotoaction", StringComparison.OrdinalIgnoreCase) ||
                                                tag.Equals("selfdestructprotoaction", StringComparison.OrdinalIgnoreCase) ||
                                                tag.Equals("birthprotoaction", StringComparison.OrdinalIgnoreCase) ||
                                                tag.Equals("transformcommand", StringComparison.OrdinalIgnoreCase);
            if (isManagedProtoActionReference)
            {
                editor.IsEnabled = false;
                ToolTip.SetTip(
                    editor,
                    tag.Equals("transformcommand", StringComparison.OrdinalIgnoreCase)
                        ? "This reference is managed automatically by the unique Transform command."
                        : "This reference is managed automatically by its ProtoAction.");
            }

            var linkedFlag = GetFlagForOtherSpecificAttribute(tag);
            if (!_isReadOnly && !string.IsNullOrWhiteSpace(linkedFlag))
                _currentFlags?.Add(linkedFlag);


            if (!_isReadOnly && !isManagedProtoActionReference)
            {
                var deleteButton = new Button { Classes = { "remove-button" }, VerticalAlignment = VerticalAlignment.Center };
                deleteButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        var linkedFlag = GetFlagForOtherSpecificAttribute(tag);
                        if (!string.IsNullOrWhiteSpace(linkedFlag))
                            _currentFlags?.Remove(linkedFlag);
                        RemoveOtherSpecificContainer(key, tag);
                        MarkDirty();
                        RenderOtherSpecificAddControls();
                    }
                };
                Grid.SetColumn(deleteButton, 2);
                rowGrid.Children.Add(deleteButton);
            }

            RegisterOtherSpecificContainer(key, rowGrid);
            otherSpecificContainer.Children.Add(rowGrid);
        }

