        ComboBox CreateTransformPositionCombo(string currentValue, IReadOnlyList<string> standardValues, bool enabled = true)
        {
            var values = standardValues.AsEnumerable();
            if (!string.IsNullOrWhiteSpace(currentValue) && !standardValues.Contains(currentValue, StringComparer.OrdinalIgnoreCase))
                values = values.Concat([currentValue]);

            return new ComboBox
            {
                ItemsSource = values.Distinct(StringComparer.OrdinalIgnoreCase).ToList(),
                SelectedItem = !string.IsNullOrWhiteSpace(currentValue) ? currentValue : "0",
                IsEnabled = !_isReadOnly && enabled,
                Width = 62,
                HorizontalAlignment = HorizontalAlignment.Left
            };
        }

        async Task EnsureTransformStateLoadedAsync(TransformCommandAssignmentState state)
        {
            if (state.Definition != null)
            {
                if (!state.SourceIsBuiltIn &&
                    !string.IsNullOrWhiteSpace(state.SourceCommandName) &&
                    !state.SnapshotCommandName.Equals(state.SourceCommandName, StringComparison.OrdinalIgnoreCase))
                    CaptureInlineTransformSourceSnapshots(state);
                return;
            }

            EnsureProtoUnitCommandCatalogLoaded(force: true);
            if (!_protoUnitCommandCatalog.TryGetValue(state.CommandName, out var element))
                return;

            state.Definition = ProtoUnitCommandDefinition.FromElement(element);
            state.TransformDefinition = LoadProtoUnitTransformDefinition(state.CommandName) ?? new ProtoUnitTransformDefinition
            {
                Command = state.CommandName
            };
            state.StringTexts = await ResolveProtoUnitCommandStringTextsAsync(state.Definition);
            state.SourceCommandName = state.CommandName;
            state.SourceIsBuiltIn = _builtInProtoUnitCommandNames.Contains(state.CommandName) && !IsCustomProtoUnitCommand(state.CommandName);
            if (!state.SourceIsBuiltIn)
                CaptureInlineTransformSourceSnapshots(state);
            state.DefinitionDirty = false;
        }

        void MarkTransformDefinitionDirty(TransformCommandAssignmentState state, Button saveButton)
        {
            if (_isReadOnly)
                return;
            state.DefinitionDirty = true;
            saveButton.IsVisible = true;
            MarkDirty();
        }

        async Task<bool> PersistTransformAssignmentsNowAsync()
        {
            if (_modXmlDoc == null || string.IsNullOrWhiteSpace(_modFilePath))
                return true;

            var dirtyBefore = _isDirty;
            try
            {
                var uniqueState = _transformCommandAssignments.UniqueAssignment;
                ProtoXmlHandler.SetTransformCommandEntry(unit, uniqueState == null
                    ? null
                    : new ProtoCommandEntry { Value = uniqueState.CommandName.Trim() });
                RefreshTransformCommandStatsReference();

                var regularNames = GetAvailableCommandNames()
                    .Where(name => !IsTransformUniqueCommand(name) && !IsTransformMultipleCommand(name))
                    .ToList();
                var entries = CollectValidCommandEntries(_unitCommandRows, regularNames);
                entries.AddRange(_transformCommandAssignments.BuildCommandEntries(
                    IsTransformUniqueCommand,
                    IsTransformMultipleCommand));
                ProtoXmlHandler.SetCommandEntries(unit, entries);
                ProtoXmlHandler.SaveProtoXml(_modXmlDoc, _modFilePath);
                _isDirty = dirtyBefore;
                _statusMessage.Text = "Transform assignment removed.";
                _ = Task.Delay(2000).ContinueWith(_ => Dispatcher.UIThread.Post(() => _statusMessage.Text = ""));
                return true;
            }
            catch (Exception ex)
            {
                _isDirty = dirtyBefore;
                await new Prompt(PromptType.Error, "Save failed", $"Could not save the Transform assignment change:\n{ex.Message}").ShowDialog(this);
                return false;
            }
        }

        async Task RenderTransformAssignmentAsync(TransformCommandAssignmentState state)
        {
            activeTransformState = state;
            await EnsureTransformStateLoadedAsync(state);
            transformCardHost.Children.Clear();
            RenderTransformTabs();

            if (state.Definition == null)
                return;

            var definition = state.Definition;
            var transformDefinition = state.TransformDefinition ??= new ProtoUnitTransformDefinition { Command = state.CommandName };
            var context = BuildProtoUnitCommandEditorContext(state.StringTexts);
            var sourceTransformUnitName = transformDefinition.From?.Trim() ?? "";
            var sourceBelongsToOtherUnit = !string.IsNullOrWhiteSpace(state.SourceCommandName) &&
                                           !string.IsNullOrWhiteSpace(sourceTransformUnitName) &&
                                           !sourceTransformUnitName.Equals(currentTransformUnitName, StringComparison.OrdinalIgnoreCase);
            var definitionEditorEnabled = !_isReadOnly && !sourceBelongsToOtherUnit;

            var card = new Border
            {
                Background = Brush.Parse("#181818"),
                BorderBrush = Brush.Parse("#4C4031"),
                BorderThickness = new Thickness(1),
                Padding = new Thickness(12),
                CornerRadius = new CornerRadius(6),
                Width = 810,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            var content = new StackPanel { Spacing = 8 };
            card.Child = content;
            transformCardHost.Children.Add(card);

            var saveDefinitionButton = new Button
            {
                Content = "Save",
                Background = Brush.Parse("#163E26"),
                BorderBrush = Brush.Parse("#A98243"),
                VerticalAlignment = VerticalAlignment.Bottom,
                Margin = new Thickness(8, 0, 0, 0),
                IsVisible = !_isReadOnly && (state.DefinitionDirty || sourceBelongsToOtherUnit)
            };

            var header = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("70,70,248,198,*,Auto,Auto"),
                Width = 786,
                HorizontalAlignment = HorizontalAlignment.Stretch
            };
            header.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            header.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            void AddHeader(string text, int column)
            {
                var block = new TextBlock
                {
                    Text = text,
                    FontWeight = FontWeight.Bold,
                    Margin = new Thickness(0, 0, 8, 2)
                };
                Grid.SetRow(block, 0);
                Grid.SetColumn(block, column);
                header.Children.Add(block);
            }

            AddHeader("Row", 0);
            AddHeader("Column", 1);
            AddHeader("Command", 2);
            AddHeader("Type", 3);

            if (_isReadOnly)
            {
                var rowValue = ProtoUnitCommandFieldFactory.CreateTextBox(state.Row, 62, enabled: false);
                rowValue.Margin = new Thickness(0, 0, 8, 0);
                Grid.SetRow(rowValue, 1);
                Grid.SetColumn(rowValue, 0);
                header.Children.Add(rowValue);

                var columnValue = ProtoUnitCommandFieldFactory.CreateTextBox(state.Column, 62, enabled: false);
                columnValue.Margin = new Thickness(0, 0, 8, 0);
                Grid.SetRow(columnValue, 1);
                Grid.SetColumn(columnValue, 1);
                header.Children.Add(columnValue);
            }
            else
            {
                var rowCb = CreateTransformPositionCombo(state.Row, TrainTechRowOptions, definitionEditorEnabled);
                rowCb.Margin = new Thickness(0, 0, 8, 0);
                rowCb.SelectionChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;
                    if (!await CheckStartLocalMod())
                        return;
                    state.Row = rowCb.SelectedItem as string ?? rowCb.SelectedValue as string ?? "0";
                    MarkDirty();
                };
                Grid.SetRow(rowCb, 1);
                Grid.SetColumn(rowCb, 0);
                header.Children.Add(rowCb);

                var columnCb = CreateTransformPositionCombo(state.Column, TrainTechColumnOptions, definitionEditorEnabled);
                columnCb.Margin = new Thickness(0, 0, 8, 0);
                columnCb.SelectionChanged += async (_, _) =>
                {
                    if (_isPopulating)
                        return;
                    if (!await CheckStartLocalMod())
                        return;
                    state.Column = columnCb.SelectedItem as string ?? columnCb.SelectedValue as string ?? "0";
                    MarkDirty();
                };
                Grid.SetRow(columnCb, 1);
                Grid.SetColumn(columnCb, 1);
                header.Children.Add(columnCb);
            }

            Control commandNameEditorControl;
            TextBox? commandNameTextBox = null;
            AutoCompleteBox? commandNameAutoComplete = null;
            if (!_isReadOnly && string.IsNullOrWhiteSpace(state.SourceCommandName))
            {
                var suggestions = GetTransformCommandNames(state.IsMultiple)
                    .Where(name => !_transformCommandAssignments.Any(other =>
                        !ReferenceEquals(other, state) && other.CommandName.Equals(name, StringComparison.OrdinalIgnoreCase)))
                    .ToList();
                commandNameAutoComplete = new AutoCompleteBox
                {
                    Text = state.CommandName,
                    ItemsSource = suggestions,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    Width = 240,
                    MaxWidth = 240,
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                EditorTextFieldStyle.ConfigureSelector(commandNameAutoComplete);
                commandNameAutoComplete.Width = 240;
                commandNameAutoComplete.MaxWidth = 240;
                EditorFieldAppearance.ApplyStandard(commandNameAutoComplete);
                EditorAutoCompleteService.EnableDropdown(commandNameAutoComplete, () => _isPopulating, selectAllOnFirstClick: false);
                commandNameAutoComplete.TextChanged += (_, _) =>
                {
                    if (_isPopulating) return;
                    var nextName = commandNameAutoComplete.Text?.Trim() ?? "";
                    if (state.CommandName.Equals(nextName, StringComparison.Ordinal)) return;
                    state.CommandName = nextName;
                    definition.Name = nextName;
                    transformDefinition.Command = nextName;
                    if (!state.IsMultiple)
                        RefreshTransformCommandStatsReference();
                    MarkTransformDefinitionDirty(state, saveDefinitionButton);
                    RenderTransformTabs();
                };
                commandNameAutoComplete.SelectionChanged += (_, _) =>
                {
                    if (_isPopulating || commandNameAutoComplete.SelectedItem is not string selected) return;
                    Dispatcher.UIThread.Post(async () =>
                    {
                        if (_transformCommandAssignments.Any(other =>
                            !ReferenceEquals(other, state) && other.CommandName.Equals(selected, StringComparison.OrdinalIgnoreCase)))
                            return;
                        state.CommandName = selected;
                        state.SourceCommandName = selected;
                        state.SourceIsBuiltIn = _builtInProtoUnitCommandNames.Contains(selected) && !IsCustomProtoUnitCommand(selected);
                        state.SnapshotCommandName = "";
                        state.LoadedCommandSnapshot = null;
                        state.LoadedTransformSnapshot = null;
                        state.Definition = null;
                        state.TransformDefinition = LoadProtoUnitTransformDefinition(selected);
                        state.StringTexts = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                        state.DefinitionDirty = false;
                        if (!state.IsMultiple)
                            RefreshTransformCommandStatsReference();
                        RenderTransformTabs();
                        await RenderTransformAssignmentAsync(state);
                    }, DispatcherPriority.Background);
                };
                commandNameEditorControl = commandNameAutoComplete;
            }
            else
            {
                commandNameTextBox = ProtoUnitCommandFieldFactory.CreateTextBox(state.CommandName, 240, !_isReadOnly);
                commandNameTextBox.TextChanged += (_, _) =>
                {
                    if (_isReadOnly || _isPopulating) return;
                    var nextName = commandNameTextBox.Text?.Trim() ?? "";
                    if (state.CommandName.Equals(nextName, StringComparison.Ordinal)) return;
                    state.CommandName = nextName;
                    definition.Name = nextName;
                    transformDefinition.Command = nextName;
                    if (!state.IsMultiple)
                        RefreshTransformCommandStatsReference();
                    MarkTransformDefinitionDirty(state, saveDefinitionButton);
                    RenderTransformTabs();
                };
                commandNameEditorControl = commandNameTextBox;
            }
            Grid.SetRow(commandNameEditorControl, 1);
            Grid.SetColumn(commandNameEditorControl, 2);
            header.Children.Add(commandNameEditorControl);

            Control typeEditor;
            if (!_isReadOnly && definitionEditorEnabled && !state.IsMultiple)
            {
                var typeCombo = new ComboBox
                {
                    ItemsSource = new[] { "Transform (Unique)", "Transform (Multiple)" },
                    SelectedItem = "Transform (Unique)",
                    Width = 190,
                    MaxWidth = 190,
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                typeCombo.SelectionChanged += (_, _) =>
                {
                    if (_isPopulating || typeCombo.SelectedItem as string != "Transform (Multiple)")
                        return;

                    state.IsMultiple = true;
                    ProtoUnitCommandTransformRules.ApplyModeDefaults(definition.Flags, ProtoUnitCommandTransformKind.Multiple);
                    MarkTransformDefinitionDirty(state, saveDefinitionButton);
                    MarkDirty();
                    RefreshTransformCommandStatsReference();
                    _ = RenderTransformAssignmentAsync(state);
                };
                typeEditor = typeCombo;
            }
            else
            {
                typeEditor = ProtoUnitCommandFieldFactory.CreateTextBox(
                    state.IsMultiple ? "Transform (Multiple)" : "Transform (Unique)", 190, enabled: false);
            }
            typeEditor.Margin = new Thickness(0, 0, 8, 0);
            Grid.SetRow(typeEditor, 1);
            Grid.SetColumn(typeEditor, 3);
            header.Children.Add(typeEditor);

            Grid.SetRow(saveDefinitionButton, 0);
            Grid.SetRowSpan(saveDefinitionButton, 2);
            Grid.SetColumn(saveDefinitionButton, 5);
            saveDefinitionButton.VerticalAlignment = VerticalAlignment.Top;
            header.Children.Add(saveDefinitionButton);

            if (!_isReadOnly)
            {
                var remove = new Button
                {
                    Content = "Remove",
                    Background = Brush.Parse("#7A1F1C"),
            BorderBrush = Brush.Parse("#B55640"),
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(8, 0, 0, 0)
                };
                remove.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;

                    // Unsaved drafts are not shared commands yet. Removing one only discards the draft.
                    var existingSourceName = state.SourceCommandName.Trim();
                    var existingCustom = !string.IsNullOrWhiteSpace(existingSourceName) &&
                                         IsCustomProtoUnitCommand(existingSourceName);
                    var choice = ProtoUnitTransformRemovalChoice.OnlyThisUnit; // Original/Data.bar: detach from this ProtoUnit only.
                    if (existingCustom)
                    {
                        choice = await ProtoUnitTransformRemovalDialog.ShowAsync(this, existingSourceName);
                        if (choice == ProtoUnitTransformRemovalChoice.Cancel)
                            return;
                    }

                    var oldIndex = _transformCommandAssignments.IndexOf(state);
                    _transformCommandAssignments.Remove(state);
                    RefreshTransformCommandStatsReference();
                    if (ReferenceEquals(activeTransformState, state))
                        activeTransformState = _transformCommandAssignments.FirstOrDefault();

                    if (string.IsNullOrWhiteSpace(existingSourceName))
                    {
                        RenderTransformTabs();
                        transformCardHost.Children.Clear();
                        if (activeTransformState != null)
                            await RenderTransformAssignmentAsync(activeTransformState);
                        RefreshTransformAddArea();
                        return;
                    }

                    if (!await PersistTransformAssignmentsNowAsync())
                    {
                        _transformCommandAssignments.Insert(Math.Clamp(oldIndex, 0, _transformCommandAssignments.Count), state);
                        activeTransformState = state;
                        RenderTransformTabs();
                        await RenderTransformAssignmentAsync(state);
                        return;
                    }

                    if (choice == ProtoUnitTransformRemovalChoice.RemoveTotally && existingCustom)
                    {
                        var deleted = await DeleteProtoUnitCommandCoreAsync(existingSourceName, currentTransformUnitName);
                        if (!deleted)
                        {
                            await new Prompt(
                                PromptType.Error,
                                "Command kept",
                                $"'{existingSourceName}' was removed from this ProtoUnit, but its command definition could not be deleted because it is still used or referenced elsewhere.").ShowDialog(this);
                        }
                    }

                    RenderTransformTabs();
                    transformCardHost.Children.Clear();
                    if (activeTransformState != null)
                        await RenderTransformAssignmentAsync(activeTransformState);
                    RefreshTransformAddArea();
                };
                Grid.SetRow(remove, 0);
                Grid.SetRowSpan(remove, 2);
                Grid.SetColumn(remove, 6);
                header.Children.Add(remove);
            }
            content.Children.Add(header);

            var details = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("115,240,Auto,240,*"),
                ColumnSpacing = 8,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            for (var rowIndex = 0; rowIndex < 5; rowIndex++)
                details.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            void AddLabel(string text, int row, int column)
            {
                var label = new TextBlock
                {
                    Text = text,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(0, 2, 8, 2)
                };
                Grid.SetRow(label, row);
                Grid.SetColumn(label, column);
                details.Children.Add(label);
            }

            void AddEditor(Control editor, int row, int column, int span = 1)
            {
                editor.Margin = new Thickness(0, 2, 0, 2);
                Grid.SetRow(editor, row);
                Grid.SetColumn(editor, column);
                if (span > 1)
                    Grid.SetColumnSpan(editor, span);
                details.Children.Add(editor);
            }

            AddLabel("Display Name", 0, 0);
            var displayNameEditor = ProtoUnitCommandFieldFactory.CreateTextBox(state.StringTexts.GetValueOrDefault("displaynameid", ""), 240, definitionEditorEnabled);
            displayNameEditor.TextChanged += (_, _) =>
            {
                if (!definitionEditorEnabled || _isPopulating) return;
                var next = displayNameEditor.Text ?? "";
                if (state.StringTexts.GetValueOrDefault("displaynameid", "").Equals(next, StringComparison.Ordinal)) return;
                state.StringTexts["displaynameid"] = next;
                MarkTransformDefinitionDirty(state, saveDefinitionButton);
            };
            AddEditor(displayNameEditor, 0, 1);

            AddLabel("Icon", 0, 2);
            var iconEditor = new AssetPathEditor { Width = 240, IsEnabled = definitionEditorEnabled };
            iconEditor.Configure(definition.Values.GetValueOrDefault("icon", ""), context.IconPaths, value =>
            {
                if (!definition.Values.GetValueOrDefault("icon", "").Equals(value, StringComparison.Ordinal))
                {
                    definition.Values["icon"] = value;
                    MarkTransformDefinitionDirty(state, saveDefinitionButton);
                }
                return Task.CompletedTask;
            });
            AddEditor(iconEditor, 0, 3);

            AddLabel("Rollover", 1, 0);
            var rolloverEditor = ProtoUnitCommandFieldFactory.CreateTextBox(state.StringTexts.GetValueOrDefault("rollovertextid", ""), 603, definitionEditorEnabled);
            rolloverEditor.MinHeight = 54;
            rolloverEditor.AcceptsReturn = true;
            rolloverEditor.TextWrapping = TextWrapping.Wrap;
            rolloverEditor.TextChanged += (_, _) =>
            {
                if (!definitionEditorEnabled || _isPopulating) return;
                var next = rolloverEditor.Text ?? "";
                if (state.StringTexts.GetValueOrDefault("rollovertextid", "").Equals(next, StringComparison.Ordinal)) return;
                state.StringTexts["rollovertextid"] = next;
                MarkTransformDefinitionDirty(state, saveDefinitionButton);
            };
            AddEditor(rolloverEditor, 1, 1, 3);

            // The Transform-specific rows are shared with the standalone ProtoUnit Command editor.
            // The inline host keeps ownership of card actions/persistence and locks the source ProtoUnit.
            content.Children.Add(details);
            var sharedTransformEditor = new ProtoUnitCommandTransformEditor(
                transformDefinition,
                definition.Values,
                context.ProtoUnitNames,
                context.TechNames,
                context.PowerNames,
                editable: definitionEditorEnabled,
                lockFrom: true,
                changed: () => MarkTransformDefinitionDirty(state, saveDefinitionButton),
                isBusy: () => _isPopulating);
            content.Children.Add(sharedTransformEditor);

            var fromEditor = sharedTransformEditor.FromEditor;
            var toEditor = sharedTransformEditor.ToEditor;
            var prereqTechEditor = sharedTransformEditor.PrereqTechEditor;
            var associatedTechEditor = sharedTransformEditor.AssociatedTechEditor;
            fromEditor.BorderBrush = sourceBelongsToOtherUnit ? Brush.Parse("#d64545") : Brush.Parse("#4C4031");

            var sharedFlagsEditor = new ProtoUnitCommandFlagsEditor(
                definition.Flags,
                editable: definitionEditorEnabled,
                transformKind: () => state.IsMultiple ? ProtoUnitCommandTransformKind.Multiple : ProtoUnitCommandTransformKind.Unique,
                changed: () => MarkTransformDefinitionDirty(state, saveDefinitionButton),
                isBusy: () => _isPopulating);
            content.Children.Add(sharedFlagsEditor);

            async Task<bool> SaveTransformDefinitionAsync()
            {
                definition.Name = commandNameAutoComplete?.Text?.Trim() ?? commandNameTextBox?.Text?.Trim() ?? "";
                state.CommandName = definition.Name;
                transformDefinition.Command = state.CommandName;
                if (!state.IsMultiple)
                    RefreshTransformCommandStatsReference();

                if (sourceBelongsToOtherUnit && state.CommandName.Equals(state.SourceCommandName, StringComparison.OrdinalIgnoreCase))
                {
                    await new Prompt(
                        PromptType.Error,
                        "Transform command belongs to another unit",
                        $"'{state.SourceCommandName}' transforms '{sourceTransformUnitName}', not '{currentTransformUnitName}'. Change the Command name and save to create a custom copy for this ProtoUnit.").ShowDialog(this);
                    return false;
                }

                // Inline Transform commands always belong to the ProtoUnit being edited.
                transformDefinition.From = currentTransformUnitName;
                transformDefinition.To = toEditor.Text?.Trim() ?? "";
                transformDefinition.Tech = prereqTechEditor.Text?.Trim() ?? "";
                definition.Values["associatedtech"] = associatedTechEditor.Text?.Trim() ?? "";

                var validation = sharedTransformEditor.ValidateRequired(currentTransformUnitName);
                if (string.IsNullOrWhiteSpace(state.CommandName) || !validation.IsValid)
                {
                    var message = !validation.FromValid && !string.IsNullOrWhiteSpace(transformDefinition.From) &&
                                  !transformDefinition.From.Equals(currentTransformUnitName, StringComparison.OrdinalIgnoreCase)
                        ? $"This Transform command belongs to '{transformDefinition.From}', but the edited ProtoUnit is '{currentTransformUnitName}'. Change Transform to '{currentTransformUnitName}' and use a new command name to create a custom copy."
                        : "Command Name, Transform, To, Prereq Tech and Associated Tech are required and must use valid existing entries.";
                    await new Prompt(PromptType.Error, "Transform command", message).ShowDialog(this);
                    return false;
                }

                if (!await SaveInlineTransformCommandDefinitionAsync(state))
                    return false;

                saveDefinitionButton.IsVisible = false;
                MarkDirty();
                RenderTransformTabs();
                RefreshTransformAddArea();
                _statusMessage.Text = "Transform command saved.";
                await RenderTransformAssignmentAsync(state);
                _ = Task.Delay(2000).ContinueWith(_ => Dispatcher.UIThread.Post(() => _statusMessage.Text = ""));
                return true;
            }

            saveDefinitionButton.Click += async (_, _) => await SaveTransformDefinitionAsync();

            if (commandNameAutoComplete != null)
            {
                commandNameAutoComplete.KeyDown += async (_, e) =>
                {
                    if (e.Key != Key.Enter || commandNameAutoComplete.SelectedItem != null)
                        return;
                    e.Handled = true;
                    await SaveTransformDefinitionAsync();
                };
            }
            if (commandNameTextBox != null)
            {
                commandNameTextBox.KeyDown += async (_, e) =>
                {
                    if (e.Key != Key.Enter)
                        return;
                    e.Handled = true;
                    await SaveTransformDefinitionAsync();
                };
            }

            _saveActiveTransformCommandBeforeUnitSaveAsync = async () =>
            {
                if (!ReferenceEquals(activeTransformState, state))
                    return true;
                if (!state.DefinitionDirty && !sourceBelongsToOtherUnit)
                    return true;
                return await SaveTransformDefinitionAsync();
            };
        }

        async Task AddNewMultipleTransformTabAsync()
        {
            var definition = new ProtoUnitCommandDefinition();
            ProtoUnitCommandTransformRules.ApplyModeDefaults(definition.Flags, ProtoUnitCommandTransformKind.Multiple);
            var state = new TransformCommandAssignmentState
            {
                IsMultiple = true,
                Row = "0",
                Column = "0",
                Definition = definition,
                TransformDefinition = new ProtoUnitTransformDefinition { From = currentTransformUnitName },
                DefinitionDirty = true
            };
            _transformCommandAssignments.Add(state);
            RefreshTransformCommandStatsReference();
            activeTransformState = state;
            MarkDirty();
            RenderTransformTabs();
            await RenderTransformAssignmentAsync(state);
            RefreshTransformAddArea();
        }

        void RenderTransformTabs()
        {
            transformTabs.Children.Clear();
            if (activeTransformState == null)
                _saveActiveTransformCommandBeforeUnitSaveAsync = null;
            foreach (var state in _transformCommandAssignments)
            {
                var label = string.IsNullOrWhiteSpace(state.CommandName) ? "New Transform" : state.CommandName;
                var tab = new Button
                {
                    Content = label,
                    Margin = new Thickness(0, 0, 6, 6),
                    Padding = new Thickness(10, 4),
                    Background = ReferenceEquals(state, activeTransformState) ? Brush.Parse("#28466f") : Brush.Parse("#2b2b2b")
                };
                tab.Click += (_, _) => _ = RenderTransformAssignmentAsync(state);
                transformTabs.Children.Add(tab);
            }

            if (!_isReadOnly && !_transformCommandAssignments.Any(state => !state.IsMultiple))
            {
                var add = new Button
                {
                    Content = "Add Transform Command",
                    Classes = { "add-item" },
                    Margin = new Thickness(0, 0, 6, 6),
                    Padding = new Thickness(10, 4),
                    HorizontalAlignment = HorizontalAlignment.Left
                };
                add.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;
                    if (_transformCommandAssignments.Any(state => state.IsMultiple))
                        await AddNewMultipleTransformTabAsync();
                    else
                        ShowTransformTypePicker();
                };
                transformTabs.Children.Add(add);
            }
        }

        async Task CommitTransformSelection(bool multiple, AutoCompleteBox selector, ComboBox rowPicker, ComboBox columnPicker)
        {
            var input = selector.Text?.Trim() ?? "";
            var validNames = GetTransformCommandNames(multiple);
            var match = validNames.FirstOrDefault(name => name.Equals(input, StringComparison.OrdinalIgnoreCase));
            if (string.IsNullOrWhiteSpace(match))
                return;
            if (_transformCommandAssignments.Any(state => state.CommandName.Equals(match, StringComparison.OrdinalIgnoreCase)))
                return;
            if (!multiple && _transformCommandAssignments.Any(state => !state.IsMultiple))
                return;
            if (!await CheckStartLocalMod())
                return;

            var state = new TransformCommandAssignmentState
            {
                CommandName = match,
                SourceCommandName = match,
                SourceIsBuiltIn = _builtInProtoUnitCommandNames.Contains(match) && !IsCustomProtoUnitCommand(match),
                IsMultiple = multiple,
                Row = rowPicker.SelectedItem as string ?? rowPicker.SelectedValue as string ?? "0",
                Column = columnPicker.SelectedItem as string ?? columnPicker.SelectedValue as string ?? "0",
                TransformDefinition = LoadProtoUnitTransformDefinition(match)
            };
            _transformCommandAssignments.Add(state);
            RefreshTransformCommandStatsReference();
            activeTransformState = state;
            MarkDirty();
            RenderTransformTabs();
            await RenderTransformAssignmentAsync(state);
            RefreshTransformAddArea();
        }

        void ShowTransformCommandPicker(bool multiple)
        {
            transformAddHost.Children.Clear();
            var validNames = GetTransformCommandNames(multiple)
                .Where(name => !_transformCommandAssignments.Any(state => state.CommandName.Equals(name, StringComparison.OrdinalIgnoreCase)))
                .ToList();

            var panel = new StackPanel { Spacing = 2, HorizontalAlignment = HorizontalAlignment.Left };
            var header = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("70,70,248,Auto,Auto"),
                HorizontalAlignment = HorizontalAlignment.Left
            };
            header.Children.Add(new TextBlock { Text = "Row", FontWeight = FontWeight.Bold });
            var columnHeader = new TextBlock { Text = "Column", FontWeight = FontWeight.Bold };
            Grid.SetColumn(columnHeader, 1);
            header.Children.Add(columnHeader);
            var commandHeader = new TextBlock { Text = "Command", FontWeight = FontWeight.Bold };
            Grid.SetColumn(commandHeader, 2);
            header.Children.Add(commandHeader);
            panel.Children.Add(header);

            var row = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("70,70,248,Auto,Auto"),
                HorizontalAlignment = HorizontalAlignment.Left
            };
            var rowPicker = CreateTransformPositionCombo("0", TrainTechRowOptions);
            rowPicker.Margin = new Thickness(0, 0, 8, 0);
            Grid.SetColumn(rowPicker, 0);
            row.Children.Add(rowPicker);
            var columnPicker = CreateTransformPositionCombo("0", TrainTechColumnOptions);
            columnPicker.Margin = new Thickness(0, 0, 8, 0);
            Grid.SetColumn(columnPicker, 1);
            row.Children.Add(columnPicker);

            var selector = new AutoCompleteBox
            {
                FilterMode = AutoCompleteFilterMode.Contains,
                ItemsSource = validNames,
                PlaceholderText = multiple ? "Transform (Multiple) command" : "Transform (Unique) command"
            };
            EditorTextFieldStyle.ConfigureSelector(selector);
            EditorFieldAppearance.ApplyStandard(selector);
            selector.Width = 240;
            selector.MaxWidth = 240;
            selector.Margin = new Thickness(0, 0, 8, 0);
            EditorAutoCompleteService.EnableDropdown(selector, () => _isPopulating, selectAllOnFirstClick: false);
            Grid.SetColumn(selector, 2);
            row.Children.Add(selector);

            var save = new Button
            {
                Content = "Save",
                Background = Brush.Parse("#163E26"),
                BorderBrush = Brush.Parse("#A98243"),
                Padding = new Thickness(8, 4),
                Margin = new Thickness(0, 0, 6, 0),
                IsVisible = false
            };
            Grid.SetColumn(save, 3);
            row.Children.Add(save);

            var cancel = new Button { Content = "Cancel", Padding = new Thickness(8, 4) };
            cancel.Click += (_, _) => RefreshTransformAddArea();
            Grid.SetColumn(cancel, 4);
            row.Children.Add(cancel);
            panel.Children.Add(row);
            transformAddHost.Children.Add(panel);

            selector.TextChanged += (_, _) =>
            {
                save.IsVisible = !string.IsNullOrWhiteSpace(selector.Text);
            };

            selector.SelectionChanged += (_, _) =>
            {
                if (selector.SelectedItem is string selected)
                {
                    selector.Text = selected;
                    Dispatcher.UIThread.Post(
                        () => _ = CommitTransformSelection(multiple, selector, rowPicker, columnPicker),
                        DispatcherPriority.Background);
                }
            };

            async Task SaveTransformPickerAsync()
            {
                var input = selector.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(input))
                    return;

                var existingMatch = validNames.FirstOrDefault(name => name.Equals(input, StringComparison.OrdinalIgnoreCase));
                if (!string.IsNullOrWhiteSpace(existingMatch))
                {
                    await CommitTransformSelection(multiple, selector, rowPicker, columnPicker);
                    return;
                }

                EnsureProtoUnitCommandCatalogLoaded(force: true);
                if (!ProtoUnitCommandNamePolicy.IsAvailable(input, _protoUnitCommandCatalog.Keys))
                {
                    await new Prompt(
                        PromptType.Error,
                        "Command already exists",
                        $"A command named '{input}' already exists but is not a compatible {(multiple ? "Transform (Multiple)" : "Transform (Unique)")} command.").ShowDialog(this);
                    return;
                }

                if (!await CheckStartLocalMod())
                    return;

                var definition = new ProtoUnitCommandDefinition { Name = input };
                if (multiple)
                    ProtoUnitCommandTransformRules.ApplyModeDefaults(definition.Flags, ProtoUnitCommandTransformKind.Multiple);
                else
                    ProtoUnitCommandTransformRules.ApplyModeDefaults(definition.Flags, ProtoUnitCommandTransformKind.Unique);

                var state = new TransformCommandAssignmentState
                {
                    CommandName = input,
                    SourceCommandName = "",
                    SourceIsBuiltIn = false,
                    IsMultiple = multiple,
                    Row = rowPicker.SelectedItem as string ?? rowPicker.SelectedValue as string ?? "0",
                    Column = columnPicker.SelectedItem as string ?? columnPicker.SelectedValue as string ?? "0",
                    Definition = definition,
                    TransformDefinition = new ProtoUnitTransformDefinition
                    {
                        Command = input,
                        From = currentTransformUnitName
                    },
                    DefinitionDirty = true
                };
                _transformCommandAssignments.Add(state);
                RefreshTransformCommandStatsReference();
                activeTransformState = state;
                MarkDirty();
                transformAddHost.Children.Clear();
                RenderTransformTabs();
                await RenderTransformAssignmentAsync(state);
            }

            save.Click += async (_, _) => await SaveTransformPickerAsync();
            selector.KeyDown += async (_, e) =>
            {
                if (e.Key != Key.Enter || selector.SelectedItem != null)
                    return;
                e.Handled = true;
                await SaveTransformPickerAsync();
            };
        }

        void ShowTransformTypePicker()
        {
            transformAddHost.Children.Clear();
            var row = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("Auto,200,Auto"),
                ColumnSpacing = 8,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            row.Children.Add(new TextBlock { Text = "Type", VerticalAlignment = VerticalAlignment.Center });
            var typePicker = new ComboBox
            {
                ItemsSource = new[] { "Transform (Unique)", "Transform (Multiple)" },
                Width = 200,
                HorizontalAlignment = HorizontalAlignment.Left
            };
            Grid.SetColumn(typePicker, 1);
            row.Children.Add(typePicker);
            var cancel = new Button { Content = "Cancel", Padding = new Thickness(8, 4) };
            cancel.Click += (_, _) => RefreshTransformAddArea();
            Grid.SetColumn(cancel, 2);
            row.Children.Add(cancel);
            transformAddHost.Children.Add(row);

            typePicker.SelectionChanged += (_, _) =>
            {
                if (typePicker.SelectedItem is not string type)
                    return;
                ShowTransformCommandPicker(type.Equals("Transform (Multiple)", StringComparison.OrdinalIgnoreCase));
            };
        }

        void RefreshTransformAddArea()
        {
            transformAddHost.Children.Clear();
            RenderTransformTabs();
        }

        var initialTransformEntry = ProtoXmlHandler.GetTransformCommandEntry(unit);
        if (initialTransformEntry != null && !string.IsNullOrWhiteSpace(initialTransformEntry.Value))
        {
            var matchingCommandEntry = transformCommandEntries.FirstOrDefault(entry =>
                entry.Value.Equals(initialTransformEntry.Value, StringComparison.OrdinalIgnoreCase));
            var uniqueState = new TransformCommandAssignmentState
            {
                CommandName = initialTransformEntry.Value,
                SourceCommandName = initialTransformEntry.Value,
                SourceIsBuiltIn = _builtInProtoUnitCommandNames.Contains(initialTransformEntry.Value) && !IsCustomProtoUnitCommand(initialTransformEntry.Value),
                IsMultiple = false,
                Row = string.IsNullOrWhiteSpace(matchingCommandEntry?.Row) ? "0" : matchingCommandEntry.Row,
                Column = string.IsNullOrWhiteSpace(matchingCommandEntry?.Column) ? "0" : matchingCommandEntry.Column,
                MergeMode = matchingCommandEntry?.MergeMode ?? "",
                TransformDefinition = LoadProtoUnitTransformDefinition(initialTransformEntry.Value)
            };
            _transformCommandAssignments.Add(uniqueState);
        }

        foreach (var entry in transformCommandEntries)
        {
            if (_transformCommandAssignments.Any(state => state.CommandName.Equals(entry.Value, StringComparison.OrdinalIgnoreCase)))
                continue;
            var isMultiple = IsTransformMultipleCommand(entry.Value);
            if (!isMultiple && _transformCommandAssignments.Any(state => !state.IsMultiple))
                continue;
            _transformCommandAssignments.Add(new TransformCommandAssignmentState
            {
                CommandName = entry.Value,
                SourceCommandName = entry.Value,
                SourceIsBuiltIn = _builtInProtoUnitCommandNames.Contains(entry.Value) && !IsCustomProtoUnitCommand(entry.Value),
                IsMultiple = isMultiple,
                Row = string.IsNullOrWhiteSpace(entry.Row) ? "0" : entry.Row,
                Column = string.IsNullOrWhiteSpace(entry.Column) ? "0" : entry.Column,
                MergeMode = entry.MergeMode,
                TransformDefinition = LoadProtoUnitTransformDefinition(entry.Value)
            });
        }

        activeTransformState = _transformCommandAssignments.FirstOrDefault();
        RenderTransformTabs();
        if (activeTransformState != null)
            _ = RenderTransformAssignmentAsync(activeTransformState);
        RefreshTransformAddArea();

        _validateTransformAssignmentsBeforeUnitSaveAsync = async () =>
        {
            foreach (var state in _transformCommandAssignments)
            {
                if (state.DefinitionDirty)
                {
                    activeTransformState = state;
                    await RenderTransformAssignmentAsync(state);
                    await new Prompt(
                        PromptType.Error,
                        "Unsaved Transform command",
                        $"Save the Transform command '{state.CommandName}' with the green Save button before saving the ProtoUnit.").ShowDialog(this);
                    return false;
                }

                var transform = state.TransformDefinition ?? LoadProtoUnitTransformDefinition(state.CommandName);
                if (transform == null || string.IsNullOrWhiteSpace(transform.From) ||
                    transform.From.Equals(currentTransformUnitName, StringComparison.OrdinalIgnoreCase))
                    continue;

                activeTransformState = state;
                await RenderTransformAssignmentAsync(state);
                await new Prompt(
                    PromptType.Error,
                    "Transform command",
                    $"'{state.CommandName}' transforms '{transform.From}', but this ProtoUnit is '{currentTransformUnitName}'. Change the Transform field to '{currentTransformUnitName}' and save the command under a new name before saving the ProtoUnit.").ShowDialog(this);
                return false;
            }
            return true;
        };


        _activeEditorPanel = _actionsEditorPanel;
        _activeEditorTabIndex = 1;
        var tacticsGrid = new Grid { ColumnDefinitions = new ColumnDefinitions("Auto,380,Auto,*") };
        tacticsGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

        var tacticsLabel = new TextBlock
        {
            Text = "Tactics",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 4, 8, 4)
        };
        Grid.SetColumn(tacticsLabel, 0);
        Grid.SetRow(tacticsLabel, 0);
        tacticsGrid.Children.Add(tacticsLabel);

        string initialTactics = ProtoXmlHandler.GetSimpleField(unit, "tactics") ?? "";
        if (!string.IsNullOrWhiteSpace(initialTactics) &&
            !initialTactics.EndsWith(".tactics", StringComparison.OrdinalIgnoreCase))
        {
            initialTactics += ".tactics";
        }
        var availableTactics = GetAvailableTacticsNames();
        if (!string.IsNullOrWhiteSpace(initialTactics) &&
            !availableTactics.Contains(initialTactics.Trim(), StringComparer.OrdinalIgnoreCase))
        {
            availableTactics.Add(initialTactics.Trim());
            availableTactics = availableTactics.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
        }

        var tacticsControl = new AutoCompleteBox
        {
            Text = initialTactics,
            FilterMode = AutoCompleteFilterMode.Contains,
            IsEnabled = !_isReadOnly,
            Margin = new Thickness(0, 4, 0, 4)
        };
        EditorTextFieldStyle.ConfigureSelector(tacticsControl);
        ConfigureStrictSuggestionAutoComplete(tacticsControl, availableTactics, initialTactics);

        Grid.SetColumn(tacticsControl, 1);
        Grid.SetRow(tacticsControl, 0);
        tacticsGrid.Children.Add(tacticsControl);

        var manageTacticsIcon = new Grid
        {
            Width = 22,
            Height = 22
        };
        manageTacticsIcon.Children.Add(new TextBlock
        {
            Text = "✎",
            FontSize = 15,
            HorizontalAlignment = HorizontalAlignment.Left,
            VerticalAlignment = VerticalAlignment.Top,
            Margin = new Thickness(0, -2, 0, 0),
            RenderTransform = new ScaleTransform(-1, 1),
            RenderTransformOrigin = RelativePoint.Center
        });
        manageTacticsIcon.Children.Add(new TextBlock
        {
            Text = "⚙",
            FontSize = 13,
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment = VerticalAlignment.Bottom,
            Margin = new Thickness(0, 0, -1, -1)
        });

        var manageTacticsButton = new Button
        {
            Content = manageTacticsIcon,
            Width = 36,
            Height = 32,
            Padding = new Thickness(6),
            Margin = new Thickness(6, 4, 0, 4),
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center,
            IsEnabled = !_isReadOnly,
            IsVisible = _unitTabs.SelectedIndex == 1
        };
        ToolTip.SetTip(manageTacticsButton, "Manage tactics files");
        manageTacticsButton.Click += async (_, _) => await OpenTacticsManagerAsync();
        Grid.SetColumn(manageTacticsButton, 2);
        Grid.SetRow(manageTacticsButton, 0);
        tacticsGrid.Children.Add(manageTacticsButton);

        _fieldControls["tactics"] = tacticsControl;
        if (_protoActionHostAdapter.Context.ShowsProtoUnitChrome)
        {
            AddSectionHeader("Tactics");
            _activeEditorPanel.Children.Add(tacticsGrid);
            if (!string.IsNullOrWhiteSpace(_currentUnitTacticsLoadDiagnostic))
            {
                _activeEditorPanel.Children.Add(new Border
                {
                    BorderBrush = Brush.Parse("#d32f2f"),
                    BorderThickness = new Thickness(1),
                    CornerRadius = new CornerRadius(3),
                    Background = Brush.Parse("#2b1111"),
                    Padding = new Thickness(10, 8),
                    Margin = new Thickness(0, 2, 0, 8),
                    Child = new TextBlock
                    {
                        Text = _currentUnitTacticsLoadDiagnostic,
                        Foreground = Brush.Parse("#ffb3b3"),
                        TextWrapping = TextWrapping.Wrap,
                        MaxWidth = 760,
                        HorizontalAlignment = HorizontalAlignment.Left
                    }
                });
            }
        }

        var committedTacticsName = initialTactics.Trim();
        var committedTacticsActions = CloneProtoActionMap(LoadProtoActionsForTactics(committedTacticsName));
        var tacticsSelectionChangeInProgress = false;

        async Task CommitSelectedTacticsAsync(string selectedName)
        {
            var newTacticsName = selectedName.Trim();
            if (newTacticsName.Equals(committedTacticsName, StringComparison.OrdinalIgnoreCase) ||
                tacticsSelectionChangeInProgress || _isPopulating || _isReadOnly ||
                _modXmlRoot == null || string.IsNullOrWhiteSpace(_currentUnitName))
                return;

            tacticsSelectionChangeInProgress = true;
            try
            {
                tacticsControl.Text = newTacticsName;
                var proceed = await CheckStartLocalMod();
                if (!proceed || _modXmlRoot == null || string.IsNullOrWhiteSpace(_currentUnitName))
                {
                    tacticsControl.Text = committedTacticsName;
                    return;
                }

                // Persist the proto overlay while the old tactics metadata is still active.
                ApplyCurrentEdits();
                var currentUnit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, _currentUnitName);
                if (currentUnit == null)
                    return;

                ProtoXmlHandler.SetSimpleField(currentUnit, "tactics", newTacticsName);
                var newTacticsActions = CloneProtoActionMap(LoadProtoActionsForTactics(newTacticsName));
                MigrateProtoActionsForTacticsChange(currentUnit, committedTacticsActions, newTacticsActions);

                committedTacticsName = newTacticsName;
                committedTacticsActions = newTacticsActions;
                RefreshCurrentUnitProtoActionMetadata(currentUnit);
                MarkDirty();
                BuildEditorPanel(_currentUnitName, resetScroll: false);
            }
            finally
            {
                tacticsSelectionChangeInProgress = false;
            }
        }

        tacticsControl.SelectionChanged += async (_, _) =>
        {
            if (tacticsControl.SelectedItem is string selectedValue)
                await CommitSelectedTacticsAsync(selectedValue);
        };
        tacticsControl.LostFocus += async (_, _) =>
        {
            // An empty field explicitly means that the unit has no tactics file.
            // Commit it just like selecting a file so inherited actions are materialized
            // and all tactics markers/protections are cleared immediately.
            if (string.IsNullOrWhiteSpace(tacticsControl.Text) &&
                !string.IsNullOrWhiteSpace(committedTacticsName))
            {
                await CommitSelectedTacticsAsync("");
            }
        };

        Panel? tacticsModeParentPanel = null;
        StackPanel? tacticsModeActionsPanel = null;
        if (_protoActionHostAdapter.Context.ShowsTacticsDefinitionEditor && _activeEditorPanel != null)
        {
            tacticsModeParentPanel = _activeEditorPanel;
            tacticsModeActionsPanel = new StackPanel { Spacing = 10, Margin = new Thickness(0, 15, 0, 0) };
            var tacticsModeTacticPanel = new StackPanel { Spacing = 10, Margin = new Thickness(0, 15, 0, 0) };
            var modeTabs = new TabControl
            {
                ItemsSource = new[]
                {
                    new TabItem { Header = "Actions", Content = tacticsModeActionsPanel, Classes = { "compact-mode-tab" } },
                    new TabItem { Header = "Tactic", Content = tacticsModeTacticPanel, Classes = { "compact-mode-tab" } },
                },
                SelectedIndex = 0
            };
            tacticsModeParentPanel.Children.Add(modeTabs);

            _activeEditorPanel = tacticsModeTacticPanel;
            BuildBasicTacticEditor();
            _activeEditorPanel = tacticsModeActionsPanel;
        }
        else
        {
            AddSectionHeader("Proto Actions");
        }

        var actions = _protoActionHostAdapter.LoadActions(unit);
        var actionsContainer = new StackPanel { Spacing = 10 };
        (_activeEditorPanel ?? throw new InvalidOperationException("The action editor panel was not initialized.")).Children.Add(actionsContainer);
        var actionSelectorPanel = new WrapPanel { Orientation = Orientation.Horizontal };
        var actionDetailsPanel = new StackPanel { Spacing = 10 };
        actionsContainer.Children.Add(actionSelectorPanel);
        actionsContainer.Children.Add(actionDetailsPanel);
        ProtoActionWidgetState? selectedAction = null;
        var isBuildingInitialActions = true;
        ProtoActionWidgetState? pointerDragSource = null;
        ProtoActionWidgetState? pointerDragTarget = null;
        Button? pointerDragSourceButton = null;
        Point pointerDragStart = default;
        bool pointerDragActive = false;
        bool pointerDragHoldCancelled = false;
        bool pointerDragInsertAfter = false;
        IBrush? pointerDragTargetOriginalBorderBrush = null;
        Thickness pointerDragTargetOriginalBorderThickness = default;
        var pointerDragHoldTimer = new DispatcherTimer
        {
            Interval = TimeSpan.FromSeconds(0.1)
        };

        bool BlockForDuplicateSelectedActionName()
        {
            if (selectedAction?.HasDuplicateName != true)
                return false;

            selectedAction.NameAcb.Focus();
            return true;
        }

        void SelectAction(ProtoActionWidgetState? action)
        {
            if (!ReferenceEquals(action, selectedAction) && BlockForDuplicateSelectedActionName())
                return;

            selectedAction = action;
            _selectedProtoActionIndex = action == null ? 0 : Math.Max(0, _protoActionWidgets.IndexOf(action));
            RefreshActionSelector();
        }

        bool CanReorderAction(ProtoActionWidgetState actionState)
            => !_isReadOnly &&
               (_protoActionHostAdapter.Context.OwnsCompleteActionSequence || !actionState.IsCurrentTacticsAction);

        IReadOnlyList<ProtoActionWidgetState> GetLinkedReorderGroup(ProtoActionWidgetState actionState)
        {
            var primary = actionState;
            if (actionState.IsLinkedMaulAreaAction)
            {
                primary = _protoActionWidgets.FirstOrDefault(candidate =>
                              ReferenceEquals(candidate.MaulAreaCompanion, actionState))
                          ?? actionState;
            }
            else if (actionState.IsLinkedAbductDropAction)
            {
                primary = _protoActionWidgets.FirstOrDefault(candidate =>
                              ReferenceEquals(candidate.AbductDropCompanion, actionState))
                          ?? actionState;
            }

            var group = new HashSet<ProtoActionWidgetState>(ReferenceEqualityComparer.Instance)
            {
                primary
            };
            if (primary.MaulAreaCompanion != null)
                group.Add(primary.MaulAreaCompanion);
            if (primary.AbductDropCompanion != null)
                group.Add(primary.AbductDropCompanion);

            return _protoActionWidgets.Where(group.Contains).ToList();
        }

        bool CanReorderActionGroup(ProtoActionWidgetState actionState)
            => GetLinkedReorderGroup(actionState).All(CanReorderAction);

        void RestorePointerDragTargetVisual()
        {
            if (pointerDragTarget?.ActionSelectorButton is not Button targetButton)
                return;

            targetButton.BorderBrush = pointerDragTargetOriginalBorderBrush;
            targetButton.BorderThickness = pointerDragTargetOriginalBorderThickness;
        }

        void ResetPointerDragVisuals()
        {
            pointerDragHoldTimer.Stop();
            if (pointerDragSourceButton != null)
            {
                pointerDragSourceButton.Opacity = 1;
                pointerDragSourceButton.Cursor = null;
            }
            RestorePointerDragTargetVisual();
            pointerDragSource = null;
            pointerDragTarget = null;
            pointerDragSourceButton = null;
            pointerDragActive = false;
            pointerDragHoldCancelled = false;
            pointerDragInsertAfter = false;
            pointerDragTargetOriginalBorderBrush = null;
            pointerDragTargetOriginalBorderThickness = default;
        }

        void SetPointerDragTarget(ProtoActionWidgetState? target, bool insertAfter)
        {
            if (ReferenceEquals(target, pointerDragTarget) && insertAfter == pointerDragInsertAfter)
                return;

            RestorePointerDragTargetVisual();

            pointerDragTarget = target;
            pointerDragInsertAfter = insertAfter;
            if (pointerDragTarget?.ActionSelectorButton is Button targetButton &&
                !ReferenceEquals(pointerDragTarget, pointerDragSource))
            {
                pointerDragTargetOriginalBorderBrush = targetButton.BorderBrush;
                pointerDragTargetOriginalBorderThickness = targetButton.BorderThickness;
                targetButton.BorderBrush = Brush.Parse("#42d8e8");
                targetButton.BorderThickness = insertAfter
                    ? new Thickness(1, 1, 4, 1)
                    : new Thickness(4, 1, 1, 1);
            }
        }

        ProtoActionWidgetState? FindPointerDropTarget(Point position, out bool insertAfter)
        {
            insertAfter = false;
            var sourceGroup = pointerDragSource == null
                ? []
                : GetLinkedReorderGroup(pointerDragSource);
            foreach (var candidate in _protoActionWidgets)
            {
                // An inherited action cannot move in the ProtoUnit editor, but it is
                // still a valid anchor for a locally-owned action.
                if (sourceGroup.Contains(candidate))
                    continue;
                if (candidate.ActionSelectorButton is not Button candidateButton ||
                    !candidateButton.Bounds.Contains(position))
                {
                    continue;
                }

                insertAfter = position.X >= candidateButton.Bounds.Center.X;
                return candidate;
            }

            return null;
        }

        bool MoveActionGroup(
            ProtoActionWidgetState source,
            ProtoActionWidgetState target,
            bool insertAfter)
        {
            if (!CanReorderActionGroup(source))
                return false;

            var moved = ProtoActionOrderPolicy.MoveGroup(
                _protoActionWidgets,
                GetLinkedReorderGroup(source),
                GetLinkedReorderGroup(target),
                insertAfter);
            if (!moved)
                return false;

            var orderedBorders = _protoActionWidgets
                .Select(actionState => actionState.WidgetBorder)
                .Where(border => border != null)
                .Cast<Control>()
                .ToList();
            actionDetailsPanel.Children.Clear();
            foreach (var border in orderedBorders)
                actionDetailsPanel.Children.Add(border);

            _selectedProtoActionIndex = Math.Max(0, _protoActionWidgets.IndexOf(selectedAction ?? source));
            RefreshActionSelector();
            MarkDirty();
            return true;
        }

        pointerDragHoldTimer.Tick += (_, _) =>
        {
            pointerDragHoldTimer.Stop();
            if (pointerDragSource == null || pointerDragSourceButton == null || pointerDragHoldCancelled)
                return;

            pointerDragActive = true;
            pointerDragSourceButton.Cursor = new Cursor(StandardCursorType.SizeAll);
            pointerDragSourceButton.Opacity = 0.55;
        };

        void RefreshActionSelector()
        {
            if (selectedAction != null && !_protoActionWidgets.Contains(selectedAction))
                selectedAction = _protoActionWidgets.FirstOrDefault();
            if (selectedAction != null)
                _selectedProtoActionIndex = Math.Max(0, _protoActionWidgets.IndexOf(selectedAction));

            actionSelectorPanel.Children.Clear();
            foreach (var actionState in _protoActionWidgets)
            {
                var actionName = actionState.NameAcb.Text?.Trim() ?? "";

                var actionButton = new Button
                {
                    Content = CreateProtoActionSelectorContent(actionState, actionName),
                    Padding = new Thickness(8, 3),
                    Margin = new Thickness(0, 0, 6, 6),
                    Background = ReferenceEquals(actionState, selectedAction)
                        ? Brush.Parse("#393125")
                        : Brush.Parse("#252526")
                };
                if (CanReorderActionGroup(actionState))
                {
                    ToolTip.SetTip(actionButton, "Press and hold for one second, then drag to reorder. The order is saved to XML.");
                    actionButton.AddHandler(InputElement.PointerPressedEvent, (_, args) =>
                    {
                        if (!args.GetCurrentPoint(actionSelectorPanel).Properties.IsLeftButtonPressed ||
                            !CanReorderActionGroup(actionState) ||
                            BlockForDuplicateSelectedActionName())
                        {
                            return;
                        }

                        ResetPointerDragVisuals();
                        pointerDragSource = actionState;
                        pointerDragSourceButton = actionButton;
                        pointerDragStart = args.GetPosition(actionSelectorPanel);
                        pointerDragHoldCancelled = false;
                        pointerDragHoldTimer.Start();
                        args.Pointer.Capture(actionButton);
                        args.Handled = true;
                    }, RoutingStrategies.Tunnel, handledEventsToo: true);
                    actionButton.AddHandler(InputElement.PointerMovedEvent, (_, args) =>
                    {
                        if (!ReferenceEquals(pointerDragSource, actionState))
                            return;

                        var position = args.GetPosition(actionSelectorPanel);
                        if (!pointerDragActive)
                        {
                            var delta = position - pointerDragStart;
                            if (Math.Abs(delta.X) >= 5 || Math.Abs(delta.Y) >= 5)
                            {
                                pointerDragHoldCancelled = true;
                                pointerDragHoldTimer.Stop();
                            }
                            return;
                        }

                        var target = FindPointerDropTarget(position, out var insertAfter);
                        SetPointerDragTarget(target, insertAfter);
                        args.Handled = true;
                    }, RoutingStrategies.Tunnel, handledEventsToo: true);
                    actionButton.AddHandler(InputElement.PointerReleasedEvent, (_, args) =>
                    {
                        if (!ReferenceEquals(pointerDragSource, actionState))
                            return;

                        var wasDragging = pointerDragActive;
                        var dropTarget = pointerDragTarget;
                        var insertAfter = pointerDragInsertAfter;
                        pointerDragSource = null;
                        args.Pointer.Capture(null);
                        ResetPointerDragVisuals();

                        if (wasDragging && dropTarget != null)
                            MoveActionGroup(actionState, dropTarget, insertAfter);
                        else
                            SelectAction(actionState);
                        args.Handled = true;
                    }, RoutingStrategies.Tunnel, handledEventsToo: true);
                    actionButton.AddHandler(InputElement.PointerCaptureLostEvent, (_, _) =>
                    {
                        if (ReferenceEquals(pointerDragSource, actionState))
                            ResetPointerDragVisuals();
                    }, RoutingStrategies.Tunnel, handledEventsToo: true);
                }
                else if (_protoActionHostAdapter.Context.UsesTacticsInheritance && actionState.IsCurrentTacticsAction)
                {
                    ToolTip.SetTip(actionButton, "This action is owned by the linked tactics file. Reorder it in the Tactics manager.");
                }
                actionButton.Click += (_, _) =>
                {
                    SelectAction(actionState);
                };
                actionState.ActionSelectorButton = actionButton;
                actionSelectorPanel.Children.Add(actionButton);

                if (actionState.WidgetBorder != null)
                    actionState.WidgetBorder.IsVisible = ReferenceEquals(actionState, selectedAction);
            }

            if (_protoActionHostAdapter.Context.AllowsStandaloneActionCreation && !_isReadOnly)
            {
                var btnAddAction = new Button
                {
                    Content = "Add Action",
                    Classes = { "add-item" },
                    Padding = new Thickness(8, 3),
                    Margin = new Thickness(0, 0, 6, 6)
                };
                btnAddAction.Click += async (_, _) =>
                {
                    if (BlockForDuplicateSelectedActionName())
                        return;

                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        var newPa = new ProtoAction();
                        SelectAction(AddProtoActionWidget(newPa, isNewCustomAction: true));
                        MarkDirty();
                    }
                };
                actionSelectorPanel.Children.Add(btnAddAction);
            }
        }

        ProtoActionWidgetState AddProtoActionWidget(
            ProtoAction pa,
            bool isNewCustomAction = false,
            bool isLinkedMaulAreaAction = false,
            bool isLinkedAbductDropAction = false,
            bool isTacticsOnlyAction = false)
        {
            var widget = CreateProtoActionWidget(pa, () =>
            {
                MarkDirty();
                RefreshActionSelector();
            }, isNewCustomAction, isLinkedMaulAreaAction, isLinkedAbductDropAction, EnsureLinkedCompanionsForAction, isTacticsOnlyAction);
            actionDetailsPanel.Children.Add(widget);
            var state = _protoActionWidgets[^1];
            state.NameAcb.TextChanged += (_, _) => RefreshActionSelector();
            if (!isBuildingInitialActions && selectedAction == null)
                selectedAction = state;
            RefreshActionSelector();
            _refreshAbilityUnitActionValidity?.Invoke();
            return state;
        }

        void LinkMaulAreaAction(ProtoActionWidgetState primary, ProtoActionWidgetState companion)
        {
            primary.MaulAreaCompanion = companion;
            companion.IsLinkedMaulAreaAction = true;
            companion.NameAcb.Text = "AreaAttack";
            companion.NameAcb.IsEnabled = false;
            companion.TypeAcb.IsEnabled = false;
            companion.ForcedVisibleFieldTags.Add("rate");
            if (companion.RemoveButton != null)
                companion.RemoveButton.IsVisible = false;
            RefreshProtoActionMetadataPanels(companion);
        }

        void EnsureMaulCompanionForAction(ProtoActionWidgetState primary)
        {
            var actionType = ResolveProtoActionType(primary.NameAcb.Text?.Trim() ?? "", primary.TypeAcb.Text?.Trim() ?? "");
            if (!IsMaulActionType(actionType) || primary.IsLinkedMaulAreaAction)
                return;

            if (primary.MaulAreaCompanion != null || primary.IsCreatingMaulAreaCompanion)
                return;

            primary.IsCreatingMaulAreaCompanion = true;
            try
            {

                var companionAction = new ProtoAction
                {
                    Name = "AreaAttack",
                    Type = "Attack"
                };
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(companionAction, "attackaction", "1");
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(companionAction, "handlogic", "1");
                var companion = AddProtoActionWidget(companionAction, isNewCustomAction: true, isLinkedMaulAreaAction: true);
                var primaryIndex = _protoActionWidgets.IndexOf(primary);
                if (primaryIndex >= 0)
                {
                    _protoActionWidgets.Remove(companion);
                    _protoActionWidgets.Insert(primaryIndex + 1, companion);
                }
                if (primary.WidgetBorder?.Parent is Panel panel && companion.WidgetBorder != null)
                {
                    var primaryWidgetIndex = panel.Children.IndexOf(primary.WidgetBorder);
                    if (primaryWidgetIndex >= 0)
                    {
                        panel.Children.Remove(companion.WidgetBorder);
                        panel.Children.Insert(primaryWidgetIndex + 1, companion.WidgetBorder);
                    }
                }
                LinkMaulAreaAction(primary, companion);
                RefreshActionSelector();
            }
            finally
            {
                primary.IsCreatingMaulAreaCompanion = false;
            }
        }

        void LinkAbductDropAction(ProtoActionWidgetState primary, ProtoActionWidgetState companion)
        {
            primary.AbductDropCompanion = companion;
            companion.IsLinkedAbductDropAction = true;
            companion.NameAcb.Text = "AbductDrop";
            companion.NameAcb.IsEnabled = false;
            companion.TypeAcb.Text = "Inline";
            companion.TypeAcb.IsEnabled = false;
            companion.SelectedFlagTags.Add("isabductdrop");
            ProtoXmlHandler.SetProtoActionSimpleFieldValue(companion.Model, "isabductdrop", "1");
            if (companion.RemoveButton != null)
                companion.RemoveButton.IsVisible = false;
            RefreshProtoActionMetadataPanels(companion);
        }

        void EnsureAbductDropCompanionForAction(ProtoActionWidgetState primary)
        {
            var actionType = ResolveProtoActionType(primary.NameAcb.Text?.Trim() ?? "", primary.TypeAcb.Text?.Trim() ?? "");
            if (!IsAbductActionType(actionType) || primary.IsLinkedAbductDropAction)
                return;

            if (primary.AbductDropCompanion != null || primary.IsCreatingAbductDropCompanion)
                return;

            primary.IsCreatingAbductDropCompanion = true;
            try
            {
                var companionAction = new ProtoAction
                {
                    Name = "AbductDrop",
                    Type = "Inline"
                };
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(companionAction, "isabductdrop", "1");
                var companion = AddProtoActionWidget(companionAction, isNewCustomAction: true, isLinkedAbductDropAction: true);
                var primaryIndex = _protoActionWidgets.IndexOf(primary);
                if (primaryIndex >= 0)
                {
                    _protoActionWidgets.Remove(companion);
                    _protoActionWidgets.Insert(primaryIndex + 1, companion);
                }
                if (primary.WidgetBorder?.Parent is Panel panel && companion.WidgetBorder != null)
                {
                    var primaryWidgetIndex = panel.Children.IndexOf(primary.WidgetBorder);
                    if (primaryWidgetIndex >= 0)
                    {
                        panel.Children.Remove(companion.WidgetBorder);
                        panel.Children.Insert(primaryWidgetIndex + 1, companion.WidgetBorder);
                    }
                }
                LinkAbductDropAction(primary, companion);
                RefreshActionSelector();
            }
            finally
            {
                primary.IsCreatingAbductDropCompanion = false;
            }
        }

        void EnsureLinkedCompanionsForAction(ProtoActionWidgetState primary)
        {
            EnsureMaulCompanionForAction(primary);
            EnsureAbductDropCompanionForAction(primary);
        }

        foreach (var action in actions)
        {
            // A persisted override of a tactics-only action intentionally omits <type>.
            // Use the raw protoaction type here: if the type exists only in tactics, the
            // action remains tactics-backed after switching units or restarting the editor.
            AddProtoActionWidget(action, isTacticsOnlyAction: IsTacticsBackedProtoAction(action));
        }

        var protoActionNames = actions
            .Select(action => action.Name?.Trim() ?? "")
            .Where(name => !string.IsNullOrWhiteSpace(name))
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (_protoActionHostAdapter.Context.UsesTacticsInheritance)
        {
            foreach (var tacticsAction in _currentUnitTacticsActions.Values
                         .Where(action => !string.IsNullOrWhiteSpace(action.Name) && !protoActionNames.Contains(action.Name.Trim()))
                         .OrderBy(action => action.Name, StringComparer.OrdinalIgnoreCase))
            {
                var tacticsOnlyActionName = tacticsAction.Name.Trim();
                AddProtoActionWidget(
                    new ProtoAction { Name = tacticsOnlyActionName },
                    isTacticsOnlyAction: true);
            }
        }

        isBuildingInitialActions = false;
        selectedAction = _protoActionWidgets.ElementAtOrDefault(_selectedProtoActionIndex)
            ?? _protoActionWidgets.FirstOrDefault();

        // Existing Maul pairs are loaded as-is. Only their already-present AreaAttack
        // companion is locked; opening an original unit never creates one.
        foreach (var primary in _protoActionWidgets.Where(state =>
                     !(state.NameAcb.Text?.Trim().Equals("AreaAttack", StringComparison.OrdinalIgnoreCase) ?? false) &&
                     IsMaulActionType(ResolveProtoActionType(
                         state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? ""))).ToList())
        {
            var areaActionName = ProtoXmlHandler.GetProtoActionSimpleFieldValue(primary.Model, "areaprotoaction");
            if (string.IsNullOrWhiteSpace(areaActionName))
                areaActionName = "AreaAttack";

            var companion = _protoActionWidgets.FirstOrDefault(candidate =>
                !ReferenceEquals(candidate, primary) &&
                candidate.NameAcb.Text?.Trim().Equals(areaActionName, StringComparison.OrdinalIgnoreCase) == true);
            if (companion != null)
                LinkMaulAreaAction(primary, companion);
        }

        // Existing Abduct pairs are loaded as-is and use the same shared action editor
        // in both the ProtoUnit Actions tab and the standalone Tactics Manager.
        foreach (var primary in _protoActionWidgets.Where(state =>
                     !state.IsLinkedAbductDropAction &&
                     IsAbductActionType(ResolveProtoActionType(
                         state.NameAcb.Text?.Trim() ?? "", state.TypeAcb.Text?.Trim() ?? ""))).ToList())
        {
            var companion = _protoActionWidgets.FirstOrDefault(candidate =>
                !ReferenceEquals(candidate, primary) &&
                candidate.NameAcb.Text?.Trim().Equals("AbductDrop", StringComparison.OrdinalIgnoreCase) == true &&
                ResolveProtoActionType(candidate.NameAcb.Text?.Trim() ?? "", candidate.TypeAcb.Text?.Trim() ?? "")
                    .Equals("Inline", StringComparison.OrdinalIgnoreCase) &&
                (candidate.SelectedFlagTags.Contains("isabductdrop") ||
                 IsProtoActionFlagEnabledValue(ProtoXmlHandler.GetProtoActionSimpleFieldValue(candidate.Model, "isabductdrop"))));
            if (companion != null)
                LinkAbductDropAction(primary, companion);
        }

        RefreshActionSelector();

        if (!_isReadOnly && _protoActionHostAdapter.Context.ShowsProtoUnitChrome)
        {
            var actionButtonsRow = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Spacing = 8,
                Margin = new Thickness(0, 10, 0, 10)
            };

            var btnAddAction = new Button
            {
                Content = "Add Proto Action",
                Classes = { "add-item" },
                Margin = new Thickness(0)
            };
            btnAddAction.Click += async (s, e) =>
            {
                if (BlockForDuplicateSelectedActionName())
                    return;

                var proceed = await CheckStartLocalMod();
                if (proceed)
                {
                    var newPa = new ProtoAction();
                    SelectAction(AddProtoActionWidget(newPa, isNewCustomAction: true));
                    MarkDirty();
                }
            };
            actionButtonsRow.Children.Add(btnAddAction);

            var btnCopyAction = new Button
            {
                Content = "Copy From Another Unit",
                Classes = { "copy-import" },
                Margin = new Thickness(0)
            };
            btnCopyAction.Click += async (_, _) =>
            {
                if (BlockForDuplicateSelectedActionName())
                    return;

                await CopyProtoActionFromAnotherUnitAsync(pa =>
                {
                    SelectAction(AddProtoActionWidget(pa));
                });
            };
            actionButtonsRow.Children.Add(btnCopyAction);

            // Keep management controls immediately beneath the Proto Actions
            // heading, before the selector buttons and selected action editor.
            actionsContainer.Children.Insert(0, actionButtonsRow);
        }

        if (tacticsModeParentPanel != null)
            _activeEditorPanel = tacticsModeParentPanel;

        RebuildPageSearchTargets();
        RebuildSectionJumpFlyout();
        AttachProtoUnitStatsNumericBehaviors();
        RefreshProtoActionAnimationValidationVisuals();
        _ = PopulateStringFieldDisplaysAsync(buildGeneration);
    }

    private async Task PopulateStringFieldDisplaysAsync(int buildGeneration)
    {
        try
        {
            foreach (var tag in StringBackedFieldTags)
            {
                if (buildGeneration != _editorBuildGeneration)
                    return;

                if (!_fieldControls.TryGetValue(tag, out var ctrl) || ctrl is not TextBox tb)
                    continue;

                var stringId = _currentStringFieldIds.GetValueOrDefault(tag);
                var value = !string.IsNullOrWhiteSpace(stringId) && _pendingUnitStringUpdates.TryGetValue(stringId, out var pendingValue)
                    ? pendingValue
                    : await ResolveDisplayStringAsync(stringId);
                if (buildGeneration != _editorBuildGeneration)
                    return;
                tb.Text = value ?? stringId ?? "";
            }
        }
        finally
        {
            // Text assignments made while resolving display strings can raise
            // queued change events. Release the loading guard at Background
            // priority so those events cannot mark a newly opened unit dirty.
            Dispatcher.UIThread.Post(() =>
            {
                if (buildGeneration != _editorBuildGeneration)
                    return;

                _isPopulating = false;
                if (!_showStoredRawXml)
                    UpdateXmlPreview();
            }, DispatcherPriority.Background);
        }
    }

    private Border CreateChip(
        string text,
        Action onRemove,
        ProtoActionValueSource source = ProtoActionValueSource.ProtoOnly,
        string tacticsValue = "",
        bool allowRemove = true)
    {
        var sourceMarker = CreateProtoActionSourceMarker(source, tacticsValue);
        return EditorChipService.CreateBlueChip(
            text,
            allowRemove ? onRemove : null,
            readOnly: _isReadOnly,
            marker: sourceMarker);
    }

    private Border CreateProtoActionWidget(
        ProtoAction pa,
        Action onRemove,
        bool isNewCustomAction = false,
        bool isLinkedMaulAreaAction = false,
        bool isLinkedAbductDropAction = false,
        Action<ProtoActionWidgetState>? onActionTypeChanged = null,
        bool isTacticsOnlyAction = false)
    {
        string resolvedType = ResolveProtoActionType(pa.Name, pa.Type);
        var typeOptions = GetProtoActionTypeOptions(resolvedType);
        var effectiveAction = CreateEffectiveProtoActionSnapshot(pa, pa.Name, resolvedType);

        var border = new Border
        {
            Background = Brush.Parse("#0E1110"),
            BorderBrush = Brush.Parse("#4C4031"),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(8),
            Padding = new Thickness(10),
            Margin = new Thickness(0, 4, 0, 4)
        };

        var mainStack = new StackPanel { Spacing = 8 };
        border.Child = mainStack;

        var header = new DockPanel
        {
            LastChildFill = false
        };
        mainStack.Children.Add(header);

        var bodyStack = new StackPanel { Spacing = 8 };
        mainStack.Children.Add(bodyStack);

        var nameLabel = new TextBlock { Text = "Name:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 4, 0) };
        DockPanel.SetDock(nameLabel, Dock.Left);
        header.Children.Add(nameLabel);

        var nameAcb = new AutoCompleteBox
        {
            Text = pa.Name,
            FilterMode = AutoCompleteFilterMode.Contains,
            ItemsSource = _protoActionNameSuggestions,
            Width = (resolvedType.Equals("ConditionalTransform", StringComparison.OrdinalIgnoreCase) ||
                     resolvedType.Equals("DelayedTransform", StringComparison.OrdinalIgnoreCase)) ? 220 : 180,
            IsEnabled = !_isReadOnly,
            VerticalAlignment = VerticalAlignment.Center
        };
        if (isNewCustomAction)
            AttachNoWhitespaceNameBehavior(nameAcb);
        EnableDropdownAutoComplete(nameAcb);
        KeepAutoCompleteTextStartVisible(nameAcb);
        var nameValidationFrame = new Border
        {
            Child = nameAcb,
            BorderThickness = new Thickness(0),
            CornerRadius = new CornerRadius(4),
            Margin = new Thickness(0, 0, 10, 0),
            VerticalAlignment = VerticalAlignment.Center
        };
        DockPanel.SetDock(nameValidationFrame, Dock.Left);
        header.Children.Add(nameValidationFrame);

        var typeLabel = new TextBlock { Text = "Type:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 4, 0) };
        DockPanel.SetDock(typeLabel, Dock.Left);
        header.Children.Add(typeLabel);

        var typeAcb = new AutoCompleteBox
        {
            Text = resolvedType,
            FilterMode = AutoCompleteFilterMode.Contains,
            ItemsSource = typeOptions,
            Width = (resolvedType.Equals("ConditionalTransform", StringComparison.OrdinalIgnoreCase) ||
                     resolvedType.Equals("DelayedTransform", StringComparison.OrdinalIgnoreCase)) ? 210 : 150,
            IsEnabled = !_isReadOnly,
            VerticalAlignment = VerticalAlignment.Center
        };
        EnableDropdownAutoComplete(typeAcb);
        KeepAutoCompleteTextStartVisible(typeAcb);
        var typeValidationFrame = new Border
        {
            Child = typeAcb,
            BorderThickness = new Thickness(0),
            CornerRadius = new CornerRadius(4),
            Margin = new Thickness(0, 0, 10, 0),
            VerticalAlignment = VerticalAlignment.Center
        };
        DockPanel.SetDock(typeValidationFrame, Dock.Left);
        header.Children.Add(typeValidationFrame);

        var rawActiveValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "active");
        var hasExplicitActiveValue = !string.IsNullOrWhiteSpace(rawActiveValue);
        var initialActiveChecked = !hasExplicitActiveValue || IsProtoActionFlagEnabledValue(rawActiveValue);

        var activeLabel = new TextBlock
        {
            Text = "Active:",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 0, 6, 0)
        };
        DockPanel.SetDock(activeLabel, Dock.Left);
        header.Children.Add(activeLabel);

        var activeCheckBox = new CheckBox
        {
            IsChecked = initialActiveChecked,
            IsEnabled = !_isReadOnly,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(0, 0, 10, 0)
        };
        DockPanel.SetDock(activeCheckBox, Dock.Left);
        header.Children.Add(activeCheckBox);

        var state = new ProtoActionWidgetState
        {
            Model = pa.Clone(),
            IsNewCustomAction = isNewCustomAction,
            IsTacticsOnlyAction = isTacticsOnlyAction,
            IsCurrentTacticsAction = TryGetCurrentUnitTacticsAction(pa.Name, out var initialTacticsAction),
            HasTacticsOnlyOverrides = initialTacticsAction != null &&
                                       HasActualTacticsOverride(pa, initialTacticsAction),
            NameValidationFrame = nameValidationFrame,
            TypeValidationFrame = typeValidationFrame,
            IsLinkedMaulAreaAction = isLinkedMaulAreaAction,
            IsLinkedAbductDropAction = isLinkedAbductDropAction,
            Container = mainStack,
            BodyContainer = bodyStack,
            ActiveLabel = activeLabel,
            ActiveCheckBox = activeCheckBox,
            NameAcb = nameAcb,
            TypeAcb = typeAcb,
            CoreFieldsGrid = null!,
            RofLabel = null!,
            RofTb = null!,
            MaxRangeLabel = null!,
            MaxRangeTb = null!,
            AutoBoostModeContainer = new StackPanel { Spacing = 2 },
            JumpAttackOptionsContainer = new StackPanel { Spacing = 2 },
            BuckAttackOptionsContainer = new StackPanel { Spacing = 2 },
            LinearAreaAttackOptionsContainer = new StackPanel { Spacing = 2 },
            AbductPostCoreOptionsContainer = new StackPanel { Spacing = 2 },
            AdditionalFieldsContainer = new StackPanel { Spacing = 4 },
            StructuredFieldsContainer = new StackPanel { Spacing = 4 },
            OnHitEffectsContainer = new StackPanel { Spacing = 4 },
            FlagsContainer = new StackPanel { Spacing = 4 },
            OptionalFieldsContainer = new StackPanel { Spacing = 4 },
            DamageSectionContainer = new StackPanel { Spacing = 4 },
            DamageExtrasContainer = new StackPanel { Spacing = 4 },
            BonusSectionContainer = new StackPanel { Spacing = 4 },
            RampageLayoutContainer = new StackPanel { Spacing = 4 }
        };
        state.WidgetBorder = border;
        if (state.IsLinkedMaulAreaAction || state.IsLinkedAbductDropAction || state.IsTacticsOnlyAction)
        {
            nameAcb.IsEnabled = false;
            typeAcb.IsEnabled = false;
        }
        state.CustomFlagControls["active"] = activeCheckBox;
        state.CustomValues[ProtoActionActiveExplicitStateKey] = hasExplicitActiveValue ? "1" : "0";
        state.CustomValues[ProtoActionActiveValueStateKey] = initialActiveChecked ? "1" : "0";
        foreach (var flagTag in ProtoActionMetadataCatalog.GetKnownFlagTags())
        {
            var rawFlagValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, flagTag);
            var hasFlagElement = GetProtoActionAdditionalElement(effectiveAction, flagTag) != null;
            if (IsInvertedDefaultProtoActionFlag(flagTag))
            {
                if (rawFlagValue.Trim().Equals("0", StringComparison.OrdinalIgnoreCase))
                    state.SelectedFlagTags.Add(GetInvertedDefaultProtoActionFlagTag(flagTag));
            }
            else if (IsProtoActionFlagEnabledValue(rawFlagValue) ||
                (hasFlagElement && !rawFlagValue.Trim().Equals("0", StringComparison.OrdinalIgnoreCase)))
                state.SelectedFlagTags.Add(flagTag);
        }
        if (initialActiveChecked)
            state.SelectedFlagTags.Add("active");
        else
            state.SelectedFlagTags.Remove("active");
        _protoActionWidgets.Add(state);
        typeAcb.ItemsSource = GetProtoActionTypeOptionsForState(state, resolvedType);
        UpdateProtoActionTypeEditor(typeAcb, pa.Name);
        var lastRenderedActionType = resolvedType;
        var suppressStackControlTypeRevert = false;
        void ApplyProtoActionTypeSelection(string selectedActionType)
        {
            if (string.IsNullOrWhiteSpace(selectedActionType))
                return;

            // Keep the committed item visible even when Avalonia raises SelectionChanged
            // before its internal text synchronization has completed.
            if (!selectedActionType.Equals(typeAcb.Text?.Trim() ?? "", StringComparison.OrdinalIgnoreCase))
            {
                suppressStackControlTypeRevert = true;
                typeAcb.Text = selectedActionType;
                suppressStackControlTypeRevert = false;
            }

            var appliedDefaultAttackMode = ApplyDefaultAttackModeForNewAction(
                state,
                nameAcb.Text?.Trim() ?? "",
                selectedActionType);
            var alreadyRendered = selectedActionType.Equals(lastRenderedActionType, StringComparison.OrdinalIgnoreCase) &&
                                  state.BodyContainer.IsVisible;
            if (alreadyRendered && !appliedDefaultAttackMode)
                return;

            var previousActionType = lastRenderedActionType;
            lastRenderedActionType = selectedActionType;
            RefreshProtoActionMetadataPanels(state);
            if (IsStackControlActionType(previousActionType) ||
                IsStackControlActionType(selectedActionType))
            {
                RefreshStackControlTypeOptions();
                RefreshStackProtoActionReference();
            }
            RefreshExclusiveAttackActionReferences();
            RefreshAllProtoActionNameValidation();
            onActionTypeChanged?.Invoke(state);
        }
        RefreshProtoActionNameValidation(state);
        if (IsStackControlActionType(resolvedType) && !string.IsNullOrWhiteSpace(pa.Name))
            RefreshStackProtoActionReference();

        activeCheckBox.IsCheckedChanged += async (_, _) =>
        {
            if (_isPopulating)
                return;

            var proceed = await CheckStartLocalMod();
            if (!proceed)
                return;

            var isChecked = activeCheckBox.IsChecked == true;
            state.CustomValues[ProtoActionActiveExplicitStateKey] = "1";
            state.CustomValues[ProtoActionActiveValueStateKey] = isChecked ? "1" : "0";
            if (isChecked)
                state.SelectedFlagTags.Add("active");
            else
                state.SelectedFlagTags.Remove("active");

            RenderProtoActionFlags(state);
            MarkDirty();
        };

        if (!_isReadOnly)
        {
            var btnRemove = new Button
            {
                Content = "Remove",
                Background = Brush.Parse("#7A1F1C"),
            BorderBrush = Brush.Parse("#B55640"),
                VerticalAlignment = VerticalAlignment.Center
            };
            btnRemove.Click += async (s, e) =>
            {
                var actionName = state.NameAcb.Text?.Trim() ?? state.Model.Name?.Trim() ?? "";
                if (TryGetCurrentUnitTacticsAction(actionName, out _))
                {
                    await new Prompt(
                        PromptType.Error,
                        "Tactics Action",
                        "This action exists in the currently linked tactics file and cannot be removed. You may override its fields, but the tactics action will remain available.")
                        .ShowDialog(this);
                    return;
                }

                var proceed = await CheckStartLocalMod();
                if (proceed)
                {
                    if (state.MaulAreaCompanion != null)
                    {
                        _protoActionWidgets.Remove(state.MaulAreaCompanion);
                        if (state.MaulAreaCompanion.WidgetBorder?.Parent is Panel companionPanel)
                            companionPanel.Children.Remove(state.MaulAreaCompanion.WidgetBorder);
                    }
                    if (state.AbductDropCompanion != null)
                    {
                        _protoActionWidgets.Remove(state.AbductDropCompanion);
                        if (state.AbductDropCompanion.WidgetBorder?.Parent is Panel abductCompanionPanel)
                            abductCompanionPanel.Children.Remove(state.AbductDropCompanion.WidgetBorder);
                    }
                    _protoActionWidgets.Remove(state);
                    RefreshAllProtoActionNameValidation();
                    RefreshStackControlTypeOptions();
                    RefreshStackProtoActionReference();
                    RefreshExclusiveAttackActionReferences();
                    onRemove();
                    _refreshAbilityUnitActionValidity?.Invoke();
                    if (border.Parent is Panel p)
                    {
                        p.Children.Remove(border);
                    }
                }
            };
            state.RemoveButton = btnRemove;
            DockPanel.SetDock(btnRemove, Dock.Right);
            header.Children.Add(btnRemove);
        }

        nameAcb.TextChanged += async (s, e) =>
        {
            if (!_isPopulating)
            {
                RefreshAllProtoActionNameValidation();
                string name = nameAcb.Text?.Trim() ?? "";
                if (state.HasDuplicateName)
                {
                    _refreshAbilityUnitActionValidity?.Invoke();
                    MarkDirty();
                    return;
                }

                // While a new custom action name is being typed, an intermediate exact
                // catalog match (for example "Charge" in "ChargedModify") must not resolve
                // a type or build a card. Name-based type resolution is committed only by
                // the name dropdown closing or by focus loss below.
                if (!state.IsNewCustomAction &&
                    TryResolveProtoActionType(name, out string? mappedType) &&
                    !string.IsNullOrEmpty(mappedType))
                {
                    typeAcb.ItemsSource = GetProtoActionTypeOptionsForState(state, mappedType);
                    UpdateProtoActionTypeEditor(typeAcb, name);
                }
                else
                {
                    typeAcb.ItemsSource = GetProtoActionTypeOptionsForState(state, typeAcb.Text);
                    typeAcb.IsEnabled = !_isReadOnly && !string.IsNullOrWhiteSpace(name);
                }

                var proceed = await CheckStartLocalMod();
                if (proceed)
                {
                    if (!name.Equals(nameAcb.Text?.Trim() ?? "", StringComparison.Ordinal))
                        return;
                    if (IsStackControlActionType(ResolveProtoActionType(name, typeAcb.Text?.Trim() ?? "")))
                        RefreshStackProtoActionReference();
                    _refreshAbilityUnitActionValidity?.Invoke();
                    ApplyDefaultAttackModeForNewAction(
                        state,
                        name,
                        typeAcb.Text?.Trim() ?? "");
                    RefreshExclusiveAttackActionReferences();
                    RefreshAllProtoActionNameValidation();
                    RefreshProtoActionMetadataPanels(state);
                    onActionTypeChanged?.Invoke(state);
                    MarkDirty();
                }
            }
        };

        void CommitActionNameSelection()
        {
            if (_isPopulating || !nameAcb.IsEnabled)
                return;

            RefreshAllProtoActionNameValidation();
            if (state.HasDuplicateName)
                return;

            var committedName = nameAcb.Text?.Trim() ?? "";
            if (TryResolveProtoActionType(committedName, out var mappedType) &&
                !string.IsNullOrWhiteSpace(mappedType))
            {
                UpdateProtoActionTypeEditor(typeAcb, committedName);
                ApplyProtoActionTypeSelection(mappedType);
            }
        }

        nameAcb.DropDownClosed += (_, _) =>
        {
            if (nameAcb.SelectedItem is string selectedName &&
                selectedName.Equals(nameAcb.Text?.Trim() ?? "", StringComparison.OrdinalIgnoreCase))
            {
                Dispatcher.UIThread.Post(CommitActionNameSelection, DispatcherPriority.Input);
            }
        };

        nameAcb.LostFocus += (_, _) => CommitActionNameSelection();

        typeAcb.SelectionChanged += (_, _) =>
        {
            if (_isPopulating || string.IsNullOrWhiteSpace(nameAcb.Text))
                return;

            Dispatcher.UIThread.Post(async () =>
            {
                if (_isPopulating || string.IsNullOrWhiteSpace(nameAcb.Text))
                    return;

                if (typeAcb.SelectedItem is not string selectedType || string.IsNullOrWhiteSpace(selectedType))
                    return;

                ApplyProtoActionTypeSelection(selectedType);
                if (await CheckStartLocalMod())
                    MarkDirty();
            }, DispatcherPriority.Input);
        };

        typeAcb.TextChanged += async (s, e) =>
        {
            if (!_isPopulating && !suppressStackControlTypeRevert)
            {
                if (string.IsNullOrWhiteSpace(nameAcb.Text))
                {
                    suppressStackControlTypeRevert = true;
                    typeAcb.Text = "";
                    typeAcb.IsEnabled = false;
                    typeAcb.IsDropDownOpen = false;
                    suppressStackControlTypeRevert = false;
                    return;
                }

                var selectedActionType = GetExactProtoActionTypeMatch(typeAcb.Text);
                if (!string.IsNullOrWhiteSpace(selectedActionType))
                    ApplyProtoActionTypeSelection(selectedActionType);

                var proceed = await CheckStartLocalMod();
                if (proceed)
                {
                    MarkDirty();
                }
            }
        };

        typeAcb.LostFocus += (s, e) =>
        {
            if (typeAcb.IsEnabled)
            {
                var matchedType = GetExactProtoActionTypeMatch(typeAcb.Text);
                if (!string.IsNullOrWhiteSpace(matchedType))
                    typeAcb.Text = matchedType;
                RefreshProtoActionMetadataPanels(state);
                onActionTypeChanged?.Invoke(state);
            }
        };

        bodyStack.Children.Add(state.AutoBoostModeContainer);
        bodyStack.Children.Add(state.JumpAttackOptionsContainer);

        var showInitialCoreMinRange = UsesCoreMinRange(resolvedType) &&
                                      !isLinkedMaulAreaAction &&
                                      !isLinkedAbductDropAction &&
                                      (IsAttackActionType(resolvedType) || IsChainAttackActionType(resolvedType) || IsAoeAttackActionType(resolvedType) || IsLinearAreaAttackActionType(resolvedType) || IsAbductActionType(resolvedType) || IsTeleportAttackActionType(resolvedType) || resolvedType.Equals("WaterTornado", StringComparison.OrdinalIgnoreCase)
                                          ? state.ForcedVisibleFieldTags.Contains("minrange") || !string.IsNullOrWhiteSpace(
                                              ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "minrange"))
                                          : isNewCustomAction || !string.IsNullOrWhiteSpace(
                                              ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "minrange")));
        var fieldsGrid = new Grid
        {
            ColumnDefinitions = showInitialCoreMinRange
                ? new ColumnDefinitions("Auto, 80, Auto, 80, Auto, 80")
                : new ColumnDefinitions("Auto, 80, Auto, 80"),
            Margin = new Thickness(0, 4, 0, 4)
        };
        state.CoreFieldsGrid = fieldsGrid;
        bodyStack.Children.Add(fieldsGrid);
        bodyStack.Children.Add(state.BuckAttackOptionsContainer);
        bodyStack.Children.Add(state.AbductPostCoreOptionsContainer);
        bodyStack.Children.Add(state.LinearAreaAttackOptionsContainer);

        var rofLabel = new TextBlock { Text = "Rate of Fire:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(0, 0, 10, 0) };
        state.RofLabel = rofLabel;
        Grid.SetColumn(rofLabel, 0);
        fieldsGrid.Children.Add(rofLabel);

        var rofTb = new TextBox { Text = GetProtoActionDefaultSimpleValue("rof", effectiveAction.Rof), IsEnabled = !_isReadOnly, Margin = new Thickness(0, 0, 10, 0) };
        AttachProtoActionDecimalBehavior(rofTb);
        rofTb.TextChanged += async (s, e) =>
        {
            if (!_isPopulating)
            {
                var proceed = await CheckStartLocalMod();
                if (proceed) MarkDirty();
            }
        };
        Grid.SetColumn(rofTb, 1);
        fieldsGrid.Children.Add(rofTb);
        state.RofTb = rofTb;

        var maxRangeLabelColumn = 2;
        var maxRangeValueColumn = 3;
        if (showInitialCoreMinRange)
        {
            var minRangeLabel = new TextBlock { Text = "Min Range:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(18, 0, 10, 0) };
            Grid.SetColumn(minRangeLabel, 2);
            fieldsGrid.Children.Add(minRangeLabel);

            var initialMinRange = ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "minrange");
            var minRangeTb = new TextBox
            {
            Text = string.IsNullOrWhiteSpace(initialMinRange) && isNewCustomAction ? "0" : initialMinRange,
                IsEnabled = !_isReadOnly,
                Margin = new Thickness(0, 0, 10, 0)
            };
            AttachProtoActionDecimalBehavior(minRangeTb);
            minRangeTb.TextChanged += async (_, _) =>
            {
                if (_isPopulating)
                    return;

                var proceed = await CheckStartLocalMod();
                if (proceed)
                    MarkDirty();
            };
            Grid.SetColumn(minRangeTb, 3);
            fieldsGrid.Children.Add(minRangeTb);
            state.JumpAttackMinRangeLabel = minRangeLabel;
            state.JumpAttackMinRangeTb = minRangeTb;
            maxRangeLabelColumn = 4;
            maxRangeValueColumn = 5;
        }

        var mrLabel = new TextBlock { Text = "Max Range:", VerticalAlignment = VerticalAlignment.Center, Margin = new Thickness(18, 0, 10, 0) };
        state.MaxRangeLabel = mrLabel;
        Grid.SetColumn(mrLabel, maxRangeLabelColumn);
        fieldsGrid.Children.Add(mrLabel);

        var mrTb = new TextBox { Text = GetProtoActionDefaultSimpleValue("maxrange", effectiveAction.MaxRange), IsEnabled = !_isReadOnly };
        AttachProtoActionDecimalBehavior(mrTb);
        mrTb.TextChanged += async (s, e) =>
        {
            if (!_isPopulating)
            {
                var proceed = await CheckStartLocalMod();
                if (proceed) MarkDirty();
            }
        };
        Grid.SetColumn(mrTb, maxRangeValueColumn);
        fieldsGrid.Children.Add(mrTb);
        state.MaxRangeTb = mrTb;

        bodyStack.Children.Add(state.DamageSectionContainer);

        var dmgLabel = new TextBlock
        {
            Tag = DamageHeaderTag,
            Text = "Damage:",
            FontWeight = FontWeight.Bold,
            Margin = new Thickness(0, 6, 0, 2),
            IsVisible = false
        };
        state.DamageSectionContainer.Children.Add(dmgLabel);

        var dmgContainer = new WrapPanel { Orientation = Orientation.Horizontal };
        state.DamageSectionContainer.Children.Add(dmgContainer);

        var damageTypeLabel = new TextBlock
        {
            Text = "Type:",
            Margin = new Thickness(0, 4, 8, 4),
            VerticalAlignment = VerticalAlignment.Center,
            IsVisible = false
        };
        dmgContainer.Children.Add(damageTypeLabel);

        Button? addDamageButton = null;
        var isRefreshingDamageTypes = false;

        void RefreshDamageSectionPresentation()
        {
            damageTypeLabel.IsVisible = state.DamageRows.Count > 0;
            RefreshProtoActionDamageHeader(state);
        }

        void RefreshDamageTypeOptions()
        {
            if (isRefreshingDamageTypes)
                return;

            isRefreshingDamageTypes = true;
            foreach (var row in state.DamageRows)
            {
                var currentType = row.TypeCb.SelectedItem?.ToString() ?? "";
                var usedByOtherRows = state.DamageRows
                    .Where(other => !ReferenceEquals(other, row))
                    .Select(other => other.TypeCb.SelectedItem?.ToString() ?? "")
                    .Where(type => !string.IsNullOrWhiteSpace(type))
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);
                var availableTypes = ProtoConstants.KnownDamageTypes
                    .Where(type => type.Equals(currentType, StringComparison.OrdinalIgnoreCase) || !usedByOtherRows.Contains(type))
                    .ToList();

                row.TypeCb.ItemsSource = availableTypes;
                row.TypeCb.SelectedItem = availableTypes.FirstOrDefault(type => type.Equals(currentType, StringComparison.OrdinalIgnoreCase)) ?? currentType;
            }
            isRefreshingDamageTypes = false;
        }

        void EnsureAddDamageButton()
        {
            if (_isReadOnly)
                return;

            if (state.DamageRows.Count >= ProtoConstants.KnownDamageTypes.Count())
            {
                if (addDamageButton != null)
                    dmgContainer.Children.Remove(addDamageButton);
                return;
            }

            if (addDamageButton == null)
            {
                addDamageButton = new Button
                {
                    Content = "Add Damage",
                    Classes = { "add-component" },
                    Margin = new Thickness(2, 0, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center
                };
                addDamageButton.Click += async (_, _) =>
                {
                    if (!await CheckStartLocalMod())
                        return;

                    var usedTypes = state.DamageRows
                        .Select(row => row.TypeCb.SelectedItem?.ToString() ?? "")
                        .Where(type => !string.IsNullOrWhiteSpace(type))
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);
                    var nextType = ProtoConstants.KnownDamageTypes
                        .FirstOrDefault(type => !usedTypes.Contains(type));
                    if (string.IsNullOrWhiteSpace(nextType))
                        return;

                    AddDamageRow(nextType, "0");
                    MarkDirty();
                };
            }

            dmgContainer.Children.Remove(addDamageButton);
            dmgContainer.Children.Add(addDamageButton);
        }

        void AddDamageRow(string dtype, string dval)
        {
            var typeCb = new ComboBox
            {
                ItemsSource = ProtoConstants.KnownDamageTypes,
                SelectedItem = ProtoConstants.KnownDamageTypes.FirstOrDefault(x => x.Equals(dtype, StringComparison.OrdinalIgnoreCase)) ?? dtype,
                Width = 110,
                IsEnabled = !_isReadOnly
            };
            typeCb.SelectionChanged += async (s, e) =>
            {
                if (isRefreshingDamageTypes)
                    return;

                if (!_isPopulating)
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        RefreshDamageTypeOptions();
                        MarkDirty();
                    }
                }
            };
            var valTb = new TextBox { Text = dval, IsEnabled = !_isReadOnly, Width = 70 };
            AttachProtoActionDecimalBehavior(valTb);
            valTb.TextChanged += async (s, e) =>
            {
                if (!_isPopulating)
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed) MarkDirty();
                }
            };
            var rowPanel = new DamageEditor(typeCb, valTb, showRemoveButton: !_isReadOnly);

            string GetCurrentDamageType() => typeCb.SelectedItem?.ToString()?.Trim() ?? "";
            void RefreshDamageSourceMarker()
            {
                if (!TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction))
                {
                    rowPanel.SetSourceMarker(null);
                    return;
                }
                var type = GetCurrentDamageType();
                var protoEntry = state.Model.Damages.FirstOrDefault(entry => entry.DamageType.Equals(type, StringComparison.OrdinalIgnoreCase));
                var tacticsEntry = tacticsAction.Damages.FirstOrDefault(entry => entry.DamageType.Equals(type, StringComparison.OrdinalIgnoreCase));
                var protoAmount = string.IsNullOrWhiteSpace(protoEntry.DamageType) ? "" : protoEntry.Amount;
                var tacticsAmount = string.IsNullOrWhiteSpace(tacticsEntry.DamageType) ? "" : tacticsEntry.Amount;
                var source = GetProtoActionValueSource(valTb.Text?.Trim() ?? "", protoAmount, tacticsAmount);
                rowPanel.SetSourceMarker(CreateProtoActionSourceMarker(source, tacticsAmount));
            }
            typeCb.SelectionChanged += (_, _) => RefreshDamageSourceMarker();
            valTb.TextChanged += (_, _) => RefreshDamageSourceMarker();
            RefreshDamageSourceMarker();

            var rowState = new DamageRowState { RowPanel = rowPanel, TypeCb = typeCb, ValTb = valTb };
            state.DamageRows.Add(rowState);

            if (rowPanel.RemoveButton != null)
            {
                rowPanel.RemoveButton.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        state.DamageRows.Remove(rowState);
                        dmgContainer.Children.Remove(rowPanel);
                        RefreshDamageTypeOptions();
                        RefreshDamageSectionPresentation();
                        EnsureAddDamageButton();
                        MarkDirty();
                    }
                };
            }

            dmgContainer.Children.Add(rowPanel);
            RefreshDamageTypeOptions();
            RefreshDamageSectionPresentation();
            EnsureAddDamageButton();
        }

        foreach (var dmg in effectiveAction.Damages)
        {
            AddDamageRow(dmg.DamageType, dmg.Amount);
        }

        RefreshDamageSectionPresentation();
        EnsureAddDamageButton();

        if (!IsAutoRangedModifyActionType(resolvedType))
            bodyStack.Children.Add(state.BonusSectionContainer);
        bodyStack.Children.Add(state.AdditionalFieldsContainer);
        bodyStack.Children.Add(state.StructuredFieldsContainer);
        bodyStack.Children.Add(state.OnHitEffectsContainer);
        bodyStack.Children.Add(state.FlagsContainer);
        bodyStack.Children.Add(state.OptionalFieldsContainer);

        if (!IsAutoRangedModifyActionType(resolvedType))
        {
            var bonusContainer = new WrapPanel
            {
                Orientation = Orientation.Horizontal
            };
            state.BonusSectionContainer.Children.Add(bonusContainer);

            var bonusLabel = new TextBlock
            {
                Text = "Bonuses:",
                Margin = new Thickness(0, 4, 10, 6),
                VerticalAlignment = VerticalAlignment.Center,
                IsVisible = false
            };
            bonusContainer.Children.Add(bonusLabel);

            Button? btnAddBonus = null;

            void RefreshBonusSectionPresentation()
            {
                bonusLabel.IsVisible = state.BonusRows.Count > 0;
                RefreshProtoActionDamageHeader(state);
            }

            void EnsureAddBonusButtonAtEnd()
            {
                if (btnAddBonus == null)
                    return;

                bonusContainer.Children.Remove(btnAddBonus);
                bonusContainer.Children.Add(btnAddBonus);
            }

            void AddBonusRow(string btype, string bval)
            {
                var rowPanel = new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Spacing = 6,
                    Margin = new Thickness(0, 0, 10, 6)
                };

                var typeAcb = new AutoCompleteBox
                {
                    Text = btype,
                    FilterMode = AutoCompleteFilterMode.Contains,
                    ItemsSource = GetKnownUnitTypeNames()
                        .Concat(_barData?.UnitNames ?? [])
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(x => x)
                        .ToList(),
                    Width = 180,
                    IsEnabled = !_isReadOnly
                };
                var isInheritedBonusType =
                    _protoActionHostAdapter.Context.UsesTacticsInheritance &&
                    TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var inheritedBonusTacticsAction) &&
                    inheritedBonusTacticsAction.DamageBonuses.Any(entry =>
                        entry.UnitType.Equals(btype, StringComparison.OrdinalIgnoreCase));
                if (isInheritedBonusType)
                    typeAcb.IsEnabled = false;
                typeAcb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                rowPanel.Children.Add(typeAcb);

                var valTb = new TextBox { Text = bval, IsEnabled = !_isReadOnly, Width = 80 };
                AttachProtoActionDecimalBehavior(valTb);
                valTb.TextChanged += async (s, e) =>
                {
                    if (!_isPopulating)
                    {
                        var proceed = await CheckStartLocalMod();
                        if (proceed) MarkDirty();
                    }
                };
                var valueHost = new Grid
                {
                    Width = 80,
                    HorizontalAlignment = HorizontalAlignment.Left,
                    VerticalAlignment = VerticalAlignment.Center
                };
                valueHost.Children.Add(valTb);
                rowPanel.Children.Add(valueHost);

                Border? bonusSourceMarker = null;
                void RefreshBonusSourceMarker()
                {
                    if (bonusSourceMarker != null)
                        valueHost.Children.Remove(bonusSourceMarker);
                    bonusSourceMarker = null;

                    if (!TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var tacticsAction))
                        return;
                    var type = typeAcb.Text?.Trim() ?? "";
                    var protoEntry = state.Model.DamageBonuses.FirstOrDefault(entry => entry.UnitType.Equals(type, StringComparison.OrdinalIgnoreCase));
                    var tacticsEntry = tacticsAction.DamageBonuses.FirstOrDefault(entry => entry.UnitType.Equals(type, StringComparison.OrdinalIgnoreCase));
                    var protoMultiplier = string.IsNullOrWhiteSpace(protoEntry.UnitType) ? "" : protoEntry.Multiplier;
                    var tacticsMultiplier = string.IsNullOrWhiteSpace(tacticsEntry.UnitType) ? "" : tacticsEntry.Multiplier;
                    var source = GetProtoActionValueSource(valTb.Text?.Trim() ?? "", protoMultiplier, tacticsMultiplier);
                    bonusSourceMarker = CreateProtoActionSourceMarker(source, tacticsMultiplier);
                    if (bonusSourceMarker != null)
                    {
                        bonusSourceMarker.Margin = new Thickness(0, 0, 3, 0);
                        bonusSourceMarker.VerticalAlignment = VerticalAlignment.Center;
                        valueHost.Children.Add(bonusSourceMarker);
                    }
                }
                typeAcb.TextChanged += (_, _) => RefreshBonusSourceMarker();
                valTb.TextChanged += (_, _) => RefreshBonusSourceMarker();
                RefreshBonusSourceMarker();

                var rowState = new BonusRowState { RowPanel = rowPanel, TypeAcb = typeAcb, ValTb = valTb };
                state.BonusRows.Add(rowState);

                if (!_isReadOnly)
                {
                    var btnDel = new Button { Classes = { "remove-button" }, VerticalAlignment = VerticalAlignment.Center };
                    btnDel.Click += async (s, e) =>
                    {
                        if (isInheritedBonusType)
                        {
                            var inheritedPrompt = new Prompt(
                                PromptType.Error,
                                "Inherited damage bonus",
                                "This Damage Bonus type is supplied by the current tactics and cannot be removed. Its value can still be overridden.");
                            await inheritedPrompt.ShowDialog(this);
                            return;
                        }

                        var proceed = await CheckStartLocalMod();
                        if (proceed)
                        {
                            state.BonusRows.Remove(rowState);
                            bonusContainer.Children.Remove(rowPanel);
                            RefreshBonusSectionPresentation();
                            MarkDirty();
                        }
                    };
                    rowPanel.Children.Add(btnDel);
                }

                bonusContainer.Children.Add(rowPanel);
                RefreshBonusSectionPresentation();
                EnsureAddBonusButtonAtEnd();
            }

            foreach (var db in effectiveAction.DamageBonuses)
            {
                AddBonusRow(db.UnitType, db.Multiplier);
            }

            RefreshBonusSectionPresentation();

            if (!_isReadOnly)
            {
                btnAddBonus = new Button
                {
                    Content = "Add Damage Bonus",
                    Classes = { "add-component" },
                    Margin = new Thickness(0, 0, 0, 6),
                    VerticalAlignment = VerticalAlignment.Center
                };
                btnAddBonus.Click += async (s, e) =>
                {
                    var proceed = await CheckStartLocalMod();
                    if (proceed)
                    {
                        AddBonusRow("", "1.0");
                        MarkDirty();
                    }
                };
                bonusContainer.Children.Add(btnAddBonus);
            }
        }

        state.DamageSectionContainer.Children.Add(state.DamageExtrasContainer);
        RefreshProtoActionDamageHeader(state);

        RefreshProtoActionMetadataPanels(state);

        // Type-keyed numeric rows are rendered by several action-specific editors.
        // A type supplied by the current tactics action is identity data: keep the
        // type and row protected while allowing the numeric value to be overridden.
        if (TryGetCurrentUnitTacticsAction(state.NameAcb.Text?.Trim() ?? "", out var currentTacticsAction))
        {
            foreach (var structuredTag in new[] { "rate", "typedmaxrange", "minrate" })
            {
                if (!state.StructuredFieldRows.TryGetValue(structuredTag, out var renderedRows))
                    continue;

                var inheritedTypes = GetProtoActionStructuredFieldEntriesForEditor(
                        currentTacticsAction,
                        resolvedType,
                        structuredTag)
                    .Select(entry => entry.Attributes.TryGetValue("type", out var type) ? type.Trim() : "")
                    .Where(type => !string.IsNullOrWhiteSpace(type))
                    .ToHashSet(StringComparer.OrdinalIgnoreCase);

                foreach (var row in renderedRows)
                {
                    if (!row.AttributeEditors.TryGetValue("type", out var typeEditor))
                        continue;

                    var renderedType = typeEditor switch
                    {
                        ComboBox comboBox => comboBox.SelectedItem?.ToString()?.Trim() ?? "",
                        AutoCompleteBox acb => acb.Text?.Trim() ?? "",
                        TextBox textBox => textBox.Text?.Trim() ?? "",
                        _ => ""
                    };
                    if (!inheritedTypes.Contains(renderedType))
                        continue;

                    typeEditor.IsEnabled = false;
                    foreach (var removeButton in row.RowPanel.Children
                                 .OfType<Button>()
                                 .Where(button => button.Classes.Contains("remove-button")))
                    {
                        GuardInheritedStructuredRowRemoval(removeButton, structuredTag, renderedType);
                    }
                }
            }
        }

        RefreshAllProtoActionNameValidation();
        return border;
    }

    private void ApplyCurrentEdits(XElement? targetUnit = null)
    {
        if (string.IsNullOrEmpty(_currentUnitName)) return;

        var unit = targetUnit;
        if (unit == null)
        {
            if (_modXmlRoot == null) return;
            unit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, _currentUnitName);
        }
        if (unit == null) return;

        var originalUnit = new XElement(unit);

        static string CanonicalizeKnownOrExisting(
            string? input,
            IEnumerable<string> knownValues,
            string? existingValue = null)
        {
            var normalized = input?.Trim() ?? "";
            var known = knownValues.FirstOrDefault(value => value.Equals(normalized, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(known))
                return known;

            var existing = existingValue?.Trim() ?? "";
            return !string.IsNullOrWhiteSpace(existing) &&
                   existing.Equals(normalized, StringComparison.Ordinal)
                ? existing
                : "";
        }

        static string PreserveStrictCommittedValue(string? input, IEnumerable<string> knownValues)
        {
            var normalized = input?.Trim() ?? "";
            return knownValues.FirstOrDefault(value => value.Equals(normalized, StringComparison.OrdinalIgnoreCase))
                   ?? normalized;
        }

        static string ResolveModifyType(string? input, string? originalValue)
            => ProtoUnitStatsConditionalPolicy.ResolveModifyTypeOrLegacy(input, originalValue);

        if (_fieldControls.TryGetValue(ProtoUnitNameFieldKey, out var protoNameCtrl) && protoNameCtrl is TextBox protoNameTb)
        {
            var newUnitName = protoNameTb.Text?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(newUnitName) &&
                !newUnitName.Equals(_currentUnitName, StringComparison.OrdinalIgnoreCase) &&
                (targetUnit != null || (_modXmlRoot != null && !ProtoXmlHandler.UnitExists(_modXmlRoot, newUnitName))))
            {
                if (targetUnit != null)
                {
                    unit.SetAttributeValue("name", newUnitName);
                }
                else
                {
                    var oldStringIds = new Dictionary<string, string>(_currentStringFieldIds, StringComparer.OrdinalIgnoreCase);
                    var stringTexts = StringBackedFieldTags
                        .Where(tag => _fieldControls.TryGetValue(tag, out var control) && control is TextBox)
                        .ToDictionary(
                            tag => tag,
                            tag => ((TextBox)_fieldControls[tag]).Text?.Trim() ?? "",
                            StringComparer.OrdinalIgnoreCase);

                    var oldUnitName = _currentUnitName;
                    unit.SetAttributeValue("name", newUnitName);
                    _currentUnitName = newUnitName;
                    RenameOpenDocumentTabs(EditorEntityKind.Units, oldUnitName, newUnitName);

                    var renamedIds = BuildRenamedUnitStringIds(newUnitName, oldStringIds, stringTexts);
                    _currentStringFieldIds.Clear();
                    foreach (var entry in renamedIds)
                    {
                        _currentStringFieldIds[entry.Key] = entry.Value;
                        ProtoXmlHandler.SetSimpleField(unit, entry.Key, entry.Value);
                        if (stringTexts.TryGetValue(entry.Key, out var text))
                        {
                            _pendingUnitStringRemovals.Remove(entry.Value);
                            _pendingUnitStringUpdates[entry.Value] = text;
                        }
                    }
                    foreach (var tag in StringBackedFieldTags.Where(tag => !renamedIds.ContainsKey(tag)))
                        ProtoXmlHandler.RemoveSimpleField(unit, tag);

                    foreach (var oldStringId in oldStringIds.Values.Where(id =>
                                 !string.IsNullOrWhiteSpace(id) &&
                                 !renamedIds.Values.Contains(id, StringComparer.OrdinalIgnoreCase)))
                    {
                        _pendingUnitRenameRemovedStringIds.Add(oldStringId);
                        _pendingUnitStringUpdates.Remove(oldStringId);
                    }

                    if (_dirtyUnitNames.Remove(oldUnitName))
                        _dirtyUnitNames.Add(newUnitName);
                    if (_unitAbilityDrafts.Remove(oldUnitName, out var savedAbilityDrafts))
                        _unitAbilityDrafts[newUnitName] = savedAbilityDrafts;
                    TrackPendingUnitRename(oldUnitName, newUnitName);
                }
            }
        }

        foreach (var field in ProtoConstants.SimpleFields)
        {
            if (field.Tag.Equals("buildlimit", StringComparison.OrdinalIgnoreCase))
                continue;
            if (IsStringBackedField(field.Tag))
                continue;
            if (IsCultureAwareSimpleField(field.Tag))
                continue;

            if (_fieldControls.TryGetValue(field.Tag, out var ctrl))
            {
                string val = "";
                if (AssetPathFieldTags.Contains(field.Tag)) val = ReadControlValue(ctrl);
                else if (ctrl is AutoCompleteBox acb) val = acb.Text?.Trim() ?? "";
                else if (ctrl is ComboBox cb) val = cb.SelectedItem as string ?? cb.SelectedValue as string ?? "";
                else if (ctrl is TextBox tb) val = tb.Text?.Trim() ?? "";

                if (!string.IsNullOrEmpty(val))
                    ProtoXmlHandler.SetSimpleField(unit, field.Tag, val);
                else
                    ProtoXmlHandler.RemoveSimpleField(unit, field.Tag);
            }
        }

        // Train/Build Points are two XML representations of the same editor value.
        // Keep exactly the representation selected from the final Unit Type set.
        if (_fieldControls.ContainsKey("buildpoints"))
            ProtoXmlHandler.RemoveSimpleField(unit, "trainpoints");
        else if (_fieldControls.ContainsKey("trainpoints"))
            ProtoXmlHandler.RemoveSimpleField(unit, "buildpoints");

        foreach (var tag in OtherSpecificSimpleNumberTags.Concat(OtherSpecificSimpleTextTags).Concat(OtherSpecificSimpleSuggestionTags))
        {
            if (_fieldControls.TryGetValue(tag, out var ctrl))
            {
                string val = ctrl switch
                {
                    AutoCompleteBox acb => acb.Text?.Trim() ?? "",
                    TextBox tb => tb.Text?.Trim() ?? "",
                    StrictSearchableComboBox strictComboBox => strictComboBox.Value,
                    ComboBox cb => cb.SelectedItem as string ?? cb.SelectedValue as string ?? "",
                    _ => ""
                };

                if (tag.Equals("dodgechance", StringComparison.OrdinalIgnoreCase))
                {
                    if (string.IsNullOrWhiteSpace(val))
                    {
                        val = "0";
                    }
                    else if (double.TryParse(val, out var dodgeChance))
                    {
                        if (dodgeChance < 0) dodgeChance = 0;
                        if (dodgeChance > 1) dodgeChance = 1;
                        val = dodgeChance.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);
                    }
                    else
                    {
                        val = "0";
                    }
                }
                else if (tag.Equals("formationorder", StringComparison.OrdinalIgnoreCase))
                {
                    if (string.IsNullOrWhiteSpace(val))
                    {
                        val = "0";
                    }
                    else if (int.TryParse(val, out var formationOrder))
                    {
                        if (formationOrder < 0) formationOrder = 0;
                        if (formationOrder > 5) formationOrder = 5;
                        val = formationOrder.ToString();
                    }
                    else
                    {
                        val = "0";
                    }
                }
                else if (tag.Equals("partisancount", StringComparison.OrdinalIgnoreCase))
                {
                    if (string.IsNullOrWhiteSpace(val))
                    {
                        val = "0";
                    }
                }
                else if (tag.Equals("bloodscalemodify", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("bonescalemodify", StringComparison.OrdinalIgnoreCase))
                {
                    if (string.IsNullOrWhiteSpace(val))
                    {
                        val = "1";
                    }
                }
                else if (tag.Equals("resourcesubtype", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetKnownResourceSubtypeNames(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("initialunitaistance", StringComparison.OrdinalIgnoreCase))
                {
                    val = PreserveStrictCommittedValue(val, KnownInitialUnitAiStances);
                }
                else if (tag.Equals("pathabilityflags", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetKnownPathabilityFlags(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("placementfile", StringComparison.OrdinalIgnoreCase))
                {
                    var matchedPlacementFile = GetKnownPlacementFileNames().FirstOrDefault(x => x.Equals(val, StringComparison.OrdinalIgnoreCase));
                    if (!string.IsNullOrWhiteSpace(matchedPlacementFile))
                        val = matchedPlacementFile;
                }
                else if (tag.Equals("hotkeycontext", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetKnownHotkeyContexts(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("allyhotkeycontext", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetKnownHotkeyContexts(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("partisantype", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetAvailableTrainUnitNames(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("disguiseprotoid", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("deadreplacement", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("deadtransform", StringComparison.OrdinalIgnoreCase) ||
                         tag.Equals("eidolonprotoid", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetAvailableTrainUnitNames(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("bloodgroupoverride", StringComparison.OrdinalIgnoreCase))
                {
                    val = CanonicalizeKnownOrExisting(val, GetKnownBloodGroupNames(), ProtoXmlHandler.GetSimpleField(originalUnit, tag));
                }
                else if (tag.Equals("minimapicon", StringComparison.OrdinalIgnoreCase))
                {
                    val = GetKnownMinimapIcons().FirstOrDefault(x => x.Equals(val, StringComparison.OrdinalIgnoreCase)) ?? val;
                }

                if (!string.IsNullOrWhiteSpace(val))
                    ProtoXmlHandler.SetSimpleField(unit, tag, val);
                else
                    ProtoXmlHandler.RemoveSimpleField(unit, tag);
            }
            else
            {
                ProtoXmlHandler.RemoveSimpleField(unit, tag);
            }
        }

        if (_fieldControls.TryGetValue("socketunittype", out var socketUnitTypeCtrl) && socketUnitTypeCtrl is AutoCompleteBox socketUnitTypeAcb)
        {
            var socketUnitType = socketUnitTypeAcb.Text?.Trim() ?? "";
            socketUnitType = CanonicalizeKnownOrExisting(
                socketUnitType,
                GetAvailableBuildLimitTargets(),
                ProtoXmlHandler.GetSimpleField(originalUnit, "socketunittype"));
            if (!string.IsNullOrWhiteSpace(socketUnitType))
                ProtoXmlHandler.SetSimpleField(unit, "socketunittype", socketUnitType);
            else
                ProtoXmlHandler.RemoveSimpleField(unit, "socketunittype");
        }
        else
        {
            ProtoXmlHandler.RemoveSimpleField(unit, "socketunittype");
        }

        if (_fieldControls.TryGetValue("nonsocketplaceprotoid", out var nonSocketCtrl) && nonSocketCtrl is AutoCompleteBox nonSocketAcb)
        {
            var nonSocketPlaceProtoId = nonSocketAcb.Text?.Trim() ?? "";
            nonSocketPlaceProtoId = CanonicalizeKnownOrExisting(
                nonSocketPlaceProtoId,
                GetAvailableTrainUnitNames(),
                ProtoXmlHandler.GetSimpleField(originalUnit, "nonsocketplaceprotoid"));
            if (!string.IsNullOrWhiteSpace(nonSocketPlaceProtoId))
                ProtoXmlHandler.SetSimpleField(unit, "nonsocketplaceprotoid", nonSocketPlaceProtoId);
            else
                ProtoXmlHandler.RemoveSimpleField(unit, "nonsocketplaceprotoid");
        }
        else
        {
            ProtoXmlHandler.RemoveSimpleField(unit, "nonsocketplaceprotoid");
        }

        void SyncFlagWithOtherSpecificField(string tag, bool shouldHaveFlag)
        {
            var flag = GetFlagForOtherSpecificAttribute(tag);
            if (string.IsNullOrWhiteSpace(flag) || _currentFlags == null)
                return;

            if (shouldHaveFlag)
                _currentFlags.Add(flag);
            else
                _currentFlags.Remove(flag);
        }

        SyncFlagWithOtherSpecificField(
            "displayedrange",
            _fieldControls.TryGetValue("displayedrange", out var displayedRangeCtrl) &&
            displayedRangeCtrl is TextBox displayedRangeTb &&
            !string.IsNullOrWhiteSpace(displayedRangeTb.Text));

        SyncFlagWithOtherSpecificField(
            "dodgechance",
            _fieldControls.TryGetValue("dodgechance", out var dodgeChanceCtrl) &&
            dodgeChanceCtrl is TextBox dodgeChanceTbForFlag &&
            !string.IsNullOrWhiteSpace(dodgeChanceTbForFlag.Text));

        SyncFlagWithOtherSpecificField(
            "farming",
            (_fieldControls.TryGetValue("farmingradiusx", out var farmingRadiusXCtrl) &&
             farmingRadiusXCtrl is TextBox farmingRadiusXTb &&
             !string.IsNullOrWhiteSpace(farmingRadiusXTb.Text)) ||
            (_fieldControls.TryGetValue("farmingradiusz", out var farmingRadiusZCtrl) &&
             farmingRadiusZCtrl is TextBox farmingRadiusZTb &&
             !string.IsNullOrWhiteSpace(farmingRadiusZTb.Text)) ||
            (_fieldControls.TryGetValue("farmingobstructionradiusx", out var farmingObstructionXCtrl) &&
             farmingObstructionXCtrl is TextBox farmingObstructionXTb &&
             !string.IsNullOrWhiteSpace(farmingObstructionXTb.Text)) ||
            (_fieldControls.TryGetValue("farmingobstructionradiusz", out var farmingObstructionZCtrl) &&
             farmingObstructionZCtrl is TextBox farmingObstructionZTb &&
             !string.IsNullOrWhiteSpace(farmingObstructionZTb.Text)) ||
            (_fieldControls.TryGetValue("farmingnumstops", out var farmingNumStopsCtrl) &&
             farmingNumStopsCtrl is TextBox farmingNumStopsTb &&
             !string.IsNullOrWhiteSpace(farmingNumStopsTb.Text)));

        unit.Elements("directionalarmor").Remove();
        if (_fieldControls.TryGetValue("directionalarmor.value", out var directionalArmorValueCtrl) && directionalArmorValueCtrl is TextBox directionalArmorValueTb)
        {
            var directionalArmorValue = directionalArmorValueTb.Text?.Trim() ?? "";
            var directionalArmorAngle = _fieldControls.TryGetValue("directionalarmor.angle", out var directionalArmorAngleCtrl) && directionalArmorAngleCtrl is TextBox directionalArmorAngleTb
                ? directionalArmorAngleTb.Text?.Trim() ?? ""
                : "";

            if (!string.IsNullOrWhiteSpace(directionalArmorValue) || !string.IsNullOrWhiteSpace(directionalArmorAngle))
            {
                var directionalArmorElement = new XElement("directionalarmor");
                if (!string.IsNullOrWhiteSpace(directionalArmorAngle))
                    directionalArmorElement.SetAttributeValue("angle", directionalArmorAngle);
                if (!string.IsNullOrWhiteSpace(directionalArmorValue))
                    directionalArmorElement.SetAttributeValue("value", directionalArmorValue);
                unit.Add(directionalArmorElement);
            }
        }

        unit.Elements("creationfadetime").Remove();
        var creationFadeValue = _fieldControls.TryGetValue("creationfadetime.value", out var creationFadeValueCtrl) && creationFadeValueCtrl is TextBox creationFadeValueTb
            ? creationFadeValueTb.Text?.Trim() ?? ""
            : "";
        var creationFadeInitAlpha = _fieldControls.TryGetValue("creationfadetime.initalpha", out var creationFadeInitAlphaCtrl) && creationFadeInitAlphaCtrl is TextBox creationFadeInitAlphaTb
            ? creationFadeInitAlphaTb.Text?.Trim() ?? ""
            : "";
        if (string.IsNullOrWhiteSpace(creationFadeValue) && !string.IsNullOrWhiteSpace(creationFadeInitAlpha))
            creationFadeValue = "0";
        if (!string.IsNullOrWhiteSpace(creationFadeValue))
        {
            var creationFadeElement = new XElement("creationfadetime", creationFadeValue);
            if (!string.IsNullOrWhiteSpace(creationFadeInitAlpha))
                creationFadeElement.SetAttributeValue("initalpha", creationFadeInitAlpha);
            unit.Add(creationFadeElement);
        }

        unit.Elements("heightbob").Remove();
        var heightBobPeriod = _fieldControls.TryGetValue("heightbob.period", out var heightBobPeriodCtrl) && heightBobPeriodCtrl is TextBox heightBobPeriodTb
            ? heightBobPeriodTb.Text?.Trim() ?? ""
            : "";
        var heightBobMagnitude = _fieldControls.TryGetValue("heightbob.magnitude", out var heightBobMagnitudeCtrl) && heightBobMagnitudeCtrl is TextBox heightBobMagnitudeTb
            ? heightBobMagnitudeTb.Text?.Trim() ?? ""
            : "";
        if (!string.IsNullOrWhiteSpace(heightBobPeriod) ||
            !string.IsNullOrWhiteSpace(heightBobMagnitude))
        {
            var heightBobElement = new XElement("heightbob");
            if (!string.IsNullOrWhiteSpace(heightBobPeriod))
                heightBobElement.SetAttributeValue("period", heightBobPeriod);
            if (!string.IsNullOrWhiteSpace(heightBobMagnitude))
                heightBobElement.SetAttributeValue("magnitude", heightBobMagnitude);
            unit.Add(heightBobElement);
        }

        unit.Elements("initialshading").Remove();
        var initialShadingType = _fieldControls.TryGetValue("initialshading.type", out var initialShadingTypeCtrl) && initialShadingTypeCtrl is StrictSearchableComboBox initialShadingTypeCb
            ? initialShadingTypeCb.Value
            : "";
        var initialShadingFactor = _fieldControls.TryGetValue("initialshading.factor", out var initialShadingFactorCtrl) && initialShadingFactorCtrl is TextBox initialShadingFactorTb
            ? initialShadingFactorTb.Text?.Trim() ?? ""
            : "";
        initialShadingType = PreserveStrictCommittedValue(initialShadingType, KnownInitialShadingTypes);
        initialShadingType = ProtoConstants.GetShadingTypeXmlValue(initialShadingType);
        if (string.IsNullOrWhiteSpace(initialShadingFactor))
            initialShadingFactor = "1";
        if (!string.IsNullOrWhiteSpace(initialShadingType))
        {
            var initialShadingElement = new XElement("initialshading");
            initialShadingElement.SetAttributeValue("type", initialShadingType);
            initialShadingElement.SetAttributeValue("factor", initialShadingFactor);
            unit.Add(initialShadingElement);
        }

        unit.Elements("damageshading").Remove();
        var damageShadingType = _fieldControls.TryGetValue("damageshading.type", out var damageShadingTypeCtrl) && damageShadingTypeCtrl is StrictSearchableComboBox damageShadingTypeCb
            ? damageShadingTypeCb.Value
            : "";
        var damageShadingThreshold = _fieldControls.TryGetValue("damageshading.threshold", out var damageShadingThresholdCtrl) && damageShadingThresholdCtrl is TextBox damageShadingThresholdTb
            ? damageShadingThresholdTb.Text?.Trim() ?? ""
            : "";
        var damageShadingRate = _fieldControls.TryGetValue("damageshading.rate", out var damageShadingRateCtrl) && damageShadingRateCtrl is TextBox damageShadingRateTb
            ? damageShadingRateTb.Text?.Trim() ?? ""
            : "";
        var damageShadingTime = _fieldControls.TryGetValue("damageshading.time", out var damageShadingTimeCtrl) && damageShadingTimeCtrl is TextBox damageShadingTimeTb
            ? damageShadingTimeTb.Text?.Trim() ?? ""
            : "";
        damageShadingType = PreserveStrictCommittedValue(damageShadingType, KnownInitialShadingTypes);
        damageShadingType = ProtoConstants.GetShadingTypeXmlValue(damageShadingType);
        if (string.IsNullOrWhiteSpace(damageShadingThreshold))
            damageShadingThreshold = "1";
        else if (double.TryParse(damageShadingThreshold, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsedDamageShadingThreshold))
        {
            if (parsedDamageShadingThreshold < 0) parsedDamageShadingThreshold = 0;
            if (parsedDamageShadingThreshold > 1) parsedDamageShadingThreshold = 1;
            damageShadingThreshold = parsedDamageShadingThreshold.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);
        }
        else
        {
            damageShadingThreshold = "1";
        }
        if (string.IsNullOrWhiteSpace(damageShadingRate))
            damageShadingRate = "1";
        if (string.IsNullOrWhiteSpace(damageShadingTime))
            damageShadingTime = "1000";
        if (!string.IsNullOrWhiteSpace(damageShadingType))
        {
            var damageShadingElement = new XElement("damageshading");
            damageShadingElement.SetAttributeValue("type", damageShadingType);
            damageShadingElement.SetAttributeValue("threshold", damageShadingThreshold);
            damageShadingElement.SetAttributeValue("rate", damageShadingRate);
            damageShadingElement.SetAttributeValue("time", damageShadingTime);
            unit.Add(damageShadingElement);
        }

        unit.Elements("killreward").Remove();
        foreach (var resourceType in ProtoConstants.KnownResourceTypes)
        {
            if (_fieldControls.TryGetValue($"killreward:{resourceType}", out var killRewardCtrl) && killRewardCtrl is TextBox killRewardTb)
            {
                var killRewardValue = killRewardTb.Text?.Trim() ?? "";
                if (!string.IsNullOrWhiteSpace(killRewardValue))
                {
                    unit.Add(new XElement("killreward",
                        new XAttribute("resourcetype", resourceType),
                        killRewardValue));
                }
            }
        }

        unit.Elements("ResourceReturn").Remove();
        foreach (var resourceType in ProtoConstants.KnownResourceTypes)
        {
            if (_fieldControls.TryGetValue($"resourcereturn:{resourceType}", out var resourceReturnCtrl) && resourceReturnCtrl is TextBox resourceReturnTb)
            {
                var resourceReturnValue = resourceReturnTb.Text?.Trim() ?? "";
                if (!string.IsNullOrWhiteSpace(resourceReturnValue))
                {
                    unit.Add(new XElement("ResourceReturn",
                        new XAttribute("resourceType", resourceType),
                        resourceReturnValue));
                }
            }
        }

        unit.Elements("ResourceReturnRate").Remove();
        foreach (var resourceType in ProtoConstants.KnownResourceTypes)
        {
            if (_fieldControls.TryGetValue($"resourcereturnrate:{resourceType}", out var resourceReturnRateCtrl) && resourceReturnRateCtrl is TextBox resourceReturnRateTb)
            {
                var resourceReturnRateValue = resourceReturnRateTb.Text?.Trim() ?? "";
                if (!string.IsNullOrWhiteSpace(resourceReturnRateValue))
                {
                    unit.Add(new XElement("ResourceReturnRate",
                        new XAttribute("resourceType", resourceType),
                        resourceReturnRateValue));
                }
            }
        }

        if (_currentFlags != null)
        {
            var shouldReturnOnConstruction =
                (_fieldControls.TryGetValue("resourcereturn:returnonconstruction", out var returnOnConstructionCtrl) &&
                 returnOnConstructionCtrl is CheckBox returnOnConstructionCb &&
                 returnOnConstructionCb.IsChecked == true) ||
                (_fieldControls.TryGetValue("resourcereturnrate:returnonconstruction", out var returnRateOnConstructionCtrl) &&
                 returnRateOnConstructionCtrl is CheckBox returnRateOnConstructionCb &&
                 returnRateOnConstructionCb.IsChecked == true);

            if (shouldReturnOnConstruction)
                _currentFlags.Add("ReturnResourcesOnConstruction");
            else
                _currentFlags.Remove("ReturnResourcesOnConstruction");

            var shouldDisableDeleteReturn =
                (_fieldControls.TryGetValue("resourcereturn:noreturnondelete", out var noReturnOnDeleteCtrl) &&
                 noReturnOnDeleteCtrl is CheckBox noReturnOnDeleteCb &&
                 noReturnOnDeleteCb.IsChecked == true) ||
                (_fieldControls.TryGetValue("resourcereturnrate:noreturnondelete", out var noReturnRateOnDeleteCtrl) &&
                 noReturnRateOnDeleteCtrl is CheckBox noReturnRateOnDeleteCb &&
                 noReturnRateOnDeleteCb.IsChecked == true);

            if (shouldDisableDeleteReturn)
                _currentFlags.Add("DoNotApplyResourceReturnIfDeleted");
            else
                _currentFlags.Remove("DoNotApplyResourceReturnIfDeleted");

            if (_fieldControls.TryGetValue("resourcereturnrate:totalcostbased", out var totalCostBasedCtrl) &&
                totalCostBasedCtrl is CheckBox totalCostBasedCb &&
                totalCostBasedCb.IsChecked == true)
            {
                _currentFlags.Add("ResourceReturnRateTotalCost");
            }
            else
            {
                _currentFlags.Remove("ResourceReturnRateTotalCost");
            }
        }

        unit.Elements("dependentunit").Remove();
        var validDependentUnitNames = GetAvailableTrainUnitNames();
        var originalDependentUnits = originalUnit.Elements("dependentunit").ToList();
        for (var dependentIndex = 0; dependentIndex < _dependentUnitRows.Count; dependentIndex++)
        {
            var row = _dependentUnitRows[dependentIndex];
            var dependentUnitValue = row.ValueAcb.Text?.Trim() ?? "";
            var dependentUnitName = CanonicalizeKnownOrExisting(
                dependentUnitValue,
                validDependentUnitNames,
                originalDependentUnits.ElementAtOrDefault(dependentIndex)?.Value);
            if (string.IsNullOrWhiteSpace(dependentUnitName))
                continue;

            var dependentUnit = new XElement("dependentunit", dependentUnitName);
            var x = row.XTb.Text?.Trim() ?? "";
            var z = row.ZTb.Text?.Trim() ?? "";
            var attachBone = row.AttachBoneTb.Text?.Trim() ?? "";

            dependentUnit.SetAttributeValue("x", string.IsNullOrWhiteSpace(x) ? "0" : x);
            dependentUnit.SetAttributeValue("z", string.IsNullOrWhiteSpace(z) ? "0" : z);
            if (!string.IsNullOrWhiteSpace(attachBone))
                dependentUnit.SetAttributeValue("attachbone", attachBone);

            unit.Add(dependentUnit);
        }

        unit.Elements("veterancyranks").Remove();
        if (_veterancyRankRows.Count > 0)
        {
            var veterancyRanks = new XElement("veterancyranks");
            foreach (var row in _veterancyRankRows)
            {
                var type = row.TypeCb.SelectedItem as string ?? row.TypeCb.SelectedValue as string ?? "";
                var value = row.ValueTb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(type) || string.IsNullOrWhiteSpace(value))
                    continue;

                var tagName = type switch
                {
                    "NumKills" => "numkills",
                    "NumAttacks" => "numattacks",
                    "TotalDamage" => "totaldamage",
                    "DamageAndResourcesEaten" => "damageandresourceseaten",
                    _ => type.ToLowerInvariant()
                };

                veterancyRanks.Add(new XElement("rank", new XElement(tagName, value)));
            }

            if (veterancyRanks.HasElements)
                unit.Add(veterancyRanks);
        }

        unit.Elements("veterancybonus").Remove();
        if (_veterancyBonusRows.Count > 0 && _currentVeterancyIncludeTypes != null && _currentVeterancyIncludeTypes.Count > 0)
        {
            var groupedBonusRows = _veterancyBonusRows
                .Select(row => new
                {
                    RankId = row.RankIdTb.Text?.Trim() ?? "0",
                    ModifyType = ResolveModifyType(row.ModifyTypeAcb.Text, row.OriginalModifyType),
                    Value = row.ValueTb.Text?.Trim() ?? "",
                    DamageType = row.DamageTypeAcb.Text?.Trim() ?? "",
                    row.OriginalDamageType,
                    row.OriginalModifyType
                })
                .Where(x => !string.IsNullOrWhiteSpace(x.ModifyType) && !string.IsNullOrWhiteSpace(x.Value))
                .GroupBy(x => string.IsNullOrWhiteSpace(x.RankId) ? "0" : x.RankId);

            var veterancyBonus = new XElement("veterancybonus");
            foreach (var group in groupedBonusRows)
            {
                var rank = new XElement("rank");
                rank.SetAttributeValue("id", group.Key);
                foreach (var bonus in group)
                {
                    var modify = new XElement("veterancymodify", bonus.Value);
                    modify.SetAttributeValue("modifytype", bonus.ModifyType);
                    if (bonus.ModifyType is "DamageSpecific" or "ArmorSpecific")
                    {
                        var damageType = CanonicalizeKnownOrExisting(
                            bonus.DamageType,
                            ProtoConstants.KnownDamageTypes,
                            bonus.OriginalDamageType);
                        if (!string.IsNullOrWhiteSpace(damageType))
                            modify.SetAttributeValue("damagetype", damageType);
                    }
                    else if (ProtoConstants.GetModifyTypeValue(bonus.ModifyType).Length == 0 &&
                             bonus.ModifyType.Equals(bonus.OriginalModifyType, StringComparison.Ordinal) &&
                             !string.IsNullOrWhiteSpace(bonus.OriginalDamageType))
                    {
                        modify.SetAttributeValue("damagetype", bonus.OriginalDamageType);
                    }
                    rank.Add(modify);
                }
                veterancyBonus.Add(rank);
            }

            veterancyBonus.Add(new XElement("includetypes",
                _currentVeterancyIncludeTypes
                    .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    .Select(x => new XElement("unittype", x))));

            if (_currentVeterancyExcludeTypes != null && _currentVeterancyExcludeTypes.Count > 0)
            {
                veterancyBonus.Add(new XElement("excludetypes",
                    _currentVeterancyExcludeTypes
                        .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                        .Select(x => new XElement("unittype", x))));
            }

            if (veterancyBonus.HasElements)
                unit.Add(veterancyBonus);
        }

        unit.Elements().Where(x => x.Name.LocalName.Equals("OnDamageModifiers", StringComparison.OrdinalIgnoreCase)).Remove();
        if (_onDamageModifyRows.Count > 0)
        {
            var onDamageModifiers = new XElement("OnDamageModifiers");
            foreach (var row in _onDamageModifyRows)
            {
                var modifyType = ResolveModifyType(row.ModifyTypeAcb.Text, row.OriginalModifyType);
                var value = row.ValueTb.Text?.Trim() ?? "";
                if (string.IsNullOrWhiteSpace(modifyType) || string.IsNullOrWhiteSpace(value))
                    continue;

                var modify = new XElement("OnDamageModify", value);
                modify.SetAttributeValue("modifyType", modifyType);
                if (modifyType.Equals("DamageSpecific", StringComparison.OrdinalIgnoreCase) ||
                    modifyType.Equals("ArmorSpecific", StringComparison.OrdinalIgnoreCase))
                {
                    var damageType = row.DamageTypeCb.Value;
                    damageType = PreserveStrictCommittedValue(damageType, ProtoConstants.KnownDamageTypes);
                    if (!string.IsNullOrWhiteSpace(damageType))
                        modify.SetAttributeValue("damageType", damageType);
                }
                else if (ProtoConstants.GetModifyTypeValue(modifyType).Length == 0 &&
                         modifyType.Equals(row.OriginalModifyType, StringComparison.Ordinal) &&
                         !string.IsNullOrWhiteSpace(row.OriginalDamageType))
                {
                    modify.SetAttributeValue("damageType", row.OriginalDamageType);
                }

                onDamageModifiers.Add(modify);
            }

            if (onDamageModifiers.HasElements)
                unit.Add(onDamageModifiers);
        }

        unit.Elements("spawn").Remove();
        var validSpawnProtoUnits = GetAvailableTrainUnitNames();
        var originalSpawns = originalUnit.Elements("spawn").ToList();
        for (var spawnIndex = 0; spawnIndex < _spawnRows.Count; spawnIndex++)
        {
            var row = _spawnRows[spawnIndex];
            var originalSpawn = originalSpawns.ElementAtOrDefault(spawnIndex);
            var spawnValue = row.ValueAcb.Text?.Trim() ?? "";
            var spawnProtoUnit = CanonicalizeKnownOrExisting(spawnValue, validSpawnProtoUnits, originalSpawn?.Value);
            if (string.IsNullOrWhiteSpace(spawnProtoUnit))
                continue;

            var spawnType = row.TypeCb.SelectedItem as string ?? "";
            if (string.IsNullOrWhiteSpace(spawnType))
                continue;

            var count = row.CountTb.Text?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(count))
                count = "1";

            var lifespan = row.LifespanTb.Text?.Trim() ?? "";
            var chance = row.ChanceTb.Text?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(chance) && double.TryParse(chance, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsedSpawnChance))
            {
                if (parsedSpawnChance < 0) parsedSpawnChance = 0;
                if (parsedSpawnChance > 1) parsedSpawnChance = 1;
                chance = parsedSpawnChance.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);
            }
            else if (!string.IsNullOrWhiteSpace(chance))
            {
                chance = "1";
            }

            var delay = row.DelayTb.Text?.Trim() ?? "";
            var waterProtoUnit = row.WaterProtoUnitAcb.Text?.Trim() ?? "";
            waterProtoUnit = CanonicalizeKnownOrExisting(
                waterProtoUnit,
                validSpawnProtoUnits,
                (string?)originalSpawn?.Attribute("waterProtoUnit"));
            var shadingType = row.ShadingTypeCb.Value;
            shadingType = PreserveStrictCommittedValue(shadingType, KnownInitialShadingTypes);
            shadingType = ProtoConstants.GetShadingTypeXmlValue(shadingType);

            var spawn = new XElement("spawn", spawnProtoUnit);
            spawn.SetAttributeValue("type", spawnType);
            spawn.SetAttributeValue("count", count);
            if (!string.IsNullOrWhiteSpace(lifespan))
                spawn.SetAttributeValue("lifespan", lifespan);
            if (!string.IsNullOrWhiteSpace(chance))
                spawn.SetAttributeValue("chance", chance);
            if (!string.IsNullOrWhiteSpace(delay))
                spawn.SetAttributeValue("delay", delay);
            if (row.SkipPlacementCheckCb.IsChecked == true)
                spawn.SetAttributeValue("skipPlacementCheck", "");
            if (row.ControlGroupCb.IsChecked == true)
                spawn.SetAttributeValue("controlGroup", "");
            if (!string.IsNullOrWhiteSpace(waterProtoUnit))
                spawn.SetAttributeValue("waterProtoUnit", waterProtoUnit);
            if (row.SetOwnerCb.IsChecked == true)
                spawn.SetAttributeValue("setowner", "");
            if (!string.IsNullOrWhiteSpace(shadingType))
                spawn.SetAttributeValue("shadingtype", shadingType);

            unit.Add(spawn);
        }

        unit.Elements("respawntraindata").Remove();
        var originalRespawnTrainData = originalUnit.Element("respawntraindata");
        var respawnMode = _fieldControls.TryGetValue("respawntraindata.mode", out var respawnModeCtrl) && respawnModeCtrl is ComboBox respawnModeCb
            ? (respawnModeCb.SelectedItem as string ?? "Self Respawn")
            : "";
        if (!string.IsNullOrWhiteSpace(respawnMode))
        {
            var respawnTrainData = new XElement("respawntraindata");
            if (respawnMode.Equals("Self Respawn", StringComparison.OrdinalIgnoreCase))
            {
                var targetType = _fieldControls.TryGetValue("respawntraindata.targettype", out var targetTypeCtrl) && targetTypeCtrl is AutoCompleteBox targetTypeAcb
                    ? targetTypeAcb.Text?.Trim() ?? ""
                    : "";
                var trainProto = _fieldControls.TryGetValue("respawntraindata.trainproto", out var trainProtoCtrl) && trainProtoCtrl is AutoCompleteBox trainProtoAcb
                    ? trainProtoAcb.Text?.Trim() ?? ""
                    : "";
                var respawnTime = _fieldControls.TryGetValue("respawntraindata.respawntime", out var respawnTimeCtrl) && respawnTimeCtrl is TextBox respawnTimeTb
                    ? respawnTimeTb.Text?.Trim() ?? ""
                    : "";
                var respawnVfx = _fieldControls.TryGetValue("respawntraindata.respawnvfx", out var respawnVfxCtrl) && respawnVfxCtrl is AutoCompleteBox respawnVfxAcb
                    ? respawnVfxAcb.Text?.Trim() ?? ""
                    : "";

                targetType = CanonicalizeKnownOrExisting(
                    targetType,
                    GetAvailableBuildLimitTargets(),
                    originalRespawnTrainData?.Element("targettype")?.Value);
                trainProto = CanonicalizeKnownOrExisting(
                    trainProto,
                    validSpawnProtoUnits,
                    originalRespawnTrainData?.Element("trainproto")?.Value);
                respawnVfx = CanonicalizeKnownOrExisting(
                    respawnVfx,
                    validSpawnProtoUnits,
                    originalRespawnTrainData?.Element("respawnvfx")?.Value);

                if (!string.IsNullOrWhiteSpace(targetType) && !string.IsNullOrWhiteSpace(trainProto))
                {
                    respawnTrainData.Add(new XElement("targettype", targetType));
                    respawnTrainData.Add(new XElement("trainproto", trainProto));
                    if (!string.IsNullOrWhiteSpace(respawnTime))
                        respawnTrainData.Add(new XElement("respawntime", respawnTime));
                    if (!string.IsNullOrWhiteSpace(respawnVfx))
                        respawnTrainData.Add(new XElement("respawnvfx", respawnVfx));
                }
            }
            else if (respawnMode.Equals("Respawn Point", StringComparison.OrdinalIgnoreCase) &&
                     _currentRespawnTrainTypes != null &&
                     _currentRespawnTrainTypes.Count > 0)
            {
                respawnTrainData.Add(new XElement("respawntypes",
                    _currentRespawnTrainTypes
                        .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                        .Select(x => new XElement("unittype", x))));

                if (_currentRespawnTrainExcludeTypes != null && _currentRespawnTrainExcludeTypes.Count > 0)
                {
                    respawnTrainData.Add(new XElement("excludetypes",
                        _currentRespawnTrainExcludeTypes
                            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                            .Select(x => new XElement("unittype", x))));
                }

                var respawnRates = new XElement("respawnrates");
                foreach (var resourceType in ProtoConstants.KnownResourceTypes)
                {
                    var resourceKey = resourceType.ToLowerInvariant();
                    var value = _fieldControls.TryGetValue($"respawntraindata.{resourceKey}", out var rateCtrl) && rateCtrl is TextBox rateTb
                        ? rateTb.Text?.Trim() ?? "0"
                        : "0";
                    respawnRates.Add(new XElement(resourceKey, string.IsNullOrWhiteSpace(value) ? "0" : value));
                }
                respawnTrainData.Add(respawnRates);

                var respawnLimit = _fieldControls.TryGetValue("respawntraindata.respawnlimit", out var respawnLimitCtrl) && respawnLimitCtrl is TextBox respawnLimitTb
                    ? respawnLimitTb.Text?.Trim() ?? ""
                    : "";
                if (!string.IsNullOrWhiteSpace(respawnLimit))
                    respawnTrainData.Add(new XElement("respawnlimit", respawnLimit));

                var respawnVfx = _fieldControls.TryGetValue("respawntraindata.respawnvfx", out var respawnPointVfxCtrl) && respawnPointVfxCtrl is AutoCompleteBox respawnPointVfxAcb
                    ? respawnPointVfxAcb.Text?.Trim() ?? ""
                    : "";
                respawnVfx = CanonicalizeKnownOrExisting(
                    respawnVfx,
                    validSpawnProtoUnits,
                    originalRespawnTrainData?.Element("respawnvfx")?.Value);
                if (!string.IsNullOrWhiteSpace(respawnVfx))
                    respawnTrainData.Add(new XElement("respawnvfx", respawnVfx));
            }

            if (respawnTrainData.HasElements)
                unit.Add(respawnTrainData);
        }

        void SaveOptionalSimpleField(string tag)
        {
            if (_fieldControls.TryGetValue(tag, out var ctrl))
            {
                var value = ctrl switch
                {
                    TextBox tb => tb.Text?.Trim() ?? "",
                    AutoCompleteBox acb => acb.Text?.Trim() ?? "",
                    _ => ""
                };

                if (tag.Equals("farmingnumstops", StringComparison.OrdinalIgnoreCase))
                {
                    if (string.IsNullOrWhiteSpace(value))
                    {
                        value = "8";
                    }
                    else if (int.TryParse(value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedStops))
                    {
                        if (parsedStops < 2)
                            parsedStops = 2;
                        value = parsedStops.ToString();
                    }
                    else
                    {
                        value = "8";
                    }
                }

                if (!string.IsNullOrWhiteSpace(value))
                    ProtoXmlHandler.SetSimpleField(unit, tag, value);
                else
                    ProtoXmlHandler.RemoveSimpleField(unit, tag);
            }
            else
            {
                ProtoXmlHandler.RemoveSimpleField(unit, tag);
            }
        }

        foreach (var tag in new[]
                 {
                     "selectionradiusx", "selectionradiusz", "placementobstructionradiusx", "placementobstructionradiusz",
                     "initialshieldpoints", "maxshieldpoints", "farmingradiusx", "farmingradiusz",
                     "farmingobstructionradiusx", "farmingobstructionradiusz", "farmingnumstops"
                 })
        {
            SaveOptionalSimpleField(tag);
        }

        var unitRegenValue = _fieldControls.TryGetValue("unitregen", out var unitRegenCtrl) && unitRegenCtrl is TextBox unitRegenTb
            ? unitRegenTb.Text?.Trim() ?? ""
            : "";
        var unitRegenIdleTimeout = _fieldControls.TryGetValue("unitregen.idleTimeout", out var unitRegenIdleCtrl) && unitRegenIdleCtrl is TextBox unitRegenIdleTb
            ? unitRegenIdleTb.Text?.Trim() ?? ""
            : "";
        var unitRegenDamageTimeout = _fieldControls.TryGetValue("unitregen.damageTimeout", out var unitRegenDamageCtrl) && unitRegenDamageCtrl is TextBox unitRegenDamageTb
            ? unitRegenDamageTb.Text?.Trim() ?? ""
            : "";
        var unitRegenCombatMultiplier = _fieldControls.TryGetValue("unitregen.combatMultiplier", out var unitRegenCombatCtrl) && unitRegenCombatCtrl is TextBox unitRegenCombatTb
            ? unitRegenCombatTb.Text?.Trim() ?? ""
            : "";
        var unitRegenRateLimit = _fieldControls.TryGetValue("unitregen.ratelimit", out var unitRegenRateLimitCtrl) && unitRegenRateLimitCtrl is TextBox unitRegenRateLimitTb
            ? unitRegenRateLimitTb.Text?.Trim() ?? ""
            : "";

        if (string.IsNullOrWhiteSpace(unitRegenValue) &&
            (!string.IsNullOrWhiteSpace(unitRegenIdleTimeout) ||
             !string.IsNullOrWhiteSpace(unitRegenDamageTimeout) ||
             !string.IsNullOrWhiteSpace(unitRegenCombatMultiplier) ||
             !string.IsNullOrWhiteSpace(unitRegenRateLimit)))
        {
            unitRegenValue = "0";
        }

        if (!string.IsNullOrWhiteSpace(unitRegenRateLimit) && double.TryParse(unitRegenRateLimit, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsedRateLimit))
        {
            if (parsedRateLimit < 0) parsedRateLimit = 0;
            if (parsedRateLimit > 1) parsedRateLimit = 1;
            unitRegenRateLimit = parsedRateLimit.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);
        }

        unit.Elements("unitregen").Remove();
        if (!string.IsNullOrWhiteSpace(unitRegenValue))
        {
            var unitRegenElement = new XElement("unitregen", unitRegenValue);
            if (!string.IsNullOrWhiteSpace(unitRegenIdleTimeout))
                unitRegenElement.SetAttributeValue("idletimeout", unitRegenIdleTimeout);
            if (!string.IsNullOrWhiteSpace(unitRegenDamageTimeout))
                unitRegenElement.SetAttributeValue("damagetimeout", unitRegenDamageTimeout);
            if (!string.IsNullOrWhiteSpace(unitRegenCombatMultiplier))
                unitRegenElement.SetAttributeValue("combatmultiplier", unitRegenCombatMultiplier);
            if (!string.IsNullOrWhiteSpace(unitRegenRateLimit))
                unitRegenElement.SetAttributeValue("ratelimit", unitRegenRateLimit);

            var insertAfter = unit.Elements().FirstOrDefault(x => x.Name.LocalName.Equals("maxhitpoints", StringComparison.OrdinalIgnoreCase));
            if (insertAfter != null)
                insertAfter.AddAfterSelf(unitRegenElement);
            else
                unit.Add(unitRegenElement);
        }

        var unitShieldRegenValue = _fieldControls.TryGetValue("unitshieldregen", out var unitShieldRegenCtrl) && unitShieldRegenCtrl is TextBox unitShieldRegenTb
            ? unitShieldRegenTb.Text?.Trim() ?? ""
            : "";
        var unitShieldRegenIdleTimeout = _fieldControls.TryGetValue("unitshieldregen.idletimeout", out var unitShieldRegenIdleCtrl) && unitShieldRegenIdleCtrl is TextBox unitShieldRegenIdleTb
            ? unitShieldRegenIdleTb.Text?.Trim() ?? ""
            : "";
        var unitShieldRegenDamageTimeout = _fieldControls.TryGetValue("unitshieldregen.damagetimeout", out var unitShieldRegenDamageCtrl) && unitShieldRegenDamageCtrl is TextBox unitShieldRegenDamageTb
            ? unitShieldRegenDamageTb.Text?.Trim() ?? ""
            : "";
        var unitShieldRegenCombatMultiplier = _fieldControls.TryGetValue("unitshieldregen.combatmultiplier", out var unitShieldRegenCombatCtrl) && unitShieldRegenCombatCtrl is TextBox unitShieldRegenCombatTb
            ? unitShieldRegenCombatTb.Text?.Trim() ?? ""
            : "";
        var unitShieldRegenRateLimit = _fieldControls.TryGetValue("unitshieldregen.ratelimit", out var unitShieldRegenRateLimitCtrl) && unitShieldRegenRateLimitCtrl is TextBox unitShieldRegenRateLimitTb
            ? unitShieldRegenRateLimitTb.Text?.Trim() ?? ""
            : "";

        if (string.IsNullOrWhiteSpace(unitShieldRegenValue) &&
            (!string.IsNullOrWhiteSpace(unitShieldRegenIdleTimeout) ||
             !string.IsNullOrWhiteSpace(unitShieldRegenDamageTimeout) ||
             !string.IsNullOrWhiteSpace(unitShieldRegenCombatMultiplier) ||
             !string.IsNullOrWhiteSpace(unitShieldRegenRateLimit)))
        {
            unitShieldRegenValue = "0";
        }

        if (!string.IsNullOrWhiteSpace(unitShieldRegenRateLimit) && double.TryParse(unitShieldRegenRateLimit, NumberStyles.Float, CultureInfo.InvariantCulture, out var parsedShieldRateLimit))
        {
            if (parsedShieldRateLimit < 0) parsedShieldRateLimit = 0;
            if (parsedShieldRateLimit > 1) parsedShieldRateLimit = 1;
            unitShieldRegenRateLimit = parsedShieldRateLimit.ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);
        }

        unit.Elements("unitshieldregen").Remove();
        if (!string.IsNullOrWhiteSpace(unitShieldRegenValue))
        {
            var unitShieldRegenElement = new XElement("unitshieldregen", unitShieldRegenValue);
            if (!string.IsNullOrWhiteSpace(unitShieldRegenIdleTimeout))
                unitShieldRegenElement.SetAttributeValue("idletimeout", unitShieldRegenIdleTimeout);
            if (!string.IsNullOrWhiteSpace(unitShieldRegenDamageTimeout))
                unitShieldRegenElement.SetAttributeValue("damagetimeout", unitShieldRegenDamageTimeout);
            if (!string.IsNullOrWhiteSpace(unitShieldRegenCombatMultiplier))
                unitShieldRegenElement.SetAttributeValue("combatmultiplier", unitShieldRegenCombatMultiplier);
            if (!string.IsNullOrWhiteSpace(unitShieldRegenRateLimit))
                unitShieldRegenElement.SetAttributeValue("ratelimit", unitShieldRegenRateLimit);

            var insertAfterShield = unit.Elements().FirstOrDefault(x => x.Name.LocalName.Equals("initialshieldpoints", StringComparison.OrdinalIgnoreCase))
                ?? unit.Elements().FirstOrDefault(x => x.Name.LocalName.Equals("maxshieldpoints", StringComparison.OrdinalIgnoreCase))
                ?? unit.Elements().FirstOrDefault(x => x.Name.LocalName.Equals("unitregen", StringComparison.OrdinalIgnoreCase))
                ?? unit.Elements().FirstOrDefault(x => x.Name.LocalName.Equals("maxhitpoints", StringComparison.OrdinalIgnoreCase));
            if (insertAfterShield != null)
                insertAfterShield.AddAfterSelf(unitShieldRegenElement);
            else
                unit.Add(unitShieldRegenElement);
        }

        void SaveResourceMap(string elementName)
        {
            var entries = new List<(string ResourceType, string Value, string DropOffMultiplier)>();
            foreach (var resourceType in ProtoConstants.KnownResourceTypes)
            {
                if (_fieldControls.TryGetValue($"{elementName}:{resourceType}", out var ctrl) && ctrl is TextBox tb)
                {
                    var value = tb.Text?.Trim() ?? "";
                    var multiplier = elementName.Equals("carrycapacity", StringComparison.OrdinalIgnoreCase) &&
                                     _fieldControls.TryGetValue($"{elementName}:dropoffmultiplier:{resourceType}", out var multiplierCtrl) &&
                                     multiplierCtrl is TextBox multiplierTb
                        ? multiplierTb.Text?.Trim() ?? ""
                        : "";
                    entries.Add((resourceType, value, multiplier));
                }
            }
            ProtoXmlHandler.SetResourceMapEntries(
                unit,
                elementName,
                entries,
                omitZeroValues: elementName.Equals("carrycapacity", StringComparison.OrdinalIgnoreCase) ||
                                elementName.Equals("initialresource", StringComparison.OrdinalIgnoreCase));
        }

        SaveResourceMap("carrycapacity");
        SaveResourceMap("initialresource");
        unit.Elements("resourceconversion").Remove();
        foreach (var row in _resourceConversionRows)
        {
            var fromResource = row.FromResourceCb.SelectedItem as string ?? row.FromResourceCb.SelectedValue as string ?? "";
            var toResource = row.ToResourceCb.SelectedItem as string ?? row.ToResourceCb.SelectedValue as string ?? "";
            var value = row.ValueTb.Text?.Trim() ?? "";
            if (string.IsNullOrWhiteSpace(fromResource) || string.IsNullOrWhiteSpace(toResource) || string.IsNullOrWhiteSpace(value))
                continue;

            unit.Add(new XElement("resourceconversion",
                new XAttribute("fromresourcetype", fromResource),
                new XAttribute("toresourcetype", toResource),
                value));
        }

        void SaveUnitTypeListElement(string elementName, HashSet<string>? values)
        {
            unit.Element(elementName)?.Remove();
            if (values == null || values.Count == 0)
                return;

            unit.Add(new XElement(elementName, values.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).Select(x => new XElement("unittype", x))));
        }

        SaveUnitTypeListElement("sharedselectionunittypes", _currentSharedSelectionUnitTypes);

        if (_fieldControls.TryGetValue("decay.delay", out var decayDelayCtrl) && decayDelayCtrl is TextBox decayDelayTb &&
            _fieldControls.TryGetValue("decay.duration", out var decayDurationCtrl) && decayDurationCtrl is TextBox decayDurationTb)
        {
            var delay = decayDelayTb.Text?.Trim() ?? "";
            var duration = decayDurationTb.Text?.Trim() ?? "";
            unit.Element("decay")?.Remove();
            if (!string.IsNullOrWhiteSpace(delay) || !string.IsNullOrWhiteSpace(duration))
            {
                var decayElement = new XElement("decay");
                if (!string.IsNullOrWhiteSpace(delay))
                    decayElement.SetAttributeValue("delay", delay);
                if (!string.IsNullOrWhiteSpace(duration))
                    decayElement.SetAttributeValue("duration", duration);
                unit.Add(decayElement);
            }
        }
        else
        {
            unit.Element("decay")?.Remove();
        }

        var abilityUsesMainRecharge = _abilityDrafts.Values.Any(draft =>
            draft.GeneralFlags.Contains("chargetimeasrof") || draft.GeneralFlags.Contains("bindtochargeaction"));
        if (_fieldControls.TryGetValue("recharge.mode", out var rechargeModeCtrl) && rechargeModeCtrl is ComboBox rechargeModeCb)
        {
            unit.Element("rechargetime")?.Remove();
            unit.Element("recharge")?.Remove();
            unit.Element("rechargeincludetypes")?.Remove();
            unit.Element("rechargeexcludetypes")?.Remove();
            var rechargeMode = rechargeModeCb.SelectedItem as string ?? "Time";
            var rechargeValue = _fieldControls.TryGetValue("recharge.value", out var rechargeValueCtrl) && rechargeValueCtrl is TextBox rechargeValueTb
                ? rechargeValueTb.Text?.Trim() ?? ""
                : "";
            var rechargeInit = "";
            if (_fieldControls.TryGetValue("recharge.init", out var rechargeInitCtrl))
            {
                rechargeInit = rechargeInitCtrl switch
                {
                    CheckBox startChargedCb => startChargedCb.IsChecked == false ? "0" : "",
                    TextBox rechargeInitTb => string.IsNullOrWhiteSpace(rechargeInitTb.Text) ? "1" : rechargeInitTb.Text.Trim(),
                    _ => ""
                };
            }

            if (rechargeMode.Equals("Time", StringComparison.OrdinalIgnoreCase))
            {
                if (!string.IsNullOrWhiteSpace(rechargeValue))
                {
                    var rechargeTimeElement = new XElement("rechargetime", rechargeValue);
                    if (!string.IsNullOrWhiteSpace(rechargeInit))
                        rechargeTimeElement.SetAttributeValue("init", rechargeInit);
                    unit.Add(rechargeTimeElement);
                }
            }
            else
            {
                var validRechargeType = CanonicalizeKnownOrExisting(
                    rechargeMode,
                    ProtoConstants.KnownRechargeTypes,
                    (string?)originalUnit.Element("recharge")?.Attribute("type"));
                if (!string.IsNullOrWhiteSpace(rechargeValue) && !string.IsNullOrWhiteSpace(validRechargeType))
                {
                    var rechargeElement = new XElement("recharge", rechargeValue);
                    rechargeElement.SetAttributeValue("type", validRechargeType);
                    if (!string.IsNullOrWhiteSpace(rechargeInit))
                        rechargeElement.SetAttributeValue("init", rechargeInit);
                    unit.Add(rechargeElement);

                    SaveUnitTypeListElement("rechargeincludetypes", _currentRechargeIncludeTypes);
                    SaveUnitTypeListElement("rechargeexcludetypes", _currentRechargeExcludeTypes);
                }
            }
        }
        else if (_abilityDrafts.Count > 0 && !abilityUsesMainRecharge)
        {
            unit.Element("rechargetime")?.Remove();
            unit.Element("recharge")?.Remove();
            unit.Element("rechargeincludetypes")?.Remove();
            unit.Element("rechargeexcludetypes")?.Remove();
        }

        var abilityUsesAuxRecharge = _abilityDrafts.Values.Any(draft =>
            draft.GeneralFlags.Contains("auxchargetimeasrof") || draft.GeneralFlags.Contains("bindtoauxchargeaction"));
        if (_fieldControls.TryGetValue("auxrecharge.mode", out var auxRechargeModeCtrl) && auxRechargeModeCtrl is ComboBox auxRechargeModeCb)
        {
            unit.Element("auxrechargetime")?.Remove();
            unit.Element("auxrecharge")?.Remove();
            unit.Element("auxrechargeincludetypes")?.Remove();
            unit.Element("auxrechargeexcludetypes")?.Remove();
            var auxRechargeMode = auxRechargeModeCb.SelectedItem as string ?? "Time";
            var auxRechargeValue = _fieldControls.TryGetValue("auxrecharge.value", out var auxRechargeValueCtrl) && auxRechargeValueCtrl is TextBox auxRechargeValueTb
                ? auxRechargeValueTb.Text?.Trim() ?? ""
                : "";
            var auxRechargeInit = "";
            if (_fieldControls.TryGetValue("auxrecharge.init", out var auxRechargeInitCtrl))
            {
                auxRechargeInit = auxRechargeInitCtrl switch
                {
                    CheckBox startChargedCb => startChargedCb.IsChecked == false ? "0" : "",
                    TextBox auxRechargeInitTb => string.IsNullOrWhiteSpace(auxRechargeInitTb.Text) ? "1" : auxRechargeInitTb.Text.Trim(),
                    _ => ""
                };
            }

            if (auxRechargeMode.Equals("Time", StringComparison.OrdinalIgnoreCase))
            {
                if (!string.IsNullOrWhiteSpace(auxRechargeValue))
                {
                    var auxRechargeTimeElement = new XElement("auxrechargetime", auxRechargeValue);
                    if (!string.IsNullOrWhiteSpace(auxRechargeInit))
                        auxRechargeTimeElement.SetAttributeValue("init", auxRechargeInit);
                    unit.Add(auxRechargeTimeElement);
                }
            }
            else
            {
                var validAuxRechargeType = CanonicalizeKnownOrExisting(
                    auxRechargeMode,
                    ProtoConstants.KnownRechargeTypes,
                    (string?)originalUnit.Element("auxrecharge")?.Attribute("type"));
                if (!string.IsNullOrWhiteSpace(auxRechargeValue) && !string.IsNullOrWhiteSpace(validAuxRechargeType))
                {
                    var auxRechargeElement = new XElement("auxrecharge", auxRechargeValue);
                    auxRechargeElement.SetAttributeValue("type", validAuxRechargeType);
                    if (!string.IsNullOrWhiteSpace(auxRechargeInit))
                        auxRechargeElement.SetAttributeValue("init", auxRechargeInit);
                    unit.Add(auxRechargeElement);

                    SaveUnitTypeListElement("auxrechargeincludetypes", _currentAuxRechargeIncludeTypes);
                    SaveUnitTypeListElement("auxrechargeexcludetypes", _currentAuxRechargeExcludeTypes);
                }
            }
        }
        else if (_abilityDrafts.Count > 0 && !abilityUsesAuxRecharge)
        {
            unit.Element("auxrechargetime")?.Remove();
            unit.Element("auxrecharge")?.Remove();
            unit.Element("auxrechargeincludetypes")?.Remove();
            unit.Element("auxrechargeexcludetypes")?.Remove();
        }

        if (_fieldControls.TryGetValue("minimapcolor.red", out var redCtrl) && redCtrl is TextBox redTb)
        {
            unit.Element("minimapcolor")?.Remove();
            var red = redTb.Text?.Trim() ?? "";
            var green = _fieldControls.TryGetValue("minimapcolor.green", out var greenCtrl) && greenCtrl is TextBox greenTb
                ? greenTb.Text?.Trim() ?? ""
                : "";
            var blue = _fieldControls.TryGetValue("minimapcolor.blue", out var blueCtrl) && blueCtrl is TextBox blueTb
                ? blueTb.Text?.Trim() ?? ""
                : "";
            if (!string.IsNullOrWhiteSpace(red) || !string.IsNullOrWhiteSpace(green) || !string.IsNullOrWhiteSpace(blue))
            {
                var minimapColor = new XElement("minimapcolor");
                if (!string.IsNullOrWhiteSpace(red))
                    minimapColor.SetAttributeValue("red", red);
                if (!string.IsNullOrWhiteSpace(green))
                    minimapColor.SetAttributeValue("green", green);
                if (!string.IsNullOrWhiteSpace(blue))
                    minimapColor.SetAttributeValue("blue", blue);
                unit.Add(minimapColor);
            }
        }
        else
        {
            unit.Element("minimapcolor")?.Remove();
        }

        if (_fieldControls.TryGetValue("minimapicon", out var minimapIconCtrl) && minimapIconCtrl is AutoCompleteBox minimapIconAcb)
        {
            var minimapIcon = minimapIconAcb.Text?.Trim() ?? "";
            var knownMinimapIcon = GetKnownMinimapIcons().FirstOrDefault(x => x.Equals(minimapIcon, StringComparison.OrdinalIgnoreCase));
            if (!string.IsNullOrWhiteSpace(knownMinimapIcon))
                minimapIcon = knownMinimapIcon;
            if (!string.IsNullOrWhiteSpace(minimapIcon))
                ProtoXmlHandler.SetSimpleField(unit, "minimapicon", minimapIcon);
            else
                ProtoXmlHandler.RemoveSimpleField(unit, "minimapicon");
        }
        else
        {
            ProtoXmlHandler.RemoveSimpleField(unit, "minimapicon");
        }

        if (_fieldControls.TryGetValue("minimapsize", out var minimapSizeCtrl) && minimapSizeCtrl is TextBox minimapSizeTb)
        {
            var minimapSize = minimapSizeTb.Text?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(minimapSize))
                ProtoXmlHandler.SetSimpleField(unit, "minimapsize", minimapSize);
            else
                ProtoXmlHandler.RemoveSimpleField(unit, "minimapsize");
        }
        else
        {
            ProtoXmlHandler.RemoveSimpleField(unit, "minimapsize");
        }

        if (_fieldControls.TryGetValue("replacement.value", out var replacementValueCtrl) && replacementValueCtrl is AutoCompleteBox replacementValueAcb)
        {
            unit.Element("replacement")?.Remove();
            var value = replacementValueAcb.Text?.Trim() ?? "";
            var type = _fieldControls.TryGetValue("replacement.type", out var replacementTypeCtrl) && replacementTypeCtrl is StrictSearchableComboBox replacementTypeCb
                ? replacementTypeCb.Value
                : "";
            type = PreserveStrictCommittedValue(type, ProtoConstants.KnownReplacementTypes);
            value = CanonicalizeKnownOrExisting(
                value,
                GetAvailableTrainUnitNames(),
                originalUnit.Element("replacement")?.Value);
            var lifespan = _fieldControls.TryGetValue("replacement.lifespan", out var replacementLifespanCtrl) && replacementLifespanCtrl is TextBox replacementLifespanTb
                ? replacementLifespanTb.Text?.Trim() ?? ""
                : "";
            if (!string.IsNullOrWhiteSpace(value))
            {
                var replacement = new XElement("replacement", value);
                if (!string.IsNullOrWhiteSpace(type))
                    replacement.SetAttributeValue("type", type);
                if (!string.IsNullOrWhiteSpace(lifespan))
                    replacement.SetAttributeValue("lifespan", lifespan);
                unit.Add(replacement);
            }
        }
        else
        {
            unit.Element("replacement")?.Remove();
        }

        foreach (var tag in CultureAwareSimpleFieldTags)
        {
            var entries = new List<ProtoCultureFieldEntry>();

            if (_fieldControls.TryGetValue(tag, out var ctrl) && ctrl is AssetPathEditor defaultAcb)
            {
                var defaultValue = defaultAcb.FullValue;
                if (!string.IsNullOrWhiteSpace(defaultValue))
                    entries.Add(new ProtoCultureFieldEntry { Value = defaultValue });
            }

            if (_cultureFieldRows.TryGetValue(tag, out var rows))
            {
                foreach (var row in rows)
                {
                    var cultureLabel = row.CultureCb.SelectedItem as string ?? row.CultureCb.SelectedValue as string ?? "";
                    var cultureValue = GetCultureValue(cultureLabel);
                    var value = row.ValueEditor.FullValue;
                    if (!string.IsNullOrWhiteSpace(cultureValue) && !string.IsNullOrWhiteSpace(value))
                    {
                        entries.Add(new ProtoCultureFieldEntry
                        {
                            Culture = cultureValue,
                            Value = value
                        });
                    }
                }
            }

            ProtoXmlHandler.SetCultureAwareSimpleFields(
                unit,
                tag,
                entries
                    .GroupBy(x => x.Culture, StringComparer.OrdinalIgnoreCase)
                    .Select(g => g.First()));
        }

        foreach (var tag in StringBackedFieldTags)
        {
            if (!_fieldControls.TryGetValue(tag, out var ctrl) || ctrl is not TextBox tb)
                continue;

            var id = _currentStringFieldIds.GetValueOrDefault(tag);
            if (!string.IsNullOrWhiteSpace(id))
                ProtoXmlHandler.SetSimpleField(unit, tag, id);
            else
                ProtoXmlHandler.RemoveSimpleField(unit, tag);
        }

        var uniqueTransformState = _transformCommandAssignments.UniqueAssignment;
        if (uniqueTransformState != null && !string.IsNullOrWhiteSpace(uniqueTransformState.CommandName))
        {
            ProtoXmlHandler.SetTransformCommandEntry(unit, new ProtoCommandEntry
            {
                Value = uniqueTransformState.CommandName.Trim()
            });
        }
        else
        {
            ProtoXmlHandler.SetTransformCommandEntry(unit, null);
        }

        if (_fieldControls.TryGetValue("maxcontained", out var maxContainedCtrl) && maxContainedCtrl is TextBox maxContainedTb)
        {
            var maxContained = maxContainedTb.Text?.Trim() ?? "";
            if (!string.IsNullOrWhiteSpace(maxContained))
                ProtoXmlHandler.SetSimpleField(unit, "maxcontained", maxContained);
            else
                ProtoXmlHandler.RemoveSimpleField(unit, "maxcontained");

            ProtoXmlHandler.SetContainList(
                unit,
                _currentContains != null
                    ? _currentContains.OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    : Enumerable.Empty<string>(),
                _fieldControls.TryGetValue("contain.external", out var containExternalControl) &&
                containExternalControl is CheckBox { IsChecked: true });
            ProtoXmlHandler.SetNotContainList(
                unit,
                _currentNotContains != null
                    ? _currentNotContains.OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
                    : Enumerable.Empty<string>());

            void SaveContainBonusField(string tag)
            {
                if (_fieldControls.TryGetValue(tag, out var ctrl) && ctrl is TextBox tb)
                {
                    var value = tb.Text?.Trim() ?? "";
                    if (!string.IsNullOrWhiteSpace(value))
                        ProtoXmlHandler.SetSimpleField(unit, tag, value);
                    else
                        ProtoXmlHandler.RemoveSimpleField(unit, tag);
                }
                else
                {
                    ProtoXmlHandler.RemoveSimpleField(unit, tag);
                }
            }

            SaveContainBonusField("containedhitpointbonus");
            SaveContainBonusField("containedspeedbonus");
            SaveContainBonusField("containedregenrate");
        }
        else
        {
            ProtoXmlHandler.RemoveSimpleField(unit, "maxcontained");
            ProtoXmlHandler.SetContainList(unit, []);
            ProtoXmlHandler.SetNotContainList(unit, []);
            ProtoXmlHandler.RemoveSimpleField(unit, "containedhitpointbonus");
            ProtoXmlHandler.RemoveSimpleField(unit, "containedspeedbonus");
            ProtoXmlHandler.RemoveSimpleField(unit, "containedregenrate");
        }

        if (_fieldControls.TryGetValue("buildlimit", out var blCtrl) && blCtrl is TextBox blTb)
        {
            string val = blTb.Text?.Trim() ?? "";
            if (!string.IsNullOrEmpty(val))
            {
                ProtoXmlHandler.SetSimpleField(unit, "buildlimit", val);
                var validBuildLimitTargets = GetAvailableBuildLimitTargets();
                var normalizedBuildLimitEntries = _buildLimitRows
                    .Select(row =>
                    {
                        var input = row.ValueAcb.Text?.Trim() ?? "";
                        var value = validBuildLimitTargets.FirstOrDefault(x => x.Equals(input, StringComparison.OrdinalIgnoreCase)) ?? "";
                        var weight = row.WeightTb?.Text?.Trim() ?? "";
                        if (row.WeightTb != null)
                        {
                            if (string.IsNullOrWhiteSpace(weight))
                            {
                                weight = "1";
                            }
                            else if (double.TryParse(weight, NumberStyles.Float, CultureInfo.InvariantCulture, out double parsedWeight) && parsedWeight < 0)
                            {
                                weight = "0";
                            }
                        }

                        return new ProtoBuildLimitEntry
                        {
                            Value = value,
                            Weight = weight
                        };
                    })
                    .Where(x => !string.IsNullOrWhiteSpace(x.Value))
                    .GroupBy(x => x.Value, StringComparer.OrdinalIgnoreCase)
                    .Select(g => g.First())
                    .ToList();

                switch (_currentBuildLimitMode)
                {
                    case BuildLimitMode.Dynamic:
                        ProtoXmlHandler.SetDynamicBuildLimitUnitTypes(unit, normalizedBuildLimitEntries.Select(x => x.Value));
                        ProtoXmlHandler.SetSharedBuildLimitEntries(unit, []);
                        _currentFlags?.Remove("UseSharedBuildLimit");
                        break;
                    case BuildLimitMode.Shared:
                        ProtoXmlHandler.SetDynamicBuildLimitUnitTypes(unit, []);
                        ProtoXmlHandler.SetSharedBuildLimitEntries(unit, normalizedBuildLimitEntries);
                        _currentFlags?.Add("UseSharedBuildLimit");
                        break;
                    default:
                        ProtoXmlHandler.RemoveBuildLimitModeElements(unit);
                        _currentFlags?.Remove("UseSharedBuildLimit");
                        break;
                }
            }
            else
            {
                ProtoXmlHandler.RemoveSimpleField(unit, "buildlimit");
                ProtoXmlHandler.RemoveBuildLimitModeElements(unit);
                _currentFlags?.Remove("UseSharedBuildLimit");
            }
        }
        else
        {
            ProtoXmlHandler.RemoveSimpleField(unit, "buildlimit");
            ProtoXmlHandler.RemoveBuildLimitModeElements(unit);
            _currentFlags?.Remove("UseSharedBuildLimit");
        }

        var costs = new List<(string ResourceType, string Amount)>();
        foreach (var kvp in _costControls)
        {
            costs.Add((kvp.Key, kvp.Value.Text?.Trim() ?? "0"));
        }
        ProtoXmlHandler.SetCostEntries(unit, costs);

        var armors = new List<(string ArmorType, string Value)>();
        foreach (var kvp in _armorControls)
        {
            var value = kvp.Value.Text?.Trim();
            if (string.IsNullOrWhiteSpace(value))
                value = "0";
            else if (double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out double num))
                value = Math.Clamp(num, 0, 1).ToString("0.####", System.Globalization.CultureInfo.InvariantCulture);
            else
                value = "0";

            armors.Add((kvp.Key, value));
        }
        ProtoXmlHandler.SetArmorEntries(unit, armors);

        if (_currentUnitTypes != null)
        {
            ProtoXmlHandler.SetUnitTypeList(unit, _currentUnitTypes.OrderBy(x => x));
        }

        if (_currentFlags != null)
        {
            if (HasReflectAttackProtoAction())
                _currentFlags.Add("HasReflectAttack");
            else
                _currentFlags.Remove("HasReflectAttack");

            if (HasAutoCastBySelfProtoAction())
                _currentFlags.Add("CastAbilitySelf");

            if (HasHealProtoAction())
                _currentFlags.Add("CanAutoHeal");
            else
                _currentFlags.Remove("CanAutoHeal");

            if (HasTradeAddAllyResourcesProtoAction())
                _currentFlags.Add("TradeAddAllyResources");
            else
                _currentFlags.Remove("TradeAddAllyResources");

            ProtoXmlHandler.SetFlagList(unit, _currentFlags.OrderBy(x => x));
        }

        ProtoXmlHandler.SetTrainEntries(unit, CollectValidCommandEntries(_trainCommandRows, GetAvailableTrainUnitNames()));
        ProtoXmlHandler.SetTechEntries(unit, CollectValidCommandEntries(_techCommandRows, GetAvailableTechNames()));
        var regularCommandNamesForSave = GetAvailableCommandNames()
            .Where(name => !IsTransformUniqueCommand(name) && !IsTransformMultipleCommand(name))
            .ToList();
        var commandEntries = CollectValidCommandEntries(_unitCommandRows, regularCommandNamesForSave);
        if (_containEjectCommandCheckBox != null)
        {
            commandEntries.RemoveAll(entry => entry.Value.Equals("Eject", StringComparison.OrdinalIgnoreCase));
            if (_containEjectCommandCheckBox.IsChecked == true)
            {
                commandEntries.Add(new ProtoCommandEntry
                {
                    Value = "Eject",
                    Row = "3",
                    Column = "1"
                });
            }
        }
        else if (_containRemovedDuringEdit)
        {
            commandEntries.RemoveAll(entry => entry.Value.Equals("Eject", StringComparison.OrdinalIgnoreCase));
        }
        commandEntries.AddRange(_transformCommandAssignments.BuildCommandEntries(
            IsTransformUniqueCommand,
            IsTransformMultipleCommand));
        ProtoXmlHandler.SetCommandEntries(unit, commandEntries);

        // Freeze every visible card before serializing any action. This prevents an
        // earlier action's save-side effects from changing controls read by a later one.
        foreach (var actionState in _protoActionWidgets)
        {
            var actionName = actionState.NameAcb.Text?.Trim() ?? "";
            var actionType = _protoActionHostAdapter.ResolveActionType(
                actionName,
                actionState.TypeAcb.Text,
                name => TryResolveProtoActionType(name, out var resolvedType) ? resolvedType : null,
                GetExactProtoActionTypeMatch);
            CaptureProtoActionDraftFromControls(
                actionState,
                actionType,
                preserveMissingDynamicCollections: false,
                consumePendingChargedElements: true);
        }

        var actionsList = new List<ProtoAction>();
        var selfDestructProtoActionName = "";
        var birthProtoActionName = "";
        var stackControlProtoActionName = "";
        foreach (var pw in _protoActionWidgets)
        {
            var pa = pw.Model.Clone();
            pa.Name = pw.Draft.Name;
            pa.Type = pw.Draft.Type;
            var tacticsAction = _protoActionHostAdapter.FindInheritedAction(
                pa.Name,
                name => TryGetCurrentUnitTacticsAction(name, out var matchedAction) ? matchedAction : null);

            pa.Damages.Clear();
            pa.DamageBonuses.Clear();
            var currentActionType = pa.Type?.Trim() ?? "";
            var draftSimpleValues = pw.Draft.CopySimpleValues();
            var draftStructuredValues = pw.Draft.CopyStructuredValues();
            var draftSelectedFlagTags = pw.Draft.CopySelectedFlagTags();
            var draftForcedVisibleFieldTags = pw.Draft.CopyForcedVisibleFieldTags();
            var draftCustomValues = pw.Draft.CopyCustomValues();
            var draftEmpowerSections = pw.Draft.CopyEmpowerSections();
            if (IsAttackActionType(currentActionType))
            {
                var attackMode = pw.Draft.AttackMode;
                if (attackMode.Equals("Self-Destruct Attack", StringComparison.OrdinalIgnoreCase))
                    selfDestructProtoActionName = pa.Name;
                else if (attackMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase))
                    birthProtoActionName = pa.Name;
            }
            if (IsStackControlActionType(currentActionType))
                stackControlProtoActionName = pa.Name;
            var effectiveAction = CreateEffectiveProtoActionSnapshot(
                pw.Model,
                pa.Name,
                currentActionType);
            var attackUsesCombatRanges = !IsAttackActionType(currentActionType) ||
                                        draftSelectedFlagTags.Contains("handlogic") ||
                                        draftSelectedFlagTags.Contains("rangedlogic");
            var showRof = attackUsesCombatRanges &&
                          draftCustomValues.GetValueOrDefault("additional.rof") != "1" &&
                          ShouldShowProtoActionHardcodedField(pw, effectiveAction, currentActionType, "rof");
            pa.Rof = showRof
                ? ResolveProtoOverrideValue(
                    pw.Draft.RateOfFire,
                    tacticsAction?.Rof ?? "",
                    pw.Model.Rof)
                : ResolveProtoOverrideValue(
                    "",
                    tacticsAction?.Rof ?? "",
                    pw.Model.Rof);
            var showMaxRange = attackUsesCombatRanges &&
                               draftCustomValues.GetValueOrDefault("additional.maxrange") != "1" &&
                               ShouldShowProtoActionHardcodedField(pw, effectiveAction, currentActionType, "maxrange");
            pa.MaxRange = showMaxRange
                ? ResolveProtoOverrideValue(
                    pw.Draft.MaxRange,
                    tacticsAction?.MaxRange ?? "",
                    pw.Model.MaxRange)
                : ResolveProtoOverrideValue(
                    "",
                    tacticsAction?.MaxRange ?? "",
                    pw.Model.MaxRange);

            if (IsMaulActionType(currentActionType))
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, "areaprotoaction", "AreaAttack");
            if (pw.IsLinkedAbductDropAction)
            {
                pa.Name = "AbductDrop";
                pa.Type = "Inline";
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, "isabductdrop", "1");
            }

            if (IsAttackActionType(currentActionType) &&
                pw.Draft.AttackMode.Equals("Birth Attack", StringComparison.OrdinalIgnoreCase))
            {
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, "castpowertargettype", "");
            }

            var usesStackControlEditor = IsStackControlActionType(currentActionType) ||
                                         draftForcedVisibleFieldTags.Contains("stackcontrol") ||
                                         draftSimpleValues.ContainsKey("stackmax") ||
                                         GetProtoActionAdditionalElement(pw.Model, "stackcontrol") != null;
            if (usesStackControlEditor)
            {
                var currentStackMax = draftSimpleValues.GetValueOrDefault("stackmax", "");
                var currentStackAddAction = draftSimpleValues.GetValueOrDefault("stackaddaction", "");
                var currentStackSubAction = draftSimpleValues.GetValueOrDefault("stacksubaction", "");

                var tacticsStackMax = tacticsAction != null ? GetProtoActionNestedChildValue(tacticsAction, "stackcontrol", "stackmax") : "";
                var tacticsStackAddAction = tacticsAction != null ? GetProtoActionNestedChildValue(tacticsAction, "stackcontrol", "stackaddaction") : "";
                var tacticsStackSubAction = tacticsAction != null ? GetProtoActionNestedChildValue(tacticsAction, "stackcontrol", "stacksubaction") : "";

                var originalStackMax = GetProtoActionNestedChildValue(pw.Model, "stackcontrol", "stackmax");
                var originalStackAddAction = GetProtoActionNestedChildValue(pw.Model, "stackcontrol", "stackaddaction");
                var originalStackSubAction = GetProtoActionNestedChildValue(pw.Model, "stackcontrol", "stacksubaction");

                if (!StackControlValuesEqual(
                        currentStackMax, currentStackAddAction, currentStackSubAction,
                        tacticsStackMax, tacticsStackAddAction, tacticsStackSubAction) ||
                    StackControlValuesEqual(
                        originalStackMax, originalStackAddAction, originalStackSubAction,
                        currentStackMax, currentStackAddAction, currentStackSubAction))
                {
                    SaveProtoActionStackControlElement(pa, currentStackMax, currentStackAddAction, currentStackSubAction);
                }
            }

            var currentModifyTypeForEmpower = draftSimpleValues.TryGetValue("modifytype", out var currentModifyType)
                ? ProtoConstants.GetModifyTypeValue(currentModifyType)
                : ProtoConstants.GetModifyTypeValue(ProtoXmlHandler.GetProtoActionSimpleFieldValue(pw.Model, "modifytype"));
            if (IsEmpowerActionType(currentActionType) ||
                (IsAutoRangedModifyActionType(currentActionType) &&
                 currentModifyTypeForEmpower.Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase)) ||
                EmpowerSectionTags.Any(tag =>
                    draftForcedVisibleFieldTags.Contains(tag) ||
                    draftEmpowerSections?.ContainsKey(tag) == true ||
                    GetProtoActionAdditionalElement(pw.Model, tag) != null))
            {
                var usesNativeEmpowerLayout = IsEmpowerActionType(currentActionType) ||
                                              (IsAutoRangedModifyActionType(currentActionType) &&
                                               currentModifyTypeForEmpower.Equals("AuraEmpower", StringComparison.OrdinalIgnoreCase));
                foreach (var sectionTag in EmpowerSectionTags.Where(tag =>
                             usesNativeEmpowerLayout ||
                             draftForcedVisibleFieldTags.Contains(tag) ||
                             draftEmpowerSections?.ContainsKey(tag) == true ||
                             GetProtoActionAdditionalElement(pw.Model, tag) != null))
                {
                    var currentSection = draftEmpowerSections?.TryGetValue(sectionTag, out var draftSection) == true
                        ? draftSection
                        : null;
                    var tacticsSection = tacticsAction != null ? GetProtoActionAdditionalElement(tacticsAction, sectionTag) : null;
                    var originalSection = GetProtoActionAdditionalElement(pw.Model, sectionTag);

                    RemoveProtoActionAdditionalElement(pa, sectionTag);
                    if (!EmpowerSectionElementsEqual(currentSection, tacticsSection) ||
                        EmpowerSectionElementsEqual(originalSection, currentSection))
                    {
                        SetProtoActionAdditionalElement(pa, sectionTag, currentSection);
                    }
                }
            }

            if (IsBolsterActionType(currentActionType))
            {
                var currentCharged = pw.Draft.CopyChargedElements() ?? [];
                var tacticsCharged = tacticsAction?.AdditionalElements
                    .Where(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase))
                    .Select(x => new XElement(x))
                    .ToList() ?? [];
                var originalCharged = pw.Model.AdditionalElements
                    .Where(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase))
                    .Select(x => new XElement(x))
                    .ToList();

                pa.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase));
                if (!ChargedElementsEqual(currentCharged, tacticsCharged) ||
                    ChargedElementsEqual(originalCharged, currentCharged))
                {
                    foreach (var element in currentCharged)
                        pa.AdditionalElements.Add(new XElement(element));
                }
            }

            var usesFullChargedEditor = !IsBolsterActionType(currentActionType) &&
                (IsChargedModifyActionType(currentActionType) ||
                 IsRampageActionType(currentActionType) ||
                 draftForcedVisibleFieldTags.Contains("charged") ||
                 (pw.Draft.FullChargedElements?.Count ?? 0) > 0 ||
                 pw.Model.AdditionalElements.Any(element =>
                     element.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase)));
            if (usesFullChargedEditor)
            {
                var currentCharged = pw.Draft.CopyFullChargedElements() ?? [];
                var tacticsCharged = tacticsAction?.AdditionalElements
                    .Where(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase))
                    .Select(x => new XElement(x))
                    .ToList() ?? [];
                var originalCharged = pw.Model.AdditionalElements
                    .Where(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase))
                    .Select(x => new XElement(x))
                    .ToList();

                pa.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals("charged", StringComparison.OrdinalIgnoreCase));
                if (!ChargedElementsEqual(currentCharged, tacticsCharged) ||
                    ChargedElementsEqual(originalCharged, currentCharged))
                {
                    foreach (var element in currentCharged)
                        pa.AdditionalElements.Add(new XElement(element));
                }
            }

            if (IsAreaRestrictActionType(currentActionType))
            {
                var currentVfx = draftSimpleValues.GetValueOrDefault("charged", "");
                SaveProtoActionNestedChildElement(pa, "charged", "chargedmodifyvfx", currentVfx);
            }

            var currentOnHitEffects = (pw.Draft.CopyOnHitEffects() ?? [])
                .Select(snapshot => new XElement(snapshot.Element))
                .ToList();
            var tacticsOnHitEffects = GetProtoActionOnHitEffectElements(tacticsAction ?? new ProtoAction());
            pa.AdditionalElements.RemoveAll(x => x.Name.LocalName.Equals("onhiteffect", StringComparison.OrdinalIgnoreCase));

            static XElement? FindOnHitEffectByType(IEnumerable<XElement> effects, XElement candidate)
            {
                var candidateType = ((string?)candidate.Attribute("type") ?? "").Trim();
                return string.IsNullOrWhiteSpace(candidateType)
                    ? null
                    : effects.FirstOrDefault(effect => string.Equals(
                        ((string?)effect.Attribute("type") ?? "").Trim(),
                        candidateType,
                        StringComparison.OrdinalIgnoreCase));
            }

            foreach (var effect in currentOnHitEffects)
            {
                var tacticsMatch = FindOnHitEffectByType(tacticsOnHitEffects, effect);
                // An unchanged inherited card belongs only to the shared tactics file. New proto
                // cards and edited same-type overrides remain serialized in this unit.
                if (tacticsMatch != null && XNode.DeepEquals(effect, tacticsMatch))
                    continue;

                pa.AdditionalElements.Add(new XElement(effect));
            }

            foreach (var kvp in draftSimpleValues)
            {
                if (IsAttackActionType(currentActionType) &&
                    kvp.Key.Equals("launchpoint", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }
                if (IsManagedStackControlFieldTag(currentActionType, kvp.Key))
                    continue;
                if (IsManagedChargedFieldTag(currentActionType, kvp.Key))
                    continue;
                if (IsAreaRestrictActionType(currentActionType) &&
                    kvp.Key.Equals("charged", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                var currentValue = kvp.Value;
                if (kvp.Key.Equals("modifytype", StringComparison.OrdinalIgnoreCase))
                    currentValue = ProtoConstants.GetModifyTypeValue(currentValue);
                if (kvp.Key.Equals("displaynameid", StringComparison.OrdinalIgnoreCase))
                {
                    var displayText = currentValue;
                    var originalStringId = draftCustomValues.GetValueOrDefault("displaynameid.stringid") ?? "";
                    currentValue = string.IsNullOrWhiteSpace(displayText)
                        ? ""
                        : BuildProtoActionDisplayNameStringId(_currentUnitName ?? "", pa.Name);
                    var previousGeneratedId = draftCustomValues.GetValueOrDefault("displaynameid.generated-id") ?? "";
                    if (!string.IsNullOrWhiteSpace(previousGeneratedId) &&
                        !previousGeneratedId.Equals(currentValue, StringComparison.OrdinalIgnoreCase))
                    {
                        _pendingUnitStringUpdates.Remove(previousGeneratedId);
                        _pendingUnitStringRemovals.Add(previousGeneratedId);
                    }
                    pw.CustomValues["displaynameid.generated-id"] = currentValue;
                    if (!string.IsNullOrWhiteSpace(currentValue))
                    {
                        _pendingUnitStringUpdates[currentValue] = displayText;
                        _pendingUnitStringRemovals.Remove(currentValue);
                    }
                    if (!string.IsNullOrWhiteSpace(originalStringId) &&
                        originalStringId.StartsWith("STR_ACTION_", StringComparison.OrdinalIgnoreCase) &&
                        !originalStringId.Equals(currentValue, StringComparison.OrdinalIgnoreCase))
                    {
                        _pendingUnitStringRemovals.Add(originalStringId);
                    }
                }
                var tacticsValue = tacticsAction != null
                    ? ProtoXmlHandler.GetProtoActionSimpleFieldValue(tacticsAction, kvp.Key)
                    : "";
                var originalProtoValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(pw.Model, kvp.Key);
                var protoValue = ResolveProtoOverrideValue(currentValue, tacticsValue, originalProtoValue);
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, kvp.Key, protoValue);
            }

            // Core Min Range uses the same <minrange> backing attribute as the generic
            // additional-field editor. Apply it after generic additional fields so a stale
            // duplicate control can never overwrite the visible core value.
            if (attackUsesCombatRanges && UsesCoreMinRange(currentActionType) && !pw.IsLinkedMaulAreaAction && !pw.IsLinkedAbductDropAction && pw.JumpAttackMinRangeTb != null)
            {
                var currentMinRange = pw.Draft.MinRange;
                var tacticsMinRange = tacticsAction != null
                    ? ProtoXmlHandler.GetProtoActionSimpleFieldValue(tacticsAction, "minrange")
                    : "";
                var originalMinRange = ProtoXmlHandler.GetProtoActionSimpleFieldValue(pw.Model, "minrange");
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(
                    pa,
                    "minrange",
                    ResolveProtoOverrideValue(currentMinRange, tacticsMinRange, originalMinRange));
            }

            if (IsAttackActionType(currentActionType) &&
                draftSimpleValues.TryGetValue("launchpoint", out var currentLaunchPoint))
            {
                var tacticsLaunchPoint = tacticsAction != null
                    ? GetProtoActionLaunchPointValue(tacticsAction)
                    : "";
                var originalLaunchPoint = GetProtoActionLaunchPointValue(pw.Model);
                var protoLaunchPoint = ResolveProtoOverrideValue(currentLaunchPoint, tacticsLaunchPoint, originalLaunchPoint);
                var projectileElement = GetProtoActionAdditionalElement(pa, "projectile");
                var usesActionLaunchPoint = UsesProtoActionLaunchPointAttribute(tacticsAction) ||
                                            UsesProtoActionLaunchPointAttribute(pw.Model);
                var usesProjectileLaunchPoint = UsesProjectileLaunchPointAttribute(tacticsAction) ||
                                                UsesProjectileLaunchPointAttribute(pw.Model);

                if (usesActionLaunchPoint)
                {
                    pa.SourceElement ??= new XElement("protoaction");
                    pa.SourceElement.SetAttributeValue("launchpoint", string.IsNullOrWhiteSpace(protoLaunchPoint) ? null : protoLaunchPoint);
                }
                else if (usesProjectileLaunchPoint)
                {
                    if (projectileElement == null)
                    {
                        var currentProjectile = draftSimpleValues.TryGetValue("projectile", out var draftProjectile)
                            ? draftProjectile
                            : ProtoXmlHandler.GetProtoActionSimpleFieldValue(effectiveAction, "projectile");
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, "projectile", currentProjectile);
                        projectileElement = GetProtoActionAdditionalElement(pa, "projectile");
                    }
                    projectileElement?.SetAttributeValue("launchpoint", string.IsNullOrWhiteSpace(protoLaunchPoint) ? null : protoLaunchPoint);
                }
                else
                {
                    ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, "launchpoint", protoLaunchPoint);
                }
            }

            if (IsAutoRangedModifyActionType(currentActionType) || IsAreaMutateActionType(currentActionType) || IsAutoRangedAttachActionType(currentActionType))
            {
                static List<string> GetUnitTypeEntries(ProtoAction action, string tag) => ProtoXmlHandler.GetProtoActionStructuredFieldEntries(action, tag)
                    .Select(entry => entry.Value?.Trim() ?? "")
                    .Where(value => !string.IsNullOrWhiteSpace(value))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();

                foreach (var tag in new[] { "modifyabstracttype", "forbidabstracttype", "modifyprotoid", "forbidunittype" })
                {
                    if (IsAreaMutateActionType(currentActionType) && tag.Equals("modifyprotoid", StringComparison.OrdinalIgnoreCase))
                    {
                        var currentValue = draftSimpleValues.GetValueOrDefault(tag, "");
                        var tacticsValue = tacticsAction != null
                            ? ProtoXmlHandler.GetProtoActionSimpleFieldValue(tacticsAction, tag)
                            : "";
                        var originalValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(pw.Model, tag);
                        var protoValue = ResolveProtoOverrideValue(currentValue, tacticsValue, originalValue);
                        ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, tag, protoValue);
                        continue;
                    }

                    var originalEntries = GetUnitTypeEntries(pw.Model, tag);
                    var tacticsEntries = tacticsAction != null
                        ? GetUnitTypeEntries(tacticsAction, tag)
                        : [];
                    var currentEntries = draftCustomValues.TryGetValue("autorangedmodify." + tag, out var storedEntries)
                        ? storedEntries.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                            .Distinct(StringComparer.OrdinalIgnoreCase)
                            .ToList()
                        : originalEntries.Count > 0
                            ? originalEntries
                            : tacticsEntries;
                    var shouldWriteEntries = !currentEntries.SequenceEqual(tacticsEntries, StringComparer.OrdinalIgnoreCase) ||
                                             originalEntries.SequenceEqual(currentEntries, StringComparer.OrdinalIgnoreCase);

                    pa.AdditionalElements.RemoveAll(element => element.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase));
                    if (shouldWriteEntries)
                    {
                        foreach (var value in currentEntries)
                            pa.AdditionalElements.Add(new XElement(tag, value));
                    }
                }
            }

            foreach (var flagTag in ProtoActionMetadataCatalog.GetKnownFlagTags())
            {
                var tacticsValue = tacticsAction != null
                    ? ProtoXmlHandler.GetProtoActionSimpleFieldValue(tacticsAction, flagTag)
                    : "";
                var tacticsFlagIsEnabled = IsProtoActionFlagEnabledValue(tacticsValue) ||
                    (tacticsAction != null &&
                     GetProtoActionAdditionalElement(tacticsAction, flagTag) != null &&
                     !tacticsValue.Trim().Equals("0", StringComparison.OrdinalIgnoreCase));
                var currentValue = flagTag.Equals("active", StringComparison.OrdinalIgnoreCase)
                    ? (draftCustomValues.GetValueOrDefault(ProtoActionActiveExplicitStateKey, "0").Equals("1", StringComparison.OrdinalIgnoreCase)
                        ? draftCustomValues.GetValueOrDefault(ProtoActionActiveValueStateKey, "0")
                        : "")
                    : IsInvertedDefaultProtoActionFlag(flagTag)
                        ? (draftSelectedFlagTags.Contains(GetInvertedDefaultProtoActionFlagTag(flagTag)) ? "0" : "")
                    : (IsMaintainActionType(currentActionType) && flagTag.Equals("pausable", StringComparison.OrdinalIgnoreCase))
                        ? draftCustomValues.GetValueOrDefault(MaintainPausableValueStateKey, "1")
                    : (IsMaintainActionType(currentActionType) && flagTag.Equals("showqueuewhilewaiting", StringComparison.OrdinalIgnoreCase))
                        ? draftCustomValues.GetValueOrDefault(MaintainShowQueueWhileWaitingValueStateKey, "1")
                    : ((IsBuckAttackActionType(currentActionType) || IsThrowActionType(currentActionType)) && flagTag.Equals("workonfrozenunits", StringComparison.OrdinalIgnoreCase))
                        ? (draftCustomValues.GetValueOrDefault(BuckAttackWorkOnFrozenUnitsExplicitStateKey, "0") == "1"
                            ? draftCustomValues.GetValueOrDefault(BuckAttackWorkOnFrozenUnitsStateKey, "0")
                            : "")
                    : draftSelectedFlagTags.Contains(flagTag)
                        ? "1"
                        : tacticsFlagIsEnabled
                            ? "0"
                            : "";
                var originalProtoValue = ProtoXmlHandler.GetProtoActionSimpleFieldValue(pw.Model, flagTag);
                var protoValue = flagTag.Equals("active", StringComparison.OrdinalIgnoreCase)
                    ? currentValue switch
                    {
                        "1" => "1",
                        "0" => "0",
                        _ => ResolveProtoOverrideValue(currentValue, tacticsValue, originalProtoValue)
                    }
                    : (IsMaintainActionType(currentActionType) && flagTag.Equals("pausable", StringComparison.OrdinalIgnoreCase))
                        ? (currentValue == "0" ? "0" : "1")
                    : (IsMaintainActionType(currentActionType) && flagTag.Equals("showqueuewhilewaiting", StringComparison.OrdinalIgnoreCase))
                        ? (currentValue == "0" ? "0" : "1")
                    : IsInvertedDefaultProtoActionFlag(flagTag)
                        ? (currentValue == "0" ? "0" : "")
                    : ((IsBuckAttackActionType(currentActionType) || IsThrowActionType(currentActionType)) && flagTag.Equals("workonfrozenunits", StringComparison.OrdinalIgnoreCase))
                        ? (string.IsNullOrWhiteSpace(currentValue)
                            ? ResolveProtoOverrideValue(currentValue, tacticsValue, originalProtoValue)
                            : (currentValue == "1" ? "1" : "0"))
                    : ResolveProtoOverrideValue(currentValue, tacticsValue, originalProtoValue);
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, flagTag, protoValue);
            }

            if (IsDrainResurrectionActionType(currentActionType))
            {
                var currentDamageFlags = draftCustomValues.TryGetValue("drainresurrection.damageflags", out var storedDamageFlags)
                    ? storedDamageFlags
                    : draftSimpleValues.TryGetValue("damageflags", out var draftDamageFlags)
                        ? draftDamageFlags
                        : ProtoXmlHandler.GetProtoActionSimpleFieldValue(pw.Model, "damageflags");
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(pa, "damageflags", currentDamageFlags);
            }

            foreach (var kvp in draftStructuredValues)
            {
                if (kvp.Key.Equals("scalebycontainedunittype", StringComparison.OrdinalIgnoreCase))
                {
                    var currentScaleEntries = kvp.Value;
                    var tacticsScaleEntries = tacticsAction != null
                        ? GetProtoActionStructuredFieldEntriesForEditor(tacticsAction, currentActionType, kvp.Key)
                        : [];
                    var originalScaleEntries = GetProtoActionStructuredFieldEntriesForEditor(pw.Model, currentActionType, kvp.Key);
                    var entriesToWrite = StructuredFieldEntriesEqual(currentScaleEntries, tacticsScaleEntries) &&
                                         !StructuredFieldEntriesEqual(originalScaleEntries, currentScaleEntries)
                        ? []
                        : currentScaleEntries;
                    SetScaleByContainedUnitTypeEntries(pa, entriesToWrite);
                    continue;
                }

                if (kvp.Key.Equals("donotautogatherunlessgatheringtypes", StringComparison.OrdinalIgnoreCase))
                {
                    var currentGatheringTypes = kvp.Value
                        .Select(x => x.Value?.Trim() ?? "")
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .ToList();
                    var tacticsGatheringTypes = tacticsAction != null
                        ? GetProtoActionNestedUnitTypeValues(tacticsAction, "donotautogatherunlessgatheringtypes")
                        : [];
                    var originalGatheringTypes = GetProtoActionNestedUnitTypeValues(pw.Model, "donotautogatherunlessgatheringtypes");
                    var protoGatheringTypes = currentGatheringTypes.SequenceEqual(tacticsGatheringTypes, StringComparer.OrdinalIgnoreCase) &&
                                              !currentGatheringTypes.SequenceEqual(originalGatheringTypes, StringComparer.OrdinalIgnoreCase)
                        ? []
                        : currentGatheringTypes;
                    SaveProtoActionNestedUnitTypeListElement(pa, "donotautogatherunlessgatheringtypes", protoGatheringTypes);
                    continue;
                }

                if (IsCombinedProtoActionModifyTypeTag(currentActionType, kvp.Key))
                {
                    SaveCombinedProtoActionModifyTypeEntries(pw, pa, tacticsAction, kvp.Value);
                    continue;
                }

                var currentEntries = kvp.Value;
                var tacticsEntries = tacticsAction != null
                    ? ProtoXmlHandler.GetProtoActionStructuredFieldEntries(tacticsAction, kvp.Key)
                    : [];
                var originalProtoEntries = ProtoXmlHandler.GetProtoActionStructuredFieldEntries(pw.Model, kvp.Key);
                var protoEntries = StructuredFieldEntriesEqual(currentEntries, tacticsEntries) &&
                                  !StructuredFieldEntriesEqual(originalProtoEntries, currentEntries)
                    ? []
                    : currentEntries;
                ProtoXmlHandler.SetProtoActionStructuredFieldEntries(pa, kvp.Key, protoEntries);
            }

            var currentDamageEntries = pw.Draft.Damages.ToList();

            var tacticsDamageEntries = tacticsAction?.Damages.ToList() ?? [];
            var originalProtoDamageEntries = pw.Model.Damages.ToList();
            foreach (var damageEntry in DamageEntriesEqual(currentDamageEntries, tacticsDamageEntries) &&
                                        !DamageEntriesEqual(originalProtoDamageEntries, currentDamageEntries)
                ? []
                : currentDamageEntries)
            {
                pa.Damages.Add(damageEntry);
            }

            var currentBonusEntries = pw.Draft.DamageBonuses.ToList();

            var tacticsBonusEntries = tacticsAction?.DamageBonuses.ToList() ?? [];
            var originalProtoBonusEntries = pw.Model.DamageBonuses.ToList();
            foreach (var bonusEntry in DamageBonusEntriesEqual(currentBonusEntries, tacticsBonusEntries) &&
                                       !DamageBonusEntriesEqual(originalProtoBonusEntries, currentBonusEntries)
                ? []
                : currentBonusEntries)
            {
                pa.DamageBonuses.Add(bonusEntry);
            }

            if (_protoActionHostAdapter.ShouldCollapseTacticsOnlyOverlay(pw.IsTacticsOnlyAction))
            {
                // The tactics action already supplies its name/type. A generated protoaction
                // contains only fields that differ from tactics, plus the name required to match it.
                pa.Type = "";
                pa.SourceElement = null;
                if (!HasSerializableProtoActionOverride(pa))
                    continue;
            }

            actionsList.Add(pa);
        }
        _protoActionHostAdapter.WriteActions(unit, actionsList);

        if (!string.IsNullOrWhiteSpace(selfDestructProtoActionName))
            ProtoXmlHandler.SetSimpleField(unit, "selfdestructprotoaction", selfDestructProtoActionName);
        else
            ProtoXmlHandler.RemoveSimpleField(unit, "selfdestructprotoaction");

        if (!string.IsNullOrWhiteSpace(birthProtoActionName))
            ProtoXmlHandler.SetSimpleField(unit, "birthprotoaction", birthProtoActionName);
        else
            ProtoXmlHandler.RemoveSimpleField(unit, "birthprotoaction");

        SyncStackProtoActionReference(unit, stackControlProtoActionName);

        ProtoUnitStatsXmlPreserver.PreserveUnmanagedContent(originalUnit, unit);
    }

    internal static void SyncStackProtoActionReference(XElement unit, string? actionName)
    {
        var normalizedActionName = actionName?.Trim() ?? "";
        if (!string.IsNullOrWhiteSpace(normalizedActionName))
            ProtoXmlHandler.SetSimpleField(unit, "stackprotoaction", normalizedActionName);
        else
            ProtoXmlHandler.RemoveSimpleField(unit, "stackprotoaction");
    }

    internal static void SaveUnitTypeXmlDocument(XDocument document, string path)
        => SaveAbilityXmlDocument(document, path);

    private static string GetRechargeModeDisplayValue(string? value)
        => string.Equals(value?.Trim(), "resourceDropoff", StringComparison.OrdinalIgnoreCase)
            ? "ResourceDropoff"
            : value?.Trim() ?? "";

    private static string[] GetRechargeModeDisplayOptions()
        => (new[] { "Time" })
            .Concat(ProtoConstants.KnownRechargeTypes.Select(GetRechargeModeDisplayValue))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

    private CheckBox CreateRechargeStartChargedCheckBox(string? init, Thickness? margin = null)
        => new()
        {
            Content = "Start charged",
            IsChecked = !string.Equals(init, "0", StringComparison.OrdinalIgnoreCase),
            IsEnabled = !_isReadOnly,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = margin ?? new Thickness(0)
        };

    private void RegisterStatsRechargeEditors(
        string prefix,
        ComboBox modeEditor,
        TextBox valueEditor,
        CheckBox startChargedEditor)
    {
        _statsRechargeModeEditors[prefix] = modeEditor;
        _statsRechargeValueEditors[prefix] = valueEditor;
        _statsRechargeStartChargedEditors[prefix] = startChargedEditor;

        if (!_abilityRechargeModeEditors.TryGetValue(prefix, out var abilityMode) ||
            !_abilityRechargeValueEditors.TryGetValue(prefix, out var abilityValue) ||
            !_abilityRechargeStartChargedEditors.TryGetValue(prefix, out var abilityStartCharged))
        {
            return;
        }

        _syncingSharedRechargeEditors = true;
        try
        {
            modeEditor.SelectedItem = GetRechargeModeDisplayValue(abilityMode.SelectedItem as string);
            valueEditor.Text = abilityValue.Text;
            startChargedEditor.IsChecked = abilityStartCharged.IsChecked;
        }
        finally
        {
            _syncingSharedRechargeEditors = false;
        }
    }

    private void RegisterAbilityRechargeEditors(
        string prefix,
        ComboBox modeEditor,
        TextBox valueEditor,
        CheckBox startChargedEditor)
    {
        _abilityRechargeModeEditors[prefix] = modeEditor;
        _abilityRechargeValueEditors[prefix] = valueEditor;
        _abilityRechargeStartChargedEditors[prefix] = startChargedEditor;

        if (!_statsRechargeModeEditors.TryGetValue(prefix, out var statsMode) ||
            !_statsRechargeValueEditors.TryGetValue(prefix, out var statsValue) ||
            !_statsRechargeStartChargedEditors.TryGetValue(prefix, out var statsStartCharged))
        {
            return;
        }

        _syncingSharedRechargeEditors = true;
        try
        {
            modeEditor.SelectedItem = GetRechargeModeDisplayValue(statsMode.SelectedItem as string);
            valueEditor.Text = statsValue.Text;
            startChargedEditor.IsChecked = statsStartCharged.IsChecked;
        }
        finally
        {
            _syncingSharedRechargeEditors = false;
        }
    }

    private void RestoreStatsRechargeFieldControls()
    {
        foreach (var prefix in new[] { "recharge", "auxrecharge" })
        {
            if (_statsRechargeModeEditors.TryGetValue(prefix, out var mode))
                _fieldControls[$"{prefix}.mode"] = mode;
            if (_statsRechargeValueEditors.TryGetValue(prefix, out var value))
                _fieldControls[$"{prefix}.value"] = value;
            if (_statsRechargeStartChargedEditors.TryGetValue(prefix, out var startCharged))
                _fieldControls[$"{prefix}.init"] = startCharged;
        }
    }

    private bool IsRechargeUsedByAnyAbility(string prefix)
        => prefix.Equals("auxrecharge", StringComparison.OrdinalIgnoreCase)
            ? _abilityDrafts.Values.Any(draft =>
                draft.GeneralFlags.Contains("auxchargetimeasrof") ||
                draft.GeneralFlags.Contains("bindtoauxchargeaction"))
            : _abilityDrafts.Values.Any(draft =>
                draft.GeneralFlags.Contains("chargetimeasrof") ||
                draft.GeneralFlags.Contains("bindtochargeaction"));

    private void RefreshStatsRechargeRemoveAvailability()
    {
        foreach (var pair in _statsRechargeRemoveButtons)
        {
            var isUsed = IsRechargeUsedByAnyAbility(pair.Key);
            pair.Value.IsEnabled = !_isReadOnly && !isUsed;
            ToolTip.SetTip(pair.Value, isUsed
                ? $"This {GetOtherSpecificAttributeLabel(pair.Key)} is used by an ability and cannot be removed."
                : null);
        }
    }

    private void SynchronizeSharedRechargeEditors(
        string prefix,
        ComboBox sourceMode,
        TextBox sourceValue,
        CheckBox sourceStartCharged)
    {
        if (_syncingSharedRechargeEditors)
            return;

        _syncingSharedRechargeEditors = true;
        try
        {
            var mode = GetRechargeModeDisplayValue(sourceMode.SelectedItem as string);
            var value = sourceValue.Text;
            var startCharged = sourceStartCharged.IsChecked;

            if (_statsRechargeModeEditors.TryGetValue(prefix, out var statsMode) && !ReferenceEquals(statsMode, sourceMode))
                statsMode.SelectedItem = mode;
            if (_statsRechargeValueEditors.TryGetValue(prefix, out var statsValue) && !ReferenceEquals(statsValue, sourceValue))
                statsValue.Text = value;
            if (_statsRechargeStartChargedEditors.TryGetValue(prefix, out var statsStart) && !ReferenceEquals(statsStart, sourceStartCharged))
                statsStart.IsChecked = startCharged;

            if (_abilityRechargeModeEditors.TryGetValue(prefix, out var abilityMode) && !ReferenceEquals(abilityMode, sourceMode))
                abilityMode.SelectedItem = mode;
            if (_abilityRechargeValueEditors.TryGetValue(prefix, out var abilityValue) && !ReferenceEquals(abilityValue, sourceValue))
                abilityValue.Text = value;
            if (_abilityRechargeStartChargedEditors.TryGetValue(prefix, out var abilityStart) && !ReferenceEquals(abilityStart, sourceStartCharged))
                abilityStart.IsChecked = startCharged;
        }
        finally
        {
            _syncingSharedRechargeEditors = false;
        }
    }

    private void MarkDirty()
    {
        if (_isPopulating || _suppressEditorChangeTracking) return;
        AttachProtoUnitStatsNumericBehaviors();
        RefreshProtoActionAnimationValidationVisuals();
        if (_isAbilityDefinitionEditorMode) _allowAbilityDefinitionEditorClose = false;
        _showStoredRawXml = false;
        _isDirty = true;
        if (!_isAbilityDefinitionEditorMode && _protoActionHostAdapter.Context.TracksProtoUnitDraft && !string.IsNullOrWhiteSpace(_currentUnitName))
            _dirtyUnitNames.Add(_currentUnitName);
        _fileLabel.Text = (_modFilePath ?? "Unsaved Mod") + " *";
        RefreshDocumentTabHeaders();
        ScheduleXmlPreviewRefresh();
    }

    private void CommitChipAdditionAndRefreshXmlPreview()
    {
        // AutoCompleteBox additions settle after SelectionChanged. Persist their
        // backing sets first so the preview always starts from the new chip state.
        if (!_isReadOnly && _modXmlRoot != null)
            ApplyCurrentEdits();

        UpdateXmlPreview(force: true);
    }

    private string? GetConfiguredUserFolderPath()
    {
        var config = ProtoEditorSettings.LoadSettings();
        if (!string.IsNullOrWhiteSpace(config.UserFolderPath))
        {
            return config.UserFolderPath;
        }

        var rootDirectory = _gameData.RootDirectory;
        if (Directory.Exists(rootDirectory))
        {
            return Directory.GetParent(rootDirectory)?.FullName;
        }

        return null;
    }

    private static string SanitizeModFolderName(string name)
    {
        var invalid = Path.GetInvalidFileNameChars();
        var cleaned = new string(name.Trim().Select(ch => invalid.Contains(ch) ? '_' : ch).ToArray());
        return cleaned.Trim();
    }

    private bool TryLoadModFile(string path, bool showErrors = true)
    {
        if (!Path.GetFileName(path).Equals("proto_mods.xml", StringComparison.OrdinalIgnoreCase))
        {
            if (showErrors)
            {
                _ = new Prompt(PromptType.Error, "Wrong Mod File", "The proto editor can only write to proto_mods.xml.").ShowDialog(this);
            }
            return false;
        }

        try
        {
            var (doc, root) = ProtoXmlHandler.ParseProtoXml(path);
            _modXmlDoc = doc;
            _modXmlRoot = root;
            _modFilePath = path;
            LoadCurrentModAssetCatalogs();
            _fileLabel.Text = path;
            _isDirty = false;
            ClearPendingUnitDrafts();
            InvalidateSuggestionCaches(includeTechNames: true);
            InvalidateModStringEntriesCache();
            RefreshProtoActionMetadata();

            var config = ProtoEditorSettings.LoadSettings();
            config.LastModFilePath = path;
            ProtoEditorSettings.SaveSettings(config);
            return true;
        }
        catch (Exception ex)
        {
            if (showErrors)
            {
                _ = new Prompt(PromptType.Error, "Error", $"Failed to open proto_mods.xml:\n{ex.Message}").ShowDialog(this);
            }
            return false;
        }
    }

    private async Task<bool> EnsureLocalModAsync(bool forceNew = false)
    {
        if (!forceNew && _modXmlRoot != null && _modFilePath != null)
        {
            return true;
        }

        var inputPrompt = new InputPromptWindow("Enter a name for your local mod:");
        await inputPrompt.ShowDialog(this);
        var modName = SanitizeModFolderName(inputPrompt.InputText ?? "");
        if (string.IsNullOrEmpty(modName))
        {
            return false;
        }

        var userBase = GetConfiguredUserFolderPath();
        if (string.IsNullOrWhiteSpace(userBase))
        {
            var pErr = new Prompt(PromptType.Error, "Settings Error", "User folder path is not configured. Set it in AoM Divine Data Editor Settings.");
            await pErr.ShowDialog(this);
            return false;
        }

        var modDir = Path.Combine(userBase, "mods", "local", modName, "game", "data", "gameplay");
        try
        {
            Directory.CreateDirectory(modDir);
            var dataDirectory = Directory.GetParent(modDir)?.FullName
                ?? throw new InvalidOperationException("The new mod data directory could not be resolved.");
            var gameDirectory = Directory.GetParent(dataDirectory)?.FullName
                ?? throw new InvalidOperationException("The new mod game directory could not be resolved.");
            Directory.CreateDirectory(Path.Combine(gameDirectory, "ui_myth", "resources"));
            Directory.CreateDirectory(Path.Combine(gameDirectory, "art"));
            Directory.CreateDirectory(Path.Combine(gameDirectory, "sound"));
            var xmlPath = Path.Combine(modDir, "proto_mods.xml");

            if (!File.Exists(xmlPath))
            {
                var (doc, root) = ProtoXmlHandler.CreateNewProtoFile(xmlPath);
                _modXmlDoc = doc;
                _modXmlRoot = root;
                _modFilePath = xmlPath;
                InvalidateSuggestionCaches(includeTechNames: true);
                InvalidateModStringEntriesCache();
                RefreshProtoActionMetadata();
            }
            else if (!TryLoadModFile(xmlPath))
            {
                return false;
            }

            _modFilePath = xmlPath;
            LoadCurrentModAssetCatalogs();
            _fileLabel.Text = xmlPath;
            _isDirty = false;
            EnsureCurrentModStringFileExists();

            var config = ProtoEditorSettings.LoadSettings();
            config.UserFolderPath = userBase;
            config.LastModFilePath = xmlPath;
            ProtoEditorSettings.SaveSettings(config);
            return true;
        }
        catch (Exception ex)
        {
            var pErr = new Prompt(PromptType.Error, "Error", $"Failed to create local mod:\n{ex.Message}");
            await pErr.ShowDialog(this);
            return false;
        }
    }

    private string? GetCurrentModStringsPath()
    {
        if (string.IsNullOrWhiteSpace(_modFilePath))
            return null;

        var gameplayDir = Path.GetDirectoryName(_modFilePath);
        if (string.IsNullOrWhiteSpace(gameplayDir))
            return null;

        var dataDir = Directory.GetParent(gameplayDir)?.FullName;
        if (string.IsNullOrWhiteSpace(dataDir))
            return null;

        return Path.Combine(dataDir, "strings", "English", "stringmods.txt");
    }

    private static string BuildStringIdForUnit(string unitName, string suffix)
    {
        var normalized = new string(unitName
            .Trim()
            .ToUpperInvariant()
            .Select(ch => char.IsLetterOrDigit(ch) ? ch : '_')
            .ToArray());

        while (normalized.Contains("__", StringComparison.Ordinal))
            normalized = normalized.Replace("__", "_", StringComparison.Ordinal);

        normalized = normalized.Trim('_');
        return $"STR_UNIT_{normalized}_{suffix}";
    }

    internal static string BuildProtoActionDisplayNameStringId(string unitName, string actionName)
    {
        static string Normalize(string value)
        {
            var normalized = new string(value
                .Trim()
                .ToUpperInvariant()
                .Select(character => char.IsLetterOrDigit(character) ? character : '_')
                .ToArray());
            while (normalized.Contains("__", StringComparison.Ordinal))
                normalized = normalized.Replace("__", "_", StringComparison.Ordinal);
            return normalized.Trim('_');
        }

        var normalizedUnitName = Normalize(unitName);
        var normalizedActionName = Normalize(actionName);
        return string.IsNullOrWhiteSpace(normalizedUnitName) || string.IsNullOrWhiteSpace(normalizedActionName)
            ? ""
            : $"STR_ACTION_{normalizedUnitName}_{normalizedActionName}";
    }

    internal static Dictionary<string, string> BuildRenamedUnitStringIds(
        string unitName,
        IReadOnlyDictionary<string, string> oldIds,
        IReadOnlyDictionary<string, string> fieldTexts)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        var displayText = fieldTexts.GetValueOrDefault("displaynameid") ?? "";

        foreach (var tag in StringBackedFieldTags)
        {
            if (!fieldTexts.TryGetValue(tag, out var text))
                continue;
            var oldId = oldIds.GetValueOrDefault(tag) ?? "";
            if (string.IsNullOrWhiteSpace(oldId) && string.IsNullOrWhiteSpace(text))
                continue;

            if (tag.Equals("editornameid", StringComparison.OrdinalIgnoreCase) &&
                text.Equals(displayText, StringComparison.Ordinal))
            {
                result[tag] = result.GetValueOrDefault("displaynameid") ??
                              BuildStringIdForUnit(unitName, GetStringSuffixForField("displaynameid"));
                continue;
            }

            result[tag] = BuildStringIdForUnit(unitName, GetStringSuffixForField(tag));
        }

        return result;
    }

    private void AssignGeneratedStringIds(string unitName)
    {
        _currentStringFieldIds["displaynameid"] = BuildStringIdForUnit(unitName, GetStringSuffixForField("displaynameid"));
        _currentStringFieldIds["editornameid"] = _currentStringFieldIds["displaynameid"];
        _currentStringFieldIds["rollovertextid"] = BuildStringIdForUnit(unitName, GetStringSuffixForField("rollovertextid"));
        _currentStringFieldIds["shortrollovertextid"] = BuildStringIdForUnit(unitName, GetStringSuffixForField("shortrollovertextid"));

        if (_modXmlRoot == null)
            return;

        var unit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, unitName);
        if (unit == null)
            return;

        foreach (var kvp in _currentStringFieldIds)
            ProtoXmlHandler.SetSimpleField(unit, kvp.Key, kvp.Value);
    }

    private async Task<string?> ResolveDisplayStringAsync(string? stringId)
    {
        if (string.IsNullOrWhiteSpace(stringId))
            return null;

        var modEntries = LoadCurrentModStringEntries();
        if (modEntries.TryGetValue(stringId, out var modValue))
            return modValue;

        return await _gameData.LookupStringKeyAsync(stringId);
    }

    private Task SaveTechnologyStringValuesAsync(
        IReadOnlyDictionary<string, string> updates,
        IReadOnlyCollection<string> removals)
    {
        if (updates.Count == 0 && removals.Count == 0)
            return Task.CompletedTask;

        var entries = LoadCurrentModStringEntries(requireReadable: true);
        foreach (var removal in removals)
            entries.Remove(removal);
        foreach (var update in updates)
            entries[update.Key] = update.Value;
        SaveCurrentModStringEntries(entries);
        return Task.CompletedTask;
    }

    private Dictionary<string, string> LoadCurrentModStringEntries(bool requireReadable = false)
    {
        var path = GetCurrentModStringsPath();
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        if (!requireReadable &&
            string.Equals(_cachedModStringEntriesPath, path, StringComparison.OrdinalIgnoreCase) &&
            _cachedModStringEntries != null)
        {
            return _cachedModStringEntries;
        }

        try
        {
            var parsed = StringTableParser.Parse(File.ReadAllText(path));
            _cachedModStringEntriesPath = path;
            _cachedModStringEntries = parsed;
            return parsed;
        }
        catch (Exception ex)
        {
            if (requireReadable)
                throw new InvalidOperationException($"The existing stringmods file could not be read safely: '{path}'. No string changes were written.", ex);
            return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        }
    }

    private static void AtomicWriteAllText(string path, string content)
    {
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);

        var tempPath = Path.Combine(directory ?? ".", $".{Path.GetFileName(path)}.{Guid.NewGuid():N}.tmp");
        try
        {
            File.WriteAllText(tempPath, content);
            File.Move(tempPath, path, overwrite: true);
        }
        finally
        {
            try
            {
                if (File.Exists(tempPath)) File.Delete(tempPath);
            }
            catch { }
        }
    }

    private void SaveCurrentModStringEntries(Dictionary<string, string> entries)
    {
        var path = GetCurrentModStringsPath();
        if (string.IsNullOrWhiteSpace(path))
            return;

        using var writer = new StringWriter();
        writer.WriteLine("Language = \"English\"");
        writer.WriteLine();

        foreach (var entry in entries.OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
        {
            var escaped = entry.Value.Replace("\"", "\\\"", StringComparison.Ordinal);
            writer.WriteLine($"ID = \"{entry.Key}\"   ;   Str = \"{escaped}\"");
        }

        AtomicWriteAllText(path, writer.ToString());
        _cachedModStringEntriesPath = path;
        _cachedModStringEntries = new Dictionary<string, string>(entries, StringComparer.OrdinalIgnoreCase);
    }

    private void EnsureCurrentModStringFileExists()
    {
        var path = GetCurrentModStringsPath();
        if (string.IsNullOrWhiteSpace(path))
            return;

        var dir = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(dir))
            Directory.CreateDirectory(dir);

        if (!File.Exists(path))
        {
            AtomicWriteAllText(path, "Language = \"English\"\n\n");
            InvalidateModStringEntriesCache();
        }
    }

    private void RemoveStringEntries(IEnumerable<string> ids)
    {
        var entries = LoadCurrentModStringEntries(requireReadable: true);
        var changed = false;

        foreach (var id in ids.Where(x => !string.IsNullOrWhiteSpace(x)))
            changed |= entries.Remove(id);

        if (changed)
            SaveCurrentModStringEntries(entries);
    }

    private HashSet<string> CollectUnitStringIdsForRemoval(string unitName, XElement? unit)
    {
        var ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        foreach (var tag in StringBackedFieldTags)
        {
            var unitId = unit != null ? ProtoXmlHandler.GetSimpleField(unit, tag) : null;
            if (!string.IsNullOrWhiteSpace(unitId))
                ids.Add(unitId);

            if (_currentStringFieldIds.TryGetValue(tag, out var currentId) && !string.IsNullOrWhiteSpace(currentId))
                ids.Add(currentId);

            ids.Add(BuildStringIdForUnit(unitName, GetStringSuffixForField(tag)));
        }

        return ids;
    }

    private void SaveCurrentUnitStringValues()
    {
        if (_modXmlRoot == null || string.IsNullOrWhiteSpace(_currentUnitName))
            return;

        var entries = LoadCurrentModStringEntries(requireReadable: true);
        foreach (var pendingId in _pendingUnitRenameRemovedStringIds)
            entries.Remove(pendingId);
        var displayId = _currentStringFieldIds.GetValueOrDefault("displaynameid");
        var displayText = _fieldControls.TryGetValue("displaynameid", out var displayCtrl) && displayCtrl is TextBox displayTb
            ? displayTb.Text?.Trim() ?? ""
            : "";

        foreach (var tag in StringBackedFieldTags)
        {
            if (!_fieldControls.TryGetValue(tag, out var ctrl) || ctrl is not TextBox tb)
                continue;

            var id = _currentStringFieldIds.GetValueOrDefault(tag);
            if (tag.Equals("editornameid", StringComparison.OrdinalIgnoreCase))
            {
                var editorText = tb.Text?.Trim() ?? "";
                if (string.Equals(editorText, displayText, StringComparison.Ordinal))
                {
                    id = displayId;
                    _currentStringFieldIds[tag] = displayId ?? "";
                    entries.Remove(BuildStringIdForUnit(_currentUnitName, GetStringSuffixForField(tag)));
                }
                else if (string.IsNullOrWhiteSpace(id) || string.Equals(id, displayId, StringComparison.OrdinalIgnoreCase))
                {
                    id = BuildStringIdForUnit(_currentUnitName, GetStringSuffixForField(tag));
                    _currentStringFieldIds[tag] = id;
                }
            }

            if (string.IsNullOrWhiteSpace(id))
                continue;

            entries[id] = tb.Text?.Trim() ?? "";
        }

        SaveCurrentModStringEntries(entries);
    }

    private void CaptureCurrentUnitStringDraft()
    {
        if (string.IsNullOrWhiteSpace(_currentUnitName))
            return;

        foreach (var pendingId in _pendingUnitRenameRemovedStringIds)
        {
            _pendingUnitStringRemovals.Add(pendingId);
            _pendingUnitStringUpdates.Remove(pendingId);
        }

        var displayId = _currentStringFieldIds.GetValueOrDefault("displaynameid");
        var displayText = _fieldControls.TryGetValue("displaynameid", out var displayCtrl) && displayCtrl is TextBox displayTb
            ? displayTb.Text?.Trim() ?? ""
            : "";
        foreach (var tag in StringBackedFieldTags)
        {
            if (!_fieldControls.TryGetValue(tag, out var control) || control is not TextBox editor)
                continue;

            var id = _currentStringFieldIds.GetValueOrDefault(tag);
            if (tag.Equals("editornameid", StringComparison.OrdinalIgnoreCase))
            {
                var editorText = editor.Text?.Trim() ?? "";
                if (string.Equals(editorText, displayText, StringComparison.Ordinal))
                {
                    id = displayId;
                    _currentStringFieldIds[tag] = displayId ?? "";
                    _pendingUnitStringRemovals.Add(BuildStringIdForUnit(_currentUnitName, GetStringSuffixForField(tag)));
                }
                else if (string.IsNullOrWhiteSpace(id) || string.Equals(id, displayId, StringComparison.OrdinalIgnoreCase))
                {
                    id = BuildStringIdForUnit(_currentUnitName, GetStringSuffixForField(tag));
                    _currentStringFieldIds[tag] = id;
                }
            }

            if (string.IsNullOrWhiteSpace(id))
                continue;
            _pendingUnitStringRemovals.Remove(id);
            _pendingUnitStringUpdates[id] = editor.Text?.Trim() ?? "";
        }

        if (_modXmlRoot != null)
        {
            var unit = ProtoXmlHandler.GetUnitElement(_modXmlRoot, _currentUnitName);
            if (unit != null)
            {
                foreach (var tag in StringBackedFieldTags)
                {
                    if (_fieldControls.ContainsKey(tag) &&
                        _currentStringFieldIds.TryGetValue(tag, out var id) &&
                        !string.IsNullOrWhiteSpace(id))
                    {
                        ProtoXmlHandler.SetSimpleField(unit, tag, id);
                    }
                    else
                    {
                        ProtoXmlHandler.RemoveSimpleField(unit, tag);
                    }
                }
            }
        }
    }

    private void SavePendingUnitStringDrafts()
    {
        if (_pendingUnitStringUpdates.Count == 0 && _pendingUnitStringRemovals.Count == 0)
            return;
        var entries = LoadCurrentModStringEntries(requireReadable: true);
        foreach (var id in _pendingUnitStringRemovals)
        {
            var isStillReferenced = _modXmlRoot?.Elements()
                .Where(element => element.Name.LocalName.Equals("unit", StringComparison.OrdinalIgnoreCase))
                .SelectMany(unit => unit.Descendants())
                .Any(element =>
                    (StringBackedFieldTags.Contains(element.Name.LocalName, StringComparer.OrdinalIgnoreCase) ||
                     element.Name.LocalName.Equals("displaynameid", StringComparison.OrdinalIgnoreCase)) &&
                    element.Value.Trim().Equals(id, StringComparison.OrdinalIgnoreCase)) == true;
            if (!isStillReferenced)
                entries.Remove(id);
        }
        foreach (var entry in _pendingUnitStringUpdates)
            entries[entry.Key] = entry.Value;
        SaveCurrentModStringEntries(entries);
    }

    private void TrackPendingUnitRename(string oldName, string newName)
    {
        if (string.IsNullOrWhiteSpace(oldName) || string.IsNullOrWhiteSpace(newName) ||
            oldName.Equals(newName, StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        var originalName = _pendingUnitRenames.FirstOrDefault(entry =>
            entry.Value.Equals(oldName, StringComparison.OrdinalIgnoreCase)).Key;
        if (!string.IsNullOrWhiteSpace(originalName))
        {
            _pendingUnitRenames[originalName] = newName;
            _pendingUnitRenames.Remove(oldName);
        }
        else
        {
            _pendingUnitRenames[oldName] = newName;
        }

        _dirtyUnitNames.Remove(oldName);
        _dirtyUnitNames.Add(newName);
        _unitAbilityDrafts.Remove(oldName);
        _unitAbilityDrafts[newName] = CloneAbilityDrafts(_abilityDrafts);
        if (_duplicatedUnitRechargeFallbacks.Remove(oldName, out var rechargeFallbacks))
            _duplicatedUnitRechargeFallbacks[newName] = rechargeFallbacks;
    }

    private void SavePendingUnitRenames()
    {
        if (_pendingUnitRenames.Count == 0)
            return;

        var abilitiesPath = GetCurrentModAbilitiesFilePath("abilities_mods.xml");
        if (!string.IsNullOrWhiteSpace(abilitiesPath) && File.Exists(abilitiesPath))
        {
            var document = LoadAbilityXmlDocumentForUpdate(abilitiesPath, "abilitiesmods");
            if (document.Root != null)
            {
                foreach (var rename in _pendingUnitRenames)
                {
                    var source = document.Root.Elements().FirstOrDefault(element =>
                        element.Name.LocalName.Equals(rename.Key, StringComparison.OrdinalIgnoreCase));
                    if (source == null)
                        continue;
                    document.Root.Elements().Where(element =>
                            !ReferenceEquals(element, source) &&
                            element.Name.LocalName.Equals(rename.Value, StringComparison.OrdinalIgnoreCase))
                        .Remove();
                    source.Name = rename.Value;
                }
                SaveAbilityXmlDocument(document, abilitiesPath);
            }
        }

        foreach (var rename in _pendingUnitRenames)
            AbilityBindingMetadataStore.RenameUnit(_modFilePath, rename.Key, rename.Value);
    }

    private void InitializeUnitStringValues(string unitName, string displayName, string longRollover, string shortRollover)
    {
        var entries = LoadCurrentModStringEntries(requireReadable: true);
        entries[BuildStringIdForUnit(unitName, GetStringSuffixForField("displaynameid"))] = displayName;
        entries[BuildStringIdForUnit(unitName, GetStringSuffixForField("rollovertextid"))] = longRollover;
        entries[BuildStringIdForUnit(unitName, GetStringSuffixForField("shortrollovertextid"))] = shortRollover;
        SaveCurrentModStringEntries(entries);
    }

    private async Task<bool> CheckStartLocalMod(bool allowReadOnlyPrompt = false)
    {
        if (!_isReadOnly) return true;
        if (_isPopulating || !allowReadOnlyPrompt) return false;

        var prompt = new Prompt(PromptType.Confirm, "Base Game Unit", "You are editing a base game unit which cannot be changed directly.\n\nWould you like to start a local mod to save these changes?");
        await prompt.ShowDialog(this);
        if (!prompt.Confirmed)
        {
            if (_currentUnitName != null)
            {
                Dispatcher.UIThread.Post(() => BuildEditorPanel(_currentUnitName));
            }
            return false;
        }

        if (_modXmlRoot == null)
        {
            if (!await EnsureLocalModAsync())
            {
                if (_currentUnitName != null)
                {
                    Dispatcher.UIThread.Post(() => BuildEditorPanel(_currentUnitName));
                }
                return false;
            }
        }

        if (_modXmlRoot != null && _currentUnitName != null)
        {
            if (_barXmlRoot != null && ProtoXmlHandler.UnitExists(_barXmlRoot, _currentUnitName))
            {
                var source = ProtoXmlHandler.GetUnitElement(_barXmlRoot, _currentUnitName);
                if (source != null && !ProtoXmlHandler.UnitExists(_modXmlRoot, _currentUnitName))
                {
                    ProtoXmlHandler.CloneUnit(_modXmlRoot, source, _currentUnitName);
                }
            }
            else if (!ProtoXmlHandler.UnitExists(_modXmlRoot, _currentUnitName))
            {
                ProtoXmlHandler.AddNewUnit(_modXmlRoot, _currentUnitName);
            }

            _isReadOnly = false;
            ApplyCurrentEdits();

            _unitTabs.SelectedIndex = 1;
            RefreshUnitList();
            BuildEditorPanel(_currentUnitName);
        }

        return true;
    }

    private async Task<bool> PromptUnsavedChangesAsync()
    {
        if (!_isDirty && !(_technologyView?.IsDirty ?? false)) return true;

        var prompt = new Prompt(PromptType.Confirm, "Unsaved Changes", "You have unsaved changes. Do you want to discard them and continue?");
        await prompt.ShowDialog(this);
        return prompt.Confirmed;
    }

    private string? GetLocalModsDirectory()
    {
        var userBase = GetConfiguredUserFolderPath();
        if (string.IsNullOrWhiteSpace(userBase))
            return null;

        return Path.Combine(userBase, "mods", "local");
    }

    private async void SwitchMod_Click(object? sender, RoutedEventArgs e)
    {
        var proceed = await PromptUnsavedChangesAsync();
        if (!proceed) return;

        var localModsDir = GetLocalModsDirectory();
        if (string.IsNullOrWhiteSpace(localModsDir) || !Directory.Exists(localModsDir))
        {
            var pErr = new Prompt(PromptType.Error, "Mods Folder Missing", "Could not find the local mods folder. Load the game root or set the user folder path first.");
            await pErr.ShowDialog(this);
            return;
        }

        var modFolders = Directory.GetDirectories(localModsDir)
            .Select(Path.GetFileName)
            .Where(x => !string.IsNullOrWhiteSpace(x))
            .Select(x => x!)
            .OrderBy(x => x, StringComparer.OrdinalIgnoreCase)
            .ToList();

        if (modFolders.Count == 0)
        {
            var pErr = new Prompt(PromptType.Error, "No Local Mods", "No local mod folders were found under mods\\local.");
            await pErr.ShowDialog(this);
            return;
        }

        int? preselect = null;
        if (!string.IsNullOrWhiteSpace(_modFilePath))
        {
            var gameplayDir = Path.GetDirectoryName(_modFilePath);
            var dataDir = !string.IsNullOrWhiteSpace(gameplayDir) ? Directory.GetParent(gameplayDir)?.FullName : null;
            var gameDir = !string.IsNullOrWhiteSpace(dataDir) ? Directory.GetParent(dataDir)?.FullName : null;
            var modDir = !string.IsNullOrWhiteSpace(gameDir) ? Directory.GetParent(gameDir)?.FullName : null;
            var currentModName = !string.IsNullOrWhiteSpace(modDir) ? Path.GetFileName(modDir) : null;
            if (!string.IsNullOrWhiteSpace(currentModName))
                preselect = modFolders.FindIndex(x => x.Equals(currentModName!, StringComparison.OrdinalIgnoreCase));
            if (preselect < 0) preselect = null;
        }

        var picker = new PickerWindow("Select Local Mod", modFolders, preselect);
        await picker.ShowDialog(this);
        if (!string.IsNullOrWhiteSpace(picker.PickedItem))
        {
            var path = Path.Combine(localModsDir, picker.PickedItem, "game", "data", "gameplay", "proto_mods.xml");
            if (TryLoadModFile(path))
            {
                ResetEntityBrowserToUnits();
                _unitTabs.SelectedIndex = 1;
                RefreshUnitList();
                ClearEditorPanels();
                _currentUnitName = null;
            }
        }
    }

    private async void CreateMod_Click(object? sender, RoutedEventArgs e)
    {
        var proceed = await PromptUnsavedChangesAsync();
        if (!proceed) return;

        _modXmlDoc = null;
        _modXmlRoot = null;
        _modFilePath = null;
        _isDirty = false;
        ClearPendingUnitDrafts();
        InvalidateSuggestionCaches(includeTechNames: true);
        InvalidateModStringEntriesCache();

        if (await EnsureLocalModAsync(forceNew: true))
        {
            ResetEntityBrowserToUnits();
            _unitTabs.SelectedIndex = 1;
            RefreshUnitList();
            ClearEditorPanels();
            _currentUnitName = null;
        }
    }


    private static readonly string[] AbilityGeneralFlags =
    [
        "alwaysdisabledingrid", "chargetimeasrof", "noautocast", "castonself", "actioncommand",
        "auxchargetimeasrof", "notcastable", "donotforcestop", "bindtochargeaction",
        "bindtoauxchargeaction", "enabledduringaction", "inactivewhenfullhp"
    ];

    private static readonly string[] AbilityGeneralValueTags = ["tech", "rof", "columnoverride"];

    private static readonly string[] AbilityPowerValueTags =
    [
        "icon", "displaynameid", "rolloverid", "abstractplacementtargettype", "placement", "unitaction",
        "rangeindicator", "cursortype", "activetime", "radius", "explicitlyrestrictedplacementtargettype",
        "replacerolloverid", "replaceicon"
    ];

    private static readonly string[] AbilityPowerFlags = ["allowduringnorush", "onlyfromstealth", "notblockable"];

    private static readonly HashSet<string> AbilityManagedPlacementAttributes = new(StringComparer.OrdinalIgnoreCase)
    {
        "enemy", "ally", "includeally", "allownature", "allyorenemynotself", "natureonly",
        "allowgroundtarget", "disallowwhenattackingdisabled", "disallowwatercast", "disallowlandcast",
        "allowdeadtarget", "disallowwatercastradius", "fullybuiltonly"
    };

    private static IEnumerable<XAttribute> GetUnknownPlacementAttributesFromSource(AbilityEditorDraft draft)
    {
        var placement = draft.PowerSource?.Elements()
            .FirstOrDefault(element => element.Name.LocalName.Equals("placement", StringComparison.OrdinalIgnoreCase));
        if (placement == null)
            yield break;

        foreach (var attribute in placement.Attributes())
        {
            if (!AbilityManagedPlacementAttributes.Contains(attribute.Name.LocalName))
                yield return new XAttribute(attribute);
        }
    }

    internal static void MergeUnknownPlacementAttributes(XElement? sourcePower, XElement targetPower)
    {
        var sourcePlacement = sourcePower?.Elements()
            .FirstOrDefault(element => element.Name.LocalName.Equals("placement", StringComparison.OrdinalIgnoreCase));
        var targetPlacement = targetPower.Elements()
            .FirstOrDefault(element => element.Name.LocalName.Equals("placement", StringComparison.OrdinalIgnoreCase));
        if (sourcePlacement == null || targetPlacement == null)
            return;

        foreach (var attribute in sourcePlacement.Attributes())
        {
            if (AbilityManagedPlacementAttributes.Contains(attribute.Name.LocalName))
                continue;
            if (targetPlacement.Attributes().Any(existing => existing.Name.LocalName.Equals(attribute.Name.LocalName, StringComparison.OrdinalIgnoreCase)))
                continue;
            targetPlacement.SetAttributeValue(attribute.Name, attribute.Value);
        }
    }

    private static string AbilityFieldLabel(string tag)
    {
        var known = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["alwaysdisabledingrid"] = "Always Disabled In Grid",
            ["chargetimeasrof"] = "Charge Time As ROF",
            ["noautocast"] = "No Autocast",
            ["castonself"] = "Cast On Self",
            ["actioncommand"] = "Action Command",
            ["auxchargetimeasrof"] = "Aux Charge Time As ROF",
            ["notcastable"] = "Not Castable",
            ["donotforcestop"] = "Do Not Force Stop",
            ["bindtochargeaction"] = "Bind To Charge Action",
            ["bindtoauxchargeaction"] = "Bind To Aux Charge Action",
            ["enabledduringaction"] = "Enabled During Action",
            ["inactivewhenfullhp"] = "Inactive When Full HP",
            ["tech"] = "Enabled by tech",
            ["rof"] = "ROF",
            ["columnoverride"] = "Force to column",
            ["displaynameid"] = "Display Name",
            ["rolloverid"] = "Rollover",
            ["abstractplacementtargettype"] = "Target Type",
            ["unitaction"] = "Unit Action",
            ["rangeindicator"] = "Range Indicator",
            ["cursortype"] = "Cursor Type",
            ["activetime"] = "Active Time",
            ["explicitlyrestrictedplacementtargettype"] = "Restricted Target Type",
            ["replacerolloverid"] = "Replace Rollover ID",
            ["replaceicon"] = "Replace Icon",
            ["allowduringnorush"] = "Allow During No Rush",
            ["onlyfromstealth"] = "Only From Stealth",
            ["notblockable"] = "Not Blockable"
        };
        return known.TryGetValue(tag, out var label) ? label : char.ToUpperInvariant(tag[0]) + tag[1..];
    }

    private static string GetAbilityElementName(XElement element)
    {
        var attrName = element.Attributes().FirstOrDefault(a => a.Name.LocalName.Equals("name", StringComparison.OrdinalIgnoreCase))?.Value?.Trim();
        if (!string.IsNullOrWhiteSpace(attrName))
            return attrName;
        var childName = element.Elements().FirstOrDefault(e => e.Name.LocalName.Equals("name", StringComparison.OrdinalIgnoreCase))?.Value?.Trim();
        if (!string.IsNullOrWhiteSpace(childName))
            return childName;
        return element.Nodes().OfType<XText>().Select(t => t.Value.Trim()).FirstOrDefault(v => !string.IsNullOrWhiteSpace(v)) ?? "";
    }

    private static void LoadAbilityChildren(AbilityEditorDraft draft, XElement? general, XElement? power)
    {
        if (general != null)
        {
            foreach (var child in general.Elements())
            {
                var tag = child.Name.LocalName.ToLowerInvariant();
                if (AbilityGeneralFlags.Contains(tag, StringComparer.OrdinalIgnoreCase))
                    draft.GeneralFlags.Add(tag);
                else if (AbilityGeneralValueTags.Contains(tag, StringComparer.OrdinalIgnoreCase))
                    draft.GeneralValues[tag] = child.Value;
            }
        }
        if (power != null)
        {
            var type = power.Attributes().FirstOrDefault(a => a.Name.LocalName.Equals("type", StringComparison.OrdinalIgnoreCase))?.Value?.Trim();
            if (!string.IsNullOrWhiteSpace(type))
                draft.Type = type;
            foreach (var child in power.Elements())
            {
                var tag = child.Name.LocalName.ToLowerInvariant();
                if (AbilityPowerFlags.Contains(tag, StringComparer.OrdinalIgnoreCase))
                    draft.PowerFlags.Add(tag);
                else if (tag.Equals("abstractplacementtargettype", StringComparison.OrdinalIgnoreCase))
                {
                    var value = child.Value.Trim();
                    if (!string.IsNullOrWhiteSpace(value)) draft.PlacementTargetTypes.Add(value);
                }
                else if (tag.Equals("explicitlyrestrictedplacementtargettype", StringComparison.OrdinalIgnoreCase))
                {
                    var value = child.Value.Trim();
                    if (!string.IsNullOrWhiteSpace(value)) draft.RestrictedPlacementTargetTypes.Add(value);
                }
                else if (tag.Equals("placement", StringComparison.OrdinalIgnoreCase))
                {
                    draft.PowerValues[tag] = child.Value;
                    foreach (var attr in child.Attributes())
                    {
                        draft.PlacementAttributes.Add(attr.Name.LocalName.ToLowerInvariant());
                        draft.PlacementAttributeValues[attr.Name.LocalName] = attr.Value;
                    }
                }
                else if (tag.Equals("rangeindicator", StringComparison.OrdinalIgnoreCase))
                {
                    draft.PowerValues[tag] = child.Value;
                    foreach (var attr in child.Attributes())
                        draft.RangeIndicatorAttributes[attr.Name.LocalName.ToLowerInvariant()] = attr.Value;
                }
                else if (AbilityPowerValueTags.Contains(tag, StringComparer.OrdinalIgnoreCase))
                    draft.PowerValues[tag] = child.Value;
            }
        }
    }

    private static List<XDocument> ExtractAbilityDocumentsFromBar(BarArchive barFile, string barPath)
    {
        var documents = new List<XDocument>();
        var entries = barFile.Entries;
        if (entries == null || !File.Exists(barPath)) return documents;

        var matching = entries.Where(entry =>
        {
            var normalized = entry.Name.Replace('\\', '/');
            var fileName = normalized.Split('/').LastOrDefault() ?? "";
            return normalized.Contains("abilities", StringComparison.OrdinalIgnoreCase) &&
                   fileName.EndsWith(".xmb", StringComparison.OrdinalIgnoreCase) &&
                   (fileName.Equals("abilities.xml.xmb", StringComparison.OrdinalIgnoreCase) ||
                    fileName.EndsWith(".abilities.xmb", StringComparison.OrdinalIgnoreCase));
        }).ToList();

        using var stream = File.OpenRead(barPath);
        foreach (var entry in matching)
        {
            try
            {
                var size = entry.IsCompressed ? entry.SizeUncompressed : entry.SizeInArchive;
                var decompressed = new byte[size];
                var readBytes = entry.ReadDataDecompressed(stream, decompressed);
                if (readBytes <= 0) continue;
                var xml = XmbReader.ToFormattedXml(decompressed.AsSpan(0, readBytes));
                if (!string.IsNullOrWhiteSpace(xml)) documents.Add(XDocument.Parse(xml, LoadOptions.PreserveWhitespace));
            }
            catch { }
        }
        return documents;
    }

    private string? GetCurrentModAbilitiesFilePath(string fileName)
    {
        var gameplayPath = GetCurrentModGameplayFilePath(fileName);
        if (string.IsNullOrWhiteSpace(gameplayPath)) return null;
        var gameplayDirectory = Path.GetDirectoryName(gameplayPath);
        return string.IsNullOrWhiteSpace(gameplayDirectory)
            ? null
            : Path.Combine(gameplayDirectory, "abilities", fileName);
    }

    private void RegisterAvailableAbilityName(string abilityName)
    {
        abilityName = abilityName?.Trim() ?? "";
        if (string.IsNullOrWhiteSpace(abilityName)) return;
        if (!_availableAbilityNames.Contains(abilityName, StringComparer.OrdinalIgnoreCase))
            _availableAbilityNames.Add(abilityName);
        _availableAbilityNames = _availableAbilityNames
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
            .ToList();
        if (_currentAbilityNameEditor != null)
            _currentAbilityNameEditor.ItemsSource = _availableAbilityNames.ToList();
    }

    private void LoadAbilitySources(string unitName)
    {
        _abilityDrafts.Clear();
        _abilityPowerCatalog.Clear();
        var allNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var unitAssociations = new List<XElement>();

        void AddAssociation(XElement ability)
        {
            var name = GetAbilityElementName(ability);
            if (string.IsNullOrWhiteSpace(name)) return;
            allNames.Add(name);
            var index = unitAssociations.FindIndex(x => GetAbilityElementName(x).Equals(name, StringComparison.OrdinalIgnoreCase));
            if (index >= 0) unitAssociations[index] = new XElement(ability);
            else unitAssociations.Add(new XElement(ability));
        }

        var gameplay = ResolveBaseGameplayDirectory();
        var abilitiesDirectory = string.IsNullOrWhiteSpace(gameplay) ? null : Path.Combine(gameplay, "abilities");
        if (!string.IsNullOrWhiteSpace(abilitiesDirectory) && Directory.Exists(abilitiesDirectory))
        {
            var abilitiesPath = Path.Combine(abilitiesDirectory, "abilities.xml");
            if (File.Exists(abilitiesPath))
            {
                try
                {
                    var doc = XDocument.Load(abilitiesPath, LoadOptions.PreserveWhitespace);
                    foreach (var ability in doc.Root?.Descendants().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)) ?? [])
                    {
                        var name = GetAbilityElementName(ability);
                        if (!string.IsNullOrWhiteSpace(name)) allNames.Add(name);
                    }
                    foreach (var unitNode in doc.Root?.Elements().Where(e => e.Name.LocalName.Equals(unitName, StringComparison.OrdinalIgnoreCase)) ?? [])
                    {
                        foreach (var ability in unitNode.Elements().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)))
                            AddAssociation(ability);
                    }
                }
                catch { }
            }

            foreach (var path in Directory.EnumerateFiles(abilitiesDirectory, "*.abilities", SearchOption.TopDirectoryOnly))
            {
                try
                {
                    var doc = XDocument.Load(path, LoadOptions.PreserveWhitespace);
                    foreach (var power in doc.Root?.Elements().Where(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase)) ?? [])
                    {
                        var name = GetAbilityElementName(power);
                        if (string.IsNullOrWhiteSpace(name)) continue;
                        allNames.Add(name);
                        _abilityPowerCatalog[name] = new XElement(power);
                    }
                }
                catch { }
            }
        }

        void MergeAbilityDocuments(IEnumerable<XDocument> documents)
        {
            foreach (var doc in documents)
            {
                if (doc.Root == null) continue;
                if (doc.Root.Name.LocalName.Equals("abilities", StringComparison.OrdinalIgnoreCase))
                {
                    foreach (var ability in doc.Root.Descendants().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)))
                    {
                        var name = GetAbilityElementName(ability);
                        if (!string.IsNullOrWhiteSpace(name)) allNames.Add(name);
                    }
                    foreach (var unitNode in doc.Root.Elements().Where(e => e.Name.LocalName.Equals(unitName, StringComparison.OrdinalIgnoreCase)))
                    {
                        foreach (var ability in unitNode.Elements().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)))
                            AddAssociation(ability);
                    }
                }
                else if (doc.Root.Name.LocalName.Equals("powers", StringComparison.OrdinalIgnoreCase))
                {
                    foreach (var power in doc.Root.Elements().Where(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase)))
                    {
                        var name = GetAbilityElementName(power);
                        if (string.IsNullOrWhiteSpace(name)) continue;
                        allNames.Add(name);
                        _abilityPowerCatalog[name] = new XElement(power);
                    }
                }
            }
        }

        var loadedBarPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        void LoadBarAbilities(BarArchive? barFile, string? barPath)
        {
            if (barFile == null || string.IsNullOrWhiteSpace(barPath) || !File.Exists(barPath)) return;
            var fullPath = Path.GetFullPath(barPath);
            if (!loadedBarPaths.Add(fullPath)) return;
            MergeAbilityDocuments(ExtractAbilityDocumentsFromBar(barFile, fullPath));
        }

        // Use the same Data.bar fallback chain as the working tactics/tech loaders.
        LoadBarAbilities(_protoDataBarFile, _protoDataBarPath);

        var resolvedDataBarPath = ResolveDataBarPath();
        if (!string.IsNullOrWhiteSpace(resolvedDataBarPath) && File.Exists(resolvedDataBarPath) &&
            !loadedBarPaths.Contains(Path.GetFullPath(resolvedDataBarPath)))
        {
            try
            {
                using var dataStream = File.OpenRead(resolvedDataBarPath);
                var dataBar = new BarArchive(dataStream);
                if (dataBar.Load(out _)) LoadBarAbilities(dataBar, resolvedDataBarPath);
            }
            catch { }
        }

        var abilitiesModsPath = GetCurrentModAbilitiesFilePath("abilities_mods.xml");
        if (!string.IsNullOrWhiteSpace(abilitiesModsPath) && File.Exists(abilitiesModsPath))
        {
            try
            {
                var doc = XDocument.Load(abilitiesModsPath, LoadOptions.PreserveWhitespace);
                foreach (var unitNode in doc.Root?.Elements().Where(e => e.Name.LocalName.Equals(unitName, StringComparison.OrdinalIgnoreCase)) ?? [])
                {
                    foreach (var ability in unitNode.Elements().Where(e => e.Name.LocalName.Equals("ability", StringComparison.OrdinalIgnoreCase)))
                        AddAssociation(ability);
                }
            }
            catch { }
        }

        var powersModsPath = GetCurrentModGameplayFilePath("powers_mods.xml");
        if (!string.IsNullOrWhiteSpace(powersModsPath) && File.Exists(powersModsPath))
        {
            try
            {
                var doc = XDocument.Load(powersModsPath, LoadOptions.PreserveWhitespace);
                foreach (var power in doc.Root?.Elements().Where(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase)) ?? [])
                {
                    var name = GetAbilityElementName(power);
                    if (string.IsNullOrWhiteSpace(name)) continue;
                    allNames.Add(name);
                    _abilityPowerCatalog[name] = new XElement(power);
                }
            }
            catch { }
        }

        foreach (var association in unitAssociations)
        {
            var name = GetAbilityElementName(association);
            if (string.IsNullOrWhiteSpace(name)) continue;
            _abilityPowerCatalog.TryGetValue(name, out var power);
            var draft = new AbilityEditorDraft
            {
                Name = name,
                GeneralSource = new XElement(association),
                PowerSource = power == null ? null : new XElement(power),
                SharedPowerReference = power != null
            };
            LoadAbilityChildren(draft, association, power);
            var bindingMetadata = AbilityBindingMetadataStore.Get(_modFilePath, unitName, name);
            if (bindingMetadata != null)
            {
                draft.BoundMainRechargeAction = bindingMetadata.MainAction?.Trim() ?? "";
                draft.BoundAuxRechargeAction = bindingMetadata.AuxAction?.Trim() ?? "";
                draft.BoundMainActionFlagManaged = bindingMetadata.MainOwnsChargeAction;
                draft.BoundAuxActionFlagManaged = bindingMetadata.AuxOwnsChargeAction;
            }
            _abilityDrafts[name] = draft;
        }

        if (_unitAbilityDrafts.TryGetValue(unitName, out var pendingDrafts))
        {
            _abilityDrafts.Clear();
            foreach (var entry in CloneAbilityDrafts(pendingDrafts))
            {
                _abilityDrafts[entry.Key] = entry.Value;
                allNames.Add(entry.Value.Name);
            }
        }

        _availableAbilityNames = allNames.OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
    }

    private static XElement ReplaceKnownAbilityChildren(XElement source, IEnumerable<string> knownTags, IEnumerable<XElement> replacements)
    {
        var clone = new XElement(source);
        var known = new HashSet<string>(knownTags, StringComparer.OrdinalIgnoreCase);
        clone.Elements().Where(e => known.Contains(e.Name.LocalName)).Remove();
        clone.Add(replacements);
        return clone;
    }

    internal static string BuildAbilityStringId(string abilityName, bool rollover)
    {
        var normalized = new string(abilityName.Trim().ToUpperInvariant()
            .Select(ch => char.IsLetterOrDigit(ch) ? ch : '_').ToArray());
        while (normalized.Contains("__", StringComparison.Ordinal))
            normalized = normalized.Replace("__", "_", StringComparison.Ordinal);
        normalized = normalized.Trim('_');
        return $"STR_ABILITY_{normalized}{(rollover ? "_LR" : "")}";
    }

    private string BuildUniqueAbilityStringId(string abilityName, bool rollover, IReadOnlyDictionary<string, string> stringEntries)
    {
        var baseId = BuildAbilityStringId(abilityName, rollover);
        var reserved = new HashSet<string>(stringEntries.Keys, StringComparer.OrdinalIgnoreCase);
        foreach (var power in _abilityPowerCatalog.Values)
        {
            var tag = rollover ? "rolloverid" : "displaynameid";
            var id = power.Elements().FirstOrDefault(e => e.Name.LocalName.Equals(tag, StringComparison.OrdinalIgnoreCase))?.Value?.Trim();
            if (!string.IsNullOrWhiteSpace(id)) reserved.Add(id);
        }
        if (!reserved.Contains(baseId)) return baseId;

        var stem = rollover && baseId.EndsWith("_LR", StringComparison.OrdinalIgnoreCase) ? baseId[..^3] : baseId;
        for (var suffix = 2; ; suffix++)
        {
            var candidate = $"{stem}_{suffix}{(rollover ? "_LR" : "")}";
            if (!reserved.Contains(candidate)) return candidate;
        }
    }

    internal static XDocument LoadAbilityXmlDocumentForUpdate(string path, string rootName)
    {
        if (!File.Exists(path))
            return new XDocument(new XElement(rootName));

        try
        {
            var document = XDocument.Load(path, LoadOptions.PreserveWhitespace);
            if (document.Root == null)
                throw new InvalidDataException("The XML document has no root element.");
            return document;
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException($"The existing XML file could not be read safely: '{path}'. No replacement file was created.", ex);
        }
    }

    internal static void SaveAbilityXmlDocument(XDocument document, string path, Func<string, string>? serializedXmlTransform = null)
    {
        foreach (var whitespace in document.DescendantNodes().OfType<XText>()
                     .Where(text => string.IsNullOrWhiteSpace(text.Value)).ToList())
        {
            whitespace.Remove();
        }

        document.Declaration = null;
        var directory = Path.GetDirectoryName(path);
        if (!string.IsNullOrWhiteSpace(directory))
            Directory.CreateDirectory(directory);
        var tempPath = Path.Combine(directory ?? ".", $".{Path.GetFileName(path)}.{Guid.NewGuid():N}.tmp");
        var settings = new System.Xml.XmlWriterSettings
        {
            Indent = true,
            IndentChars = "\t",
            NewLineChars = Environment.NewLine,
            NewLineHandling = System.Xml.NewLineHandling.Replace,
            OmitXmlDeclaration = true
        };
        try
        {
            using (var writer = System.Xml.XmlWriter.Create(tempPath, settings))
                document.Save(writer);
            if (serializedXmlTransform != null)
            {
                var serialized = File.ReadAllText(tempPath);
                File.WriteAllText(tempPath, serializedXmlTransform(serialized));
            }
            File.Move(tempPath, path, overwrite: true);
        }
        finally
        {
            try
            {
                if (File.Exists(tempPath)) File.Delete(tempPath);
            }
            catch { }
        }
    }

    private void SaveAbilityDrafts()
    {
        if (string.IsNullOrWhiteSpace(_modFilePath) || string.IsNullOrWhiteSpace(_currentUnitName)) return;

        var abilitiesPath = GetCurrentModAbilitiesFilePath("abilities_mods.xml");
        if (!string.IsNullOrWhiteSpace(abilitiesPath))
        {
            Directory.CreateDirectory(Path.GetDirectoryName(abilitiesPath)!);
            var doc = LoadAbilityXmlDocumentForUpdate(abilitiesPath, "abilitiesmods");
            if (doc.Root == null) doc.Add(new XElement("abilitiesmods"));
            var root = doc.Root!;
            root.Name = "abilitiesmods";
            var existingUnit = root.Elements().FirstOrDefault(e => e.Name.LocalName.Equals(_currentUnitName, StringComparison.OrdinalIgnoreCase));
            var replacementUnit = new XElement(_currentUnitName);
            foreach (var draft in _abilityDrafts.Values.Where(d => !string.IsNullOrWhiteSpace(d.Name)))
            {
                var source = draft.GeneralSource ?? new XElement("ability", new XText(draft.Name));
                var children = draft.GeneralValues.Where(kv => !string.IsNullOrWhiteSpace(kv.Value)).Select(kv => new XElement(kv.Key, kv.Value))
                    .Concat(draft.GeneralFlags.Select(flag => new XElement(flag, "1")));
                var result = ReplaceKnownAbilityChildren(source, AbilityGeneralFlags.Concat(AbilityGeneralValueTags), children);
                foreach (var text in result.Nodes().OfType<XText>().Where(t => !string.IsNullOrWhiteSpace(t.Value)).ToList()) text.Remove();
                result.AddFirst(new XText(draft.Name));
                replacementUnit.Add(result);
            }
            if (existingUnit != null)
            {
                if (replacementUnit.HasElements) existingUnit.ReplaceWith(replacementUnit);
                else existingUnit.Remove();
            }
            else if (replacementUnit.HasElements) root.Add(replacementUnit);
            SaveAbilityXmlDocument(doc, abilitiesPath);
        }

        var modified = _abilityDrafts.Values.Where(d => d.Modified && !d.SharedPowerReference && !string.IsNullOrWhiteSpace(d.Name))
            .GroupBy(d => d.Name, StringComparer.OrdinalIgnoreCase).Select(g => g.Last()).ToList();
        if (modified.Count > 0)
        {
            var powersPath = GetCurrentModGameplayFilePath("powers_mods.xml");
            if (!string.IsNullOrWhiteSpace(powersPath))
            {
                Directory.CreateDirectory(Path.GetDirectoryName(powersPath)!);
                var doc = LoadAbilityXmlDocumentForUpdate(powersPath, "powersmod");
                if (doc.Root == null) doc.Add(new XElement("powersmod"));
                var root = doc.Root!;
                root.Name = "powersmod";
                var stringEntries = LoadCurrentModStringEntries(requireReadable: true);
                var stringsChanged = false;
                foreach (var draft in modified)
                {
                    foreach (var tag in new[] { "displaynameid", "rolloverid" })
                    {
                        if (!draft.PowerDisplayTexts.TryGetValue(tag, out var text) || string.IsNullOrWhiteSpace(text))
                            continue;

                        var id = draft.PowerValues.GetValueOrDefault(tag, "").Trim();
                        var generatedId = false;
                        if (string.IsNullOrWhiteSpace(id))
                        {
                            id = BuildUniqueAbilityStringId(draft.Name, tag.Equals("rolloverid", StringComparison.OrdinalIgnoreCase), stringEntries);
                            draft.PowerValues[tag] = id;
                            generatedId = true;
                        }

                        if (generatedId || draft.ModifiedPowerDisplayTextTags.Contains(tag))
                        {
                            stringEntries[id] = text;
                            stringsChanged = true;
                        }
                    }

                    var source = draft.PowerSource ?? new XElement("power", new XAttribute("name", draft.Name));
                    var children = draft.PowerValues
                        .Where(kv => !string.IsNullOrWhiteSpace(kv.Value) &&
                                     !kv.Key.Equals("abstractplacementtargettype", StringComparison.OrdinalIgnoreCase) &&
                                     !kv.Key.Equals("explicitlyrestrictedplacementtargettype", StringComparison.OrdinalIgnoreCase) &&
                                     !kv.Key.Equals("placement", StringComparison.OrdinalIgnoreCase) &&
                                     !kv.Key.Equals("rangeindicator", StringComparison.OrdinalIgnoreCase))
                        .Select(kv => new XElement(kv.Key, kv.Value))
                        .Concat(draft.PlacementTargetTypes.Select(value => new XElement("abstractplacementtargettype", value)))
                        .Concat(draft.RestrictedPlacementTargetTypes.Select(value => new XElement("explicitlyrestrictedplacementtargettype", value)))
                        .Concat(draft.PowerFlags.Select(flag => new XElement(flag, "1")))
                        .ToList();
                    var placementValue = draft.PowerValues.GetValueOrDefault("placement", "").Trim();
                    if (!string.IsNullOrWhiteSpace(placementValue))
                    {
                        var placementElement = new XElement("placement", placementValue);
                        foreach (var attribute in GetUnknownPlacementAttributesFromSource(draft))
                            placementElement.SetAttributeValue(attribute.Name, attribute.Value);
                        foreach (var attr in draft.PlacementAttributes.OrderBy(x => x, StringComparer.OrdinalIgnoreCase))
                        {
                            var normalized = attr.ToLowerInvariant();
                            var originalName = draft.PlacementAttributeValues.Keys.FirstOrDefault(key => key.Equals(attr, StringComparison.OrdinalIgnoreCase));
                            var xmlName = normalized switch
                            {
                                "allyorenemynotself" => "allyOrEnemyNotSelf",
                                "natureonly" => "natureOnly",
                                "allowdeadtarget" => "allowDeadTarget",
                                "disallowwatercastradius" => "disallowWaterCastRadius",
                                "fullybuiltonly" => "fullyBuiltOnly",
                                _ => originalName ?? normalized
                            };
                            var value = draft.PlacementAttributeValues.TryGetValue(attr, out var preservedValue) ? preservedValue : "";
                            placementElement.SetAttributeValue(xmlName, value);
                        }
                        children.Add(placementElement);
                    }
                    var rangeIndicatorValue = draft.PowerValues.GetValueOrDefault("rangeindicator", "").Trim();
                    if (!string.IsNullOrWhiteSpace(rangeIndicatorValue))
                    {
                        var rangeIndicatorElement = new XElement("rangeindicator", rangeIndicatorValue);
                        foreach (var attr in draft.RangeIndicatorAttributes.OrderBy(x => x.Key, StringComparer.OrdinalIgnoreCase))
                            if (!string.IsNullOrWhiteSpace(attr.Value))
                                rangeIndicatorElement.SetAttributeValue(attr.Key, attr.Value);
                        children.Add(rangeIndicatorElement);
                    }
                    var replacement = ReplaceKnownAbilityChildren(source, AbilityPowerFlags.Concat(AbilityPowerValueTags), children);
                    replacement.SetAttributeValue("name", draft.Name);
                    replacement.SetAttributeValue("type", draft.Type);
                    replacement.Elements().Where(e => e.Name.LocalName.Equals("name", StringComparison.OrdinalIgnoreCase) || e.Name.LocalName.Equals("type", StringComparison.OrdinalIgnoreCase)).Remove();
                    var existing = root.Elements().FirstOrDefault(e => e.Name.LocalName.Equals("power", StringComparison.OrdinalIgnoreCase) && GetAbilityElementName(e).Equals(draft.Name, StringComparison.OrdinalIgnoreCase));
                    // Use the freshly loaded powers_mods.xml as the preservation source so
                    // unsupported placement attributes added manually after the UI opened survive.
                    MergeUnknownPlacementAttributes(existing, replacement);
                    if (existing != null) existing.ReplaceWith(replacement); else root.Add(replacement);
                    _abilityPowerCatalog[draft.Name] = new XElement(replacement);
                    RegisterAvailableAbilityName(draft.Name);
                }
                SaveAbilityXmlDocument(doc, powersPath);
                if (stringsChanged)
                    SaveCurrentModStringEntries(stringEntries);
            }
        }

        SaveCurrentAbilityBindingMetadata();

        foreach (var draft in _abilityDrafts.Values)
        {
            draft.Modified = false;
            draft.ModifiedPowerDisplayTextTags.Clear();
        }
    }

    private List<AbilityBindingMetadataRecord> BuildCurrentAbilityBindingMetadataRecords()
    {
        var records = new List<AbilityBindingMetadataRecord>();
        foreach (var draft in _abilityDrafts.Values.Where(draft => !string.IsNullOrWhiteSpace(draft.Name)))
        {
            var usesMain = draft.GeneralFlags.Contains("chargetimeasrof") || draft.GeneralFlags.Contains("bindtochargeaction");
            var usesAux = draft.GeneralFlags.Contains("auxchargetimeasrof") || draft.GeneralFlags.Contains("bindtoauxchargeaction");
            if (!usesMain && !usesAux)
                continue;
            records.Add(new AbilityBindingMetadataRecord
            {
                AbilityName = draft.Name,
                MainAction = usesMain ? draft.BoundMainRechargeAction : "",
                MainOwnsChargeAction = usesMain && draft.BoundMainActionFlagManaged,
                AuxAction = usesAux ? draft.BoundAuxRechargeAction : "",
                AuxOwnsChargeAction = usesAux && draft.BoundAuxActionFlagManaged
            });
        }
        return records;
    }

    private void SaveCurrentAbilityBindingMetadata()
    {
        if (string.IsNullOrWhiteSpace(_modFilePath) || string.IsNullOrWhiteSpace(_currentUnitName)) return;
        AbilityBindingMetadataStore.ReplaceUnit(_modFilePath, _currentUnitName, BuildCurrentAbilityBindingMetadataRecords());
    }

    private bool IsAbilityActionFlagProtected(string actionName, string flagTag, AbilityEditorDraft? ignoreDraft = null)
    {
        if (string.IsNullOrWhiteSpace(actionName)) return false;
        foreach (var draft in _abilityDrafts.Values)
        {
            if (ReferenceEquals(draft, ignoreDraft))
                continue;

            if (flagTag.Equals("chargeaction", StringComparison.OrdinalIgnoreCase) &&
                draft.BoundMainRechargeAction.Equals(actionName, StringComparison.OrdinalIgnoreCase) &&
                (draft.GeneralFlags.Contains("chargetimeasrof") || draft.GeneralFlags.Contains("bindtochargeaction")))
                return true;
            if (flagTag.Equals("auxchargeaction", StringComparison.OrdinalIgnoreCase) &&
                draft.BoundAuxRechargeAction.Equals(actionName, StringComparison.OrdinalIgnoreCase) &&
                (draft.GeneralFlags.Contains("auxchargetimeasrof") || draft.GeneralFlags.Contains("bindtoauxchargeaction")))
                return true;
        }
        return false;
    }

    private bool IsActionFlagProtectedByTactics(string actionName, string flagTag)
    {
        return TryGetCurrentUnitTacticsAction(actionName, out var tacticsAction) &&
               IsProtoActionFlagEnabledValue(GetProtoActionSimpleSourceValue(tacticsAction, flagTag));
    }

    private bool SetAbilityLinkedActionFlag(string actionName, string flagTag, bool enabled, AbilityEditorDraft? ignoreDraft = null, bool managedByAbility = false)
    {
        if (string.IsNullOrWhiteSpace(actionName)) return false;
        var state = _protoActionWidgets.FirstOrDefault(widget =>
            string.Equals(widget.NameAcb.Text?.Trim(), actionName.Trim(), StringComparison.OrdinalIgnoreCase));
        if (state == null) return false;

        if (enabled)
        {
            var inheritedFromTactics = IsActionFlagProtectedByTactics(actionName, flagTag);
            var alreadyInProto = IsProtoActionFlagEnabledValue(GetProtoActionSimpleSourceValue(state.Model, flagTag));
            state.SelectedFlagTags.Add(flagTag);
            if (!inheritedFromTactics && !alreadyInProto)
            {
                ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, flagTag, "1");
                RenderProtoActionFlags(state);
                return true;
            }
            RenderProtoActionFlags(state);
            return false;
        }

        if (managedByAbility && !IsAbilityActionFlagProtected(actionName, flagTag, ignoreDraft))
        {
            ProtoXmlHandler.SetProtoActionSimpleFieldValue(state.Model, flagTag, "");
            if (!IsActionFlagProtectedByTactics(actionName, flagTag))
                state.SelectedFlagTags.Remove(flagTag);
        }
        RenderProtoActionFlags(state);
        return false;
    }

    private void ReleaseAbilityActionBindings(AbilityEditorDraft draft)
    {
        var main = draft.BoundMainRechargeAction;
        var aux = draft.BoundAuxRechargeAction;
        var mainManaged = draft.BoundMainActionFlagManaged;
        var auxManaged = draft.BoundAuxActionFlagManaged;
        draft.BoundMainRechargeAction = "";
        draft.BoundAuxRechargeAction = "";
        draft.BoundMainActionFlagManaged = false;
        draft.BoundAuxActionFlagManaged = false;
        SetAbilityLinkedActionFlag(main, "chargeaction", false, draft, mainManaged);
        SetAbilityLinkedActionFlag(aux, "auxchargeaction", false, draft, auxManaged);
    }

