    private void DuplicateAbilityAssignmentsForUnit(string sourceUnitName, string newUnitName)
    {
        if (string.IsNullOrWhiteSpace(sourceUnitName) || string.IsNullOrWhiteSpace(newUnitName)) return;

        // BuildEditorPanel keeps the current unit's effective ability assignments in
        // _abilityDrafts (base abilities plus mod overrides). Copy those associations
        // to the duplicated unit; the shared <power> definitions themselves stay shared.
        _captureAbilityEditorCurrent?.Invoke();
        var assignments = _abilityDrafts.Values
            .Where(draft => !string.IsNullOrWhiteSpace(draft.Name))
            .Select(draft =>
            {
                var source = draft.GeneralSource ?? new XElement("ability", new XText(draft.Name));
                var children = draft.GeneralValues
                    .Where(kv => !string.IsNullOrWhiteSpace(kv.Value))
                    .Select(kv => new XElement(kv.Key, kv.Value))
                    .Concat(draft.GeneralFlags.Select(flag => new XElement(flag, "1")));
                var result = ReplaceKnownAbilityChildren(source, AbilityGeneralFlags.Concat(AbilityGeneralValueTags), children);
                foreach (var text in result.Nodes().OfType<XText>().Where(text => !string.IsNullOrWhiteSpace(text.Value)).ToList())
                    text.Remove();
                result.AddFirst(new XText(draft.Name));
                return result;
            })
            .ToList();

        if (assignments.Count == 0) return;

        var path = GetCurrentModAbilitiesFilePath("abilities_mods.xml");
        if (string.IsNullOrWhiteSpace(path)) return;
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        var doc = LoadAbilityXmlDocumentForUpdate(path, "abilitiesmods");

        if (doc.Root == null) doc.Add(new XElement("abilitiesmods"));
        var root = doc.Root!;
        root.Name = "abilitiesmods";
        foreach (var existing in root.Elements().Where(element => element.Name.LocalName.Equals(newUnitName, StringComparison.OrdinalIgnoreCase)).ToList())
            existing.Remove();

        var duplicateUnit = new XElement(newUnitName);
        duplicateUnit.Add(assignments);
        root.Add(duplicateUnit);
        SaveAbilityXmlDocument(doc, path);
        if (!string.IsNullOrWhiteSpace(_modFilePath))
        {
            AbilityBindingMetadataStore.ReplaceUnit(_modFilePath, sourceUnitName, BuildCurrentAbilityBindingMetadataRecords());
            AbilityBindingMetadataStore.CopyUnit(_modFilePath, sourceUnitName, newUnitName);
        }
    }

    private async void AddUnit_Click(object? sender, RoutedEventArgs e)
    {
        await AddUnitAsync(duplicateSelected: false);
    }

    private async Task AddUnitAsync(bool duplicateSelected)
    {
        if (_modXmlRoot == null && !await EnsureLocalModAsync())
        {
            return;
        }
        if (_modXmlRoot == null)
        {
            return;
        }

        var duplicate = duplicateSelected && !string.IsNullOrEmpty(_currentUnitName);
        if (!duplicateSelected && !string.IsNullOrEmpty(_currentUnitName))
        {
            var pChoice = new Prompt(PromptType.Confirm, "Add Unit", $"Do you want to DUPLICATE the selected unit '{_currentUnitName}'?\n(Click Confirm to duplicate, or Cancel to create a blank unit instead.)");
            await pChoice.ShowDialog(this);
            duplicate = pChoice.Confirmed;
        }

        var input = new InputPromptWindow(duplicate ? "Enter duplicate unit name:" : "Enter new unit name:", allowWhitespace: false);
        await input.ShowDialog(this);
        string? name = input.InputText?.Trim();

        if (!string.IsNullOrEmpty(name))
        {
            if (!InternalNamePolicy.IsValid(name))
            {
                await new Prompt(PromptType.Error, "Invalid Unit name",
                    "ProtoUnit names can contain only letters, digits, '_' and '-'.").ShowDialog(this);
                return;
            }
            var sourceDisplay = _fieldControls.TryGetValue("displaynameid", out var displayCtrl) && displayCtrl is TextBox displayTb
                ? displayTb.Text?.Trim() ?? ""
                : "";
            var sourceLong = _fieldControls.TryGetValue("rollovertextid", out var longCtrl) && longCtrl is TextBox longTb
                ? longTb.Text?.Trim() ?? ""
                : "";
            var sourceShort = _fieldControls.TryGetValue("shortrollovertextid", out var shortCtrl) && shortCtrl is TextBox shortTb
                ? shortTb.Text?.Trim() ?? ""
                : "";

            if (UnitNameExistsAnywhere(name))
            {
                var pErr = new Prompt(PromptType.Error, "Duplicate", $"Unit '{name}' already exists as a proto unit in the base game or this mod.");
                await pErr.ShowDialog(this);
                return;
            }

            if (duplicate && _currentUnitName != null)
            {
                // Clone the live editor state, not only the last-saved proto_mods.xml node.
                // Recharge/aux-recharge values live on the ProtoUnit and would otherwise be
                // missing when the source unit had unsaved editor changes.
                if (!_isReadOnly)
                    ApplyCurrentEdits();

                if (_isReadOnly && _barXmlRoot != null)
                {
                    var source = ProtoXmlHandler.GetUnitElement(_barXmlRoot, _currentUnitName);
                    if (source == null)
                    {
                        var pErr = new Prompt(PromptType.Error, "Missing Unit", $"Could not find base unit '{_currentUnitName}' in Data.bar.");
                        await pErr.ShowDialog(this);
                        return;
                    }
                    ProtoXmlHandler.CloneUnit(_modXmlRoot, source, name);
                }
                else
                {
                    var clone = ProtoXmlHandler.CloneUnit(_modXmlRoot, _currentUnitName, name);
                    if (clone == null)
                    {
                        var pErr = new Prompt(PromptType.Error, "Missing Unit", $"Could not find mod unit '{_currentUnitName}' in proto_mods.xml.");
                        await pErr.ShowDialog(this);
                        return;
                    }
                }

                AssignGeneratedStringIds(name);
                InitializeUnitStringValues(
                    name,
                    string.IsNullOrWhiteSpace(sourceDisplay) ? name : sourceDisplay,
                    sourceLong,
                    sourceShort);
                DuplicateAbilityAssignmentsForUnit(_currentUnitName, name);
                var duplicatedUnitForRecharge = ProtoXmlHandler.GetUnitElement(_modXmlRoot, name);
                if (duplicatedUnitForRecharge != null)
                {
                    var rechargeNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "rechargetime", "recharge", "rechargeincludetypes", "rechargeexcludetypes", "auxrechargetime", "auxrecharge", "auxrechargeincludetypes", "auxrechargeexcludetypes" };
                    _duplicatedUnitRechargeFallbacks[name] = duplicatedUnitForRecharge.Elements().Where(e => rechargeNames.Contains(e.Name.LocalName)).Select(e => new XElement(e)).ToList();
                }
            }
            else
            {
                var typeWindow = new NewUnitTypeWindow();
                await typeWindow.ShowDialog(this);
                if (typeWindow.SelectedType == null)
                    return;

                var selectedKind = typeWindow.SelectedType switch
                {
                    "Building" => NewCustomUnitKind.Building,
                    "Other" => NewCustomUnitKind.Other,
                    _ => NewCustomUnitKind.Unit
                };
                var newUnit = ProtoXmlHandler.AddNewUnit(_modXmlRoot, name);

                switch (selectedKind)
                {
                    case NewCustomUnitKind.Unit:
                        newUnit.Add(new XElement("unittype", "Unit"));
                        break;
                    case NewCustomUnitKind.Building:
                        newUnit.Add(new XElement("unittype", "Building"));
                        ProtoXmlHandler.SetSimpleField(newUnit, "buildpoints", "0");
                        break;
                    case NewCustomUnitKind.Other:
                        break;
                }

                ProtoXmlHandler.SetCostEntries(newUnit, ProtoConstants.KnownResourceTypes.Select(r => (r, "0")));
                ProtoXmlHandler.SetArmorEntries(newUnit, ProtoConstants.KnownArmorTypes.Select(a => (a, "0")));
                AssignGeneratedStringIds(name);
                InitializeUnitStringValues(name, name, "", "");
            }

            MarkDirty();
            InvalidateSuggestionCaches();
            RefreshUnitList();
            _unitTabs.SelectedIndex = 1;

            _unitList.SelectedItem = _filteredUnitNames.FirstOrDefault(item =>
                string.Equals(item.UnitName, name, StringComparison.OrdinalIgnoreCase));
            BuildEditorPanel(name);
        }
    }

    private async void DeleteUnit_Click(object? sender, RoutedEventArgs e)
    {
        await DeleteSelectedUnitAsync();
    }

    private async Task DeleteSelectedUnitAsync()
    {
        if (string.IsNullOrEmpty(_currentUnitName))
        {
            var pErr = new Prompt(PromptType.Error, "Select Unit", "Please select a unit to delete.");
            await pErr.ShowDialog(this);
            return;
        }

        if (_isReadOnly)
        {
            var pErr = new Prompt(PromptType.Error, "Original Unit", $"Unit '{_currentUnitName}' is a base game unit and cannot be deleted.");
            await pErr.ShowDialog(this);
            return;
        }

        var pConfirm = new Prompt(PromptType.Confirm, "Delete Unit", $"Are you sure you want to delete '{_currentUnitName}'?");
        await pConfirm.ShowDialog(this);
        if (pConfirm.Confirmed && _modXmlRoot != null)
        {
            var deletedUnitName = _currentUnitName;
            var unitToDelete = ProtoXmlHandler.GetUnitElement(_modXmlRoot, deletedUnitName);
            foreach (var stringId in CollectUnitStringIdsForRemoval(deletedUnitName, unitToDelete))
            {
                _pendingUnitStringUpdates.Remove(stringId);
                _pendingUnitStringRemovals.Add(stringId);
            }
            ProtoXmlHandler.DeleteUnit(_modXmlRoot, deletedUnitName);
            _dirtyUnitNames.Add(deletedUnitName);
            _unitAbilityDrafts[deletedUnitName] = new Dictionary<string, AbilityEditorDraft>(StringComparer.OrdinalIgnoreCase);
            _currentUnitName = null;
            RemoveDeletedDocumentTabs(EditorEntityKind.Units, deletedUnitName);
            MarkDirty();
            InvalidateSuggestionCaches();
            RefreshUnitList();
            ClearEditorPanels();
        }
    }

    protected override async void OnClosing(WindowClosingEventArgs e)
    {
        if (_allowCloseAfterDiscard)
        {
            base.OnClosing(e);
            return;
        }

        if (_isAbilityDefinitionEditorMode)
        {
            if (!_allowAbilityDefinitionEditorClose && _isDirty && !_abilityDefinitionEditorReadOnly)
            {
                e.Cancel = true;
                await RequestCloseAbilityDefinitionEditorAsync();
                return;
            }

            base.OnClosing(e);
            return;
        }

        if (_protoActionHostAdapter.Context.UsesStandaloneDocumentLifecycle)
        {
            if (_tacticsEditorSession?.IsCloseAllowed != true && HasUnsavedTacticsEditorChanges())
            {
                e.Cancel = true;
                await RequestCloseTacticsActionEditorAsync();
                return;
            }

            base.OnClosing(e);
            return;
        }

        e.Cancel = true;
        if (_activeEntityKind == EditorEntityKind.Technologies &&
            _technologyView != null &&
            !await _technologyView.CommitCurrentTechnologyAsync())
            return;

        if (_isDirty || (_technologyView?.IsDirty ?? false))
        {
            var proceed = await PromptUnsavedChangesAsync();
            if (proceed)
            {
                _allowCloseAfterDiscard = true;
                Close();
            }
        }
        else
        {
            _allowCloseAfterDiscard = true;
            Close();
        }
    }

